function Get-TpmReShadeEffectCatalog {
    $effects = @(
        [pscustomobject]@{ EffectId = 'SweetFX.LumaSharpen'; FriendlyName = 'LumaSharpen'; Category = 'SHARPNESS'; Repository = 'CeeJayDK/SweetFX'; PinnedCommit = '16d1a42247cb5baaf660120ee35c9a33bb94649c'; RelativeFiles = @('Shaders/SweetFX/LumaSharpen.fx'); SHA256 = @('7B358EBBDAA7BC4C44EBF6E9D41AFCB3F21EE3DDE5C5F85BF40201D5C6044680'); RequiredIncludes = @('ReShadeUI.fxh','ReShade.fxh'); RequiredTextures = @(); License = 'MIT'; Attribution = 'Christian Cann Schuldt Jensen (CeeJay.dk)'; AllowedHosts = @('raw.githubusercontent.com'); AllowedPathPrefix = '/CeeJayDK/SweetFX/16d1a42247cb5baaf660120ee35c9a33bb94649c/'; TechniqueName = 'LumaSharpen'; PerformanceClass = 'LOW'; ResolutionSensitivity = 'MEDIUM'; CompatibilityState = 'ADVISORY_UNMEASURED'; MeasuredEvidence = $false; FallbackBehavior = 'Original' }
        [pscustomobject]@{ EffectId = 'SweetFX.Vibrance'; FriendlyName = 'Vibrance'; Category = 'COLOR'; Repository = 'CeeJayDK/SweetFX'; PinnedCommit = '16d1a42247cb5baaf660120ee35c9a33bb94649c'; RelativeFiles = @('Shaders/SweetFX/Vibrance.fx'); SHA256 = @('B9189A28CA4A645A0E188F8396C81889D217E3C706E8900DFE6594D43E7C33EB'); RequiredIncludes = @('ReShadeUI.fxh','ReShade.fxh'); RequiredTextures = @(); License = 'MIT'; Attribution = 'Christian Cann Schuldt Jensen (CeeJay.dk)'; AllowedHosts = @('raw.githubusercontent.com'); AllowedPathPrefix = '/CeeJayDK/SweetFX/16d1a42247cb5baaf660120ee35c9a33bb94649c/'; TechniqueName = 'Vibrance'; PerformanceClass = 'LOW'; ResolutionSensitivity = 'LOW'; CompatibilityState = 'ADVISORY_UNMEASURED'; MeasuredEvidence = $false; FallbackBehavior = 'Original' }
        [pscustomobject]@{ EffectId = 'FXShaders.CRT_Lottes'; FriendlyName = 'CRT Lottes'; Category = 'ARCADE DISPLAY'; Repository = 'luluco250/FXShaders'; PinnedCommit = '76365e35c48e30170985ca371e67d8daf8eb9a98'; RelativeFiles = @('Shaders/CRT_Lottes.fx','Shaders/CRT_Lottes.fxh'); SHA256 = @('6B214F43C97650A34D9848211402B475627092E127258F02BB0C5919451C9B20','FE19870235B2C4C166BD367227366AAE115E9AC9EF60E84774A069D4CFC0B1E6'); RequiredIncludes = @('ReShade.fxh','CRT_Lottes.fxh'); RequiredTextures = @(); License = 'MIT; Unlicense/public domain dedication for Timothy Lottes implementation'; Attribution = 'Lucas Melo; Timothy Lottes'; AllowedHosts = @('raw.githubusercontent.com'); AllowedPathPrefix = '/luluco250/FXShaders/76365e35c48e30170985ca371e67d8daf8eb9a98/'; TechniqueName = 'CRT_Lottes'; PerformanceClass = 'HIGH'; ResolutionSensitivity = 'HIGH'; CompatibilityState = 'ADVISORY_UNMEASURED'; MeasuredEvidence = $false; FallbackBehavior = 'CleanSharp' }
    )
    foreach ($effect in $effects) {
        if ($effect.EffectId -eq 'SweetFX.LumaSharpen') { $effect | Add-Member -NotePropertyName CompatibleWith -NotePropertyValue @('SweetFX.Vibrance') -Force; $effect | Add-Member -NotePropertyName ConflictsWith -NotePropertyValue @('FXShaders.CRT_Lottes') -Force }
        elseif ($effect.EffectId -eq 'SweetFX.Vibrance') { $effect | Add-Member -NotePropertyName CompatibleWith -NotePropertyValue @('SweetFX.LumaSharpen') -Force; $effect | Add-Member -NotePropertyName ConflictsWith -NotePropertyValue @() -Force }
        else { $effect | Add-Member -NotePropertyName CompatibleWith -NotePropertyValue @() -Force; $effect | Add-Member -NotePropertyName ConflictsWith -NotePropertyValue @('SweetFX.LumaSharpen','SweetFX.Vibrance') -Force }
        $effect | Add-Member -NotePropertyName OrderConstraints -NotePropertyValue @() -Force
        if ($effect.EffectId -eq 'SweetFX.LumaSharpen') { $effect | Add-Member -NotePropertyName ByteLengths -NotePropertyValue @([int64]8688) -Force }
        elseif ($effect.EffectId -eq 'SweetFX.Vibrance') { $effect | Add-Member -NotePropertyName ByteLengths -NotePropertyValue @([int64]2217) -Force }
        else { $effect | Add-Member -NotePropertyName ByteLengths -NotePropertyValue @([int64]5114,[int64]21710) -Force }
    }
    return $effects
}

function Get-TpmReShadeProfile {
    param([string]$ProfileId)
    $profileMatches = @(Get-TpmReShadeProfiles | Where-Object { $_.ProfileId -eq $ProfileId })
    if ($profileMatches.Count -eq 0) { return $null }
    return $profileMatches[0]
}

function Test-TpmReShadePresetContent {
    param([Parameter(Mandatory)][string]$Content, [Parameter(Mandatory)]$ProfileDefinition)
    if ($Content -match '[^\x09\x0A\x0D\x20-\x7E]') { return $false }
    $techniqueLine = @($Content -split "`r?`n" | Where-Object { $_ -like 'Techniques=*' })[0]
    if ($null -eq $techniqueLine) { return $false }
    $actual = if ($techniqueLine.Length -gt 11) { @($techniqueLine.Substring(11) -split ',') } else { @() }
    $expected = @($ProfileDefinition.TechniqueOrder)
    if (($actual -join ',') -ne ($expected -join ',')) { return $false }
    foreach ($technique in $actual) { if ($technique -notin @('LumaSharpen','Vibrance','CRT_Lottes')) { return $false } }
    return $true
}

function New-TpmReShadePresetContent {
    param([object]$ProfileDefinition)
    if (-not $ProfileDefinition -or $ProfileDefinition.SchemaVersion -ne 2) { throw 'Invalid TPM ReShade profile.' }
    $stack = Resolve-TpmReShadeEffectStack -EffectIds @($ProfileDefinition.Effects)
    if (-not $stack.Valid -or (($stack.Effects | ForEach-Object EffectId) -join ',') -ne (@($ProfileDefinition.Effects) -join ',')) { throw 'Profile effect stack is not approved.' }
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('; TPM-managed approved ReShade profile: ' + $ProfileDefinition.ProfileId)

    [void]$lines.Add('; Generated by TeknoParrot Manager. Do not edit.')
    [void]$lines.Add('PresetName=' + $ProfileDefinition.FriendlyName)
    [void]$lines.Add('Techniques=' + (@($ProfileDefinition.TechniqueOrder) -join ','))
    foreach ($key in @($ProfileDefinition.Parameters.Keys | Sort-Object)) { [void]$lines.Add(('{0}={1}' -f $key, $ProfileDefinition.Parameters[$key])) }
    $content = ($lines -join "`r`n") + "`r`n"
    if (-not (Test-TpmReShadePresetContent -Content $content -ProfileDefinition $ProfileDefinition)) { throw 'Generated ReShade preset failed validation.' }
    return $content
}
function Get-TpmReShadePreviewInfo {
    param([Parameter(Mandatory)]$ProfileDefinition, [string]$PreviewRoot = '')
    $root = if ($PreviewRoot) { [IO.Path]::GetFullPath($PreviewRoot) } else { [IO.Path]::GetFullPath((Join-Path $PSScriptRoot 'PreviewAssets\ReShadePreviews')) }
    $relative = [string]$ProfileDefinition.PreviewAsset
    $expected = @{
        Original = 'TPM-preview-original.svg'; CleanSharp = 'TPM-preview-clean.svg'
        Vivid = 'TPM-preview-vivid.svg'; EnhancedArcade = 'TPM-preview-enhanced.svg'; ClassicCrt = 'TPM-preview-crt.svg'
    }
    $name = if ($expected.ContainsKey($ProfileDefinition.ProfileId)) { $expected[$ProfileDefinition.ProfileId] } else { $null }
    if (-not $name -or [IO.Path]::GetFileName($relative) -ne $name -or $relative -match '(^|[\\/])\.\.([\\/]|$)') { return [pscustomobject]@{ ProfileId=$ProfileDefinition.ProfileId; Available=$false; Path=$null; Provenance='TPM synthetic'; Reason='PREVIEW_BINDING_INVALID' } }
    $path = [IO.Path]::GetFullPath((Join-Path $root $name))
    if (-not $path.StartsWith($root.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase) -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { return [pscustomobject]@{ ProfileId=$ProfileDefinition.ProfileId; Available=$false; Path=$null; Provenance='TPM synthetic'; Reason='PREVIEW_MISSING' } }
    try { $text = [IO.File]::ReadAllText($path); if ($text -notmatch '^\s*<svg\b' -or $text -notmatch '</svg>\s*$') { throw 'invalid' }; return [pscustomobject]@{ ProfileId=$ProfileDefinition.ProfileId; Available=$true; Path=$path; Provenance='TPM synthetic'; Reason=$null } } catch { return [pscustomobject]@{ ProfileId=$ProfileDefinition.ProfileId; Available=$false; Path=$null; Provenance='TPM synthetic'; Reason='PREVIEW_INVALID' } }
}

function Get-TpmReShadeProfileGallery {
    param([string]$PreviewRoot = '')
    $reference = Get-TpmReShadePreviewReference -PreviewRoot $PreviewRoot
    return @(Get-TpmReShadeProfiles | ForEach-Object {
        [pscustomobject]@{ ProfileId=$_.ProfileId; FriendlyName=$_.FriendlyName; Description=$_.Description; PreviewAvailable=$reference.Available; PreviewPath=$null; PreviewReason=if($reference.Available){$null}else{$reference.Reason}; Provenance='TPM synthetic'; PerformanceClass=$_.PerformanceClass; ResolutionSensitivity=$_.ResolutionSensitivity }
    })
}
function Get-TpmReShadePerformanceBadge {
    param([string]$PerformanceClass = '')
    switch ($PerformanceClass.ToUpperInvariant()) {
        'LOW' { return 'Very Light' }
        'MEDIUM' { return 'Moderate' }
        'HIGH' { return 'Heavy' }
        default { return 'Performance unknown' }
    }
}

function Get-TpmReShadePreviewCacheKey {
    param([Parameter(Mandatory)][string]$SubjectId, [string[]]$ShaderSha256 = @(), [string]$IntensityId = 'Default', [string]$PresetVersion = '2', [string]$ReferenceVersion = '1', [string]$ReferenceSha256 = 'TPM-SYNTHETIC-REFERENCE-V1', [string]$RendererVersion = '1')
    $raw = (@($SubjectId,$IntensityId,$PresetVersion,$ReferenceVersion,$ReferenceSha256,$RendererVersion,(@($ShaderSha256) -join ',')) -join '|')
    $bytes = [Text.Encoding]::UTF8.GetBytes($raw)
    return ([BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash($bytes))) -replace '-', '').ToLowerInvariant()
}
function Compare-TpmReShadeProfiles {
    param([Parameter(Mandatory)][string]$LeftProfileId, [Parameter(Mandatory)][string]$RightProfileId, [string]$ReferenceIdentity = 'TPM-SYNTHETIC-ARCADE-V1')
    $left=Get-TpmReShadeProfile -ProfileId $LeftProfileId;$right=Get-TpmReShadeProfile -ProfileId $RightProfileId
    if(-not $left -or -not $right -or [string]::IsNullOrWhiteSpace($ReferenceIdentity)){return [pscustomobject]@{Valid=$false;Reason='INVALID_PREVIEW_SUBJECT'}}
    return [pscustomobject]@{Valid=$true;LeftProfileId=$left.ProfileId;RightProfileId=$right.ProfileId;ReferenceIdentity=$ReferenceIdentity;Deploys=$false;LeftEffects=@($left.Effects);RightEffects=@($right.Effects)}
}

function Get-TpmReShadeIntensityVariants {
    param([Parameter(Mandatory)]$ProfileDefinition)
    return @([pscustomobject]@{VariantId='Default';FriendlyName='Balanced';Supported=$true;SettingsVersion='1';Parameters=@{};ProfileId=$ProfileDefinition.ProfileId})
}

function Resolve-TpmReShadeIntensityVariant {
    param([Parameter(Mandatory)]$ProfileDefinition,[string]$VariantId='Default')
    $variant=@(Get-TpmReShadeIntensityVariants -ProfileDefinition $ProfileDefinition|Where-Object VariantId -eq $VariantId)[0]
    if(-not $variant){throw 'Unsupported ReShade intensity variant.'}
    return $variant
}

function Get-TpmReShadeStatePath {
    param([string]$StateRoot='')
    $root=if($StateRoot){[IO.Path]::GetFullPath($StateRoot)}else{[IO.Path]::GetFullPath((Join-Path $PSScriptRoot 'ReShade\TPM-State'))}
    $file=Join-Path $root 'profiles.json'
    return [pscustomobject]@{Root=$root;Path=$file}
}

function Read-TpmReShadeState {
    param([string]$StateRoot='')
    $paths=Get-TpmReShadeStatePath -StateRoot $StateRoot
    if(-not(Test-Path -LiteralPath $paths.Path -PathType Leaf)){return [pscustomobject]@{Profiles=[pscustomobject]@{};Favorites=@();History=[pscustomobject]@{}}}
    try{$state=Get-Content -LiteralPath $paths.Path -Raw|ConvertFrom-Json;if(-not $state.Profiles){$state|Add-Member Profiles ([pscustomobject]@{}) -Force};if(-not $state.Favorites){$state|Add-Member Favorites @() -Force};if(-not $state.History){$state|Add-Member History ([pscustomobject]@{}) -Force};return $state}catch{return [pscustomobject]@{Profiles=@{};Favorites=@();History=@{};Corrupt=$true}}
}

function Write-TpmReShadeState {
    param([Parameter(Mandatory)]$State,[string]$StateRoot='')
    $paths=Get-TpmReShadeStatePath -StateRoot $StateRoot;[IO.Directory]::CreateDirectory($paths.Root)|Out-Null
    $tmp=$paths.Path+'.tmp';$json=$State|ConvertTo-Json -Depth 12;[IO.File]::WriteAllText($tmp,$json,(New-Object Text.UTF8Encoding($false)));Move-Item -LiteralPath $tmp -Destination $paths.Path -Force
    return $true
}

function Set-TpmReShadeRememberedProfile {
    param([Parameter(Mandatory)][string]$GameId,[Parameter(Mandatory)]$ProfileDefinition,[string]$VariantId='Default',[string]$StateRoot='')
    $variant=Resolve-TpmReShadeIntensityVariant -ProfileDefinition $ProfileDefinition -VariantId $VariantId;$state=Read-TpmReShadeState -StateRoot $StateRoot
    if(-not $state.Profiles){$state|Add-Member Profiles ([pscustomobject]@{}) -Force}
    $entry=[pscustomobject]@{ProfileId=$ProfileDefinition.ProfileId;VariantId=$variant.VariantId;DefinitionVersion=[string]$ProfileDefinition.SchemaVersion;EffectIds=@($ProfileDefinition.Effects)}
    $state.Profiles|Add-Member -MemberType NoteProperty -Name $GameId -Value $entry -Force;Write-TpmReShadeState -State $state -StateRoot $StateRoot
}

function Get-TpmReShadeRememberedProfile {
    param([Parameter(Mandatory)][string]$GameId,[string]$StateRoot='')
    $state=Read-TpmReShadeState -StateRoot $StateRoot
    $props=@($state.Profiles.PSObject.Properties|Where-Object { $_.Name -eq $GameId });$entry=if($props.Count -gt 0){$props[0].Value}else{$null}
    if(-not $entry){return [pscustomobject]@{Found=$false}}
    $rememberedProfile=Get-TpmReShadeProfile -ProfileId $entry.ProfileId
    if(-not $rememberedProfile -or [string]$rememberedProfile.SchemaVersion -ne [string]$entry.DefinitionVersion -or (@($rememberedProfile.Effects)-join ',') -ne (@($entry.EffectIds)-join ',')){return [pscustomobject]@{Found=$true;Valid=$false;Reason='STALE_PROFILE_DEFINITION'}}
    try { $rememberedVariant=Resolve-TpmReShadeIntensityVariant -ProfileDefinition $rememberedProfile -VariantId $entry.VariantId } catch { return [pscustomobject]@{Found=$true;Valid=$false;Reason='UNSUPPORTED_VARIANT'} }
    return [pscustomobject]@{Found=$true;Valid=$true;Profile=$rememberedProfile;VariantId=$rememberedVariant.VariantId}
}

function Set-TpmReShadeFavorite {
    param([Parameter(Mandatory)][string]$ProfileId,[string]$VariantId='Default',[string]$StateRoot='')
    $favoriteProfile=Get-TpmReShadeProfile -ProfileId $ProfileId;if(-not $favoriteProfile){return $false};$variant=Resolve-TpmReShadeIntensityVariant -ProfileDefinition $favoriteProfile -VariantId $VariantId;$state=Read-TpmReShadeState -StateRoot $StateRoot
    $items=@($state.Favorites|Where-Object { $_.ProfileId -ne $ProfileId -or $_.VariantId -ne $variant.VariantId });$state.Favorites=@($items+[pscustomobject]@{ProfileId=$ProfileId;VariantId=$variant.VariantId});Write-TpmReShadeState -State $state -StateRoot $StateRoot
    return $true
}

function Remove-TpmReShadeFavorite {
    param([Parameter(Mandatory)][string]$ProfileId,[string]$VariantId='Default',[string]$StateRoot='')
    $state=Read-TpmReShadeState -StateRoot $StateRoot;$state.Favorites=@($state.Favorites|Where-Object { $_.ProfileId -ne $ProfileId -or $_.VariantId -ne $VariantId });Write-TpmReShadeState -State $state -StateRoot $StateRoot
}

function Get-TpmReShadeProfileEffectHashes {
    param([Parameter(Mandatory)]$ProfileDefinition)
    $catalog = @(Get-TpmReShadeEffectCatalog)
    $hashes = New-Object System.Collections.Generic.List[string]
    foreach ($effectId in @($ProfileDefinition.Effects)) {
        $effect = @($catalog | Where-Object EffectId -eq $effectId)[0]
        if (-not $effect) { throw "Effect is not approved: $effectId" }
        foreach ($hash in @($effect.SHA256)) { [void]$hashes.Add([string]$hash) }
    }
    return $hashes.ToArray()
}

function Add-TpmReShadeProfileHistory {
    param([Parameter(Mandatory)][string]$GameId,[Parameter(Mandatory)]$ProfileDefinition,[string]$VariantId='Default',[string]$StateRoot='', [int]$MaximumEntries=5)
    $variant=Resolve-TpmReShadeIntensityVariant -ProfileDefinition $ProfileDefinition -VariantId $VariantId;$state=Read-TpmReShadeState -StateRoot $StateRoot
    if(-not $state.History){$state|Add-Member History ([pscustomobject]@{}) -Force}
    $old=@();$props=@($state.History.PSObject.Properties|Where-Object { $_.Name -eq $GameId });if($props.Count -gt 0){$old=@($props[0].Value)}
    $hashes=@(Get-TpmReShadeProfileEffectHashes -ProfileDefinition $ProfileDefinition)
    $entry=[pscustomobject]@{ProfileId=$ProfileDefinition.ProfileId;VariantId=$variant.VariantId;DefinitionVersion=[string]$ProfileDefinition.SchemaVersion;EffectIds=@($ProfileDefinition.Effects);EffectSha256=@($hashes);Applied=$true;RecordedAt=(Get-Date).ToUniversalTime().ToString('o')}
    $state.History|Add-Member -MemberType NoteProperty -Name $GameId -Value (@($entry)+$old|Select-Object -First $MaximumEntries) -Force;Write-TpmReShadeState -State $state -StateRoot $StateRoot
}

function Get-TpmReShadeProfileHistory {
    param([Parameter(Mandatory)][string]$GameId,[string]$StateRoot='')
    $state=Read-TpmReShadeState -StateRoot $StateRoot;$props=@($state.History.PSObject.Properties|Where-Object { $_.Name -eq $GameId });if($props.Count -gt 0){return @($props[0].Value)};return @()
}

function Get-TpmReShadeRestoreCandidate {
    param([Parameter(Mandatory)][string]$GameId, [string]$StateRoot = '')
    $state = Read-TpmReShadeState -StateRoot $StateRoot
    if ($state.PSObject.Properties['Corrupt'] -and $state.Corrupt) { return [pscustomobject]@{ Found = $true; Valid = $false; Reason = 'CORRUPT_HISTORY' } }
    $history = @()
    $props = @($state.History.PSObject.Properties | Where-Object { $_.Name -eq $GameId })
    if ($props.Count -gt 0) { $history = @($props[0].Value) }
    if ($history.Count -eq 0) { return [pscustomobject]@{ Found = $false } }
    $invalidReason = 'CORRUPT_HISTORY'
    foreach ($entry in $history) {
        $complete = $true
        foreach ($propertyName in @('ProfileId','VariantId','DefinitionVersion','EffectIds','EffectSha256','Applied')) { if (-not $entry.PSObject.Properties[$propertyName]) { $complete = $false; break } }
        if (-not $complete -or [string]$entry.Applied -ne 'True') { continue }
        $candidateProfile = Get-TpmReShadeProfile -ProfileId $entry.ProfileId
        if (-not $candidateProfile -or [string]$candidateProfile.SchemaVersion -ne [string]$entry.DefinitionVersion -or (@($candidateProfile.Effects) -join ',') -ne (@($entry.EffectIds) -join ',')) { $invalidReason = 'STALE_PROFILE_DEFINITION'; continue }
        try { $candidateVariant = Resolve-TpmReShadeIntensityVariant -ProfileDefinition $candidateProfile -VariantId $entry.VariantId } catch { $invalidReason = 'UNSUPPORTED_VARIANT'; continue }
        try { $candidateHashes = @(Get-TpmReShadeProfileEffectHashes -ProfileDefinition $candidateProfile) } catch { $invalidReason = 'STALE_EFFECT_DEFINITION'; continue }
        if ((@($candidateHashes) -join ',') -ne (@($entry.EffectSha256) -join ',')) { $invalidReason = 'STALE_EFFECT_DEFINITION'; continue }
        return [pscustomobject]@{ Found = $true; Valid = $true; Profile = $candidateProfile; VariantId = $candidateVariant.VariantId; HistoryEntry = $entry }
    }
    return [pscustomobject]@{ Found = $true; Valid = $false; Reason = $invalidReason }
}

function Get-TpmReShadeChooserOptions {
    param([Parameter(Mandatory)][string]$GameId, [string]$StateRoot = '')
    $state = Read-TpmReShadeState -StateRoot $StateRoot
    $favoriteProfiles = @()
    if (-not ($state.PSObject.Properties['Corrupt'] -and $state.Corrupt)) {
        foreach ($favorite in @($state.Favorites)) {
            $favoriteProfile = Get-TpmReShadeProfile -ProfileId $favorite.ProfileId
            if ($favoriteProfile) {
                try { $favoriteVariant = Resolve-TpmReShadeIntensityVariant -ProfileDefinition $favoriteProfile -VariantId $favorite.VariantId; $favoriteProfiles += [pscustomobject]@{ Profile = $favoriteProfile; VariantId = $favoriteVariant.VariantId } } catch {}
            }
        }
    }
    return [pscustomobject]@{
        Remembered = Get-TpmReShadeRememberedProfile -GameId $GameId -StateRoot $StateRoot
        Restore = Get-TpmReShadeRestoreCandidate -GameId $GameId -StateRoot $StateRoot
        Favorites = $favoriteProfiles
    }
}

function Restore-TpmReShadeProfile {
    param(
        [Parameter(Mandatory)]$HistoryEntry,
        [Parameter(Mandatory)][string]$CacheRoot,
        [Parameter(Mandatory)][string]$OwnershipRoot,
        [Parameter(Mandatory)][string]$GamePath,
        [Parameter(Mandatory)][System.Xml.XmlDocument]$Doc,
        [Parameter(Mandatory)][string]$SourceDll,
        [string]$SourceDll32 = '',
        [string]$GameId = '',
        [string]$StateRoot = '',
        [ValidateSet('None','BeforeCommit')][string]$FaultStage = 'None'
    )
    try {
        foreach ($propertyName in @('ProfileId','VariantId','DefinitionVersion','EffectIds','EffectSha256','Applied')) {
            if (-not $HistoryEntry.PSObject.Properties[$propertyName]) { return [pscustomobject]@{ Succeeded = $false; Reason = 'CORRUPT_HISTORY' } }
        }
        if ([string]$HistoryEntry.Applied -ne 'True' -or [string]::IsNullOrWhiteSpace([string]$HistoryEntry.ProfileId) -or [string]::IsNullOrWhiteSpace([string]$HistoryEntry.DefinitionVersion)) {
            return [pscustomobject]@{ Succeeded = $false; Reason = 'CORRUPT_HISTORY' }
        }
        $restoreProfile = Get-TpmReShadeProfile -ProfileId $HistoryEntry.ProfileId
        if (-not $restoreProfile -or [string]$restoreProfile.SchemaVersion -ne [string]$HistoryEntry.DefinitionVersion -or (@($restoreProfile.Effects) -join ',') -ne (@($HistoryEntry.EffectIds) -join ',')) {
            return [pscustomobject]@{ Succeeded = $false; Reason = 'STALE_PROFILE_DEFINITION' }
        }
        try { $variant = Resolve-TpmReShadeIntensityVariant -ProfileDefinition $restoreProfile -VariantId $HistoryEntry.VariantId } catch { return [pscustomobject]@{ Succeeded = $false; Reason = 'UNSUPPORTED_VARIANT' } }
        try { $currentHashes = @(Get-TpmReShadeProfileEffectHashes -ProfileDefinition $restoreProfile) } catch { return [pscustomobject]@{ Succeeded = $false; Reason = 'STALE_EFFECT_DEFINITION' } }
        if ((@($currentHashes) -join ',') -ne (@($HistoryEntry.EffectSha256) -join ',')) { return [pscustomobject]@{ Succeeded = $false; Reason = 'STALE_EFFECT_DEFINITION' } }
        $ownershipPath = if ([System.IO.Path]::GetExtension($OwnershipRoot) -ieq '.json') { $OwnershipRoot } else { Join-Path $OwnershipRoot 'profile.json' }
        $deployment = Install-TpmReShadeProfileDeployment -ProfileDefinition $restoreProfile -VariantId $variant.VariantId -GamePath $GamePath -Doc $Doc -SourceDll $SourceDll -SourceDll32 $SourceDll32 -CacheRoot $CacheRoot -OwnershipPath $ownershipPath -CanonicalPreset -FaultStage $FaultStage
        if (-not $deployment.Succeeded) {
            $rollbackVerified = if ($deployment.PSObject.Properties['RollbackVerified']) { $deployment.RollbackVerified } else { $null }
            return [pscustomobject]@{ Succeeded = $false; State = $deployment.State; Reason = $deployment.Reason; Error = $deployment.Error; RollbackVerified = $rollbackVerified }
        }
        if ($GameId) {
            try { Add-TpmReShadeProfileHistory -GameId $GameId -ProfileDefinition $restoreProfile -VariantId $variant.VariantId -StateRoot $StateRoot | Out-Null }
            catch { return [pscustomobject]@{ Succeeded = $false; State = 'HISTORY_NOT_COMMITTED'; Reason = 'HISTORY_WRITE_FAILED'; Error = $_.Exception.Message; DeploymentSucceeded = $true } }
        }
        return [pscustomobject]@{ Succeeded = $true; State = 'RESTORED'; ProfileId = $restoreProfile.ProfileId; VariantId = $variant.VariantId; TargetDir = $deployment.TargetDir; DllName = $deployment.DllName; PresetApplied = $deployment.PresetApplied; HistoryRecorded = [bool]$GameId }
    } catch {
        return [pscustomobject]@{ Succeeded = $false; State = 'RESTORE_FAILED'; Reason = 'RESTORE_FAILED'; Error = $_.Exception.Message }
    }
}


function Get-TpmReShadePreviewReference {
    param([string]$PreviewRoot = '')
    return [pscustomobject]@{
        Available = $true
        Path = $null
        Version = '1'
        Hash = '722f9d7c89449d90d7def1a42e4108e443401dd6460ae3316b9e8d955e5c34f6'
        Identity = 'TPM-SYNTHETIC-ARCADE-V1'
    }
}

function New-TpmReShadePreviewBitmap {
    param([Parameter(Mandatory)]$ProfileDefinition, [ValidateSet('Before','After','Split','Slider')][string]$Mode = 'Split', [int]$Width = 960, [int]$Height = 540, [ValidateRange(0,100)][int]$SliderPosition = 50)
    Add-Type -AssemblyName System.Drawing -ErrorAction Stop
    $canvasWidth=[int]$Width;$canvasHeight=[int]$Height
    $bitmap = New-Object Drawing.Bitmap($canvasWidth,$canvasHeight)
    $graphics = [Drawing.Graphics]::FromImage($bitmap)
    try {
        $graphics.Clear([Drawing.Color]::FromArgb(16,24,32))
        $font = New-Object Drawing.Font('Consolas',18)
        $small = New-Object Drawing.Font('Consolas',12)
        $brush = New-Object Drawing.SolidBrush([Drawing.Color]::FromArgb(38,56,69))
        $graphics.FillRectangle($brush,40,40,$canvasWidth-80,$canvasHeight-80)
        $pen = New-Object Drawing.Pen([Drawing.Color]::White,3)
        $graphics.DrawRectangle($pen,40,40,$canvasWidth-80,$canvasHeight-80)
        $colors = @([Drawing.Color]::FromArgb(210,70,70),[Drawing.Color]::FromArgb(55,165,210),[Drawing.Color]::FromArgb(242,193,78))
        for ($i=0; $i -lt 3; $i++) { $b=New-Object Drawing.SolidBrush($colors[$i]);$graphics.FillRectangle($b,80+($i*270),90,250,150);$b.Dispose() }
        $green=New-Object Drawing.Pen([Drawing.Color]::FromArgb(98,195,112),28);$graphics.DrawLine($green,80,310,$canvasWidth-80,310);$green.Dispose()
        $white=New-Object Drawing.Pen([Drawing.Color]::White,2);$graphics.DrawLine($white,100,400,$canvasWidth-100,400);$white.Dispose()
        $textBrush=New-Object Drawing.SolidBrush([Drawing.Color]::White);$graphics.DrawString('TPM SYNTHETIC ARCADE TEST SCENE',$font,$textBrush,100,440);$textBrush.Dispose()
        $drawAfter = {
            if ($ProfileDefinition.Effects -contains 'SweetFX.LumaSharpen') {
                $sharp=New-Object Drawing.Pen([Drawing.Color]::White,1)
                for ($x=80; $x -lt ($canvasWidth-80); $x+=18) { $graphics.DrawLine($sharp,$x,250,$x+8,260) }
                $sharp.Dispose()
            }
            if ($ProfileDefinition.Effects -contains 'SweetFX.Vibrance') {
                $vivid=New-Object Drawing.SolidBrush([Drawing.Color]::FromArgb(45,80,255,40))
                $graphics.FillRectangle($vivid,80,90,($canvasWidth-160),150);$vivid.Dispose()
            }
            if ($ProfileDefinition.Effects -contains 'FXShaders.CRT_Lottes') {
                $scan=New-Object Drawing.Pen([Drawing.Color]::FromArgb(75,0,0,0),2)
                for ($y=90; $y -lt 400; $y+=6) { $graphics.DrawLine($scan,80,$y,$canvasWidth-80,$y) }
                $scan.Dispose()
            }
        }
        if ($Mode -eq 'After') { & $drawAfter }
        elseif ($Mode -eq 'Split' -or $Mode -eq 'Slider') {
            $leftBound = 40
            $rightBound = $canvasWidth - 40
            $topBound = 40
            $bottomBound = $canvasHeight - 40
            $isSlider = $Mode -eq 'Slider'
            $splitX = if ($isSlider) { $leftBound + [int](($rightBound - $leftBound) * ($SliderPosition / 100.0)) } else { [int](($leftBound + $rightBound) / 2) }
            if ($isSlider) {
                $clipX = $leftBound
                $clipWidth = [Math]::Max(0, $splitX - $leftBound)
            } else {
                $clipX = $splitX
                $clipWidth = [Math]::Max(0, $rightBound - $splitX)
            }
            if ($clipWidth -gt 0) {
                $graphics.SetClip((New-Object Drawing.Rectangle -ArgumentList @($clipX,$topBound,$clipWidth,($bottomBound-$topBound))))
                & $drawAfter
                $graphics.ResetClip()
            }
            $divider=New-Object Drawing.Pen([Drawing.Color]::White,4);$graphics.DrawLine($divider,$splitX,$topBound,$splitX,$bottomBound);$divider.Dispose()
            $label=New-Object Drawing.SolidBrush([Drawing.Color]::White)
            $graphics.DrawString('BEFORE',$small,$label,70,55);$graphics.DrawString('AFTER',$small,$label,[Math]::Min($splitX+30,$canvasWidth-130),55)
            $label.Dispose()
        }
        return $bitmap
    } catch { $bitmap.Dispose(); throw } finally { $graphics.Dispose(); $font.Dispose(); $small.Dispose(); $brush.Dispose(); $pen.Dispose() }
}

function New-TpmReShadePreviewArtifact {
    param([Parameter(Mandatory)]$ProfileDefinition, [ValidateSet('Before','After','Split','Slider')][string]$Mode = 'Split', [string]$PreviewRoot = '', [string]$CacheRoot = '', [string]$IntensityId = 'Default', [ValidateRange(0,100)][int]$SliderPosition = 50)
    try {
        $reference = Get-TpmReShadePreviewReference -PreviewRoot $PreviewRoot
        if (-not $reference.Available) { return [pscustomobject]@{ Available=$false; Reason=$reference.Reason; Mode=$Mode; ProfileId=$ProfileDefinition.ProfileId } }
        $catalog=@(Get-TpmReShadeEffectCatalog);$hashes=@()
        foreach($id in @($ProfileDefinition.Effects)){$effect=@($catalog|Where-Object EffectId -eq $id)[0];if(-not $effect){return [pscustomobject]@{Available=$false;Reason='UNAPPROVED_EFFECT';Mode=$Mode;ProfileId=$ProfileDefinition.ProfileId}};$hashes+=@($effect.SHA256)}
        $key=Get-TpmReShadePreviewCacheKey -SubjectId ($ProfileDefinition.ProfileId+'|'+$Mode+'|'+$SliderPosition) -ShaderSha256 $hashes -IntensityId $IntensityId -PresetVersion ([string]$ProfileDefinition.SchemaVersion) -ReferenceVersion $reference.Version -ReferenceSha256 $reference.Hash -RendererVersion '2'
        $sourceRoot=if($PreviewRoot){[IO.Path]::GetFullPath($PreviewRoot)}else{[IO.Path]::GetFullPath((Join-Path $PSScriptRoot 'ReShadePreviewCache'))}
        $root=if($CacheRoot){[IO.Path]::GetFullPath($CacheRoot)}else{[IO.Path]::GetFullPath((Join-Path $sourceRoot 'Cache'))}
        $previewRootFull=$sourceRoot
        if(-not $root.StartsWith($previewRootFull.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){return [pscustomobject]@{Available=$false;Reason='CACHE_ROOT_UNSAFE';Mode=$Mode;ProfileId=$ProfileDefinition.ProfileId}}
        [IO.Directory]::CreateDirectory($root)|Out-Null;$imagePath=Join-Path $root ($key+'.png');$manifestPath=Join-Path $root ($key+'.json')
        if((Test-Path -LiteralPath $imagePath -PathType Leaf) -and (Test-Path -LiteralPath $manifestPath -PathType Leaf)){
            try{$manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json;if($manifest.CacheKey -eq $key -and $manifest.ReferenceHash -eq $reference.Hash){$check=[Drawing.Image]::FromFile($imagePath);$check.Dispose();return [pscustomobject]@{Available=$true;Path=$imagePath;CacheKey=$key;Reused=$true;ReferenceIdentity=$reference.Identity;Mode=$Mode;ProfileId=$ProfileDefinition.ProfileId}}}catch{}
        }
        $bitmap=New-TpmReShadePreviewBitmap -ProfileDefinition $ProfileDefinition -Mode $Mode -SliderPosition $SliderPosition
        try{$bitmap.Save($imagePath,[Drawing.Imaging.ImageFormat]::Png)}finally{$bitmap.Dispose()}
        [pscustomobject]@{CacheKey=$key;ProfileId=$ProfileDefinition.ProfileId;Mode=$Mode;ReferenceIdentity=$reference.Identity;ReferenceHash=$reference.Hash;RendererVersion='2';PresetVersion=[string]$ProfileDefinition.SchemaVersion;ShaderSha256=@($hashes);IntensityId=$IntensityId}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $manifestPath -Encoding UTF8
        return [pscustomobject]@{Available=$true;Path=$imagePath;CacheKey=$key;Reused=$false;ReferenceIdentity=$reference.Identity;Mode=$Mode;ProfileId=$ProfileDefinition.ProfileId}
    } catch { return [pscustomobject]@{Available=$false;Reason='PREVIEW_RENDER_FAILED';Mode=$Mode;ProfileId=$ProfileDefinition.ProfileId;Error=$_.Exception.Message} }
}

function Open-TpmReShadePreviewWindow {
    param([Parameter(Mandatory)]$ProfileDefinition, [ValidateSet('Before','After','Split')][string]$Mode='Split', [string]$CacheRoot='', [switch]$Show)
    if(-not $Show){return [pscustomobject]@{Available=$false;Closed=$true;Reason='PREVIEW_WINDOW_NOT_REQUESTED';Mode=$Mode}}
    $formsLoaded = $false
    $drawingLoaded = $false
    $previewRoot = [IO.Path]::GetFullPath($PSScriptRoot)
    $assetChecks = @('embedded synthetic reference')
    try {
        if([Threading.Thread]::CurrentThread.GetApartmentState() -ne [Threading.ApartmentState]::STA){throw [InvalidOperationException]::new('STA required')}
        Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop; $formsLoaded = $true
        Add-Type -AssemblyName System.Drawing -ErrorAction Stop; $drawingLoaded = $true
        $artifact=New-TpmReShadePreviewArtifact -ProfileDefinition $ProfileDefinition -Mode $Mode -CacheRoot $CacheRoot
        if(-not $artifact.Available){
            Write-Log ("ReShade preview unavailable: reason={0} error='{1}' root='{2}' assets={3} PowerShell={4} edition={5} FormsLoaded={6} DrawingLoaded={7} Host='{8}'" -f $artifact.Reason, $artifact.Error, $previewRoot, ($assetChecks -join ';'), $PSVersionTable.PSVersion, $PSVersionTable.PSEdition, $formsLoaded, $drawingLoaded, $Host.Name)
            return $artifact
        }
        $form=New-Object Windows.Forms.Form;$form.Text='TeknoParrot ReShade Preview - '+$ProfileDefinition.FriendlyName;$form.Width=1000;$form.Height=700
        $picture=New-Object Windows.Forms.PictureBox;$picture.Dock='Fill';$picture.SizeMode='Zoom';$picture.Image=[Drawing.Image]::FromFile($artifact.Path)
        $toolbar=New-Object Windows.Forms.FlowLayoutPanel;$toolbar.Dock='Top';$toolbar.Height=70
        foreach($view in @('Before','After','Split')){$button=New-Object Windows.Forms.Button;$button.Text=$view;$button.Tag=$view;$button.Width=90;$button.Add_Click({[void](Update-TpmReShadePreviewWindow -Mode $this.Tag)});$toolbar.Controls.Add($button)}
        $sliderLabel=New-Object Windows.Forms.Label;$sliderLabel.Text='Comparison slider';$sliderLabel.AutoSize=$true;$toolbar.Controls.Add($sliderLabel)
        $slider=New-Object Windows.Forms.TrackBar;$slider.Name='ComparisonSlider';$slider.Minimum=0;$slider.Maximum=100;$slider.Value=50;$slider.TickFrequency=25;$slider.Width=300
        $script:TpmReShadePreviewWindowState=[pscustomobject]@{Form=$form;Picture=$picture;Profile=$ProfileDefinition;Mode=$Mode;CacheRoot=$CacheRoot;Slider=$slider;SliderValue=50}
        $slider.Add_ValueChanged({[void](Update-TpmReShadePreviewWindow -Mode 'Slider' -SliderPosition $this.Value)});$toolbar.Controls.Add($slider)
        $form.Controls.Add($picture);$form.Controls.Add($toolbar)
        return [pscustomobject]@{Available=$true;Closed=$false;Mode=$Mode;CacheKey=$artifact.CacheKey}
    } catch {
        Write-Log ("ReShade preview unavailable: reason=PREVIEW_WINDOW_UNAVAILABLE errorType='{0}' error='{1}' root='{2}' assets={3} PowerShell={4} edition={5} FormsLoaded={6} DrawingLoaded={7} Host='{8}'" -f $_.Exception.GetType().FullName, $_.Exception.Message, $previewRoot, ($assetChecks -join ';'), $PSVersionTable.PSVersion, $PSVersionTable.PSEdition, $formsLoaded, $drawingLoaded, $Host.Name)
        return [pscustomobject]@{Available=$false;Closed=$true;Reason='PREVIEW_WINDOW_UNAVAILABLE';Mode=$Mode;Error=$_.Exception.Message}
    }
}

function Update-TpmReShadePreviewWindow {
    param([ValidateSet('Before','After','Split','Slider')][string]$Mode='Split', [ValidateRange(0,100)][int]$SliderPosition=50)
    if(-not $script:TpmReShadePreviewWindowState -or $script:TpmReShadePreviewWindowState.Form.IsDisposed){return [pscustomobject]@{Available=$false;Reason='PREVIEW_WINDOW_CLOSED'}}
    $state=$script:TpmReShadePreviewWindowState
    if($Mode -eq 'Slider'){
        try{
            $image=New-TpmReShadePreviewBitmap -ProfileDefinition $state.Profile -Mode Slider -SliderPosition $SliderPosition
            $old=$state.Picture.Image;$state.Picture.Image=$image;if($old){$old.Dispose()};$state.Mode=$Mode;$state.SliderValue=$SliderPosition
            return [pscustomobject]@{Available=$true;Mode=$Mode;SliderPosition=$SliderPosition;InMemory=$true}
        }catch{
            return [pscustomobject]@{Available=$false;Reason='PREVIEW_RENDER_FAILED';Error=$_.Exception.Message}
        }
    }
    $artifact=New-TpmReShadePreviewArtifact -ProfileDefinition $state.Profile -Mode $Mode -CacheRoot $state.CacheRoot -SliderPosition $SliderPosition
    if(-not $artifact.Available){return $artifact}
    $old=$state.Picture.Image;$state.Picture.Image=[Drawing.Image]::FromFile($artifact.Path);if($old){$old.Dispose()};$state.Mode=$Mode;$state.SliderValue=$SliderPosition
    return [pscustomobject]@{Available=$true;Mode=$Mode;CacheKey=$artifact.CacheKey;SliderPosition=$SliderPosition}
}

function Close-TpmReShadePreviewWindow {
    if($script:TpmReShadePreviewWindowState){$state=$script:TpmReShadePreviewWindowState;if($state.Picture.Image){$state.Picture.Image.Dispose()};if($state.Form){$state.Form.Close();$state.Form.Dispose()};$script:TpmReShadePreviewWindowState=$null}
    return [pscustomobject]@{Closed=$true}
}

function Show-TpmReShadePreviewWindow {
    param([Parameter(Mandatory)]$ProfileDefinition, [ValidateSet('Before','After','Split')][string]$Mode = 'Split', [object]$ResolutionEvidence = $null, [switch]$Show)
    if(-not $Show){return [pscustomobject]@{Available=$false;Closed=$true;Mode=$Mode;Reason='PREVIEW_WINDOW_NOT_REQUESTED'}}
    $opened=Open-TpmReShadePreviewWindow -ProfileDefinition $ProfileDefinition -Mode $Mode -Show
    if(-not $opened.Available){return $opened}
    try{$script:TpmReShadePreviewWindowState.Form.ShowDialog()|Out-Null;return [pscustomobject]@{Available=$true;Closed=$true;Mode=$Mode;CacheKey=$opened.CacheKey}}finally{Close-TpmReShadePreviewWindow|Out-Null}
}


function Get-TpmReShadeAssetInventory {
    return @(Get-TpmReShadeEffectCatalog | ForEach-Object { $_.RelativeFiles })
}

function Test-TpmReShadeAssetInventory {
    param([string]$AssetRoot)
    foreach ($effect in (Get-TpmReShadeEffectCatalog)) {
        for ($i = 0; $i -lt @($effect.RelativeFiles).Count; $i++) {

            $path = Join-Path $AssetRoot ($effect.RelativeFiles[$i] -replace '/', '\')
            if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return $false }
        }
    }
    return $true
}
function Get-TpmReShadeApprovedEffectFiles {
    param([Parameter(Mandatory)][string]$EffectId)
    $effect = @(Get-TpmReShadeEffectCatalog | Where-Object EffectId -eq $EffectId)[0]
    if (-not $effect) { throw "Effect is not approved: $EffectId" }
    $files = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt @($effect.RelativeFiles).Count; $i++) {
        $relative = [string]$effect.RelativeFiles[$i]
        if ($relative -match '(^|/)\.\.?(/|$)' -or $relative.StartsWith('/') -or $relative -match '%2f|%5c|%2e' ) { throw 'Approved effect path is unsafe.' }
        $url = 'https://raw.githubusercontent.com/' + $effect.AllowedPathPrefix.Trim('/') + '/' + $relative
        $uri = $null
        $validUri = [Uri]::TryCreate($url, [UriKind]::Absolute, [ref]$uri)
        if (-not $validUri -or $uri.Scheme -ne 'https' -or $uri.Host -notin $effect.AllowedHosts -or $uri.Query -or $uri.Fragment -or $uri.AbsolutePath -ne ('/' + $effect.AllowedPathPrefix.Trim('/') + '/' + $relative) -or $uri.AbsolutePath -match '%2f|%5c|%2e' -or -not $uri.AbsolutePath.StartsWith($effect.AllowedPathPrefix, [StringComparison]::Ordinal)) { throw 'Approved effect URL failed allowlist validation.' }
        [void]$files.Add([pscustomobject]@{ EffectId = $effect.EffectId; RelativePath = $relative; Url = $url; SHA256 = $effect.SHA256[$i] })
    }
    return $files.ToArray()
}

function Test-TpmReShadeApprovedEffectFile {
    param([Parameter(Mandatory)]$FileSpec, [Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }

    try { return ((Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash -ieq $FileSpec.SHA256) } catch { return $false }
}
function Acquire-TpmReShadeApprovedEffect {
    param([Parameter(Mandatory)][string]$EffectId, [Parameter(Mandatory)][string]$CacheRoot, [string]$StagingRoot = '')
    $specs = @(Get-TpmReShadeApprovedEffectFiles -EffectId $EffectId)
    $effectCache = Join-Path $CacheRoot ($EffectId -replace '[^A-Za-z0-9_.-]', '_')
    [void][IO.Directory]::CreateDirectory($effectCache)
    $stage = if ($StagingRoot) { $StagingRoot } else { New-TpmStagingDirectory -Label 'ReShadeEffect' }
    if (-not (Test-Path -LiteralPath $stage -PathType Container)) { [void][IO.Directory]::CreateDirectory($stage) }
    $result = New-Object System.Collections.Generic.List[object]
    foreach ($spec in $specs) {
        $cachePath = Join-Path $effectCache ([IO.Path]::GetFileName($spec.RelativePath))
        $stagePath = Join-Path $stage ($spec.RelativePath -replace '/', '\')
        $stageDir = [IO.Path]::GetDirectoryName($stagePath)
        [void][IO.Directory]::CreateDirectory($stageDir)
        $source = $null
        if (Test-TpmReShadeApprovedEffectFile -FileSpec $spec -Path $cachePath) { $source = $cachePath }
        else {
            try {
                Invoke-WebRequest -Uri $spec.Url -UseBasicParsing -OutFile $stagePath -ErrorAction Stop
                if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec $spec -Path $stagePath)) { throw "Hash mismatch for $($spec.RelativePath)." }
                Copy-Item -LiteralPath $stagePath -Destination $cachePath -Force -ErrorAction Stop
                $source = $stagePath
            } catch { throw "Approved effect acquisition failed for $($spec.RelativePath): $($_.Exception.Message)" }
        }
        if ($source -ne $stagePath) { Copy-Item -LiteralPath $source -Destination $stagePath -Force -ErrorAction Stop }
        [void]$result.Add([pscustomobject]@{ EffectId = $EffectId; RelativePath = $spec.RelativePath; Path = $stagePath; SHA256 = $spec.SHA256; FromCache = ($source -eq $cachePath) })
    }
    return [pscustomobject]@{ EffectId = $EffectId; StagingRoot = $stage; Files = $result.ToArray() }
}

function New-TpmReShadeOwnershipManifest {
    param([Parameter(Mandatory)][string]$EffectId, [Parameter(Mandatory)][string]$DestinationRoot, [Parameter(Mandatory)]$AcquiredFiles)
    $effect = @(Get-TpmReShadeEffectCatalog | Where-Object EffectId -eq $EffectId)[0]
    if (-not $effect) { throw "Effect is not approved: $EffectId" }
    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($file in @($AcquiredFiles)) {
        $destination = Join-Path $DestinationRoot ($file.RelativePath -replace '/', '\')
        $actual = $null
        if (Test-Path -LiteralPath $file.Path -PathType Leaf) { try { $actual = (Get-FileHash -LiteralPath $file.Path -Algorithm SHA256 -ErrorAction Stop).Hash } catch {} }
        [void]$entries.Add([pscustomobject]@{ EffectId = $EffectId; PinnedRevision = $effect.PinnedCommit; RelativeSource = $file.RelativePath; DestinationPath = $destination; ExpectedSHA256 = $file.SHA256; ActualSHA256 = $actual; TPMManaged = $true })
    }
    return [pscustomobject]@{ SchemaVersion = 1; EffectId = $EffectId; PinnedRevision = $effect.PinnedCommit; Files = $entries.ToArray() }
}

function Save-TpmReShadeOwnershipManifest {
    param([Parameter(Mandatory)]$Manifest, [Parameter(Mandatory)][string]$Path)
    $parent = [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Path))
    [void][IO.Directory]::CreateDirectory($parent)
    $tmp = $Path + '.tmp'
    [IO.File]::WriteAllText($tmp, ($Manifest | ConvertTo-Json -Depth 8), (New-Object Text.UTF8Encoding $false))
    Move-Item -LiteralPath $tmp -Destination $Path -Force -ErrorAction Stop
}

function Read-TpmReShadeOwnershipManifest {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
    $manifest = Get-Content -LiteralPath $Path -Raw -ErrorAction Stop | ConvertFrom-Json
    if ($manifest.SchemaVersion -ne 1 -or -not $manifest.EffectId -or -not $manifest.Files) { throw 'Invalid ReShade ownership manifest.' }
    return $manifest
}

function Get-TpmReShadeRoleDemandValue {
    param([object]$RoleBytes, [Parameter(Mandatory)][string]$Role)
    if (-not $RoleBytes) { return [int64]0 }
    $key = $Role.ToUpperInvariant() -replace 'PATH$',''
    $property = $RoleBytes.PSObject.Properties[$key]
    if ($property -and $null -ne $property.Value) { return [int64]$property.Value }
    return [int64]0
}

function Test-TpmReShadeStoragePreflight {
    param([Parameter(Mandatory)]$Evidence)
    $blocking = New-Object System.Collections.Generic.List[string]
    $results = New-Object System.Collections.Generic.List[object]
    $volumes = @($Evidence.Volumes)
    $topRequired = $null
    if ($Evidence.PSObject.Properties['RequiredWorkingBytes'] -and $null -ne $Evidence.RequiredWorkingBytes) { $topRequired = [int64]$Evidence.RequiredWorkingBytes }
    foreach ($volume in $volumes) {
        $root = if ($volume.PSObject.Properties['Root'] -and $volume.Root) { [string]$volume.Root } else { 'UNKNOWN_VOLUME' }
        $required = $null
        if ($volume.PSObject.Properties['RequiredBytes'] -and $null -ne $volume.RequiredBytes) { $required = [int64]$volume.RequiredBytes }
        elseif ($volumes.Count -eq 1 -and $null -ne $topRequired) { $required = $topRequired }
        $free = if ($volume.PSObject.Properties['FreeBytes']) { $volume.FreeBytes } else { $null }
        $demandByRole = if ($volume.PSObject.Properties['DemandByRole']) { $volume.DemandByRole } else { [ordered]@{} }
        $reason = 'sufficient'
        $sufficient = $true
        if ($null -eq $required) {
            $sufficient = $false; $reason = 'required capacity is unknown'
        } elseif ($required -gt 0 -and $null -eq $free) {
            $sufficient = $false; $reason = 'free capacity is unknown'
        } elseif ($null -ne $free -and [int64]$free -lt $required) {
            $sufficient = $false; $reason = 'free capacity is insufficient'
        }
        if (-not $sufficient) { [void]$blocking.Add($root) }
        [void]$results.Add([pscustomobject]@{ Root = $root; FreeBytes = if ($null -eq $free) { $null } else { [int64]$free }; RequiredBytes = $required; Sufficient = $sufficient; Reason = $reason; Roles = @($volume.Roles); DemandByRole = $demandByRole })
    }
    if ($volumes.Count -eq 0 -and $null -ne $topRequired -and $topRequired -gt 0) { [void]$blocking.Add('UNKNOWN_VOLUME') }
    return [pscustomobject]@{ Allowed = ($blocking.Count -eq 0); BlockingVolumes = $blocking.ToArray(); RequiredWorkingBytes = $topRequired; Volumes = $volumes; VolumeResults = $results.ToArray() }
}
function Get-TpmReShadeTransactionStoragePlan {
    param([Parameter(Mandatory)]$AcquiredFiles, [string]$DestinationRoot, [object]$PriorManifest = $null)
    $files = @($AcquiredFiles)
    $staged = [int64]0
    foreach ($file in $files) { $staged += [int64](Get-Item -LiteralPath $file.Path -ErrorAction Stop).Length }
    $backup = [int64]0
    if ($PriorManifest) { foreach ($file in @($PriorManifest.Files)) { if (Test-Path -LiteralPath $file.DestinationPath -PathType Leaf) { $backup += [int64](Get-Item -LiteralPath $file.DestinationPath -ErrorAction Stop).Length } } }
    $stagePath = if ($files.Count -gt 0) { [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath([string]$files[0].Path)) } else { $DestinationRoot }
    $roleBytes = [pscustomobject][ordered]@{ CACHE = [int64]0; STAGING = $staged; BACKUP = $backup; TARGET = $staged; ROLLBACK = $backup }
    $roles = @(
        [pscustomobject]@{ Role = 'STAGING'; Path = $stagePath; Bytes = $roleBytes.STAGING },
        [pscustomobject]@{ Role = 'BACKUP'; Path = $stagePath; Bytes = $roleBytes.BACKUP },
        [pscustomobject]@{ Role = 'TARGET'; Path = $DestinationRoot; Bytes = $roleBytes.TARGET },
        [pscustomobject]@{ Role = 'ROLLBACK'; Path = $DestinationRoot; Bytes = $roleBytes.ROLLBACK }
    )
    $required = $staged + $backup + $staged + $backup
    return [pscustomobject]@{ RequiredWorkingBytes = $required; StagedBytes = $staged; BackupBytes = $backup; PromotionBytes = $staged; RollbackBytes = $backup; CacheBytes = [int64]0; RoleBytes = $roleBytes; Roles = $roles; RolePaths = [pscustomobject][ordered]@{ STAGING = $stagePath; BACKUP = $stagePath; TARGET = $DestinationRoot; ROLLBACK = $DestinationRoot } }
}
function Get-TpmReShadePreAcquisitionStoragePlan {
    param([Parameter(Mandatory)][string]$EffectId, [Parameter(Mandatory)][string]$CacheRoot, [Parameter(Mandatory)][string]$DestinationRoot, [object]$PriorManifest = $null)
    $cache = Join-Path $CacheRoot ($EffectId -replace '[^A-Za-z0-9_.-]', '_')
    $effect = @(Get-TpmReShadeEffectCatalog | Where-Object EffectId -eq $EffectId)[0]
    $specs = @(Get-TpmReShadeApprovedEffectFiles -EffectId $EffectId)
    $assetBytes = [int64]0; $known = $true
    for ($index = 0; $index -lt $specs.Count; $index++) {
        $spec = $specs[$index]; $cached = Join-Path $cache ([IO.Path]::GetFileName($spec.RelativePath))
        if ((Test-Path -LiteralPath $cached -PathType Leaf) -and (Test-TpmReShadeApprovedEffectFile -FileSpec $spec -Path $cached)) { $assetBytes += [int64](Get-Item -LiteralPath $cached -ErrorAction Stop).Length }
        elseif ($effect -and $effect.PSObject.Properties['ByteLengths'] -and @($effect.ByteLengths).Count -gt $index) { $assetBytes += [int64]$effect.ByteLengths[$index] }
        else { $known = $false }
    }
    $backupBytes = [int64]0
    if ($PriorManifest) { foreach ($file in @($PriorManifest.Files)) { if (Test-Path -LiteralPath $file.DestinationPath -PathType Leaf) { $backupBytes += [int64](Get-Item -LiteralPath $file.DestinationPath -ErrorAction Stop).Length } } }
    $targetBytes = $assetBytes
    $roleBytes = [pscustomobject][ordered]@{ CACHE = $assetBytes; STAGING = $assetBytes; BACKUP = $backupBytes; TARGET = $targetBytes; ROLLBACK = $backupBytes }
    $required = if ($known) { $assetBytes + $backupBytes + $targetBytes + $backupBytes } else { $null }
    return [pscustomobject]@{ EffectId = $EffectId; CapacityKnown = $known; CacheBytes = $assetBytes; StagingBytes = $assetBytes; BackupBytes = $backupBytes; TargetBytes = $targetBytes; RollbackBytes = $backupBytes; RoleBytes = $roleBytes; RolePaths = [pscustomobject][ordered]@{ CACHE = $cache; STAGING = $CacheRoot; BACKUP = $DestinationRoot; TARGET = $DestinationRoot; ROLLBACK = $DestinationRoot }; RequiredWorkingBytes = $required; Reason = if ($known) { 'Validated cache or pinned catalog byte lengths.' } else { 'Pinned asset size unavailable before acquisition.' } }
}

function Install-TpmReShadeApprovedEffect {
    param([Parameter(Mandatory)][string]$EffectId, [Parameter(Mandatory)][string]$CacheRoot, [Parameter(Mandatory)][string]$DestinationRoot, [Parameter(Mandatory)][string]$OwnershipPath, [ValidateSet('None','AfterFirstPromotion','BeforeCommit','BackupCreation','BackupVerification','RollbackFailure','AfterFirstPromotionRollbackFailure')][string]$FaultStage = 'None', [object]$StoragePreflight = $null, [switch]$PrepareOnly)
    $priorOwnership = Read-TpmReShadeOwnershipManifest -Path $OwnershipPath
    if ($StoragePreflight) {
        $prePlan = Get-TpmReShadePreAcquisitionStoragePlan -EffectId $EffectId -CacheRoot $CacheRoot -DestinationRoot $DestinationRoot -PriorManifest $priorOwnership
        if ($null -eq $prePlan.RequiredWorkingBytes) { throw "STORAGE: UNKNOWN pre-acquisition capacity requirement. No network or mutation started." }
        if (-not $StoragePreflight.PSObject.Properties['RequiredWorkingBytes']) { Add-Member -InputObject $StoragePreflight -MemberType NoteProperty -Name RequiredWorkingBytes -Value ([int64]0) }
        $StoragePreflight.RequiredWorkingBytes = $prePlan.RequiredWorkingBytes
        foreach ($volume in @($StoragePreflight.Volumes)) {
            $required = [int64]0
            foreach ($role in @($volume.Roles)) { $required += Get-TpmReShadeRoleDemandValue -RoleBytes $prePlan.RoleBytes -Role ([string]$role) }
            if (-not $volume.PSObject.Properties['RequiredBytes']) { Add-Member -InputObject $volume -MemberType NoteProperty -Name RequiredBytes -Value ([int64]0) }
            $volume.RequiredBytes = $required
        }
        $preflight = Test-TpmReShadeStoragePreflight -Evidence $StoragePreflight
        if (-not $preflight.Allowed) { throw "STORAGE: insufficient or unknown capacity on $($preflight.BlockingVolumes -join ', '). No mutation started." }
    }
    $acquired = Acquire-TpmReShadeApprovedEffect -EffectId $EffectId -CacheRoot $CacheRoot
    if ($StoragePreflight) {
        $plan = Get-TpmReShadeTransactionStoragePlan -AcquiredFiles @($acquired.Files) -DestinationRoot $DestinationRoot
        $StoragePreflight.RequiredWorkingBytes = $plan.RequiredWorkingBytes
        foreach ($volume in @($StoragePreflight.Volumes)) {
            $required = [int64]0
            foreach ($role in @($volume.Roles)) { $required += Get-TpmReShadeRoleDemandValue -RoleBytes $plan.RoleBytes -Role ([string]$role) }
            if (-not $volume.PSObject.Properties['RequiredBytes']) { Add-Member -InputObject $volume -MemberType NoteProperty -Name RequiredBytes -Value ([int64]0) }
            $volume.RequiredBytes = $required
        }
        $postflight = Test-TpmReShadeStoragePreflight -Evidence $StoragePreflight
        if (-not $postflight.Allowed) { throw "STORAGE: insufficient or unknown capacity on $($postflight.BlockingVolumes -join ', '). No promotion started." }
    }
    $manifest = New-TpmReShadeOwnershipManifest -EffectId $EffectId -DestinationRoot $DestinationRoot -AcquiredFiles @($acquired.Files)
    foreach ($asset in @($acquired.Files)) {
        if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec $asset -Path $asset.Path)) { throw "INTEGRITY: staged approved effect hash validation failed for $($asset.RelativePath)." }
    }
    if ($PrepareOnly) { return [pscustomobject]@{ Succeeded = $true; State = 'PREPARED'; StagingRoot = $acquired.StagingRoot; Files = @($acquired.Files); Manifest = $priorOwnership } }
    $old = Read-TpmReShadeOwnershipManifest -Path $OwnershipPath
    $backup = Join-Path $acquired.StagingRoot '.tpm-backup'
    $changed = @()
    $wasRepair = $false
    $allExact = $true
    foreach ($entry in @($manifest.Files)) {
        $prior = $null
        if ($old) { foreach ($candidate in @($old.Files)) { if ([string]$candidate.DestinationPath -eq [string]$entry.DestinationPath) { $prior = $candidate; break } } }
        if (-not $prior -or [string]$prior.TPMManaged -ne 'True' -or -not (Test-TpmReShadeApprovedEffectFile -FileSpec ([pscustomobject]@{ SHA256 = $entry.ExpectedSHA256 }) -Path $entry.DestinationPath)) { $allExact = $false; break }
    }
    if ($allExact) { return [pscustomobject]@{ Succeeded = $true; State = 'NO_OP'; Manifest = $old } }
    try {
        foreach ($entry in @($manifest.Files)) {
            if ([IO.File]::Exists([string]$entry.DestinationPath)) {
                $owned = $false
                if ($null -ne $old) {
                    foreach ($priorEntry in @($old.Files)) {
                        if ([string]$priorEntry.DestinationPath -eq [string]$entry.DestinationPath -and $priorEntry.TPMManaged -eq $true) { $owned = $true; break }
                    }
                }
                if (-not $owned) { throw "COLLISION: existing non-TPM-managed file '$($entry.DestinationPath)' was preserved." }
            }
            if (-not (Test-PathInside ([string]$entry.DestinationPath) ([string]$DestinationRoot))) { throw 'SECURITY: destination escaped approved ReShade root.' }
            if (Test-Path -LiteralPath $entry.DestinationPath -PathType Leaf) {
                $owned = $false
                if ($null -ne $old) {
                    foreach ($priorEntry in @($old.Files)) {
                        if ([string]$priorEntry.DestinationPath -eq [string]$entry.DestinationPath -and $priorEntry.TPMManaged -eq $true) { $owned = $true; break }
                    }
                }
                if (-not $owned) { throw "COLLISION: existing non-TPM-managed file '$($entry.DestinationPath)' was preserved." }
                if ($FaultStage -eq 'BackupCreation') { throw 'BACKUP: forced backup creation failure.' }
                [void][IO.Directory]::CreateDirectory($backup)
                $originalHash = (Get-FileHash -LiteralPath $entry.DestinationPath -Algorithm SHA256 -ErrorAction Stop).Hash
                $backupPath = Join-Path $backup ([IO.Path]::GetFileName($entry.DestinationPath))
                Copy-Item -LiteralPath $entry.DestinationPath -Destination $backupPath -Force -ErrorAction Stop
                if ($FaultStage -eq 'BackupVerification') { throw 'BACKUP: forced backup verification failure.' }
                if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec ([pscustomobject]@{ SHA256 = $originalHash }) -Path $backupPath)) { throw "BACKUP: verification failed for $($entry.DestinationPath)." }
                $wasRepair = $true
            }
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($entry.DestinationPath))
            Copy-Item -LiteralPath ($acquired.Files | Where-Object RelativePath -eq $entry.RelativeSource | Select-Object -ExpandProperty Path) -Destination $entry.DestinationPath -Force -ErrorAction Stop
            $changed += $entry
            if (($FaultStage -eq 'AfterFirstPromotion' -or $FaultStage -eq 'AfterFirstPromotionRollbackFailure') -and $changed.Count -eq 1) { throw 'TEST: forced promotion failure after first promotion.' }
        }
        foreach ($entry in @($manifest.Files)) {
            if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec ([pscustomobject]@{ SHA256 = $entry.ExpectedSHA256 }) -Path $entry.DestinationPath)) { throw "VERIFY: installed hash mismatch for $($entry.RelativeSource)." }
            $entry.ActualSHA256 = (Get-FileHash -LiteralPath $entry.DestinationPath -Algorithm SHA256).Hash
        }
        if ($FaultStage -eq 'BeforeCommit') { throw 'TEST: forced final verification failure.' }
        Save-TpmReShadeOwnershipManifest -Manifest $manifest -Path $OwnershipPath
        $installState = 'INSTALLED'
        if ($wasRepair) { $installState = 'REPAIR' }
        return [pscustomobject]@{ Succeeded = $true; State = $installState; Manifest = $manifest }
    } catch {
        if ($_.Exception.Message -like 'COLLISION:*') { return [pscustomobject]@{ Succeeded = $false; State = 'COLLISION'; Error = $_.Exception.Message } }
        $rollbackOk = $true
        $rollbackErrors = @()
        foreach ($entry in @($changed)) {
            $bak = Join-Path $backup ([IO.Path]::GetFileName($entry.DestinationPath))
            try {
                if ($FaultStage -eq 'RollbackFailure' -or $FaultStage -eq 'AfterFirstPromotionRollbackFailure') { throw 'TEST: forced rollback restore failure.' }
                if (Test-Path -LiteralPath $bak -PathType Leaf) {
                    Copy-Item -LiteralPath $bak -Destination $entry.DestinationPath -Force -ErrorAction Stop
                } elseif (Test-Path -LiteralPath $entry.DestinationPath -PathType Leaf) {
                    Remove-Item -LiteralPath $entry.DestinationPath -Force -ErrorAction Stop
                }
                $prior = $null
                if ($old) {
                    $priorMatches = @($old.Files | Where-Object DestinationPath -eq $entry.DestinationPath)
                    if ($priorMatches.Count -gt 0) { $prior = $priorMatches[0] }
                }
                if ($prior -and -not (Test-TpmReShadeApprovedEffectFile -FileSpec ([pscustomobject]@{ SHA256 = $prior.ExpectedSHA256 }) -Path $entry.DestinationPath)) { throw 'restored file hash mismatch' }
                if (-not $prior -and (Test-Path -LiteralPath $entry.DestinationPath -PathType Leaf)) { throw 'new file remained after rollback' }
            } catch { $rollbackOk = $false; $rollbackErrors += $_.Exception.Message }
        }
        $rollbackState = 'ACTION_REQUIRED'
        if ($rollbackOk) { $rollbackState = 'ROLLED_BACK' }
        return [pscustomobject]@{ Succeeded = $false; State = $rollbackState; Error = $_.Exception.Message; RollbackError = ($rollbackErrors -join '; '); RollbackVerified = $rollbackOk }
    }
}

function Get-TpmReShadeProfileOwnershipPath {
    param([Parameter(Mandatory)][string]$GameId, [string]$StateRoot = '')
    $paths = Get-TpmReShadeStatePath -StateRoot $StateRoot
    $idBytes = [Text.Encoding]::UTF8.GetBytes($GameId)
    $idHash = ([BitConverter]::ToString(([Security.Cryptography.SHA256]::Create().ComputeHash($idBytes))) -replace '-', '').ToLowerInvariant()
    return (Join-Path (Join-Path $paths.Root 'Deployments') ($idHash + '.json'))
}

function Install-TpmReShadeProfileDeployment {
    param(
        [Parameter(Mandatory)]$ProfileDefinition,
        [Parameter(Mandatory)][string]$GamePath,
        [Parameter(Mandatory)][System.Xml.XmlDocument]$Doc,
        [Parameter(Mandatory)][string]$SourceDll,
        [string]$SourceDll32 = '',
        [string]$PresetPath = '',
        [string]$PerGamePresetPath = '',
        [Parameter(Mandatory)][string]$CacheRoot,
        [Parameter(Mandatory)][string]$OwnershipPath,
        [string]$VariantId = 'Default',
        [switch]$CanonicalPreset,
        [switch]$AllowUserOwnedOverwrite,
        [ValidateSet('None','BeforeCommit')][string]$FaultStage = 'None'
    )
    $staging = $null
    $preparedStages = New-Object System.Collections.Generic.List[string]
    $preserveStaging = $false
    try {
        $approvedProfile = Get-TpmReShadeProfile -ProfileId $ProfileDefinition.ProfileId
        if (-not $approvedProfile -or [string]$approvedProfile.SchemaVersion -ne [string]$ProfileDefinition.SchemaVersion -or (@($approvedProfile.Effects) -join ',') -ne (@($ProfileDefinition.Effects) -join ',')) {
            return [pscustomobject]@{ Succeeded = $false; State = 'STALE_PROFILE_DEFINITION'; Reason = 'STALE_PROFILE_DEFINITION' }
        }
        $variant = Resolve-TpmReShadeIntensityVariant -ProfileDefinition $approvedProfile -VariantId $VariantId
        $exeDir = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($GamePath))
        if ([string]::IsNullOrWhiteSpace($exeDir)) { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_GAME_PATH'; Reason = 'INVALID_GAME_PATH' } }
        $architecture = Get-ExeArchitecture -ExePath $GamePath
        $activeDll = $SourceDll
        if ($architecture -eq 'x86') {
            if (-not $SourceDll32 -or -not (Test-Path -LiteralPath $SourceDll32 -PathType Leaf)) { return [pscustomobject]@{ Succeeded = $false; State = 'MISSING_32BIT_DLL'; Reason = 'MISSING_32BIT_DLL' } }
            $activeDll = $SourceDll32
        } elseif ($architecture -and $architecture -ne 'x64') {
            return [pscustomobject]@{ Succeeded = $false; State = 'UNSUPPORTED_ARCHITECTURE'; Reason = 'UNSUPPORTED_ARCHITECTURE' }
        }
        if (-not $activeDll -or -not (Test-Path -LiteralPath $activeDll -PathType Leaf) -or -not (Test-TpmNoReparsePath -Path $activeDll)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        if (-not (Test-Path -LiteralPath $GamePath -PathType Leaf) -or -not (Test-TpmNoReparsePath -Path $GamePath)) { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_GAME_PATH'; Reason = 'INVALID_GAME_PATH' } }
        $targetInfo = Get-ReShadeTargetInfo -Doc $Doc -GamePath $GamePath -ExeDir $exeDir
        if (-not $targetInfo -or [string]::IsNullOrWhiteSpace($targetInfo.TargetDir) -or [string]::IsNullOrWhiteSpace($targetInfo.DllName) -or -not (Test-TpmNoReparsePath -Path $targetInfo.TargetDir)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        if ((Test-Path -LiteralPath $CacheRoot) -and -not (Test-TpmNoReparsePath -Path $CacheRoot)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        if (-not (Test-TpmNoReparsePath -Path $OwnershipPath)) { return [pscustomobject]@{ Succeeded = $false; State = 'UNSAFE_PATH'; Reason = 'UNSAFE_PATH' } }
        $prior = Read-TpmReShadeOwnershipManifest -Path $OwnershipPath
        $staging = New-TpmStagingDirectory -Label 'ReShadeProfile'
        $fileNames = New-Object System.Collections.Generic.List[string]
        $manifestFiles = New-Object System.Collections.Generic.List[object]
        $dllName = [System.IO.Path]::GetFileName($targetInfo.DllName)
        if ([string]::IsNullOrWhiteSpace($dllName) -or $dllName -ne $targetInfo.DllName) { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_TARGET'; Reason = 'INVALID_TARGET' } }
        $dllStage = Join-Path $staging $dllName
        Copy-Item -LiteralPath $activeDll -Destination $dllStage -Force -ErrorAction Stop
        if (-not (Test-Path -LiteralPath $dllStage -PathType Leaf)) { throw 'DLL staging failed.' }
        $dllHash = (Get-FileHash -LiteralPath $dllStage -Algorithm SHA256 -ErrorAction Stop).Hash
        [void]$fileNames.Add($dllName)
        [void]$manifestFiles.Add([pscustomobject]@{ RelativeSource = $dllName; DestinationPath = (Join-Path $targetInfo.TargetDir $dllName); ExpectedSHA256 = $dllHash; ActualSHA256 = $dllHash; TPMManaged = $true; Kind = 'ReShadeDll' })
        $effectivePreset = $null
        $presetSource = $null
        $presetContent = $null
        if ($PerGamePresetPath -and (Test-Path -LiteralPath $PerGamePresetPath -PathType Leaf)) { $effectivePreset = $PerGamePresetPath; $presetSource = 'per-game' }
        elseif ($PresetPath -and (Test-Path -LiteralPath $PresetPath -PathType Leaf)) { $effectivePreset = $PresetPath; $presetSource = 'global' }
        if ($effectivePreset) {
            if ([System.IO.Path]::GetExtension($effectivePreset) -ine '.ini') { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_PRESET'; Reason = 'INVALID_PRESET' } }
            $presetContent = [IO.File]::ReadAllText($effectivePreset)
            if ($CanonicalPreset -and $presetSource -eq 'generated' -and -not (Test-TpmReShadePresetContent -Content $presetContent -ProfileDefinition $approvedProfile)) { return [pscustomobject]@{ Succeeded = $false; State = 'INVALID_PRESET'; Reason = 'INVALID_PRESET' } }
        } elseif ($CanonicalPreset -and $approvedProfile.ProfileId -ne 'Original') {
            $presetSource = 'generated'
            $presetContent = New-TpmReShadePresetContent -ProfileDefinition $approvedProfile
        }
        if ($effectivePreset -or $presetContent) {
            $presetName = 'ReShade.ini'
            $presetStage = Join-Path $staging $presetName
            if ($null -ne $presetContent) { [IO.File]::WriteAllText($presetStage, [string]$presetContent, (New-Object Text.UTF8Encoding($false))) }
            else { Copy-Item -LiteralPath $effectivePreset -Destination $presetStage -Force -ErrorAction Stop }
            $presetHash = (Get-FileHash -LiteralPath $presetStage -Algorithm SHA256 -ErrorAction Stop).Hash
            [void]$fileNames.Add($presetName)
            [void]$manifestFiles.Add([pscustomobject]@{ RelativeSource = $presetName; DestinationPath = (Join-Path $targetInfo.TargetDir $presetName); ExpectedSHA256 = $presetHash; ActualSHA256 = $presetHash; TPMManaged = $true; Kind = 'ReShadePreset' })
        }
        foreach ($effectId in @($approvedProfile.Effects)) {
            $prepared = Install-TpmReShadeApprovedEffect -EffectId $effectId -CacheRoot $CacheRoot -DestinationRoot $targetInfo.TargetDir -OwnershipPath $OwnershipPath -PrepareOnly
            if (-not $prepared -or -not $prepared.Succeeded -or $prepared.State -ne 'PREPARED' -or [string]::IsNullOrWhiteSpace([string]$prepared.StagingRoot)) { throw "Approved effect preparation failed for $effectId." }
            [void]$preparedStages.Add([string]$prepared.StagingRoot)
            foreach ($asset in @($prepared.Files)) {
                $rawRelative = [string]$asset.RelativePath
                $relative = ($rawRelative -replace '/', '\').TrimStart('\')
                $assetDestination = Join-Path $targetInfo.TargetDir $relative
                $assetStage = Join-Path $staging $relative
                if ([string]::IsNullOrWhiteSpace($rawRelative) -or [System.IO.Path]::IsPathRooted($rawRelative) -or $rawRelative.StartsWith('/') -or $rawRelative.StartsWith('\') -or $relative -match '(^|\\)\.\.(\\|$)' -or -not (Test-PathInside $assetStage $staging) -or -not (Test-PathInside ([string]$asset.Path) ([string]$prepared.StagingRoot))) { throw 'Approved effect path is unsafe.' }
                [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($assetStage))
                Copy-Item -LiteralPath $asset.Path -Destination $assetStage -Force -ErrorAction Stop
                if (-not (Test-TpmReShadeApprovedEffectFile -FileSpec $asset -Path $assetStage)) { throw "INTEGRITY: staged approved effect hash validation failed for $relative." }
                if ($fileNames -contains $relative) { throw "Duplicate staged ReShade path: $relative" }
                [void]$fileNames.Add($relative)
                $assetHash = (Get-FileHash -LiteralPath $assetStage -Algorithm SHA256 -ErrorAction Stop).Hash
                [void]$manifestFiles.Add([pscustomobject]@{ RelativeSource = $relative; DestinationPath = $assetDestination; ExpectedSHA256 = $assetHash; ActualSHA256 = $assetHash; TPMManaged = $true; Kind = 'ApprovedEffect' })
            }
        }
        foreach ($entry in $manifestFiles.ToArray()) {
            if (-not (Test-PathInside ([string]$entry.DestinationPath) ([string]$targetInfo.TargetDir))) { throw 'SECURITY: profile destination escaped target folder.' }
            if (Test-Path -LiteralPath $entry.DestinationPath) {
                $owned = $false
                if ($prior) { foreach ($oldEntry in @($prior.Files)) { if ([string]$oldEntry.DestinationPath -eq [string]$entry.DestinationPath -and [string]$oldEntry.TPMManaged -eq 'True') { $owned = $true; break } } }
                if (-not $owned -and -not $AllowUserOwnedOverwrite) { return [pscustomobject]@{ Succeeded = $false; State = 'COLLISION'; Reason = 'USER_OWNED_CONTENT_PRESERVED'; Error = "Existing non-TPM-managed file was preserved: $($entry.DestinationPath)" } }
            }
        }
        $retained = @()
        if ($prior) { $retained = @($prior.Files | Where-Object { $_.DestinationPath -notin @($manifestFiles.ToArray() | ForEach-Object DestinationPath) }) }
        $manifest = [pscustomobject]@{ SchemaVersion = 1; EffectId = 'ReShadeProfile.' + $approvedProfile.ProfileId; PinnedRevision = 'TPM-PROFILE'; Files = @($manifestFiles.ToArray() + $retained) }
        $commit = { if ($FaultStage -eq 'BeforeCommit') { throw 'TEST: forced profile commit failure.' }; Save-TpmReShadeOwnershipManifest -Manifest $manifest -Path $OwnershipPath | Out-Null }
        [void](Invoke-TpmTransactionalPromote -StagingDir $staging -DestDir $targetInfo.TargetDir -FileNames $fileNames.ToArray() -CommitAction $commit)
        return [pscustomobject]@{ Succeeded = $true; State = 'INSTALLED'; ProfileId = $approvedProfile.ProfileId; VariantId = $variant.VariantId; TargetDir = $targetInfo.TargetDir; DllName = $dllName; ApiDetected = $targetInfo.ApiDetected; PresetSource = $presetSource; PresetApplied = [bool]($effectivePreset -or $presetContent); Manifest = $manifest }
    } catch {
        $message = $_.Exception.Message
        if ($message -match 'ROLLBACK FAILED|CLEANUP FAILED') { $preserveStaging = $true }
        return [pscustomobject]@{ Succeeded = $false; State = if ($message -match 'COLLISION') { 'COLLISION' } elseif ($message -match 'ROLLBACK FAILED') { 'ACTION_REQUIRED' } else { 'ROLLED_BACK' }; Reason = 'PROFILE_DEPLOYMENT_FAILED'; Error = $message; RollbackVerified = ($message -notmatch 'ROLLBACK FAILED') }
    } finally {
        foreach ($preparedStage in @($preparedStages.ToArray())) { if (Test-Path -LiteralPath $preparedStage) { Remove-Item -LiteralPath $preparedStage -Recurse -Force -ErrorAction SilentlyContinue } }
        if ($staging -and -not $preserveStaging -and (Test-Path -LiteralPath $staging)) { Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue }
    }
}
function Get-TpmHardwareEnvironmentEvidence {
    param([switch]$RefreshDynamic, [string[]]$VolumePaths = @())
    $cpu = $null; $os = $null; $ram = $null; $gpus = @(); $battery = $null
    try { $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1 } catch {}
    try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch {}
    try { $ram = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } catch {}
    try { $gpus = @(Get-CimInstance Win32_VideoController -ErrorAction Stop) } catch {}
    try { $battery = Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1 } catch {}
    $volumes = New-Object System.Collections.Generic.List[object]
    foreach ($path in $VolumePaths) {
        try {
            $root = [IO.Path]::GetPathRoot($path)
            $drive = Get-PSDrive -Name $root.TrimEnd('\').TrimEnd(':') -ErrorAction Stop
            [void]$volumes.Add([pscustomobject]@{ Path = $path; FreeBytes = [int64]$drive.Free; Confidence = 'KNOWN' })
        } catch {
            [void]$volumes.Add([pscustomobject]@{ Path = $path; FreeBytes = $null; Confidence = 'UNKNOWN' })
        }
    }
    return [pscustomobject]@{
        OSVersion = if ($os) { $os.Version } else { $null }; OSBuild = if ($os) { $os.BuildNumber } else { $null }; Architecture = $env:PROCESSOR_ARCHITECTURE
        CpuModel = if ($cpu) { $cpu.Name } else { $null }; PhysicalCoreCount = if ($cpu) { $cpu.NumberOfCores } else { $null }; LogicalProcessorCount = if ($cpu) { $cpu.NumberOfLogicalProcessors } else { $null }; CpuEvidenceConfidence = if ($cpu) { 'RELIABLE' } else { 'UNKNOWN' }
        Adapters = @($gpus | ForEach-Object { [pscustomobject]@{ AdapterIndex = $_.Index; Name = $_.Name; DriverVersion = $_.DriverVersion; DedicatedMemoryBytes = $_.AdapterRAM; Status = $_.Status } }); ActiveAdapterIndex = if ($gpus.Count -eq 1) { 0 } else { $null }; ActiveAdapterName = if ($gpus.Count -eq 1) { $gpus[0].Name } else { $null }; ActiveGpuConfidence = if ($gpus.Count -eq 1) { 'INFERRED' } else { 'UNKNOWN' }; ActiveGpuSelectionReason = if ($gpus.Count -eq 1) { 'only usable adapter enumerated' } else { 'target adapter cannot be established from shared evidence' }; MultiGpuAmbiguous = ($gpus.Count -gt 1)
        InstalledRamBytes = if ($ram) { [int64]$ram.TotalPhysicalMemory } else { $null }; AvailableRamBytes = if ($os) { [int64]$os.FreePhysicalMemory * 1KB } else { $null }; MemoryEvidenceConfidence = if ($ram -and $os) { 'RELIABLE' } else { 'UNKNOWN' }
        RenderWidth = if ($gpus.Count -eq 1) { $gpus[0].CurrentHorizontalResolution } else { $null }; RenderHeight = if ($gpus.Count -eq 1) { $gpus[0].CurrentVerticalResolution } else { $null }; ResolutionConfidence = if ($gpus.Count -eq 1 -and $gpus[0].CurrentHorizontalResolution) { 'INFERRED' } else { 'UNKNOWN' }; DisplayCount = $null; RefreshRate = if ($gpus.Count -eq 1) { $gpus[0].CurrentRefreshRate } else { $null }
        BatteryPowered = [bool]$battery; PowerSavingActive = if ($battery) { $battery.BatteryStatus -in @(1,4,5) } else { $null }; PowerEvidenceConfidence = if ($battery) { 'RELIABLE' } else { 'UNKNOWN' }
        Volumes = $volumes.ToArray()
        DynamicRefreshed = [bool]$RefreshDynamic; SensitiveIdentifiersIncluded = $false
    }
}

function Get-TpmReShadeExpertEffects {
    param([string]$Category = '', [string]$Search = '')
    $effects = @(Get-TpmReShadeEffectCatalog)
    if (-not [string]::IsNullOrWhiteSpace($Category)) {
        $effects = @($effects | Where-Object { $_.Category -ieq $Category.Trim() })
    }
    if (-not [string]::IsNullOrWhiteSpace($Search)) {
        $needle = $Search.Trim()
        $effects = @($effects | Where-Object {
            $_.FriendlyName -like "*$needle*" -or $_.EffectId -like "*$needle*" -or $_.Category -like "*$needle*"
        })
    }
    return @($effects | Sort-Object Category, FriendlyName, EffectId)
}

function Resolve-TpmReShadeEffectStack {
    param([string[]]$EffectIds)
    $requested = @($EffectIds | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $catalog = @(Get-TpmReShadeEffectCatalog)
    $selected = New-Object System.Collections.Generic.List[object]
    $errors = New-Object System.Collections.Generic.List[string]
    foreach ($id in $requested) {
        $effectMatches = @($catalog | Where-Object EffectId -eq $id)
        if ($effectMatches.Count -eq 0) { [void]$errors.Add("Effect is not in the approved catalog: $id"); continue }
        $effect = $effectMatches[0]
        $selectedIds = @($selected | ForEach-Object { [string]$_.EffectId })
        if ($selectedIds -notcontains [string]$effect.EffectId) { [void]$selected.Add($effect) }
    }
    foreach ($effect in $selected) {
        foreach ($other in $selected) {
            if ($effect.EffectId -ne $other.EffectId -and ($effect.ConflictsWith -contains $other.EffectId)) {
                [void]$errors.Add("Effects conflict: $($effect.FriendlyName) and $($other.FriendlyName)")
            }
        }
    }
    $ordered = @($selected | Sort-Object { [array]::IndexOf($requested, $_.EffectId) })
    return [pscustomobject]@{
        Valid = ($errors.Count -eq 0)
        Effects = @($ordered)
        TechniqueOrder = @($ordered | ForEach-Object TechniqueName)
        Errors = @($errors | Sort-Object -Unique)
        Warning = if ($ordered.Count -gt 1) { 'This multi-effect stack requires direct TPM validation before normal-mode exposure.' } else { $null }
    }
}

function Get-TpmResolutionClassification {
    param([object]$Width, [object]$Height)
    if ($null -eq $Width -or $null -eq $Height -or [string]::IsNullOrWhiteSpace([string]$Width) -or [string]::IsNullOrWhiteSpace([string]$Height)) {
        return [pscustomobject]@{ State = 'UNKNOWN'; Width = $null; Height = $null; Advisory = 'Display resolution is unavailable; no resolution-based compatibility claim is made.' }
    }
    try {
        if ([string]$Width -notmatch '^[0-9]+$' -or [string]$Height -notmatch '^[0-9]+$') { throw 'malformed' }
        $w = [int64]$Width; $h = [int64]$Height
        if ($w -le 0 -or $h -le 0) { throw 'malformed' }
        if ($w -lt 640 -or $h -lt 480) { $state = 'KNOWN_UNUSUALLY_LOW' }
        elseif ($w -ge 3840 -or $h -ge 2160) { $state = 'KNOWN_UNUSUALLY_HIGH' }
        elseif (([double]$w / [double]$h) -ge 2.3) { $state = 'KNOWN_UNUSUALLY_WIDE' }
        else { $state = 'KNOWN_NORMAL' }
        return [pscustomobject]@{ State = $state; Width = $w; Height = $h; Advisory = if ($state -eq 'KNOWN_UNUSUALLY_LOW') { 'Display resolution is unusually low; resolution-sensitive effects may look different.' } elseif ($state -eq 'KNOWN_UNUSUALLY_HIGH') { 'Display resolution is unusually high; resolution-sensitive effects may cost more performance.' } elseif ($state -eq 'KNOWN_UNUSUALLY_WIDE') { 'Display aspect ratio is unusually wide; framing may differ.' } else { $null } }
    } catch {
        return [pscustomobject]@{ State = 'MALFORMED'; Width = $null; Height = $null; Advisory = 'Display resolution evidence is malformed; no resolution-based compatibility claim is made.' }
    }
}
function Get-TpmDisplayTopologyClassification {
    param([object[]]$Displays = @(), [string]$TargetDisplayId = '')
    if ($null -eq $Displays -or @($Displays).Count -eq 0) { return [pscustomobject]@{ State = 'UNKNOWN'; Confidence = 'UNKNOWN'; UsableDisplays = 0; TargetConfidence = 'UNKNOWN'; TargetDisplayId = $null; TargetResolution = $null; DuplicateDisplayIds = @(); Advisory = 'Display topology is unavailable; TPM will not choose a monitor.' } }
    $usable = New-Object System.Collections.Generic.List[object]
    $malformed = $false
    foreach ($display in @($Displays)) {
        if ($null -eq $display -or -not $display.PSObject.Properties['Id'] -or [string]::IsNullOrWhiteSpace([string]$display.Id)) { $malformed = $true; continue }
        $connected = if ($display.PSObject.Properties['Connected']) { [bool]$display.Connected } else { $true }
        if (-not $connected) { continue }
        $resolution = Get-TpmResolutionClassification -Width $display.Width -Height $display.Height
        if ($resolution.State -eq 'MALFORMED') { $malformed = $true; continue }
        [void]$usable.Add([pscustomobject]@{ Record = $display; Resolution = $resolution })
    }
    if ($usable.Count -eq 0) { return [pscustomobject]@{ State = if ($malformed) { 'MALFORMED' } else { 'ZERO_USABLE' }; Confidence = 'UNKNOWN'; UsableDisplays = 0; TargetConfidence = 'UNKNOWN'; TargetDisplayId = $null; TargetResolution = $null; DuplicateDisplayIds = @(); Advisory = 'No usable connected display evidence is available.' } }
    $primary = @($usable | Where-Object { $_.Record.PSObject.Properties['IsPrimary'] -and [bool]$_.Record.IsPrimary })
    $duplicateIds = @($usable | Group-Object { [string]$_.Record.Id } | Where-Object { $_.Count -gt 1 } | Select-Object -ExpandProperty Name)
    $state = 'SINGLE'
    if ($usable.Count -gt 1) {
        if ($primary.Count -gt 1 -or $malformed) { $state = 'MALFORMED' }
        elseif (@($usable | Where-Object { $_.Record.PSObject.Properties['IsMirrored'] -and [bool]$_.Record.IsMirrored }).Count -eq $usable.Count) { $state = 'MIRRORED' }
        elseif ($primary.Count -eq 0) { $state = 'MULTIPLE_NO_PRIMARY' }
        else { $state = 'MULTIPLE_PRIMARY' }
        $orientations = @($usable | ForEach-Object { if ($_.Record.PSObject.Properties['Orientation']) { [string]$_.Record.Orientation } else { '' } } | Select-Object -Unique)
        $refresh = @($usable | ForEach-Object { if ($_.Record.PSObject.Properties['RefreshRate']) { [string]$_.Record.RefreshRate } else { '' } } | Select-Object -Unique)
        $sizes = @($usable | ForEach-Object { '{0}x{1}' -f $_.Resolution.Width,$_.Resolution.Height } | Select-Object -Unique)
        if ($state -ne 'MALFORMED' -and (($orientations.Count -gt 1) -or ($refresh.Count -gt 1) -or ($sizes.Count -gt 1))) { $state = 'MULTIPLE_MIXED' }
    } elseif ($malformed) { $state = 'MALFORMED' }
    $target = $null
    $targetAmbiguous = $false
    if (-not [string]::IsNullOrWhiteSpace($TargetDisplayId)) {
        $targetMatches = @($usable | Where-Object { [string]$_.Record.Id -eq $TargetDisplayId })
        if ($targetMatches.Count -eq 1) { $target = $targetMatches[0] }
        elseif ($targetMatches.Count -gt 1) { $targetAmbiguous = $true }
    } elseif ($usable.Count -eq 1) {
        $target = $usable[0]
    }
    $targetConfidence = if ($targetAmbiguous) { 'AMBIGUOUS' } elseif ($target) { 'CONFIDENT' } elseif (-not [string]::IsNullOrWhiteSpace($TargetDisplayId)) { 'UNKNOWN' } elseif ($usable.Count -eq 1) { 'CONFIDENT' } elseif ($state -eq 'MALFORMED') { 'UNKNOWN' } else { 'AMBIGUOUS' }
    return [pscustomobject]@{ State = $state; Confidence = if ($state -eq 'MALFORMED') { 'UNKNOWN' } elseif ($usable.Count -eq 1 -or $primary.Count -eq 1) { 'KNOWN' } else { 'AMBIGUOUS' }; UsableDisplays = $usable.Count; TargetConfidence = $targetConfidence; TargetDisplayId = if ($target) { [string]$target.Record.Id } else { $null }; TargetResolution = if ($target) { $target.Resolution } else { $null }; DuplicateDisplayIds = $duplicateIds; Advisory = if ($targetAmbiguous) { 'The target display identity is duplicated; TPM will not choose a monitor.' } elseif ($targetConfidence -eq 'AMBIGUOUS') { 'The game target display is not evidenced; TPM will not choose a monitor.' } elseif ($state -eq 'MALFORMED') { 'Display topology evidence is malformed; TPM will not make a suitability claim.' } else { $null } }
}

function Get-TpmReShadeEligibilityEvidence {
    param([object]$Environment = $null, [object]$GameContext = $null, [string]$StagingPath = '')
    $e = if ($Environment) { $Environment } else { [pscustomobject]@{} }
    $g = if ($GameContext) { $GameContext } else { [pscustomobject]@{} }
    $adapter = $null
    if ($null -ne $e.ActiveAdapterIndex) { $adapter = @($e.Adapters | Where-Object { $_.AdapterIndex -eq $e.ActiveAdapterIndex })[0] }
    $volumes = @($e.Volumes)
    $staging = @($volumes | Where-Object { $_.Path -eq $StagingPath })[0]
    $free = if ($staging) { $staging.FreeBytes } else { $null }
    $resolution = Get-TpmResolutionClassification -Width $e.RenderWidth -Height $e.RenderHeight
    $topology = if ($e.PSObject.Properties['DisplayTopology'] -and $e.DisplayTopology) { if ($e.DisplayTopology.PSObject.Properties['State']) { $e.DisplayTopology } else { Get-TpmDisplayTopologyClassification -Displays @($e.DisplayTopology.Displays) -TargetDisplayId ([string]$e.DisplayTopology.TargetDisplayId) } } else { $null }

    # RAM pressure is intentionally not inferred from a fixed threshold here; the shared layer reports bytes and confidence only.
    return [pscustomobject]@{
        ActiveGpuKnown = ($null -ne $adapter -and $e.ActiveGpuConfidence -ne 'UNKNOWN'); ActiveGpuConfidence = if ($e.ActiveGpuConfidence) { $e.ActiveGpuConfidence } else { 'UNKNOWN' }
        ActiveGpuModel = if ($adapter) { $adapter.Name } else { $null }; IsIntegrated = $null; IsDiscrete = $null
        DedicatedVramBytes = if ($adapter) { $adapter.DedicatedMemoryBytes } else { $null }; SharedGpuMemoryBytes = $null; GraphicsCapability = $null; DriverVersion = if ($adapter) { $adapter.DriverVersion } else { $null }; MultiGpuAmbiguous = $e.MultiGpuAmbiguous
        CpuModel = $e.CpuModel; PhysicalCoreCount = $e.PhysicalCoreCount; LogicalProcessorCount = $e.LogicalProcessorCount; CpuLoadPercent = $null; CpuLoadConfidence = 'UNKNOWN'
        InstalledRamBytes = $e.InstalledRamBytes; AvailableRamBytes = $e.AvailableRamBytes; RamPressure = $false; MemoryEvidenceConfidence = $e.MemoryEvidenceConfidence
        RequiredWorkingBytes = $null; StagingFreeBytes = $free; BackupFreeBytes = $null; CacheFreeBytes = $null; TargetVolumeFreeBytes = $null
        RenderWidth = $resolution.Width; RenderHeight = $resolution.Height; ResolutionClass = $resolution.State; ResolutionConfidence = if ($resolution.State -eq 'UNKNOWN' -or $resolution.State -eq 'MALFORMED') { $resolution.State } else { if ($e.ResolutionConfidence) { $e.ResolutionConfidence } else { 'KNOWN' } }; RefreshRate = $e.RefreshRate; HdrState = $null
        PowerSavingActive = $e.PowerSavingActive; BatteryPowered = $e.BatteryPowered; ThermalConcern = $null; GpuLoadPercent = $null; TemporaryLoadConfidence = 'UNKNOWN'
        RenderingApi = $g.RenderingApi; Bitness = $g.Bitness; GameCompatibilityState = $g.GameCompatibilityState; ContextConfidence = $g.ContextConfidence; DisplayTopology = $topology
    }
}
function Get-TpmReShadeStorageEvidence {
    param([object]$DeploymentContext = $null)
    $context = if ($DeploymentContext) { $DeploymentContext } else { [pscustomobject]@{} }
    $roles = @('StagingPath','BackupPath','CachePath','TargetPath')
    $groups = [ordered]@{}
    $roleBytes = if ($context.PSObject.Properties['RoleBytes']) { $context.RoleBytes } else { $null }
    $rolePaths = if ($context.PSObject.Properties['RolePaths']) { $context.RolePaths } else { $null }
    foreach ($role in $roles) {
        $path = [string]$context.$role
        $normalized = ([string]$role).ToUpperInvariant() -replace 'PATH$',''
        if ([string]::IsNullOrWhiteSpace($path) -and $rolePaths) {
            $pathProperty = $rolePaths.PSObject.Properties[$normalized]
            if ($pathProperty) { $path = [string]$pathProperty.Value }
        }
        $demand = Get-TpmReShadeRoleDemandValue -RoleBytes $roleBytes -Role $role
        if ([string]::IsNullOrWhiteSpace($path)) { continue }
        try {
            $root = [IO.Path]::GetPathRoot([IO.Path]::GetFullPath($path)).ToUpperInvariant()
            if (-not $groups.Contains($root)) {
                $free = $null
                try { $drive = Get-PSDrive -Name $root.TrimEnd('\').TrimEnd(':') -ErrorAction Stop; if ($null -ne $drive.Free) { $free = [int64]$drive.Free } } catch { $free = $null }
                $groups[$root] = [pscustomobject]@{ Root = $root; FreeBytes = $free; RequiredBytes = [int64]0; Roles = New-Object System.Collections.Generic.List[string]; DemandByRole = [ordered]@{} }
            }
            if (@($groups[$root].Roles) -notcontains $role) { [void]$groups[$root].Roles.Add($role) }
            $groups[$root].RequiredBytes = [int64]$groups[$root].RequiredBytes + $demand
            $groups[$root].DemandByRole[$normalized] = $demand
        } catch {
            $unknownRoot = 'UNKNOWN:' + $normalized
            if (-not $groups.Contains($unknownRoot)) { $groups[$unknownRoot] = [pscustomobject]@{ Root = $unknownRoot; FreeBytes = $null; RequiredBytes = [int64]0; Roles = New-Object System.Collections.Generic.List[string]; DemandByRole = [ordered]@{} } }
            if (@($groups[$unknownRoot].Roles) -notcontains $role) { [void]$groups[$unknownRoot].Roles.Add($role) }
            $groups[$unknownRoot].RequiredBytes = [int64]$groups[$unknownRoot].RequiredBytes + $demand
            $groups[$unknownRoot].DemandByRole[$normalized] = $demand
        }
    }
    $required = if ($context.PSObject.Properties['RequiredWorkingBytes'] -and $null -ne $context.RequiredWorkingBytes) { [int64]$context.RequiredWorkingBytes } else { $null }
    return [pscustomobject]@{ RequiredWorkingBytes = $required; RoleBytes = $roleBytes; Volumes = @($groups.Values) }
}

function Get-TpmReShadeEligibilityFromSystem {
    param([Parameter(Mandatory)][string[]]$EffectIds, [object]$GameContext = $null, [string]$StagingPath = '')
    $stack = Resolve-TpmReShadeEffectStack -EffectIds $EffectIds
    $environment = Get-TpmHardwareEnvironmentEvidence -RefreshDynamic -VolumePaths @($StagingPath)
    $evidence = Get-TpmReShadeEligibilityEvidence -Environment $environment -GameContext $GameContext -StagingPath $StagingPath
    return Get-TpmReShadeEligibility -Stack $stack -Evidence $evidence
}

function Get-TpmReShadeEligibility {
    param([Parameter(Mandatory)]$Stack, [Parameter(Mandatory)]$Evidence)
    $reasons = New-Object System.Collections.Generic.List[string]
    $classes = @($Stack.Effects | ForEach-Object PerformanceClass)
    $renderWidth = if ($Evidence.PSObject.Properties['RenderWidth']) { $Evidence.RenderWidth } else { $null }
    $renderHeight = if ($Evidence.PSObject.Properties['RenderHeight']) { $Evidence.RenderHeight } else { $null }
    $resolutionClass = if ($Evidence.PSObject.Properties['ResolutionClass'] -and $Evidence.ResolutionClass) { $Evidence.ResolutionClass } else { (Get-TpmResolutionClassification -Width $renderWidth -Height $renderHeight).State }
    if (-not $Stack.Valid) { [void]$reasons.Add('STACK_CONFLICT') }
    if ($Stack.Warning) { [void]$reasons.Add('STACK_UNVALIDATED') }
    if ($Evidence.ActiveGpuConfidence -eq 'UNKNOWN') { [void]$reasons.Add('ACTIVE_GPU_UNKNOWN') }
    if ($resolutionClass -eq 'UNKNOWN') { [void]$reasons.Add('RESOLUTION_UNKNOWN') }
    elseif ($resolutionClass -eq 'MALFORMED') { [void]$reasons.Add('RESOLUTION_MALFORMED') }
    if ($Evidence.RamPressure -eq $true) { [void]$reasons.Add('RAM_PRESSURE') }
    $displayTopology = if ($Evidence.PSObject.Properties['DisplayTopology']) { $Evidence.DisplayTopology } else { $null }
    if ($displayTopology -and $displayTopology.TargetConfidence -in @('UNKNOWN','AMBIGUOUS')) { [void]$reasons.Add('DISPLAY_TARGET_AMBIGUOUS') }
    $space = Test-TpmReShadeWorkingSpace -Evidence $Evidence
    if (@($space.InsufficientVolumes).Count -gt 0) { [void]$reasons.Add('DISK_SPACE_LOW') }
    elseif (@($space.UnknownVolumes).Count -gt 0) { [void]$reasons.Add('DISK_SPACE_UNKNOWN') }
    $powerSavingActive = if ($Evidence.PSObject.Properties['PowerSavingActive']) { $Evidence.PowerSavingActive } else { $false }
    if ($powerSavingActive -eq $true) { [void]$reasons.Add('POWER_SAVING_ACTIVE') }
    if ($resolutionClass -eq 'KNOWN_UNUSUALLY_HIGH' -and ($classes -contains 'HIGH')) { [void]$reasons.Add('RESOLUTION_HIGH') }
    $status = 'GOOD_MATCH'
    if ($reasons -contains 'STACK_CONFLICT' -or $reasons -contains 'DISK_SPACE_LOW') { $status = 'NOT_RECOMMENDED' }
    elseif ($reasons -contains 'RAM_PRESSURE' -or $reasons -contains 'RESOLUTION_HIGH' -or $reasons -contains 'POWER_SAVING_ACTIVE') { $status = 'PERFORMANCE_RISK' }
    elseif ($reasons -contains 'ACTIVE_GPU_UNKNOWN' -or $reasons -contains 'RESOLUTION_UNKNOWN' -or $reasons -contains 'RESOLUTION_MALFORMED' -or $reasons -contains 'DISK_SPACE_UNKNOWN' -or $reasons -contains 'DISPLAY_TARGET_AMBIGUOUS') { $status = 'UNKNOWN' }
    elseif ($classes -contains 'HIGH') { $status = 'LIKELY_OK' }
    $fallback = if ($status -eq 'NOT_RECOMMENDED') { @($Stack.Effects | Select-Object -First 1 | ForEach-Object FallbackBehavior)[0] } else { $null }
    return [pscustomobject]@{ Status = $status; Reasons = @($reasons); HardwareConfidence = if ($Evidence.ActiveGpuConfidence -eq 'UNKNOWN') { 'UNKNOWN' } else { 'KNOWN' }; FallbackProfileId = $fallback; Explanation = switch ($status) { 'GOOD_MATCH' { 'Good match for your PC.' }; 'LIKELY_OK' { 'Should run reliably, but this profile has higher processing cost.' }; 'PERFORMANCE_RISK' { 'This profile may reduce performance under current system conditions.' }; 'NOT_RECOMMENDED' { 'This profile is not recommended for the current system conditions.' }; default { 'Hardware performance could not be verified.' } } }
}

function Test-TpmReShadeWorkingSpace {
    param([Parameter(Mandatory)]$Evidence)
    $requiredValue = if ($Evidence.PSObject.Properties['RequiredWorkingBytes']) { $Evidence.RequiredWorkingBytes } else { $null }
    $required = [int64]$(if ($requiredValue) { $requiredValue } else { 64MB })
    $checks = @(
        [pscustomobject]@{ Name = 'staging'; Free = if ($Evidence.PSObject.Properties['StagingFreeBytes']) { $Evidence.StagingFreeBytes } else { $null } }
        [pscustomobject]@{ Name = 'backup'; Free = if ($Evidence.PSObject.Properties['BackupFreeBytes']) { $Evidence.BackupFreeBytes } else { $null } }
        [pscustomobject]@{ Name = 'cache'; Free = if ($Evidence.PSObject.Properties['CacheFreeBytes']) { $Evidence.CacheFreeBytes } else { $null } }
        [pscustomobject]@{ Name = 'target'; Free = if ($Evidence.PSObject.Properties['TargetVolumeFreeBytes']) { $Evidence.TargetVolumeFreeBytes } else { $null } }
    )
    $unknown = @($checks | Where-Object { $null -eq $_.Free })
    $insufficient = @($checks | Where-Object { $_.Free -is [int64] -and $_.Free -lt $required })
    $insufficientNames = @($insufficient | ForEach-Object { $_.Name })
    $unknownNames = @($unknown | ForEach-Object { $_.Name })
    return [pscustomobject]@{ Sufficient = ($insufficientNames.Count -eq 0 -and $unknownNames.Count -eq 0); RequiredBytes = $required; InsufficientVolumes = $insufficientNames; UnknownVolumes = $unknownNames }
}

function Resolve-ReShadeCustomPresetPath {
    param([string]$InputPath)
    if ([string]::IsNullOrWhiteSpace($InputPath)) { return $null }
    try {
        $candidate = $InputPath.Trim()
        if ([System.IO.Path]::GetExtension($candidate) -ine '.ini') { return $null }
        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) { return $null }
        return $candidate
    } catch {
        return $null
    }
}

function Invoke-ReShadeUpdateIfAvailable {
    param([string]$SourceDll, [string]$SourceDll32, [string]$InstalledVersion)
    if ([string]::IsNullOrWhiteSpace($InstalledVersion)) { return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll; SourceDll32 = $SourceDll32 } }
    $latest = Get-ReShadeLatestVersion
    if (-not $latest -or [version]$latest -le [version]$InstalledVersion) {
        return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll; SourceDll32 = $SourceDll32 }
    }
    Write-Host '  ReShade update available' -ForegroundColor Yellow
    Write-Host ("  Installed: {0}" -f $InstalledVersion)
    Write-Host ("  Available: {0}" -f $latest)
    $choice = (Read-HostSafe '  [Y] Update now  [N] Keep current version  Choice, default Y' -Default 'Y').Trim().ToUpper()
    if ($choice -ne 'Y') { Write-Log ("ReShade update declined: installed={0}; available={1}" -f $InstalledVersion, $latest); return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll; SourceDll32 = $SourceDll32 } }
    $url = Get-ReShadeSetupDownloadUrl -Version $latest
    if (-not $url) { Write-Host '  ReShade update could not be started safely; keeping the installed version.' -ForegroundColor Yellow; return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll; SourceDll32 = $SourceDll32 } }
    $cacheDir = Join-Path $PSScriptRoot 'ReShade'
    $setupPath = Join-Path $cacheDir ("ReShade_Setup_{0}.exe" -f $latest)
    try {
        [void][IO.Directory]::CreateDirectory($cacheDir)
        if (-not (Invoke-TpmDownload -DownloadUrl $url -DestinationPath $setupPath -Label 'ReShadeSetup' -Version $latest)) { throw 'The official download did not complete.' }
        $signature = Test-ReShadeSetupTrustedSignature -Path $setupPath
        if (-not $signature.Trusted) { throw 'The downloaded installer did not pass the trusted ReShade signature check.' }
        Expand-ReShadeSelfExtractingArchive -SetupExePath $setupPath -DestDir $cacheDir
        $newDll = Join-Path $cacheDir 'ReShade64.dll'
        $newDll32 = Join-Path $cacheDir 'ReShade32.dll'
        if (-not (Test-Path -LiteralPath $newDll -PathType Leaf)) { throw 'The updated 64-bit DLL was not found after extraction.' }
        Write-Host ("  ReShade {0} downloaded and verified." -f $latest) -ForegroundColor Green
        Write-Log ("ReShade update applied to setup source: installed={0}; available={1}" -f $InstalledVersion, $latest)
        return [pscustomobject]@{ Updated = $true; SourceDll = $newDll; SourceDll32 = $(if (Test-Path -LiteralPath $newDll32 -PathType Leaf) { $newDll32 } else { $SourceDll32 }) }
    } catch {
        Write-Host ("  ReShade update failed safely: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
        Write-Log ("ReShade update failed: {0}" -f $_.Exception.Message)
        return [pscustomobject]@{ Updated = $false; SourceDll = $SourceDll; SourceDll32 = $SourceDll32 }
    }
}

function Invoke-ReShadeSetup {
    param(
        [string]$UserProfilesDir,
        [string]$SourceDll,      # 64-bit DLL path (caller guarantees it exists)
        [string]$SourceDll32,    # 32-bit DLL path (optional; $null = skip x86 games)
        [string]$ConfigPath,
        [string]$TpRoot,
        [string]$Mode,
        [string]$ZipSource,
        [string]$GamesInstallFolder,
        [bool]$RetroBat,
        [string]$HsDataPath
    )

    if ([string]::IsNullOrWhiteSpace($SourceDll) -or -not (Test-Path -LiteralPath $SourceDll -PathType Leaf)) {
        Write-Host '  ReShade setup stopped: a valid 64-bit ReShade source DLL was not found.' -ForegroundColor Yellow
        Write-Log 'ReShade setup blocked: SourceDll was empty or did not resolve to a file.'
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'SOURCE_DLL_UNAVAILABLE' }
    }

    # Version check
    $bVer = $null
    try {
        $vi   = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($SourceDll)
        $bVer = "$($vi.FileMajorPart).$($vi.FileMinorPart).$($vi.FileBuildPart)"
        Write-Host ("  ReShade (64-bit) : {0}" -f $bVer) -ForegroundColor DarkGray
    } catch {}
    if ($SourceDll32 -and (Test-Path -LiteralPath $SourceDll32)) {
        try {
            $vi32   = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($SourceDll32)
            $bVer32 = "$($vi32.FileMajorPart).$($vi32.FileMinorPart).$($vi32.FileBuildPart)"
            Write-Host ("  ReShade (32-bit) : {0}" -f $bVer32) -ForegroundColor DarkGray
        } catch {}
    } else {
        Write-Host "  ReShade (32-bit) : not found -- 32-bit games will be skipped" -ForegroundColor DarkGray
    }

    # Authenticode check on the DLL(s) before deploying them anywhere.
    foreach ($dllCheck in @(
        @{ Path = $SourceDll;   Label = "64-bit" },
        @{ Path = $SourceDll32; Label = "32-bit" }
    )) {
        if (-not $dllCheck.Path -or -not (Test-Path -LiteralPath $dllCheck.Path)) { continue }
        $sigResult = Test-ReShadeDllSignature -Path $dllCheck.Path
        $sha256    = $null
        try { $sha256 = (Get-FileHash -LiteralPath $dllCheck.Path -Algorithm SHA256).Hash } catch {}
        Write-Log ("ReShade ({0}): signature={1} signer='{2}' sha256={3}" -f $dllCheck.Label, $sigResult.Status, $sigResult.Signer, $sha256)
        if ($sigResult.Status -eq 'Valid') {
            Write-Host ("  ReShade ($($dllCheck.Label)) source verified.") -ForegroundColor DarkGray
        } else {
            Write-Host ("  ReShade ($($dllCheck.Label)) source needs review before use.") -ForegroundColor Yellow
        }
    }
    $updateResult = Invoke-ReShadeUpdateIfAvailable -SourceDll $SourceDll -SourceDll32 $SourceDll32 -InstalledVersion $bVer
    if ($updateResult.Updated) {
        $SourceDll = $updateResult.SourceDll
        $SourceDll32 = $updateResult.SourceDll32
        try {
            $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($SourceDll)
            $bVer = "$($vi.FileMajorPart).$($vi.FileMinorPart).$($vi.FileBuildPart)"
        } catch {}
    }


    $gallery = @(Get-TpmReShadeProfileGallery)
    Write-Host "  Preview gallery (illustrative, local synthetic scenes)" -ForegroundColor DarkCyan
    foreach ($item in $gallery) {
        $previewText = if ($item.PreviewAvailable) { 'preview available' } else { 'preview unavailable; selection still works' }
        Write-Host ("    {0}: {1} [{2}]" -f $item.FriendlyName, $item.Description, $previewText) -ForegroundColor DarkGray
    }
    $favoriteState = Read-TpmReShadeState
    $favoriteProfiles = @()
    foreach ($favorite in @($favoriteState.Favorites)) {
        $favoriteProfile = Get-TpmReShadeProfile -ProfileId $favorite.ProfileId
        if ($favoriteProfile) {
            try { $favoriteVariant = Resolve-TpmReShadeIntensityVariant -ProfileDefinition $favoriteProfile -VariantId $favorite.VariantId; $favoriteProfiles += [pscustomobject]@{ Profile = $favoriteProfile; VariantId = $favoriteVariant.VariantId } } catch {}
        }
    }
    $favoriteItems = @($favoriteProfiles | ForEach-Object { $_.Profile.FriendlyName })
    if ($favoriteItems.Count -gt 0) {
        Write-Host ("  Favorites: " + ($favoriteItems -join ', ')) -ForegroundColor DarkCyan
        Write-Host "  Choose F at the profile prompt to select a favorite." -ForegroundColor DarkCyan
    }

    # Curated profile selection is the normal path. Advanced custom .ini remains opt-in.
    Write-Host ""
    Write-Host "  Visual profile" -ForegroundColor Cyan
    Write-Host "    1) Clean & Sharp  (Recommended)" -ForegroundColor White
    Write-Host "    2) Classic Arcade CRT" -ForegroundColor White
    Write-Host "    3) Vivid Arcade" -ForegroundColor White
    Write-Host "    4) Enhanced Arcade" -ForegroundColor White
    Write-Host "    5) Original" -ForegroundColor White
    if ($favoriteProfiles.Count -gt 0) { Write-Host "    F) Choose a favorite profile" -ForegroundColor White }
    $profilePick = (Read-HostSafe "  Choose 1-5$(if($favoriteProfiles.Count -gt 0){' or F'}) (default 1)").Trim()
    $profileMap = @{ '1' = 'CleanSharp'; '2' = 'ClassicCrt'; '3' = 'Vivid'; '4' = 'EnhancedArcade'; '5' = 'Original' }
    if ($profilePick -match '^[Ff]$' -and $favoriteProfiles.Count -gt 0) {
        for ($favoriteIndex = 0; $favoriteIndex -lt $favoriteProfiles.Count; $favoriteIndex++) { Write-Host ("      {0}) {1}" -f ($favoriteIndex + 1), $favoriteProfiles[$favoriteIndex].Profile.FriendlyName) -ForegroundColor DarkGray }
        $favoritePick = (Read-HostSafe "  Favorite number (blank = Clean & Sharp)").Trim()
        if ($favoritePick -match '^\d+$' -and [int]$favoritePick -ge 1 -and [int]$favoritePick -le $favoriteProfiles.Count) {
            $selectedProfile = $favoriteProfiles[[int]$favoritePick - 1].Profile
        } else { $selectedProfile = Get-TpmReShadeProfile -ProfileId 'CleanSharp' }
    } else {
        if ([string]::IsNullOrWhiteSpace($profilePick)) { $profilePick = '1' }
        if (-not $profileMap.ContainsKey($profilePick)) { $profilePick = '1' }
        $selectedProfile = Get-TpmReShadeProfile -ProfileId $profileMap[$profilePick]
    }
    $presetPath = $null
    $generatedPresetPath = $null
    if ($selectedProfile.ProfileId -ne 'Original') {
        $generatedPresetPath = Join-Path ([System.IO.Path]::GetTempPath()) ('TPM-ReShade-' + [guid]::NewGuid().ToString('N') + '.ini')
        try {
            [System.IO.File]::WriteAllText($generatedPresetPath, (New-TpmReShadePresetContent -ProfileDefinition $selectedProfile), (New-Object System.Text.UTF8Encoding $false))
            $presetPath = $generatedPresetPath
        } catch {
            Write-Log "ReShade: failed to generate selected profile preset -- $_"
            Write-Host "  Could not generate the selected profile. Continuing with Original." -ForegroundColor Yellow
        }
    }
    Write-Host ("  Selected: {0}" -f $selectedProfile.FriendlyName) -ForegroundColor DarkGray
    $previewFailureShown = $false
    do {
        $previewWindowResult = Show-TpmReShadePreviewWindow -ProfileDefinition $selectedProfile -Mode 'Split' -Show
        if ($previewWindowResult.Available) { break }
        if (-not $previewFailureShown) {
            Write-Host "  ReShade preview could not open." -ForegroundColor Yellow
            Write-Host "  The visual preview is unavailable, but text-only setup remains available." -ForegroundColor Yellow
            $previewFailureShown = $true
        }
        Write-Host "  [R] Retry preview  [T] Text-only setup  [S] Skip ReShade setup  [B] Back  [D] Details"
        $previewChoice = (Read-HostSafe "  Choice (R/T/S/B/D)" -Default 'R').Trim().ToUpper()
        if ($previewChoice -eq 'D') {
            Write-Host ("  Preview reason: {0}" -f $previewWindowResult.Reason) -ForegroundColor DarkGray
            Write-Log ("ReShade preview details: reason={0}; root={1}" -f $previewWindowResult.Reason, $previewWindowResult.PreviewRoot)
        } elseif ($previewChoice -in @('S', 'B')) {
            return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'PREVIEW_CANCELLED' }
        } elseif ($previewChoice -eq 'T') {
            break
        } elseif ($previewChoice -notin @('R', '')) {
            Write-Host "  Enter R, T, S, B, or D." -ForegroundColor Yellow
        }
    } while ($true)
    $customPresetChoice = (Read-HostSafe ("  Use the selected ReShade profile?`n  ({0} will be applied. Choose Custom only if you already have your own ReShade .ini preset.)`n`n  [Y] Yes, use {0}  [C] Custom preset  [B] Back`n`n  Choice, default Y" -f $selectedProfile.FriendlyName) -Default 'Y').Trim().ToUpper()
    if ($customPresetChoice -eq 'C') {
        $pInp = Read-PathWithBrowse "  Path to your ReShade preset (.ini) file" -Mode File -FileFilter "ReShade preset (*.ini)|*.ini|All files (*.*)|*.*"
        $customPath = Resolve-ReShadeCustomPresetPath -InputPath $pInp
        if ($customPath) { $presetPath = $customPath; Write-Host "  Custom preset selected." -ForegroundColor DarkGray }
    } elseif ($customPresetChoice -eq 'B') {
        return
    }

    # Per-game preset overrides: ReShadePresets\<ProfileCode>.ini always wins
    # over the global choice above for that one game. Same convention as
    # CustomThumbnails\<ProfileCode>.png (Invoke-ThumbnailDownload) -- file
    # name is the profile code, validated against registered profiles, with
    # a WRONG NAME warning for typos instead of a silent no-op.
    $reShadePresetsDir = Join-Path $PSScriptRoot "ReShadePresets"
    if (Test-Path -LiteralPath $reShadePresetsDir) {
        $presetFiles = @(Get-ChildItem -LiteralPath $reShadePresetsDir -Filter "*.ini" -File -ErrorAction SilentlyContinue)
        if ($presetFiles.Count -gt 0) {
            $knownPresetCodes = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Directory.Name -ne "FullBackup" } |
                ForEach-Object { [void]$knownPresetCodes.Add($_.BaseName) }
            foreach ($pfile in $presetFiles) {
                $code = [System.IO.Path]::GetFileNameWithoutExtension($pfile.Name)
                if (-not $knownPresetCodes.Contains($code)) {
                    Write-Host ("  WRONG NAME: ReShadePresets\{0}" -f $pfile.Name) -ForegroundColor Yellow
                    Write-Host ("             '{0}' does not match any registered game profile code." -f $code) -ForegroundColor Yellow
                    Write-Host "             Check TeknoParrot-Manager-controls.txt for the correct" -ForegroundColor Yellow
                    Write-Host "             name, rename the file, then re-run. File will be ignored." -ForegroundColor Yellow
                    Write-Log "ReShade: per-game preset $($pfile.Name) -- no matching profile code, ignored."
                }
            }
        }
    }

    # Game selection
    Write-Host ""
    Write-Host "  Which games should get ReShade?" -ForegroundColor Cyan
    Write-Host "  You can run setup again later to add or change individual games." -ForegroundColor DarkCyan
    $selectedGames = @(Select-RegisteredGamesInteractive -UserProfilesDir $UserProfilesDir)
    if ($selectedGames.Count -eq 0) {
        Write-Host "  No games selected. ReShade setup cancelled." -ForegroundColor Yellow
        Write-Log "ReShade setup: cancelled -- no games selected."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'NO_GAMES_SELECTED' }
    }
    $bulkApply = $false
    $allRegisteredGames = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue | Where-Object { $_.Directory.Name -ne 'FullBackup' })
    if ($selectedGames.Count -gt 1) {
        $bulkChoice = ''
        do {
            Write-Host ("  Apply {0} to all {1} selected games?" -f $selectedProfile.FriendlyName, $selectedGames.Count) -ForegroundColor Cyan
            Write-Host '  [Y] Yes, apply to all'
            Write-Host '  [S] Select games one by one'
            Write-Host '  [B] Back'
            Write-Host '  [D] Details'
            $bulkChoice = (Read-HostSafe '  Choice, default Y' -Default 'Y').Trim().ToUpper()
            if ($bulkChoice -eq 'D') { Write-Host ("  Profile: {0} -- {1}" -f $selectedProfile.FriendlyName, $selectedProfile.Description) -ForegroundColor DarkGray }
            elseif ($bulkChoice -notin @('Y', 'S', 'B')) { Write-Host '  Invalid choice. Choose Y, S, B, or D.' -ForegroundColor Yellow }
        } while ($bulkChoice -notin @('Y', 'S', 'B'))
        if ($bulkChoice -eq 'B') { return }
        $bulkApply = ($bulkChoice -eq 'Y')
    }

    $rememberedSelections = @{}
    $restoreSelections = @{}
    if (-not $bulkApply) {
    foreach ($pf in $selectedGames) {
        $options = Get-TpmReShadeChooserOptions -GameId $pf.BaseName
        if ($options.Restore.Found -and $options.Restore.Valid) {
            Write-Host ("  R) Reapply previous trusted profile for {0}: {1}" -f $pf.BaseName, $options.Restore.Profile.FriendlyName) -ForegroundColor DarkCyan
            $restoreAnswer = (Read-HostSafe ("  Reapply {0} for this game? (Y/N, default N)" -f $options.Restore.Profile.FriendlyName)).Trim()
            if ($restoreAnswer -match '^(Y|y)$') { $restoreSelections[$pf.BaseName] = $options.Restore }
        } elseif ($options.Restore.Found) {
            Write-Host ("  Previous profile for {0} is unavailable ({1}); choose a fresh profile." -f $pf.BaseName, $options.Restore.Reason) -ForegroundColor Yellow
        }
        if ($options.Remembered.Found -and $options.Remembered.Valid) {
            Write-Host ("  Remembered for {0}: {1}" -f $pf.BaseName, $options.Remembered.Profile.FriendlyName) -ForegroundColor DarkCyan
            if (-not $restoreSelections.ContainsKey($pf.BaseName)) {
                $rememberAnswer = (Read-HostSafe ("  Use remembered {0} for this game? (Y/N, default N)" -f $options.Remembered.Profile.FriendlyName)).Trim()
                if ($rememberAnswer -match '^(Y|y)$') { $rememberedSelections[$pf.BaseName] = $options.Remembered }
            }
        } elseif ($options.Remembered.Found) {
            Write-Host ("  Saved profile for {0} needs reselection." -f $pf.BaseName) -ForegroundColor Yellow
        }
    }
    }

    # Deploy
    Write-Host ""
    Write-Host ("  Installing ReShade into {0} game folder(s)..." -f $selectedGames.Count) -ForegroundColor Cyan
    $deployed = 0; $skipped = 0; $protected = 0; $errors = 0; $presetOverrides = 0
    $reShadeCacheRoot = Join-Path $PSScriptRoot 'ReShade\Cache'

    foreach ($pf in $selectedGames) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { $skipped++; continue }

            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { $skipped++; continue }

            $gamePath = $gpNode.InnerText.Trim()
            if (-not (Test-Path -LiteralPath $gamePath)) {
                Write-Host ("    {0}: game path not found -- skipped" -f $pf.BaseName) -ForegroundColor DarkGray
                $skipped++; continue
            }
            $exeDir = [System.IO.Path]::GetDirectoryName($gamePath)
            if ([string]::IsNullOrWhiteSpace($exeDir)) {
                Write-Host ("    {0}: invalid game path (no directory component) -- skipped" -f $pf.BaseName) -ForegroundColor Yellow
                $skipped++; continue
            }
            $ownershipPath = Get-TpmReShadeProfileOwnershipPath -GameId $pf.BaseName
            if ($restoreSelections.ContainsKey($pf.BaseName)) {
                $restoreResult = Restore-TpmReShadeProfile -HistoryEntry $restoreSelections[$pf.BaseName].HistoryEntry -CacheRoot $reShadeCacheRoot -OwnershipRoot $ownershipPath -GamePath $gamePath -Doc $doc -SourceDll $SourceDll -SourceDll32 $SourceDll32 -GameId $pf.BaseName -StateRoot ''
                if (-not $restoreResult.Succeeded) { throw ("reapply rejected: {0}" -f $restoreResult.Reason) }
                $restoreNote = if ($restoreResult.PresetApplied) { '  (preset: generated)' } else { '' }
                Write-Host ("    {0}  [{1}]{2}  reapplied previous trusted profile" -f $pf.BaseName, $restoreResult.DllName, $restoreNote) -ForegroundColor Green
                Write-Log "ReShade: reapplied $($pf.BaseName) -> $($restoreResult.TargetDir) [$($restoreResult.DllName)]$restoreNote"
                $deployed++
                continue
            }
            $profileForGame = $selectedProfile
            $canonicalForGame = $false
            if ($rememberedSelections.ContainsKey($pf.BaseName)) {
                $profileForGame = $rememberedSelections[$pf.BaseName].Profile
                $canonicalForGame = $true
            }
            $perGamePreset = Join-Path $reShadePresetsDir ($pf.BaseName + '.ini')
            $presetForGame = if ($canonicalForGame) { $null } else { $presetPath }
            $profileDeployment = Install-TpmReShadeProfileDeployment -ProfileDefinition $profileForGame -GamePath $gamePath -Doc $doc -SourceDll $SourceDll -SourceDll32 $SourceDll32 -PresetPath $presetForGame -PerGamePresetPath $perGamePreset -CacheRoot $reShadeCacheRoot -OwnershipPath $ownershipPath -CanonicalPreset:$canonicalForGame
            if (-not $profileDeployment.Succeeded) {
                if ($profileDeployment.Reason -eq 'USER_OWNED_CONTENT_PRESERVED') { $protected++; Write-Log "ReShade: protected existing user-owned files for $($pf.BaseName)"; continue }
                if ($profileDeployment.State -in @('MISSING_32BIT_DLL','UNSUPPORTED_ARCHITECTURE')) { $skipped++; continue }
                throw ("profile deployment rejected: {0}" -f $profileDeployment.Reason)
            }
            if (-not $profileDeployment.ApiDetected) { Write-Host ("    {0}: graphics API not detected, defaulting to dxgi.dll" -f $pf.BaseName) -ForegroundColor Yellow }
            $presetSource = $profileDeployment.PresetSource
            if ($presetSource -eq 'per-game') { $presetOverrides++ }
            $presetNote = if ($presetSource) { "  (preset: $presetSource)" } else { "" }
            Write-Host ("    {0}  [{1}]{2}" -f $pf.BaseName, $profileDeployment.DllName, $presetNote) -ForegroundColor Green
            Write-Log "ReShade: $($pf.BaseName) -> $($profileDeployment.TargetDir) [$($profileDeployment.DllName)]$presetNote"
            $deployed++
            try { Add-TpmReShadeProfileHistory -GameId $pf.BaseName -ProfileDefinition $profileForGame -StateRoot '' | Out-Null } catch { Write-Log "ReShade: history record failed for $($pf.BaseName) -- $_" }
        } catch {
            Write-Host ("    FAILED {0}: {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "ReShade: FAILED $($pf.BaseName) -- $_"
            $errors++
        }
    }

    Write-Host ""
    Write-Host ("  Installed : {0} game(s)" -f $deployed) -ForegroundColor Green
    if ($presetOverrides -gt 0) {
        Write-Host ("  Per-game presets applied : {0}" -f $presetOverrides) -ForegroundColor Cyan
    }
    if ($skipped -gt 0) {
        Write-Host ("  Skipped   : {0}  (path not found, 32-bit DLL missing, or unsupported architecture)" -f $skipped) -ForegroundColor DarkGray
    }
    if ($protected -gt 0) {
        Write-Host ("  Protected : {0}  (existing ReShade files were kept unchanged)" -f $protected) -ForegroundColor Yellow
    }
    if ($errors -gt 0) {
        Write-Host ("  Errors    : {0}  -- see TeknoParrot-Manager.log for details" -f $errors) -ForegroundColor Red
    }
    Write-Host ""
    Write-Host "  To turn effects on/off: launch a game and press the  Home  key." -ForegroundColor Cyan
    Write-Host "  TPM does not remove an unowned ReShade hook automatically." -ForegroundColor DarkCyan
    Write-Host "  Existing or changed files need advanced troubleshooting review." -ForegroundColor DarkCyan
    Write-Log ("ReShade setup: Installed={0} Protected={1} Skipped={2} Errors={3} PresetOverrides={4}" -f $deployed, $protected, $skipped, $errors, $presetOverrides)
    if ($generatedPresetPath -and (Test-Path -LiteralPath $generatedPresetPath)) {
        Remove-Item -LiteralPath $generatedPresetPath -Force -ErrorAction SilentlyContinue
    }
    return [pscustomobject]@{ Succeeded = ($deployed -gt 0 -and $errors -eq 0); Deployed = $deployed; Errors = $errors; Reason = if ($errors) { 'DEPLOYMENT_ERRORS' } elseif ($deployed -eq 0) { 'NO_GAMES_DEPLOYED' } else { $null } }
}

# =============================================================================
# Scans the first 2 MB of a game exe for legacy graphics API imports (DX8 /
# DirectDraw / Glide). Returns an array from: 'D3D8', 'DDraw', 'Glide2x',
# 'Glide3x'. Returns empty array if nothing is detected or on error.
function Get-GameLegacyApi {
    param([string]$ExePath)
    $found = @()
    try {
        $readLen = [int][Math]::Min((Get-Item -LiteralPath $ExePath).Length, 2097152)
        $buf     = New-Object byte[] $readLen
        $fs      = [System.IO.File]::OpenRead($ExePath)
        try {
            $pos = 0
            while ($pos -lt $readLen) {
                $n = $fs.Read($buf, $pos, $readLen - $pos)
                if ($n -eq 0) { break }
                $pos += $n
            }
        } finally { $fs.Dispose() }
        $text = [System.Text.Encoding]::ASCII.GetString($buf, 0, $pos)
        if ($text -match '(?i)d3d8\.dll')              { $found += 'D3D8'    }
        if ($text -match '(?i)ddraw\.dll')             { $found += 'DDraw'   }
        if ($text -match '(?i)glide2x\.dll')           { $found += 'Glide2x' }
        if ($text -match '(?i)(?:glide3x|glide)\.dll') { $found += 'Glide3x' }
    } catch {
        Write-Log "dgVoodoo2: scan failed for $ExePath -- $_"
    }
    return $found
}

# Pure, read-only check used by the Library health check's coverage
# report: given the legacy APIs an exe imports (from Get-GameLegacyApi)
# and its folder, decides whether dgVoodoo2 is already deployed there.
# Deliberately NOT shared with Invoke-DgVoodoo2Setup's own deploy logic --
# that logic also depends on which DLLs the user has actually bundled in
# their dgVoodoo2 source folder (falls back to deploying everything
# available if the ideal DLL is missing), which is a real, intentional
# difference from "does this game need dgVoodoo2 at all" -- a coverage
# report should answer the latter, independent of what's bundled.
function Test-DgVoodoo2UpToDate {
    param($Apis, [string]$ExeDir)

    if ($Apis.Count -eq 0) { return [pscustomobject]@{ Eligible = $false; UpToDate = $true } }
    $requiredDlls = @()
    if ($Apis -contains 'D3D8')    { $requiredDlls += 'D3D8.dll'    }
    if ($Apis -contains 'DDraw')   { $requiredDlls += 'DDraw.dll'   }
    if ($Apis -contains 'Glide2x') { $requiredDlls += 'Glide2x.dll' }
    if ($Apis -contains 'Glide3x') { $requiredDlls += 'Glide3x.dll' }
    $missing = @($requiredDlls | Where-Object { -not (Test-Path -LiteralPath (Join-Path $ExeDir $_)) })
    return [pscustomobject]@{ Eligible = $true; UpToDate = ($missing.Count -eq 0) }
}

# =============================================================================
# dgVoodoo2 install wizard: auto-detect DX8/DDraw/Glide games, deploy DLLs.
function Invoke-DgVoodoo2Setup {
    param(
        [string]$UserProfilesDir,
        [string]$SourceDir,
        [string]$TpRoot
    )

    # Validate at least one expected DLL is present in the source folder.
    $allExpected = @('D3D8.dll', 'DDraw.dll', 'D3DImm.dll', 'Glide2x.dll', 'Glide3x.dll')
    $available   = @($allExpected | Where-Object { Test-Path -LiteralPath (Join-Path $SourceDir $_) })
    if ($available.Count -eq 0) {
        Write-Host ("  ERROR: No dgVoodoo2 DLLs found in: {0}" -f $SourceDir) -ForegroundColor Red
        Write-Host ("  Expected one or more of: {0}" -f ($allExpected -join ', ')) -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: aborted -- no DLLs in $SourceDir"
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'NO_SOURCE_FILES' }
    }
    Write-Host ("  Available DLLs : {0}" -f ($available -join ', ')) -ForegroundColor DarkGray

    # Per-game config overrides: dgVoodoo2Presets\<ProfileCode>.conf always
    # wins over the global dgVoodoo.conf in $SourceDir for that one game.
    # Same convention as ReShadePresets\<ProfileCode>.ini (Invoke-ReShadeSetup)
    # and CustomThumbnails\<ProfileCode>.png (Invoke-ThumbnailDownload).
    $dgVoodoo2PresetsDir = Join-Path $PSScriptRoot "dgVoodoo2Presets"
    if (Test-Path -LiteralPath $dgVoodoo2PresetsDir) {
        $confFiles = @(Get-ChildItem -LiteralPath $dgVoodoo2PresetsDir -Filter "*.conf" -File -ErrorAction SilentlyContinue)
        if ($confFiles.Count -gt 0) {
            $knownConfCodes = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Directory.Name -ne "FullBackup" } |
                ForEach-Object { [void]$knownConfCodes.Add($_.BaseName) }
            foreach ($cfile in $confFiles) {
                $code = [System.IO.Path]::GetFileNameWithoutExtension($cfile.Name)
                if (-not $knownConfCodes.Contains($code)) {
                    Write-Host ("  WRONG NAME: dgVoodoo2Presets\{0}" -f $cfile.Name) -ForegroundColor Yellow
                    Write-Host ("             '{0}' does not match any registered game profile code." -f $code) -ForegroundColor Yellow
                    Write-Host "             Check TeknoParrot-Manager-controls.txt for the correct" -ForegroundColor Yellow
                    Write-Host "             name, rename the file, then re-run. File will be ignored." -ForegroundColor Yellow
                    Write-Log "dgVoodoo2: per-game config $($cfile.Name) -- no matching profile code, ignored."
                }
            }
        }
    }

    # Scan all registered games for legacy API usage and build a detection map.
    Write-Host ""
    Write-Host "  Scanning registered games for old DirectX / Glide usage..." -ForegroundColor Cyan
    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                  Where-Object { $_.Directory.Name -ne "FullBackup" } |
                  Sort-Object BaseName)
    if ($profiles.Count -eq 0) {
        Write-Host "  No registered games found." -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: aborted -- no registered profiles."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'NO_REGISTERED_PROFILES' }
    }

    $detectedMap = @{}   # BaseName -> API array
    foreach ($pf in $profiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $gpNode   = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { continue }
            $gamePath = $gpNode.InnerText.Trim()
            if (-not (Test-Path -LiteralPath $gamePath)) { continue }
            $apis = @(Get-GameLegacyApi -ExePath $gamePath)
            if ($apis.Count -gt 0) { $detectedMap[$pf.BaseName] = $apis }
        } catch {
            Write-Log "dgVoodoo2 scan: error reading $($pf.BaseName) -- $_"
        }
    }

    Write-Host ("  Scanned {0} game(s)." -f $profiles.Count) -ForegroundColor DarkGray
    if ($detectedMap.Count -gt 0) {
        Write-Host ("  Auto-detected {0} game(s) using legacy APIs:" -f $detectedMap.Count) -ForegroundColor Cyan
        foreach ($name in ($detectedMap.Keys | Sort-Object)) {
            Write-Host ("    {0}  [{1}]" -f $name, ($detectedMap[$name] -join ', '))
        }
    } else {
        Write-Host ""
        Write-Host "  No dgVoodoo2 setup needed" -ForegroundColor Green
        Write-Host "  TeknoParrot Manager checked your registered games and did not find any games that appear to need dgVoodoo2." -ForegroundColor Cyan
        Write-Host "  dgVoodoo2 is only used for select older games that need legacy DirectX, DirectDraw, or Glide compatibility." -ForegroundColor DarkGray
        Write-Host "  Nothing was changed." -ForegroundColor Green
        Write-Host ""
        Write-Host "  [D] Details  [Q] Back to menu"
        $selectionMode = (Read-HostSafe "  Choice, default Q").ToUpper()
        if ($selectionMode -eq 'D') {
            Write-Host ""
            Write-Host "  Details" -ForegroundColor Cyan
            Write-Host ("  Scanned game count: {0}" -f $profiles.Count) -ForegroundColor DarkGray
            Write-Host ("  Available DLLs: {0}" -f ($available -join ', ')) -ForegroundColor DarkGray
            Write-Host "  Detection checks executable imports for DirectX, DirectDraw, and Glide APIs." -ForegroundColor DarkGray
            Write-Host "  Advanced dgVoodoo2 selection is available for expert use:" -ForegroundColor Cyan
            Write-Host "  [M] Select specific games"
            Write-Host "  [Q] Back to menu"
            $selectionMode = (Read-HostSafe "  Choice, default Q").ToUpper()
        }
        if ($selectionMode -ne 'M') {
            Write-Log "dgVoodoo2 setup: no candidates detected; no changes made."
            return [pscustomobject]@{ Succeeded = $true; Deployed = 0; Errors = 0; Reason = 'NOT_NEEDED' }
        }
    }

    # Game selection.
    if ($detectedMap.Count -gt 0) {
        Write-Host ""
        Write-Host "  Which games should get dgVoodoo2?" -ForegroundColor Cyan
        Write-Host "  A) Auto-detected games only ($($detectedMap.Count) game(s) listed above)"
        Write-Host "  M) Pick games manually from the full list"
        Write-Host "  Q) Cancel"
        $selectionMode = (Read-HostSafe "  Enter A, M, or Q").ToUpper()
    }

    $targetProfiles = @()
    if ($selectionMode -eq 'A') {
        $targetProfiles = @($profiles | Where-Object { $detectedMap.ContainsKey($_.BaseName) })
    } elseif ($selectionMode -eq 'M') {
        $targetProfiles = @(Select-DgVoodoo2GamesInteractive -UserProfilesDir $UserProfilesDir)
    } else {
        Write-Host "  dgVoodoo2 setup cancelled." -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: cancelled."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'DECLINED' }
    }

    if ($targetProfiles.Count -eq 0) {
        Write-Host "  No games selected. dgVoodoo2 setup cancelled." -ForegroundColor Yellow
        Write-Log "dgVoodoo2 setup: cancelled -- no games selected."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'NO_GAMES_SELECTED' }
    }

    # Deploy DLLs to each selected game folder.
    Write-Host ""
    Write-Host ("  Installing dgVoodoo2 into {0} game folder(s)..." -f $targetProfiles.Count) -ForegroundColor Cyan
    $deployed = 0; $skipped = 0; $errors = 0; $presetOverrides = 0
    $hasConf  = Test-Path -LiteralPath (Join-Path $SourceDir "dgVoodoo.conf")

    foreach ($pf in $targetProfiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { $skipped++; continue }
            $gpNode   = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { $skipped++; continue }
            $gamePath = $gpNode.InnerText.Trim()
            if (-not (Test-Path -LiteralPath $gamePath)) {
                Write-Host ("  SKIP  {0} -- exe not found." -f $pf.BaseName) -ForegroundColor Yellow
                $skipped++; continue
            }
            $exeDir = [System.IO.Path]::GetDirectoryName($gamePath)
            if ([string]::IsNullOrWhiteSpace($exeDir)) { $skipped++; continue }

            # Determine which DLLs this game needs based on detected API.
            $apis = if ($detectedMap.ContainsKey($pf.BaseName)) `
                        { @($detectedMap[$pf.BaseName]) } `
                    else `
                        { @(Get-GameLegacyApi -ExePath $gamePath) }

            $toDeploy = @()
            if ($apis.Count -eq 0) {
                $toDeploy = $available   # manual pick with no detection: deploy all available
            } else {
                if ($apis -contains 'D3D8')    { $toDeploy += @($available | Where-Object { $_ -in @('D3D8.dll',   'D3DImm.dll') }) }
                if ($apis -contains 'DDraw')   { $toDeploy += @($available | Where-Object { $_ -in @('DDraw.dll',  'D3DImm.dll') }) }
                if ($apis -contains 'Glide2x') { $toDeploy += @($available | Where-Object { $_ -eq  'Glide2x.dll'               }) }
                if ($apis -contains 'Glide3x') { $toDeploy += @($available | Where-Object { $_ -eq  'Glide3x.dll'               }) }
                $toDeploy = @($toDeploy | Select-Object -Unique)
                if ($toDeploy.Count -eq 0) {
                    Write-Host ("  WARN  {0}: detected [{1}] but none of those DLLs are in the source folder; deploying all available." -f $pf.BaseName, ($apis -join ', ')) -ForegroundColor Yellow
                    Write-Log "dgVoodoo2: $($pf.BaseName) -- detected [$($apis -join ', ')] but no matching DLLs found; deploying all available."
                    $toDeploy = $available
                }
            }

            foreach ($dllName in $toDeploy) {
                $dstDll = Join-Path $exeDir $dllName
                if (-not (Test-Path -LiteralPath $dstDll)) {
                    Copy-Item -LiteralPath (Join-Path $SourceDir $dllName) -Destination $dstDll -ErrorAction Stop
                }
            }
            # Per-game config (dgVoodoo2Presets\<ProfileCode>.conf) always wins
            # over the global dgVoodoo.conf for this one game, and -- unlike
            # the global conf -- always overwrites: it's an explicit per-game
            # action, so "never overwrite" would silently defeat it on any
            # game that already has a conf deployed from a prior run.
            $perGameConf = Join-Path $dgVoodoo2PresetsDir ($pf.BaseName + ".conf")
            $confNote    = ""
            if (Test-Path -LiteralPath $perGameConf) {
                $dstConf = Join-Path $exeDir "dgVoodoo.conf"
                Copy-Item -LiteralPath $perGameConf -Destination $dstConf -Force -ErrorAction Stop
                $presetOverrides++
                $confNote = "  (config: per-game)"
            } elseif ($hasConf) {
                $dstConf = Join-Path $exeDir "dgVoodoo.conf"
                if (-not (Test-Path -LiteralPath $dstConf)) {
                    Copy-Item -LiteralPath (Join-Path $SourceDir "dgVoodoo.conf") -Destination $dstConf -ErrorAction Stop
                }
            }
            $apiStr = if ($apis.Count -gt 0) { "  [{0}]" -f ($apis -join ', ') } else { "" }
            Write-Host ("  OK    {0}{1}{2}" -f $pf.BaseName, $apiStr, $confNote) -ForegroundColor Green
            Write-Log ("dgVoodoo2: deployed {0} to {1}{2}" -f ($toDeploy -join ', '), $exeDir, $confNote)
            $deployed++
        } catch {
            Write-Host ("  ERROR {0} -- {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "dgVoodoo2: error on $($pf.BaseName) -- $_"
            $errors++
        }
    }

    Write-Host ""
    Write-Host ("  Deployed  : {0} game(s)" -f $deployed) -ForegroundColor Green
    if ($presetOverrides -gt 0) {
        Write-Host ("  Per-game configs applied : {0}" -f $presetOverrides) -ForegroundColor Cyan
    }
    if ($skipped -gt 0) { Write-Host ("  Skipped   : {0}" -f $skipped) -ForegroundColor DarkGray }
    if ($errors  -gt 0) { Write-Host ("  Errors    : {0}" -f $errors)  -ForegroundColor Red      }
    Write-Host ""
    Write-Host "  TeknoParrot Manager does not remove an unowned dgVoodoo2 hook automatically." -ForegroundColor DarkCyan
    Write-Host "  Existing or changed files need advanced troubleshooting review." -ForegroundColor DarkCyan
    Write-Log ("dgVoodoo2 setup: deployed={0} skipped={1} errors={2} presetOverrides={3}" -f $deployed, $skipped, $errors, $presetOverrides)
    return [pscustomobject]@{ Succeeded = ($deployed -gt 0 -and $errors -eq 0); Deployed = $deployed; Errors = $errors; Reason = if ($errors) { 'DEPLOYMENT_ERRORS' } elseif ($deployed -eq 0) { 'NO_GAMES_DEPLOYED' } else { $null } }
}

# =============================================================================
# XPath 1.0 has no escape for apostrophes in string literals; use concat()
# when the value contains one so the predicate always parses correctly.
function ConvertTo-XPathStringLiteral {
    param([string]$s)
    if ($s -notmatch "'") { return "'$s'" }
    $parts = $s.Split([char]39) | ForEach-Object { "'$_'" }
    return 'concat(' + ($parts -join ',"''",') + ')'
}

# Read-only, best-effort GPU vendor auto-detect via WMI -- no prompting.
# Returns [pscustomobject]@{ Vendor; Name } (Vendor may be $null if
# undetected). Shared by Invoke-GpuFixSetup (which falls back to an
# interactive prompt on failure) and the automatic compatibility check
# (which silently skips on failure, since it must not block an
# unattended-style run with a prompt).
function Get-DetectedGpuVendor {
    $gpuVendor = $null
    $gpuName   = $null
    try {
        # Bounded wait: a WMI service hiccup should fall through to the manual
        # vendor prompt below rather than hang the script indefinitely. Local
        # GPU enumeration doesn't have the network-round-trip hang risk that
        # Test-IsNetworkPath's drive check had, but the WMI service itself can
        # still misbehave, so this is bounded defensively rather than removed.
        $adapters = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop -OperationTimeoutSec 10 |
            Where-Object { $_.Name -notmatch '(?i)microsoft|virtual|remote' } |
            Sort-Object { if ($_.AdapterRAM) { [double]$_.AdapterRAM } else { 0.0 } } -Descending)
        if ($adapters.Count -gt 0) {
            $gpuName = $adapters[0].Name
            if     ($gpuName -imatch 'amd|radeon')                 { $gpuVendor = 'AMD'    }
            elseif ($gpuName -imatch 'nvidia|geforce|rtx|gtx')     { $gpuVendor = 'NVIDIA' }
            elseif ($gpuName -imatch 'intel')                      { $gpuVendor = 'Intel'  }
        }
    } catch {
        Write-Log "Get-DetectedGpuVendor: WMI detection failed -- $_"
    }
    return [pscustomobject]@{ Vendor = $gpuVendor; Name = $gpuName }
}

# Discovers GPU fix field names by scanning TeknoParrot GameProfiles at
# runtime, so newly added games with new fix fields are covered
# automatically without a script update. Shared (read-only) between
# Invoke-GpuFixSetup and the Library health check's coverage report --
# extracting this avoids the two ever silently drifting apart.
function Get-GpuFixFieldNames {
    param([string]$TpRoot)

    $gpDir         = Join-Path $TpRoot "GameProfiles"
    $boolAmdFields = [System.Collections.Generic.HashSet[string]]::new(
                         [string[]]@('EnableAmdFix','AMDCrashFix','AMDFix'),
                         [System.StringComparer]::OrdinalIgnoreCase)
    $dropdownGpuFields = [System.Collections.Generic.HashSet[string]]::new(
                             [string[]]@('GPU Fix'),
                             [System.StringComparer]::OrdinalIgnoreCase)

    if (Test-Path -LiteralPath $gpDir) {
        $gpFiles = @(Get-ChildItem -LiteralPath $gpDir -Filter "*.xml" -ErrorAction SilentlyContinue)
        foreach ($gf in $gpFiles) {
            try {
                $gdoc = Read-Xml $gf.FullName
                $fnodes = $gdoc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
                foreach ($n in $fnodes) {
                    $fn = if ($n.FieldName) { $n.FieldName.Trim() } else { '' }
                    $ft = if ($n.FieldType)  { $n.FieldType.Trim()  } else { '' }
                    if (-not $fn) { continue }
                    if ($ft -eq 'Bool' -and $fn -imatch '\bamd\b|\bradeon\b|AMDFix|AMDCrash') {
                        [void]$boolAmdFields.Add($fn)
                    } elseif ($ft -eq 'Dropdown') {
                        $opts = @($n.SelectNodes("FieldOptions/string") | ForEach-Object { $_.InnerText.Trim() })
                        if ($opts | Where-Object { $_ -imatch '^amd$|^nvidia$|^intel$|^new amd' }) {
                            [void]$dropdownGpuFields.Add($fn)
                        }
                    }
                }
            } catch {
                Write-Log ("GPU Fix: WARNING -- could not parse GameProfile '$($gf.BaseName)': $_")
            }
        }
    }
    return [pscustomobject]@{ BoolFields = $boolAmdFields; DropdownFields = $dropdownGpuFields; GameProfilesFound = (Test-Path -LiteralPath $gpDir) }
}

# Combines Get-GpuFixFieldNames and Get-FFBBlasterFieldNames into a single
# pass over GameProfiles. The Library health check needs both sets of
# fields in the same run, and calling the two functions separately means
# every GameProfile XML in the folder (TeknoParrot ships profiles for its
# entire supported-game catalog, not just the user's library, so this can
# be 1000+ files) gets parsed twice for no reason. Returns
# [pscustomobject]@{ Gpu = <same shape as Get-GpuFixFieldNames>; Ffb = <same shape as Get-FFBBlasterFieldNames> }
# -- the matching logic for each is identical to the two standalone
# functions, just evaluated in the same loop iteration. Invoke-GpuFixSetup
# and Invoke-FFBBlasterSetup keep calling their own standalone functions
# unchanged (they only ever need one or the other, never both at once), so
# this is purely additive -- only the health check's combined-need call
# site switches to use it.
function Get-GpuAndFfbFieldNames {
    param([string]$TpRoot)

    $gpDir             = Join-Path $TpRoot "GameProfiles"
    $boolAmdFields     = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $dropdownGpuFields = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $ffbFields         = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $gpDirExists       = Test-Path -LiteralPath $gpDir

    if ($gpDirExists) {
        $gpFiles = @(Get-ChildItem -LiteralPath $gpDir -Filter "*.xml" -ErrorAction SilentlyContinue)
        foreach ($gf in $gpFiles) {
            try {
                $gdoc = Read-Xml $gf.FullName
                $fnodes = $gdoc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
                foreach ($n in $fnodes) {
                    $cn = if ($n.CategoryName) { $n.CategoryName.Trim() } else { '' }
                    $fn = if ($n.FieldName)     { $n.FieldName.Trim()     } else { '' }
                    $ft = if ($n.FieldType)     { $n.FieldType.Trim()     } else { '' }
                    if ($ft -eq 'Bool') {
                        if ($fn -and $fn -imatch '\bamd\b|\bradeon\b|AMDFix|AMDCrash') {
                            [void]$boolAmdFields.Add($fn)
                        }
                        if ($cn -imatch 'ffb.*blaster|blaster.*ffb') {
                            [void]$ffbFields.Add($cn)
                        } elseif ($fn -and $fn -imatch 'ffb.*blaster|blaster.*ffb') {
                            [void]$ffbFields.Add($fn)
                        }
                    } elseif ($ft -eq 'Dropdown') {
                        $opts = @($n.SelectNodes("FieldOptions/string") | ForEach-Object { $_.InnerText.Trim() })
                        if ($opts | Where-Object { $_ -imatch '^amd$|^nvidia$|^intel$|^new amd' }) {
                            [void]$dropdownGpuFields.Add($fn)
                        }
                    }
                }
            } catch {
                Write-Log ("GpuAndFfbFieldScan: WARNING -- could not parse GameProfile '$($gf.BaseName)': $_")
            }
        }
    }

    return [pscustomobject]@{
        Gpu = [pscustomobject]@{ BoolFields = $boolAmdFields; DropdownFields = $dropdownGpuFields; GameProfilesFound = $gpDirExists }
        Ffb = $ffbFields
    }
}

# Pure decision function: for a given UserProfile XML and the field names
# discovered by Get-GpuFixFieldNames, determines whether the profile has
# any GPU fix field at all (Eligible) and, if so, whether every such
# field already matches the value expected for $Vendor (UpToDate). Also
# returns the exact node + new value for each field that needs changing,
# so Invoke-GpuFixSetup can apply them without re-deriving the same
# vendor-specific value logic a second time.
function Test-GpuFixUpToDate {
    param([System.Xml.XmlDocument]$Doc, $BoolFields, $DropdownFields, [string]$Vendor)

    $eligible = $false
    $changes  = New-Object System.Collections.Generic.List[object]

    foreach ($fieldName in $BoolFields) {
        $xpLit = ConvertTo-XPathStringLiteral $fieldName
        $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$xpLit]")
        if ($null -eq $fi) { continue }
        $fvNode = $fi.SelectSingleNode("FieldValue")
        if ($null -eq $fvNode) { continue }
        $eligible = $true
        $newVal = if ($Vendor -eq 'AMD') { '1' } else { '0' }
        if ($fvNode.InnerText -ne $newVal) {
            [void]$changes.Add([pscustomobject]@{ FieldName = $fieldName; Node = $fvNode; OldValue = $fvNode.InnerText; NewValue = $newVal })
        }
    }

    foreach ($fieldName in $DropdownFields) {
        $xpLit = ConvertTo-XPathStringLiteral $fieldName
        $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$xpLit]")
        if ($null -eq $fi) { continue }
        $fvNode = $fi.SelectSingleNode("FieldValue")
        $opts   = @($fi.SelectNodes("FieldOptions/string") | ForEach-Object { $_.InnerText.Trim() })
        if ($null -eq $fvNode -or $opts.Count -eq 0) { continue }
        $eligible = $true

        $newVal = 'None'
        if ($Vendor -eq 'AMD') {
            if     ($opts -contains 'New AMD Driver') { $newVal = 'New AMD Driver' }
            elseif ($opts -contains 'AMD')            { $newVal = 'AMD'            }
        } elseif ($Vendor -eq 'NVIDIA') {
            if ($opts -contains 'NVIDIA') { $newVal = 'NVIDIA' }
        } elseif ($Vendor -eq 'Intel') {
            if ($opts -contains 'INTEL') { $newVal = 'INTEL' }
        }

        if ($fvNode.InnerText -ne $newVal) {
            [void]$changes.Add([pscustomobject]@{ FieldName = $fieldName; Node = $fvNode; OldValue = $fvNode.InnerText; NewValue = $newVal })
        }
    }

    return [pscustomobject]@{ Eligible = $eligible; UpToDate = ($eligible -and $changes.Count -eq 0); Changes = $changes }
}

# =============================================================================
# POSTGRESQL DETECTION  (read-only helpers, shared by Postgres setup mode
# and the Library health check's coverage report)
# =============================================================================
# Several Incredible Technologies games (Golden Tee Live, Power Putt Live,
# Silver Strike Bowling Live, Target Toss Pro, Orange County Choppers
# Pinball) need a local PostgreSQL 8.3 database. Their Postgres settings
# live inside ConfigValues/FieldInformation under CategoryName=Postgres --
# the same generic per-game-setting structure GPU Fix/FFB Blaster above
# already use -- confirmed against a real Golden Tee Live 2019 GameProfile.
# Field names are standardized across every such game (it's the same
# settings panel design), so unlike GPU Fix this never needs per-game
# field-name variant matching -- just the category existence check below.

$script:PostgresInstallDir  = "C:\Program Files (x86)\PostgreSQL\8.3"
$script:PostgresBinDir      = Join-Path $script:PostgresInstallDir "bin"
$script:PostgresServiceName = "pgsql-8.3"

# Returns $true if this profile has any Postgres-category field at all.
function Test-GameNeedsPostgres {
    param([System.Xml.XmlDocument]$Doc)
    $node = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[CategoryName='Postgres']")
    return ($null -ne $node)
}

# Reads one named field's current value from the Postgres category, or
# $null if the field is missing entirely (distinct from an empty string,
# which means the field exists but is blank -- callers care about this
# distinction: "Automatically create Database" being absent means an older
# GameProfileRevision that predates the feature, not that it's off).
function Get-PostgresFieldValue {
    param([System.Xml.XmlDocument]$Doc, [string]$FieldName)
    $xpLit = ConvertTo-XPathStringLiteral $FieldName
    $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[CategoryName='Postgres' and FieldName=$xpLit]")
    if ($null -eq $fi) { return $null }
    $fvNode = $fi.SelectSingleNode("FieldValue")
    if ($null -eq $fvNode) { return $null }
    return $fvNode.InnerText
}

# Sets one named field's value in the Postgres category. No-op (returns
# $false) if the field doesn't exist on this profile -- never creates a
# new field, since the schema is owned by TeknoParrot's own GameProfile
# definitions, not by this script.
function Set-PostgresFieldValue {
    param([System.Xml.XmlDocument]$Doc, [string]$FieldName, [string]$Value)
    $xpLit = ConvertTo-XPathStringLiteral $FieldName
    $fi = $Doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[CategoryName='Postgres' and FieldName=$xpLit]")
    if ($null -eq $fi) { return $false }
    $fvNode = $fi.SelectSingleNode("FieldValue")
    if ($null -eq $fvNode) { return $false }
    $fvNode.InnerText = $Value
    return $true
}

# Validates a database name is safe to interpolate into a SQL string/CLI
# argument before any Postgres operation touches it. DbName ultimately
# comes from a GameProfile XML field -- shipped by TeknoParrot, but this
# script treats it as semi-trusted rather than blindly safe in a SQL
# context, matching the project's "external-ish input into a command must
# be validated" convention used elsewhere (e.g. Test-PathInside for
# filesystem paths). Every real DbName observed (GameDB19, GAMEDBPP12,
# GameDBSSB, GameDBBags, etc.) is plain alphanumeric, so this is not a
# practical restriction -- just a guard against the unexpected.
function Test-SafePostgresDbName {
    param([string]$DbName)
    return ($DbName -match '^[A-Za-z0-9_]+$')
}

# Every libpq helper uses a short-lived PGPASSFILE rather than PGPASSWORD.
# The file is created in the system temporary directory, stripped of
# inherited ACLs, granted only to the current Windows identity, and deleted
# before the helper returns. The process environment is restored afterward.
# A cleanup failure blocks the operation rather than leaving a credential
# behind. GameProfile Pass values remain a compatibility-required plaintext
# boundary for TeknoParrotUI; recovery backups are ACL-locked evidence.
function New-PostgresPgPassFile {
    param([Parameter(Mandatory)][string]$Password)
    if ([string]::IsNullOrEmpty($Password)) { throw 'Postgres: cannot create a credential file for an empty password.' }
    $path = Join-Path ([System.IO.Path]::GetTempPath()) ('tpm-pgpass-' + [guid]::NewGuid().ToString('N') + '.conf')
    $escaped = $Password -replace '\\', '\\' -replace ':', '\:'
    $line = '127.0.0.1:5432:*:postgres:' + $escaped
    try {
        [System.IO.File]::WriteAllText($path, $line + [Environment]::NewLine, (New-Object System.Text.UTF8Encoding $false))
        $owner = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
        & icacls $path /inheritance:r /grant:r ($owner + ':(F)') 1>$null 2>$null
        if ($LASTEXITCODE -ne 0) { throw 'icacls failed' }
    } catch {
        try { if (Test-Path -LiteralPath $path) { [System.IO.File]::Delete($path) } } catch {}
        throw 'Postgres: could not create and lock down the temporary credential file.'
    }
    return $path
}

function Remove-PostgresPgPassFile {
    param([string]$Path, [switch]$ThrowOnFailure)
    if ($Path -and (Test-Path -LiteralPath $Path)) {
        try {
            [System.IO.File]::Delete($Path)
            if (Test-Path -LiteralPath $Path) { throw 'credential file remains' }
        } catch {
            if ($ThrowOnFailure) { throw 'Postgres: temporary credential cleanup failed.' }
            return $false
        }
    }
    return $true
}

function Set-PostgresPgPassFileEnvironment {
    param([string]$Path)
    $previous = [Environment]::GetEnvironmentVariable('PGPASSFILE', 'Process')
    [Environment]::SetEnvironmentVariable('PGPASSFILE', $Path, 'Process')
    return $previous
}

function Restore-PostgresPgPassFileEnvironment {
    param([string]$PreviousValue)
    [Environment]::SetEnvironmentVariable('PGPASSFILE', $PreviousValue, 'Process')
}

function Wait-PostgresServiceState {
    param([Parameter(Mandatory)][string]$DesiredStatus, [int]$TimeoutSeconds = 30)
    $service = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
    if ($service.PSObject.Methods.Name -contains 'WaitForStatus') {
        $service.WaitForStatus($DesiredStatus, [TimeSpan]::FromSeconds($TimeoutSeconds))
    }
    $observed = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
    if ([string]$observed.Status -ne $DesiredStatus) {
        throw "PostgreSQL service did not reach the required state '$DesiredStatus'."
    }
    return $observed
}

function Test-PostgresInstalled {
    $svc = Get-Service -Name $script:PostgresServiceName -ErrorAction SilentlyContinue
    $psqlExists = Test-Path -LiteralPath (Join-Path $script:PostgresBinDir 'psql.exe')
    return (($null -ne $svc) -and $psqlExists)
}

# Returns a verified tri-state result instead of collapsing a connection or
# query failure into "database absent". Creation is allowed only when
# Verified is true and Exists is false.
function Get-PostgresDatabaseState {
    param([Parameter(Mandatory)][string]$DbName, [Parameter(Mandatory)][string]$SuperPasswordPlain)
    if (-not (Test-SafePostgresDbName $DbName)) { throw 'Postgres: unsafe database name.' }
    $psqlExe = Join-Path $script:PostgresBinDir 'psql.exe'
    if (-not (Test-Path -LiteralPath $psqlExe -PathType Leaf)) { throw 'Postgres: psql.exe could not be verified.' }
    $pgpassFile = New-PostgresPgPassFile -Password $SuperPasswordPlain
    $previousPgPassFile = $null
    try {
        $previousPgPassFile = Set-PostgresPgPassFileEnvironment -Path $pgpassFile
        $result = & $psqlExe -U postgres -h 127.0.0.1 -p 5432 -tAc "SELECT 1 FROM pg_database WHERE datname='$DbName'" 2>$null
        if ($LASTEXITCODE -ne 0) { throw 'Postgres: database existence query failed.' }
        return [pscustomobject]@{ Exists = ($result -match '^\s*1\s*$'); Verified = $true }
    } finally {
        Restore-PostgresPgPassFileEnvironment -PreviousValue $previousPgPassFile
        Remove-PostgresPgPassFile -Path $pgpassFile -ThrowOnFailure
    }
}

function Test-PostgresDatabaseExists {
    param([string]$DbName, [string]$SuperPasswordPlain)
    try { return ((Get-PostgresDatabaseState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain).Exists) }
    catch {
        Write-Log "Postgres: database existence check failed for '$DbName' -- operation blocked."
        return $false
    }
}

function Test-PostgresPassword {
    param([Parameter(Mandatory)][string]$SuperPasswordPlain)
    $psqlExe = Join-Path $script:PostgresBinDir 'psql.exe'
    if (-not (Test-Path -LiteralPath $psqlExe -PathType Leaf)) { return $false }
    $pgpassFile = New-PostgresPgPassFile -Password $SuperPasswordPlain
    $previousPgPassFile = $null
    try {
        $previousPgPassFile = Set-PostgresPgPassFileEnvironment -Path $pgpassFile
        & $psqlExe -U postgres -h 127.0.0.1 -p 5432 -tAc 'SELECT 1' 2>$null | Out-Null
        return ($LASTEXITCODE -eq 0)
    } finally {
        Restore-PostgresPgPassFileEnvironment -PreviousValue $previousPgPassFile
        Remove-PostgresPgPassFile -Path $pgpassFile -ThrowOnFailure
    }
}

function ConvertTo-PostgresSqlPasswordLiteral {
    param([Parameter(Mandatory)][string]$Password)
    if ([string]::IsNullOrEmpty($Password) -or $Password.IndexOf([char]0) -ge 0) {
        throw 'Postgres: the recovery password is empty or contains a NUL character.'
    }
    $builder = New-Object System.Text.StringBuilder
    foreach ($character in $Password.ToCharArray()) {
        $code = [int][char]$character
        switch ($code) {
            8  { [void]$builder.Append('\b') }
            9  { [void]$builder.Append('\t') }
            10 { [void]$builder.Append('\n') }
            11 { [void]$builder.Append('\v') }
            12 { [void]$builder.Append('\f') }
            13 { [void]$builder.Append('\r') }
            39 { [void]$builder.Append([char]92); [void]$builder.Append([char]39) }
            92 { [void]$builder.Append([char]92); [void]$builder.Append([char]92) }
            default {
                if ($code -lt 32) {
                    [void]$builder.Append([char]92)
                    [void]$builder.Append(('{0:D3}' -f $code))
                } else { [void]$builder.Append($character) }
            }
        }
    }
    return "E'" + $builder.ToString() + "'"
}

function ConvertTo-PostgresRedactedText {
    param([string]$Text, [string[]]$Secrets = @())
    $safe = if ($null -eq $Text) { '' } else { [string]$Text }
    foreach ($secret in @($Secrets)) {
        if (-not [string]::IsNullOrEmpty($secret)) { $safe = $safe.Replace($secret, '[REDACTED]') }
    }
    return $safe
}

function Invoke-PostgresNativeProcessWithInput {
    param(
        [Parameter(Mandatory)][string]$FilePath,
        [Parameter(Mandatory)][string]$Arguments,
        [Parameter(Mandatory)][string]$InputText,
        [string[]]$Secrets = @()
    )
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $FilePath
    $psi.Arguments = $Arguments
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardInput = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    try { $psi.StandardInputEncoding = New-Object System.Text.UTF8Encoding $false } catch {}
    $proc = New-Object System.Diagnostics.Process
    $proc.StartInfo = $psi
    try {
        if (-not $proc.Start()) { throw 'Postgres process could not be started.' }
        $proc.StandardInput.Write($InputText)
        $proc.StandardInput.Close()
        $stdout = $proc.StandardOutput.ReadToEnd()
        $stderr = $proc.StandardError.ReadToEnd()
        $proc.WaitForExit()
        return [pscustomobject]@{
            ExitCode = $proc.ExitCode
            Output = ConvertTo-PostgresRedactedText -Text $stdout -Secrets $Secrets
            Error = ConvertTo-PostgresRedactedText -Text $stderr -Secrets $Secrets
        }
    } finally { $proc.Dispose() }
}

function Copy-PostgresRecoveryEvidenceFile {
    param([Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Destination)
    if (-not (Test-Path -LiteralPath $Source -PathType Leaf)) { throw 'Postgres recovery evidence source is missing.' }
    [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($Destination))
    Copy-Item -LiteralPath $Source -Destination $Destination -Force -ErrorAction Stop
    $sourceItem = Get-Item -LiteralPath $Source -Force -ErrorAction Stop
    $destItem = Get-Item -LiteralPath $Destination -Force -ErrorAction Stop
    $sourceHash = (Get-FileHash -LiteralPath $Source -Algorithm SHA256 -ErrorAction Stop).Hash
    $destHash = (Get-FileHash -LiteralPath $Destination -Algorithm SHA256 -ErrorAction Stop).Hash
    if ($sourceItem.Length -ne $destItem.Length -or $sourceHash -ne $destHash) { throw 'Postgres recovery evidence hash verification failed.' }
    return [pscustomobject]@{ Source = $Source; Backup = $Destination; Sha256 = $destHash }
}

function Lock-PostgresRecoveryDirectory {
    param([Parameter(Mandatory)][string]$Path)
    $owner = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
    & icacls $Path /inheritance:r /grant:r ($owner + ':(OI)(CI)(F)') 1>$null 2>$null
    if ($LASTEXITCODE -ne 0) { throw 'Postgres recovery evidence ACL could not be verified.' }
}

function New-PostgresRecoveryBackup {
    param([Parameter(Mandatory)][string]$UserProfilesDir)
    $timestamp = (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss_fff')
    $backupRoot = Join-Path (Join-Path $PSScriptRoot 'PostgresRecoveryBackups') $timestamp
    $configBackupRoot = Join-Path $backupRoot 'PostgreSQL'
    $profileBackupRoot = Join-Path $backupRoot 'Profiles'
    $profileBackups = New-Object System.Collections.Generic.List[object]
    $configBackups = New-Object System.Collections.Generic.List[object]
    try {
        [void][System.IO.Directory]::CreateDirectory($configBackupRoot)
        [void][System.IO.Directory]::CreateDirectory($profileBackupRoot)
        Lock-PostgresRecoveryDirectory -Path $backupRoot
        $dataDir = Join-Path $script:PostgresInstallDir 'data'
        if (-not (Test-Path -LiteralPath $dataDir -PathType Container)) { throw 'Postgres data directory is not present.' }
        foreach ($configName in @('pg_hba.conf', 'postgresql.conf')) {
            [void]$configBackups.Add((Copy-PostgresRecoveryEvidenceFile -Source (Join-Path $dataDir $configName) -Destination (Join-Path $configBackupRoot $configName)))
        }
        $configVariable = Get-Variable -Name configPath -Scope Script -ErrorAction SilentlyContinue
        if ($configVariable -and $configVariable.Value -and (Test-Path -LiteralPath $configVariable.Value -PathType Leaf)) {
            [void]$configBackups.Add((Copy-PostgresRecoveryEvidenceFile -Source $configVariable.Value -Destination (Join-Path $backupRoot 'TeknoParrot-Manager.config.json')))
        }
        if (-not (Test-Path -LiteralPath $UserProfilesDir -PathType Container)) { throw 'UserProfiles directory is not present.' }
        $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction Stop | Where-Object { $_.Directory.Name -ne 'FullBackup' } | Sort-Object Name)
        foreach ($profileFile in $profiles) {
            $doc = Read-Xml $profileFile.FullName
            if ($doc.GameProfile -and (Test-GameNeedsPostgres $doc)) {
                [void]$profileBackups.Add((Copy-PostgresRecoveryEvidenceFile -Source $profileFile.FullName -Destination (Join-Path $profileBackupRoot $profileFile.Name)))
            }
        }
        if ($profileBackups.Count -eq 0) { throw 'No affected PostgreSQL profiles were identified.' }
        return [pscustomobject]@{ Path = $backupRoot; ConfigBackups = $configBackups.ToArray(); ProfileBackups = $profileBackups.ToArray(); Verified = $true }
    } catch {
        Write-Log "Postgres recovery backup: blocked; evidence remains at $backupRoot."
        return [pscustomobject]@{ Path = $backupRoot; ConfigBackups = $configBackups.ToArray(); ProfileBackups = $profileBackups.ToArray(); Verified = $false }
    }
}

function Restore-PostgresProfileBackups {
    param([Parameter(Mandatory)]$RecoveryBackup)
    foreach ($item in @($RecoveryBackup.ProfileBackups | Sort-Object Source)) {
        Copy-Item -LiteralPath $item.Backup -Destination $item.Source -Force -ErrorAction Stop
        $sourceHash = (Get-FileHash -LiteralPath $item.Source -Algorithm SHA256 -ErrorAction Stop).Hash
        $backupHash = (Get-FileHash -LiteralPath $item.Backup -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($sourceHash -ne $backupHash) { throw 'Postgres profile rollback hash verification failed.' }
    }
    return $true
}

function Reset-PostgresPasswordAutomatically {
    param([Parameter(Mandatory)][string]$NewPassword, [Parameter(Mandatory)]$RecoveryBackup)
    $result = [ordered]@{ Attempted = $false; Succeeded = $false; RecoveryBlocked = $true; BackupPath = $RecoveryBackup.Path; Reason = '' }
    if (-not $RecoveryBackup.Verified) { $result.Reason = 'Verified recovery evidence is unavailable.'; return [pscustomobject]$result }
    $postgresExe = Join-Path $script:PostgresBinDir 'postgres.exe'
    $dataDir = Join-Path $script:PostgresInstallDir 'data'
    if (-not (Test-Path -LiteralPath $postgresExe -PathType Leaf) -or -not (Test-Path -LiteralPath $dataDir -PathType Container)) {
        $result.Reason = 'The PostgreSQL executable or data directory could not be verified.'
        return [pscustomobject]$result
    }
    if ($dataDir -match '[\r\n"]') { $result.Reason = 'The PostgreSQL data path is not safe for the native recovery command.'; return [pscustomobject]$result }
    $service = Get-Service -Name $script:PostgresServiceName -ErrorAction SilentlyContinue
    if ($null -eq $service) { $result.Reason = 'The PostgreSQL service could not be verified.'; return [pscustomobject]$result }
    $wasRunning = ([string]$service.Status -ne 'Stopped')
    try {
        $result.Attempted = $true
        if ($wasRunning) {
            Stop-Service -Name $script:PostgresServiceName -Force -ErrorAction Stop
            Wait-PostgresServiceState -DesiredStatus 'Stopped' | Out-Null
        }
        if (Test-Path -LiteralPath (Join-Path $dataDir 'postmaster.pid') -PathType Leaf) { throw 'A live PostgreSQL postmaster is still present.' }
        $literal = ConvertTo-PostgresSqlPasswordLiteral -Password $NewPassword
        $sql = 'ALTER ROLE postgres WITH PASSWORD ' + $literal + ';' + [Environment]::NewLine + [Environment]::NewLine
        $processResult = Invoke-PostgresNativeProcessWithInput -FilePath $postgresExe -Arguments ('--single -D "' + $dataDir + '" -j postgres') -InputText $sql -Secrets @($NewPassword)
        if ($processResult.ExitCode -ne 0) { throw "Automatic PostgreSQL password reset failed with exit code $($processResult.ExitCode)." }
        Start-Service -Name $script:PostgresServiceName -ErrorAction Stop
        Wait-PostgresServiceState -DesiredStatus 'Running' | Out-Null
        if (-not (Test-PostgresPassword -SuperPasswordPlain $NewPassword)) { throw 'The reset completed but the approved password did not authenticate.' }
        $result.Succeeded = $true
        $result.RecoveryBlocked = $false
        $result.Reason = 'Automatic PostgreSQL password reset and authentication verification completed.'
        Write-Log "Postgres recovery: automatic password reset completed; pg_hba.conf was not changed. Evidence=$($RecoveryBackup.Path)"
    } catch {
        $result.Reason = 'Automatic PostgreSQL password reset did not complete.'
        Write-Log "Postgres recovery: blocked; no recovery-complete result was reported. Evidence=$($RecoveryBackup.Path)"
        try {
            $current = Get-Service -Name $script:PostgresServiceName -ErrorAction SilentlyContinue
            if ($current -and $wasRunning -and [string]$current.Status -eq 'Stopped') { Start-Service -Name $script:PostgresServiceName -ErrorAction Stop; Wait-PostgresServiceState -DesiredStatus 'Running' | Out-Null }
            if ($current -and -not $wasRunning -and [string]$current.Status -eq 'Running') { Stop-Service -Name $script:PostgresServiceName -Force -ErrorAction Stop; Wait-PostgresServiceState -DesiredStatus 'Stopped' | Out-Null }
        } catch { Write-Log 'Postgres recovery: original service state could not be restored.' }
    }
    return [pscustomobject]$result
}

function Restore-PostgresServiceState {
    param([object]$WasRunning)
    if ($null -eq $WasRunning) { return $true }
    try {
        $service = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
        $running = ([string]$service.Status -ne 'Stopped')
        if ([bool]$WasRunning -and -not $running) {
            Start-Service -Name $script:PostgresServiceName -ErrorAction Stop
            Wait-PostgresServiceState -DesiredStatus 'Running' | Out-Null
        } elseif (-not [bool]$WasRunning -and $running) {
            Stop-Service -Name $script:PostgresServiceName -Force -ErrorAction Stop
            Wait-PostgresServiceState -DesiredStatus 'Stopped' | Out-Null
        }
        return $true
    } catch {
        Write-Log 'Postgres recovery: original service state could not be restored.'
        return $false
    }
}
# =============================================================================
# GPU Fix Setup: detect GPU vendor, scan TeknoParrot GameProfiles for fix
# fields (so newly added games are covered automatically), and apply the
# appropriate values to every registered UserProfile XML.
function Invoke-GpuFixSetup {
    param(
        [string]$UserProfilesDir,
        [string]$TpRoot
    )

    # -- GPU detection ----------------------------------------------------------
    Write-Host ""
    Write-Host "  Detecting GPU..." -ForegroundColor DarkGray
    $detected  = Get-DetectedGpuVendor
    $gpuVendor = $detected.Vendor
    $gpuName   = $detected.Name

    if ($gpuVendor) {
        Write-Host ("  Detected : {0} ({1})" -f $gpuVendor, $gpuName) -ForegroundColor DarkGray
        Write-Log "GPU Fix: detected $gpuVendor ($gpuName)"
    } else {
        Write-Host "  Could not auto-detect GPU vendor." -ForegroundColor Yellow
        if ($gpuName) { Write-Host ("  Adapter  : {0}" -f $gpuName) -ForegroundColor DarkGray }
        $inp = (Read-HostSafe "  Enter GPU vendor (AMD / NVIDIA / Intel) or press Enter to cancel")
        if ([string]::IsNullOrWhiteSpace($inp)) {
            Write-Host "  GPU fix setup cancelled." -ForegroundColor DarkGray
            Write-Log "GPU Fix: cancelled -- vendor not detected and user did not enter one."
            return
        }
        if     ($inp -imatch '^amd$|^radeon$')     { $gpuVendor = 'AMD'    }
        elseif ($inp -imatch '^nvidia$|^geforce$')  { $gpuVendor = 'NVIDIA' }
        elseif ($inp -imatch '^intel$')             { $gpuVendor = 'Intel'  }
        else {
            Write-Host ("  Unrecognised vendor '{0}'. Use AMD, NVIDIA, or Intel." -f $inp) -ForegroundColor Red
            Write-Log "GPU Fix: cancelled -- unrecognised vendor '$inp'."
            return
        }
        Write-Host ("  Using    : {0}" -f $gpuVendor) -ForegroundColor DarkGray
        Write-Log "GPU Fix: user-specified vendor = $gpuVendor"
    }

    # -- Discover GPU fix field names from TeknoParrot GameProfiles -------------
    # Scans at runtime so newly added games with new fix fields are covered
    # automatically without requiring a script update.
    Write-Host "  Scanning GameProfiles for GPU fix fields..." -ForegroundColor DarkGray
    $gpuFields         = Get-GpuFixFieldNames -TpRoot $TpRoot
    $boolAmdFields     = $gpuFields.BoolFields
    $dropdownGpuFields = $gpuFields.DropdownFields
    if ($gpuFields.GameProfilesFound) {
        Write-Log ("GPU Fix: discovered fields -- Bool AMD: [{0}]  Dropdown GPU: [{1}]" -f `
            ($boolAmdFields -join ', '), ($dropdownGpuFields -join ', '))
    } else {
        Write-Host ("  GameProfiles folder not found -- using built-in field list.") -ForegroundColor DarkGray
        Write-Log "GPU Fix: GameProfiles not found -- using fallback field list."
    }

    # -- Backup UserProfiles before any write ------------------------------------
    # This setup writes vendor-fix fields into every registered profile, so it
    # needs the same backup-before-destructive-operation safety net as
    # Invoke-CursorHideSetup -- without it, a bad GPU detection or a corrupted
    # GameProfiles scan would overwrite every UserProfile XML with no way back.
    $backupRoot = Join-Path $UserProfilesDir "FullBackup"
    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss")
    $backupPath = Join-Path $backupRoot ("GpuFix_" + $timestamp)
    try {
        [void][System.IO.Directory]::CreateDirectory($backupRoot)
        [void][System.IO.Directory]::CreateDirectory($backupPath)
    } catch {
        Write-Host "  ERROR: Could not create backup folder: $_" -ForegroundColor Red
        Write-Log "GPU Fix: backup failed -- $_"
        return
    }
    $backupCopyErrs = $null
    # Copy-Item receives FileInfo/DirectoryInfo objects from the pipeline
    # (not path strings), so pipeline binding already bypasses wildcard
    # expansion -- safe even with [, ], $ in game folder names. If this
    # source is ever changed to raw path strings, add -LiteralPath there.
    Get-ChildItem -LiteralPath $UserProfilesDir | Where-Object { $_.Name -ne "FullBackup" } |
        Copy-Item -Destination $backupPath -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable backupCopyErrs
    if ($backupCopyErrs.Count -gt 0) {
        Write-Host ("  WARNING: {0} file(s) could not be backed up." -f $backupCopyErrs.Count) -ForegroundColor Yellow
        Write-Log "GPU Fix: backup had $($backupCopyErrs.Count) error(s)"
    }
    Write-Host ("  Backup: {0}" -f $backupPath) -ForegroundColor DarkGray
    Write-Log "GPU Fix: backup at $backupPath"

    # -- Walk UserProfiles ------------------------------------------------------
    Write-Host ""
    Write-Host "  Applying GPU fixes to registered profiles..." -ForegroundColor DarkGray
    $profiles  = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -ErrorAction SilentlyContinue)
    $updated   = 0
    $unchanged = 0
    $errors    = 0

    foreach ($pf in $profiles) {
        try {
            $doc    = Read-Xml $pf.FullName
            $result = Test-GpuFixUpToDate -Doc $doc -BoolFields $boolAmdFields -DropdownFields $dropdownGpuFields -Vendor $gpuVendor

            if ($result.Changes.Count -gt 0) {
                foreach ($c in $result.Changes) {
                    $c.Node.InnerText = $c.NewValue
                    Write-Log "GPU Fix: $($pf.BaseName) :: $($c.FieldName) $($c.OldValue) -> $($c.NewValue)"
                }
                Save-Xml $doc $pf.FullName
                $updated++
                Write-Host ("    {0}" -f $pf.BaseName) -ForegroundColor Green
            } else {
                $unchanged++
            }
        } catch {
            Write-Host ("    FAILED {0}: {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "GPU Fix: FAILED $($pf.BaseName) -- $_"
            $errors++
        }
    }

    Write-Host ""
    Write-Host ("  Updated  : {0} profile(s)" -f $updated) -ForegroundColor Green
    if ($unchanged -gt 0) {
        Write-Host ("  No change: {0} (already correct or no GPU fix fields)" -f $unchanged) -ForegroundColor DarkGray
    }
    if ($errors -gt 0) {
        Write-Host ("  Errors   : {0} -- see log for details" -f $errors) -ForegroundColor Red
    }
    Write-Log ("GPU Fix: complete. Vendor={0} Updated={1} Unchanged={2} Errors={3}" -f `
        $gpuVendor, $updated, $unchanged, $errors)
}

# =============================================================================
# Full crosshair setup flow: validate collection, preview, pick, deploy.
# Updates cursor_path under [USB Port 1 guncon2] and [USB Port 2 guncon2] in PCSX2.ini.
# Handles sections that already have cursor_path (replaces), sections that exist without
# it (inserts before the next section header), and missing sections (appends at EOF).
function Set-Pcsx2CursorPaths {
    param([string]$IniPath, [string]$P1Path, [string]$P2Path)

    # ECVF: cursor_path is pcsx2x6-emulator-owned for jvsmode=lightgun
    # titles (contracts\pcsx2x6\contract.json, evidence.md#ev-guncon2-clear) --
    # the emulator itself clears it in memory whenever JVS mode is
    # LIGHTGUN, so writing it here does not affect what is actually
    # rendered for any currently-supported TeknoParrot lightgun title.
    # Consulted dynamically (not hardcoded) so this adapts automatically
    # if the contract is ever revised -- a future non-JVS GunCon2 title,
    # or updated evidence from the pending hardware experiment recorded
    # in contracts\pcsx2x6\experiments.md. If the framework cannot be
    # consulted at all, this fails closed: skip the write rather than
    # fall back to the old, now-confirmed-incorrect unconditional write.
    $writeAllowed = $false
    $skipReason = "the pcsx2x6 emulator contract framework was not available to confirm this write is safe"
    try {
        # $PSScriptRoot can be an empty string (e.g. a function body invoked
        # from a dynamically-created scriptblock with no backing file, as in
        # this project's own Pester harness) -- Join-Path rejects an empty
        # -Path with a binding exception, so this whole resolution step
        # must be inside the try, not just the module load that follows it.
        $ecvfContractsModule = Join-Path $PSScriptRoot "scripts\TPMCertification.Contracts.psm1"
        if (Test-Path -LiteralPath $ecvfContractsModule -PathType Leaf) {
            Import-Module $ecvfContractsModule -Force -ErrorAction Stop
            $loadedContract = Get-TPMEmulatorContractV1 -ContractId 'pcsx2x6'
            try {
                Assert-TPMOwnershipWriteAllowedV1 -Contract $loadedContract.Contract -SettingPath 'USB1.guncon2_cursor_path[jvsmode=lightgun]' | Out-Null
                $writeAllowed = $true
            } catch {
                $skipReason = "pcsx2x6's cursor_path is emulator-owned for jvsmode=lightgun titles -- $_"
            }
        }
    } catch {
        $skipReason = "could not load or evaluate the pcsx2x6 emulator contract -- $_"
    }
    if (-not $writeAllowed) {
        Write-Host ("    NOTE: Skipping PCSX2.ini cursor_path write -- {0}" -f $skipReason) -ForegroundColor Yellow
        Write-Log "Crosshairs: skipped PCSX2.ini cursor_path write -- $skipReason"
        return $false
    }

    try {
        $lines   = [System.IO.File]::ReadAllLines($IniPath)
        $out     = New-Object System.Collections.Generic.List[string]
        $targets = @{ 'usb port 1 guncon2' = $P1Path; 'usb port 2 guncon2' = $P2Path }
        $done    = @{ 'usb port 1 guncon2' = $false;  'usb port 2 guncon2' = $false  }
        $sect    = ''

        foreach ($ln in $lines) {
            $t = $ln.Trim()
            if ($t -match '^\[(.+)\]$') {
                if ($targets.ContainsKey($sect) -and -not $done[$sect]) {
                    $out.Add("cursor_path = $($targets[$sect])")
                    $done[$sect] = $true
                }
                $sect = $matches[1].ToLower()
                $out.Add($ln); continue
            }
            if ($t -match '^cursor_path\s*=' -and $targets.ContainsKey($sect)) {
                $out.Add("cursor_path = $($targets[$sect])")
                $done[$sect] = $true; continue
            }
            $out.Add($ln)
        }
        # Handle last section (no following header to trigger flush)
        if ($targets.ContainsKey($sect) -and -not $done[$sect]) {
            $out.Add("cursor_path = $($targets[$sect])")
            $done[$sect] = $true
        }
        # Append sections that were never present in the file
        foreach ($tgt in ($done.Keys | Where-Object { -not $done[$_] })) {
            $hdr = if ($tgt -eq 'usb port 1 guncon2') { '[USB Port 1 guncon2]' } else { '[USB Port 2 guncon2]' }
            $out.Add($hdr); $out.Add("cursor_path = $($targets[$tgt])")
        }
        # Back up before overwriting -- this is the user's PCSX2 emulator
        # config, not a file this script created, so a bad parse should
        # never leave them without their original settings.
        $iniBackup = $IniPath + ".bak_" + (Get-Date).ToString("yyyyMMdd_HHmmss")
        Copy-Item -LiteralPath $IniPath -Destination $iniBackup -ErrorAction Stop
        [System.IO.File]::WriteAllText($IniPath, ($out -join "`r`n"), (New-Object System.Text.UTF8Encoding $false))
        Write-Log "Crosshairs: updated PCSX2.ini at $IniPath (backup: $iniBackup)"
        return $true
    } catch {
        Write-Host ("    WARNING: Could not update PCSX2.ini -- {0}" -f $_) -ForegroundColor Yellow
        Write-Log "Crosshairs: PCSX2.ini update failed -- $_"
        return $false
    }
}

# Locates the pcsx2x6 emulator folder under a TeknoParrot root: common
# names first, then any pcsx2-prefixed subfolder as a fallback. Returns
# $null if none is found (most installs don't have one -- it's specific to
# a handful of lightgun titles). Shared by Invoke-CrosshairSetup (issue #79
# crosshair deployment) and Get-CompatibilityWarnings (issue #85 BIOS
# detection) so both agree on what counts as "present" from one place, not
# two independently-maintained copies of the same candidate search.
function Resolve-Pcsx2Directory {
    param([Parameter(Mandatory)][string]$TeknoParrotRoot)
    foreach ($candidate in @("pcsx2x6","PCSX2x6","pcsx2","PCSX2")) {
        $try = Join-Path $TeknoParrotRoot $candidate
        if (Test-Path -LiteralPath $try) { return $try }
    }
    return Get-ChildItem -LiteralPath $TeknoParrotRoot -Directory -ErrorAction SilentlyContinue |
           Where-Object { $_.Name -imatch '^pcsx2' } | Select-Object -First 1 -ExpandProperty FullName
}

# Read-only, contract-backed required-component assessment shared by the
# compatibility warning surface. A warning is eligible only when exactly one
# valid ECVF contract matches the registered EmulatorType, the contract has a
# non-empty PathExists PresenceDetector, and the corresponding emulator folder
# already exists. Missing/invalid/ambiguous contracts, unsupported detector
# methods, and absent emulator folders remain Unknown/unclassified and produce
# no missing-component claim.
function Get-ContractBackedMissingComponents {
    param(
        [Parameter(Mandatory)][string]$EmulatorType,
        [Parameter(Mandatory)][string]$TeknoParrotRoot,
        [string[]]$AffectedProfiles = @(),
        [string]$ContractsRoot = ''
    )

    $unknown = [ordered]@{
        State             = 'Unknown'
        Reason            = $null
        ContractId        = $null
        EmulatorDirectory = $null
        Components        = @()
    }

    if ([string]::IsNullOrWhiteSpace($EmulatorType)) {
        $unknown.Reason = 'registered profile did not declare an emulator type'
        return [pscustomobject]$unknown
    }
    if ([string]::IsNullOrWhiteSpace($TeknoParrotRoot) -or
        -not (Test-Path -LiteralPath $TeknoParrotRoot -PathType Container)) {
        $unknown.Reason = 'TeknoParrot root was not available for component assessment'
        return [pscustomobject]$unknown
    }

    try {
        $ecvfContractsModule = Join-Path $PSScriptRoot "scripts\TPMCertification.Contracts.psm1"
        if (-not (Test-Path -LiteralPath $ecvfContractsModule -PathType Leaf)) {
            $unknown.Reason = 'the ECVF contracts framework was not available'
            return [pscustomobject]$unknown
        }
        Import-Module $ecvfContractsModule -Force -ErrorAction Stop

        $resolvedContractsRoot = if ([string]::IsNullOrWhiteSpace($ContractsRoot)) {
            Join-Path $PSScriptRoot 'contracts'
        } else { $ContractsRoot }
        # Use the ECVF registry loader used by the existing #254 detector.
        # It validates each discovered contract's machine-readable schema and
        # fails closed if any contract cannot be loaded; this warning path does
        # not reinterpret a second contract format of its own.
        $registeredContracts = Get-TPMRegisteredEmulatorContractsV1 -ContractsRoot $resolvedContractsRoot
        $contractMatches = @($registeredContracts | Where-Object {
            [string]::Equals([string]$_.ContractId, $EmulatorType, [StringComparison]::OrdinalIgnoreCase)
        })
        if ($contractMatches.Count -ne 1) {
            $unknown.Reason = if ($contractMatches.Count -eq 0) {
                "no ECVF contract matched EmulatorType '$EmulatorType'"
            } else {
                "more than one ECVF contract matched EmulatorType '$EmulatorType'"
            }
            return [pscustomobject]$unknown
        }

        $contractEntry = $contractMatches[0]
        $contract = $contractEntry.Contract
        $contractId = [string]$contract.ContractId
        $unknown.ContractId = $contractId

        $emulatorDirectory = if ([string]::Equals($contractId, 'pcsx2x6', [StringComparison]::OrdinalIgnoreCase)) {
            # Preserve #254's established resolver, including its supported
            # casing and pcsx2-prefixed fallback names.
            Resolve-Pcsx2Directory -TeknoParrotRoot $TeknoParrotRoot
        } else {
            @(Get-ChildItem -LiteralPath $TeknoParrotRoot -Directory -ErrorAction SilentlyContinue |
                Where-Object { [string]::Equals($_.Name, $contractId, [StringComparison]::OrdinalIgnoreCase) } |
                Select-Object -First 1 -ExpandProperty FullName)
        }
        if ([string]::IsNullOrWhiteSpace([string]$emulatorDirectory) -or
            -not (Test-Path -LiteralPath $emulatorDirectory -PathType Container)) {
            $unknown.Reason = "the contract-matched emulator folder '$contractId' was not present"
            return [pscustomobject]$unknown
        }
        $unknown.EmulatorDirectory = $emulatorDirectory

        $capabilities = @($contract.EnvironmentCapabilities | Where-Object {
            $_.PresenceDetector -and
            $_.PresenceDetector.Method -eq 'PathExists' -and
            -not [string]::IsNullOrWhiteSpace([string]$_.PresenceDetector.Source)
        })
        if ($capabilities.Count -eq 0) {
            $unknown.Reason = "contract '$contractId' has no usable PathExists required-component detector"
            return [pscustomobject]$unknown
        }

        $affected = @($AffectedProfiles | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Sort-Object -Unique)
        $missing = New-Object System.Collections.Generic.List[object]
        foreach ($capability in $capabilities) {
            $detector = $capability.PresenceDetector
            $relativeSource = [string]$detector.Source
            if ([System.IO.Path]::IsPathRooted($relativeSource) -or
                $relativeSource -match '(^|[\\/])\.\.([\\/]|$)') {
                # A contract path that is not safely relative to its own
                # emulator folder cannot establish a trustworthy warning.
                continue
            }
            try {
                $expectedPath = Join-Path $emulatorDirectory $relativeSource
                $emulatorFull = [System.IO.Path]::GetFullPath($emulatorDirectory).TrimEnd([char]'\', [char]'/' )
                $expectedFull = [System.IO.Path]::GetFullPath($expectedPath)
                $withinEmulator = $expectedFull.StartsWith($emulatorFull + [System.IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase) -or
                                  [string]::Equals($expectedFull, $emulatorFull, [StringComparison]::OrdinalIgnoreCase)
                if (-not $withinEmulator) { continue }
            } catch {
                continue
            }

            if (Test-TPMEmulatorPresentV1 -Detector $detector -InstallDir $emulatorDirectory) { continue }

            $missing.Add([pscustomobject]@{
                EmulatorType       = $EmulatorType
                ContractId          = $contractId
                ContractDisplayName = [string]$contract.DisplayName
                ContractStatus      = [string]$contract.ContractStatus
                Confidence          = [string]$contract.EvidenceConfidence
                ContractBacked      = $true
                CapabilityId        = [string]$capability.CapabilityId
                ExpectedPath        = $expectedPath
                DetectorMethod      = [string]$detector.Method
                DetectorSource      = $relativeSource
                AffectedProfiles    = $affected
                AffectedGames       = $affected
                State               = 'Missing'
            })
        }

        return [pscustomobject]@{
            State             = if ($missing.Count -gt 0) { 'Missing' } else { 'Present' }
            Reason            = if ($missing.Count -gt 0) { 'one or more contract-declared components were absent' } else { $null }
            ContractId        = $contractId
            EmulatorDirectory = $emulatorDirectory
            Components        = $missing.ToArray()
        }
    } catch {
        $unknown.Reason = 'could not load or evaluate the ECVF contract -- ' + $_.Exception.Message
        return [pscustomobject]$unknown
    }
}

# Checks whether a pcsx2x6 process is currently running, so first-run
# initialization never races a live emulator instance touching the same
# ini/data-root files. Mirrors the Get-Process -Name guard pattern already
# used elsewhere in this script for LaunchBox/BigBox/TeknoParrotUi.
function Test-Pcsx2ProcessRunning {
    return [bool](Get-Process -Name "pcsx2-qtx64" -ErrorAction SilentlyContinue)
}

# Read-only classification of a resolved pcsx2x6 install against the ECVF
# contract's env-init EnvironmentCapability and the canonical crosshair PNG
# locations (issue #173). Never invokes InitializationAction and never
# writes anything -- this only reports state; a caller decides separately
# whether and how to repair. States:
#   NotInstalled        -- folder missing or emulator executable not found.
#   Unknown              -- the ECVF contracts framework could not be
#                           consulted; callers must treat this the same as
#                           NotInstalled for any write-adjacent decision.
#   StockUninitialized   -- present, but PCSX2.ini fails the contract's
#                           InitializedVerifier (no inis\PCSX2.ini yet, or
#                           missing required sections).
#   Incomplete           -- PCSX2.ini is initialized but one or both
#                           canonical crosshair PNGs are missing.
#   Canonical            -- PCSX2.ini is initialized and both crosshair
#                           PNGs are present at the canonical location.
function Get-Pcsx2CrosshairPrerequisiteState {
    param([Parameter(Mandatory)][string]$Pcsx2Dir)

    $result = [ordered]@{
        State                 = 'NotInstalled'
        Pcsx2Dir              = $Pcsx2Dir
        DataRoot              = $null
        IniPath               = $null
        Reason                = $null
        HasP1Png              = $false
        HasP2Png              = $false
        Contract              = $null
        EnvironmentCapability = $null
    }

    if ([string]::IsNullOrWhiteSpace($Pcsx2Dir) -or -not (Test-Path -LiteralPath $Pcsx2Dir -PathType Container)) {
        $result.Reason = "pcsx2x6 install folder not found"
        return [pscustomobject]$result
    }

    try {
        $ecvfContractsModule = Join-Path $PSScriptRoot "scripts\TPMCertification.Contracts.psm1"
        if (-not (Test-Path -LiteralPath $ecvfContractsModule -PathType Leaf)) {
            $result.State  = 'Unknown'
            $result.Reason = "the ECVF contracts framework was not available to classify this install"
            return [pscustomobject]$result
        }
        Import-Module $ecvfContractsModule -Force -ErrorAction Stop
        $loaded = Get-TPMEmulatorContractV1 -ContractId 'pcsx2x6'
        $envCap = $loaded.Contract.EnvironmentCapabilities | Where-Object { $_.CapabilityId -eq 'env-init' } | Select-Object -First 1
        if (-not $envCap) {
            $result.State  = 'Unknown'
            $result.Reason = "pcsx2x6 contract has no 'env-init' EnvironmentCapability"
            return [pscustomobject]$result
        }
        $result.Contract              = $loaded.Contract
        $result.EnvironmentCapability = $envCap

        $present = Test-TPMEmulatorPresentV1 -Detector $envCap.PresenceDetector -InstallDir $Pcsx2Dir
        if (-not $present) {
            $result.Reason = "$($envCap.PresenceDetector.Source) not found under $Pcsx2Dir"
            return [pscustomobject]$result
        }

        $dataRoot = Resolve-TPMEnvironmentDataRootV1 -Resolver $envCap.DataRootResolver -InstallDir $Pcsx2Dir
        $result.DataRoot = $dataRoot
        if ($envCap.InitializedVerifier.RequiredPaths.Count -gt 0) {
            $result.IniPath = Join-Path $dataRoot $envCap.InitializedVerifier.RequiredPaths[0]
        }

        $p1Path = Join-Path $dataRoot "crosshairs\P1.png"
        $p2Path = Join-Path $dataRoot "crosshairs\P2.png"
        $result.HasP1Png = Test-Path -LiteralPath $p1Path -PathType Leaf
        $result.HasP2Png = Test-Path -LiteralPath $p2Path -PathType Leaf

        $verified = Test-TPMEnvironmentInitializedV1 -Verifier $envCap.InitializedVerifier -DataRoot $dataRoot
        if (-not $verified.Initialized) {
            $result.State  = 'StockUninitialized'
            $result.Reason = $verified.Reason
            return [pscustomobject]$result
        }

        if ($result.HasP1Png -and $result.HasP2Png) {
            $result.State = 'Canonical'
        } else {
            $result.State  = 'Incomplete'
            $result.Reason = "PCSX2.ini is initialized but one or both canonical crosshair PNGs are missing"
        }
        return [pscustomobject]$result
    } catch {
        $result.State  = 'Unknown'
        $result.Reason = "could not load or evaluate the pcsx2x6 emulator contract -- $_"
        return [pscustomobject]$result
    }
}

# Triggers the pcsx2x6 emulator's own -testconfig -portable first-run
# initialization mechanism (contract EnvironmentCapability 'env-init'),
# then re-verifies with the same read-only InitializedVerifier used for
# detection. Never hand-authors PCSX2.ini content -- CliInvocation only
# ever runs the emulator's own executable (issue #173). The caller must
# have already obtained user approval and confirmed no pcsx2x6 process is
# running; this function does not prompt and does not guard against a
# running process itself.
function Invoke-Pcsx2FirstRunSetup {
    param([Parameter(Mandatory)]$State)

    if ($State.State -ne 'StockUninitialized') {
        return [pscustomobject]@{ Success = $false; Reason = "first-run setup only applies to a StockUninitialized install (current state: $($State.State))" }
    }

    $ecvfContractsModule = Join-Path $PSScriptRoot "scripts\TPMCertification.Contracts.psm1"
    try {
        Import-Module $ecvfContractsModule -Force -ErrorAction Stop
        Invoke-TPMEnvironmentInitializationActionV1 -Action $State.EnvironmentCapability.InitializationAction -InstallDir $State.Pcsx2Dir | Out-Null
    } catch {
        Write-Log "Pcsx2FirstRunSetup: initialization action failed -- $_"
        return [pscustomobject]@{ Success = $false; Reason = "first-run initialization failed -- $_" }
    }

    $reverified = Test-TPMEnvironmentInitializedV1 -Verifier $State.EnvironmentCapability.InitializedVerifier -DataRoot $State.DataRoot
    if (-not $reverified.Initialized) {
        Write-Log "Pcsx2FirstRunSetup: post-init verification failed -- $($reverified.Reason)"
        return [pscustomobject]@{ Success = $false; Reason = "PCSX2.ini still not initialized after running first-run setup -- $($reverified.Reason)" }
    }

    Write-Log "Pcsx2FirstRunSetup: first-run initialization succeeded for $($State.Pcsx2Dir)"
    return [pscustomobject]@{ Success = $true; Reason = $null }
}

# Read-only report of the current on-disk cursor_path values for the
# emulator-owned USB1/USB2 guncon2 device (contract SettingPaths
# 'USB1.guncon2_cursor_path[jvsmode=lightgun]' /
# 'USB2.guncon2_cursor_path[jvsmode=lightgun]', Owner=Emulator,
# WritePolicy=NeverWrite). Uses the real on-disk section/key format
# confirmed in contracts\pcsx2x6\evidence.md#ev-usb-ini-contract -- [USB1]/
# [USB2] sections, guncon2_cursor_path key -- not the [USB Port N guncon2]/
# cursor_path format Set-Pcsx2CursorPaths still targets for its (always
# contract-denied) write attempt. That mismatch has no effect on write
# safety -- the write is denied before any section is even parsed -- but it
# does mean Set-Pcsx2CursorPaths cannot be reused to observe the real
# value, hence this separate, strictly read-only reader. Never writes
# anything.
function Get-Pcsx2CursorPathReport {
    param([Parameter(Mandatory)][string]$IniPath)

    if (-not (Test-Path -LiteralPath $IniPath -PathType Leaf)) {
        return [pscustomobject]@{ Available = $false; USB1CursorPath = $null; USB2CursorPath = $null; Reason = "PCSX2.ini not found at $IniPath" }
    }
    try {
        $lines = [System.IO.File]::ReadAllLines($IniPath)
    } catch {
        return [pscustomobject]@{ Available = $false; USB1CursorPath = $null; USB2CursorPath = $null; Reason = "could not read PCSX2.ini -- $_" }
    }

    $values = @{ 'usb1' = $null; 'usb2' = $null }
    $sect = ''
    foreach ($ln in $lines) {
        $t = $ln.Trim()
        if ($t -match '^\[(.+)\]$') { $sect = $matches[1].ToLower(); continue }
        if (($sect -eq 'usb1' -or $sect -eq 'usb2') -and $t -match '^guncon2_cursor_path\s*=\s*(.*)$') {
            $values[$sect] = $matches[1].Trim()
        }
    }
    return [pscustomobject]@{
        Available      = $true
        USB1CursorPath = $values['usb1']
        USB2CursorPath = $values['usb2']
        Reason         = $null
    }
}

# Crosshair setup wizard: HTML preview of all crosshair PNGs, P1/P2 picker,
# deploy selected images to all registered lightgun game folders. Optionally
# hides the hardware cursor by setting HideCursor/DisableCursor=1 in every
# lightgun UserProfile (backs up profiles first).
function Invoke-CrosshairSetup {
    param([string]$UserProfilesDir, [string]$GamesInstallFolder, [string]$TpRoot)

    $crosshairsDir = Join-Path $PSScriptRoot "Crosshairs"
    $previewPath   = Join-Path $PSScriptRoot "TeknoParrot-Crosshairs-Preview.html"

    if (-not (Test-Path -LiteralPath $crosshairsDir)) {
        Write-Host "  ERROR: Crosshairs folder not found: $crosshairsDir" -ForegroundColor Red
        Write-Host "  Place PNG crosshair files in a 'Crosshairs' subfolder next to the script." -ForegroundColor Yellow
        Write-Log "Crosshairs: Crosshairs folder not found"; return
    }

    # Scan and validate -- any PNG in the folder is a candidate
    $allFiles = @(Get-ChildItem -LiteralPath $crosshairsDir -Filter "*.png" -File -ErrorAction SilentlyContinue |
                     Sort-Object Name)
    $valid   = [System.Collections.Generic.List[string]]::new()
    $invalid = [System.Collections.Generic.List[string]]::new()

    foreach ($f in $allFiles) {
        if (Test-PngFile -Path $f.FullName) { $valid.Add($f.FullName) }
        else {
            $invalid.Add($f.Name)
            Write-Log "Crosshairs: rejected invalid PNG -- $($f.Name)"
        }
    }

    if ($invalid.Count -gt 0) {
        Write-Host ("  WARNING: {0} file(s) failed PNG validation and were skipped:" -f $invalid.Count) -ForegroundColor Yellow
        foreach ($n in $invalid) { Write-Host "    $n" -ForegroundColor DarkGray }
    }
    if ($valid.Count -eq 0) {
        Write-Host "  No valid PNG crosshairs found in: $crosshairsDir" -ForegroundColor Red
        Write-Log "Crosshairs: no valid PNGs found"; return
    }

    Write-Host ("  Found {0} valid crosshair(s). Generating preview..." -f $valid.Count) -ForegroundColor Cyan
    Export-CrosshairPreview -CrosshairPaths $valid.ToArray() -OutPath $previewPath
    Write-Host "  Preview: $previewPath" -ForegroundColor Cyan
    Write-Host "  Opening in browser -- browse the grid, then come back here." -ForegroundColor DarkCyan
    if (Test-Path -LiteralPath $previewPath -PathType Leaf) { Start-Process -FilePath $previewPath }
    Write-Host ""

    # Remembers the last P1/P2 choice (by filename, not index -- indices shift
    # if PNGs are added/removed from the Crosshairs folder between runs) so a
    # re-run doesn't require re-finding/re-entering the same numbers. A saved
    # name that no longer exists in $valid is silently ignored.
    $crosshairStatePath = Join-Path $PSScriptRoot "TeknoParrot-Manager-crosshairs.json"
    $lastP1Idx = $null; $lastP2Idx = $null
    if (Test-Path -LiteralPath $crosshairStatePath) {
        try {
            $crosshairState = Get-Content -LiteralPath $crosshairStatePath -Raw | ConvertFrom-Json
            if ($crosshairState.P1) {
                $hit = for ($i = 0; $i -lt $valid.Count; $i++) { if ([System.IO.Path]::GetFileNameWithoutExtension($valid[$i]) -eq $crosshairState.P1) { $i; break } }
                if ($null -ne $hit) { $lastP1Idx = $hit }
            }
            if ($crosshairState.P2) {
                $hit = for ($i = 0; $i -lt $valid.Count; $i++) { if ([System.IO.Path]::GetFileNameWithoutExtension($valid[$i]) -eq $crosshairState.P2) { $i; break } }
                if ($null -ne $hit) { $lastP2Idx = $hit }
            }
        } catch { Write-Log "Crosshairs: could not read last-used state -- $_" }
    }

    # Pick P1
    $p1Idx = $null
    while ($null -eq $p1Idx) {
        $promptText = if ($null -ne $lastP1Idx) {
            "  P1 crosshair index (0-{0}, Enter for last used: {1} {2})" -f ($valid.Count - 1), $lastP1Idx, [System.IO.Path]::GetFileNameWithoutExtension($valid[$lastP1Idx])
        } else { "  P1 crosshair index (0-{0})" -f ($valid.Count - 1) }
        $raw = (Read-HostSafe $promptText)
        if ($raw -eq '' -and $null -ne $lastP1Idx) { $p1Idx = $lastP1Idx }
        elseif ($raw -match '^\d+$' -and $raw.Length -le 9 -and [int]$raw -lt $valid.Count) { $p1Idx = [int]$raw }
        else { Write-Host ("  Enter a number between 0 and {0}." -f ($valid.Count - 1)) -ForegroundColor Yellow }
    }
    # Pick P2
    $p2Idx = $null
    while ($null -eq $p2Idx) {
        $promptText = if ($null -ne $lastP2Idx) {
            "  P2 crosshair index (0-{0}, or same as P1, Enter for last used: {1} {2})" -f ($valid.Count - 1), $lastP2Idx, [System.IO.Path]::GetFileNameWithoutExtension($valid[$lastP2Idx])
        } else { "  P2 crosshair index (0-{0}, or same as P1)" -f ($valid.Count - 1) }
        $raw = (Read-HostSafe $promptText)
        if ($raw -eq '' -and $null -ne $lastP2Idx) { $p2Idx = $lastP2Idx }
        elseif ($raw -match '^\d+$' -and $raw.Length -le 9 -and [int]$raw -lt $valid.Count) { $p2Idx = [int]$raw }
        else { Write-Host ("  Enter a number between 0 and {0}." -f ($valid.Count - 1)) -ForegroundColor Yellow }
    }

    $p1Name = [System.IO.Path]::GetFileNameWithoutExtension($valid[$p1Idx])
    $p2Name = [System.IO.Path]::GetFileNameWithoutExtension($valid[$p2Idx])
    Write-Host ""
    Write-Host "  P1: $p1Name    P2: $p2Name" -ForegroundColor Green
    $crosshairConfirm = (Read-HostSafe "  Apply these crosshairs? (Y/N, default Y)" -Default 'Y').Trim().ToUpper()
    if ($crosshairConfirm -ne 'Y') {
        Write-Host "  Crosshair setup cancelled. No files were changed." -ForegroundColor Yellow
        Write-Log "Crosshairs: cancelled before deployment."
        return
    }
    Write-Log "Crosshairs: P1=$p1Name  P2=$p2Name"

    try {
        [System.IO.File]::WriteAllText($crosshairStatePath, ([ordered]@{ P1 = $p1Name; P2 = $p2Name } | ConvertTo-Json), (New-Object System.Text.UTF8Encoding $false))
    } catch { Write-Log "Crosshairs: could not save last-used state -- $_" }

    # Locate ElfLdr2 folder -- search common names then any elf-named subfolder
    $elfDir = $null
    foreach ($candidate in @("ElfLdr2","ElfLoader2","elf","elf2","ElfLdr")) {
        $try = Join-Path $TpRoot $candidate
        if (Test-Path -LiteralPath $try) { $elfDir = $try; break }
    }
    if (-not $elfDir) {
        $elfDir = Get-ChildItem -LiteralPath $TpRoot -Directory -ErrorAction SilentlyContinue |
                  Where-Object { $_.Name -imatch 'elf' } |
                  Select-Object -First 1 -ExpandProperty FullName
    }

    # Locate pcsx2x6 folder -- shared resolver, see Resolve-Pcsx2Directory.
    $pcsx2Dir = Resolve-Pcsx2Directory -TeknoParrotRoot $TpRoot

    # Deploy
    Write-Host ""
    Write-Host "  Deploying to lightgun games..." -ForegroundColor Cyan
    $deployed = 0; $skipped = 0; $errors = 0; $elfDeployed = $false; $pcsx2Deployed = $false

    $xmlFiles = Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Directory.Name -ne "FullBackup" }

    foreach ($pf in $xmlFiles) {
        try {
            $doc     = Read-Xml $pf.FullName
            if ($null -eq $doc.GameProfile) { continue }
            $gunNode = $doc.GameProfile.SelectSingleNode("GunGame")
            if (-not $gunNode -or $gunNode.InnerText -ne "true") { continue }

            $emuType = ""
            $etNode  = $doc.GameProfile.SelectSingleNode("EmulatorType")
            if ($etNode) { $emuType = $etNode.InnerText.Trim() }

            if ($emuType -eq "ElfLdr2") {
                # All ElfLdr2 lightgun games share one folder -- deploy once
                if (-not $elfDeployed) {
                    $dest = if ($elfDir) { $elfDir } else { $TpRoot }
                    Copy-Item -LiteralPath $valid[$p1Idx] -Destination (Join-Path $dest "P1.png") -Force -ErrorAction Stop
                    Copy-Item -LiteralPath $valid[$p2Idx] -Destination (Join-Path $dest "P2.png") -Force -ErrorAction Stop
                    Write-Host ("    ElfLdr2 -> {0}" -f $dest) -ForegroundColor Green
                    Write-Log "Crosshairs: deployed to ElfLdr2 folder $dest"
                    $elfDeployed = $true
                }
                $deployed++; continue
            }

            if ($emuType -eq "Pcsx2x6") {
                # All Pcsx2x6 lightgun games share one emulator folder -- deploy once
                # Also updates inis\PCSX2.ini with the cursor_path for each USB port.
                if (-not $pcsx2Deployed) {
                    if ($pcsx2Dir) {
                        $pcsx2Deployed = $true
                        $prereqState = Get-Pcsx2CrosshairPrerequisiteState -Pcsx2Dir $pcsx2Dir

                        if ($prereqState.State -eq 'StockUninitialized') {
                            Write-Host ""
                            Write-Host "  PCSX2 Crosshair Setup Required" -ForegroundColor Cyan
                            Write-Host ("    TPM found pcsx2x6 installed but not yet initialized for TeknoParrot ({0})." -f $prereqState.Reason) -ForegroundColor DarkGray
                            Write-Host "    TPM can trigger the emulator's own first-run initialization, then install the crosshair assets and verify the result." -ForegroundColor DarkGray
                            $firstRunAnswer = (Read-HostSafe "  Configure Automatically? (Y/N)").ToUpper()
                            if ($firstRunAnswer -eq "Y") {
                                if (-not (Wait-TpmForProcessClose -ProcessNames @('pcsx2-qtx64') -FriendlyName 'PCSX2')) {
                                    Write-Host "    Crosshair setup cancelled without changes. The selected crosshairs were not deployed." -ForegroundColor Yellow
                                    Write-Log "Crosshairs: Pcsx2x6 first-run setup paused while process remained open"
                                } else {
                                    $firstRun = Invoke-Pcsx2FirstRunSetup -State $prereqState
                                    if ($firstRun.Success) {
                                        Write-Host "    First-run initialization succeeded." -ForegroundColor Green
                                        $prereqState = Get-Pcsx2CrosshairPrerequisiteState -Pcsx2Dir $pcsx2Dir
                                    } else {
                                        Write-Host ("    FAILED: {0}" -f $firstRun.Reason) -ForegroundColor Red
                                        Write-Log "Crosshairs: Pcsx2x6 first-run setup failed -- $($firstRun.Reason)"
                                    }
                                }
                            } else {
                                Write-Host "    Skipped -- Pcsx2x6 crosshair setup needs an initialized PCSX2.ini to continue." -ForegroundColor Yellow
                                Write-Log "Crosshairs: Pcsx2x6 first-run setup declined by user"
                            }
                        }

                        if ($prereqState.State -eq 'StockUninitialized') {
                            # Still not initialized (declined, process remained
                            # open, or the trigger failed) -- do not place
                            # assets or touch cursor_path against an install
                            # PCSX2.ini that has never been validated.
                            $skipped++; continue
                        }

                        # ECVF is fail-closed for every write-adjacent action:
                        # an Unknown contract state is treated as NotInstalled
                        # for deployment decisions, while the original state
                        # remains available for reporting and diagnostics.
                        $assetCopyState = if ($prereqState.State -eq 'Unknown') { 'NotInstalled' } else { $prereqState.State }
                        if ($assetCopyState -eq 'NotInstalled') {
                            Write-Host ("    SKIPPED: Pcsx2x6 prerequisite state is {0}; no crosshair assets or cursor_path handling performed." -f $prereqState.State) -ForegroundColor Yellow
                            Write-Log ("Crosshairs: Pcsx2x6 deployment skipped -- prerequisite state {0} ({1})" -f $prereqState.State, $prereqState.Reason)
                            $skipped++; continue
                        }

                        # Deploy under the contract-resolved DataRoot, not a
                        # reconstructed default path. This preserves portable.txt
                        # and any future resolver behavior in one ownership boundary.
                        $dataRoot = $prereqState.DataRoot
                        if ([string]::IsNullOrWhiteSpace($dataRoot)) {
                            Write-Host ("    SKIPPED: Pcsx2x6 DataRoot could not be resolved for prerequisite state {0}; no crosshair assets or cursor_path handling performed." -f $prereqState.State) -ForegroundColor Yellow
                            Write-Log ("Crosshairs: Pcsx2x6 deployment skipped -- DataRoot unavailable for prerequisite state {0}" -f $prereqState.State)
                            $deployed++; continue
                        }
                        $crosshairSubDir = Join-Path $dataRoot "crosshairs"
                        if (-not (Test-Path -LiteralPath $crosshairSubDir)) {
                            [void](New-Item -ItemType Directory -Path $crosshairSubDir -Force -ErrorAction Stop)
                        }
                        $p1Dest = Join-Path $crosshairSubDir "P1.png"
                        $p2Dest = Join-Path $crosshairSubDir "P2.png"
                        Copy-Item -LiteralPath $valid[$p1Idx] -Destination $p1Dest -Force -ErrorAction Stop
                        Copy-Item -LiteralPath $valid[$p2Idx] -Destination $p2Dest -Force -ErrorAction Stop
                        # ECVF-correct ini path (contracts\pcsx2x6\evidence.md#ev-portable-root):
                        # DataRoot\inis\PCSX2.ini, not a bare "$pcsx2Dir\inis\PCSX2.ini" --
                        # the real ini lives under the resolved TeknoParrot data-root subfolder.
                        $iniPath = $prereqState.IniPath
                        if ($iniPath -and (Test-Path -LiteralPath $iniPath)) {
                            $iniUpdated = Set-Pcsx2CursorPaths -IniPath $iniPath -P1Path $p1Dest -P2Path $p2Dest
                            $iniStatus = if ($iniUpdated) { "PCSX2.ini updated" } else { "PNGs copied; PCSX2.ini cursor_path left untouched, see note above" }
                            Write-Host ("    Pcsx2x6 -> {0}  ({1})" -f $pcsx2Dir, $iniStatus) -ForegroundColor Green
                            # ECVF: cursor_path under [USB1]/[USB2] is emulator-owned,
                            # WritePolicy=NeverWrite -- this reports the current
                            # on-disk value for operator visibility, it never writes.
                            $cursorReport = Get-Pcsx2CursorPathReport -IniPath $iniPath
                            if ($cursorReport.Available) {
                                $usb1Display = if ($cursorReport.USB1CursorPath) { $cursorReport.USB1CursorPath } else { "(not set)" }
                                $usb2Display = if ($cursorReport.USB2CursorPath) { $cursorReport.USB2CursorPath } else { "(not set)" }
                                Write-Host ("      cursor_path is emulator-managed: USB1={0}  USB2={1}  (PCSX2 clears this automatically when JVS mode is LIGHTGUN -- no action needed)" -f $usb1Display, $usb2Display) -ForegroundColor DarkGray
                            }
                        } else {
                            Write-Host ("    Pcsx2x6 -> {0}  (PCSX2.ini not found; PNGs copied)" -f $pcsx2Dir) -ForegroundColor Green
                            Write-Log "Crosshairs: Pcsx2x6 PCSX2.ini not found at $iniPath"
                        }
                        Write-Log "Crosshairs: deployed to Pcsx2x6 folder $pcsx2Dir"
                    } else {
                        Write-Host "    Pcsx2x6: emulator folder not found in TeknoParrot root -- skipped" -ForegroundColor Yellow
                        Write-Log "Crosshairs: Pcsx2x6 folder not found in $TpRoot"
                    }
                }
                $deployed++; continue
            }

            # Standard game: copy to the game exe directory
            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { $skipped++; continue }
            $exeDir = [System.IO.Path]::GetDirectoryName($gpNode.InnerText.Trim())
            if ([string]::IsNullOrWhiteSpace($exeDir) -or -not (Test-Path -LiteralPath $exeDir)) { $skipped++; continue }

            Copy-Item -LiteralPath $valid[$p1Idx] -Destination (Join-Path $exeDir "P1.png") -Force -ErrorAction Stop
            Copy-Item -LiteralPath $valid[$p2Idx] -Destination (Join-Path $exeDir "P2.png") -Force -ErrorAction Stop
            Write-Host ("    {0} -> {1}" -f $pf.BaseName, $exeDir) -ForegroundColor Green
            Write-Log "Crosshairs: deployed $($pf.BaseName) -> $exeDir"
            $deployed++
        } catch {
            Write-Host ("    FAILED {0}: {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "Crosshairs: error on $($pf.BaseName) -- $_"
            $errors++
        }
    }

    Write-Host ""
    Write-Host ("  Deployed : {0} lightgun game(s)" -f $deployed) -ForegroundColor Green
    if ($skipped -gt 0) { Write-Host ("  Skipped  : {0} (no path or folder not found)" -f $skipped) -ForegroundColor DarkGray }
    if ($errors  -gt 0) { Write-Host ("  Errors   : {0}" -f $errors) -ForegroundColor Red }
    Write-Log ("Crosshairs: done. Deployed={0} Skipped={1} Errors={2}" -f $deployed, $skipped, $errors)

    Write-Host ""
    $hideCursor = (Read-HostSafe "  Also hide the Windows cursor for all lightgun games? (Y/N)").ToUpper()
    if ($hideCursor -eq "Y") {
        Write-Host ""
        Invoke-CursorHideSetup -UserProfilesDir $UserProfilesDir
    }
    return [pscustomobject]@{ Succeeded = ($errors -eq 0 -and $deployed -gt 0); Deployed = $deployed; Skipped = $skipped; Errors = $errors }
}

# =============================================================================
# Sets the cursor-hide field (HideCursor / "Hide Cursor" / DisableCursor) to 1
# in every registered lightgun UserProfile. Backs up UserProfiles first since
# it modifies XMLs. Skips profiles that have no cursor field or are already set.
function Invoke-CursorHideSetup {
    param([string]$UserProfilesDir)

    $cursorFields = @("HideCursor", "Hide Cursor", "DisableCursor")

    $backupRoot = Join-Path $UserProfilesDir "FullBackup"
    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss")
    $backupPath = Join-Path $backupRoot ("CursorHide_" + $timestamp)
    try {
        [void][System.IO.Directory]::CreateDirectory($backupRoot)
        [void][System.IO.Directory]::CreateDirectory($backupPath)
    } catch {
        Write-Host "  ERROR: Could not create backup folder: $_" -ForegroundColor Red
        Write-Log "CursorHide: backup failed -- $_"
        return
    }
    $backupCopyErrs = $null
    # Copy-Item receives FileInfo/DirectoryInfo objects from the pipeline
    # (not path strings), so pipeline binding already bypasses wildcard
    # expansion -- safe even with [, ], $ in game folder names. If this
    # source is ever changed to raw path strings, add -LiteralPath there.
    Get-ChildItem -LiteralPath $UserProfilesDir | Where-Object { $_.Name -ne "FullBackup" } |
        Copy-Item -Destination $backupPath -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable backupCopyErrs
    if ($backupCopyErrs.Count -gt 0) {
        Write-Host ("  WARNING: {0} file(s) could not be backed up." -f $backupCopyErrs.Count) -ForegroundColor Yellow
        Write-Log "CursorHide: backup had $($backupCopyErrs.Count) error(s)"
    }
    Write-Host ("  Backup: {0}" -f $backupPath) -ForegroundColor DarkGray
    Write-Log "CursorHide: backup at $backupPath"

    $updated = 0; $alreadySet = 0; $noField = 0; $errors = 0

    $xmlFiles = Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Directory.Name -ne "FullBackup" }

    foreach ($pf in $xmlFiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if ($null -eq $doc.GameProfile) { continue }
            $gunNode = $doc.GameProfile.SelectSingleNode("GunGame")
            if (-not $gunNode -or $gunNode.InnerText -ne "true") { continue }

            $changed = $false
            $wasSet  = $false
            foreach ($fieldName in $cursorFields) {
                $fi = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $fieldName)]")
                if ($null -eq $fi) { continue }
                $fv = $fi.SelectSingleNode("FieldValue")
                if ($null -eq $fv) { continue }
                if ($fv.InnerText -eq "1") { $wasSet = $true; continue }
                $fv.InnerText = "1"
                $changed = $true
            }

            if ($changed) {
                Save-Xml $doc $pf.FullName
                Write-Host ("    Updated : {0}" -f $pf.BaseName) -ForegroundColor Green
                Write-Log "CursorHide: updated $($pf.BaseName)"
                $updated++
            } elseif ($wasSet) {
                $alreadySet++
            } else {
                $noField++
            }
        } catch {
            Write-Host ("    FAILED  {0}: {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "CursorHide: error on $($pf.BaseName) -- $_"
            $errors++
        }
    }

    Write-Host ""
    Write-Host ("  Updated  : {0} lightgun game(s)" -f $updated) -ForegroundColor Green
    if ($alreadySet -gt 0) { Write-Host ("  Already  : {0} (cursor already hidden)" -f $alreadySet) -ForegroundColor DarkGray }
    if ($noField   -gt 0) { Write-Host ("  No field : {0} (profile has no cursor field)" -f $noField) -ForegroundColor DarkGray }
    if ($errors    -gt 0) { Write-Host ("  Errors   : {0}" -f $errors) -ForegroundColor Red }
    Write-Log ("CursorHide: done. Updated={0} AlreadySet={1} NoField={2} Errors={3}" -f $updated, $alreadySet, $noField, $errors)
}

# =============================================================================
# Extracts a ZIP to a destination directory using \\?\ extended-length paths on
# every file write, bypassing Windows' 260-character MAX_PATH limit. Replaces
# ZipFile::ExtractToDirectory which throws PathTooLongException for games with
# deeply-nested internal paths. Includes a zip-slip guard.
function Expand-ZipFileSafe {
    param([string]$ZipPath, [string]$DestDir, [string]$GameName = '')

    # GetFullPath on the (short) base is safe. We deliberately avoid calling
    # GetFullPath on the combined base+entry path: on .NET 4.x (PS 5.1) that
    # throws PathTooLongException before \\?\ is ever applied, defeating the
    # whole purpose of this function.
    $destFull  = [System.IO.Path]::GetFullPath($DestDir).TrimEnd('\')
    # The \\?\ long-path prefix has a different form for UNC paths
    # (\\server\share\...) than for drive-letter paths -- a naive
    # '\\?\' + $destFull concatenation produces an invalid
    # '\\?\\\server\share\...' for UNC destinations. Build the correct
    # prefix once so every long-path target below uses the right form.
    $longPrefixBase = if ($destFull -match '^\\\\[^\?]') {
        '\\?\UNC\' + $destFull.Substring(2)
    } else {
        '\\?\' + $destFull
    }
    $label     = if ($GameName) { $GameName } else { [System.IO.Path]::GetFileNameWithoutExtension($ZipPath) }
    $archive   = $null
    try {
        $archive   = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
        $fileCount = @($archive.Entries | Where-Object { $_.Name -ne '' }).Count
        $current   = 0
        foreach ($entry in $archive.Entries) {
            $rel = $entry.FullName.Replace('/', '\').TrimStart('\')

            # Zip-slip guard: reject traversal (..) and absolute paths.
            # String-level check avoids the 260-char limit of GetFullPath on
            # .NET 4.x. Rooted check blocks entries like C:\evil\path.exe.
            if ($rel -match '(^|\\)\.\.($|\\)' -or [System.IO.Path]::IsPathRooted($rel)) {
                throw "ZIP entry escapes destination folder: $($entry.FullName)"
            }

            # Directory entry: Name is empty string when FullName ends with /
            if ($entry.Name -eq '' -or $rel.EndsWith('\')) {
                [void][System.IO.Directory]::CreateDirectory($longPrefixBase + '\' + $rel.TrimEnd('\'))
                continue
            }

            $current++
            if ($fileCount -gt 0) {
                $pct = [Math]::Min(100, [int](($current / $fileCount) * 100))
                Write-Progress -Activity "Extracting: $label" `
                               -Status ("File {0} of {1}" -f $current, $fileCount) `
                               -PercentComplete $pct
            }

            $longTarget = $longPrefixBase + '\' + $rel
            # CreateDirectory is idempotent; no Exists check needed (also avoids TOCTOU).
            [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($longTarget))

            $src = $entry.Open()
            try {
                $dst = [System.IO.File]::Open($longTarget, [System.IO.FileMode]::Create,
                           [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
                try   { $src.CopyTo($dst) }
                finally { $dst.Dispose() }
            } finally { $src.Dispose() }
        }
    } finally {
        if ($archive) { $archive.Dispose() }
        Write-Progress -Activity "Extracting: $label" -Completed
    }
}

# Extracts NAS ZIPs to a local folder. Tracks state to skip unchanged games.
# Never deletes local games. ZIP base names listed in $noSync are skipped.
# If $onlySync is non-empty, only ZIPs whose base name is in the list are extracted.
function Invoke-AutoSync {
    param([string]$zipSource, [string]$installFolder, [string]$syncStatePath,
          $noSync = @(), $onlySync = @(), [bool]$retroBat = $false, [bool]$DryRun = $false,
          [hashtable]$datIndex = $null, [string]$userProfilesDir = '')

    $syncState = @{}
    if (Test-Path -LiteralPath $syncStatePath) {
        try {
            $loaded = Get-Content -LiteralPath $syncStatePath -Raw | ConvertFrom-Json
            foreach ($prop in $loaded.PSObject.Properties) { $syncState[$prop.Name] = $prop.Value }
        } catch { Write-Log "AutoSync: could not read sync state -- starting fresh." }
    }

    $zipFiles = @(Get-ChildItem -LiteralPath $zipSource -Filter *.zip -ErrorAction SilentlyContinue)
    if (-not $zipFiles -or $zipFiles.Count -eq 0) {
        Write-Host "  No ZIP files found in source. Skipping extraction." -ForegroundColor Yellow
        $subdirHits = @(Get-ChildItem -LiteralPath $zipSource -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $c = (Get-ChildItem -LiteralPath $_.FullName -Filter *.zip -ErrorAction SilentlyContinue | Measure-Object).Count
            if ($c -gt 0) { [PSCustomObject]@{ Path = $_.FullName; Count = $c } }
        })
        if ($subdirHits.Count -gt 0) {
            Write-Host "  Tip: ZIPs found one level down -- point the source path at one of these directly:" -ForegroundColor Cyan
            foreach ($sd in $subdirHits) {
                Write-Host "    $($sd.Path)  ($($sd.Count) ZIPs)" -ForegroundColor DarkCyan
            }
        }
        return @{ Synced = 0; UpToDate = 0; Failed = 0; Skipped = 0; WouldSync = 0 }
    }

$syncedNames = New-Object System.Collections.Generic.List[string]
    $synced = 0; $upToDate = 0; $failed = 0; $skipped = 0; $wouldSync = 0

    if ($onlySync.Count -gt 0) {
        Write-Host "  Whitelist active: only extracting $($onlySync.Count) game(s) listed in onlySync." -ForegroundColor Cyan
    }

    # Build the shared extracted-folder resolver map so AutoSync and the
    # interactive picker agree on which ZIPs are already present.
    $normalizedFolderMap = Get-StagingFolderMap $installFolder

    foreach ($zip in $zipFiles) {
        $rawName    = [System.IO.Path]::GetFileNameWithoutExtension($zip.Name)
        if ($noSync -contains $rawName) {
            Write-Host "  Skipped (override) : $rawName" -ForegroundColor DarkGray
            $skipped++; continue
        }
        # Skip collection metadata files (changelog, game notes, readme).
        # These start with "!TeknoParrot Collection" regardless of date suffix.
        if ($rawName -like '!TeknoParrot Collection*') {
            Write-Host "  Skipped (metadata)  : $rawName" -ForegroundColor DarkGray
            $skipped++; continue
        }
        # If a whitelist is active, skip anything not on it.
        if ($onlySync.Count -gt 0 -and $onlySync -notcontains $rawName) {
            $skipped++; continue
        }
        # Use the raw ZIP base name as the folder name so it matches the
        # collection's naming convention exactly -- e.g.
        # "Game Name (ver) (date) [Platform] [TP]". This avoids garbled names
        # and prevents duplicate folders alongside manually-extracted games.
        $extractFolderName = if ($retroBat) { "$rawName.teknoparrot" } else { $rawName }
        $extractDir = Join-Path $installFolder $extractFolderName
        # Defence in depth: confirm the resolved folder still lands inside
        # $installFolder before any destructive use below. A ZIP base name
        # cannot legally contain \ or / on Windows, so this should never
        # trip, but every other site that joins a script folder with an
        # externally-influenced name carries this same guard.
        if (-not (Test-PathInside $extractDir $installFolder)) {
            Write-Host "  Skipped (unsafe path) : $rawName" -ForegroundColor Red
            Write-Log "AutoSync: skipped '$rawName' -- resolved extract path '$extractDir' is outside install folder '$installFolder'"
            $skipped++; continue
        }
        # Sentinel lives next to the game folder (not inside it) so we do not
        # need to pre-create the game directory. Expand-Archive creates the
        # directory itself; pre-creating it caused PS 5.1 to throw "already
        # exists" even when -Force was supplied.
        $sentinel   = Join-Path $installFolder "$extractFolderName.extracting"
        $nasModStr  = $zip.LastWriteTimeUtc.ToString("o")
        $stored     = $syncState[$rawName]

        # Resolve an existing, non-empty folder using exact naming,
        # RetroBat suffixes, path-limit aliases, dat/profile identity, and a
        # conservative fuzzy metadata match. See issue #66.
        $matchedFolder = Resolve-ExtractedGameFolder -RawZipName $rawName -InstallFolder $installFolder -FolderMap $normalizedFolderMap -DatIndex $datIndex -UserProfilesDir $userProfilesDir

        $needsSync = $false; $reason = ""
        if ($null -eq $stored) {
            # Game not yet tracked. Only treat the folder as "already extracted"
            # if the matched folder (exact or old-convention) has content --
            # empty folders are failed extractions that should be retried.
            $hasContent = $matchedFolder -and (-not (Test-Path -LiteralPath $sentinel))
            if ($hasContent) {
                $syncState[$rawName] = [ordered]@{
                    NasSize = $zip.Length; NasLastModified = $nasModStr
                    LocalPath = $matchedFolder; SyncedAt = (Get-Date).ToUniversalTime().ToString("o")
                }
                $label = if ($matchedFolder -ne $extractDir) { "  Already extracted  : $rawName`n    (old name: $(Split-Path $matchedFolder -Leaf))" } else { "  Already extracted  : $rawName" }
                Write-Host $label -ForegroundColor DarkGray
                $upToDate++; continue
            }
            $needsSync = $true; $reason = "new"
        } elseif ([long]$stored.NasSize -ne $zip.Length -or $stored.NasLastModified -ne $nasModStr) {
            $needsSync = $true; $reason = "changed on NAS"
        } elseif (-not (($stored.LocalPath -and (Test-Path -LiteralPath $stored.LocalPath)) -or (Test-Path -LiteralPath $extractDir))) {
            if ($matchedFolder -and (Test-Path -LiteralPath $matchedFolder)) {
                # Folder was renamed since the last sync (e.g. a manual PATH
                # TOO LONG short-name rename per ACTION REQUIRED, issue #13)
                # -- found via the normalised map. Heal the stored path so
                # future runs hit the Test-Path fast path above directly.
                $stored.LocalPath = $matchedFolder
            } else {
                $needsSync = $true; $reason = "not extracted"
            }
        } elseif (Test-Path -LiteralPath $sentinel) {
            $needsSync = $true; $reason = "incomplete previous extraction"
        }

        if (-not $needsSync) { Write-Host "  Up to date : $rawName" -ForegroundColor DarkGray; $upToDate++; continue }

        if ($DryRun) {
            Write-Host "  Would extract ($reason) : $rawName" -ForegroundColor Yellow
            Write-Log "AutoSync DryRun: would extract $rawName ($reason)"
            $wouldSync++
            continue
        }

        Write-Host "  Extracting ($reason) : $rawName" -ForegroundColor Yellow
        Write-Log "AutoSync: extracting $rawName ($reason)"

        # The sentinel's entire lifecycle -- creation and guaranteed cleanup --
        # is owned by this single try/finally. The finally block has one
        # responsibility: remove the sentinel. It runs unconditionally on
        # success, on any exception, on continue, and on Ctrl+C
        # (PipelineStoppedException), because try/finally always executes its
        # finally clause before control leaves the block, regardless of how.
        try {
            # Create sentinel before any file operations. An unremoved sentinel
            # on the next run triggers a re-extraction, keeping state consistent.
            # If creation itself fails, the outer catch handles it and the
            # finally still runs (Remove-Item on a missing file is a no-op).
            [System.IO.File]::WriteAllText($sentinel, '', (New-Object System.Text.UTF8Encoding $false))

            # All extraction work is nested here so the sentinel's finally
            # always fires after it completes, regardless of how it exits.
            try {
                # Clear any existing (stale or partial) game folder before
                # extracting. Treat removal failures as fatal: a partial old
                # folder combined with a fresh extraction produces a corrupt
                # mixed-version game.
                if (Test-Path -LiteralPath $extractDir) {
                    $removeErrs = @()
                    Remove-Item -LiteralPath $extractDir -Recurse -Force `
                                -ErrorAction SilentlyContinue -ErrorVariable removeErrs
                    if ($removeErrs.Count -gt 0) {
                        Write-Host "    FAILED (could not clear existing folder -- files may be in use):" -ForegroundColor Red
                        Write-Host "    $($removeErrs[0])" -ForegroundColor Red
                        Write-Log "AutoSync: FAILED $rawName -- could not clear $extractDir : $($removeErrs[0])"
                        # Remove the sync-state entry so next run re-attempts rather
                        # than treating a corrupt/partial folder as up to date.
                        [void]$syncState.Remove($rawName)
                        $failed++
                        continue   # outer finally fires before the loop advances
                    }
                }
                # Expand-ZipFileSafe uses \\?\ extended-length paths for every file
                # write, bypassing MAX_PATH. The destination folder does not exist
                # yet (cleared above); the function creates it during extraction.
                Expand-ZipFileSafe -ZipPath $zip.FullName -DestDir $extractDir -GameName $rawName
                $syncState[$rawName] = [ordered]@{
                    NasSize = $zip.Length; NasLastModified = $nasModStr
                    LocalPath = $extractDir; SyncedAt = (Get-Date).ToUniversalTime().ToString("o")
                }
                Write-Host "    -> $extractDir" -ForegroundColor Green
                Write-Log "AutoSync: completed $rawName -> $extractDir"
                $synced++
                [void]$syncedNames.Add($extractFolderName)
            } catch {
                Write-Host "    FAILED : $_" -ForegroundColor Red
                Write-Log "AutoSync: FAILED $rawName -- $_"
                # Remove the partial folder so the next run does not misclassify
                # a half-extracted game as already complete (sentinel gone + some
                # files present = indistinguishable from a successful extraction).
                if (-not [string]::IsNullOrWhiteSpace($extractDir)) {
                    Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction SilentlyContinue
                }
                $failed++
            }
        } catch {
            # Reached only when WriteAllText failed (sentinel could not be created).
            Write-Host "    FAILED (could not create extraction sentinel): $_" -ForegroundColor Red
            Write-Log "AutoSync: FAILED $rawName -- sentinel creation error: $_"
            $failed++
        } finally {
            # Sole responsibility of this block: remove the sentinel file.
            # Intentionally the only statement here so nothing can prevent it
            # from running or delay it. Remove-Item with SilentlyContinue is
            # safe even when the sentinel was never created.
            Remove-Item -LiteralPath $sentinel -Force -ErrorAction SilentlyContinue
        }
    }

    if (-not $DryRun) {
        try { [System.IO.File]::WriteAllText($syncStatePath, ($syncState | ConvertTo-Json -Depth 3), (New-Object System.Text.UTF8Encoding $false)) }
        catch { Write-Log "AutoSync: WARNING -- could not save sync state: $_" }
    }

    return @{ Synced = $synced; SyncedNames = @($syncedNames); UpToDate = $upToDate; Failed = $failed; Skipped = $skipped; WouldSync = $wouldSync }
}

# Builds a lookup of TeknoParrot profiles keyed by their executable name(s)
# (lowercased). Each <ExecutableName> may contain multiple alternatives
# separated by ; or | -- all alternatives are indexed so any matching file
# found on disk correctly identifies the game.
function Build-ProfileIndex {
    param([string]$gameProfilesDir)
    $index = @{}
    $templates = Get-ChildItem -LiteralPath $gameProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue
    foreach ($tpl in $templates) {
        $exe = Get-PrimaryExecutableName $tpl.FullName
        if ($exe -and $exe.Trim() -ne "") {
            foreach ($alt in (Get-ExeAlternatives $exe.Trim())) {
                $k = $alt.ToLower()
                if (-not $index.ContainsKey($k)) { $index[$k] = @() }
                $index[$k] += [pscustomobject]@{
                    Code         = $tpl.BaseName
                    TemplatePath = $tpl.FullName
                    ExeName      = $exe.Trim()
                }
            }
        }
    }
    return $index
}

# Streaming XmlReader parser for No-Intro Logiqx XML dat files.
# Reads <game name="..."><GameProfile>...<Executable>... without loading the
# entire document into memory -- required for the 584 MB collection dat.
# Skips <rom> nodes (hash tables) to stay fast.
# Returns normalised-name -> { ProfileCode, Executable } hashtable.
function Build-DatIndexFromStream {
    param([System.IO.Stream]$stream)
    $index    = @{}
    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.IgnoreWhitespace = $true
    $settings.DtdProcessing    = [System.Xml.DtdProcessing]::Prohibit
    $reader = [System.Xml.XmlReader]::Create($stream, $settings)
    try {
        $gameName    = ''
        $profCode    = ''
        $exePath     = ''
        $insideGame  = $false
        $currentElem = ''
        # Skip() already advances the reader onto the next sibling node (the
        # following <rom>, or the </game> EndElement if that was the last
        # one) -- it does NOT need (or want) a further Read() to get there.
        # The loop used to call Read() unconditionally every iteration, so
        # after every Skip() it silently consumed and discarded whatever
        # node Skip() had just landed on. With dozens to hundreds of <rom>
        # entries per game, that discarded one real node per skip, and once
        # the cumulative drift landed exactly on a game's own </game> node,
        # that game's EndElement (and its ProfileCode/Executable capture)
        # never fired at all. Confirmed empirically against a real
        # collection dat: this silently dropped roughly half of all <game>
        # entries (493 opened, only 236 closed) before this fix, regardless
        # of whether the game had a valid ProfileCode. See issue #12.
        $advance = $true
        while ($true) {
            if ($advance) { if (-not $reader.Read()) { break } }
            $advance = $true
            if ($reader.NodeType -eq [System.Xml.XmlNodeType]::Element) {
                $currentElem = $reader.Name
                if ($currentElem -eq 'game') {
                    $gameName    = $reader.GetAttribute('name')
                    $profCode    = ''
                    $exePath     = ''
                    $insideGame  = $true
                } elseif ($currentElem -eq 'rom' -and $insideGame) {
                    $reader.Skip()   # each <game> has hundreds of <rom> hash entries; skip for perf
                    $currentElem = ''
                    $advance     = $false   # already positioned on the next node -- don't double-advance
                }
            } elseif ($reader.NodeType -eq [System.Xml.XmlNodeType]::Text -and $insideGame) {
                if     ($currentElem -eq 'GameProfile')                           { $profCode = $reader.Value }
                elseif ($currentElem -eq 'Executable' -and -not $exePath) { $exePath  = $reader.Value }
            } elseif ($reader.NodeType -eq [System.Xml.XmlNodeType]::EndElement -and $reader.Name -eq 'game') {
                $insideGame = $false
                if ($profCode -and $gameName) {
                    $normName = Get-NormalizedGameKey $gameName
                    if ($normName -and -not $index.ContainsKey($normName)) {
                        $index[$normName] = [pscustomobject]@{
                            ProfileCode  = $profCode.Trim()
                            Executable   = $exePath.Trim()
                            # Retained (not just the normalized key) so Register-Games'
                            # Pass-2 fuzzy fallback can compare meaningful title words
                            # against the folder's own name -- see issue #84.
                            OriginalName = $gameName.Trim()
                        }
                    }
                }
            }
        }
    } finally {
        $reader.Close()
    }
    return $index
}

# Reads the collection dat directly from inside the Eggman ZIP without extracting.
# ZipArchive is opened, the matching entry stream is passed to Build-DatIndexFromStream,
# and the archive is disposed in the finally block regardless of outcome.
function Build-DatIndexFromZip {
    param([string]$zipPath, [string]$entryPattern = '*Collection*_RomVault*.dat')
    $za = $null
    try {
        $za    = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
        $entry = @($za.Entries | Where-Object { $_.FullName -like $entryPattern })[0]
        if (-not $entry) {
            Write-Host ("  WARNING: No dat entry matching '{0}' in ZIP." -f $entryPattern) -ForegroundColor Yellow
            Write-Log ("DatIndex (ZIP): no entry matching '{0}'." -f $entryPattern)
            return @{}
        }
        Write-Host ("    Reading: {0}" -f $entry.Name) -ForegroundColor DarkGray
        $stream = $entry.Open()
        try   { return Build-DatIndexFromStream $stream }
        finally { if ($stream) { $stream.Close() } }
    } catch {
        Write-Host ("  WARNING: Could not read dat from ZIP -- {0}" -f $_) -ForegroundColor Yellow
        Write-Log "DatIndex (ZIP): parse failed -- $_"
        return @{}
    } finally {
        if ($za) { $za.Dispose() }
    }
}


# Parses a No-Intro style TeknoParrot dat file from disk using streaming XmlReader.
# Replaces the old DOM-based approach which could not handle the 584 MB collection dat.
# Returns normalised-name -> { ProfileCode, Executable } hashtable.
function Build-DatIndex {
    param([string]$datPath)
    try {
        $fs = [System.IO.File]::OpenRead($datPath)
        try   { return Build-DatIndexFromStream $fs }
        finally { if ($fs) { $fs.Close() } }
    } catch {
        Write-Host ("  WARNING: Could not parse dat file -- {0}" -f $_) -ForegroundColor Yellow
        Write-Log "DatIndex: parse failed -- $_"
        return @{}
    }
}

# Reads the plain-text game-notes file bundled in the Eggman ZIP.
# Format: sections delimited by lines of 60+ '=' chars.
# First non-blank line of each section: "Game Name (ProfileCode)"
# Remaining lines: the note body.
# Returns ProfileCode.ToLower() -> trimmed note text hashtable.
function Build-GameNotesIndexFromStream {
    param([System.IO.Stream]$stream)
    $index   = @{}
    $reader  = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8)
    try {
        $code       = ''
        $noteLines  = New-Object System.Collections.Generic.List[string]
        $inSection  = $false
        $headerRead = $false

        while (-not $reader.EndOfStream) {
            $ln = $reader.ReadLine()
            if ($ln -match '^={60,}') {
                if ($code -and $noteLines.Count -gt 0) {
                    $body = (($noteLines | Where-Object { $_.Trim() }) -join "`n").Trim()
                    if ($body) { $index[$code] = $body }
                }
                $code = ''; $noteLines.Clear(); $inSection = $true; $headerRead = $false
                continue
            }
            if (-not $inSection) { continue }
            if (-not $headerRead) {
                if ([string]::IsNullOrWhiteSpace($ln)) { continue }
                $m = [regex]::Match($ln, '\(([A-Za-z][A-Za-z0-9_]*)\)\s*$')
                if ($m.Success) { $code = $m.Groups[1].Value.ToLower() }
                $headerRead = $true
            } else {
                $noteLines.Add($ln)
            }
        }
        if ($code -and $noteLines.Count -gt 0) {
            $body = (($noteLines | Where-Object { $_.Trim() }) -join "`n").Trim()
            if ($body) { $index[$code] = $body }
        }
    } finally { $reader.Close() }
    return $index
}

function Build-GameNotesIndex {
    param([string]$path)
    try {
        $fs = [System.IO.File]::OpenRead($path)
        try   { return Build-GameNotesIndexFromStream $fs }
        finally { if ($fs) { $fs.Close() } }
    } catch { Write-Log "NotesIndex: parse failed -- $_"; return @{} }
}

function Build-GameNotesIndexFromZip {
    param([string]$zipPath)
    $za = $null
    try {
        $za    = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
        $entry = @($za.Entries | Where-Object { $_.Name -like '*.txt' -and $_.Name -ilike '*note*' })[0]
        if (-not $entry) { return @{} }
        Write-Host ("    Reading: {0}" -f $entry.Name) -ForegroundColor DarkGray
        $stream = $entry.Open()
        try   { return Build-GameNotesIndexFromStream $stream }
        finally { if ($stream) { $stream.Close() } }
    } catch { Write-Log "NotesIndex (ZIP): parse failed -- $_"; return @{} }
    finally  { if ($za) { $za.Dispose() } }
}

# Queries the teknogods/TeknoParrotUI GitHub repo tree for all GameProfile XML
# filenames. Falls back to scanning the local GameProfiles folder if GitHub is
# unreachable. Returns a HashSet[string] of profile code stems (e.g. "BladeArcus").
function Get-TeknoParrotProfileSet {
    param([string]$localGameProfilesDir = '')
    $result = New-Object 'System.Collections.Generic.HashSet[string]'([StringComparer]::OrdinalIgnoreCase)
    $loaded = $false
    # Resolve the repo's actual default branch instead of hardcoding "master" --
    # if teknogods/TeknoParrotUI ever renames its default branch, this still
    # finds it. Falls back to "master" (today's known default) on any failure
    # so a transient API error doesn't block profile discovery entirely.
    $branch = 'master'
    try {
        $repoResp = Invoke-WebRequest -Uri 'https://api.github.com/repos/teknogods/TeknoParrotUI' `
                        -UseBasicParsing -TimeoutSec 10 -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
        $defaultBranch = ($repoResp.Content | ConvertFrom-Json).default_branch
        if (-not [string]::IsNullOrWhiteSpace($defaultBranch)) { $branch = $defaultBranch }
    } catch {
        Write-Log "ProfileSet (GitHub): could not resolve default branch, falling back to 'master' -- $_"
    }
    $branchEncoded = [System.Uri]::EscapeDataString($branch)
    $apiUri = "https://api.github.com/repos/teknogods/TeknoParrotUI/git/trees/${branchEncoded}?recursive=1"
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $resp = Invoke-WebRequest -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                        -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $tree   = ($resp.Content | ConvertFrom-Json).tree
            $prefix = 'TeknoParrotUi.Common/GameProfiles/'
            foreach ($node in $tree) {
                if ($node.type -eq 'blob' -and $node.path -like ($prefix + '*.xml')) {
                    $stem = [System.IO.Path]::GetFileNameWithoutExtension($node.path.Substring($prefix.Length))
                    if ($stem -match '^[\w]+$') { [void]$result.Add($stem) }   # security: reject stems with path separators or dots
                }
            }
            if ($result.Count -gt 0) {
                Write-Log "ProfileSet (GitHub): $($result.Count) profiles from teknogods/TeknoParrotUI."
                $loaded = $true
            } else {
                Write-Log "ProfileSet (GitHub): 0 profiles returned -- API may have changed."
            }
            break
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "ProfileSet (GitHub): query failed -- HTTP $status -- $_"; break
            }
            Write-Log "ProfileSet (GitHub): attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    if (-not $loaded -and $localGameProfilesDir -and (Test-Path -LiteralPath $localGameProfilesDir)) {
        Get-ChildItem -LiteralPath $localGameProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue |
            ForEach-Object {
                $s = [System.IO.Path]::GetFileNameWithoutExtension($_.Name)
                if ($s -match '^[\w]+$') { [void]$result.Add($s) }
            }
        Write-Log "ProfileSet (local fallback): $($result.Count) profiles from $localGameProfilesDir"
    }
    return $result
}

# Resolves a dat ProfileCode to the correct template filename stem.
# Priority: (1) exact local template; (2) code in GitHub profileSet; (3) fuzzy
# match against profileSet above $FuzzyAutoThreshold; (4) return original.
function Resolve-ProfileCode {
    param([string]$code, [string]$gameProfilesDir,
          [System.Collections.Generic.HashSet[string]]$profileSet = $null)
    if (-not $code) { return $code }
    if ($gameProfilesDir -and (Test-Path -LiteralPath (Join-Path $gameProfilesDir ($code + ".xml")))) {
        return $code
    }
    if ($null -eq $profileSet -or $profileSet.Count -eq 0) { return $code }
    if ($profileSet.Contains($code)) { return $code }
    $normCode  = Get-NormalizedGameKey $code
    $bestScore = 0.0
    $bestMatch = $null
    foreach ($candidate in $profileSet) {
        $score = Get-DiceSimilarity $normCode (Get-NormalizedGameKey $candidate)
        if ($score -gt $bestScore) { $bestScore = $score; $bestMatch = $candidate }
    }
    if ($bestScore -ge $FuzzyAutoThreshold -and $null -ne $bestMatch -and $bestMatch -match '^[\w]+$') {
        Write-Log ("Resolve-ProfileCode: '{0}' -> '{1}' (score {2})" -f $code, $bestMatch, [Math]::Round($bestScore,2))
        return $bestMatch
    }
    # Below threshold -- return the original code unchanged (not $null).
    # Register-Games depends on receiving a usable string even when resolution fails.
    return $code
}

# Queries the GitHub API for the latest Eggman dat release asset.
# Eggmansworld/Datfiles posted its final release ("LAST UPDATE FROM THIS
# REPO!!") and moved the TeknoParrot dats to Eggmansworld/TeknoParrot.
# The new repo also switched from a fixed "teknoparrot" release tag to a
# date-based tag per release (e.g. "2026-06-17"), so a fixed-tag lookup
# can no longer work -- query "latest" instead. Asset naming is unchanged
# (still matches 'TeknoParrot*Collection*RomVault*.zip').
# Returns [pscustomobject]@{DownloadUrl; FileName; SizeMB} or $null on failure.
function Test-EggmanDatReleaseUrl {
    param([string]$Url)
    $parsedUri = $null
    if (-not [System.Uri]::TryCreate($Url, [System.UriKind]::Absolute, [ref]$parsedUri)) { return $false }
    if ($parsedUri.Scheme -ne 'https') { return $false }

    if ($parsedUri.Host -ine 'github.com') { return $false }
    return $parsedUri.AbsolutePath.StartsWith('/Eggmansworld/TeknoParrot/releases/download/', [System.StringComparison]::Ordinal)
}

function Get-EggmanDatRelease {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/Eggmansworld/TeknoParrot/releases/latest'
            $resp   = Invoke-WebRequest -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $rel    = $resp.Content | ConvertFrom-Json
            $asset  = @($rel.assets) | Where-Object { $_.name -like 'TeknoParrot*Collection*RomVault*.zip' } |
                          Select-Object -First 1
            if (-not $asset) { return $null }
            if (-not (Test-EggmanDatReleaseUrl -Url $asset.browser_download_url)) {
                Write-Log "EggmanDat: unexpected download URL format -- skipping."
                return $null
            }
            return [pscustomobject]@{
                DownloadUrl = $asset.browser_download_url
                FileName    = $asset.name
                SizeMB      = [Math]::Round($asset.size / 1MB, 1)
                SizeBytes   = [int64]$asset.size
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "EggmanDat: GitHub release query failed -- $_"; return $null
            }
            Write-Log "EggmanDat: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

function Invoke-TpmDownloadHttpClient {
    param([string]$DownloadUrl, [string]$TempPath, [string]$Label = 'download')
    if (-not ('System.Net.Http.HttpClient' -as [type])) {
        Add-Type -AssemblyName System.Net.Http
    }
    $client = $null
    $response = $null
    $inputStream = $null
    $outputStream = $null
    try {
        $client = New-Object System.Net.Http.HttpClient
        $client.Timeout = [TimeSpan]::FromMinutes(30)
        $response = $client.GetAsync($DownloadUrl, [System.Net.Http.HttpCompletionOption]::ResponseHeadersRead).GetAwaiter().GetResult()
        [void]$response.EnsureSuccessStatusCode()
        $totalBytes = if ($response.Content.Headers.ContentLength.HasValue) { [int64]$response.Content.Headers.ContentLength.Value } else { [int64]0 }
        $inputStream = $response.Content.ReadAsStreamAsync().GetAwaiter().GetResult()
        $outputStream = [System.IO.File]::Create($TempPath)
        $buffer = New-Object byte[] 1048576
        $downloadedBytes = [int64]0
        $progressWatch = [System.Diagnostics.Stopwatch]::StartNew()
        while (($read = $inputStream.Read($buffer, 0, $buffer.Length)) -gt 0) {
            $outputStream.Write($buffer, 0, $read)
            $downloadedBytes += $read
            Write-TpmDownloadProgress -Label $Label -Method 'HttpClient' -DownloadedBytes $downloadedBytes -TotalBytes $totalBytes -Elapsed $progressWatch.Elapsed
        }
        Write-TpmDownloadProgress -Label $Label -Method 'HttpClient' -DownloadedBytes $downloadedBytes -TotalBytes $totalBytes -Elapsed $progressWatch.Elapsed -Complete
    } finally {
        if ($outputStream) { $outputStream.Dispose() }
        if ($inputStream) { $inputStream.Dispose() }
        if ($response) { $response.Dispose() }
        if ($client) { $client.Dispose() }
    }
}

function Invoke-TpmDownloadWebRequest {
    param([string]$DownloadUrl, [string]$TempPath, [string]$Label = 'download')
    Write-TpmDownloadProgress -Label $Label -Method 'Invoke-WebRequest' -DownloadedBytes 0 -TotalBytes 0 -Elapsed ([TimeSpan]::Zero)
    Invoke-WebRequest -Uri $DownloadUrl -OutFile $TempPath -UseBasicParsing -ErrorAction Stop
    $bytes = (Get-Item -LiteralPath $TempPath -ErrorAction Stop).Length
    Write-TpmDownloadProgress -Label $Label -Method 'Invoke-WebRequest' -DownloadedBytes $bytes -TotalBytes $bytes -Elapsed ([TimeSpan]::Zero) -Complete
}

function Test-TpmDownloadBitsAvailable {
    $bitsCommand = Get-Command Start-BitsTransfer -ErrorAction SilentlyContinue
    if (-not $bitsCommand) { return $false }
    $bitsSvc = try { Get-Service -Name BITS -ErrorAction Stop } catch { $null }
    return ($bitsSvc -ne $null -and $bitsSvc.Status -eq 'Running')
}

function Invoke-TpmDownloadBits {
    param([string]$DownloadUrl, [string]$TempPath, [string]$Label = 'download')
    $job = $null
    $progressWatch = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        $job = Start-BitsTransfer -Source $DownloadUrl -Destination $TempPath `
            -Description "TeknoParrot Manager $Label" `
            -DisplayName "Downloading $Label..." `
            -Asynchronous `
            -ErrorAction Stop
        while ($job.JobState -in @('Connecting', 'Transferring', 'Queued', 'TransientError')) {
            Write-TpmDownloadProgress -Label $Label -Method 'BITS' -DownloadedBytes ([int64]$job.BytesTransferred) -TotalBytes ([int64]$job.BytesTotal) -Elapsed $progressWatch.Elapsed
            Start-Sleep -Milliseconds 500
            $job = Get-BitsTransfer -JobId $job.JobId -ErrorAction Stop
        }
        if ($job.JobState -ne 'Transferred') {
            throw "BITS transfer ended with state $($job.JobState)."
        }
        Complete-BitsTransfer -BitsJob $job -ErrorAction Stop
        $bytes = (Get-Item -LiteralPath $TempPath -ErrorAction Stop).Length
        Write-TpmDownloadProgress -Label $Label -Method 'BITS' -DownloadedBytes $bytes -TotalBytes $bytes -Elapsed $progressWatch.Elapsed -Complete
    } catch {
        if ($job) {
            try { Remove-BitsTransfer -BitsJob $job -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        }
        throw
    }
}

# Parses a GitHub Releases API asset "digest" field (e.g.
# "sha256:82f987...") into a bare uppercase hex hash, or $null if the field
# is absent/empty or not in the sha256: form this script verifies against.
# Shared by every release-asset fetch that wants to opt into SHA-256
# verification (currently BepInEx and dgVoodoo2) -- a generic GitHub
# Releases API feature, not specific to either project.
function Get-TpmSha256FromDigestField {
    param([string]$Digest)
    if ([string]::IsNullOrWhiteSpace($Digest)) { return $null }
    if ($Digest -match '^sha256:([0-9a-fA-F]{64})$') { return $Matches[1].ToUpper() }
    return $null
}

function Test-TpmDownloadedFile {
    param([string]$Path, [Int64]$ExpectedBytes = 0, [string]$ExpectedSha256 = '')
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    $item = Get-Item -LiteralPath $Path -ErrorAction Stop
    if ($item.Length -le 0) { return $false }
    if ($ExpectedBytes -gt 0 -and $item.Length -ne $ExpectedBytes) { return $false }
    if ($ExpectedSha256) {
        # Fail closed: any hashing error (unreadable file, etc.) is treated
        # the same as a mismatch, never as "skip the check."
        $actualHash = $null
        try { $actualHash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash } catch {}
        if (-not $actualHash -or $actualHash -ine $ExpectedSha256) {
            Write-Log "Test-TpmDownloadedFile: SECURITY -- SHA-256 mismatch for '$Path' (expected $ExpectedSha256, got $actualHash)."
            return $false
        }
    }
    return $true
}

function Write-TpmDownloadProgress {
    param(
        [string]$Label = 'download',
        [string]$Method,
        [Int64]$DownloadedBytes,
        [Int64]$TotalBytes = 0,
        [TimeSpan]$Elapsed,
        [switch]$Complete
    )
    $activeStatus = $script:ActiveTpmWorkflowStatus
    if ($activeStatus) {
        $downloadStatusNow = (Get-Date).ToUniversalTime()
        if ($Complete) {
            [void](Update-TpmWorkflowActivity -Context $activeStatus -Activity ("{0} download finished" -f $Label))
            return
        }
        if ($null -eq $activeStatus.LastDownloadStatusUtc -or ($downloadStatusNow - $activeStatus.LastDownloadStatusUtc).TotalMilliseconds -ge 500) {
            $activeStatus.LastDownloadStatusUtc = $downloadStatusNow
            $downloadMb = [Math]::Round($DownloadedBytes / 1MB, 1)
            if ($TotalBytes -gt 0) {
                $downloadPercent = [Math]::Min(100, [Math]::Max(0, [Math]::Round(($DownloadedBytes / $TotalBytes) * 100, 0)))
                [void](Update-TpmWorkflowActivity -Context $activeStatus -Activity ("{0}: {1}% downloaded ({2} MB)" -f $Label, $downloadPercent, $downloadMb))
            } else {
                [void](Update-TpmWorkflowActivity -Context $activeStatus -Activity ("{0}: {1} MB downloaded" -f $Label, $downloadMb))
            }
        }
        return
    }

    $activity = "Downloading $Label"
    if ($Complete) {
        Write-Progress -Id 42 -Activity $activity -Completed
        return
    }

    $downloadedMb = [Math]::Round($DownloadedBytes / 1MB, 1)
    $seconds = [Math]::Max($Elapsed.TotalSeconds, 0.001)
    $mbps = [Math]::Round(($DownloadedBytes / 1MB) / $seconds, 2)
    if ($TotalBytes -gt 0) {
        $totalMb = [Math]::Round($TotalBytes / 1MB, 1)
        $percent = [Math]::Min(100, [Math]::Max(0, [Math]::Round(($DownloadedBytes / $TotalBytes) * 100, 0)))
        $etaText = ''
        if ($DownloadedBytes -gt 0 -and $mbps -gt 0) {
            $remainingSeconds = (($TotalBytes - $DownloadedBytes) / 1MB) / $mbps
            if ($remainingSeconds -ge 0) {
                $etaText = " ETA {0}" -f ([TimeSpan]::FromSeconds($remainingSeconds).ToString("mm\:ss"))
            }
        }
        Write-Progress -Id 42 -Activity $activity -Status ("{0}: {1}%  {2}/{3} MB  {4} MB/s{5}" -f $Method, $percent, $downloadedMb, $totalMb, $mbps, $etaText) -PercentComplete $percent
    } else {
        Write-Progress -Id 42 -Activity $activity -Status ("{0}: {1} MB downloaded  {2} MB/s" -f $Method, $downloadedMb, $mbps)
    }
}

function Write-TpmDownloadMetrics {
    param([string]$Label, [string]$Method, [string]$Path, [TimeSpan]$Elapsed, [switch]$Quiet)
    $bytes = (Get-Item -LiteralPath $Path -ErrorAction Stop).Length
    $mb = [Math]::Round($bytes / 1MB, 2)
    $seconds = [Math]::Max($Elapsed.TotalSeconds, 0.001)
    $mbps = [Math]::Round(($bytes / 1MB) / $seconds, 2)
    $message = "${Label}: download method=$Method size=${mb}MB elapsed=$([Math]::Round($Elapsed.TotalSeconds, 1))s speed=${mbps}MB/s"
    Write-Log $message
    if (-not $Quiet) {
        Write-Host ("  Downloaded with {0}: {1} MB in {2:n1}s ({3} MB/s)" -f $Method, $mb, $Elapsed.TotalSeconds, $mbps) -ForegroundColor DarkGray
    }
}

# Extracts an HTTP status code from a failed download attempt's error
# record, if one is present -- a real WebException's .Response.StatusCode
# when available, otherwise a best-effort parse of the exception message
# (HttpClient's EnsureSuccessStatusCode() reports it as text, e.g.
# "... does not indicate success: 404 (Not Found)."). Returns 0 (unknown)
# rather than guessing when neither is present. Used to (a) short-circuit
# the retry loop below on a definitive 4xx rather than retrying something
# that will never succeed, and (b) let a caller like Invoke-ThumbnailDownload
# distinguish "404, not in this repo" from a real transient failure.
function Get-TpmHttpStatusCodeFromError {
    param($ErrorRecord)
    # Not every exception type this can see (RuntimeException from a plain
    # "throw '...'" in a mock, HttpRequestException from HttpClient, etc.)
    # declares a Response property at all -- unlike WebException, where it's
    # merely $null on a non-HTTP failure. Under strict mode, dot-accessing a
    # property that doesn't exist throws PropertyNotFoundException, which
    # previously crashed this function (and its caller) before it ever got a
    # chance to fall through to the message-based extraction below. Checking
    # for the property's existence via PSObject first -- rather than just its
    # truthiness -- preserves the original error path for every exception
    # type that genuinely lacks the property, instead of throwing a new,
    # unrelated one.
    $responseProperty = $ErrorRecord.Exception.PSObject.Properties['Response']
    if ($responseProperty -and $responseProperty.Value) {
        # Same existence-before-truthiness reasoning one level deeper: a
        # Response object can itself be a type (or a test double) that has
        # no StatusCode property at all, not merely a null/zero one. Dot-
        # accessing .StatusCode directly in the condition above would throw
        # under strict mode for that shape instead of falling through.
        $statusCodeProperty = $responseProperty.Value.PSObject.Properties['StatusCode']
        if ($statusCodeProperty -and $null -ne $statusCodeProperty.Value) {
            # [int] cast covers both a plain numeric StatusCode and an
            # enum-like one (e.g. [System.Net.HttpStatusCode]::NotFound) --
            # enums cast cleanly to their underlying integer value. The
            # try/catch only guards a genuinely uncastable value; it still
            # falls through to the message-based extraction below rather
            # than silently reporting a wrong code.
            try { return [int]$statusCodeProperty.Value } catch {}
        }
    }
    if ($ErrorRecord.Exception.Message -match '\((\d{3})\)') { return [int]$Matches[1] }
    if ($ErrorRecord.Exception.Message -match ':\s*(\d{3})\s') { return [int]$Matches[1] }
    return 0
}

# Downloads a live asset to a sibling partial file first, then moves it
# into place only after completion validation. Preferred order is BITS,
# HttpClient, then Invoke-WebRequest as an emergency fallback. The
# HttpClient and Invoke-WebRequest tiers each retry up to 3 times with a
# short backoff on a transient failure; a definitive 4xx response is never
# retried (retrying it cannot succeed) and falls straight through to the
# next tier / final failure. Pass -LastStatusCode ([ref]$var) to read the
# final HTTP status code (0 if unknown/not HTTP-related) after a failure.
function Invoke-TpmDownload {
    param([string]$DownloadUrl, [string]$DestinationPath, [Int64]$ExpectedBytes = 0, [string]$Label = 'Download', [string]$Version = '', [switch]$Quiet, [ref]$LastStatusCode, [string]$ExpectedSha256 = '', [scriptblock]$ValidationScript)
    if ($LastStatusCode) { $LastStatusCode.Value = 0 }
    $saveDir = Split-Path -Parent $DestinationPath
    if ([string]::IsNullOrWhiteSpace($saveDir)) { $saveDir = (Get-Location).Path }
    if (-not (Test-Path -LiteralPath $saveDir -PathType Container)) {
        New-Item -ItemType Directory -Path $saveDir -Force | Out-Null
    }
    # The temp/partial download lands on local disk, not next to the final
    # destination -- $DestinationPath can be (and for several download
    # targets in this script routinely is) a network-mapped drive. A large
    # download sustained directly over that share, immediately followed by
    # a same-share Move-Item, is exactly the kind of transient network
    # flakiness this project has already hit and documented elsewhere (see
    # ARCHITECTURE.md, "Startup: network-path detection and hard timeout").
    # Move-Item works transparently across volumes (copy+delete under the
    # hood when a simple rename isn't possible), so downloading locally
    # first and moving into place at the end changes nothing about the
    # final result -- it only shrinks the window where a flaky network
    # path can make the in-progress file disappear out from under us.
    # Falls back to $saveDir itself if the local temp directory isn't
    # writable for some reason, matching the original behavior.
    $tempDir = $env:TEMP
    if ([string]::IsNullOrWhiteSpace($tempDir) -or -not (Test-Path -LiteralPath $tempDir -PathType Container)) {
        $tempDir = $saveDir
    }
    $tempName = '.{0}.{1}.partial' -f ([System.IO.Path]::GetFileName($DestinationPath)), ([guid]::NewGuid().ToString('N'))
    $tempPath = Join-Path $tempDir $tempName
    $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
    $methodUsed = $null
    $detectedStatusCode = 0
    try {
        $bitsSucceeded = $false
        if (Test-TpmDownloadBitsAvailable) {
            try {
                Invoke-TpmDownloadBits -DownloadUrl $DownloadUrl -TempPath $tempPath -Label $Label
                $bitsSucceeded = $true
                $methodUsed = 'BITS'
            } catch {
                Write-Log "${Label}: BITS transfer failed (${_}), trying HttpClient."
                try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
            }
        }
        if (-not $bitsSucceeded) {
            $httpClientSucceeded = $false
            for ($attempt = 1; $attempt -le 3; $attempt++) {
                try {
                    Invoke-TpmDownloadHttpClient -DownloadUrl $DownloadUrl -TempPath $tempPath -Label $Label
                    $methodUsed = 'HttpClient'
                    $httpClientSucceeded = $true
                    break
                } catch {
                    $detectedStatusCode = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
                    try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
                    if ($attempt -ge 3 -or ($detectedStatusCode -ge 400 -and $detectedStatusCode -lt 500)) {
                        Write-Log "${Label}: HttpClient download failed (${_}), trying Invoke-WebRequest."
                        break
                    }
                    Write-Log "${Label}: HttpClient attempt $attempt failed -- retrying"
                    Start-Sleep -Seconds 2
                }
            }
            if (-not $httpClientSucceeded) {
                for ($attempt = 1; $attempt -le 3; $attempt++) {
                    try {
                        Invoke-TpmDownloadWebRequest -DownloadUrl $DownloadUrl -TempPath $tempPath -Label $Label
                        $methodUsed = 'Invoke-WebRequest'
                        break
                    } catch {
                        $detectedStatusCode = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
                        try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
                        if ($attempt -ge 3 -or ($detectedStatusCode -ge 400 -and $detectedStatusCode -lt 500)) { throw }
                        Write-Log "${Label}: download attempt $attempt failed -- retrying"
                        Start-Sleep -Seconds 2
                    }
                }
            }
        }
        if (-not (Test-TpmDownloadedFile -Path $tempPath -ExpectedBytes $ExpectedBytes -ExpectedSha256 $ExpectedSha256)) {
            # Fail closed: delete the partial file (handled in the catch
            # block below via $tempPath) and surface a clear error -- this
            # covers both "incomplete/empty" and "SHA-256 verification
            # failed" (Test-TpmDownloadedFile already logged the specific
            # SECURITY reason for the latter).
            throw "Downloaded file is incomplete, empty, or failed integrity verification."
        }
        if ($ValidationScript -and -not (& $ValidationScript $tempPath)) {
            throw "Downloaded file failed the caller's content validation."
        }
        if (Test-Path -LiteralPath $DestinationPath -PathType Leaf) {
            Remove-Item -LiteralPath $DestinationPath -Force -ErrorAction Stop
        }
        Move-Item -LiteralPath $tempPath -Destination $DestinationPath -Force -ErrorAction Stop
        $stopwatch.Stop()
        Write-TpmDownloadMetrics -Label $Label -Method $methodUsed -Path $DestinationPath -Elapsed $stopwatch.Elapsed -Quiet:$Quiet
        Write-DownloadAudit -Source $DownloadUrl -FileName ([System.IO.Path]::GetFileName($DestinationPath)) -Path $DestinationPath -Version $Version
        return $true
    } catch {
        $stopwatch.Stop()
        if (-not $Quiet) { Write-Host ("  Download failed: {0}" -f $_) -ForegroundColor Red }
        Write-Log "${Label}: download failed -- $_"
        try { if (Test-Path -LiteralPath $tempPath) { [System.IO.File]::Delete($tempPath) } } catch {}
        if ($LastStatusCode) { $LastStatusCode.Value = $detectedStatusCode }
        return $false
    } finally {
        # The BITS/HttpClient/Invoke-WebRequest tiers each raise the Id 42
        # progress overlay as they start working, but only the success path
        # in each of them clears it. Every failure/exception exit above used
        # to leave whatever partial-progress text ("0 MB downloaded") was
        # last written on screen permanently, since nothing after this point
        # in the whole call chain ever touches Id 42 again. Clearing here
        # unconditionally (success, per-tier failure, or an unexpected
        # throw) guarantees the overlay never survives past this function
        # regardless of how it exits -- see issue #132.
        Write-Progress -Id 42 -Activity "Downloading $Label" -Completed
    }
}

# Compares the local Eggman dat ZIP against the latest GitHub release. The
# release format exposes no separate version number or date, so the remote
# byte size remains the freshness signal, but a same-size file is only treated
# as current after its ZIP structure and collection DAT entry are readable.
# See issue #106: the "check for a newer release" prompt previously always
# asked to download/switch regardless of whether the remote release changed.
# Pure/read-only -- never writes or repairs the local file.
function Test-EggmanDatUpToDate {
    param(
        [string]$LocalDatPath,
        [Int64]$RemoteSizeBytes
    )
    if (-not (Test-Path -LiteralPath $LocalDatPath)) {
        return [pscustomobject]@{ Status = 'Unknown'; LocalSizeBytes = $null }
    }
    $localSizeBytes = (Get-Item -LiteralPath $LocalDatPath).Length
    if (-not (Test-EggmanDatZip -Path $LocalDatPath -ExpectedBytes $localSizeBytes)) {
        return [pscustomobject]@{ Status = 'UpdateAvailable'; LocalSizeBytes = $localSizeBytes }
    }
    $status = if ($localSizeBytes -eq $RemoteSizeBytes) { 'Current' } else { 'UpdateAvailable' }
    return [pscustomobject]@{ Status = $status; LocalSizeBytes = $localSizeBytes }
}

function Invoke-EggmanDatDownload {
    param(
        [string]$downloadUrl,
        [string]$savePath,
        [Int64]$ExpectedBytes = 0,
        [string]$ProgramDirectory = ''
    )
    if (-not (Test-EggmanDatDestinationSafe -Path $savePath -ProgramDirectory $ProgramDirectory)) {
        Write-Log "EggmanDat: SECURITY -- destination failed the immediate pre-download role check: $savePath"
        return $false
    }
    return (Invoke-TpmDownload -DownloadUrl $downloadUrl -DestinationPath $savePath -ExpectedBytes $ExpectedBytes -Label 'EggmanDat' -ValidationScript {
        param([string]$DownloadedPath)
        if (-not (Test-EggmanDatDestinationSafe -Path $savePath -ProgramDirectory $ProgramDirectory)) {
            Write-Log "EggmanDat: SECURITY -- destination failed the immediate pre-write role check: $savePath"
            return $false
        }
        return (Test-EggmanDatZip -Path $DownloadedPath -ExpectedBytes $ExpectedBytes)
    })
}

# Returns the TPM-owned per-user data root for downloaded Eggman recognition
# data. This is deliberately outside the TeknoParrot installation, the TPM
# program folder, game ZIP sources, and the game staging folder. The directory
# is not created by this read-only resolver; Invoke-TpmDownload creates it only
# when a validated download is ready to be written.
function Get-EggmanDatDataRoot {
    $localAppData = [System.Environment]::GetFolderPath([System.Environment+SpecialFolder]::LocalApplicationData)
    if ([string]::IsNullOrWhiteSpace($localAppData)) {
        $localAppData = [System.Environment]::GetEnvironmentVariable('LOCALAPPDATA')
    }
    if ([string]::IsNullOrWhiteSpace($localAppData)) { return $null }
    return (Join-Path $localAppData 'TeknoParrotManager\Eggman')
}

# Review round 3 used a script-adjacent default. That made a download write
# into the TPM package directory and made ownership ambiguous. The default is
# now a deterministic per-user TPM data location. RootPath is test-only
# injection: production callers omit it, while focused tests can remain inside
# their disposable TestDrive instead of touching the real profile.
function Get-EggmanDatDefaultSavePath {
    param([string]$FileName, [string]$RootPath = '')
    $dataRoot = if ([string]::IsNullOrWhiteSpace($RootPath)) { Get-EggmanDatDataRoot } else { $RootPath }
    if ([string]::IsNullOrWhiteSpace($dataRoot)) { return $null }
    return (Join-Path $dataRoot $FileName)
}

# Classify Eggman paths by role instead of treating every mapped/NAS path as
# unsafe. The configured primary ZIP source may be an approved DAT destination
# when it is reachable, canonical, non-reparse, and outside protected roots.
# The supplementary source is never selected as a primary fallback.
function Get-EggmanDatPathRole {
    param(
        [string]$Path,
        [ValidateSet('Destination','PrimaryZipSource')]
        [string]$RequestedRole = 'Destination',
        [string]$ProgramDirectory = ''
    )

    $result = [ordered]@{
        Safe = $false
        CanonicalPath = $null
        Role = 'Unknown'
        ReasonCode = 'Invalid'
        Reason = 'The path is empty or cannot be canonicalized.'
        ReparseBacked = $false
    }
    if ([string]::IsNullOrWhiteSpace($Path)) { return [pscustomobject]$result }

    try {
        if (-not [System.IO.Path]::IsPathRooted($Path)) { return [pscustomobject]$result }
        $result.CanonicalPath = [System.IO.Path]::GetFullPath($Path).TrimEnd('\','/')
        if ([string]::IsNullOrWhiteSpace($result.CanonicalPath)) { return [pscustomobject]$result }
    } catch { return [pscustomobject]$result }

    $canonicalRoots = @{}
    foreach ($entry in @(
        [pscustomobject]@{ Name = 'TeknoParrotRoot'; Path = $tpRoot },
        [pscustomobject]@{ Name = 'GamesInstall'; Path = $gamesInstallFolder },
        [pscustomobject]@{ Name = 'ProgramDirectory'; Path = $ProgramDirectory },
        [pscustomobject]@{ Name = 'PrimaryZipSource'; Path = $zipSource },
        [pscustomobject]@{ Name = 'SupplementaryZipSource'; Path = $zipSourceSupplementary }
    )) {
        if ([string]::IsNullOrWhiteSpace([string]$entry.Path)) { continue }
        try {
            if (-not [System.IO.Path]::IsPathRooted([string]$entry.Path)) {
                $result.ReasonCode = 'Ambiguous'
                $result.Reason = "$($entry.Name) is not an absolute path."
                return [pscustomobject]$result
            }
            $canonicalRoots[$entry.Name] = [System.IO.Path]::GetFullPath([string]$entry.Path).TrimEnd('\','/')
        } catch {
            $result.ReasonCode = 'Ambiguous'
            $result.Reason = "$($entry.Name) cannot be canonicalized."
            return [pscustomobject]$result
        }
    }

    if ($canonicalRoots.ContainsKey('PrimaryZipSource') -and
        $canonicalRoots.ContainsKey('SupplementaryZipSource') -and
        (Test-TpmPathOverlap $canonicalRoots['PrimaryZipSource'] $canonicalRoots['SupplementaryZipSource'])) {
        $result.ReasonCode = 'AmbiguousSourceRoles'
        $result.Reason = 'The primary and supplementary ZIP source folders overlap.'
        return [pscustomobject]$result
    }

    foreach ($protectedName in @('TeknoParrotRoot','GamesInstall','ProgramDirectory')) {
        if ($canonicalRoots.ContainsKey($protectedName) -and
            (Test-TpmPathOverlap $result.CanonicalPath $canonicalRoots[$protectedName])) {
            $result.ReasonCode = switch ($protectedName) {
                'TeknoParrotRoot' { 'TeknoParrotRoot' }
                'GamesInstall' { 'ProtectedStaging' }
                default { 'ProtectedRuntime' }
            }
            $result.Role = 'Protected'
            $result.Reason = "The path overlaps the protected $protectedName root."
            return [pscustomobject]$result
        }
    }

    if (-not (Test-TpmNoReparsePath -Path $result.CanonicalPath)) {
        $result.ReasonCode = 'ReparseOrInaccessible'
        $result.Reason = 'The path or one of its existing parent components is reparse-backed or inaccessible.'
        $result.ReparseBacked = $true
        return [pscustomobject]$result
    }

    $primaryRoot = if ($canonicalRoots.ContainsKey('PrimaryZipSource')) { $canonicalRoots['PrimaryZipSource'] } else { $null }
    $supplementaryRoot = if ($canonicalRoots.ContainsKey('SupplementaryZipSource')) { $canonicalRoots['SupplementaryZipSource'] } else { $null }

    if ($RequestedRole -eq 'PrimaryZipSource') {
        if ([string]::IsNullOrWhiteSpace($primaryRoot) -or
            -not $result.CanonicalPath.Equals($primaryRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
            $result.ReasonCode = 'NotPrimarySource'
            $result.Reason = 'The path is not the configured primary ZIP/source folder.'
            return [pscustomobject]$result
        }
        if (-not (Test-Path -LiteralPath $result.CanonicalPath -PathType Container -ErrorAction SilentlyContinue)) {
            $result.ReasonCode = 'PrimarySourceUnavailable'
            $result.Reason = 'The configured primary ZIP/source folder is not a reachable directory.'
            return [pscustomobject]$result
        }
        $result.Safe = $true
        $result.Role = 'PrimaryZipSource'
        $result.ReasonCode = 'Safe'
        $result.Reason = 'The configured primary ZIP/source folder is role-safe.'
        return [pscustomobject]$result
    }

    if ($supplementaryRoot -and (Test-PathInside $result.CanonicalPath $supplementaryRoot)) {
        $result.ReasonCode = 'SupplementarySource'
        $result.Reason = 'The supplementary ZIP/source folder is not an automatic primary DAT destination.'
        return [pscustomobject]$result
    }
    if ($primaryRoot -and (Test-PathInside $result.CanonicalPath $primaryRoot)) {
        if (Test-Path -LiteralPath $result.CanonicalPath -PathType Container -ErrorAction SilentlyContinue) {
            $result.ReasonCode = 'DestinationIsFolder'
            $result.Reason = 'The destination must be a file path, not a source folder.'
            return [pscustomobject]$result
        }
        $result.Safe = $true
        $result.Role = 'EggmanDatInPrimaryZipSource'
        $result.ReasonCode = 'Safe'
        $result.Reason = 'The destination is inside the explicitly configured primary ZIP/source folder.'
        return [pscustomobject]$result
    }
    if (($primaryRoot -and (Test-TpmPathOverlap $result.CanonicalPath $primaryRoot)) -or
        ($supplementaryRoot -and (Test-TpmPathOverlap $result.CanonicalPath $supplementaryRoot))) {
        $result.ReasonCode = 'AmbiguousSourceBoundary'
        $result.Reason = 'The destination overlaps a configured source boundary without being inside an approved role.'
        return [pscustomobject]$result
    }
    if (Test-Path -LiteralPath $result.CanonicalPath -PathType Container -ErrorAction SilentlyContinue) {
        $result.ReasonCode = 'DestinationIsFolder'
        $result.Reason = 'The destination must be a file path, not a folder.'
        return [pscustomobject]$result
    }

    $result.Safe = $true
    $result.Role = 'ExternalEggmanDatDestination'
    $result.ReasonCode = 'Safe'
    $result.Reason = 'The destination is outside protected roots and source boundaries.'
    return [pscustomobject]$result
}

function Test-EggmanDatDestinationSafe {
    param(
        [string]$Path,
        [string]$ProgramDirectory = ''
    )
    return [bool](Get-EggmanDatPathRole -Path $Path -RequestedRole Destination -ProgramDirectory $ProgramDirectory).Safe
}

# Return only a reachable, non-reparse primary source folder. This is the
# deliberate fallback for a configured DAT that is readable under TeknoParrot
# but cannot be overwritten there.
function Get-EggmanDatDestinationCandidates {
    param([string]$ProgramDirectory = '')
    $candidate = Get-EggmanDatPathRole -Path $zipSource -RequestedRole PrimaryZipSource -ProgramDirectory $ProgramDirectory
    if ($candidate.Safe) {
        return @([pscustomobject]@{
            Path = $candidate.CanonicalPath
            Role = $candidate.Role
            Reason = $candidate.Reason
        })
    }
    return @()
}

# Resolve the write destination before any release query or download. The
# current DAT remains readable for comparison, but TPM never writes a
# replacement under the TeknoParrot root.
function Resolve-EggmanDatUpdateDestination {
    param(
        [string]$CurrentPath,
        [string]$ProgramDirectory = ''
    )
    $current = Get-EggmanDatPathRole -Path $CurrentPath -RequestedRole Destination -ProgramDirectory $ProgramDirectory
    if ($current.Safe) {
        return [pscustomobject]@{
            Status = 'Ready'
            DestinationPath = $current.CanonicalPath
            DestinationFolder = [System.IO.Path]::GetDirectoryName($current.CanonicalPath)
            Reason = $current.Reason
        }
    }

    $tpRootCanonical = $null
    if (-not [string]::IsNullOrWhiteSpace([string]$tpRoot)) {
        try { $tpRootCanonical = [System.IO.Path]::GetFullPath($tpRoot).TrimEnd('\','/') } catch {}
    }
    if ($tpRootCanonical -and (Test-PathInside $current.CanonicalPath $tpRootCanonical)) {
        Write-Host '  Current DAT is under the TeknoParrot root, which TPM will not write to.' -ForegroundColor Yellow
        $candidates = @(Get-EggmanDatDestinationCandidates -ProgramDirectory $ProgramDirectory)
        if ($candidates.Count -gt 0) {
            $candidate = $candidates[0]
            Write-Host ("  Safe external DAT folder found: {0}" -f $candidate.Path) -ForegroundColor Green
            $choice = (Read-HostSafe 'Download latest DAT there? (Y/N)').ToUpper()
            if ($choice -eq 'Y') {
                return [pscustomobject]@{
                    Status = 'FallbackSelected'
                    DestinationPath = $null
                    DestinationFolder = $candidate.Path
                    Reason = $candidate.Reason
                }
            }
            Write-Host '  Keeping the current DAT. No download was started.' -ForegroundColor Yellow
            return [pscustomobject]@{
                Status = 'Declined'
                DestinationPath = $null
                DestinationFolder = $null
                Reason = 'The user declined the safe external destination.'
            }
        }
        Write-Host '  No safe external primary DAT folder is configured or reachable.' -ForegroundColor Yellow
        Write-Host '  Action: configure a reachable primary ZIP/source folder outside TeknoParrot' -ForegroundColor Yellow
        Write-Host '  and staging, verify its Windows share permissions, then run the update again.' -ForegroundColor Yellow
        return [pscustomobject]@{
            Status = 'NoSafeDestination'
            DestinationPath = $null
            DestinationFolder = $null
            Reason = 'No role-safe primary ZIP/source folder was available.'
        }
    }

    Write-Host '  The configured Eggman DAT destination is not safe to write.' -ForegroundColor Yellow
    Write-Host ("  Action: choose a canonical, non-reparse folder outside TeknoParrot and staging; TPM will not write until it passes validation. ({0})" -f $current.Reason) -ForegroundColor Yellow
    return [pscustomobject]@{
        Status = 'Invalid'
        DestinationPath = $null
        DestinationFolder = $null
        Reason = $current.Reason
    }
}

# A matching byte count is not enough to trust a downloaded Eggman archive:
# a text file, truncated archive, or corrupt ZIP can have the expected length.
# Require a readable ZIP central directory and the collection DAT entry that
# Build-DatIndexFromZip consumes. No extraction or write occurs here.
function Test-EggmanDatZip {
    param([string]$Path, [Int64]$ExpectedBytes = 0)
    if (-not (Test-TpmDownloadedFile -Path $Path -ExpectedBytes $ExpectedBytes)) { return $false }
    $zip = $null
    try {
        $zip = [System.IO.Compression.ZipFile]::OpenRead($Path)
        $collectionEntry = @($zip.Entries | Where-Object { $_.FullName -like '*Collection*_RomVault*.dat' })[0]
        return ($null -ne $collectionEntry)
    } catch {
        Write-Log "EggmanDat: ZIP validation failed for '$Path' -- $_"
        return $false
    } finally {
        if ($zip) { $zip.Dispose() }
    }
}

# Shared download step for a resolved Eggman release. The ordinary first-run
# path uses the deterministic TPM-owned default without asking where to save.
# AllowBrowse is used only when no preferred path was supplied. The configured
# update flow supplies PreferredSavePath, so a valid configured path is reused
# without an alternate-location dialog and is still revalidated before use.
# An unsafe configured DAT under TeknoParrot may offer the role-safe primary
# source folder before any download begins.
# Returns the saved path on success, or $null on failure/abort.
function Invoke-EggmanDatDownloadInteractive {
    param(
        [pscustomobject]$rel,
        [switch]$AllowBrowse,
        [string]$PreferredSavePath = '',
        [string]$DefaultRoot = '',
        [string]$ProgramDirectory = ''
    )

    $safeDatFileName = [System.IO.Path]::GetFileName($rel.FileName)
    $defaultSavePath = if ([string]::IsNullOrWhiteSpace($PreferredSavePath)) {
        Get-EggmanDatDefaultSavePath -FileName $safeDatFileName -RootPath $DefaultRoot
    } else {
        $PreferredSavePath
    }
    $defaultRoot = if ([string]::IsNullOrWhiteSpace($DefaultRoot)) { Get-EggmanDatDataRoot } else { $DefaultRoot }
    $unsafeFileName  = [string]::IsNullOrWhiteSpace($safeDatFileName) -or
        [string]::IsNullOrWhiteSpace($defaultSavePath) -or
        [System.IO.Path]::GetExtension($safeDatFileName) -ne '.zip'
    if ($unsafeFileName) {
        Write-Log "EggmanDat: SECURITY -- unsafe release filename '$($rel.FileName)'"
        Write-Host "  Unexpected filename from GitHub -- skipped for safety." -ForegroundColor Red
        return $null
    }
    $defaultDestination = Get-EggmanDatPathRole -Path $defaultSavePath -RequestedRole Destination -ProgramDirectory $ProgramDirectory
    if (-not $defaultDestination.Safe) {
        $isUnderTeknoParrot = $false
        if (-not [string]::IsNullOrWhiteSpace([string]$tpRoot)) {
            try {
                $isUnderTeknoParrot = Test-PathInside $defaultDestination.CanonicalPath ([System.IO.Path]::GetFullPath($tpRoot))
            } catch {}
        }
        if ($isUnderTeknoParrot) {
            Write-Host '  Current DAT is under the TeknoParrot root, which TPM will not write to.' -ForegroundColor Yellow
            $candidates = @(Get-EggmanDatDestinationCandidates -ProgramDirectory $ProgramDirectory)
            if ($candidates.Count -gt 0) {
                $candidate = $candidates[0]
                Write-Host ("  Safe external DAT folder found: {0}" -f $candidate.Path) -ForegroundColor Green
                $choice = (Read-HostSafe 'Download latest DAT there? (Y/N)').ToUpper()
                if ($choice -eq 'Y') {
                    $defaultSavePath = Join-Path $candidate.Path $safeDatFileName
                    $defaultDestination = Get-EggmanDatPathRole -Path $defaultSavePath -RequestedRole Destination -ProgramDirectory $ProgramDirectory
                } else {
                    Write-Host '  Keeping the current DAT. No download was started.' -ForegroundColor Yellow
                    return $null
                }
            } else {
                Write-Host '  No safe external primary DAT folder is configured or reachable.' -ForegroundColor Yellow
                Write-Host '  Action: configure a reachable primary ZIP/source folder outside TeknoParrot' -ForegroundColor Yellow
                Write-Host '  and staging, verify its Windows share permissions, then run the update again.' -ForegroundColor Yellow
                return $null
            }
        } else {
            Write-Log "EggmanDat: SECURITY -- default destination failed role validation: $defaultSavePath ($($defaultDestination.Reason))"
            Write-Host '  TPM could not select a safe Eggman data location for this setup.' -ForegroundColor Yellow
            if (-not $AllowBrowse) { return $null }
            $defaultSavePath = $null
        }
    }
    $rawSave = $defaultSavePath
    if ($AllowBrowse -and [string]::IsNullOrWhiteSpace($PreferredSavePath)) {
        $prompt = if ($defaultSavePath) { "  Save to (Enter for default: $defaultSavePath)" } else { "  Save to (choose a safe alternate location)" }
        $initialDirectory = if ($defaultSavePath) { Split-Path -Parent $defaultSavePath } else { $defaultRoot }
        $rawSave = Read-PathWithBrowse $prompt -Mode SaveFile `
                       -FileFilter "ZIP files (*.zip)|*.zip|All files (*.*)|*.*" -DefaultFileName $safeDatFileName -InitialDirectory $initialDirectory
        if (-not $rawSave) { $rawSave = $defaultSavePath }
    }
    if ([string]::IsNullOrWhiteSpace($rawSave)) {
        Write-Host "  No safe Eggman data destination was selected -- skipped." -ForegroundColor Yellow
        return $null
    }
    try { $rawSave = [System.IO.Path]::GetFullPath($rawSave) } catch {
        Write-Host "  The selected Eggman data destination is not a valid path -- skipped." -ForegroundColor Yellow
        return $null
    }
    $finalDestination = Get-EggmanDatPathRole -Path $rawSave -RequestedRole Destination -ProgramDirectory $ProgramDirectory
    if (-not $finalDestination.Safe) {
        Write-Host '  Refusing to write Eggman recognition data to an unsafe or ambiguous path.' -ForegroundColor Red
        Write-Log "EggmanDat: SECURITY -- rejected destination $rawSave ($($finalDestination.Reason))"
        return $null
    }
    $rawSave = $finalDestination.CanonicalPath
    if ($rel.SizeBytes -gt 0 -and (Test-EggmanDatZip -Path $rawSave -ExpectedBytes $rel.SizeBytes)) {
        Write-Host "  Existing Eggman dat ZIP already matches the release size. Reusing it." -ForegroundColor Green
        Write-Log "EggmanDat: existing ZIP matches release size; download skipped."
        return $rawSave
    }
    Write-Host "  Downloading -- this may take a few minutes..." -ForegroundColor Cyan
    if (Invoke-EggmanDatDownload $rel.DownloadUrl $rawSave -ExpectedBytes $rel.SizeBytes -ProgramDirectory $ProgramDirectory) { return $rawSave }
    return $null
}

# =============================================================================
# POSTGRESQL INSTALL ORCHESTRATION
# =============================================================================
# Confirmed working via multiple real install attempts on a real machine
# this session (several genuine failures along the way, each root-caused
# via verbose MSI logs -- see LESSONS_LEARNED.md's PostgreSQL install notes
# for the full story). Key facts baked into the property list below:
#   - Targets postgresql-8.3-int.msi directly, NOT the postgresql-8.3.msi
#     wrapper -- the wrapper is a near-empty UI shell with no real
#     Feature/Component data of its own; under /qn it has nothing to do
#     and fails.
#   - INTERNALLAUNCH=1 satisfies the internal MSI's own LaunchCondition
#     ("INTERNALLAUNCH=1 OR Installed"), bypassing the wrapper entirely.
#   - ROOTDRIVE=C:\ is required -- without it, MSI's default drive-
#     selection heuristic can pick whatever local drive has the most free
#     space, which would not match the hardcoded
#     C:\Program Files (x86)\PostgreSQL\8.3\ path baked into every
#     GameProfile's Path field.
#   - SERVICEDOMAIN must be the real computer name, NOT the Win32 "local
#     machine" literal "." -- this custom action does its own domain\
#     username string handling and does not resolve "." correctly, which
#     manifests as "No mapping between account names and security IDs
#     was done".

# Queries the GitHub API for the Eggmansworld/tp-it-guides "universal-guide"
# release, which bundles both the PDF setup guide and the actual
# PostgreSQL 8.3 installer files. Unlike the Eggman dat repo, this repo
# hosts several distinct release tags for different purposes (a
# customization guide, a score-submission pack, an obsolete-guides
# archive) -- "latest" would return whichever was most recently published,
# not necessarily this one, so this fetches by the specific known tag.
# Returns [pscustomobject]@{DownloadUrl; FileName; SizeMB} or $null on failure.
function Get-PostgresGuideRelease {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/Eggmansworld/tp-it-guides/releases/tags/universal-guide'
            $resp   = Invoke-WebRequest -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $rel    = $resp.Content | ConvertFrom-Json
            $asset  = @($rel.assets) | Where-Object { $_.name -like '*.zip' } | Select-Object -First 1
            if (-not $asset) { return $null }
            if ($asset.browser_download_url -notmatch '^https://[a-zA-Z0-9._-]*(github\.com|githubusercontent\.com)/') {
                Write-Log "PostgresGuide: unexpected download URL format -- skipping."
                return $null
            }
            return [pscustomobject]@{
                DownloadUrl = $asset.browser_download_url
                FileName    = $asset.name
                SizeMB      = [Math]::Round($asset.size / 1MB, 1)
                SizeBytes   = [int64]$asset.size
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "PostgresGuide: GitHub release query failed -- $_"; return $null
            }
            Write-Log "PostgresGuide: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# Downloads the guide ZIP through the shared hardened download pipeline.
function Invoke-PostgresGuideDownload {
    param([string]$downloadUrl, [string]$savePath, [Int64]$ExpectedBytes = 0)
    return (Invoke-TpmDownload -DownloadUrl $downloadUrl -DestinationPath $savePath -ExpectedBytes $ExpectedBytes -Label 'PostgresGuide')
}

# True if the current process has Administrator privileges. Installing
# PostgreSQL as a Windows service requires this -- the first such check in
# this script, since every other write this script makes is to ordinary
# user-writable folders or files this script's own process already has
# rights to.
function Test-RunningAsAdministrator {
    $identity  = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

# Explain why Windows permission is needed before TPM starts its automatic
# elevation/resume handoff. The normal user path never asks a beginner to
# close TPM, find a script, or select the same menu item again.
function Write-PostgresAdministratorGuidance {
    param(
        [ValidateSet('Install','Recovery')]
        [string]$Operation = 'Recovery'
    )
    if ($Operation -eq 'Install') {
        Write-Host '  TPM needs Windows permission to install the small local database used by these games.' -ForegroundColor Yellow
    } else {
        Write-Host '  TPM needs Windows permission to repair the saved PostgreSQL password.' -ForegroundColor Yellow
    }
    Write-Host '  Windows will ask you to approve this. TPM will continue the same setup automatically.' -ForegroundColor Yellow
    Write-Host '  You do not need to close TPM or choose PostgreSQL setup again.' -ForegroundColor Yellow
    Write-Host '  Existing PostgreSQL data and profiles are protected; TPM backs up before changing anything.' -ForegroundColor Yellow
}

function Get-PostgresRecoveryStateDirectory {
    $base = if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) { $env:LOCALAPPDATA } else { $env:TEMP }
    return (Join-Path $base 'TeknoParrotManager\Recovery')
}

function Set-PostgresRecoveryStateAcl {
    param([Parameter(Mandatory)][string]$Path, [switch]$Directory)
    $sid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $permission = if ($Directory) { '(OI)(CI)(F)' } else { '(F)' }
    $rules = @(
        ('*{0}:{1}' -f $sid, $permission),
        ('*S-1-5-32-544:{0}' -f $permission),
        ('*S-1-5-18:{0}' -f $permission)
    )
    & icacls $Path /inheritance:r /grant:r @rules 1>$null 2>$null
    if ($LASTEXITCODE -ne 0) { throw 'Postgres recovery state ACL could not be verified.' }
}

function Protect-PostgresRecoveryEnvelope {
    param([Parameter(Mandatory)][string]$PlainText)
    Add-Type -AssemblyName System.Security
    $bytes = [Text.Encoding]::UTF8.GetBytes($PlainText)
    try {
        $protected = [Security.Cryptography.ProtectedData]::Protect(
            $bytes, $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
        return [Convert]::ToBase64String($protected)
    } finally {
        if ($bytes) { [Array]::Clear($bytes, 0, $bytes.Length) }
    }
}

function Unprotect-PostgresRecoveryEnvelope {
    param([Parameter(Mandatory)][string]$ProtectedText)
    Add-Type -AssemblyName System.Security
    $protected = [Convert]::FromBase64String($ProtectedText)
    $bytes = $null
    try {
        $bytes = [Security.Cryptography.ProtectedData]::Unprotect(
            $protected, $null, [Security.Cryptography.DataProtectionScope]::LocalMachine)
        return [Text.Encoding]::UTF8.GetString($bytes)
    } finally {
        if ($protected) { [Array]::Clear($protected, 0, $protected.Length) }
        if ($bytes) { [Array]::Clear($bytes, 0, $bytes.Length) }
    }
}

function Remove-PostgresRecoveryState {
    param([string]$Path, [string]$ClaimPath = '')
    $targets = @($Path, $ClaimPath) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
    try {
        foreach ($target in $targets) {
            if (Test-Path -LiteralPath $target -PathType Leaf) {
                Remove-Item -LiteralPath $target -Force -ErrorAction Stop
            }
        }
        return (@($targets | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf }).Count -eq 0)
    } catch {
        Write-Log 'Postgres recovery: protected resume state cleanup failed.'
        return $false
    }
}

function New-PostgresRecoveryState {
    param(
        [Parameter(Mandatory)][string]$ConfigPath,
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [ValidateSet('Install','Recovery')]
        [string]$Operation = 'Recovery',
        [string]$PasswordPlain = '',
        [int]$AttemptId = 1,
        [int]$ParentPid = 0,
        [Int64]$ParentStartTicks = 0,
        [string]$ParentProcessPath = '',
        [string]$ParentProcessSha256 = '',
        [string]$OriginUserSid = '',
        [string]$ExpectedScriptSha256 = '',
        [string]$ExpectedConfigSha256 = ''
    )
    if ($Operation -eq 'Recovery' -and [string]::IsNullOrEmpty($PasswordPlain)) {
        throw 'Postgres recovery state requires a chosen password.'
    }
    if ($AttemptId -lt 1 -or $AttemptId -gt 5) { throw 'Postgres recovery state attempt limit was exceeded.' }
    $stateDirectory = Get-PostgresRecoveryStateDirectory
    $issuanceId = [guid]::NewGuid().ToString('N')
    $statePath = Join-Path $stateDirectory ('.tpm-postgres-recovery-' + $issuanceId + '.json')
    $tempPath = $statePath + '.tmp'
    try {
        [void][System.IO.Directory]::CreateDirectory($stateDirectory)
        Set-PostgresRecoveryStateAcl -Path $stateDirectory -Directory
        $parent = if ($ParentPid -gt 0) { Get-Process -Id $ParentPid -ErrorAction Stop } else { Get-Process -Id $PID -ErrorAction Stop }
        if ($ParentPid -le 0) { $ParentPid = [int]$PID }
        if ($ParentStartTicks -le 0) { $ParentStartTicks = [int64]$parent.StartTime.ToUniversalTime().Ticks }
        if ([string]::IsNullOrWhiteSpace($ParentProcessPath)) { $ParentProcessPath = [string]$parent.Path }
        if ([string]::IsNullOrWhiteSpace($ParentProcessPath) -or -not (Test-Path -LiteralPath $ParentProcessPath -PathType Leaf)) { throw 'Postgres recovery parent executable could not be verified.' }
        if ([string]::IsNullOrWhiteSpace($ParentProcessSha256)) { $ParentProcessSha256 = (Get-FileHash -LiteralPath $ParentProcessPath -Algorithm SHA256 -ErrorAction Stop).Hash }
        if ([string]::IsNullOrWhiteSpace($OriginUserSid)) { $OriginUserSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value }
        $scriptFull = [System.IO.Path]::GetFullPath($ScriptPath)
        $configFull = [System.IO.Path]::GetFullPath($ConfigPath)
        $scriptHash = (Get-FileHash -LiteralPath $scriptFull -Algorithm SHA256 -ErrorAction Stop).Hash
        $configHash = (Get-FileHash -LiteralPath $configFull -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($ExpectedScriptSha256 -and $scriptHash -ne $ExpectedScriptSha256) { throw 'Postgres recovery script changed during retry.' }
        if ($ExpectedConfigSha256 -and $configHash -ne $ExpectedConfigSha256) { throw 'Postgres recovery configuration changed during retry.' }
        $created = (Get-Date).ToUniversalTime()
        $expires = $created.AddMinutes(5)
        $payload = [ordered]@{
            SchemaVersion           = 3
            Purpose                 = 'TeknoParrotManager.PostgresRecovery'
            IssuanceId              = $issuanceId
            Operation               = $Operation
            Nonce                   = [guid]::NewGuid().ToString('N')
            AttemptId               = $AttemptId
            CreatedUtc              = $created.ToString('o')
            ExpiresUtc              = $expires.ToString('o')
            ParentPid               = $ParentPid
            ParentStartTicks        = $ParentStartTicks
            ParentProcessPath       = [System.IO.Path]::GetFullPath($ParentProcessPath)
            ParentProcessSha256     = $ParentProcessSha256
            OriginUserSid           = $OriginUserSid
            MachineName             = [Environment]::MachineName
            ScriptPath              = $scriptFull
            ScriptSha256            = $scriptHash
            ConfigPath              = $configFull
            ConfigSha256            = $configHash
            TpRoot                  = [System.IO.Path]::GetFullPath($TpRoot)
            UserProfilesDir         = [System.IO.Path]::GetFullPath($UserProfilesDir)
            PasswordPlain           = $PasswordPlain
            PasswordOriginEncrypted = if ($Operation -eq 'Recovery') { ConvertTo-PostgresEncryptedPassword -PlainText $PasswordPlain } else { '' }
        }
        $outer = [ordered]@{
            SchemaVersion = 3
            Purpose       = 'TeknoParrotManager.PostgresRecovery'
            CipherText    = Protect-PostgresRecoveryEnvelope -PlainText ($payload | ConvertTo-Json -Depth 6)
        }
        [System.IO.File]::WriteAllText($tempPath, ($outer | ConvertTo-Json -Depth 4), (New-Object System.Text.UTF8Encoding $false))
        Set-PostgresRecoveryStateAcl -Path $tempPath
        [System.IO.File]::Move($tempPath, $statePath)
        Set-PostgresRecoveryStateAcl -Path $statePath
        if (-not (Test-Path -LiteralPath $statePath -PathType Leaf)) { throw 'Protected recovery state was not created.' }
        return $statePath
    } catch {
        [void](Remove-PostgresRecoveryState -Path $statePath)
        if (Test-Path -LiteralPath $tempPath -PathType Leaf) { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue }
        throw 'TPM could not prepare the protected PostgreSQL recovery handoff.'
    } finally {
        $PasswordPlain = $null
        [GC]::Collect()
    }
}

function New-PostgresRecoveryRetryState {
    param([Parameter(Mandatory)]$State)
    return New-PostgresRecoveryState -ConfigPath $State.ConfigPath -ScriptPath $State.ScriptPath `
        -TpRoot $State.TpRoot -UserProfilesDir $State.UserProfilesDir -Operation $State.Operation `
        -PasswordPlain $State.PasswordPlain -AttemptId ([int]$State.AttemptId + 1) `
        -ParentPid ([int]$State.ParentPid) -ParentStartTicks ([Int64]$State.ParentStartTicks) `
        -ParentProcessPath $State.ParentProcessPath -ParentProcessSha256 $State.ParentProcessSha256 `
        -OriginUserSid $State.OriginUserSid -ExpectedScriptSha256 $State.ScriptSha256 `
        -ExpectedConfigSha256 $State.ConfigSha256
}

function Find-PostgresRecoveryRetryState {
    param(
        [Parameter(Mandatory)][string]$PreviousStatePath,
        [Parameter(Mandatory)][string]$ExpectedConfigPath,
        [Parameter(Mandatory)][string]$ExpectedScriptPath,
        [Parameter(Mandatory)][string]$ExpectedTpRoot,
        [Parameter(Mandatory)][string]$ExpectedUserProfilesDir,
        [Parameter(Mandatory)][int]$ExpectedParentPid,
        [Parameter(Mandatory)][int]$PreviousAttemptId
    )
    $stateDirectory = [System.IO.Path]::GetFullPath((Get-PostgresRecoveryStateDirectory)).TrimEnd('\','/')
    $previousFull = [System.IO.Path]::GetFullPath($PreviousStatePath)
    foreach ($candidate in @(Get-ChildItem -LiteralPath $stateDirectory -Filter '.tpm-postgres-recovery-*.json' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTimeUtc -Descending)) {
        if ($candidate.FullName -ieq $previousFull) { continue }
        try {
            $outer = Get-Content -LiteralPath $candidate.FullName -Raw -ErrorAction Stop | ConvertFrom-Json
            if ($outer.SchemaVersion -ne 3 -or $outer.Purpose -ne 'TeknoParrotManager.PostgresRecovery' -or [string]::IsNullOrWhiteSpace([string]$outer.CipherText)) { continue }
            $payload = Unprotect-PostgresRecoveryEnvelope -ProtectedText ([string]$outer.CipherText) | ConvertFrom-Json
            if ([int]$payload.ParentPid -ne $ExpectedParentPid -or [int]$payload.AttemptId -le $PreviousAttemptId) { continue }
            if ([System.IO.Path]::GetFullPath([string]$payload.ConfigPath) -ine [System.IO.Path]::GetFullPath($ExpectedConfigPath) -or
                [System.IO.Path]::GetFullPath([string]$payload.ScriptPath) -ine [System.IO.Path]::GetFullPath($ExpectedScriptPath) -or
                [System.IO.Path]::GetFullPath([string]$payload.TpRoot) -ine [System.IO.Path]::GetFullPath($ExpectedTpRoot) -or
                [System.IO.Path]::GetFullPath([string]$payload.UserProfilesDir) -ine [System.IO.Path]::GetFullPath($ExpectedUserProfilesDir)) { continue }
            return $candidate.FullName
        } catch {}
    }
    return $null
}

function Read-PostgresRecoveryState {
    param(
        [Parameter(Mandatory)][string]$StatePath,
        [Parameter(Mandatory)][string]$ExpectedConfigPath,
        [Parameter(Mandatory)][string]$ExpectedScriptPath,
        [Parameter(Mandatory)][string]$ExpectedTpRoot,
        [Parameter(Mandatory)][string]$ExpectedUserProfilesDir
    )
    $passwordPlain = $null
    $fullPath = $null
    $claimPath = $null
    $usedPath = $null
    try {
        $stateDirectory = [System.IO.Path]::GetFullPath((Get-PostgresRecoveryStateDirectory)).TrimEnd('\','/')
        $fullPath = [System.IO.Path]::GetFullPath($StatePath)
        $leaf = [System.IO.Path]::GetFileName($fullPath)
        $issuanceMatch = [regex]::Match($leaf, '^\.tpm-postgres-recovery-(?<id>[0-9a-f]{32})\.json$')
        if ([System.IO.Path]::GetDirectoryName($fullPath).TrimEnd('\','/') -ine $stateDirectory -or
            -not $issuanceMatch.Success -or
            -not (Test-Path -LiteralPath $fullPath -PathType Leaf)) { throw 'Recovery state path is not a TPM state file.' }
        $fileIssuanceId = $issuanceMatch.Groups['id'].Value
        $claimPath = $fullPath + '.claim'
        $usedPath = $fullPath + '.used'
        if ((Test-Path -LiteralPath $usedPath -PathType Leaf) -or (Test-Path -LiteralPath $claimPath -PathType Leaf)) { throw 'Recovery state was already consumed.' }
        [System.IO.File]::Move($fullPath, $claimPath)
        $markerStream = $null
        try {
            $markerStream = [System.IO.File]::Open($usedPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
            $markerStream.Close()
        } finally {
            if ($markerStream) { $markerStream.Dispose() }
        }
        Set-PostgresRecoveryStateAcl -Path $usedPath
        $outer = Get-Content -LiteralPath $claimPath -Raw -ErrorAction Stop | ConvertFrom-Json
        if ($outer.SchemaVersion -ne 3 -or $outer.Purpose -ne 'TeknoParrotManager.PostgresRecovery' -or [string]::IsNullOrWhiteSpace([string]$outer.CipherText)) { throw 'Recovery state envelope is invalid.' }
        $payload = Unprotect-PostgresRecoveryEnvelope -ProtectedText ([string]$outer.CipherText) | ConvertFrom-Json
        if ($payload.SchemaVersion -ne 3 -or $payload.Purpose -ne 'TeknoParrotManager.PostgresRecovery' -or
            [string]$payload.IssuanceId -ne $fileIssuanceId -or
            $payload.Operation -notin @('Install','Recovery') -or [string]::IsNullOrWhiteSpace([string]$payload.Nonce) -or
            [int]$payload.AttemptId -lt 1 -or [int]$payload.AttemptId -gt 5) { throw 'Recovery state metadata is invalid.' }
        $now = (Get-Date).ToUniversalTime()
        $created = if ($payload.CreatedUtc -is [DateTime]) { ([DateTime]$payload.CreatedUtc).ToUniversalTime() } else { [DateTimeOffset]::Parse([string]$payload.CreatedUtc).UtcDateTime }
        $expires = if ($payload.ExpiresUtc -is [DateTime]) { ([DateTime]$payload.ExpiresUtc).ToUniversalTime() } else { [DateTimeOffset]::Parse([string]$payload.ExpiresUtc).UtcDateTime }
        if ($expires -le $created -or ($expires - $created) -gt [TimeSpan]::FromMinutes(5) -or $created -gt $now.AddMinutes(2) -or $expires -le $now) { throw 'Recovery state lifetime is invalid or expired.' }
        if ([System.IO.Path]::GetFullPath([string]$payload.ConfigPath) -ine [System.IO.Path]::GetFullPath($ExpectedConfigPath) -or
            [System.IO.Path]::GetFullPath([string]$payload.ScriptPath) -ine [System.IO.Path]::GetFullPath($ExpectedScriptPath) -or
            [System.IO.Path]::GetFullPath([string]$payload.TpRoot) -ine [System.IO.Path]::GetFullPath($ExpectedTpRoot) -or
            [System.IO.Path]::GetFullPath([string]$payload.UserProfilesDir) -ine [System.IO.Path]::GetFullPath($ExpectedUserProfilesDir)) { throw 'Recovery state belongs to a different TPM installation.' }
        if ([string]$payload.MachineName -ine [Environment]::MachineName -or [string]$payload.OriginUserSid -ne [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value) { throw 'Recovery state belongs to a different Windows identity.' }
        $parent = Get-Process -Id ([int]$payload.ParentPid) -ErrorAction Stop
        if ([int64]$parent.StartTime.ToUniversalTime().Ticks -ne [int64]$payload.ParentStartTicks -or
            [System.IO.Path]::GetFullPath([string]$parent.Path) -ine [System.IO.Path]::GetFullPath([string]$payload.ParentProcessPath) -or
            (Get-FileHash -LiteralPath $parent.Path -Algorithm SHA256 -ErrorAction Stop).Hash -ne [string]$payload.ParentProcessSha256) { throw 'Recovery parent identity changed.' }
        if ((Get-FileHash -LiteralPath $ExpectedScriptPath -Algorithm SHA256 -ErrorAction Stop).Hash -ne [string]$payload.ScriptSha256 -or
            (Get-FileHash -LiteralPath $ExpectedConfigPath -Algorithm SHA256 -ErrorAction Stop).Hash -ne [string]$payload.ConfigSha256) { throw 'Recovery source or configuration changed during the handoff.' }
        $markerText = 'TPM.PostgresRecovery.v3|' + [string]$payload.IssuanceId + '|' + [string]$payload.Nonce + '|' + [string]$payload.AttemptId
        [System.IO.File]::WriteAllText($usedPath, $markerText, (New-Object System.Text.UTF8Encoding $false))
        if ((Get-Content -LiteralPath $usedPath -Raw -ErrorAction Stop) -ne $markerText) { throw 'Recovery state consumption marker could not be verified.' }
        if ($payload.Operation -eq 'Recovery') {
            $passwordPlain = [string]$payload.PasswordPlain
            if ([string]::IsNullOrEmpty($passwordPlain) -or [string]::IsNullOrEmpty([string]$payload.PasswordOriginEncrypted)) { throw 'Recovery password state is missing.' }
        } elseif (-not [string]::IsNullOrEmpty([string]$payload.PasswordPlain) -or -not [string]::IsNullOrEmpty([string]$payload.PasswordOriginEncrypted)) {
            throw 'Install state unexpectedly contains a password.'
        }
        return [pscustomobject]@{
            Path                    = $fullPath
            ClaimPath               = $claimPath
            UsedPath                = $usedPath
            IssuanceId              = [string]$payload.IssuanceId
            Nonce                   = [string]$payload.Nonce
            Operation               = [string]$payload.Operation
            AttemptId               = [int]$payload.AttemptId
            CreatedUtc              = [string]$payload.CreatedUtc
            ExpiresUtc              = [string]$payload.ExpiresUtc
            ParentPid               = [int]$payload.ParentPid
            ParentStartTicks        = [Int64]$payload.ParentStartTicks
            ParentProcessPath       = [string]$payload.ParentProcessPath
            ParentProcessSha256     = [string]$payload.ParentProcessSha256
            OriginUserSid            = [string]$payload.OriginUserSid
            ScriptPath              = [string]$payload.ScriptPath
            ScriptSha256            = [string]$payload.ScriptSha256
            ConfigPath              = [string]$payload.ConfigPath
            ConfigSha256            = [string]$payload.ConfigSha256
            TpRoot                  = [string]$payload.TpRoot
            UserProfilesDir         = [string]$payload.UserProfilesDir
            PasswordPlain           = $passwordPlain
            PasswordOriginEncrypted = [string]$payload.PasswordOriginEncrypted
        }
    } catch {
        Write-Log ("Postgres recovery state validation failed -- {0}" -f $_.Exception.Message)
        try {
            if ($usedPath -and (Test-Path -LiteralPath $usedPath -PathType Leaf)) { Remove-Item -LiteralPath $usedPath -Force -ErrorAction Stop }
            if ($claimPath -and (Test-Path -LiteralPath $claimPath -PathType Leaf) -and -not (Test-Path -LiteralPath $fullPath -PathType Leaf)) {
                [System.IO.File]::Move($claimPath, $fullPath)
            }
        } catch { Write-Log 'Postgres recovery state validation cleanup failed; encrypted evidence was retained.' }
        throw 'TPM could not safely resume the protected PostgreSQL setup.'
    } finally {
        $passwordPlain = $null
        [GC]::Collect()
    }
}

function Exit-PostgresRecoveryResume {
    param([Parameter(Mandatory)][string]$Message, [int]$ExitCode = 1)
    $retryPath = $null
    $resumeState = $script:PostgresRecoveryResumeState
    if ($resumeState -and $resumeState.ClaimPath) {
        try {
            $retryPath = New-PostgresRecoveryRetryState -State $resumeState
            if (-not (Remove-PostgresRecoveryState -Path $resumeState.Path -ClaimPath $resumeState.ClaimPath)) {
                $retryPath = $null
            }
        } catch {
            $retryPath = $null
        }
    }
    if ($script:PostgresRecoveryStatus) {
        try {
            [void](Set-TpmWorkflowFailure -Context $script:PostgresRecoveryStatus -FailureId 'postgres-resume-failure' -Message $Message -DataSafety 'TPM did not report profile or database changes as complete.' -RecoveryActions @(@{ Id = 'Retry'; Label = 'Use the protected retry' }; @{ Id = 'Stop'; Label = 'Stop safely' }))
        } catch {}
    }
    Write-Host ''
    Write-Host ('  ' + $Message) -ForegroundColor Red
    Write-Host '  TPM did not report the PostgreSQL setup as complete. No further profile changes were made.' -ForegroundColor Yellow
    if ($retryPath) {
        Write-Host '  TPM preserved a protected retry. Choose PostgreSQL setup again to continue safely.' -ForegroundColor Yellow
        Write-Log 'Postgres recovery resume: stopped before completion; a fresh protected retry state was issued.'
    } else {
        Write-Host '  TPM could not preserve a safe retry state. Nothing else was changed.' -ForegroundColor Yellow
        Write-Log 'Postgres recovery resume: stopped before completion; no retry state was retained.'
    }
    [void](Read-HostSafe '  Press Enter to close TPM')
    if ($script:PostgresRecoveryStatus -and $script:PostgresRecoveryStatus.Failure) {
        try {
            [void](Acknowledge-TpmWorkflowFailure -Context $script:PostgresRecoveryStatus -FailureId 'postgres-resume-failure')
            [void](Stop-TpmWorkflowStatus -Context $script:PostgresRecoveryStatus -Reason 'PostgreSQL recovery stopped')
            [void](Close-TpmWorkflowStatus -Context $script:PostgresRecoveryStatus)
        } catch {}
    }
    exit $ExitCode
}

function ConvertTo-PostgresProcessArgument {
    param([Parameter(Mandatory)][string]$Value)
    if ($Value -notmatch '[\s"]') { return $Value }
    return '"' + ($Value -replace '(\\*)"', '$1$1\"' -replace '(\\+)$', '$1$1') + '"'
}

function Start-PostgresRecoveryAsAdministrator {
    param(
        [Parameter(Mandatory)][string]$ConfigPath,
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][string]$TpRoot,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [ValidateSet('Install','Recovery')]
        [string]$Operation = 'Recovery',
        [string]$PasswordPlain = ''
    )
    $statePath = $null
    $attemptId = 1
    $makeArguments = {
        param([string]$Token)
        $items = @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $ScriptPath, '-PostgresRecoveryResumeToken', $Token)
        return (($items | ForEach-Object { ConvertTo-PostgresProcessArgument -Value ([string]$_) }) -join ' ')
    }
    try {
        $statePath = New-PostgresRecoveryState -ConfigPath $ConfigPath -ScriptPath $ScriptPath -TpRoot $TpRoot -UserProfilesDir $UserProfilesDir -Operation $Operation -PasswordPlain $PasswordPlain
        $hostName = if ($PSVersionTable.PSEdition -eq 'Core') { 'pwsh.exe' } else { 'powershell.exe' }
        $hostPath = Join-Path $PSHOME $hostName
        if (-not (Test-Path -LiteralPath $hostPath -PathType Leaf)) { throw 'PowerShell host was not found.' }
        $argumentString = & $makeArguments $statePath
    } catch {
        Write-Host '  TPM could not prepare the automatic repair. No changes were made.' -ForegroundColor Red
        Write-Log 'Postgres recovery: protected UAC handoff could not be prepared.'
        [void](Remove-PostgresRecoveryState -Path $statePath)
        return $false
    } finally {
        $PasswordPlain = $null
        [GC]::Collect()
    }

    while ($true) {
        Write-Host '  TPM will ask Windows for permission, then continue this setup automatically.' -ForegroundColor Cyan
        $childExit = $null
        try {
            $child = Start-Process -FilePath $hostPath -ArgumentList $argumentString -Verb RunAs -Wait -PassThru -ErrorAction Stop
            $childExit = [int]$child.ExitCode
            if ($childExit -eq 0) {
                if (-not (Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))) {
                    Write-Host '  PostgreSQL setup finished, but TPM could not clean its one-time recovery record.' -ForegroundColor Red
                    Write-Log 'Postgres recovery: child succeeded but consumed-state cleanup was not verified.'
                    return $false
                }
                return $true
            }
            Write-Host '  Windows allowed TPM to continue, but PostgreSQL setup did not finish.' -ForegroundColor Red
        } catch {
            Write-Host '  Windows did not give TPM permission to continue.' -ForegroundColor Yellow
            Write-Log 'Postgres recovery: UAC approval was unavailable or was declined.'
        }
        $nextState = Find-PostgresRecoveryRetryState -PreviousStatePath $statePath `
            -ExpectedConfigPath $ConfigPath -ExpectedScriptPath $ScriptPath -ExpectedTpRoot $TpRoot `
            -ExpectedUserProfilesDir $UserProfilesDir -ExpectedParentPid $PID -PreviousAttemptId $attemptId
        if ($nextState) {
            $statePath = $nextState
            $attemptId++
            $argumentString = & $makeArguments $statePath
            Write-Host '  TPM prepared a fresh protected retry. Your password was not requested again.' -ForegroundColor Yellow
        } elseif (Test-Path -LiteralPath $statePath -PathType Leaf) {
            Write-Host '  Nothing was changed by the failed automatic repair. The protected repair information is still available.' -ForegroundColor Yellow
        } else {
            Write-Host '  TPM consumed the failed attempt and could not prepare a safe retry. Nothing else was changed.' -ForegroundColor Yellow
        }
        $retry = (Read-HostSafe '  Try again? (Y/N)').ToUpper()
        if ($retry -ne 'Y') {
            [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
            return $false
        }
        if (-not (Test-Path -LiteralPath $statePath -PathType Leaf)) {
            Write-Host '  TPM cannot retry this consumed attempt safely. Start PostgreSQL setup again to create a new protected request.' -ForegroundColor Red
            [void](Read-HostSafe '  Press Enter to continue')
            return $false
        }
    }
}

# Decrypts a SecureString to plaintext only as long as needed, then
# explicitly zeroes and frees the unmanaged memory holding it -- letting GC
# eventually collect a managed string isn't the same as zeroing the bytes,
# and a password is worth being careful about even briefly. Also used by
# the DPAPI-encrypted config storage below to decrypt back to plaintext
# only at the point of use.
function ConvertFrom-SecureStringPlain {
    param([System.Security.SecureString]$Secure)
    $ptr = [Runtime.InteropServices.Marshal]::SecureStringToGlobalAllocUnicode($Secure)
    try {
        return [Runtime.InteropServices.Marshal]::PtrToStringUni($ptr)
    } finally {
        [Runtime.InteropServices.Marshal]::ZeroFreeGlobalAllocUnicode($ptr)
    }
}

# Encrypts a plaintext password for storage in config.json via Windows
# DPAPI (ConvertFrom-SecureString with no -Key ties the result to the
# current Windows user + machine) -- the inverse of
# ConvertFrom-SecureStringPlain. Used to persist the Postgres superuser
# password after a successful install; nothing else in this script has
# ever needed to store a secret before this feature.
function ConvertTo-PostgresEncryptedPassword {
    param([string]$PlainText)
    $secure = ConvertTo-SecureString -String $PlainText -AsPlainText -Force
    return ($secure | ConvertFrom-SecureString)
}

# Accepts two SecureString entries and returns plaintext only to the immediate
# caller. The entries are cleared on every path; the prompt never echoes the
# approved password and no retry detail includes it.
function Read-ConfirmedPostgresPassword {
    param([string]$WhatFor)
    while ($true) {
        $firstPlain = $null; $secondPlain = $null
        try {
            $first = Read-Host "  Enter $WhatFor" -AsSecureString
            $second = Read-Host '  Re-enter the same password to confirm' -AsSecureString
            $firstPlain = ConvertFrom-SecureStringPlain $first
            $secondPlain = ConvertFrom-SecureStringPlain $second
            if (-not [string]::IsNullOrEmpty($firstPlain) -and [string]::Equals($firstPlain, $secondPlain, [System.StringComparison]::Ordinal)) {
                $approved = $firstPlain
                return $approved
            }
        } finally {
            $firstPlain = $null
            $secondPlain = $null
        }
        Write-Host "  Those two entries did not match or were empty -- let's try again." -ForegroundColor Yellow
    }
}

function Invoke-PostgresSelectedPasswordRecovery {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$PasswordPlain,
        [object]$StatusContext = $null
    )
    if ($StatusContext) { [void](Start-TpmWorkflowStep -Context $StatusContext -StepId 'backup' -Activity 'Making a verified safety backup') }
    Write-Host "  TPM is creating a verified recovery backup before resetting the PostgreSQL role password..." -ForegroundColor Cyan
    $backup = New-PostgresRecoveryBackup -UserProfilesDir $UserProfilesDir
    if (-not $backup.Verified) {
        return [pscustomobject]@{ Succeeded = $false; Backup = $backup; Reason = 'RECOVERY_BACKUP_UNVERIFIED' }
    }
    if ($StatusContext) { [void](Complete-TpmWorkflowStep -Context $StatusContext -Outcome Succeeded -Summary 'Verified safety backup complete' -NextStep 'Repair and verify the database password') }
    if ($StatusContext) { [void](Start-TpmWorkflowStep -Context $StatusContext -StepId 'reset' -Activity 'Repairing the PostgreSQL password') }
    $reset = Reset-PostgresPasswordAutomatically -NewPassword $PasswordPlain -RecoveryBackup $backup
    if (-not $reset.Succeeded) {
        return [pscustomobject]@{ Succeeded = $false; Backup = $backup; Reason = 'PASSWORD_RESET_FAILED' }
    }
    if (-not (Test-PostgresPassword -SuperPasswordPlain $PasswordPlain)) {
        return [pscustomobject]@{ Succeeded = $false; Backup = $backup; Reason = 'PASSWORD_VERIFICATION_FAILED' }
    }
    if ($StatusContext) { [void](Complete-TpmWorkflowStep -Context $StatusContext -Outcome Fixed -Summary 'Password repaired and verified' -NextStep 'Save the repaired settings') }
    return [pscustomobject]@{ Succeeded = $true; Backup = $backup; Reason = $null }
}

# Cross-checks PostgreSQL's own installation registry record -- written by
# the EnterpriseDB-based installer under \Installations\<install-id>,
# independent of the generic Windows Installer Uninstall key already
# checked in Remove-PostgresPartialInstall below -- against the expected
# install directory. Issue #4 (v1.0 roadmap): a second, independent
# registry source agreeing before any destructive msiexec /x call.
#
# Deliberately supplementary, not a new blocking gate: a PARTIAL/failed
# install -- the exact case Remove-PostgresPartialInstall exists to clean
# up -- may never have reached the install stage that writes this key at
# all, so its absence here is "no additional information," never a reason
# to skip cleanup. Only an explicit MISMATCH (the key exists, has an entry,
# and that entry's install directory points somewhere other than expected)
# is a red flag worth refusing to act on.
#
# The exact install-id subkey name under \Installations\ (the issue
# suggests "postgresql-8.3") is NOT assumed -- this dev machine has no real
# PostgreSQL install to verify that against (same constraint as the
# project's "no game data on this machine" note), so every existing
# install-id subkey is checked rather than guessing one exact name. "Base
# Directory" is the documented value name EnterpriseDB's installer writes
# there; if that's ever wrong on a real system, Get-ItemProperty simply
# returns nothing for it, which still degrades safely to "no additional
# information" rather than a false positive.
function Test-PostgresInstallationsRegistry {
    param([string]$ExpectedInstallDir)
    $expected = $ExpectedInstallDir.TrimEnd('\')
    $roots = @(
        "HKLM:\SOFTWARE\PostgreSQL\Installations\*",
        "HKLM:\SOFTWARE\WOW6432Node\PostgreSQL\Installations\*"
    )
    $entries = @(Get-ItemProperty -Path $roots -ErrorAction SilentlyContinue |
                     Where-Object { $_.'Base Directory' })
    if ($entries.Count -eq 0) {
        return [pscustomobject]@{ HasRecord = $false; Mismatch = $false }
    }
    # -ieq (case-insensitive EXACT equality), not -like -- this is a literal
    # path comparison, not a wildcard pattern match. Using -like here would
    # treat any `[`, `]`, or `*` in either path as wildcard syntax.
    $matching = @($entries | Where-Object { $_.'Base Directory'.TrimEnd('\') -ieq $expected })
    return [pscustomobject]@{ HasRecord = $true; Mismatch = ($matching.Count -eq 0) }
}

# Cleans up a half-installed/stale PostgreSQL 8.3 before a fresh install
# attempt. A failed install can leave a real Windows account, an orphaned
# user profile, and a ProfileList registry SID entry behind even when the
# installer itself reports failure -- confirmed empirically this session.
# Safe to call even when nothing is present -- every step checks first and
# skips cleanly. Never called when Test-PostgresInstalled is already true.
function Remove-PostgresPartialInstall {
    Write-Log "Postgres: checking for partial/stale install before fresh attempt..."

    $uninstallKeys = @(
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )
    $expectedInstallDir = $script:PostgresInstallDir.TrimEnd('\')
    $pgInstallationsCheck = Test-PostgresInstallationsRegistry -ExpectedInstallDir $expectedInstallDir
    $pgEntries = Get-ItemProperty -Path $uninstallKeys -ErrorAction SilentlyContinue |
                     Where-Object { $_.DisplayName -like "PostgreSQL*8.3*" }
    foreach ($entry in $pgEntries) {
        # Only ever uninstall an entry confirmed to be OUR install location --
        # someone could have an unrelated standalone PostgreSQL 8.3 for
        # legacy dev work at a different path, and a DisplayName match alone
        # is not enough to assume it's safe to remove. Case-insensitive EXACT
        # equality (-ine), not -notlike -- this was previously -notlike, which
        # treats the path as a wildcard pattern; a real path containing `[`,
        # `]`, or `*` could have matched/missed unintentionally. Caught in a
        # full deep-scan review; harmless today since the path is a hardcoded
        # constant with no wildcard metacharacters, but -ine is the correct
        # operator for what this comparison actually means.
        $installLoc = if ($entry.InstallLocation) { $entry.InstallLocation.TrimEnd('\') } else { '' }
        if ($installLoc -ine $expectedInstallDir) {
            Write-Log "Postgres: skipping uninstall of '$($entry.DisplayName)' -- InstallLocation '$installLoc' does not match our expected path, not touching it."
            continue
        }
        if ($pgInstallationsCheck.HasRecord -and $pgInstallationsCheck.Mismatch) {
            Write-Log "Postgres: skipping uninstall of '$($entry.DisplayName)' -- PostgreSQL's own Installations registry record disagrees with the matched InstallLocation, not touching it."
            continue
        }
        $productCode = $entry.PSChildName
        if ($productCode -notmatch '^\{[0-9A-Fa-f]{8}-([0-9A-Fa-f]{4}-){3}[0-9A-Fa-f]{12}\}$') { continue }
        $uninstallLog = Join-Path $env:TEMP ("pg83-uninstall-" + [guid]::NewGuid().ToString("N") + ".log")
        try {
            Start-Process -FilePath "msiexec.exe" -ArgumentList @("/x", $productCode, "/qn", "/l*v", "`"$uninstallLog`"") -Wait -PassThru | Out-Null
            Write-Log "Postgres: uninstalled stale entry $productCode"
        } finally {
            Remove-Item -LiteralPath $uninstallLog -Force -ErrorAction SilentlyContinue
        }
    }

    # Only the exact service name our own install recipe creates -- not a
    # wildcard match, since an unrelated Postgres install (a different
    # version, or a hand-named service) must never be stopped or deleted
    # by this cleanup.
    $pgServices = @(Get-Service -Name $script:PostgresServiceName -ErrorAction SilentlyContinue)
    foreach ($svc in $pgServices) {
        if ($svc.Status -eq 'Running') { Stop-Service -Name $svc.Name -Force -ErrorAction SilentlyContinue }
        & sc.exe delete $svc.Name | Out-Null
        Write-Log "Postgres: removed leftover service $($svc.Name)"
    }

    if (Test-Path -LiteralPath $script:PostgresInstallDir) {
        Remove-Item -LiteralPath $script:PostgresInstallDir -Recurse -Force -ErrorAction SilentlyContinue
        Write-Log "Postgres: removed leftover $script:PostgresInstallDir"
    }

    $pgUser = Get-LocalUser -Name "postgres" -ErrorAction SilentlyContinue
    if ($pgUser) {
        Remove-LocalUser -Name "postgres" -ErrorAction SilentlyContinue
        Write-Log "Postgres: removed leftover local user 'postgres'"
    }

    # Remove-LocalUser does not clean up the profile folder or its
    # ProfileList registry SID mapping -- a stale entry here produces "No
    # mapping between account names and security IDs was done" on the next
    # install attempt (confirmed empirically this session).
    $profileListPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList"
    $staleProfiles = Get-ChildItem -Path $profileListPath -ErrorAction SilentlyContinue | Where-Object {
        $imagePath = (Get-ItemProperty -Path $_.PSPath -Name ProfileImagePath -ErrorAction SilentlyContinue).ProfileImagePath
        $imagePath -and ($imagePath -like "*\postgres")
    }
    foreach ($sidKey in $staleProfiles) {
        $imagePath = (Get-ItemProperty -Path $sidKey.PSPath -Name ProfileImagePath).ProfileImagePath
        Remove-Item -Path $sidKey.PSPath -Recurse -Force -ErrorAction SilentlyContinue
        if (Test-Path -LiteralPath $imagePath) {
            Remove-Item -LiteralPath $imagePath -Recurse -Force -ErrorAction SilentlyContinue
        }
        Write-Log "Postgres: removed orphaned profile registration for $imagePath"
    }
    if (Test-Path -LiteralPath "C:\Users\postgres") {
        Remove-Item -LiteralPath "C:\Users\postgres" -Recurse -Force -ErrorAction SilentlyContinue
    }
}

# Windows Installer's Automation interface accepts the same public MSI
# properties without launching msiexec.exe. This keeps SERVICEPASSWORD and
# SUPERPASSWORD out of process argument lists while retaining the MSI's
# unattended property-driven install. No verbose installer log is requested.
function Invoke-PostgresMsiPackage {
    param(
        [Parameter(Mandatory)][string]$MsiPath,
        [Parameter(Mandatory)][string]$PropertyValues
    )
    $installer = $null
    try {
        $installer = New-Object -ComObject WindowsInstaller.Installer
        $installer.UILevel = 2
        $installer.InstallProduct($MsiPath, $PropertyValues)
        return $true
    } catch {
        Write-Log 'Postgres install: Windows Installer automation failed.'
        return $false
    } finally {
        $PropertyValues = $null
        if ($installer) {
            try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($installer) } catch {}
        }
        $installer = $null
        [GC]::Collect()
    }
}

# Installs PostgreSQL 8.3 silently using the confirmed-working property set
# above. Requires Administrator (creates a Windows service + a local user
# account) -- prints a clear message and returns $false rather than failing
# unhelpfully if not elevated. Returns $true on confirmed success
# (Test-PostgresInstalled checked afterward, not just the installer API return,
# since a misleading "success" with no real service was observed during
# this session's testing). The superuser password is returned via
# $OutSuperPasswordPlain so the caller can DPAPI-encrypt and save it --
# this function never persists anything itself, and always deletes its
# working folder (the ZIP and extracted MSI) in a finally block regardless of
# outcome. No verbose MSI log is requested because the PostgreSQL 8.3 MSI can
# write connection passwords into deferred custom-action logging.
function Install-Postgres83 {
    param([ref]$OutSuperPasswordPlain)

    if (-not (Test-RunningAsAdministrator)) {
        Write-Host "  TPM needs Windows permission before it can install PostgreSQL." -ForegroundColor Red
        Write-Host "  No changes were made. TPM will request that permission from its normal setup flow." -ForegroundColor Yellow
        Write-Log "Postgres install: aborted -- not running as Administrator."
        return $false
    }

    Write-Host ""
    Write-Host "  PostgreSQL 8.3 is required by one or more of your registered games." -ForegroundColor Cyan
    Write-Host "  It's a small local database program that runs quietly in the" -ForegroundColor DarkGray
    Write-Host "  background and only talks to TeknoParrot -- nothing is sent over" -ForegroundColor DarkGray
    Write-Host "  the internet, and it won't interfere with anything else on your PC." -ForegroundColor DarkGray
    Write-Host ""
    Write-Host "  You'll be asked for two different passwords:" -ForegroundColor White
    Write-Host "    1) A SERVICE ACCOUNT password -- for a Windows account Windows uses" -ForegroundColor DarkGray
    Write-Host "       to run PostgreSQL in the background. You'll almost never need it again." -ForegroundColor DarkGray
    Write-Host "    2) A DATABASE password -- this is the important one. It gets saved" -ForegroundColor DarkGray
    Write-Host "       (encrypted) so every Postgres game can be configured automatically." -ForegroundColor DarkGray
    Write-Host ""

    $svcPwPlain   = Read-ConfirmedPostgresPassword "the SERVICE ACCOUNT password"
    Write-Host ""
    $superPwPlain = Read-ConfirmedPostgresPassword "the DATABASE password"
    Write-Host ""

    Write-Host "  Checking for the PostgreSQL installer..." -ForegroundColor Cyan
    $rel = Get-PostgresGuideRelease
    if ($null -eq $rel) {
        Write-Host "  ERROR: Could not reach GitHub to download the installer." -ForegroundColor Red
        Write-Log "Postgres install: aborted -- could not fetch release info."
        $svcPwPlain = $null; $superPwPlain = $null
        return $false
    }

    $workDir = Join-Path $env:TEMP ("pg83-install-" + [guid]::NewGuid().ToString("N"))
    [void][System.IO.Directory]::CreateDirectory($workDir)
    $zipPath = Join-Path $workDir "guide.zip"

    try {
        Write-Host "  Downloading installer ($($rel.SizeMB) MB, this may take a minute)..." -ForegroundColor Cyan
        if (-not (Invoke-PostgresGuideDownload $rel.DownloadUrl $zipPath -ExpectedBytes $rel.SizeBytes)) {
            Write-Host "  ERROR: Download failed." -ForegroundColor Red
            return $false
        }
        Expand-ZipFileSafe -ZipPath $zipPath -DestDir $workDir -GameName "PostgreSQL installer"
        $msiFile = Get-ChildItem -LiteralPath $workDir -Filter "postgresql-8.3-int.msi" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $msiFile) {
            Write-Host "  ERROR: Installer file not found inside the downloaded ZIP." -ForegroundColor Red
            Write-Log "Postgres install: aborted -- postgresql-8.3-int.msi not found after extraction."
            return $false
        }

        Remove-PostgresPartialInstall

        Write-Host "  Installing PostgreSQL 8.3 -- this can take a minute or two..." -ForegroundColor Cyan
        $msiPropertyValues = @(
            "INTERNALLAUNCH=1",
            "ROOTDRIVE=C:\",
            "SERVICEACCOUNT=postgres",
            "SERVICEDOMAIN=$env:COMPUTERNAME",
            "SERVICEPASSWORD=`"$svcPwPlain`"",
            "SERVICEPASSWORDV=`"$svcPwPlain`"",
            "CREATESERVICEUSER=1",
            "SUPERUSER=postgres",
            "SUPERPASSWORD=`"$superPwPlain`"",
            "LISTENPORT=5432",
            "LOCALE=C",
            "ENCODING=UTF8",
            "CLENCODE=UTF8",
            "PERMITREMOTE=0",
            "RUNSTACKBUILDER=0",
            "DOSERVICE=1",
            "DOINITDB=1"
        )
        $msiPropertyString = $msiPropertyValues -join ' '
        $msiSucceeded = Invoke-PostgresMsiPackage -MsiPath $msiFile.FullName -PropertyValues $msiPropertyString
        $msiPropertyString = $null
        $msiPropertyValues = $null
        $svcPwPlain = $null
        [GC]::Collect()

        if (-not $msiSucceeded -or -not (Test-PostgresInstalled)) {
            Write-Host "  ERROR: PostgreSQL install did not complete successfully." -ForegroundColor Red
            Write-Log 'Postgres install: FAILED -- Windows Installer did not produce a verified PostgreSQL service.'
            $superPwPlain = $null
            return $false
        }


        Write-Host "  PostgreSQL 8.3 installed and running." -ForegroundColor Green
        Write-Log "Postgres install: succeeded."
        $OutSuperPasswordPlain.Value = $superPwPlain
        return $true
    } finally {
        $svcPwPlain = $null
        $superPwPlain = $null
        [GC]::Collect()
        Remove-Item -LiteralPath $workDir -Recurse -Force -ErrorAction SilentlyContinue
    }
}

# =============================================================================
# POSTGRESQL PER-GAME SETUP  (field configuration + database creation/restore)
# =============================================================================

# Locates the right backup file inside a game's own pg_backup folder. Per
# the guide: backups may sit directly inside pg_backup\, or inside a
# YYYY-MM-DD-named subfolder; when subfolders exist, the most recent one
# (by name -- they're ISO-formatted and sort correctly as strings) is used.
# The right file within is the one with the highest leading 4-digit
# number. Hardcoding the exact filename per the guide's Appendix A was
# deliberately avoided -- the guide itself says these drift as games get
# updated. Returns the full file path, or $null if pg_backup doesn't exist
# or contains nothing recognizable.
function Get-PostgresBackupFile {
    param([string]$GameFolder)

    $pgBackupDir = Join-Path $GameFolder "pg_backup"
    if (-not (Test-Path -LiteralPath $pgBackupDir)) { return $null }

    $dateSubfolders = @(Get-ChildItem -LiteralPath $pgBackupDir -Directory -ErrorAction SilentlyContinue |
                            Where-Object { $_.Name -match '^\d{4}-\d{2}-\d{2}$' } | Sort-Object Name -Descending)
    $searchDir = if ($dateSubfolders.Count -gt 0) { $dateSubfolders[0].FullName } else { $pgBackupDir }

    $candidates = @(Get-ChildItem -LiteralPath $searchDir -File -ErrorAction SilentlyContinue)
    if ($candidates.Count -eq 0) { return $null }

    $best = $candidates | Sort-Object -Descending -Property {
        if ($_.Name -match '^(\d{4})') { [int]$Matches[1] } else { -1 }
    } | Select-Object -First 1
    return $best.FullName
}

# Creates a database and restores a bundled backup only after a verified
# database-state query proved that the exact database name is absent. It
# never drops or recreates an existing database.
function New-PostgresDatabaseFromBackup {
    param([string]$DbName, [string]$Encoding, [string]$BackupFile, [string]$SuperPasswordPlain)
    if (-not (Test-SafePostgresDbName $DbName)) { Write-Log 'Postgres: refusing unsafe database name.'; return $false }
    foreach ($exeName in @('createdb.exe', 'psql.exe', 'pg_restore.exe')) {
        if (-not (Test-Path -LiteralPath (Join-Path $script:PostgresBinDir $exeName) -PathType Leaf)) { return $false }
    }
    if (-not (Test-Path -LiteralPath $BackupFile -PathType Leaf)) { return $false }
    $createdbExe = Join-Path $script:PostgresBinDir 'createdb.exe'
    $psqlExe = Join-Path $script:PostgresBinDir 'psql.exe'
    $pgRestoreExe = Join-Path $script:PostgresBinDir 'pg_restore.exe'
    $pgpassFile = New-PostgresPgPassFile -Password $SuperPasswordPlain
    $previousPgPassFile = $null
    try {
        $previousPgPassFile = Set-PostgresPgPassFileEnvironment -Path $pgpassFile
        & $createdbExe -U postgres -h 127.0.0.1 -p 5432 -E $Encoding -T template0 $DbName 2>&1 | Out-Null
        if ($LASTEXITCODE -ne 0) { return $false }
        & $psqlExe -U postgres -h 127.0.0.1 -p 5432 -d $DbName -c "ALTER DATABASE `"$DbName`" SET standard_conforming_strings = on;" 2>&1 | Out-Null
        & $pgRestoreExe -U postgres -h 127.0.0.1 -p 5432 -d $DbName $BackupFile 2>&1 | Out-Null
        if ($LASTEXITCODE -ne 0) { return $false }
        $state = Get-PostgresDatabaseState -DbName $DbName -SuperPasswordPlain $SuperPasswordPlain
        return ($state.Verified -and $state.Exists)
    } catch { return $false }
    finally {
        Restore-PostgresPgPassFileEnvironment -PreviousValue $previousPgPassFile
        Remove-PostgresPgPassFile -Path $pgpassFile -ThrowOnFailure
    }
}
# Main per-game Postgres setup pass. All profiles are preflighted and all
# database existence checks must be verified before any profile write. Pass is
# written whenever it differs because TeknoParrotUI owns that plaintext
# compatibility field; the caller must supply a verified recovery backup.
function Invoke-PostgresGameSetup {
    param([string]$UserProfilesDir, [string]$SuperPasswordPlain, $RecoveryBackup = $null)
    $results = [ordered]@{ Configured = 0; DbCreated = 0; AlreadyConfigured = 0; Errors = 0; RecoveryBlocked = $false; BackupPath = $null }
    if (-not $RecoveryBackup) { $RecoveryBackup = New-PostgresRecoveryBackup -UserProfilesDir $UserProfilesDir }
    if ($RecoveryBackup) { $results.BackupPath = $RecoveryBackup.Path }
    if (-not $RecoveryBackup -or -not $RecoveryBackup.Verified) {
        $results.Errors++
        $results.RecoveryBlocked = $true
        Write-Log 'Postgres: profile setup blocked because recovery evidence was not verified.'
        return [pscustomobject]$results
    }
    $relBinPath = $script:PostgresBinDir.TrimEnd('\') + '\'
    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction Stop | Where-Object { $_.Directory.Name -ne 'FullBackup' } | Sort-Object Name)
    $plans = New-Object System.Collections.Generic.List[object]
    $dbState = @{}
    $preflightBlocked = $false
    foreach ($pf in $profiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile -or -not (Test-GameNeedsPostgres $doc)) { continue }
            $dbName = Get-PostgresFieldValue $doc 'DbName'
            if ([string]::IsNullOrWhiteSpace($dbName) -or -not (Test-SafePostgresDbName $dbName)) { throw 'The profile has no safe PostgreSQL database name.' }
            if ($null -eq (Get-PostgresFieldValue $doc 'Pass')) { throw 'The profile has no PostgreSQL Pass field.' }
            $changed = $false
            foreach ($field in @(@('Path', $relBinPath), @('Address', '127.0.0.1'), @('Port', '5432'), @('User', 'postgres'))) {
                if ([string]::IsNullOrWhiteSpace((Get-PostgresFieldValue $doc $field[0]))) {
                    if (-not (Set-PostgresFieldValue $doc $field[0] $field[1])) { throw "The profile has no PostgreSQL $($field[0]) field." }
                    $changed = $true
                }
            }
            if (-not [string]::Equals((Get-PostgresFieldValue $doc 'Pass'), $SuperPasswordPlain, [System.StringComparison]::Ordinal)) {
                if (-not (Set-PostgresFieldValue $doc 'Pass' $SuperPasswordPlain)) { throw 'The profile PostgreSQL Pass field could not be updated.' }
                $changed = $true
            }
            if ($dbState.ContainsKey($dbName)) { $state = $dbState[$dbName] }
            else {
                $state = Get-PostgresDatabaseState -DbName $dbName -SuperPasswordPlain $SuperPasswordPlain
                if (-not $state.Verified) { throw 'The database existence result was not verified.' }
                $dbState[$dbName] = $state
            }
            $autoCreate = (Get-PostgresFieldValue $doc 'Automatically create Database') -eq '1'
            $backupFile = $null; $encoding = $null
            if (-not $state.Exists -and -not $autoCreate) {
                $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
                $gamePath = if ($gamePathNode) { $gamePathNode.InnerText } else { '' }
                if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path -LiteralPath $gamePath -PathType Leaf)) { throw 'The profile needs database creation but its game executable is unavailable.' }
                $backupFile = Get-PostgresBackupFile -GameFolder ([System.IO.Path]::GetDirectoryName($gamePath))
                if (-not $backupFile) { throw 'The profile needs database creation but no bundled pg_backup file was found.' }
                $encoding = if ($dbName -eq 'GameDB06') { 'UTF8' } else { 'SQL_ASCII' }
            }
            [void]$plans.Add([pscustomobject]@{ Profile = $pf; Document = $doc; DbName = $dbName; DbExists = [bool]$state.Exists; AutoCreate = $autoCreate; BackupFile = $backupFile; Encoding = $encoding; Changed = $changed })
        } catch {
            $preflightBlocked = $true
            $results.Errors++
            Write-Log "Postgres: preflight blocked for $($pf.BaseName); no profile write was attempted."
        }
    }
    if ($preflightBlocked) {
        $results.RecoveryBlocked = $true
        Write-Log 'Postgres: profile setup aborted because preflight was not fully verified.'
        return [pscustomobject]$results
    }
    foreach ($plan in @($plans | Sort-Object { $_.Profile.Name })) {
        if ($plan.DbExists -or $plan.AutoCreate) { continue }
        if (-not (New-PostgresDatabaseFromBackup -DbName $plan.DbName -Encoding $plan.Encoding -BackupFile $plan.BackupFile -SuperPasswordPlain $SuperPasswordPlain)) {
            $results.Errors++
            $results.RecoveryBlocked = $true
            Write-Log "Postgres: database creation failed for $($plan.Profile.BaseName); no profile write was reported complete."
            return [pscustomobject]$results
        }
        $plan.DbExists = $true
        $dbState[$plan.DbName] = [pscustomobject]@{ Exists = $true; Verified = $true }
        $results.DbCreated++
    }
    try {
        foreach ($plan in @($plans | Sort-Object { $_.Profile.Name })) {
            if ($plan.Changed) {
                Save-Xml $plan.Document $plan.Profile.FullName
                $results.Configured++
            } else { $results.AlreadyConfigured++ }
        }
    } catch {
        $results.Errors++
        $results.RecoveryBlocked = $true
        Write-Log "Postgres: profile write failed; restoring from verified evidence at $($RecoveryBackup.Path)."
        try { Restore-PostgresProfileBackups -RecoveryBackup $RecoveryBackup | Out-Null; Write-Log 'Postgres: profile rollback completed.' }
        catch { Write-Log "Postgres: profile rollback failed; evidence remains at $($RecoveryBackup.Path)." }
    }
    return [pscustomobject]$results
}
# =============================================================================
# FFB ARCADE PLUGIN  (force feedback / rumble for arcade racers and shooters)
# =============================================================================
# Source: mightymikem/FFBArcadePlugin, an actively-maintained fork of
# Boomslangnz/FFBArcadePlugin. Deploys one compiled DLL (MAME32.dll x86 /
# MAME64.dll x64) into a game's folder, renamed to whatever DLL that
# specific game expects to load (d3d9.dll, d3d11.dll, opengl32.dll,
# xinput1_3.dll, or winmm.dll). The per-game destination filename is a
# fixed lookup tied to specific titles, not auto-detected from the exe --
# so unlike ReShade it cannot be guessed at runtime; it is fetched live
# from the upstream AutoSetup.cmd build script instead of hardcoded here,
# so this automatically tracks whatever the fork currently supports.

# Fetches and parses the upstream AutoSetup.cmd to build a folder-name ->
# destination-DLL-filename map. The file has a very regular shape:
#   cd <FolderName>
#   rename dinput8.dll <destination>.dll
#   cd..
# (folder names are quoted only when they contain special characters, e.g.
# `cd "Sega Race TV"` vs `cd Afterburner Climax` -- the regex handles both).
# Returns an empty hashtable (not a hardcoded fallback list) if the fetch
# fails after retries -- there is nothing meaningful to fall back to since
# the table only exists upstream.
function Get-FFBPluginGameMap {
    $map = @{}
    $uri = 'https://raw.githubusercontent.com/mightymikem/FFBArcadePlugin/master/AutoSetup.cmd'
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $resp = Invoke-WebRequest -Uri $uri -UseBasicParsing -TimeoutSec 20 `
                        -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $ms = [regex]::Matches($resp.Content, '(?m)^cd\s+"?([^"\r\n]+?)"?\s*\r?\nrename\s+dinput8\.dll\s+(\S+)\s*\r?\ncd\.\.')
            foreach ($m in $ms) {
                $folderName = $m.Groups[1].Value.Trim()
                $destDll    = $m.Groups[2].Value.Trim()
                if ($folderName -and $destDll) { $map[$folderName] = $destDll }
            }
            if ($map.Count -gt 0) {
                Write-Log "FFBPlugin: $($map.Count) game(s) in the live AutoSetup.cmd table."
            } else {
                Write-Log "FFBPlugin: 0 entries parsed from AutoSetup.cmd -- format may have changed."
            }
            return $map
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "FFBPlugin: AutoSetup.cmd fetch failed -- $_"
                return $map
            }
            Write-Log "FFBPlugin: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $map
}

# Downloads MAME32.dll / MAME64.dll directly from the repo root (plain
# files, not inside the release ZIP -- no extraction step needed).
# Returns $true if at least one architecture's DLL was downloaded.
function Invoke-FFBPluginDownload {
    param([string]$destDir)
    [void][System.IO.Directory]::CreateDirectory($destDir)
    $got = $false
    foreach ($dllName in @('MAME32.dll', 'MAME64.dll')) {
        $uri      = "https://raw.githubusercontent.com/mightymikem/FFBArcadePlugin/master/$dllName"
        $destPath = Join-Path $destDir $dllName
        if (Invoke-TpmDownload -DownloadUrl $uri -DestinationPath $destPath -Label 'FFBPlugin') {
            $got = $true
            Write-Log "FFBPlugin: downloaded $dllName"
        } else {
            Write-Log "FFBPlugin: $dllName download failed."
        }
    }
    return $got
}

# Deploys FFB plugin DLLs to registered games matched against the live
# AutoSetup.cmd table by fuzzy folder-name similarity. Never overwrites an
# existing file at the destination filename (ReShade or anything else
# already occupying that hook point) -- skips and reports instead.
function Get-FFBPluginOwnershipPath {
    param([Parameter(Mandatory)][string]$CacheDir)
    return (Join-Path $CacheDir 'TPM-FFB-Plugin-Ownership.json')
}

function Read-FFBPluginOwnership {
    param([Parameter(Mandatory)][string]$CacheDir)
    $path = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return @() }
    try {
        $data = Get-Content -LiteralPath $path -Raw -ErrorAction Stop | ConvertFrom-Json
        return @($data.Entries)
    } catch {
        Write-Log 'FFBPlugin ownership manifest could not be read; no automatic removal was attempted.'
        return @()
    }
}

function Write-FFBPluginOwnership {
    param([Parameter(Mandatory)][string]$CacheDir, [Parameter(Mandatory)][object]$Entries)
    [void][System.IO.Directory]::CreateDirectory($CacheDir)
    $path = Get-FFBPluginOwnershipPath -CacheDir $CacheDir
    $temp = $path + '.tmp'
    $payload = [ordered]@{ SchemaVersion = 1; Entries = @($Entries) }
    [System.IO.File]::WriteAllText($temp, ($payload | ConvertTo-Json -Depth 5), (New-Object System.Text.UTF8Encoding $false))
    Move-Item -LiteralPath $temp -Destination $path -Force -ErrorAction Stop
}

function Remove-FFBPluginOwnedDeployment {
    param([Parameter(Mandatory)][string]$CacheDir, [Parameter(Mandatory)][string]$ProfileCode)
    $entries = @(Read-FFBPluginOwnership -CacheDir $CacheDir)
    $remaining = New-Object System.Collections.Generic.List[object]
    $removedItems = New-Object System.Collections.ArrayList
    $removed = $false
    foreach ($entry in $entries) {
        if ([string]$entry.ProfileCode -ne $ProfileCode) { [void]$remaining.Add($entry); continue }
        $destination = [string]$entry.Destination
        if (-not (Test-Path -LiteralPath $destination -PathType Leaf) -or
            [string]::IsNullOrWhiteSpace([string]$entry.GameRoot) -or
            -not (Test-PathInside -child $destination -parent ([string]$entry.GameRoot))) {
            [void]$remaining.Add($entry); continue
        }
        $currentHash = (Get-FileHash -LiteralPath $destination -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($currentHash -ine [string]$entry.DeployedSha256) {
            Write-Host ("    Kept {0}: the hook file changed after TPM installed it." -f $destination) -ForegroundColor Yellow
            Write-Log "FFBPlugin ownership: refused removal of changed file $destination"
            [void]$remaining.Add($entry); continue
        }
        $backupDir = Join-Path (Join-Path ([string]$entry.GameRoot) 'FullBackup') ('FFBPluginCleanup_' + (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss'))
        [void][System.IO.Directory]::CreateDirectory($backupDir)
        $backupPath = Join-Path $backupDir ([System.IO.Path]::GetFileName($destination))
        Copy-Item -LiteralPath $destination -Destination $backupPath -Force -ErrorAction Stop
        Remove-Item -LiteralPath $destination -Force -ErrorAction Stop
        [void]$removedItems.Add([pscustomobject]@{ Destination = $destination; Backup = $backupPath; Hash = $entry.DeployedSha256 })
        $removed = $true
    }
    if ($removed) {
        try {
            Write-FFBPluginOwnership -CacheDir $CacheDir -Entries $remaining.ToArray()
        } catch {
            $rollbackErrors = New-Object System.Collections.Generic.List[string]
            foreach ($item in @($removedItems)) {
                try {
                    if (-not (Test-Path -LiteralPath $item.Destination -PathType Leaf)) {
                        Copy-Item -LiteralPath $item.Backup -Destination $item.Destination -Force -ErrorAction Stop
                    }
                    if ((Get-FileHash -LiteralPath $item.Destination -Algorithm SHA256 -ErrorAction Stop).Hash -ine [string]$item.Hash) { throw 'restored hash mismatch' }
                } catch { [void]$rollbackErrors.Add($item.Destination) }
            }
            if ($rollbackErrors.Count -gt 0) {
                Write-Log ("FFBPlugin ownership: manifest write and deletion rollback failed; evidence remains in backup(s): {0}" -f ($rollbackErrors -join ', '))
                throw 'FFBPlugin ownership manifest update failed and deletion rollback was incomplete.'
            }
            Write-Log 'FFBPlugin ownership: manifest write failed; deletion was rolled back from verified backup.'
            throw 'FFBPlugin ownership manifest update failed; deletion was rolled back.'
        }
    }
    return $removed
}

function Invoke-FFBPluginSetup {
    param([string]$UserProfilesDir, [string]$CacheDir, [string[]]$NativeEnabledCodes = @())

    # A caller passing an explicit $null overrides the default above (PowerShell
    # does not apply a parameter default when $null is passed deliberately) --
    # guard here too, since HashSet's constructor throws on a null collection.
    if ($null -eq $NativeEnabledCodes) { $NativeEnabledCodes = @() }
    $nativeEnabledSet = [System.Collections.Generic.HashSet[string]]::new(
        [string[]]$NativeEnabledCodes, [System.StringComparer]::OrdinalIgnoreCase)
    $ownershipEntries = @(Read-FFBPluginOwnership -CacheDir $CacheDir)

    Write-Host ""
    Write-Host "  Fetching the current supported-games list..." -ForegroundColor DarkGray
    $gameMap = Get-FFBPluginGameMap
    if ($gameMap.Count -eq 0) {
        Write-Host "  Could not reach GitHub to fetch the FFB plugin game list -- try again later." -ForegroundColor Red
        Write-Log "FFBPlugin setup: aborted -- game map fetch failed."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 1; Reason = 'GAME_MAP_FAILED' }
    }
    Write-Host ("  {0} game(s) in the upstream table." -f $gameMap.Count) -ForegroundColor DarkGray

    Write-Host "  Downloading the FFB plugin DLLs..." -ForegroundColor DarkGray
    if (-not (Invoke-FFBPluginDownload -destDir $CacheDir)) {
        Write-Host "  Could not download the FFB plugin DLLs -- try again later." -ForegroundColor Red
        Write-Log "FFBPlugin setup: aborted -- DLL download failed."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 1; Reason = 'DLL_DOWNLOAD_FAILED' }
    }
    $srcDll32 = Join-Path $CacheDir "MAME32.dll"
    $srcDll64 = Join-Path $CacheDir "MAME64.dll"

    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                  Where-Object { $_.Directory.Name -ne "FullBackup" })
    if ($profiles.Count -eq 0) {
        Write-Host "  No registered games found." -ForegroundColor Yellow
        Write-Log "FFBPlugin setup: aborted -- no registered profiles."
        return [pscustomobject]@{ Succeeded = $false; Deployed = 0; Errors = 0; Reason = 'NO_REGISTERED_PROFILES' }
    }

    # Pre-normalise the FFB table once for fuzzy matching.
    $normFfbList = @(foreach ($name in $gameMap.Keys) {
        [pscustomobject]@{ Name = $name; Norm = (Get-NormalizedGameKey $name); Dest = $gameMap[$name] }
    })

    Write-Host ""
    Write-Host ("  Matching {0} registered game(s) against the FFB table..." -f $profiles.Count) -ForegroundColor Cyan

    # First pass: resolve a candidate match for every profile (regardless of
    # native status) so overlaps -- games covered by BOTH mechanisms -- can be
    # surfaced and decided on once, rather than silently defaulting to native.
    $candidates = @()
    $matchErrors = 0
    foreach ($pf in $profiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { continue }
            $gamePath = $gpNode.InnerText.Trim()
            if (-not (Test-Path -LiteralPath $gamePath)) { continue }
            $exeDir     = [System.IO.Path]::GetDirectoryName($gamePath)
            $folderName = Split-Path -Path $exeDir -Leaf
            $normFolder = Get-NormalizedGameKey $folderName

            $best = $null; $bestScore = 0.0
            foreach ($cand in $normFfbList) {
                $score = Get-DiceSimilarity $normFolder $cand.Norm
                if ($score -gt $bestScore) { $bestScore = $score; $best = $cand }
            }
            if ($null -eq $best -or $bestScore -lt $FuzzyAutoThreshold) { continue }

            $candidates += [pscustomobject]@{
                Profile = $pf; GamePath = $gamePath; ExeDir = $exeDir
                Match = $best; Score = $bestScore
            }
        } catch {
            Write-Host ("    ERROR {0} -- {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "FFBPlugin: error reading $($pf.BaseName) -- $_"
            $matchErrors++
        }
    }

    # Overlaps: profiles with a confident third-party match that are ALSO
    # already covered by native FFB Blaster. Ask once, covering all of them,
    # instead of silently preferring native or prompting per game.
    $overlaps = @($candidates | Where-Object { $nativeEnabledSet.Contains($_.Profile.BaseName) })
    $useNativeForOverlaps = $true
    if ($overlaps.Count -gt 0) {
        Write-Host ""
        Write-Host ("  {0} game(s) are covered by BOTH FFB Blaster and the third-party plugin:" -f $overlaps.Count) -ForegroundColor Cyan
        foreach ($ov in $overlaps) { Write-Host ("    - {0}" -f $ov.Profile.BaseName) -ForegroundColor DarkGray }
        $ans = (Read-HostSafe "  Use FFB Blaster (native) for these games instead of the third-party plugin? (Y/N)").ToUpper()
        $useNativeForOverlaps = ($ans -eq "Y")
        Write-Log ("FFBPlugin: {0} overlapping game(s) with native FFB Blaster -- user chose {1}" -f $overlaps.Count, $(if ($useNativeForOverlaps) {"native"} else {"third-party plugin"}))
    }

    # Two distinct reasons get tracked separately, not combined into one
    # "no match" bucket: $skippedNoMatch is a game the live AutoSetup.cmd
    # table doesn't know about at all (nothing this script can do); a game
    # the table DOES match but whose 32-bit/64-bit MAME DLL isn't present
    # locally is a different, user-fixable situation (go get that DLL) and
    # gets its own $skippedDllMissing counter instead -- conflating the two
    # under one label would make "no match" misleadingly look like every
    # one of those games is simply unsupported.
    $deployed = 0; $skippedNative = 0; $skippedCollision = 0
    $skippedNoMatch = 0; $skippedDllMissing = 0; $errors = $matchErrors
    $noMatchCount = $profiles.Count - $candidates.Count - $matchErrors
    $skippedNoMatch += $noMatchCount

    foreach ($c in $candidates) {
        $pf = $c.Profile
        try {
            if ($nativeEnabledSet.Contains($pf.BaseName) -and $useNativeForOverlaps) {
                [void](Remove-FFBPluginOwnedDeployment -CacheDir $CacheDir -ProfileCode $pf.BaseName)
                $skippedNative++
                continue
            }

            $exeDir   = $c.ExeDir
            $destDll  = $c.Match.Dest
            $destPath = Join-Path $exeDir $destDll
            # Security: $destDll comes from the live AutoSetup.cmd fetched from
            # GitHub (untrusted input) -- verify the resolved path still lands
            # inside the game's own folder before writing anything. A crafted
            # rename line (e.g. "..\..\evil.dll") would otherwise escape the
            # intended destination folder.
            if (-not (Test-PathInside $destPath $exeDir)) {
                Write-Host ("    SKIP  {0}: destination filename '{1}' is unsafe -- not deploying." -f $pf.BaseName, $destDll) -ForegroundColor Red
                Write-Log "FFBPlugin: SECURITY -- skipped $($pf.BaseName), destDll '$destDll' resolves outside $exeDir"
                $errors++
                continue
            }
            if (Test-Path -LiteralPath $destPath) {
                Write-Host ("    SKIP  {0}: {1} already exists (ReShade or another hook) -- not overwritten." -f $pf.BaseName, $destDll) -ForegroundColor Yellow
                Write-Log "FFBPlugin: skipped $($pf.BaseName) -- $destDll already occupied at $destPath"
                $skippedCollision++
                continue
            }

            $arch   = Get-ExeArchitecture -ExePath $c.GamePath
            $srcDll = if ($arch -eq 'x86') { $srcDll32 } else { $srcDll64 }
            if (-not (Test-Path -LiteralPath $srcDll)) {
                Write-Host ("    SKIP  {0}: {1}-bit DLL not available." -f $pf.BaseName, $(if ($arch -eq 'x86') {'32'} else {'64'})) -ForegroundColor Yellow
                $skippedDllMissing++; continue
            }

            Copy-Item -LiteralPath $srcDll -Destination $destPath -ErrorAction Stop
            $sourceHash = (Get-FileHash -LiteralPath $srcDll -Algorithm SHA256 -ErrorAction Stop).Hash
            $deployedHash = (Get-FileHash -LiteralPath $destPath -Algorithm SHA256 -ErrorAction Stop).Hash
            $ownershipEntries = @($ownershipEntries | Where-Object { $_.Destination -ine $destPath })
            $ownershipEntries += [pscustomobject]@{
                ProfileCode = $pf.BaseName
                GameRoot = $exeDir
                Destination = $destPath
                SourceSha256 = $sourceHash
                DeployedSha256 = $deployedHash
                CreatedUtc = (Get-Date).ToUniversalTime().ToString('o')
            }
            Write-FFBPluginOwnership -CacheDir $CacheDir -Entries $ownershipEntries
            Write-Host ("    OK    {0}  [{1}]  (matched '{2}', {3})" -f $pf.BaseName, $destDll, $c.Match.Name, [Math]::Round($c.Score,2)) -ForegroundColor Green
            Write-Log "FFBPlugin: deployed $destDll to $exeDir (matched '$($c.Match.Name)', score $([Math]::Round($c.Score,2)))"
            $deployed++
        } catch {
            Write-Host ("    ERROR {0} -- {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "FFBPlugin: error on $($pf.BaseName) -- $_"
            $errors++
        }
    }

    Write-Host ""
    Write-Host ("  Deployed           : {0} game(s)" -f $deployed) -ForegroundColor Green
    if ($skippedNative -gt 0) {
        Write-Host ("  Skipped (native)   : {0}  (FFB Blaster already covers these -- preferred over the plugin)" -f $skippedNative) -ForegroundColor DarkGray
    }
    if ($skippedCollision -gt 0) {
        Write-Host ("  Skipped (collision): {0}  (a hook DLL already exists -- not overwritten)" -f $skippedCollision) -ForegroundColor Yellow
    }
    if ($skippedNoMatch -gt 0) {
        Write-Host ("  Skipped (no match) : {0}  (not in the plugin's supported-games list)" -f $skippedNoMatch) -ForegroundColor DarkGray
    }
    if ($skippedDllMissing -gt 0) {
        Write-Host ("  Skipped (no DLL)   : {0}  (matched, but the 32-bit or 64-bit plugin DLL isn't downloaded)" -f $skippedDllMissing) -ForegroundColor Yellow
    }
    if ($errors -gt 0) {
        Write-Host ("  Errors             : {0}  -- see TeknoParrot-Manager.log for details" -f $errors) -ForegroundColor Red
    }
    Write-Host ""
    Write-Host "  TPM records its own deployed hook files so a later native choice can remove only verified ownership." -ForegroundColor DarkCyan
    Write-Host "  TPM does not remove an unowned FFB hook automatically." -ForegroundColor DarkCyan
    Write-Log ("FFBPlugin setup: deployed={0} skippedNative={1} skippedCollision={2} skippedNoMatch={3} skippedDllMissing={4} errors={5}" -f $deployed, $skippedNative, $skippedCollision, $skippedNoMatch, $skippedDllMissing, $errors)
    return [pscustomobject]@{ Succeeded = ($errors -eq 0); Deployed = $deployed; Errors = $errors; Reason = if ($errors) { 'DEPLOYMENT_ERRORS' } else { $null } }
}

# GameProfiles at runtime -- never hardcoded. Shared (read-only) between
# Invoke-FFBBlasterSetup and the Library health check's coverage report.
function Get-FFBBlasterFieldNames {
    param([string]$GameProfilesDir)

    $ffbFields = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if (Test-Path -LiteralPath $GameProfilesDir) {
        $gpFiles = @(Get-ChildItem -LiteralPath $GameProfilesDir -Filter "*.xml" -ErrorAction SilentlyContinue)
        foreach ($gf in $gpFiles) {
            try {
                $gdoc = Read-Xml $gf.FullName
                $fnodes = $gdoc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
                foreach ($n in $fnodes) {
                    $cn = if ($n.CategoryName) { $n.CategoryName.Trim() } else { '' }
                    $fn = if ($n.FieldName)     { $n.FieldName.Trim()     } else { '' }
                    $ft = if ($n.FieldType)     { $n.FieldType.Trim()     } else { '' }
                    if ($ft -ne 'Bool') { continue }
                    if ($cn -imatch 'ffb.*blaster|blaster.*ffb') {
                        [void]$ffbFields.Add($cn)
                    } elseif ($fn -and $fn -imatch 'ffb.*blaster|blaster.*ffb') {
                        # Older TP builds that put the identifying text on
                        # FieldName instead of CategoryName -- fall back to
                        # treating the field name itself as the category key.
                        [void]$ffbFields.Add($fn)
                    }
                }
            } catch {
                Write-Log ("FFBBlaster: WARNING -- could not parse GameProfile '$($gf.BaseName)': $_")
            }
        }
    }
    return $ffbFields
}

# Pure decision function: for a given UserProfile XML and the category
# keys discovered by Get-FFBBlasterFieldNames (a CategoryName on newer TP
# builds, or a literal FieldName on older ones -- see that function's
# fallback), determines whether the profile has an FFB Blaster field at
# all (Eligible) and whether it is already set to '1' (UpToDate). Returns
# the exact node + target value for any field that needs changing,
# mirroring Test-GpuFixUpToDate.
function Test-FFBBlasterUpToDate {
    param([System.Xml.XmlDocument]$Doc, $Categories)

    $eligible = $false
    $changes  = New-Object System.Collections.Generic.List[object]

    foreach ($key in $Categories) {
        $xpLit = ConvertTo-XPathStringLiteral $key
        $fis = @($Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[CategoryName=$xpLit]"))
        if ($fis.Count -eq 0) {
            # Fallback for older-build profiles where $key is a literal FieldName.
            $fis = @($Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation[FieldName=$xpLit]"))
        }
        foreach ($fi in $fis) {
            $ft = if ($fi.FieldType) { $fi.FieldType.Trim() } else { '' }
            if ($ft -ne 'Bool') { continue }
            $fvNode = $fi.SelectSingleNode("FieldValue")
            if ($null -eq $fvNode) { continue }
            $eligible = $true
            $fieldName = if ($fi.FieldName) { $fi.FieldName.Trim() } else { '' }
            if ($fvNode.InnerText -ne '1') {
                [void]$changes.Add([pscustomobject]@{ FieldName = $fieldName; Node = $fvNode; OldValue = $fvNode.InnerText; NewValue = '1' })
            }
        }
    }

    return [pscustomobject]@{ Eligible = $eligible; UpToDate = ($eligible -and $changes.Count -eq 0); Changes = $changes }
}

# Platforms/emulation paths on which TeknoParrot's native FFB Blaster is
# NOT currently supported, keyed by the GameProfile's own EmulationProfile
# (or EmulatorType) value -- compared case-insensitively. This is an
# explicit deny-list, not an allow-list: the script does NOT maintain a
# positive roster of every supported platform (that would go stale on every
# upstream addition and wrongly mark brand-new platforms as unsupported).
# Instead, only platforms POSITIVELY known not to support FFB Blaster are
# listed here, so a write is blocked for them even if a profile somehow
# carries an FFB-Blaster-shaped field. 'pcsx2x6' is the confirmed case
# (issue #41): TeknoParrot's PCSX2 fork does not implement FFB Blaster, and
# its profiles legitimately have no such field today -- but a future
# upstream change must never cause this script to enable it there. Add a
# platform here only after positively confirming FFB Blaster does not work
# on it; never the reverse.
$script:FFBBlasterUnsupportedPlatforms = @('pcsx2x6')

# Regex identifying any FieldInformation node (by CategoryName or FieldName)
# that LOOKS like an FFB Blaster control, regardless of whether it is a
# well-formed Bool field. Used to distinguish "this game genuinely has no
# FFB Blaster control" (Unsupported) from "something FFB-Blaster-shaped is
# here but does not match the schema we know how to write" (Unknown).
$script:FFBBlasterNamePattern = 'ffb.*blaster|blaster.*ffb'

# Pure capability/safety gate for native FFB Blaster on a single profile.
# Supersedes a bare Test-FFBBlasterUpToDate call at every decision point
# (Invoke-FFBBlasterSetup and the Library health check) so the platform
# deny-list and the unknown-field safety state are enforced in exactly one
# place. Returns a structured outcome -- this is the canonical shape the
# whole FFB Blaster feature reasons about (issue #41):
#   Status     : 'Supported' | 'Unsupported' | 'Unknown'
#   Reason     : human-readable explanation (for logs + the user summary)
#   WouldWrite : $true ONLY when Status='Supported' AND a field actually
#                needs changing -- the single signal a caller may write on.
#   Eligible   : a well-formed Bool FFB Blaster field is present
#   UpToDate   : that field is already enabled
#   Changes    : the exact node(s)+value(s) to write (from
#                Test-FFBBlasterUpToDate), empty unless Status='Supported'
#   Platform   : the EmulationProfile/EmulatorType value examined
# Decision order (deny-list first, so an unsupported platform can never be
# written even if it carries a matching field):
#   1. Platform in $FFBBlasterUnsupportedPlatforms        -> Unsupported
#   2. Well-formed Bool FFB Blaster field present         -> Supported
#   3. FFB-Blaster-shaped field present but malformed     -> Unknown
#      (drift: wrong FieldType, no FieldValue, etc.)
#   4. No FFB-Blaster-shaped field at all                 -> Unsupported
# Only case 2 ever permits a write; cases 1/3/4 always set WouldWrite=$false.
function Get-FFBBlasterSupport {
    param([System.Xml.XmlDocument]$Doc, $Categories)

    # Platform identity: prefer EmulationProfile, fall back to EmulatorType
    # (both carry 'pcsx2x6' on a real PCSX2 fork profile -- confirmed against
    # live teknogods/TeknoParrotUI GameProfiles).
    $platform = ''
    if ($Doc.GameProfile) {
        $epNode = $Doc.GameProfile.SelectSingleNode("EmulationProfile")
        if ($epNode -and $epNode.InnerText) { $platform = $epNode.InnerText.Trim() }
        if ([string]::IsNullOrWhiteSpace($platform)) {
            $etNode = $Doc.GameProfile.SelectSingleNode("EmulatorType")
            if ($etNode -and $etNode.InnerText) { $platform = $etNode.InnerText.Trim() }
        }
    }

    $emptyChanges = New-Object System.Collections.Generic.List[object]

    # 1. Deny-list gate -- always first, never overridden by field presence.
    foreach ($bad in $script:FFBBlasterUnsupportedPlatforms) {
        if ($platform -and ($platform -ieq $bad)) {
            return [pscustomobject]@{
                Status     = 'Unsupported'
                Reason     = "FFB Blaster is not supported on the '$platform' platform"
                WouldWrite = $false
                Eligible   = $false
                UpToDate   = $false
                Changes    = $emptyChanges
                Platform   = $platform
            }
        }
    }

    # 2. Well-formed Bool field present?
    $result = Test-FFBBlasterUpToDate -Doc $Doc -Categories $Categories
    if ($result.Eligible) {
        $would = ($result.Changes.Count -gt 0)
        $reason = if ($would) { "FFB Blaster field present and not yet enabled" }
                  else        { "FFB Blaster field present and already enabled" }
        return [pscustomobject]@{
            Status     = 'Supported'
            Reason     = $reason
            WouldWrite = $would
            Eligible   = $true
            UpToDate   = $result.UpToDate
            Changes    = $result.Changes
            Platform   = $platform
        }
    }

    # 3. Anything FFB-Blaster-shaped present that we could NOT treat as a
    #    writable Bool field? That is schema drift -- never write, flag for
    #    manual review.
    $shaped = $false
    if ($Doc.GameProfile) {
        $fnodes = $Doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
        foreach ($n in $fnodes) {
            $cn = if ($n.CategoryName) { $n.CategoryName.Trim() } else { '' }
            $fn = if ($n.FieldName)     { $n.FieldName.Trim()     } else { '' }
            if (($cn -and $cn -imatch $script:FFBBlasterNamePattern) -or
                ($fn -and $fn -imatch $script:FFBBlasterNamePattern)) {
                $shaped = $true; break
            }
        }
    }
    if ($shaped) {
        return [pscustomobject]@{
            Status     = 'Unknown'
            Reason     = "An FFB Blaster-like field was found but does not match the known Bool schema -- skipped for manual review"
            WouldWrite = $false
            Eligible   = $false
            UpToDate   = $false
            Changes    = $emptyChanges
            Platform   = $platform
        }
    }

    # 4. No FFB Blaster control of any shape -- this game simply does not
    #    have the feature.
    return [pscustomobject]@{
        Status     = 'Unsupported'
        Reason     = "This game has no FFB Blaster field"
        WouldWrite = $false
        Eligible   = $false
        UpToDate   = $false
        Changes    = $emptyChanges
        Platform   = $platform
    }
}

# Sets up TeknoParrot's own built-in "FFB Blaster" force feedback, a
# per-game Bool field in GameProfiles -- paywalled (any paid TeknoParrot
# membership). The script cannot check subscription status, so it must
# ask before touching anything: enabling the field has no effect at all
# without a membership, so there is no point doing it on spec.
# Returns the list of profile codes successfully enabled or already
# enabled, so the third-party plugin setup can ask the user whether to
# keep native or switch to the plugin for any game covered by both.
function Invoke-FFBBlasterSetup {
    param([string]$UserProfilesDir, [string]$TpRoot)

    Write-Host ""
    Write-Host "  FFB Blaster is TeknoParrot's own built-in force feedback." -ForegroundColor Cyan
    Write-Host "  It is included with any paid TeknoParrot membership" -ForegroundColor Cyan
    Write-Host "  (teknoparrot.com/en/Home/Subscription)." -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  Do you have an active, paid TeknoParrot membership? (Y/N)" -ForegroundColor Yellow
    Write-Host "  If you answer N, FFB Blaster will NOT be set up -- it does not work" -ForegroundColor Yellow
    Write-Host "  without one, and there is no point enabling a field that has no effect." -ForegroundColor Yellow
    $hasSub = (Read-HostSafe "  Answer").ToUpper()
    if ($hasSub -ne "Y") {
        Write-Host "  Skipped -- no membership." -ForegroundColor DarkGray
        Write-Log "FFBBlaster setup: skipped -- user has no TeknoParrot membership."
        return ,@()   # comma forces real array semantics, not $null -- see
                      # Invoke-FFBPluginSetup's -NativeEnabledCodes param
    }

    # Discover the field name dynamically -- never hardcoded, same pattern
    # as Invoke-GpuFixSetup's $boolAmdFields discovery.
    Write-Host "  Scanning GameProfiles for FFB Blaster fields..." -ForegroundColor DarkGray
    $gpDir     = Join-Path $TpRoot "GameProfiles"
    $ffbFields = Get-FFBBlasterFieldNames -GameProfilesDir $gpDir
    if ($ffbFields.Count -eq 0) {
        # Before giving up, check whether there ARE any FFB-Blaster-shaped
        # fields in the GameProfiles at all, just not of type Bool. If so,
        # this is a schema drift situation (upstream changed the FieldType),
        # not simply "TeknoParrot does not support FFB Blaster here yet" --
        # and the two cases deserve different user-facing messages.
        $shapedNonBoolCount = 0
        if (Test-Path -LiteralPath $gpDir) {
            foreach ($gf in @(Get-ChildItem -LiteralPath $gpDir -Filter "*.xml" -ErrorAction SilentlyContinue)) {
                try {
                    $gdoc = Read-Xml $gf.FullName
                    $fnodes = $gdoc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")
                    foreach ($n in $fnodes) {
                        $cn = if ($n.CategoryName) { $n.CategoryName.Trim() } else { '' }
                        $fn = if ($n.FieldName)     { $n.FieldName.Trim()     } else { '' }
                        $ft = if ($n.FieldType)     { $n.FieldType.Trim()     } else { '' }
                        if ($ft -ieq 'Bool') { continue }   # Already caught by Get-FFBBlasterFieldNames
                        if (($cn -and $cn -imatch $script:FFBBlasterNamePattern) -or
                            ($fn -and $fn -imatch $script:FFBBlasterNamePattern)) {
                            $shapedNonBoolCount++
                        }
                    }
                } catch { }
            }
        }
        if ($shapedNonBoolCount -gt 0) {
            Write-Host "  WARNING: FFB Blaster-shaped fields were found in GameProfiles, but" -ForegroundColor Yellow
            Write-Host "  none have the expected Bool type -- this may indicate an upstream" -ForegroundColor Yellow
            Write-Host ("  schema change ({0} field(s) affected). Skipped for manual review." -f $shapedNonBoolCount) -ForegroundColor Yellow
            Write-Host "  Run Get-GameProfileSchemaDrift against a sample profile to confirm." -ForegroundColor DarkGray
            Write-Log ("FFBBlaster setup: aborted -- {0} FFB-Blaster-shaped non-Bool field(s) detected (schema drift)." -f $shapedNonBoolCount)
        } else {
            Write-Host "  No FFB Blaster field found in any GameProfile -- this TeknoParrot" -ForegroundColor Yellow
            Write-Host "  install may not support it yet." -ForegroundColor Yellow
            Write-Log "FFBBlaster setup: aborted -- no FFB Blaster field discovered."
        }
        return ,@()
    }
    Write-Log ("FFBBlaster: discovered fields -- [{0}]" -f ($ffbFields -join ', '))

    # Backup before writing -- this touches every matching UserProfile.
    $backupRoot = Join-Path $UserProfilesDir "FullBackup"
    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss")
    $backupPath = Join-Path $backupRoot ("FFBBlaster_" + $timestamp)
    try {
        [void][System.IO.Directory]::CreateDirectory($backupRoot)
        [void][System.IO.Directory]::CreateDirectory($backupPath)
    } catch {
        Write-Host "  ERROR: Could not create backup folder: $_" -ForegroundColor Red
        Write-Log "FFBBlaster: backup failed -- $_"
        return ,@()
    }
    $backupCopyErrs = $null
    Get-ChildItem -LiteralPath $UserProfilesDir | Where-Object { $_.Name -ne "FullBackup" } |
        Copy-Item -Destination $backupPath -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable backupCopyErrs
    if ($backupCopyErrs.Count -gt 0) {
        Write-Host ("  WARNING: {0} file(s) could not be backed up." -f $backupCopyErrs.Count) -ForegroundColor Yellow
    }
    Write-Host ("  Backup: {0}" -f $backupPath) -ForegroundColor DarkGray
    Write-Log "FFBBlaster: backup at $backupPath"

    Write-Host ""
    Write-Host "  Enabling FFB Blaster on registered profiles..." -ForegroundColor DarkGray
    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                  Where-Object { $_.Directory.Name -ne "FullBackup" })
    $enabledCodes = New-Object System.Collections.Generic.List[string]
    $updated = 0; $unchanged = 0; $unsupported = 0; $unknown = 0; $errors = 0
    $unknownNames = New-Object System.Collections.Generic.List[string]
    $skippedPlatforms = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    foreach ($pf in $profiles) {
        try {
            $doc    = Read-Xml $pf.FullName
            # Single structured capability+safety gate (issue #41). Only a
            # 'Supported' outcome with WouldWrite/Changes ever causes a write;
            # 'Unsupported' (no field, or an unsupported platform such as
            # pcsx2x6) and 'Unknown' (drifted/unrecognized field shape) are
            # both skipped without touching the profile.
            $support = Get-FFBBlasterSupport -Doc $doc -Categories $ffbFields
            switch ($support.Status) {
                'Unsupported' {
                    $unsupported++
                    if ($support.Platform -and ($script:FFBBlasterUnsupportedPlatforms -icontains $support.Platform)) {
                        [void]$skippedPlatforms.Add($support.Platform)
                    }
                    Write-Log "FFBBlaster: $($pf.BaseName) :: unsupported -- $($support.Reason)"
                    continue
                }
                'Unknown' {
                    $unknown++
                    [void]$unknownNames.Add($pf.BaseName)
                    Write-Log "FFBBlaster: $($pf.BaseName) :: unknown -- $($support.Reason) (NOT written)"
                    continue
                }
            }
            # Supported from here on.
            [void]$enabledCodes.Add($pf.BaseName)
            if ($support.WouldWrite) {
                foreach ($c in $support.Changes) {
                    $c.Node.InnerText = $c.NewValue
                    Write-Log "FFBBlaster: $($pf.BaseName) :: $($c.FieldName) -> $($c.NewValue)"
                }
                Save-Xml $doc $pf.FullName
                $updated++
                Write-Host ("    {0}" -f $pf.BaseName) -ForegroundColor Green
            } else {
                $unchanged++
            }
        } catch {
            Write-Host ("    FAILED {0}: {1}" -f $pf.BaseName, $_) -ForegroundColor Red
            Write-Log "FFBBlaster: FAILED $($pf.BaseName) -- $_"
            $errors++
        }
    }

    $supportedTotal = $updated + $unchanged
    Write-Host ""
    Write-Host "  FFB Blaster support check:" -ForegroundColor Cyan
    Write-Host ("    Supported profiles  : {0}" -f $supportedTotal) -ForegroundColor Green
    Write-Host ("    Unsupported profiles: {0}" -f $unsupported) -ForegroundColor DarkGray
    Write-Host ("    Unknown profiles    : {0}" -f $unknown) -ForegroundColor $(if ($unknown -gt 0) {'Yellow'} else {'DarkGray'})
    Write-Host ""
    Write-Host ("  Updated  : {0} profile(s)" -f $updated) -ForegroundColor Green
    if ($unchanged -gt 0) { Write-Host ("  No change: {0} (already enabled)" -f $unchanged) -ForegroundColor DarkGray }
    foreach ($plat in $skippedPlatforms) {
        Write-Host ("  Skipped {0} profiles because FFB Blaster is not currently supported there." -f $plat) -ForegroundColor DarkGray
    }
    if ($unknown -gt 0) {
        Write-Host ("  Unknown  : {0} profile(s) had an unrecognized FFB Blaster field and were NOT changed -- review manually:" -f $unknown) -ForegroundColor Yellow
        Write-Host ("    {0}" -f ($unknownNames -join ', ')) -ForegroundColor DarkGray
    }
    if ($errors -gt 0)    { Write-Host ("  Errors   : {0} -- see log for details" -f $errors) -ForegroundColor Red }
    Write-Log ("FFBBlaster setup: complete. Supported={0} Updated={1} Unchanged={2} Unsupported={3} Unknown={4} Errors={5}" -f $supportedTotal, $updated, $unchanged, $unsupported, $unknown, $errors)
    return @($enabledCodes)
}

# =============================================================================
# BEPINEX UPDATE CHECKER  (Unity modding/plugin framework some games need)
# =============================================================================
# BepInEx is a third-party Unity plugin/modding framework. Several
# TeknoParrot games require a community BepInEx plugin to get controls or
# fixes working (the live-fetched example list is shown in the menu --
# see Get-BepInExRequiredGames below). Mode 9 offers a user-approved install,
# update, or reset using stable x64 or x86 packages; it never applies the
# framework silently to every game.

# Fetches the live list of games known to require BepInEx, for display
# only (menu text, not used to gate actual logic -- the setup flow can offer
# install/update/reset for selected games after safety checks).
# Source: eggmansworld.github.io/TeknoParrot, the structured replacement
# for the old plain-text gamenotes doc, already used for the v0.88-v0.90
# compatibility tables. That site has no clean "requires BepInEx" tag, so
# this matches a tight phrase pattern against the free-text notes field
# instead -- verified against the live data to reproduce the same games
# this script used to hardcode here, so it tracks new additions without
# becoming stale. Returns an empty array (never a hardcoded fallback list)
# if the fetch fails -- the caller falls back to generic wording.
function Get-BepInExRequiredGames {
    $games = Get-EggmanGameData
    if (-not $games) { return ,@() }
    $pattern = '(?i)requires?\s+(the\s+)?(latest\s+)?BepInEx|must\s+use\s+(the\s+)?(latest\s+)?BepInEx'
    return @($games | Where-Object { $_.notes -and $_.notes -match $pattern } |
              Select-Object -ExpandProperty game_name)
}

# Shared fetch+parse for the eggmansworld.github.io structured compatibility
# data (the <script type="application/json" id="game-data"> block). Returns
# the full deserialized array, or $null if the fetch/parse fails. Both
# Get-BepInExRequiredGames and Get-GameSetupNotes hit the same endpoint --
# centralizing the fetch-with-retry + regex-extract logic here means there's
# only one copy that can drift out of sync with the page's actual markup.
function Get-EggmanGameData {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $resp = Invoke-WebRequest -Uri 'https://eggmansworld.github.io/TeknoParrot/' `
                        -UseBasicParsing -TimeoutSec 20 -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $m = [regex]::Match($resp.Content, '(?s)<script type="application/json" id="game-data">(.*?)</script>')
            if (-not $m.Success) { return $null }
            return @($m.Groups[1].Value | ConvertFrom-Json)
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "EggmanGameData: fetch failed -- $_"; return $null
            }
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# Fetches the latest STABLE x64 BepInEx release info, fetch-with-retry
# shape identical to Get-EggmanDatRelease/Get-FFBPluginGameMap.
# Returns [pscustomobject]@{ Version; DownloadUrl; FileName } or $null.
function Get-BepInExLatestRelease {
    param([ValidateSet('x64','x86')][string]$Architecture = 'x64')
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/BepInEx/BepInEx/releases'
            $resp   = Invoke-WebRequest -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $releases = $resp.Content | ConvertFrom-Json
            # Releases are returned newest-first; prerelease=false reliably
            # distinguishes the v5-lts stable line from v6-bleeding-edge
            # pre-releases -- no tag-name parsing needed.
            $stable = @($releases | Where-Object { -not $_.prerelease }) | Select-Object -First 1
            if (-not $stable) { return $null }
            $asset = @($stable.assets | Where-Object { $_.name -like ('BepInEx_win_{0}_*.zip' -f $Architecture) }) | Select-Object -First 1
            if (-not $asset) { return $null }
            $parsedUri = $null
            $urlOk = [System.Uri]::TryCreate($asset.browser_download_url, [System.UriKind]::Absolute, [ref]$parsedUri) -and
                     $parsedUri.Scheme -eq 'https' -and
                     $parsedUri.Host -eq 'github.com' -and
                     [string]::IsNullOrEmpty($parsedUri.UserInfo) -and
                     $parsedUri.AbsolutePath.StartsWith('/BepInEx/BepInEx/releases/download/', [System.StringComparison]::Ordinal)
            if (-not $urlOk) {
                Write-Log "BepInEx: unexpected download URL format -- skipping."
                return $null
            }
            $verStr = $stable.tag_name.TrimStart('v')
            # The GitHub Releases API serves a machine-readable "digest"
            # field (sha256:<64-hex>) computed by GitHub itself from the
            # uploaded bytes, over the same allowlisted api.github.com host
            # already used to discover this download URL -- confirmed
            # present on real release assets during design. Extracted here
            # so every caller can opt into SHA-256 verification via
            # Invoke-TpmDownload -ExpectedSha256 instead of trusting size
            # alone; $null (not present/not sha256) means the caller falls
            # back to size-only validation, same as before this field existed.
            $expectedSha256 = Get-TpmSha256FromDigestField -Digest $asset.digest
            return [pscustomobject]@{
                Version = $verStr; Architecture = $Architecture; DownloadUrl = $asset.browser_download_url; FileName = $asset.name; SizeBytes = [int64]$asset.size; ExpectedSha256 = $expectedSha256
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "BepInEx: release query failed -- $_"; return $null
            }
            Write-Log "BepInEx: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# Fetches the latest dgVoodoo2 release from its official GitHub Releases
# channel (github.com/dege-diosg/dgVoodoo2). Mirrors Get-BepInExLatestRelease
# almost exactly: same URL-allowlist validation (scheme=https, host exactly
# github.com/api.github.com, no userinfo, path under the expected releases
# path), same 3-attempt retry/backoff/4xx-shortcircuit, same SHA-256 digest
# extraction. Selects the main (non-dev, non-debug) ZIP asset by name
# pattern -- dgVoodoo2 releases also ship dev/debug variant ZIPs that this
# script never wants. Returns [pscustomobject]@{ Version; DownloadUrl;
# FileName; SizeBytes; ExpectedSha256 } or $null.
function Get-DgVoodoo2LatestRelease {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/dege-diosg/dgVoodoo2/releases/latest'
            $resp   = Invoke-WebRequest -Uri $apiUri -UseBasicParsing -TimeoutSec 20 `
                          -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $release = $resp.Content | ConvertFrom-Json
            if (-not $release -or -not $release.assets) { return $null }
            # Main ZIP asset: named like "dgVoodoo2_87_3.zip" -- excludes any
            # asset name containing "dev" or "debug" (the dev/debug variant
            # ZIPs this project deliberately never fetches).
            $mainAsset = @($release.assets | Where-Object {
                $_.name -match '(?i)^dgVoodoo2[_0-9.]*\.zip$' -and $_.name -notmatch '(?i)dev|debug'
            }) | Select-Object -First 1
            if (-not $mainAsset) { return $null }
            $parsedUri = $null
            $urlOk = [System.Uri]::TryCreate($mainAsset.browser_download_url, [System.UriKind]::Absolute, [ref]$parsedUri) -and
                     $parsedUri.Scheme -eq 'https' -and
                     $parsedUri.Host -eq 'github.com' -and
                     [string]::IsNullOrEmpty($parsedUri.UserInfo) -and
                     $parsedUri.AbsolutePath.StartsWith('/dege-diosg/dgVoodoo2/releases/download/', [System.StringComparison]::Ordinal)
            if (-not $urlOk) {
                Write-Log "dgVoodoo2: unexpected download URL format -- skipping."
                return $null
            }
            $verStr = $release.tag_name.TrimStart('v')
            # GitHub may omit the optional digest property on an otherwise
            # valid release asset. Read it by property presence so strict
            # mode does not turn that compatibility case into a failed query.
            $digest = if ($mainAsset.PSObject.Properties.Name -contains 'digest') {
                $mainAsset.digest
            } else {
                $null
            }
            $expectedSha256 = Get-TpmSha256FromDigestField -Digest $digest
            return [pscustomobject]@{
                Version = $verStr; DownloadUrl = $mainAsset.browser_download_url; FileName = $mainAsset.name; SizeBytes = [int64]$mainAsset.size; ExpectedSha256 = $expectedSha256
            }
        } catch {
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge 3 -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "dgVoodoo2: release query failed -- $_"; return $null
            }
            Write-Log "dgVoodoo2: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# Extracts only the 6 known dgVoodoo2 files from a downloaded release ZIP
# into $DestDir, narrowly scoped rather than a generic "extract everything"
# -- a changed ZIP layout in a future dgVoodoo2 release is a "stop and tell
# the user" event, not a best-effort partial extraction. Each entry name is
# sanitized via [System.IO.Path]::GetFileName() and containment-checked via
# Test-PathInside before writing, same protection class SECURITY.md already
# mandates for BepInEx/FFBPlugin. Fails closed if any of the 6 expected
# entries is missing at its expected subpath within the ZIP.
#
# Transactional (P1 #1 remediation): all 6 files are extracted into an
# isolated staging directory (New-TpmStagingDirectory) and fully validated
# there first; $DestDir is never touched until the complete, valid set of 6
# exists in staging. Promotion into $DestDir goes through
# Invoke-TpmTransactionalPromote, which is itself rollback-safe -- if
# promoting any one of the 6 files fails partway through and rollback
# completes, $DestDir is restored to exactly its pre-call state (any of the
# other 5 already promoted in this same call are removed again, and any
# pre-existing files that were moved aside to make room are restored).
# On a recoverable failure (missing ZIP entry, an extraction-time error on
# any single entry, or a promotion-time error whose rollback completes),
# $DestDir ends up byte-for-byte unchanged from before this function was
# called. If an underlying filesystem mutation loses the original source
# before a valid backup is observable, exact restoration is impossible; the
# transaction instead reports an explicit ROLLBACK FAILED / INCONSISTENT
# condition and preserves recovery evidence. The staging directory is
# removed on ordinary success/failure when cleanup succeeds; it is
# preserved when transaction recovery, transaction cleanup, or ordinary
# staging cleanup fails so
# recovery evidence/residue remains available.
function Expand-DgVoodoo2Zip {
    param([string]$ZipPath, [string]$DestDir)

    # Expected subpath (inside the ZIP) -> destination file name. Verified
    # live against the real dgVoodoo2_87_3.zip release layout during this
    # feature's implementation: D3D8/DDraw/D3DImm all live under MS\x86\,
    # Glide2x/Glide3x both live under 3Dfx\x86\, and dgVoodoo.conf sits at
    # the ZIP root -- matching this script's own existing manual-install
    # instructions ("From the MS\x86\ subfolder", "From the 3Dfx\x86\
    # subfolder", "From the root of the ZIP").
    $expectedEntries = [ordered]@{
        'MS\x86\D3D8.dll'      = 'D3D8.dll'
        'MS\x86\DDraw.dll'     = 'DDraw.dll'
        'MS\x86\D3DImm.dll'    = 'D3DImm.dll'
        '3Dfx\x86\Glide2x.dll' = 'Glide2x.dll'
        '3Dfx\x86\Glide3x.dll' = 'Glide3x.dll'
        'dgVoodoo.conf'        = 'dgVoodoo.conf'
    }

    $stagingDir = New-TpmStagingDirectory -Label 'dgVoodoo2'
    $rollbackFailurePreserved = $false
    $operationError = $null
    try {
        $archive = $null
        try {
            $archive = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
            # Build a lookup of normalized (backslash, no leading slash) ZIP
            # entry paths -> ZipArchiveEntry, so each expected subpath can be
            # matched exactly regardless of the ZIP's own separator style.
            $byPath = @{}
            foreach ($entry in $archive.Entries) {
                $norm = $entry.FullName.Replace('/', '\').TrimStart('\')
                $byPath[$norm] = $entry
            }

            $missing = @($expectedEntries.Keys | Where-Object { -not $byPath.ContainsKey($_) })
            if ($missing.Count -gt 0) {
                throw "dgVoodoo2 release ZIP layout has changed -- missing expected file(s): $($missing -join ', ')"
            }

            # Phase 1: extract all 6 files into the STAGING directory only.
            # $DestDir is not touched at all in this phase.
            foreach ($subPath in $expectedEntries.Keys) {
                $destName = $expectedEntries[$subPath]
                # Sanitize: strip to a bare file name (defense in depth even
                # though $destName is a fixed literal above, not ZIP-derived)
                # and verify the resolved staging path stays inside
                # $stagingDir before ever opening a write handle.
                $safeName  = [System.IO.Path]::GetFileName($destName)
                $stagePath = Join-Path $stagingDir $safeName
                if ([string]::IsNullOrWhiteSpace($safeName) -or -not (Test-PathInside $stagePath $stagingDir)) {
                    throw "SECURITY: refused to stage dgVoodoo2 entry outside staging folder ($destName)."
                }
                Copy-TpmZipEntryToFile -Entry $byPath[$subPath] -DestPath $stagePath
            }
        } finally {
            if ($archive) { $archive.Dispose() }
        }

        # Final validation of the staged set before promotion: all 6 files
        # must actually exist in staging with non-zero length.
        $requiredNames = @($expectedEntries.Values)
        foreach ($name in $requiredNames) {
            $stagePath = Join-Path $stagingDir $name
            if (-not (Test-Path -LiteralPath $stagePath -PathType Leaf) -or (Get-Item -LiteralPath $stagePath).Length -le 0) {
                throw "dgVoodoo2: staged entry '$name' is missing or empty after extraction -- aborting before any destination change."
            }
        }

        # Only now, with a complete and valid staged set of 6, touch the
        # real destination -- rollback-safe promotion.
        [void](Invoke-TpmTransactionalPromote -StagingDir $stagingDir -DestDir $DestDir -FileNames $requiredNames)
    } catch {
        $operationError = $_
        # Same reasoning as Expand-ReShadeSelfExtractingArchive: if
        # Invoke-TpmTransactionalPromote reports a rollback or cleanup
        # failure, its backup copies under
        # $stagingDir\.tpm-rollback-backup are the remaining route to
        # manual recovery -- do not delete them here.
        if ($_.Exception.Message -match 'ROLLBACK FAILED|CLEANUP FAILED') {
            $rollbackFailurePreserved = $true
            Write-Log "Expand-DgVoodoo2Zip: staging directory '$stagingDir' preserved for manual recovery after a transaction recovery failure."
        }
        throw
    } finally {
        if (-not $rollbackFailurePreserved -and (Test-Path -LiteralPath $stagingDir)) {
            try {
                Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction Stop
            } catch {
                $cleanupMessage = "TPM STAGING CLEANUP FAILED for '$stagingDir' -- destination state was left valid or restored, but ordinary staging cleanup failed; residue remains at '$stagingDir'. Cleanup error: $($_.Exception.Message)"
                if ($operationError) {
                    $cleanupMessage += " Original operation error: $($operationError.Exception.Message)"
                }
                Write-Log $cleanupMessage
                throw $cleanupMessage
            }
        }
    }
}

# Returns the installed BepInEx version string for a game's exe folder, or
# $null if BepInEx is not installed there. BepInEx\core\BepInEx.dll's own
# FileVersion is the only reliable version source -- .doorstop_version is
# the unrelated Doorstop bootstrap version, not BepInEx's.
function Get-BepInExInstalledVersion {
    param([string]$ExeDir)
    $dllPath = Join-Path $ExeDir 'BepInEx\core\BepInEx.dll'
    if (-not (Test-Path -LiteralPath $dllPath)) { return $null }
    try {
        $vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($dllPath)
        if ([string]::IsNullOrWhiteSpace($vi.FileVersion)) { return $null }
        return $vi.FileVersion
    } catch { return $null }
}

# Returns 'x64', 'x86', or $null for an installed BepInEx's architecture.
# BepInEx's own managed DLLs are AnyCPU/MSIL in BOTH the win_x64 and win_x86
# zips, so they cannot reveal which build is installed -- only the native
# Doorstop winhttp.dll shim's PE machine type can.
function Get-BepInExInstalledArch {
    param([string]$ExeDir)
    $whPath = Join-Path $ExeDir 'winhttp.dll'
    if (-not (Test-Path -LiteralPath $whPath)) { return $null }
    return Get-ExeArchitecture -ExePath $whPath
}

function Test-BepInExNoReparsePath {
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][string]$Path)
    try {
        if ([string]::IsNullOrWhiteSpace($Root) -or [string]::IsNullOrWhiteSpace($Path)) { return $false }
        $rootFull = [System.IO.Path]::GetFullPath($Root).TrimEnd('\','/')
        $pathFull = [System.IO.Path]::GetFullPath($Path).TrimEnd('\','/')
        if (-not (Test-PathInside -child $pathFull -parent $rootFull)) { return $false }
        if (-not (Test-Path -LiteralPath $rootFull -PathType Container -ErrorAction SilentlyContinue)) { return $false }
        $rootItem = Get-Item -LiteralPath $rootFull -Force -ErrorAction Stop
        if (($rootItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { return $false }
        $relative = $pathFull.Substring($rootFull.Length).TrimStart('\','/')
        $cursor = $rootFull
        foreach ($part in ($relative -split '[\/]')) {
            if ([string]::IsNullOrWhiteSpace($part)) { continue }
            $cursor = Join-Path $cursor $part
            if (-not (Test-Path -LiteralPath $cursor)) { continue }
            $item = Get-Item -LiteralPath $cursor -Force -ErrorAction Stop
            if (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { return $false }
            if ($cursor -ine $pathFull -and -not $item.PSIsContainer) { return $false }
        }
        return $true
    } catch { return $false }
}

function Test-BepInExGameRootSafe {
    param([Parameter(Mandatory)][string]$GameRoot, [Parameter(Mandatory)][string]$ApprovedRoot)
    if (-not (Test-Path -LiteralPath $GameRoot -PathType Container -ErrorAction SilentlyContinue)) { return $false }
    return (Test-BepInExNoReparsePath -Root $ApprovedRoot -Path $GameRoot)
}

function Write-BepInExUnsafeRootGuidance {
    param(
        [Parameter(Mandatory)][string]$GameCode,
        [string]$ApprovedRoot = '',
        [string]$Reason = 'the game folder is outside the approved root or contains a reparse-backed path'
    )
    Write-Host ("  TPM could not safely update BepInEx for {0}." -f $GameCode) -ForegroundColor Red
    Write-Host '  The game folder is not a normal folder inside your chosen Games folder.' -ForegroundColor Yellow
    Write-Host ("  Check this game's path in TeknoParrot and move or correct it so it is inside: {0}" -f $ApprovedRoot) -ForegroundColor Yellow
    Write-Host '  TPM did not download or change anything. Then choose the BepInEx update again.' -ForegroundColor Yellow
    Write-Log "BepInEx update check: blocked on unsafe game root for $GameCode. Technical reason: $Reason. Action required: verify the game is inside the approved non-reparse root."
}

function Get-BepInExInstallationHealth {
    param([Parameter(Mandatory)][string]$ExeDir)
    $result = [ordered]@{ Installed = $false; Complete = $false; Version = $null; Architecture = $null; Reason = 'Not installed' }
    $dllPath = Join-Path $ExeDir 'BepInEx\core\BepInEx.dll'
    if (-not (Test-Path -LiteralPath $dllPath -PathType Leaf)) { return [pscustomobject]$result }
    $result.Installed = $true
    $result.Version = Get-BepInExInstalledVersion -ExeDir $ExeDir
    $result.Architecture = Get-BepInExInstalledArch -ExeDir $ExeDir
    $required = @('BepInEx\core\BepInEx.dll', 'winhttp.dll', 'doorstop_config.ini', '.doorstop_version')
    foreach ($relative in $required) {
        $path = Join-Path $ExeDir $relative
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            $result.Reason = 'Missing ' + $relative
            return [pscustomobject]$result
        }
        if (-not (Test-BepInExNoReparsePath -Root $ExeDir -Path $path)) {
            $result.Reason = 'Unsafe ' + $relative
            return [pscustomobject]$result
        }
    }
    if ([string]::IsNullOrWhiteSpace([string]$result.Version)) { $result.Reason = 'BepInEx version is unreadable'; return [pscustomobject]$result }
    if ($result.Architecture -notin @('x64','x86')) { $result.Reason = 'BepInEx native bootstrap architecture is unreadable'; return [pscustomobject]$result }
    $result.Complete = $true
    $result.Reason = 'Complete'
    return [pscustomobject]$result
}

function Test-BepInExExistingTreeSafe {
    param([Parameter(Mandatory)][string]$GameRoot)
    foreach ($name in @('BepInEx', 'doorstop_config.ini', 'winhttp.dll', '.doorstop_version', 'changelog.txt')) {
        $path = Join-Path $GameRoot $name
        if (-not (Test-Path -LiteralPath $path)) { continue }
        if (-not (Test-BepInExNoReparsePath -Root $GameRoot -Path $path)) { return $false }
        try {
            $item = Get-Item -LiteralPath $path -Force -ErrorAction Stop
            if ($item.PSIsContainer) {
                foreach ($child in @(Get-ChildItem -LiteralPath $path -Force -Recurse -ErrorAction Stop)) {
                    if (($child.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { return $false }
                }
            }
        } catch { return $false }
    }
    return $true
}

function Get-BepInExStagedFiles {
    param([Parameter(Mandatory)][string]$StagingDir, [Parameter(Mandatory)][string]$DestDir)
    if (-not (Test-Path -LiteralPath $StagingDir -PathType Container)) { throw 'BepInEx staging directory is missing.' }
    foreach ($item in @(Get-ChildItem -LiteralPath $StagingDir -Force -Recurse -ErrorAction Stop)) {
        if (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'BepInEx staging contains a reparse point.' }
    }
    $stageFull = [System.IO.Path]::GetFullPath($StagingDir).TrimEnd('\','/')
    $files = @(Get-ChildItem -LiteralPath $StagingDir -File -Recurse -ErrorAction Stop | Sort-Object FullName)
    $result = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($file in $files) {
        $relative = $file.FullName.Substring($stageFull.Length).TrimStart('\','/')
        if ([string]::IsNullOrWhiteSpace($relative) -or [System.IO.Path]::IsPathRooted($relative) -or $relative -match '(^|[\/])\.\.([\/]|$)') { throw 'BepInEx staging contains an unsafe relative path.' }
        $destPath = Join-Path $DestDir $relative
        if (-not (Test-PathInside -child $file.FullName -parent $StagingDir) -or -not (Test-PathInside -child $destPath -parent $DestDir)) { throw 'BepInEx staging path escaped its approved directory.' }
        $key = $relative.ToLowerInvariant()
        if ($seen.ContainsKey($key)) { throw 'BepInEx staging contains duplicate file names.' }
        $seen[$key] = $true
        [void]$result.Add($relative)
    }
    if ($result.Count -eq 0) { throw 'BepInEx ZIP contained no files to promote.' }
    return @($result)
}

# Removes only a TPM-created BepInEx staging directory under the controlled
# temporary root. The complete path and every existing descendant are checked
# again immediately before recursive deletion so cleanup cannot follow a
# replaced reparse point or delete an unrelated path.
function Remove-BepInExStagingDirectory {
    param([Parameter(Mandatory)][string]$StagingDir)
    if ([string]::IsNullOrWhiteSpace($StagingDir) -or $StagingDir -match '[\r\n]') {
        throw 'TPM BEPINEX STAGING CLEANUP REFUSED because the staging path was empty or malformed.'
    }
    try {
        $stagingRoot = [System.IO.Path]::GetFullPath((Join-Path $env:TEMP 'TeknoParrotManagerStaging')).TrimEnd('\','/')
        $stagingFull = [System.IO.Path]::GetFullPath($StagingDir).TrimEnd('\','/')
    } catch {
        throw 'TPM BEPINEX STAGING CLEANUP REFUSED because the staging path could not be canonicalized.'
    }
    $leaf = [System.IO.Path]::GetFileName($stagingFull)
    if ([string]::IsNullOrWhiteSpace($leaf) -or $leaf -notlike 'BepInEx-*' -or
        -not (Test-PathInside -child $stagingFull -parent $stagingRoot)) {
        throw "TPM BEPINEX STAGING CLEANUP REFUSED for '$stagingFull' because it is not a TPM BepInEx directory under the controlled staging root."
    }
    if (-not (Test-Path -LiteralPath $stagingFull)) { return $true }
    if (-not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $stagingFull)) {
        throw "TPM BEPINEX STAGING CLEANUP REFUSED for '$stagingFull' because its path is reparse-backed or otherwise unsafe."
    }
    try {
        $pending = New-Object 'System.Collections.Generic.Stack[string]'
        $files = New-Object 'System.Collections.Generic.List[string]'
        $directories = New-Object 'System.Collections.Generic.List[string]'
        $pending.Push($stagingFull)
        while ($pending.Count -gt 0) {
            $current = $pending.Pop()
            if (-not (Test-PathInside -child $current -parent $stagingRoot) -or
                -not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $current)) {
                throw "staging directory is outside the controlled root or reparse-backed: $current"
            }
            [void]$directories.Add($current)
            foreach ($child in @(Get-ChildItem -LiteralPath $current -Force -ErrorAction Stop)) {
                $childFull = [System.IO.Path]::GetFullPath($child.FullName)
                if (-not (Test-PathInside -child $childFull -parent $stagingFull)) {
                    throw "staging descendant escaped the validated directory: $childFull"
                }
                if (($child.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) {
                    throw "staging descendant is reparse-backed: $childFull"
                }
                if ($child.PSIsContainer) { $pending.Push($childFull) } else { [void]$files.Add($childFull) }
            }
        }
        foreach ($file in $files) {
            if (-not (Test-Path -LiteralPath $file)) { continue }
            if (-not (Test-PathInside -child $file -parent $stagingFull) -or
                -not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $file)) {
                throw "staging file changed to an unsafe path before cleanup: $file"
            }
            Remove-Item -LiteralPath $file -Force -ErrorAction Stop
        }
        for ($i = $directories.Count - 1; $i -ge 0; $i--) {
            $directory = $directories[$i]
            if (-not (Test-Path -LiteralPath $directory)) { continue }
            if (-not (Test-PathInside -child $directory -parent $stagingRoot) -or
                -not (Test-BepInExNoReparsePath -Root $stagingRoot -Path $directory)) {
                throw "staging directory changed to an unsafe path before cleanup: $directory"
            }
            Remove-Item -LiteralPath $directory -Force -ErrorAction Stop
        }
        if (Test-Path -LiteralPath $stagingFull) { throw 'staging directory remains after removal' }
    } catch {
        throw "TPM BEPINEX STAGING CLEANUP FAILED for '$stagingFull' -- residue remains at '$stagingFull'. Cleanup error: $($_.Exception.Message)"
    }
    return $true
}

function Test-BepInExFileMatch {
    param([Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Destination)
    if (-not (Test-Path -LiteralPath $Source -PathType Leaf) -or -not (Test-Path -LiteralPath $Destination -PathType Leaf)) { return $false }
    try {
        $sourceItem = Get-Item -LiteralPath $Source -Force -ErrorAction Stop
        $destItem = Get-Item -LiteralPath $Destination -Force -ErrorAction Stop
        if ($sourceItem.Length -ne $destItem.Length) { return $false }
        $sourceHash = (Get-FileHash -LiteralPath $Source -Algorithm SHA256 -ErrorAction Stop).Hash
        $destHash = (Get-FileHash -LiteralPath $Destination -Algorithm SHA256 -ErrorAction Stop).Hash
        return [string]::Equals([string]$sourceHash, [string]$destHash, [System.StringComparison]::OrdinalIgnoreCase)
    } catch { return $false }
}

function Test-BepInExBackupEntry {
    param([Parameter(Mandatory)][string]$Source, [Parameter(Mandatory)][string]$Backup)
    try {
        if (-not (Test-Path -LiteralPath $Source) -or -not (Test-Path -LiteralPath $Backup)) { return $false }
        $sourceItem = Get-Item -LiteralPath $Source -Force -ErrorAction Stop
        if (-not $sourceItem.PSIsContainer) { return (Test-BepInExFileMatch -Source $Source -Destination $Backup) }
        foreach ($child in @(Get-ChildItem -LiteralPath $Backup -Force -Recurse -ErrorAction Stop)) {
            if (($child.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { return $false }
        }
        $sourceFiles = @(Get-ChildItem -LiteralPath $Source -File -Recurse -ErrorAction Stop)
        $backupFiles = @(Get-ChildItem -LiteralPath $Backup -File -Recurse -ErrorAction Stop)
        if ($sourceFiles.Count -ne $backupFiles.Count) { return $false }
        $sourceRoot = [System.IO.Path]::GetFullPath($Source).TrimEnd('\','/')
        foreach ($file in $sourceFiles) {
            $relative = $file.FullName.Substring($sourceRoot.Length).TrimStart('\','/')
            if (-not (Test-BepInExFileMatch -Source $file.FullName -Destination (Join-Path $Backup $relative))) { return $false }
        }
        return $true
    } catch { return $false }
}

function New-BepInExUpdateBackup {
    param([Parameter(Mandatory)][string]$GameRoot)
    if (-not (Test-BepInExExistingTreeSafe -GameRoot $GameRoot)) { throw 'BepInEx target tree is unsafe before backup.' }
    $baseName = 'BepInEx_Backup_' + (Get-Date).ToString('yyyy-MM-dd_HH-mm-ss')
    $backupPath = Join-Path $GameRoot $baseName
    $suffix = 1
    while (Test-Path -LiteralPath $backupPath) { $backupPath = Join-Path $GameRoot ($baseName + '-' + $suffix); $suffix++ }
    [void][System.IO.Directory]::CreateDirectory($backupPath)
    try {
        foreach ($name in @('BepInEx', 'doorstop_config.ini', 'winhttp.dll', '.doorstop_version', 'changelog.txt')) {
            $source = Join-Path $GameRoot $name
            if (-not (Test-Path -LiteralPath $source)) { continue }
            if (-not (Test-BepInExNoReparsePath -Root $GameRoot -Path $source)) { throw "BepInEx source is reparse-backed: $name" }
            $destination = Join-Path $backupPath $name
            Copy-Item -LiteralPath $source -Destination $destination -Recurse -Force -ErrorAction Stop
            if (-not (Test-BepInExBackupEntry -Source $source -Backup $destination)) { throw "BepInEx backup verification failed for $name" }
        }
        return $backupPath
    } catch { throw "BepInEx backup failed; evidence remains at '$backupPath'." }
}

function Remove-BepInExFixedTree {
    param([Parameter(Mandatory)][string]$GameRoot)
    foreach ($name in @('BepInEx', 'doorstop_config.ini', 'winhttp.dll', '.doorstop_version', 'changelog.txt')) {
        $path = Join-Path $GameRoot $name
        if (Test-Path -LiteralPath $path) {
            if (-not (Test-BepInExNoReparsePath -Root $GameRoot -Path $path)) { throw "BepInEx reset refused unsafe path: $name" }
            Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop
        }
    }
}

function Restore-BepInExUpdateBackup {
    param([Parameter(Mandatory)][string]$GameRoot, [Parameter(Mandatory)][string]$BackupPath)
    foreach ($item in @(Get-ChildItem -LiteralPath $BackupPath -Force -ErrorAction Stop)) {
        $destination = Join-Path $GameRoot $item.Name
        Copy-Item -LiteralPath $item.FullName -Destination $destination -Recurse -Force -ErrorAction Stop
        if (-not (Test-BepInExBackupEntry -Source $item.FullName -Backup $destination)) { throw "BepInEx reset rollback verification failed: $($item.Name)" }
    }
}

function Invoke-TpmTransactionalTreePromote {
    param(
        [Parameter(Mandatory)][string]$StagingDir,
        [Parameter(Mandatory)][string]$DestDir,
        [Parameter(Mandatory)][string[]]$RelativeFiles,
        [scriptblock]$ValidationScript = $null
    )
    $rollbackDir = Join-Path $StagingDir '.tpm-rollback-backup'
    $originals = New-Object System.Collections.Generic.List[object]
    $promoted = New-Object System.Collections.Generic.List[string]
    $createdDirs = New-Object System.Collections.Generic.List[string]
    try {
        if (-not (Test-Path -LiteralPath $DestDir -PathType Container)) { throw 'BepInEx destination directory is missing.' }
        [void][System.IO.Directory]::CreateDirectory($rollbackDir)
        $seen = @{}
        foreach ($relative in @($RelativeFiles | Sort-Object)) {
            if ([string]::IsNullOrWhiteSpace($relative) -or [System.IO.Path]::IsPathRooted($relative) -or $relative -match '(^|[\/])\.\.([\/]|$)') { throw 'BepInEx transaction received an unsafe relative path.' }
            $source = Join-Path $StagingDir $relative
            $destination = Join-Path $DestDir $relative
            if (-not (Test-PathInside -child $source -parent $StagingDir) -or -not (Test-PathInside -child $destination -parent $DestDir)) { throw 'BepInEx transaction path escaped its approved directory.' }
            if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { throw "BepInEx staged file is missing: $relative" }
            $key = $relative.ToLowerInvariant()
            if ($seen.ContainsKey($key)) { throw 'BepInEx transaction received duplicate paths.' }
            $seen[$key] = $true
            if (-not (Test-BepInExNoReparsePath -Root $DestDir -Path $destination)) { throw "BepInEx destination path is unsafe: $relative" }
            if (Test-Path -LiteralPath $destination) {
                if (-not (Test-Path -LiteralPath $destination -PathType Leaf)) { throw "BepInEx destination is not a file: $relative" }
                $rollbackFile = Join-Path $rollbackDir $relative
                [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($rollbackFile))
                Copy-Item -LiteralPath $destination -Destination $rollbackFile -Force -ErrorAction Stop
                if (-not (Test-BepInExFileMatch -Source $destination -Destination $rollbackFile)) { throw "BepInEx rollback capture failed: $relative" }
                [void]$originals.Add([pscustomobject]@{ Relative = $relative; Backup = $rollbackFile })
            }
        }
        $destFull = [System.IO.Path]::GetFullPath($DestDir).TrimEnd('\','/')
        foreach ($relative in @($RelativeFiles | Sort-Object)) {
            $source = Join-Path $StagingDir $relative
            $destination = Join-Path $DestDir $relative
            $parent = [System.IO.Path]::GetDirectoryName($destination)
            $missing = New-Object System.Collections.Generic.List[string]
            $cursor = $parent
            while ($cursor -and $cursor -ine $destFull -and -not (Test-Path -LiteralPath $cursor -PathType Container)) {
                [void]$missing.Add($cursor)
                $cursor = [System.IO.Path]::GetDirectoryName($cursor)
            }
            if ($cursor -ine $destFull) { throw "BepInEx destination parent is outside the game root: $relative" }
            for ($i = $missing.Count - 1; $i -ge 0; $i--) {
                [void][System.IO.Directory]::CreateDirectory($missing[$i])
                [void]$createdDirs.Add($missing[$i])
            }
            [void]$promoted.Add($relative)
            Copy-Item -LiteralPath $source -Destination $destination -Force -ErrorAction Stop
            if (-not (Test-BepInExFileMatch -Source $source -Destination $destination)) { throw "BepInEx promoted file verification failed: $relative" }
        }
        if ($ValidationScript -and -not [bool](& $ValidationScript)) { throw 'BepInEx post-promotion validation failed.' }
    } catch {
        $promotionError = $_
        $rollbackErrors = New-Object System.Collections.Generic.List[string]
        for ($i = $promoted.Count - 1; $i -ge 0; $i--) {
            $destination = Join-Path $DestDir $promoted[$i]
            try {
                if (Test-Path -LiteralPath $destination) {
                    $item = Get-Item -LiteralPath $destination -Force -ErrorAction Stop
                    if (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0 -or $item.PSIsContainer) { throw 'promoted target is not a regular file' }
                    Remove-Item -LiteralPath $destination -Force -ErrorAction Stop
                }
            } catch { [void]$rollbackErrors.Add("remove '$destination'") }
        }
        for ($i = $originals.Count - 1; $i -ge 0; $i--) {
            $entry = $originals[$i]; $destination = Join-Path $DestDir $entry.Relative
            try {
                [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($destination))
                Copy-Item -LiteralPath $entry.Backup -Destination $destination -Force -ErrorAction Stop
                if (-not (Test-BepInExFileMatch -Source $entry.Backup -Destination $destination)) { throw 'restored hash mismatch' }
            } catch { [void]$rollbackErrors.Add("restore '$destination'") }
        }
        for ($i = $createdDirs.Count - 1; $i -ge 0; $i--) {
            try {
                $dir = $createdDirs[$i]
                if (Test-Path -LiteralPath $dir -PathType Container -and @(Get-ChildItem -LiteralPath $dir -Force -ErrorAction SilentlyContinue).Count -eq 0) { Remove-Item -LiteralPath $dir -Force -ErrorAction Stop }
            } catch { [void]$rollbackErrors.Add("remove created directory '$($createdDirs[$i])'") }
        }
        if ($rollbackErrors.Count -gt 0) {
            $message = "TPM TRANSACTION ROLLBACK FAILED for '$DestDir'; evidence remains at '$rollbackDir'."
            Write-Log "BepInEx: $message"
            throw $message
        }
        try { if (Test-Path -LiteralPath $rollbackDir) { Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction Stop } } catch {
            $message = "TPM TRANSACTION CLEANUP FAILED for '$DestDir'; evidence remains at '$rollbackDir'."
            Write-Log "BepInEx: $message"
            throw $message
        }
        Write-Log "BepInEx: rollback completed for '$DestDir'."
        throw $promotionError
    }
    try { if (Test-Path -LiteralPath $rollbackDir) { Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction Stop } } catch {
        $message = "TPM TRANSACTION CLEANUP FAILED for '$DestDir'; evidence remains at '$rollbackDir'."
        Write-Log "BepInEx: $message"
        throw $message
    }
    return $true
}

# Validates every inspectable game root before release query, prompt, download,
# backup, extraction, or promotion. Fresh installs and existing updates use
# stable x64 or x86 releases selected from the executable/installed shim.
function Invoke-BepInExUpdateCheck {
    param([string]$UserProfilesDir, [string]$CacheDir, [string]$ApprovedGamesRoot = '')
    if ([string]::IsNullOrWhiteSpace($ApprovedGamesRoot)) { $ApprovedGamesRoot = $gamesInstallFolder }
    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue | Where-Object { $_.Directory.Name -ne 'FullBackup' } | Sort-Object Name)
    if ($profiles.Count -eq 0) { Write-Host '  No registered games found.' -ForegroundColor Yellow; Write-Log 'BepInEx update check: aborted -- no registered profiles.'; return }
    if (-not (Test-Path -LiteralPath $ApprovedGamesRoot -PathType Container -ErrorAction SilentlyContinue)) { Write-Host '  The configured games root could not be verified -- no BepInEx changes made.' -ForegroundColor Red; Write-Log "BepInEx update check: blocked because approved root is unavailable: $ApprovedGamesRoot"; return }
    $candidates = New-Object System.Collections.Generic.List[object]
    $safetyBlocked = $false
    foreach ($pf in $profiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $gamePathNode = $doc.GameProfile.SelectSingleNode('GamePath')
            if (-not $gamePathNode -or [string]::IsNullOrWhiteSpace($gamePathNode.InnerText)) { continue }
            $gamePath = $gamePathNode.InnerText.Trim()
            if (-not (Test-Path -LiteralPath $gamePath -PathType Leaf)) { continue }
            $exeDir = [System.IO.Path]::GetDirectoryName($gamePath)
            if (-not (Test-BepInExGameRootSafe -GameRoot $exeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExNoReparsePath -Root $exeDir -Path $gamePath)) {
                $safetyBlocked = $true
                Write-BepInExUnsafeRootGuidance -GameCode $pf.BaseName -ApprovedRoot $ApprovedGamesRoot
                continue
            }
            [void]$candidates.Add([pscustomobject]@{ Code = $pf.BaseName; ExeDir = $exeDir; GamePath = $gamePath })
        } catch {
            $safetyBlocked = $true
            Write-BepInExUnsafeRootGuidance -GameCode $pf.BaseName -ApprovedRoot $ApprovedGamesRoot -Reason 'the game root could not be verified'
        }
    }
    if ($safetyBlocked) { Write-Host '  No BepInEx download or write was attempted.' -ForegroundColor Yellow; return [pscustomobject]@{ Succeeded = $false; Reason = 'UNSAFE_ROOT' } }

    Write-Host ''
    Write-Host '  Checking stable BepInEx releases for the detected game architectures...' -ForegroundColor DarkGray
    $latestByArch = @{}
    $requiredArchitectures = @($candidates | ForEach-Object {
        $installedArch = Get-BepInExInstalledArch -ExeDir $_.ExeDir
        $exeArch = $null
        try { $exeArch = Get-ExeArchitecture -ExePath $_.GamePath } catch {}
        if ($installedArch -in @('x64','x86') -and ($exeArch -notin @('x64','x86') -or $exeArch -eq $installedArch)) { $installedArch } else { $exeArch }
    } | Where-Object { $_ -in @('x64','x86') } | Sort-Object -Unique)
    foreach ($architecture in $requiredArchitectures) {
        $latestByArch[$architecture] = Get-BepInExLatestRelease -Architecture $architecture
        if (-not $latestByArch[$architecture]) {
            Write-Host ("  TPM could not reach GitHub for the stable {0} BepInEx release. Nothing was changed." -f $architecture) -ForegroundColor Red
            Write-Host '  Check the connection and choose this setup again; TPM will retry the automatic download.' -ForegroundColor Yellow
            Write-Log "BepInEx update check: release query failed for $architecture."
            return [pscustomobject]@{ Succeeded = $false; Reason = 'RELEASE_QUERY_FAILED' }
        }
    }
    $outdated = New-Object System.Collections.Generic.List[object]
    $upToDate = 0; $errors = 0
    foreach ($candidate in $candidates) {
        try {
            $health = Get-BepInExInstallationHealth -ExeDir $candidate.ExeDir
            $installedVer = $health.Version
            $installedArch = $health.Architecture
            $exeArch = $null
            try { $exeArch = Get-ExeArchitecture -ExePath $candidate.GamePath } catch {}
            if ($exeArch -in @('x64','x86') -and $installedArch -in @('x64','x86') -and $installedArch -ne $exeArch) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = $installedVer; Architecture = $exeArch; Latest = $latestByArch[$exeArch]; RepairRequired = $true })
                continue
            }
            $arch = if ($installedArch -in @('x64','x86')) { $installedArch } else { $exeArch }
            $latest = $latestByArch[$arch]
            if (-not $latest) { continue }
            if (-not $health.Installed) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = 'Not installed'; Architecture = $arch; Latest = $latest; RepairRequired = $false })
                continue
            }
            if (-not $health.Complete) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = 'Broken (' + $health.Reason + ')'; Architecture = $arch; Latest = $latest; RepairRequired = $true })
                continue
            }
            $instParsed = $null; $latestParsed = $null
            if (-not [version]::TryParse($installedVer, [ref]$instParsed) -or -not [version]::TryParse($latest.Version, [ref]$latestParsed)) { continue }
            if ($instParsed -lt $latestParsed) {
                [void]$outdated.Add([pscustomobject]@{ Code = $candidate.Code; ExeDir = $candidate.ExeDir; GamePath = $candidate.GamePath; Installed = $installedVer; Architecture = $arch; Latest = $latest })
            } else { $upToDate++ }
        } catch { $errors++; Write-Log "BepInEx update check: inspection failed for $($candidate.Code)." }
    }
    if ($outdated.Count -eq 0) {
        Write-Host ("  Up to date: {0} game(s)" -f $upToDate) -ForegroundColor Green
        if ($errors -gt 0) { Write-Host ("  Errors: {0}" -f $errors) -ForegroundColor Red }
        return [pscustomobject]@{ Succeeded = ($errors -eq 0); Reason = if ($errors) { 'INSPECTION_FAILED' } else { $null } }
    }
    Write-Host ("  {0} game(s) need BepInEx installation or update:" -f $outdated.Count) -ForegroundColor Cyan
    foreach ($o in @($outdated | Sort-Object Code)) { Write-Host ("    - {0}: {1} -> {2} ({3})" -f $o.Code, $o.Installed, $o.Latest.Version, $o.Architecture) -ForegroundColor DarkGray }
    $repairChoice = (Read-HostSafe ("  Y Install/update, R repair-reset then install, or N cancel for these {0} game(s)? (Y/R/N)" -f $outdated.Count)).ToUpper()
    if ($repairChoice -notin @('Y','R')) {
        Write-Log 'BepInEx update check: user declined installation/update/reset.'
        return [pscustomobject]@{ Succeeded = $false; Reason = 'DECLINED' }
    }
    $repairReset = ($repairChoice -eq 'R')
    [void][System.IO.Directory]::CreateDirectory($CacheDir)
    $zipByArch = @{}
    foreach ($architecture in @($outdated | Select-Object -ExpandProperty Architecture -Unique)) {
        $latest = $latestByArch[$architecture]
        $safeFileName = [System.IO.Path]::GetFileName($latest.FileName)
        $zipPath = Join-Path $CacheDir $safeFileName
        if ([string]::IsNullOrWhiteSpace($safeFileName) -or -not (Test-PathInside $zipPath $CacheDir)) {
            Write-Log "BepInEx update check: blocked on unsafe $architecture release filename."
            return [pscustomobject]@{ Succeeded = $false; Reason = 'UNSAFE_RELEASE_FILENAME' }
        }
        if (-not (Invoke-TpmDownload -DownloadUrl $latest.DownloadUrl -DestinationPath $zipPath -ExpectedBytes $latest.SizeBytes -Label 'BepInEx' -Version $latest.Version -ExpectedSha256 $latest.ExpectedSha256)) {
            Write-Host ("  BepInEx {0}-bit download failed. Nothing was changed." -f ($(if ($architecture -eq 'x86') { '32' } else { '64' }))) -ForegroundColor Red
            Write-Host '  Choose this setup again to retry automatically, or cancel without changing the game.' -ForegroundColor Yellow
            Write-Log "BepInEx update check: download or digest verification failed for $architecture."
            return [pscustomobject]@{ Succeeded = $false; Reason = 'DOWNLOAD_FAILED' }
        }
        $zipByArch[$architecture] = $zipPath
    }
    $updated = 0; $updatedWithCleanupFailure = 0; $updateErrors = 0; $cleanupErrors = 0
    foreach ($o in @($outdated | Sort-Object Code)) {
        $stagingDir = $null; $preserveStaging = $false; $promotionSucceeded = $false; $cleanupFailureRecorded = $false
        $backupPath = $null
        $resetApplied = $false
        try {
            if (-not (Test-BepInExGameRootSafe -GameRoot $o.ExeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExExistingTreeSafe -GameRoot $o.ExeDir)) { throw 'BepInEx final root safety check failed.' }
            $stagingDir = New-TpmStagingDirectory -Label 'BepInEx'
            $zipPathForGame = $zipByArch[$o.Architecture]
            Expand-ZipFileSafe -ZipPath $zipPathForGame -DestDir $stagingDir -GameName $o.Code
            $relativeFiles = @(Get-BepInExStagedFiles -StagingDir $stagingDir -DestDir $o.ExeDir)
            if (-not (Test-BepInExGameRootSafe -GameRoot $o.ExeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExExistingTreeSafe -GameRoot $o.ExeDir)) { throw 'BepInEx root changed before backup.' }
            $backupPath = New-BepInExUpdateBackup -GameRoot $o.ExeDir
            if (-not (Test-BepInExGameRootSafe -GameRoot $o.ExeDir -ApprovedRoot $ApprovedGamesRoot) -or -not (Test-BepInExExistingTreeSafe -GameRoot $o.ExeDir)) { throw 'BepInEx root failed after backup.' }
            if ($repairReset) {
                $resetApplied = $true
                Remove-BepInExFixedTree -GameRoot $o.ExeDir
            }
            $validation = { return ((Get-BepInExInstalledVersion -ExeDir $o.ExeDir) -eq $o.Latest.Version) }
            [void](Invoke-TpmTransactionalTreePromote -StagingDir $stagingDir -DestDir $o.ExeDir -RelativeFiles $relativeFiles -ValidationScript $validation)
            $promotionSucceeded = $true
            [void](Remove-BepInExStagingDirectory -StagingDir $stagingDir)
            $stagingDir = $null
            Write-Host ("    OK    {0}  ({1} -> {2})" -f $o.Code, $o.Installed, $o.Latest.Version) -ForegroundColor Green
            Write-Log "BepInEx: updated $($o.Code) from $($o.Installed) to $($o.Latest.Version); backup=$backupPath"
            $updated++
        } catch {
            if ($promotionSucceeded -and $_.Exception.Message -match '^TPM BEPINEX STAGING CLEANUP (FAILED|REFUSED)') {
                $preserveStaging = $true
                $cleanupFailureRecorded = $true
                Write-Host ("    WARNING {0} -- update applied, but staging cleanup failed" -f $o.Code) -ForegroundColor Yellow
                Write-Host ("            ACTION REQUIRED: inspect and remove residue at {0}" -f $stagingDir) -ForegroundColor Yellow
                Write-Log "BepInEx: update applied for $($o.Code), but staging cleanup failed; action required; residue=$stagingDir; backup=$backupPath"
                $updatedWithCleanupFailure++
                $cleanupErrors++
            } else {
                if ($resetApplied -and -not $promotionSucceeded -and $backupPath) {
                    try { Restore-BepInExUpdateBackup -GameRoot $o.ExeDir -BackupPath $backupPath }
                    catch { Write-Host ("    ERROR {0} -- repair reset rollback failed; backup remains at {1}" -f $o.Code, $backupPath) -ForegroundColor Red; Write-Log "BepInEx reset rollback failed for $($o.Code); backup=$backupPath"; $updateErrors++ }
                }
                if ($_.Exception.Message -match 'ROLLBACK FAILED|CLEANUP FAILED') { $preserveStaging = $true }
                Write-Host ("    ERROR {0} -- update blocked" -f $o.Code) -ForegroundColor Red
                Write-Log "BepInEx: update blocked for $($o.Code); evidence and backups were preserved where available."
                $updateErrors++
            }
        } finally {
            if ($stagingDir -and -not $preserveStaging) {
                try {
                    [void](Remove-BepInExStagingDirectory -StagingDir $stagingDir)
                    $stagingDir = $null
                } catch {
                    $preserveStaging = $true
                    if (-not $cleanupFailureRecorded) {
                        Write-Host ("    ACTION REQUIRED {0} -- staging cleanup failed" -f $o.Code) -ForegroundColor Yellow
                        Write-Host ("                    Inspect and remove residue at {0}" -f $stagingDir) -ForegroundColor Yellow
                        Write-Log "BepInEx: staging cleanup failed for blocked update $($o.Code); action required; residue=$stagingDir"
                        $cleanupErrors++
                    }
                }
            }
        }
    }
    Write-Host ("  Updated cleanly: {0} game(s)" -f $updated) -ForegroundColor Green
    if ($updatedWithCleanupFailure -gt 0) { Write-Host ("  Updated with cleanup failure: {0} -- ACTION REQUIRED" -f $updatedWithCleanupFailure) -ForegroundColor Yellow }
    if ($updateErrors -gt 0) { Write-Host ("  Errors: {0} -- see log for details" -f $updateErrors) -ForegroundColor Red }
    if ($cleanupErrors -gt 0) { Write-Host ("  Cleanup failures: {0} -- see log for residue path(s)" -f $cleanupErrors) -ForegroundColor Yellow }
    Write-Log ("BepInEx update check: updatedCleanly={0} updatedWithCleanupFailure={1} errors={2} cleanupFailures={3}" -f $updated, $updatedWithCleanupFailure, $updateErrors, $cleanupErrors)
    return [pscustomobject]@{ Succeeded = ($updateErrors -eq 0 -and $cleanupErrors -eq 0 -and $updatedWithCleanupFailure -eq 0); Updated = $updated; Errors = $updateErrors + $cleanupErrors }
}
# =============================================================================
# CHECK FOR UPDATES -- manual, backup-first self-update for this script
# =============================================================================
# See docs/AUTO_UPDATE.md for the full design. This mirrors the standalone
# tools/Invoke-TpmAutoUpdate.ps1 helper's logic (same release asset pattern,
# same content-validation checks, same read-only pre-check) but inlined here
# as plain functions -- consistent with this script's single-file, no-
# external-module architecture -- and driven by the interactive Y/N
# confirmation flow the menu requires instead of -CheckOnly/-Apply switches.
# TLS 1.2 is already forced globally near the top of this script, so no
# separate per-call TLS setup is needed here.

function ConvertTo-ManagerComparableVersion {
    # [version] can only hold numeric dot-separated segments -- it throws on
    # any non-numeric suffix (e.g. "1.0-RC1"). Release tags carry a "-RC#"
    # (or similar prerelease) suffix for display purposes, so the numeric
    # base is extracted before parsing. This is sufficient for this script's
    # only actual use of the result: comparing the single current
    # $ScriptVersion against a single latest-release tag, never two
    # prereleases of the same numeric base against each other, so a release
    # candidate and its own eventual final release under the same numeric
    # base (e.g. "1.0-RC1" and "1.0") compare as equal rather than the RC
    # being "older" -- correct for "don't re-offer the version I'm already
    # on," not a general semver-precedence implementation. See issue #105.
    param([Parameter(Mandatory)][string]$VersionText)
    $normalized  = ($VersionText -replace '^v', '').Trim()
    $numericPart = ($normalized -split '-')[0].Trim()
    try {
        return [version]$numericPart
    } catch {
        throw "Version '$VersionText' is not a valid version number after normalization."
    }
}

# Converts a raw GitHub release tag (e.g. "v1.0-RC2", "v0.99.44") into this
# script's own canonical display shape: "v<version> <LABEL>" with a space,
# the same shape $DisplayVersion already uses for the running script
# ("v1.0 RC2") -- never the dash-separated git tag form. Without this, the
# "Current version" line (built from $DisplayVersion/$ScriptVersion) and
# the "Latest version" line (previously the raw tag) could show the same
# release two different ways side by side, e.g. "v1.0" vs "v1.0-RC2" --
# correct per ConvertTo-ManagerComparableVersion's numeric-base comparison,
# but confusing to read. See issue #134.
function ConvertTo-ManagerDisplayVersionFromTag {
    param([Parameter(Mandatory)][string]$VersionText)
    $normalized = ($VersionText -replace '^v', '').Trim()
    $parts = $normalized -split '-', 2
    if ($parts.Count -gt 1 -and $parts[1]) {
        return "v{0} {1}" -f $parts[0], $parts[1]
    }
    return "v$($parts[0])"
}

function Get-ManagerUpdateRelease {
    # Same retry/backoff shape as Get-BepInExLatestRelease / Get-EggmanDatRelease,
    # but MaxAttempts/TimeoutSec are tunable: the menu-triggered check can afford
    # to retry patiently since the user explicitly asked, but the quiet startup
    # check (Invoke-StartupUpdateCheck) uses a single short-timeout attempt so an
    # unreachable GitHub cannot noticeably delay launching the script.
    param(
        [int]$MaxAttempts = 3,
        [int]$TimeoutSec = 20
    )

    for ($attempt = 1; $attempt -le $MaxAttempts; $attempt++) {
        try {
            $apiUri = 'https://api.github.com/repos/Jumpstile/teknoparrot-manager/releases/latest'
            $resp    = Invoke-WebRequest -Uri $apiUri -UseBasicParsing -TimeoutSec $TimeoutSec `
                           -Headers @{ 'User-Agent' = "TeknoParrot-Manager/$ScriptVersion" }
            $release = $resp.Content | ConvertFrom-Json
            $asset   = @($release.assets | Where-Object { $_.name -match '^TeknoParrot\.Manager\.v.*\.zip$' }) | Select-Object -First 1
            if (-not $asset) {
                Write-Log "CheckForUpdates: latest release $($release.tag_name) has no matching asset."
                return $null
            }
            # URI-parsed validation (not -like/regex prefix matching) so the
            # host check inspects the actual parsed authority -- rejects
            # userinfo tricks and lookalike hosts a naive prefix check could
            # be fooled by. Same approach as the standalone updater tool.
            $parsedUri = $null
            $urlOk = [System.Uri]::TryCreate($asset.browser_download_url, [System.UriKind]::Absolute, [ref]$parsedUri) -and
                     $parsedUri.Scheme -eq 'https' -and
                     $parsedUri.Host -eq 'github.com' -and
                     [string]::IsNullOrEmpty($parsedUri.UserInfo) -and
                     $parsedUri.AbsolutePath.StartsWith('/Jumpstile/teknoparrot-manager/releases/download/', [System.StringComparison]::Ordinal)
            if (-not $urlOk) {
                Write-Log "CheckForUpdates: refusing non-release GitHub asset URL: $($asset.browser_download_url)"
                return $null
            }
            return [pscustomobject]@{
                TagName     = $release.tag_name
                Name        = $release.name
                Body        = $release.body
                AssetName   = $asset.name
                DownloadUrl = $asset.browser_download_url
                SizeBytes   = [int64]$asset.size
            }
        } catch {
            $status = 0
            # Get-TpmHttpStatusCodeFromError guards the same optional
            # .Exception.Response/.StatusCode access this used to do inline
            # (unsafe under strict mode for exception types that lack either
            # property entirely -- RuntimeException from a plain "throw",
            # HttpRequestException, etc.) and additionally falls back to
            # extracting a status code embedded only in the message text.
            $status = Get-TpmHttpStatusCodeFromError -ErrorRecord $_
            if ($attempt -ge $MaxAttempts -or ($status -ge 400 -and $status -lt 500)) {
                Write-Log "CheckForUpdates: release query failed -- $_"; return $null
            }
            Write-Log "CheckForUpdates: attempt $attempt failed, retrying in 5s -- $_"
            Start-Sleep -Seconds 5
        }
    }
    return $null
}

# First non-blank line of a release's markdown body, trimmed of the most
# common markdown decoration and clamped to a short length -- a "brief
# summary" for the startup notice, not a full changelog rendering.
function Get-ManagerUpdateReleaseSummary {
    param([string]$Body)

    if ([string]::IsNullOrWhiteSpace($Body)) { return $null }

    $firstLine = ($Body -split "`r?`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1)
    if (-not $firstLine) { return $null }

    $firstLine = $firstLine.Trim() -replace '^#+\s*', '' -replace '^[-*]\s*', ''
    if ($firstLine.Length -gt 150) {
        $firstLine = $firstLine.Substring(0, 150).TrimEnd() + "..."
    }
    return $firstLine
}

function Assert-ManagerUpdateTargetWritable {
    param([Parameter(Mandatory)][string]$Path)

    # An explicitly approved update may clear only the target script's
    # ReadOnly attribute. The installer transaction records that fact and
    # reapplies it to the replacement or original file in finally.
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if ($item.IsReadOnly) {
        Set-ItemProperty -LiteralPath $Path -Name IsReadOnly -Value $false -ErrorAction Stop
        return $true
    }
    return $false
}

function New-ManagerUpdateBackup {
    param([Parameter(Mandatory)][string]$Path)

    # Derived from $Path itself (not $PSScriptRoot) so the backup always
    # lands next to the actual target file regardless of caller context --
    # matches the standalone tools/TpmAutoUpdate.Core.psm1 module's
    # New-TpmUpdateBackup, and avoids relying on $PSScriptRoot, which is an
    # automatic variable reset per function invocation rather than an
    # ordinary dynamically-scoped one (a caller cannot override it).
    $repoRoot   = Split-Path -Parent $Path
    $backupRoot = Join-Path $repoRoot "UpdateBackups"
    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss")
    $backupDir  = Join-Path $backupRoot ("TeknoParrotManager_" + $timestamp)
    New-Item -ItemType Directory -Path $backupDir -Force | Out-Null

    $backupPath = Join-Path $backupDir (Split-Path -Leaf $Path)
    Copy-Item -LiteralPath $Path -Destination $backupPath -Force

    if (-not (Test-Path -LiteralPath $backupPath -PathType Leaf)) {
        throw "Backup creation failed: $backupPath"
    }
    return $backupPath
}

function Expand-ManagerUpdateAsset {
    param(
        [Parameter(Mandatory)][string]$ZipPath,
        [Parameter(Mandatory)][string]$EntryName,
        [Parameter(Mandatory)][string]$DestinationPath
    )

    if (-not (Test-Path -LiteralPath $ZipPath -PathType Leaf)) {
        throw "Downloaded release asset not found: $ZipPath"
    }

    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    $zip = [System.IO.Compression.ZipFile]::OpenRead($ZipPath)
    try {
        $entry = $zip.Entries | Where-Object { $_.FullName -eq $EntryName } | Select-Object -First 1
        if (-not $entry) {
            throw "Release asset does not contain the expected entry '$EntryName'."
        }
        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $DestinationPath, $true)
    } finally {
        $zip.Dispose()
    }
    return $DestinationPath
}

function Test-ManagerUpdateExtractedScript {
    param([Parameter(Mandatory)][string]$Path)

    # Defense-in-depth before the extracted file ever replaces the live
    # script: exists, non-empty, is not the raw zip container (would happen
    # if extraction were ever skipped or broken upstream), and looks like
    # TeknoParrot-Manager.ps1 rather than an unrelated or truncated file.
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "Extracted script not found: $Path"
    }
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -eq 0) {
        throw "Extracted script is empty: $Path"
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0x50 -and $bytes[1] -eq 0x4B) {
        throw "Extracted script begins with a zip signature (PK) -- refusing to install: $Path"
    }
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($content -notmatch 'TeknoParrot Manager') {
        throw "Extracted script does not contain the expected 'TeknoParrot Manager' marker: $Path"
    }
    if ($content -notmatch '\$ScriptVersion\s*=\s*"[^"]+"') {
        throw "Extracted script does not contain a `$ScriptVersion assignment: $Path"
    }
    return $true
}

# Does the check, confirmation, and (if accepted) the actual update. Returns
# $true only if a new script was installed -- callers must not keep running
# after that (the in-memory code is now stale) and should exit rather than
# continue the menu loop. Returns $false for every other outcome (already
# current, declined, or failed), all of which are safe to fall through to
# "press Enter to return to menu".
# Shared backup/download/extract/validate/replace path used by both the menu
# option and the startup checker, once each has already obtained its own
# explicit confirmation (their prompts differ, so that step stays in each
# caller). Never prompts itself. Returns $true only if a new script was
# actually installed.
function Invoke-ManagerUpdateInstall {
    param(
        [Parameter(Mandatory)][string]$ScriptPath,
        [Parameter(Mandatory)][pscustomobject]$Release
    )
    $readOnlyCleared = $false
    try {
        $readOnlyCleared = [bool](Assert-ManagerUpdateTargetWritable -Path $ScriptPath)
    } catch {
        Write-Host ""
        Write-Host "  TPM could not prepare the update because the script file could not be changed safely." -ForegroundColor Red
        Write-Host "  No backup or download was attempted." -ForegroundColor Yellow
        Write-Log "CheckForUpdates: writable-target preparation failed."
        return $false
    }
    if ($readOnlyCleared) {
        Write-Host '  TPM temporarily cleared the file protection for this approved update and will restore it after this attempt.' -ForegroundColor DarkGray
    }

    $downloadedZipPath = $null
    $extractedScriptPath = $null
    $backupPath = $null
    try {
        Write-Host ""
        Write-Host "  Backing up current script..." -ForegroundColor DarkGray
        $backupPath = New-ManagerUpdateBackup -Path $ScriptPath
        Write-Host "  Backup created: $backupPath" -ForegroundColor Green
        Write-Log "CheckForUpdates: backup created at $backupPath"

        Write-Host "  Downloading $($Release.AssetName)..." -ForegroundColor DarkGray
        $downloadedZipPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-update-" + [guid]::NewGuid().ToString('N') + '.zip')
        if (-not (Invoke-TpmDownload -DownloadUrl $Release.DownloadUrl -DestinationPath $downloadedZipPath -ExpectedBytes $Release.SizeBytes -Label 'CheckForUpdates' -Version $Release.TagName)) {
            throw "Downloaded update asset is missing, empty, or incomplete: $downloadedZipPath"
        }

        Write-Host "  Extracting and validating..." -ForegroundColor DarkGray
        $extractedScriptPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-update-extracted-" + [guid]::NewGuid().ToString('N') + '.ps1')
        Expand-ManagerUpdateAsset -ZipPath $downloadedZipPath -EntryName "TeknoParrot-Manager.ps1" -DestinationPath $extractedScriptPath | Out-Null
        Test-ManagerUpdateExtractedScript -Path $extractedScriptPath | Out-Null

        Write-Host "  Installing update..." -ForegroundColor DarkGray
        # -ErrorAction Stop is required here, not optional: $ErrorActionPreference
        # is never set anywhere in this script (defaults to 'Continue'), so a
        # sharing-violation failure (e.g. AV briefly holding the file open) would
        # otherwise print a red error and silently fall through as if the move had
        # succeeded -- reporting "Update installed" and returning $true while the
        # live script was never actually replaced. Confirmed empirically: this
        # was a real, reproducible bug, not a theoretical one -- caught by a
        # destructive-path test that locks the destination file during the move.
        Move-Item -LiteralPath $extractedScriptPath -Destination $ScriptPath -Force -ErrorAction Stop
        # Defense-in-depth, matching New-ManagerUpdateBackup's own post-copy
        # verification pattern: confirm the replacement actually landed before
        # declaring success, rather than trusting Move-Item's absence of an
        # exception alone.
        if (-not (Test-Path -LiteralPath $ScriptPath -PathType Leaf)) {
            throw "Update replacement did not complete: $ScriptPath not found after Move-Item."
        }
        $extractedScriptPath = $null

        Write-Host ""
        Write-Host "============================================" -ForegroundColor Cyan
        Write-Host "  Update installed: $(ConvertTo-ManagerDisplayVersionFromTag -VersionText $Release.TagName)" -ForegroundColor Green
        Write-Host "============================================" -ForegroundColor Cyan
        Write-Log "CheckForUpdates: update to $($Release.TagName) installed successfully. Backup: $backupPath"
        return $true
    } catch {
        Write-Host ""
        Write-Host "  ERROR: update failed -- $_" -ForegroundColor Red
        if ($backupPath) {
            Write-Host "  Backup created: Yes ($backupPath)" -ForegroundColor Yellow
        } else {
            Write-Host "  Backup created: No" -ForegroundColor Yellow
        }
        Write-Log "CheckForUpdates: update failed -- $_. Backup: $(if ($backupPath) { $backupPath } else { 'none' })"
        return $false
    } finally {
        if ($downloadedZipPath -and (Test-Path -LiteralPath $downloadedZipPath -PathType Leaf)) {
            Remove-Item -LiteralPath $downloadedZipPath -Force -ErrorAction SilentlyContinue
        }
        if ($extractedScriptPath -and (Test-Path -LiteralPath $extractedScriptPath -PathType Leaf)) {
            Remove-Item -LiteralPath $extractedScriptPath -Force -ErrorAction SilentlyContinue
        }
        if ($readOnlyCleared -and (Test-Path -LiteralPath $ScriptPath -PathType Leaf)) {
            try {
                Set-ItemProperty -LiteralPath $ScriptPath -Name IsReadOnly -Value $true -ErrorAction Stop
            } catch {
                Write-Host '  WARNING: TPM could not restore the original read-only protection on the manager script.' -ForegroundColor Red
                Write-Log 'CheckForUpdates: read-only attribute restoration failed.'
            }
        }
    }
}

# Compares $ScriptVersion against the latest GitHub release and, if a newer
# one exists, prints it and (unless -SkipConfirmationMessage) explains what
# updating will do before asking for explicit Y/N confirmation. Returns
# $true only if a new script was actually installed -- see
# Invoke-ManagerUpdateInstall's comment for why this never calls exit itself.
function Invoke-CheckForUpdates {
    param([Parameter(Mandatory)][string]$ScriptPath)

    Write-Host ""
    Write-Host "  Checking for updates..." -ForegroundColor DarkGray
    Write-Log "CheckForUpdates: checking current v$ScriptVersion against latest GitHub release."

    try {
        $localVersion = ConvertTo-ManagerComparableVersion -VersionText $ScriptVersion
    } catch {
        Write-Host "  ERROR: could not parse the current version ($ScriptVersion) -- $_" -ForegroundColor Red
        Write-Log "CheckForUpdates: could not parse current version -- $_"
        return $false
    }

    $release = Get-ManagerUpdateRelease
    if (-not $release) {
        Write-Host "  Could not reach GitHub to check for updates. Check your connection and try again." -ForegroundColor Yellow
        Write-Log "CheckForUpdates: release check failed or found no usable asset."
        return $false
    }

    try {
        $latestVersion = ConvertTo-ManagerComparableVersion -VersionText $release.TagName
    } catch {
        Write-Host "  ERROR: could not parse the latest release version ($($release.TagName)) -- $_" -ForegroundColor Red
        Write-Log "CheckForUpdates: could not parse latest release version -- $_"
        return $false
    }

    $latestDisplay = ConvertTo-ManagerDisplayVersionFromTag -VersionText $release.TagName

    Write-Host ""
    Write-Host ("  Current version : {0}" -f (Get-ManagerDisplayVersion)) -ForegroundColor Cyan
    Write-Host ("  Latest version  : {0}" -f $latestDisplay) -ForegroundColor Cyan

    if ($latestVersion -le $localVersion) {
        Write-Host ""
        Write-Host "  You're already running the latest version. No update needed." -ForegroundColor Green
        Write-Log "CheckForUpdates: already current (v$ScriptVersion)."
        return $false
    }

    Write-Host ""
    Write-Host "  An update is available: $(Get-ManagerDisplayVersion) -> $latestDisplay" -ForegroundColor Yellow
    Write-Host ""
    Write-Host "  Updating will:" -ForegroundColor Cyan
    Write-Host "    1) Back up the current script to UpdateBackups\<timestamp>\"
    Write-Host "    2) Download the update ($($release.AssetName))"
    Write-Host "    3) Validate the downloaded script before installing it"
    Write-Host "    4) Replace TeknoParrot-Manager.ps1 with the new version"
    Write-Host "    5) Require you to restart TeknoParrot Manager afterward --"
    Write-Host "       this session will exit rather than keep running the old code."
    Write-Host ""

    $ans = (Read-HostSafe "  Update to $latestDisplay now? (Y/N)").ToUpper()
    if ($ans -ne "Y") {
        Write-Host "  Skipped -- no changes made." -ForegroundColor DarkGray
        Write-Log "CheckForUpdates: user declined the update to $($release.TagName)."
        return $false
    }

    return Invoke-ManagerUpdateInstall -ScriptPath $ScriptPath -Release $release
}

# Quiet, opt-in (CheckForUpdatesOnStartup, default true) startup update
# check. Uses a single short-timeout attempt (Get-ManagerUpdateRelease
# -MaxAttempts 1 -TimeoutSec 5) so an unreachable GitHub cannot noticeably
# delay launching the script -- unlike the menu option, nobody explicitly
# asked for this check, so it must not be allowed to hang. Never prompts,
# logs, or writes anything when already current. When a newer release
# exists, shows current/latest/a one-line release summary and offers
# Y (update now) / N (remind me later) / V (view full release notes, then
# re-prompt). Shares Invoke-ManagerUpdateInstall with the menu option for
# the actual backup-first install; never calls exit itself for the same
# testability reason documented there -- the caller (top-level script code)
# decides whether to exit after a successful install.
function Invoke-StartupUpdateCheck {
    param([Parameter(Mandatory)][string]$ScriptPath)

    try {
        $localVersion = ConvertTo-ManagerComparableVersion -VersionText $ScriptVersion
    } catch {
        Write-Log "StartupUpdateCheck: could not parse current version -- $_"
        return $false
    }

    $release = Get-ManagerUpdateRelease -MaxAttempts 1 -TimeoutSec 5
    if (-not $release) {
        Write-Log "StartupUpdateCheck: release check failed, found no usable asset, or GitHub was unreachable -- continuing to menu."
        return $false
    }

    try {
        $latestVersion = ConvertTo-ManagerComparableVersion -VersionText $release.TagName
    } catch {
        Write-Log "StartupUpdateCheck: could not parse latest release version -- $_"
        return $false
    }

    if ($latestVersion -le $localVersion) {
        Write-Log "StartupUpdateCheck: already current (v$ScriptVersion)."
        return $false
    }

    $latestDisplay = ConvertTo-ManagerDisplayVersionFromTag -VersionText $release.TagName

    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " Update Available" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host ("  Current version : {0}" -f (Get-ManagerDisplayVersion)) -ForegroundColor Cyan
    Write-Host ("  Latest version  : {0}" -f $latestDisplay) -ForegroundColor Cyan
    if ($release.Name) { Write-Host ("  Release         : {0}" -f $release.Name) -ForegroundColor Cyan }
    $summary = Get-ManagerUpdateReleaseSummary -Body $release.Body
    if ($summary) {
        Write-Host ""
        Write-Host "  $summary" -ForegroundColor DarkGray
    }
    Write-Log "StartupUpdateCheck: update available (v$ScriptVersion -> $($release.TagName))."

    while ($true) {
        $ans = (Read-HostSafe "  Update now, remind me later, or view release notes? (Y/N/V)").ToUpper()

        if ($ans -eq "V") {
            Write-Host ""
            if ($release.Body) {
                Write-Host $release.Body -ForegroundColor DarkGray
            } else {
                Write-Host "  No release notes were provided for this release." -ForegroundColor DarkGray
            }
            Write-Host ""
            continue
        }

        if ($ans -eq "Y") {
            Write-Host ""
            Write-Host "  Updating will:" -ForegroundColor Cyan
            Write-Host "    1) Back up the current script to UpdateBackups\<timestamp>\"
            Write-Host "    2) Download the update ($($release.AssetName))"
            Write-Host "    3) Validate the downloaded script before installing it"
            Write-Host "    4) Replace TeknoParrot-Manager.ps1 with the new version"
            Write-Host "    5) Require you to restart TeknoParrot Manager afterward --"
            Write-Host "       this session will exit rather than keep running the old code."
            Write-Host ""
            $confirm = (Read-HostSafe "  Proceed? (Y/N)").ToUpper()
            if ($confirm -ne "Y") {
                Write-Host "  Skipped -- no changes made." -ForegroundColor DarkGray
                Write-Log "StartupUpdateCheck: user backed out of the update to $($release.TagName)."
                return $false
            }
            return Invoke-ManagerUpdateInstall -ScriptPath $ScriptPath -Release $release
        }

        # N, or anything else -- remind me later.
        Write-Host "  Continuing -- you can check again any time from menu option 13." -ForegroundColor DarkGray
        Write-Log "StartupUpdateCheck: user chose to be reminded later."
        return $false
    }
}

# Scans the install folder for executables and registers matching TeknoParrot
# profiles by setting <GamePath> in a copy written to UserProfiles. Three passes:
#   1 -- exe filename -> profile index (built from <ExecutableName> in GameProfile XMLs)
#   2 -- dat lookup for folders whose exe name is not in any profile
#   3 -- Dice-match normalised folder name against profile code names, resolving
#        games with empty <ExecutableName> (BladeStrangers, LuigisMansion, etc.)
# Existing UserProfiles are never overwritten.
# A profile code can only be claimed once per run (TeknoParrot allows exactly
# one GamePath per profile). Folders that resolve to a code already claimed by
# an earlier folder (e.g. several ROM revisions sharing one generic exe name
# and one profile, like multiple Virtua Fighter 5 Lindbergh dumps) are added to
function Register-Games {
    param([string]$userProfilesDir, [string]$installFolder, [hashtable]$profileIndex,
          [string]$gameProfilesDir = '', [hashtable]$datIndex = $null,
          [System.Collections.Generic.HashSet[string]]$profileSet = $null,
          [bool]$DryRun = $false,
          [string]$tpRootDir = '', [hashtable]$subFolderMap = $null,
          [string[]]$GameFolders = $null)

    if ($null -eq $GameFolders -or $GameFolders.Count -eq 0) {
        $exeFiles = @(Get-GameFiles $installFolder)
    } else {
        $installRoot = [System.IO.Path]::GetFullPath($installFolder).TrimEnd('\')
        $scanRoots = New-Object System.Collections.Generic.List[string]
        foreach ($folder in $GameFolders) {
            $child = [System.IO.Path]::GetFullPath((Join-Path $installRoot ([string]$folder))).TrimEnd('\')
            if (-not (Test-PathInside $child $installRoot) -or -not (Test-Path -LiteralPath $child -PathType Container)) {
                Write-Log "Register-Games: rejected unsafe or missing filtered game folder '$folder'."
                continue
            }
            [void]$scanRoots.Add($child)
        }
        $exeFiles = @($scanRoots | ForEach-Object { Get-GameFiles $_ })
    }
    $registered     = New-Object System.Collections.ArrayList
    $already        = New-Object System.Collections.ArrayList
    $ambiguous      = New-Object System.Collections.ArrayList
    $seenCodes      = @{}

    $codeClaimedBy  = @{}   # profile code -> folder name that already claimed it this run
    # Snapshot of codes that already had a UserProfile BEFORE this run started.
    # Needed to tell apart two genuinely different situations that both make
    # $seenCodes.ContainsKey($code) true: (1) the code was already registered
    # (by TeknoParrotUI or an earlier run) before this run touched anything --
    # not a conflict, just report "Already"; vs (2) two folders THIS run both
    # resolved to the SAME unclaimed code -- a real conflict between two
    # fresh candidates. Without this distinction, a folder whose own exe
    # happens to share a name with dozens of other titles (e.g. NESiCAxLive's
    # game.exe) gets falsely flagged as "duplicate" every time an unrelated
    # already-registered sibling from that same shared-exe pool is scanned
    # first and incidentally marks this folder's own code as "seen".
    $preExistingCodes = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    Get-ChildItem -LiteralPath $userProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Directory.Name -ne "FullBackup" } |
        ForEach-Object { [void]$preExistingCodes.Add($_.BaseName) }
    # Maps an exe's exact full path to the profile code already pointing at it
    # (if any). This is a stronger, name-independent signal than fuzzy-matching
    # the folder name against candidate profile codes: it catches a folder
    # whose correct profile is already configured even when that profile's own
    # code never scores high enough against the folder name to be picked
    # automatically (e.g. a generic/typo'd code like "Primevil" for "Primeval
    # Hunt"), and even when the correct profile was never a fuzzy-match
    # candidate at all because its own ExecutableName differs from this exe's
    # filename (e.g. "Nosferatu" not appearing among the "main.exe" candidates
    # for Nosferatu Lilinor). See issue #9.
    $gamePathIndex = [System.Collections.Generic.Dictionary[string,string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    Get-ChildItem -LiteralPath $userProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Directory.Name -ne "FullBackup" } |
        ForEach-Object {
            try {
                $existingDoc = Read-Xml $_.FullName
                $gpNode = $existingDoc.GameProfile.SelectSingleNode("GamePath")
                if ($null -ne $gpNode -and $gpNode.InnerText) {
                    # Trim() first: a GamePath written by a tool other than this
                    # script's own Save-Xml could carry incidental leading/trailing
                    # whitespace, which would otherwise make this key never match
                    # $exe.FullName (a clean FileInfo path) even when they refer to
                    # the same file. See issue #9.
                    $gamePathIndex[$gpNode.InnerText.Trim().TrimEnd('\')] = $_.BaseName
                }
            } catch {
                Write-Log ("Register-Games: WARNING -- could not parse existing UserProfile '$($_.BaseName)' while building GamePath index: $_")
            }
        }
    $installBase    = $installFolder.TrimEnd('\')
    $matchedFolders = @{}   # folders that matched at least one profile key
    $allExeFolders  = @{}   # folders containing any recognisable executable
    $_regTotal = $exeFiles.Count
    $_regI     = 0

    foreach ($exe in $exeFiles) {
        $_regI++
        if ($_regTotal -gt 0) {
            Write-Progress -Activity "Scanning game library" `
                           -Status ("({0}/{1}) {2}" -f $_regI, $_regTotal, $exe.Directory.Name) `
                           -PercentComplete ([int]($_regI / $_regTotal * 100))
        }
        $relPath    = $exe.FullName.Substring($installBase.Length).TrimStart('\')
        $folderName = ($relPath -split '\\')[0]
        $folderKey  = $folderName -replace '\.(teknoparrot|parrot|game)$', ''   # strip suffix for matching/tracking
        $allExeFolders[$folderKey] = $folderName   # store original name (with any suffix) for path resolution

        $key = $exe.Name.ToLower()
        if (-not $profileIndex.ContainsKey($key)) { continue }

        $matchList = $profileIndex[$key]

        # Same executable name maps to more than one profile.
        # Attempt folder-name fuzzy matching before giving up.
        if ($matchList.Count -gt 1) {
            # $matchedFolders is set per conclusive outcome below, NOT
            # unconditionally just because this exe's filename happened to
            # appear in $profileIndex. A folder can contain more than one
            # exe-like file (an installer, an uninstaller, a redistributable
            # stub, the real launcher); if an unrelated one of those happens
            # to collide with some other profile's <ExecutableName>, marking
            # the whole folder "matched" on that collision alone would
            # permanently block Pass 2/3 below from ever getting a chance to
            # resolve the folder's REAL exe via the dat -- even though this
            # specific exe was never actually identified. $resolved tracks
            # whether THIS exe's own outcome was conclusive; it defaults true
            # and is only flipped false at the genuinely-unresolved "shared"
            # ambiguous outcomes further down. See issue #10.
            $resolved = $true

            # Exact-path check first, ahead of any fuzzy-name matching: if an
            # existing UserProfile already points its GamePath at this exact
            # exe, this folder is fully handled regardless of whether that
            # profile's own code name fuzzy-matches the folder name at all, or
            # was even among $matchList's candidates. See issue #9.
            if ($gamePathIndex.ContainsKey($exe.FullName)) {
                $existingCode = $gamePathIndex[$exe.FullName]
                if (-not $seenCodes.ContainsKey($existingCode)) {
                    if ($already -notcontains $existingCode) { [void]$already.Add($existingCode) }
                    $seenCodes[$existingCode] = $true
                    $codeClaimedBy[$existingCode] = "(already registered in TeknoParrotUI)"
                    Backfill-SecondaryExecutablePath (Join-Path $userProfilesDir ($existingCode + ".xml")) $DryRun
                }
                $matchedFolders[$folderKey] = $true
                continue
            }

            # $folderKey has the RetroBat suffix stripped, ready to normalise.
            # The $RawThrillsPathLimits alias fallback (e.g. NicktoonsNitro -> NTN,
            # for a folder renamed to this script's own PATH TOO LONG suggestion --
            # see issue #13) is handled inside Resolve-BestFuzzyMatch.
            $normFolder  = Get-NormalizedGameKey $folderKey

            $fuzzyResult    = Resolve-BestFuzzyMatch -NormFolder $normFolder -MatchList $matchList -RawThrillsAliases $RawThrillsPathLimits
            $bestFuzzy      = $fuzzyResult.Best
            $bestFuzzyScore = $fuzzyResult.BestScore

            if ($fuzzyResult.IsConfidentMatch) {
                # High-confidence fuzzy match: register automatically.
                $code = $bestFuzzy.Code
                if ($seenCodes.ContainsKey($code)) {
                    if ($preExistingCodes.Contains($code)) {
                        # Already registered before this run started (TeknoParrotUI
                        # or an earlier run) -- not a conflict from this run's
                        # perspective, just confirm it's set and move on. (Guard
                        # against a duplicate "Already" entry: an earlier folder's
                        # alreadyReg scan may have already recorded this same code.)
                        if ($already -notcontains $code) { [void]$already.Add($code) }
                    } else {
                        # Another folder already claimed this profile code THIS run --
                        # TeknoParrot can only point one profile at one executable, so
                        # this is a real conflict, not a silent duplicate to drop.
                        [void]$ambiguous.Add([pscustomobject]@{
                            Exe        = $exe.FullName
                            Codes      = $code
                            BestGuess  = $code
                            BestScore  = 1.0
                            Reason     = "duplicate"
                            ClaimedBy  = $codeClaimedBy[$code]
                        })
                    }
                    continue
                }
                $userProfile = Join-Path $userProfilesDir ($code + ".xml")
                if (Test-Path -LiteralPath $userProfile) {
                    [void]$already.Add($code); $seenCodes[$code] = $true; $codeClaimedBy[$code] = $folderName
                    Backfill-SecondaryExecutablePath $userProfile $DryRun
                } else {
                    # Mark seen before the file operation so that if Save throws,
                    # a second exe match for the same code doesn't cause a duplicate
                    # attempt (and duplicate error output) within the same run.
                    $seenCodes[$code] = $true
                    $codeClaimedBy[$code] = $folderName
                    try {
                        $tpl = Read-Xml $bestFuzzy.TemplatePath
                        $gp  = $tpl.GameProfile.SelectSingleNode("GamePath")
                        if ($null -eq $gp) {
                            $gp = $tpl.CreateElement("GamePath")
                            [void]$tpl.GameProfile.PrependChild($gp)
                        }
                        $gp.InnerText = $exe.FullName
                        [void](Set-SecondaryExecutablePath $tpl $exe.FullName)
                        Save-XmlMaybe $tpl $userProfile $DryRun
                        [void]$registered.Add([pscustomobject]@{
                            Code        = $code
                            GamePath    = $exe.FullName
                            FuzzyScore  = [Math]::Round($bestFuzzyScore, 2)
                            FuzzyFolder = $folderName
                        })
                        Write-Log "Registered (fuzzy $([Math]::Round($bestFuzzyScore,2))) $code -> $($exe.FullName)  [folder: $folderName]"
                    } catch {
                        Write-Host "  FAILED to register $code : $_" -ForegroundColor Red
                        Write-Log "Register (fuzzy) FAILED $code -- $_"
                    }
                }
            } else {
                # Bug fix: check if any candidate is already registered (UserProfile
                # exists) before flagging as ACTION REQUIRED. A game registered via
                # TeknoParrotUI would have a .xml file even though the fuzzy score is
                # below the auto-register threshold.
                $alreadyReg = @($matchList | Where-Object {
                    Test-Path -LiteralPath (Join-Path $userProfilesDir ($_.Code + ".xml"))
                })
                foreach ($ar in $alreadyReg) {
                    if (-not $seenCodes.ContainsKey($ar.Code)) {
                        if ($already -notcontains $ar.Code) { [void]$already.Add($ar.Code) }
                        $seenCodes[$ar.Code] = $true
                        $codeClaimedBy[$ar.Code] = "(already registered in TeknoParrotUI)"
                        Backfill-SecondaryExecutablePath (Join-Path $userProfilesDir ($ar.Code + ".xml")) $DryRun
                    }
                }

                # A sibling sharing this exe name being already registered does NOT
                # mean THIS folder's own game is handled -- e.g. H2Overdrive already
                # having a profile says nothing about whether X-Games Snowboarder
                # (a different game sharing the same generic sdaemon.exe loader)
                # does. Only skip this folder if its OWN best-guess candidate
                # specifically is among the already-registered set; otherwise it
                # still needs the dat lookup / manual-registration fallback below,
                # even though some unrelated sibling is already fine.
                $ownAlreadyRegistered = ($null -ne $bestFuzzy) -and
                    (@($alreadyReg | Where-Object { $_.Code -eq $bestFuzzy.Code }).Count -gt 0)

                if (-not $ownAlreadyRegistered) {
                    # Dat-based disambiguation: look up the normalised folder name in the
                    # dat index. The dat's <GameProfile> is authoritative, so if a match is
                    # found we use it directly instead of falling through to ambiguous.
                    $datEntry = if ($datIndex.Count -gt 0) { $datIndex[$normFolder] } else { $null }
                    if ($null -ne $datEntry) {
                        $datCode = $datEntry.ProfileCode
                        # Profile codes are purely alphanumeric; reject anything else to
                        # prevent path traversal via a crafted dat file.
                        if ($datCode -match '^[\w]+$') {
                            if ($gameProfilesDir) {
                                $datCode = Resolve-ProfileCode $datCode $gameProfilesDir $profileSet
                            }
                            $userProfile = Join-Path $userProfilesDir ($datCode + ".xml")
                            if ($seenCodes.ContainsKey($datCode)) {
                                if ($preExistingCodes.Contains($datCode)) {
                                    if ($already -notcontains $datCode) { [void]$already.Add($datCode) }
                                } else {
                                    [void]$ambiguous.Add([pscustomobject]@{
                                        Exe        = $exe.FullName
                                        Codes      = $datCode
                                        BestGuess  = $datCode
                                        BestScore  = 1.0
                                        Reason     = "duplicate"
                                        ClaimedBy  = $codeClaimedBy[$datCode]
                                    })
                                }
                            } else {
                                $seenCodes[$datCode] = $true
                                $codeClaimedBy[$datCode] = $folderName
                                if (Test-Path -LiteralPath $userProfile) {
                                    [void]$already.Add($datCode)
                                    Backfill-SecondaryExecutablePath $userProfile $DryRun
                                } else {
                                    $templatePath = Join-Path $gameProfilesDir ($datCode + ".xml")
                                    $exeToUse     = $exe.FullName
                                    if (-not [string]::IsNullOrWhiteSpace($datEntry.Executable)) {
                                        $relExe     = $datEntry.Executable.TrimStart('\', '/')
                                        # Guard: a bare backslash/slash normalises to an empty
                                        # string; using it as a path component would match the
                                        # game folder itself rather than an executable.
                                        if ($relExe) {
                                            $folderFull = Join-Path $installBase $folderName
                                            $datExe     = Join-Path $folderFull $relExe
                                            # Security: dat-supplied path must stay inside the game folder.
                                            if (Test-PathInside $datExe $folderFull) {
                                                if     (Test-Path -LiteralPath $datExe -PathType Leaf) { $exeToUse = $datExe }
                                                elseif (Test-Path -LiteralPath ($datExe + ".exe")) { $exeToUse = $datExe + ".exe" }
                                                elseif (Test-Path -LiteralPath ($datExe + ".elf")) { $exeToUse = $datExe + ".elf" }
                                            }
                                        }
                                    }
                                    if (Test-Path -LiteralPath $templatePath) {
                                        try {
                                            $tpl = Read-Xml $templatePath
                                            $gp  = $tpl.GameProfile.SelectSingleNode("GamePath")
                                            if ($null -eq $gp) {
                                                $gp = $tpl.CreateElement("GamePath")
                                                [void]$tpl.GameProfile.PrependChild($gp)
                                            }
                                            $gp.InnerText = $exeToUse
                                            [void](Set-SecondaryExecutablePath $tpl $exeToUse)
                                            Save-XmlMaybe $tpl $userProfile $DryRun
                                            [void]$registered.Add([pscustomobject]@{
                                                Code     = $datCode
                                                GamePath = $exeToUse
                                                DatMatch = $true
                                            })
                                            Write-Log "Registered (dat) $datCode -> $exeToUse"
                                        } catch {
                                            Write-Host "  FAILED to register $datCode : $_" -ForegroundColor Red
                                            Write-Log "Register (dat) FAILED $datCode -- $_"
                                        }
                                    } else {
                                        Write-Log ("DatIndex: template '{0}.xml' not in GameProfiles -- flagging as ambiguous." -f $datCode)
                                        [void]$ambiguous.Add([pscustomobject]@{
                                            Exe       = $exe.FullName
                                            Codes     = ($matchList | ForEach-Object { $_.Code }) -join ", "
                                            BestGuess = $datCode
                                            BestScore = 1.0
                                            Reason    = "shared"
                                        })
                                        $resolved = $false
                                    }
                                }
                            }
                        } else {
                            Write-Log ("DatIndex: invalid ProfileCode '{0}' -- skipped." -f $datCode)
                            [void]$ambiguous.Add([pscustomobject]@{
                                Exe       = $exe.FullName
                                Codes     = ($matchList | ForEach-Object { $_.Code }) -join ", "
                                BestGuess = if ($null -ne $bestFuzzy) { $bestFuzzy.Code } else { $null }
                                BestScore = [Math]::Round($bestFuzzyScore, 2)
                                Reason    = "shared"
                            })
                            $resolved = $false
                        }
                    } else {
                        # Below threshold with no dat entry: flag for manual registration.
                        [void]$ambiguous.Add([pscustomobject]@{
                            Exe       = $exe.FullName
                            Codes     = ($matchList | ForEach-Object { $_.Code }) -join ", "
                            BestGuess = if ($null -ne $bestFuzzy) { $bestFuzzy.Code } else { $null }
                            BestScore = [Math]::Round($bestFuzzyScore, 2)
                            Reason    = "shared"
                        })
                        $resolved = $false
                    }
                }
            }
            # Only mark the folder as accounted for if this exe's own outcome
            # was conclusive (registered/already/duplicate-conflict) -- not
            # when it fell through to a genuinely-unresolved "shared"
            # ambiguous entry. An unresolved exe leaves the folder eligible
            # for Pass 2/3 below, in case a DIFFERENT exe in this same folder
            # (or the folder's name itself) resolves cleanly via the dat or a
            # profile-code fuzzy match. See issue #10.
            if ($resolved) { $matchedFolders[$folderKey] = $true }
            continue
        }

        # A single candidate for this exe name is always a confident,
        # unambiguous identification (unlike the $matchList.Count -gt 1
        # branch above, this never falls through to an unresolved "shared"
        # outcome) -- safe to mark the folder accounted for unconditionally.
        $matchedFolders[$folderKey] = $true

        $match = $matchList[0]
        $code  = $match.Code
        if ($seenCodes.ContainsKey($code)) {
            if ($preExistingCodes.Contains($code)) {
                if ($already -notcontains $code) { [void]$already.Add($code) }
            } else {
                # Another folder already claimed this profile code THIS run. Most
                # often this is multiple ROM revisions of the same game sharing one
                # generic exe name and one TeknoParrot profile (e.g. several Virtua
                # Fighter 5 Lindbergh revisions). TeknoParrot can only point that
                # profile at one executable, so surface it instead of dropping it.
                [void]$ambiguous.Add([pscustomobject]@{
                    Exe        = $exe.FullName
                    Codes      = $code
                    BestGuess  = $code
                    BestScore  = 1.0
                    Reason     = "duplicate"
                    ClaimedBy  = $codeClaimedBy[$code]
                })
            }
            continue
        }

        $userProfile = Join-Path $userProfilesDir ($code + ".xml")
        if (Test-Path -LiteralPath $userProfile) {
            [void]$already.Add($code)
            $seenCodes[$code] = $true
            $codeClaimedBy[$code] = $folderName
            Backfill-SecondaryExecutablePath $userProfile $DryRun
            continue
        }

        # Mark seen before the file operation for the same reason as the fuzzy
        # path: prevents a duplicate attempt if a second matching exe is found.
        $seenCodes[$code] = $true
        $codeClaimedBy[$code] = $folderName
        try {
            $tpl = Read-Xml $match.TemplatePath
            # SelectSingleNode returns the node if it exists (even when empty)
            # and $null only when truly absent. This avoids creating a second
            # GamePath element, which would make the value assignment ambiguous.
            $gp = $tpl.GameProfile.SelectSingleNode("GamePath")
            if ($null -eq $gp) {
                $gp = $tpl.CreateElement("GamePath")
                [void]$tpl.GameProfile.PrependChild($gp)
            }
            $gp.InnerText = $exe.FullName
            [void](Set-SecondaryExecutablePath $tpl $exe.FullName)
            Save-XmlMaybe $tpl $userProfile $DryRun
            [void]$registered.Add([pscustomobject]@{ Code = $code; GamePath = $exe.FullName })
            Write-Log "Registered $code -> $($exe.FullName)"
        } catch {
            Write-Host "  FAILED to register $code : $_" -ForegroundColor Red
            Write-Log "Register FAILED $code -- $_"
        }
    }
    Write-Progress -Activity "Scanning game library" -Completed

    # Second pass: folders that had recognisable executables but none of them were
    # in $profileIndex (no exe->profile mapping). These are typically games whose
    # executable name is not listed in any GameProfile XML -- common with pcsx2x6,
    # ELF-based Lindbergh games, or custom loaders. Try the dat index: first an
    # exact normalised-name lookup, then a fuzzy scan of all dat keys.
    if ($datIndex.Count -gt 0 -and $gameProfilesDir) {
        foreach ($folderKey in @($allExeFolders.Keys | Where-Object { -not $matchedFolders.ContainsKey($_) })) {
            $origName   = $allExeFolders[$folderKey]
            $normFolder = Get-NormalizedGameKey $folderKey
            $datEntry   = $datIndex[$normFolder]
            $datScore   = 1.0

            # Fuzzy dat scan when no exact name match (handles slightly misnamed folders)
            if ($null -eq $datEntry) {
                $bestScore = 0.0
                $bestKey   = $null
                foreach ($dk in $datIndex.Keys) {
                    $score = Get-DiceSimilarity $normFolder $dk
                    if ($score -gt $bestScore) { $bestScore = $score; $bestKey = $dk }
                }
                if ($bestScore -ge $FuzzyAutoThreshold -and $null -ne $bestKey) {
                    # Issue #84: reject a fuzzy dat-name candidate that introduces
                    # extra meaningful title words the folder doesn't have -- e.g.
                    # a "Zoids Infinity" folder must not silently register against
                    # "Zoids Infinity EX Plus" just because the bigram score alone
                    # clears $FuzzyAutoThreshold. A hard block (folder stays
                    # unmatched, same as "no dat entry found"), not a score
                    # penalty or a higher threshold -- see #84's design.
                    $candidateName   = $datIndex[$bestKey].OriginalName
                    $candidateTokens = Get-MeaningfulTitleTokens $candidateName
                    $folderTokens    = Get-MeaningfulTitleTokens $origName
                    $extraTokens     = @($candidateTokens | Where-Object { -not $folderTokens.Contains($_) })
                    if ($extraTokens.Count -gt 0) {
                        Write-Log ("DatIndex (pass2): rejected fuzzy candidate '{0}' for folder '{1}' -- extra title token(s): {2} (score {3:F2})" -f $candidateName, $origName, ($extraTokens -join ', '), $bestScore)
                    } else {
                        $datEntry = $datIndex[$bestKey]
                        $datScore = $bestScore
                    }
                }
            }

            if ($null -eq $datEntry) { continue }

            $datCode = $datEntry.ProfileCode
            if ($datCode -notmatch '^[\w]+$') {
                Write-Log ("DatIndex (pass2): invalid ProfileCode '{0}' -- skipped folder {1}" -f $datCode, $folderKey)
                continue
            }
            if ($gameProfilesDir) {
                $datCode = Resolve-ProfileCode $datCode $gameProfilesDir $profileSet
            }

            $matchedFolders[$folderKey] = $true   # prevents folder appearing in $unmatched

            if ($seenCodes.ContainsKey($datCode)) {
                if ($preExistingCodes.Contains($datCode)) {
                    if ($already -notcontains $datCode) { [void]$already.Add($datCode) }
                } else {
                    $dupFolderFull = Join-Path $installBase $origName
                    $dupExe = @($exeFiles | Where-Object {
                        $_.FullName.Length -gt $dupFolderFull.Length -and
                        $_.FullName.StartsWith($dupFolderFull + '\')
                    })[0]
                    [void]$ambiguous.Add([pscustomobject]@{
                        Exe        = if ($dupExe) { $dupExe.FullName } else { $dupFolderFull }
                        Codes      = $datCode
                        BestGuess  = $datCode
                        BestScore  = 1.0
                        Reason     = "duplicate"
                        ClaimedBy  = $codeClaimedBy[$datCode]
                    })
                }
                continue
            }
            $seenCodes[$datCode] = $true
            $codeClaimedBy[$datCode] = $origName

            $userProfile = Join-Path $userProfilesDir ($datCode + ".xml")
            if (Test-Path -LiteralPath $userProfile) {
                [void]$already.Add($datCode)
                Backfill-SecondaryExecutablePath $userProfile $DryRun
                continue
            }

            $templatePath = Join-Path $gameProfilesDir ($datCode + ".xml")
            if (-not (Test-Path -LiteralPath $templatePath)) {
                Write-Log ("DatIndex (pass2): no GameProfiles template for '{0}' -- skipping {1}" -f $datCode, $folderKey)
                continue
            }

            # Resolve the exe: dat's Executable path first, then any file in the folder.
            $folderFull = Join-Path $installBase $origName
            $exeToUse   = $null
            if (-not [string]::IsNullOrWhiteSpace($datEntry.Executable)) {
                $relExe = $datEntry.Executable.TrimStart('\', '/')
                if ($relExe) {
                    $datExe = Join-Path $folderFull $relExe
                    if (Test-PathInside $datExe $folderFull) {
                        if     (Test-Path -LiteralPath $datExe              -PathType Leaf) { $exeToUse = $datExe }
                        elseif (Test-Path -LiteralPath ($datExe + ".exe") -PathType Leaf) { $exeToUse = $datExe + ".exe" }
                        elseif (Test-Path -LiteralPath ($datExe + ".elf") -PathType Leaf) { $exeToUse = $datExe + ".elf" }
                    }
                }
            }
            if (-not $exeToUse) {
                # Fallback: pick the first matching file already found for this folder
                $first = @($exeFiles | Where-Object {
                    $_.FullName.Length -gt $folderFull.Length -and
                    $_.FullName.StartsWith($folderFull + '\')
                })[0]
                if ($first) { $exeToUse = $first.FullName }
            }
            if (-not $exeToUse) {
                Write-Log ("DatIndex (pass2): no exe found for '{0}' in folder {1}" -f $datCode, $folderKey)
                continue
            }

            try {
                $tpl = Read-Xml $templatePath
                $gp  = $tpl.GameProfile.SelectSingleNode("GamePath")
                if ($null -eq $gp) {
                    $gp = $tpl.CreateElement("GamePath")
                    [void]$tpl.GameProfile.PrependChild($gp)
                }
                $gp.InnerText = $exeToUse
                [void](Set-SecondaryExecutablePath $tpl $exeToUse)
                Save-XmlMaybe $tpl $userProfile $DryRun
                $label = if ($datScore -lt 1.0) { "dat/fuzzy $([Math]::Round($datScore,2))" } else { "dat/exact" }
                [void]$registered.Add([pscustomobject]@{
                    Code        = $datCode
                    GamePath    = $exeToUse
                    DatMatch    = $true
                    FuzzyScore  = if ($datScore -lt 1.0) { [Math]::Round($datScore, 2) } else { $null }
                    FuzzyFolder = if ($datScore -lt 1.0) { $origName } else { $null }
                })
                Write-Log "Registered ($label) $datCode -> $exeToUse"
            } catch {
                Write-Host "  FAILED to register $datCode : $_" -ForegroundColor Red
                Write-Log "Register (dat pass2) FAILED $datCode -- $_"
            }
        }
    }

    # Third pass: folders still unmatched -- Dice-compare normalised folder name
    # against normalised profile code names. Targets games whose GameProfile has
    # an empty <ExecutableName> (BladeStrangers, LuigisMansion, PokkenTournament,
    # etc.) that never entered $profileIndex and have no dat entry.
    if ($gameProfilesDir -and $profileSet -and $profileSet.Count -gt 0) {
        $normCodeList = @(foreach ($code in $profileSet) {
            $n = Get-NormalizedGameKey $code
            if ($n) { [pscustomobject]@{ Code = $code; Norm = $n } }
        })

        foreach ($folderKey in @($allExeFolders.Keys | Where-Object { -not $matchedFolders.ContainsKey($_) })) {
            $origName   = $allExeFolders[$folderKey]
            $normFolder = Get-NormalizedGameKey $folderKey
            if (-not $normFolder) { continue }

            $bestScore = 0.0
            $bestCode  = $null
            foreach ($nc in $normCodeList) {
                $score = Get-DiceSimilarity $normFolder $nc.Norm
                if ($score -gt $bestScore) { $bestScore = $score; $bestCode = $nc.Code }
            }
            if ($bestScore -lt $FuzzyAutoThreshold -or -not $bestCode) { continue }

            $matchedFolders[$folderKey] = $true

            if ($seenCodes.ContainsKey($bestCode)) {
                if ($preExistingCodes.Contains($bestCode)) {
                    if ($already -notcontains $bestCode) { [void]$already.Add($bestCode) }
                } else {
                    $dupFolderFull = Join-Path $installBase $origName
                    $dupExe = @($exeFiles | Where-Object {
                        $_.FullName.Length -gt $dupFolderFull.Length -and
                        $_.FullName.StartsWith($dupFolderFull + '\')
                    })[0]
                    [void]$ambiguous.Add([pscustomobject]@{
                        Exe        = if ($dupExe) { $dupExe.FullName } else { $dupFolderFull }
                        Codes      = $bestCode
                        BestGuess  = $bestCode
                        BestScore  = 1.0
                        Reason     = "duplicate"
                        ClaimedBy  = $codeClaimedBy[$bestCode]
                    })
                }
                continue
            }
            $seenCodes[$bestCode] = $true
            $codeClaimedBy[$bestCode] = $origName

            $userProfile = Join-Path $userProfilesDir ($bestCode + ".xml")
            if (Test-Path -LiteralPath $userProfile) {
                [void]$already.Add($bestCode)
                Backfill-SecondaryExecutablePath $userProfile $DryRun
                continue
            }

            $templatePath = Join-Path $gameProfilesDir ($bestCode + ".xml")
            if (-not (Test-Path -LiteralPath $templatePath)) {
                Write-Log ("ProfileCode (pass3): no template for '{0}' -- skipping {1}" -f $bestCode, $folderKey)
                continue
            }

            # Prefer .exe > .elf > extension-less > .xbe > .dll when GameProfile
            # has no ExecutableName to guide us.
            $folderFull = Join-Path $installBase $origName
            $candidates = @($exeFiles | Where-Object {
                $_.FullName.Length -gt $folderFull.Length -and
                $_.FullName.StartsWith($folderFull + '\')
            })
            $exeToUse = $null
            foreach ($prio in @('.exe', '.elf', '', '.xbe', '.dll')) {
                $hit = @($candidates | Where-Object { $_.Extension.ToLower() -eq $prio })[0]
                if ($hit) { $exeToUse = $hit.FullName; break }
            }
            if (-not $exeToUse -and $candidates.Count -gt 0) { $exeToUse = $candidates[0].FullName }
            if (-not $exeToUse) {
                Write-Log ("ProfileCode (pass3): no exe found for '{0}' in folder {1}" -f $bestCode, $folderKey)
                continue
            }

            try {
                $tpl = Read-Xml $templatePath
                $gp  = $tpl.GameProfile.SelectSingleNode("GamePath")
                if ($null -eq $gp) {
                    $gp = $tpl.CreateElement("GamePath")
                    [void]$tpl.GameProfile.PrependChild($gp)
                }
                $gp.InnerText = $exeToUse
                [void](Set-SecondaryExecutablePath $tpl $exeToUse)
                Save-XmlMaybe $tpl $userProfile $DryRun
                [void]$registered.Add([pscustomobject]@{
                    Code        = $bestCode
                    GamePath    = $exeToUse
                    DatMatch    = $false
                    FuzzyScore  = [Math]::Round($bestScore, 2)
                    FuzzyFolder = $origName
                })
                Write-Log ("Registered (code/fuzzy {0}) {1} -> {2}" -f [Math]::Round($bestScore,2), $bestCode, $exeToUse)
            } catch {
                Write-Host "  FAILED to register $bestCode : $_" -ForegroundColor Red
                Write-Log "Register (pass3) FAILED $bestCode -- $_"
            }
        }
    }

    # A folder can contain more than one exe-like file -- e.g. a dedicated
    # launcher (already cleanly matched to its own profile elsewhere in this
    # loop) sitting alongside an unrelated generic/shared stub (which only
    # collided with OTHER profiles' ExecutableName and was reported above as
    # "shared"/ambiguous). $matchedFolders already tracks every folder that
    # got a conclusive match from ANY of its exes; $unmatched below already
    # filters against it, but $ambiguous never did, so a folder whose real
    # game was already correctly registered via one exe could still show up
    # in the "needs manual registration" report because of a second,
    # unrelated exe in the same folder. Drop any ambiguous entry whose
    # folder is in $matchedFolders by now -- the folder is accounted for
    # Pass 4: subFolderMap -- profile codes whose executable lives in a known
    # subfolder of the TeknoParrot root rather than in the staging folder.
    # Example: CrediarDolphin titles whose game files must live at
    # TeknoParrot\CrediarDolphin\User\Wii\. Configured in overrides.json:
    # { "subFolderMap": { "TatsunokoCap": "CrediarDolphin\\User\\Wii" } }
    if (($null -eq $GameFolders -or $GameFolders.Count -eq 0) -and
        $subFolderMap -and $subFolderMap.Count -gt 0 -and $gameProfilesDir -and
        $tpRootDir -and (Test-Path -LiteralPath $tpRootDir)) {
        foreach ($sfCode in @($subFolderMap.Keys)) {
            $sfCode = [string]$sfCode
            if ($sfCode -notmatch '^[\w]+$') {
                Write-Log "Register-Games: subFolderMap key '$sfCode' contains invalid characters -- skipped."
                continue
            }
            if ($preExistingCodes.Contains($sfCode) -or $seenCodes.ContainsKey($sfCode)) { continue }
            $sfSubPath = [string]$subFolderMap[$sfCode]
            $sfScanDir = Join-Path $tpRootDir $sfSubPath
            if (-not (Test-Path -LiteralPath $sfScanDir)) { continue }
            $sfTplPath = Join-Path $gameProfilesDir "$sfCode.xml"
            if (-not (Test-Path -LiteralPath $sfTplPath)) { continue }
            $sfExeName = Get-PrimaryExecutableName $sfTplPath
            if (-not $sfExeName) { continue }
            $sfExePath = Join-Path $sfScanDir $sfExeName
            if (-not (Test-Path -LiteralPath $sfExePath -PathType Leaf)) { continue }
            $sfUserProfile = Join-Path $userProfilesDir "$sfCode.xml"
            if (Test-Path -LiteralPath $sfUserProfile) {
                [void]$already.Add($sfCode)
                $seenCodes[$sfCode] = $true
                Backfill-SecondaryExecutablePath $sfUserProfile $DryRun
                continue
            }
            $seenCodes[$sfCode] = $true
            try {
                $sfTpl = Read-Xml $sfTplPath
                $sfGp  = $sfTpl.GameProfile.SelectSingleNode("GamePath")
                if ($null -eq $sfGp) {
                    $sfGp = $sfTpl.CreateElement("GamePath")
                    [void]$sfTpl.GameProfile.PrependChild($sfGp)
                }
                $sfGp.InnerText = $sfExePath
                [void](Set-SecondaryExecutablePath $sfTpl $sfExePath)
                Save-XmlMaybe $sfTpl $sfUserProfile $DryRun
                [void]$registered.Add([pscustomobject]@{ Code = $sfCode; GamePath = $sfExePath; SubFolderMatch = $true })
                Write-Log "Registered (subFolderMap) $sfCode -> $sfExePath"
            } catch {
                Write-Host "  FAILED to register $sfCode (subFolderMap) : $_" -ForegroundColor Red
                Write-Log "Register FAILED $sfCode (subFolderMap) -- $_"
            }
        }
    }

    # regardless of what this particular exe resolved to. See issue #9
    # (Nosferatu Lilinor: NLAM.exe cleanly registers the real profile, but a
    # generic "main" stub in the same folder collides with WMMT3/WMMT3DXP
    # and was being reported as still needing registration).
    $ambiguous = @($ambiguous | Where-Object {
        $rel        = if ($_.Exe.Length -gt $installBase.Length) { $_.Exe.Substring($installBase.Length).TrimStart('\') } else { $_.Exe }
        $folderName = ($rel -split '\\')[0]
        $folderKey  = $folderName -replace '\.(teknoparrot|parrot|game)$', ''
        -not $matchedFolders.ContainsKey($folderKey)
    })

    $unmatched = @($allExeFolders.Keys | Where-Object { -not $matchedFolders.ContainsKey($_) } | Sort-Object)
    return [pscustomobject]@{ Registered = $registered; Already = $already; Ambiguous = $ambiguous; Unmatched = $unmatched }
}

function Invoke-ManualRegistrationChoices {
    param(
        [Parameter(Mandatory)][hashtable]$ManualRegData,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [Parameter(Mandatory)][string]$GameProfilesDir,
        [Parameter(Mandatory)][string]$InstallFolder,
        [Parameter(Mandatory)]$Result,
        [bool]$DryRun = $false
    )

    foreach ($folderName in @($ManualRegData.Keys | Sort-Object)) {
        $info = $ManualRegData[$folderName]
        $candidates = @($info.Profiles -split ',' | ForEach-Object { $_.Trim() } |
            Where-Object { $_ -match '^[\w]+$' })
        if ($candidates.Count -eq 0) { continue }

        Write-Host ""
        Write-Host ("  Ambiguous registration: {0}" -f $folderName) -ForegroundColor Yellow
        Write-Host ("  Executable: {0}" -f $info.Exe) -ForegroundColor DarkGray
        for ($i = 0; $i -lt $candidates.Count; $i++) {
            Write-Host ("    {0}) {1}" -f ($i + 1), $candidates[$i]) -ForegroundColor DarkCyan
        }
        $choice = (Read-HostSafe "  Pick a profile number, or press Enter to leave unresolved").Trim()
        if ([string]::IsNullOrWhiteSpace($choice)) { continue }
        if ($choice -notmatch '^\d+$' -or [int]$choice -lt 1 -or [int]$choice -gt $candidates.Count) {
            Write-Host "  Invalid choice -- no profile was changed." -ForegroundColor Yellow
            continue
        }

        $code = $candidates[[int]$choice - 1]
        $templatePath = Join-Path $GameProfilesDir ($code + ".xml")
        $userProfilePath = Join-Path $UserProfilesDir ($code + ".xml")
        if (-not (Test-Path -LiteralPath $templatePath -PathType Leaf)) {
            Write-Host ("  Profile template is unavailable: {0}" -f $code) -ForegroundColor Red
            Write-Log "Manual registration: template unavailable for $code; folder=$folderName"
            continue
        }
        if (Test-Path -LiteralPath $userProfilePath -PathType Leaf) {
            Write-Host ("  UserProfile {0}.xml already exists -- it was not overwritten." -f $code) -ForegroundColor Yellow
            Write-Log "Manual registration: existing UserProfile preserved for $code; folder=$folderName"
            continue
        }
        try {
            $installRoot = [System.IO.Path]::GetFullPath($InstallFolder).TrimEnd('\')
            $exeFullPath = [System.IO.Path]::GetFullPath($info.Exe)
        } catch {
            Write-Host "  The selected executable path could not be validated -- no profile was written." -ForegroundColor Red
            Write-Log "Manual registration: path validation failed for $code -- $_"
            continue
        }
        if (-not $exeFullPath.StartsWith($installRoot + '\', [System.StringComparison]::OrdinalIgnoreCase) -or
            -not (Test-Path -LiteralPath $exeFullPath -PathType Leaf) -or
            -not (Test-BepInExNoReparsePath -Root $installRoot -Path $exeFullPath)) {
            Write-Host "  The selected executable is outside the game staging folder or no longer present -- no profile was written." -ForegroundColor Red
            Write-Log "Manual registration: executable rejected for $code; path=$exeFullPath"
            continue
        }
        try {
            $template = Read-Xml $templatePath
            $gamePath = $template.GameProfile.SelectSingleNode("GamePath")
            if ($null -eq $gamePath) {
                $gamePath = $template.CreateElement("GamePath")
                [void]$template.GameProfile.PrependChild($gamePath)
            }
            $gamePath.InnerText = $info.Exe
            [void](Set-SecondaryExecutablePath $template $info.Exe)
            Save-XmlMaybe $template $userProfilePath $DryRun
            [void]$Result.Registered.Add([pscustomobject]@{
                Code = $code
                GamePath = $info.Exe
                ManualChoice = $true
            })
            [void]$ManualRegData.Remove($folderName)
            Write-Host ("  Registered {0} -> {1}" -f $code, $info.Exe) -ForegroundColor Green
            Write-Log "Manual registration: selected $code for $folderName -> $($info.Exe)"
        } catch {
            Write-Host ("  FAILED to register {0}: {1}" -f $code, $_) -ForegroundColor Red
            Write-Log "Manual registration FAILED for $code -- $_"
        }
    }
}

# Checks every UserProfile's GamePath and re-points broken ones (empty path or
# missing file). Locates the game's executable by name in the install folder.
# An exe name is only used to auto-fix a path when it belongs to exactly ONE
# profile in the TeknoParrot library AND exactly ONE file is found on disk.
# If the exe name is shared by multiple profiles (e.g. sdaemon.exe, game.exe)
# it is always flagged as ambiguous -- even if only one file exists on disk --
# because there is no safe way to know which game the file belongs to.
# Profiles with a valid, working path are left untouched.
function Repair-GamePaths {
    param([string]$userProfilesDir, [string]$installFolder, [hashtable]$profileIndex, [bool]$DryRun = $false)

    # Map filename (lowercased) -> list of full paths found on disk.
    # Uses Get-GameFiles so .xbe, .dll, ELF, disc images, and extension-less
    # binaries are all included alongside Windows EXE files.
    $exeMap = @{}
    foreach ($file in (Get-GameFiles $installFolder)) {
        $k = $file.Name.ToLower()
        if (-not $exeMap.ContainsKey($k)) { $exeMap[$k] = New-Object System.Collections.ArrayList }
        [void]$exeMap[$k].Add($file.FullName)
    }

    $reports = New-Object System.Collections.ArrayList
    $files = Get-ChildItem -LiteralPath $userProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue
    foreach ($f in $files) {
        try { $doc = Read-Xml $f.FullName } catch { Write-Log "Repair-GamePaths: could not parse $($f.Name) -- $_"; continue }
        if ($null -eq $doc.GameProfile) { continue }

        $gpNode  = $doc.GameProfile.SelectSingleNode("GamePath")
        $curPath = if ($gpNode) { $gpNode.InnerText } else { "" }
        $exeName = [string]$doc.GameProfile.ExecutableName

        if ($curPath -and (Test-Path -LiteralPath $curPath)) { continue }   # path is fine

        if ([string]::IsNullOrWhiteSpace($exeName)) {
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "no-exe-name" })
            continue
        }
        # If this exe name maps to more than one profile in the library it is
        # inherently ambiguous -- never auto-assign it regardless of what is on disk.
        $alts         = Get-ExeAlternatives $exeName.Trim()
        $profileCount = ($alts | ForEach-Object {
            $ak = $_.ToLower()
            if ($profileIndex.ContainsKey($ak)) { $profileIndex[$ak].Count } else { 0 }
        } | Measure-Object -Maximum).Maximum
        if (-not $profileCount) { $profileCount = 0 }
        if ($profileCount -gt 1) {
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "ambiguous"; Exe = $exeName })
            continue
        }

        # Try each alternative name in the on-disk map.
        $key = $null
        foreach ($alt in $alts) {
            $ak = $alt.ToLower()
            if ($exeMap.ContainsKey($ak)) { $key = $ak; break }
        }
        if ($null -eq $key) {
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "not-found"; Exe = $exeName })
            continue
        }
        if ($exeMap[$key].Count -gt 1) {
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "ambiguous"; Exe = $exeName })
            continue
        }

        # Exe name is unique in the library and only one file exists on disk -- safe to fix.
        $newPath = $exeMap[$key][0]
        try {
            if ($null -eq $gpNode) {
                $gpNode = $doc.CreateElement("GamePath")
                [void]$doc.GameProfile.PrependChild($gpNode)
            }
            $gpNode.InnerText = $newPath
            Save-XmlMaybe $doc $f.FullName $DryRun
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "fixed"; NewPath = $newPath })
            Write-Log "Repair: fixed $($f.BaseName) -> $newPath"
        } catch {
            Write-Log "Repair: FAILED to save $($f.Name) -- $_"
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "save-failed" })
        }
    }
    # Review round 2 (Luna Max): "return $reports" lets the output stream
    # enumerate the ArrayList -- with exactly one report, that unwraps to
    # the single pscustomobject itself rather than a one-element collection.
    # This was masked on pwsh only because PowerShell 6+ added a synthetic
    # .Count/.Length property to every object (scalars included), so
    # $reports.Count still happened to read 1 there; Windows PowerShell 5.1
    # has no such synthetic property, so the exact same unwrap left
    # $reports.Count genuinely absent (Should -Be 1 saw $null). The leading
    # comma prevents the unwrap and returns the real ArrayList -- reliably
    # array-shaped with zero, one, or many reports, on both engines.
    return ,$reports
}

# Read-only library status: classifies every UserProfile's GamePath as
# valid / broken / empty, the same check Repair-GamePaths already does
# (Test-Path on $curPath), but reports only -- never writes, never scans
# the install folder, never touches the network. Safe to run any time as a
# fast health check between full AutoSync/Register runs.
function Invoke-LibraryHealthCheck {
    param([string]$UserProfilesDir, [string]$LogPath, [string]$TpRoot)

    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                  Where-Object { $_.Directory.Name -ne "FullBackup" } | Sort-Object BaseName)

    $valid = New-Object System.Collections.ArrayList
    $broken = New-Object System.Collections.ArrayList
    $empty = New-Object System.Collections.ArrayList

    foreach ($pf in $profiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { [void]$broken.Add($pf.BaseName); continue }
            $gpNode  = $doc.GameProfile.SelectSingleNode("GamePath")
            $curPath = if ($gpNode) { $gpNode.InnerText.Trim() } else { "" }
            if ([string]::IsNullOrWhiteSpace($curPath)) {
                [void]$empty.Add($pf.BaseName)
            } elseif (Test-Path -LiteralPath $curPath) {
                [void]$valid.Add($pf.BaseName)
            } else {
                [void]$broken.Add($pf.BaseName)
            }
        } catch {
            [void]$broken.Add($pf.BaseName)
            Write-Log "HealthCheck: could not parse $($pf.Name) -- $_"
        }
    }

    Write-Host ""
    Write-Host ("  Registered profiles : {0}" -f $profiles.Count) -ForegroundColor Cyan
    Write-Host ("  Valid GamePath      : {0}" -f $valid.Count) -ForegroundColor Green
    if ($broken.Count -gt 0) {
        Write-Host ("  Broken GamePath     : {0}" -f $broken.Count) -ForegroundColor Red
        Write-Host ("    {0}" -f ($broken -join ', ')) -ForegroundColor DarkGray
    } else {
        Write-Host "  Broken GamePath     : 0" -ForegroundColor Green
    }
    if ($empty.Count -gt 0) {
        Write-Host ("  Empty GamePath      : {0}" -f $empty.Count) -ForegroundColor Yellow
        Write-Host ("    {0}" -f ($empty -join ', ')) -ForegroundColor DarkGray
    } else {
        Write-Host "  Empty GamePath      : 0" -ForegroundColor Green
    }
    if ($broken.Count -gt 0 -or $empty.Count -gt 0) {
        Write-Host ""
        Write-Host "  Run Register only (mode 2) or AutoSync (mode 1) and choose Repair" -ForegroundColor DarkCyan
        Write-Host "  to fix broken paths automatically where possible." -ForegroundColor DarkCyan
    }

    # -- Optional-setup coverage: GPU fix + FFB Blaster -------------------------
    # Read-only, local-only (no network) -- mirrors Invoke-GpuFixSetup and
    # Invoke-FFBBlasterSetup's detection via the shared Get-*FieldNames /
    # Test-*UpToDate helpers, but never writes anything. Third-party FFB
    # plugin coverage is deliberately NOT checked here -- it requires a
    # live fetch of the AutoSetup.cmd table, which would break this mode's
    # "no network access" guarantee; run mode 8 to check that instead.
    $gpuFixNeeded     = New-Object System.Collections.ArrayList
    $ffbBlasterNeeded = New-Object System.Collections.ArrayList
    $dgVoodoo2Needed  = New-Object System.Collections.ArrayList
    $postgresNeeded   = New-Object System.Collections.ArrayList
    $postgresConfigured = 0
    $reShadeCount     = 0
    $bepInExCount     = 0
    $detected         = Get-DetectedGpuVendor
    $combinedFields    = Get-GpuAndFfbFieldNames -TpRoot $TpRoot
    $gpuFields        = $combinedFields.Gpu
    $ffbFields        = $combinedFields.Ffb

    foreach ($pf in $profiles) {
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            if ($detected.Vendor) {
                $gpuResult = Test-GpuFixUpToDate -Doc $doc -BoolFields $gpuFields.BoolFields -DropdownFields $gpuFields.DropdownFields -Vendor $detected.Vendor
                if ($gpuResult.Eligible -and -not $gpuResult.UpToDate) { [void]$gpuFixNeeded.Add($pf.BaseName) }
            }
            # Use the same structured gate the setup flow uses (issue #41) so
            # the health check agrees exactly with what Invoke-FFBBlasterSetup
            # would actually do: only a 'Supported' profile that still needs a
            # write is reported as needing the fix. An unsupported platform
            # (e.g. pcsx2x6) or an unrecognized/drifted field is never flagged
            # here as "not applied" -- it cannot and should not be applied.
            $ffbSupport = Get-FFBBlasterSupport -Doc $doc -Categories $ffbFields
            if ($ffbSupport.Status -eq 'Supported' -and $ffbSupport.WouldWrite) { [void]$ffbBlasterNeeded.Add($pf.BaseName) }

            if (Test-GameNeedsPostgres $doc) {
                if ([string]::IsNullOrWhiteSpace((Get-PostgresFieldValue $doc "Pass"))) {
                    [void]$postgresNeeded.Add($pf.BaseName)
                } else {
                    $postgresConfigured++
                }
            }

            # dgVoodoo2 / ReShade / BepInEx all need a resolved, existing exe
            # path -- skip silently for broken/empty profiles (already
            # reported above).
            $gpNode   = $doc.GameProfile.SelectSingleNode("GamePath")
            $gamePath = if ($gpNode) { $gpNode.InnerText.Trim() } else { "" }
            if ([string]::IsNullOrWhiteSpace($gamePath) -or -not (Test-Path -LiteralPath $gamePath)) { continue }
            $exeDir = [System.IO.Path]::GetDirectoryName($gamePath)
            if ([string]::IsNullOrWhiteSpace($exeDir)) { continue }

            $apis = @(Get-GameLegacyApi -ExePath $gamePath)
            $dgResult = Test-DgVoodoo2UpToDate -Apis $apis -ExeDir $exeDir
            if ($dgResult.Eligible -and -not $dgResult.UpToDate) { [void]$dgVoodoo2Needed.Add($pf.BaseName) }

            $rsInfo = Get-ReShadeTargetInfo -Doc $doc -GamePath $gamePath -ExeDir $exeDir
            if (Test-Path -LiteralPath (Join-Path $rsInfo.TargetDir $rsInfo.DllName)) { $reShadeCount++ }

            if (Get-BepInExInstalledVersion -ExeDir $exeDir) { $bepInExCount++ }
        } catch {
            Write-Log "HealthCheck: coverage check could not parse $($pf.Name) -- $_"
        }
    }

    Write-Host ""
    Write-Host "  Optional setup coverage:" -ForegroundColor Cyan
    if ($detected.Vendor) {
        if ($gpuFixNeeded.Count -gt 0) {
            Write-Host ("  GPU fix not applied : {0}  (detected: {1})" -f $gpuFixNeeded.Count, $detected.Vendor) -ForegroundColor Yellow
            Write-Host ("    {0}" -f ($gpuFixNeeded -join ', ')) -ForegroundColor DarkGray
        } else {
            Write-Host ("  GPU fix not applied : 0  (detected: {0})" -f $detected.Vendor) -ForegroundColor Green
        }
    } else {
        Write-Host "  GPU fix coverage    : skipped (could not auto-detect GPU vendor)" -ForegroundColor DarkGray
    }
    if ($ffbBlasterNeeded.Count -gt 0) {
        Write-Host ("  FFB Blaster not on  : {0}" -f $ffbBlasterNeeded.Count) -ForegroundColor Yellow
        Write-Host ("    {0}" -f ($ffbBlasterNeeded -join ', ')) -ForegroundColor DarkGray
    } else {
        Write-Host "  FFB Blaster not on  : 0" -ForegroundColor Green
    }
    Write-Host "  FFB plugin coverage : not checked here (needs network access -- run mode 8)" -ForegroundColor DarkGray
    if ($dgVoodoo2Needed.Count -gt 0) {
        Write-Host ("  dgVoodoo2 not applied : {0}  (legacy DX8/DDraw/Glide games)" -f $dgVoodoo2Needed.Count) -ForegroundColor Yellow
        Write-Host ("    {0}" -f ($dgVoodoo2Needed -join ', ')) -ForegroundColor DarkGray
    } else {
        Write-Host "  dgVoodoo2 not applied : 0  (legacy DX8/DDraw/Glide games)" -ForegroundColor Green
    }
    if ($gpuFixNeeded.Count -gt 0 -or $ffbBlasterNeeded.Count -gt 0 -or $dgVoodoo2Needed.Count -gt 0) {
        Write-Host ""
        Write-Host "  Run mode 5 (ReShade), 6 (dgVoodoo2), 7 (GPU fix), or 8 (FFB) to apply these." -ForegroundColor DarkCyan
    }

    # Postgres coverage is entirely read-only here -- never calls
    # Install-Postgres83 or Invoke-PostgresGameSetup, same separation of
    # concerns as the other coverage sections above.
    $postgresInstalled = Test-PostgresInstalled
    Write-Host ""
    Write-Host ("  PostgreSQL service  : {0}" -f $(if ($postgresInstalled) { "installed and running" } else { "not installed" })) -ForegroundColor $(if ($postgresInstalled) { "Green" } else { "DarkGray" })
    if ($postgresNeeded.Count -gt 0) {
        Write-Host ("  Postgres not configured : {0}  (needs a database password set)" -f $postgresNeeded.Count) -ForegroundColor Yellow
        Write-Host ("    {0}" -f ($postgresNeeded -join ', ')) -ForegroundColor DarkGray
    } elseif ($postgresConfigured -gt 0) {
        Write-Host "  Postgres not configured : 0" -ForegroundColor Green
    }
    if ($postgresConfigured -gt 0) {
        Write-Host ("  Postgres configured : {0}" -f $postgresConfigured) -ForegroundColor DarkGray
    }
    if ($postgresNeeded.Count -gt 0) {
        Write-Host "  Run mode 12 (Postgres setup) to apply these." -ForegroundColor DarkCyan
    }

    Write-Host ""
    Write-Host "  Informational (not flagged as needing attention -- ReShade and BepInEx" -ForegroundColor DarkGray
    Write-Host "  are per-game choices, not a hardware/membership-driven yes-or-no):" -ForegroundColor DarkGray
    Write-Host ("    ReShade installed  : {0} of {1} registered games" -f $reShadeCount, $valid.Count) -ForegroundColor DarkGray
    Write-Host ("    BepInEx installed  : {0} of {1} registered games" -f $bepInExCount, $valid.Count) -ForegroundColor DarkGray
    Write-Host ""
    Write-Host ("  Summary: {0} registered; {1} valid paths; {2} broken; {3} empty." -f $profiles.Count, $valid.Count, $broken.Count, $empty.Count) -ForegroundColor Cyan
    if ($broken.Count -eq 0 -and $empty.Count -eq 0) {
        Write-Host "  No library path action needed." -ForegroundColor Green
    } else {
        Write-Host "  Next action: run Register or AutoSync Repair for highlighted paths." -ForegroundColor Yellow
    }

    if ($LogPath -and (Test-Path -LiteralPath $LogPath)) {
        try {
            $lastRun = Get-Content -LiteralPath $LogPath -ErrorAction Stop | Select-String "^\[.*\] Completed\. " | Select-Object -Last 1
            if ($lastRun) {
                Write-Host ""
                Write-Host ("  Last full run : {0}" -f $lastRun.Line) -ForegroundColor DarkGray
            }
        } catch {}
    }

    Write-Log ("HealthCheck: total={0} valid={1} broken={2} empty={3} gpuFixNeeded={4} ffbBlasterNeeded={5} dgVoodoo2Needed={6} reShadeCount={7} bepInExCount={8}" -f `
        $profiles.Count, $valid.Count, $broken.Count, $empty.Count, $gpuFixNeeded.Count, $ffbBlasterNeeded.Count, $dgVoodoo2Needed.Count, $reShadeCount, $bepInExCount)
}

# =============================================================================
# COMPATIBILITY WARNINGS  (Raw Thrills path-length + iDmacDrv32 version pins)
# =============================================================================
# Static, empirically-documented facts about specific old game builds --
# not something that changes upstream, so hardcoded here rather than
# live-fetched (unlike the FFB table, which tracks a live upstream project).

# Standard CRC-32 (IEEE 802.3 polynomial), table-driven. .NET has no
# built-in CRC32 type, so this is a small self-contained implementation.
function Get-Crc32 {
    param([string]$Path)
    # PowerShell parses 0xFFFFFFFF / 0xEDB88320 as negative Int32 literals
    # (they exceed Int32.MaxValue), which breaks casting/bxor against
    # [uint32] values -- use the decimal equivalents instead so they
    # promote to Int64 and cast to UInt32 cleanly.
    $poly    = 3988292384  # 0xEDB88320
    $allOnes = 4294967295  # 0xFFFFFFFF
    $crcTable = New-Object 'System.UInt32[]' 256
    for ($i = 0; $i -lt 256; $i++) {
        $c = [uint32]$i
        for ($j = 0; $j -lt 8; $j++) {
            if (($c -band 1) -ne 0) { $c = [uint32]($poly -bxor ($c -shr 1)) }
            else { $c = [uint32]($c -shr 1) }
        }
        $crcTable[$i] = $c
    }
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $crc = [uint32]$allOnes
    foreach ($b in $bytes) {
        $crc = [uint32]($crcTable[($crc -bxor $b) -band 0xFF] -bxor ($crc -shr 8))
    }
    return ('{0:X8}' -f [uint32]($crc -bxor $allOnes))
}

# Raw Thrills used three engine generations with different hard-coded
# install-path length limits. Exceeding the limit causes the game to fail
# to launch. Value = @{ Limit; Suggested } -- Suggested is the short
# folder rename the community has settled on for that title.
$RawThrillsPathLimits = @{
    # ~64-char limit (old engine, strictest)
    'BBHPro'           = @{ Limit = 64; Suggested = 'BBHP'   }
    'BBHHome'          = @{ Limit = 64; Suggested = 'BBHPH'  }
    'FNF'              = @{ Limit = 64; Suggested = 'FNF'    }
    'FNFSB'            = @{ Limit = 64; Suggested = 'FNFSB'  }
    'GHA'              = @{ Limit = 64; Suggested = 'GHA'    }
    'NicktoonsNitro'   = @{ Limit = 64; Suggested = 'NTN'    }
    'Terminator'       = @{ Limit = 64; Suggested = 'TERM'   }
    'TargetTerrorGold' = @{ Limit = 64; Suggested = 'TTG'    }
    # ~96-char limit (mid-era engine)
    'AliensArmageddon' = @{ Limit = 96; Suggested = 'ALIENS' }
    'BBHWorld'         = @{ Limit = 96; Suggested = 'BBHW'   }
    'Cars'             = @{ Limit = 96; Suggested = 'CARS'   }
    'DirtyDrivin'      = @{ Limit = 96; Suggested = 'DRTYDR' }
    'FNFSB2'           = @{ Limit = 96; Suggested = 'FNFSB2' }
    'Frogger'          = @{ Limit = 96; Suggested = 'FROGGR' }
    'H2Overdrive'      = @{ Limit = 96; Suggested = 'H2OVER' }
    'JurassicPark'     = @{ Limit = 96; Suggested = 'JURASS' }
    'SnoCross'         = @{ Limit = 96; Suggested = 'WXGSNO' }
    # Standalone case, not a Raw Thrills title but the same kind of
    # hard-coded limit -- TPUI itself shows a warning dialog for this one.
    'YugiohDT6U'       = @{ Limit = 64; Suggested = 'YUGIOH' }
}

# Builds the normalised folder-name -> path map used by the extraction
# pickers (Select-GamesInteractive, Select-GamesInteractiveCombined) and
# Invoke-AutoSync to decide whether a ZIP's game is already extracted.
# Normalisation strips the .teknoparrot/.parrot/.game suffix and removes a
# space immediately before ( or [ so old- and new-convention folder names
# for the same game map to the same key (see callers' original comments).
#
# Also registers each PATH TOO LONG entry's profile Code under its Suggested
# short name's existing folder. The shared resolver can then use the DAT
# ProfileCode to recognize short-name folders such as ALIENS.teknoparrot.
function Get-StagingFolderMap {
    param([string]$installFolder)
    $map = @{}
    foreach ($dir in (Get-ChildItem -LiteralPath $installFolder -Directory -ErrorAction SilentlyContinue)) {
        $baseName = $dir.Name -replace '\.(teknoparrot|parrot|game)$', ''
        $keys = @(
            $dir.Name,
            $baseName,
            ($baseName -replace ' (?=[\[\(])', ''),
            (Get-NormalizedGameKey $baseName)
        ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        foreach ($key in $keys) {
            if (-not $map.ContainsKey($key)) { $map[$key] = $dir.FullName }
        }
    }
    if ($RawThrillsPathLimits) {
        foreach ($code in $RawThrillsPathLimits.Keys) {
            $suggested = $RawThrillsPathLimits[$code].Suggested
            if ($map.ContainsKey($suggested) -and -not $map.ContainsKey($code)) {
                $map[$code] = $map[$suggested]
            }
        }
    }
    return $map
}

function Test-ExtractedFolderHasContent {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    if (-not (Test-Path -LiteralPath $Path -PathType Container)) { return $false }
    return ((Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue | Measure-Object).Count -gt 0)
}

# Exact-key lookup only (no fuzzy/Dice fallback): the dat's own game names
# already normalise identically to well-formed ZIP names in practice (both
# follow the same RomVault/Eggman convention), which is why
# Resolve-RegisteredGameFolder's original exact-match design already worked
# for issue #13. A Dice-similarity fallback here was found to add no
# matching power for any confirmed case while being unable to distinguish
# two different profile codes whose normalised names happen to score high
# against the same ZIP name -- removed rather than tuned. See issue #66
# review notes.
function Get-DatEntryForZipName {
    param([string]$RawZipName, [hashtable]$DatIndex)
    if (-not $DatIndex -or $DatIndex.Count -eq 0) { return $null }
    $normZip = Get-NormalizedGameKey $RawZipName
    if ($DatIndex.ContainsKey($normZip)) { return $DatIndex[$normZip] }
    return $null
}

function Resolve-ExtractedGameFolder {
    param(
        [string]$RawZipName,
        [string]$InstallFolder,
        [hashtable]$FolderMap = $null,
        [hashtable]$DatIndex = $null,
        [string]$UserProfilesDir = ''
    )

    if ([string]::IsNullOrWhiteSpace($RawZipName) -or [string]::IsNullOrWhiteSpace($InstallFolder)) { return $null }
    if (-not $FolderMap) { $FolderMap = Get-StagingFolderMap $InstallFolder }

    $baseName = $RawZipName -replace '\.(teknoparrot|parrot|game)$', ''
    $candidateKeys = New-Object System.Collections.Generic.List[string]
    foreach ($key in @(
        $RawZipName,
        $baseName,
        ($baseName -replace ' (?=[\[\(])', ''),
        (Get-NormalizedGameKey $baseName)
    )) {
        if (-not [string]::IsNullOrWhiteSpace($key) -and -not $candidateKeys.Contains($key)) { [void]$candidateKeys.Add($key) }
    }

    $datEntry = Get-DatEntryForZipName -RawZipName $RawZipName -DatIndex $DatIndex
    if ($datEntry -and $datEntry.ProfileCode -and $datEntry.ProfileCode -match '^[\w]+$') {
        $profileCode = [string]$datEntry.ProfileCode
        foreach ($key in @($profileCode, (Get-NormalizedGameKey $profileCode))) {
            if (-not [string]::IsNullOrWhiteSpace($key) -and -not $candidateKeys.Contains($key)) { [void]$candidateKeys.Add($key) }
        }
        if ($RawThrillsPathLimits -and $RawThrillsPathLimits.ContainsKey($profileCode)) {
            $suggested = [string]$RawThrillsPathLimits[$profileCode].Suggested
            foreach ($key in @($suggested, (Get-NormalizedGameKey $suggested))) {
                if (-not [string]::IsNullOrWhiteSpace($key) -and -not $candidateKeys.Contains($key)) { [void]$candidateKeys.Add($key) }
            }
        }
    }

    foreach ($key in $candidateKeys) {
        if ($FolderMap.ContainsKey($key) -and (Test-ExtractedFolderHasContent $FolderMap[$key])) {
            return $FolderMap[$key]
        }
    }

    $registeredFolder = Resolve-RegisteredGameFolder $RawZipName $DatIndex $UserProfilesDir
    if (Test-ExtractedFolderHasContent $registeredFolder) { return $registeredFolder }

    # No Dice-similarity folder scan here (removed -- see issue #66 review
    # notes). The date/version/region-stripped normalised key
    # (Get-NormalizedGameKey) is already one of $candidateKeys checked
    # against $FolderMap above -- $FolderMap is keyed by that same
    # normalised form for every on-disk folder (Get-StagingFolderMap), so
    # the "harmless metadata difference" case (e.g. Battle Gear 3's
    # differing release date) is already resolved via that O(1) lookup
    # without ever reaching this point. A similarity-scored scan added no
    # matching power beyond that exact-key tier for any confirmed case,
    # while being unable to reliably distinguish two different games with a
    # long shared title prefix (e.g. numbered sequels): a real ZIP for one
    # game was found to resolve to a different, similarly-named game's
    # folder at the 0.95 threshold this used, which would have silently
    # skipped extracting the correct game. Removed rather than re-tuned.
    return $null
}

# Folder-name matching (Get-StagingFolderMap above) cannot recognise a
# folder that was renamed to anything other than a name the script itself
# would derive from the ZIP -- a hand-picked short name, a reorganised
# subfolder, anything. But if the game is already fully registered with a
# working GamePath, its real folder location is sitting right there in the
# UserProfile XML, independent of what the folder happens to be named.
# This resolves a ZIP to that real folder via the collection dat (ZIP base
# name -> ProfileCode -> UserProfiles\<ProfileCode>.xml -> GamePath's
# containing folder), so a registered game is never reported as "available
# to extract" again regardless of how its folder is named. Returns $null
# if the dat has no entry, no matching profile is registered, or the
# registered GamePath does not actually exist on disk. See issue #13.
function Resolve-RegisteredGameFolder {
    param([string]$rawZipName, [hashtable]$datIndex, [string]$userProfilesDir)
    if (-not $datIndex -or $datIndex.Count -eq 0 -or -not $userProfilesDir) { return $null }
    $datEntry = Get-DatEntryForZipName -RawZipName $rawZipName -DatIndex $datIndex
    if (-not $datEntry -or -not $datEntry.ProfileCode) { return $null }
    # Profile codes are purely alphanumeric; reject anything else before joining
    # into a path -- the dat is externally-sourced, untrusted input, same as the
    # ProfileCode check in Register-Games (see SECURITY.md).
    if ($datEntry.ProfileCode -notmatch '^[\w]+$') { return $null }
    $profilePath = Join-Path $userProfilesDir "$($datEntry.ProfileCode).xml"
    if (-not (Test-Path -LiteralPath $profilePath)) { return $null }
    try {
        $doc    = Read-Xml $profilePath
        $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
        if ($null -eq $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { return $null }
        $gamePath = $gpNode.InnerText.Trim().TrimEnd('\')
        if (-not (Test-Path -LiteralPath $gamePath)) { return $null }
        return [System.IO.Path]::GetDirectoryName($gamePath)
    } catch { return $null }
}

# Specific games need a SPECIFIC OLD CRC of a specific file -- a newer
# version causes a coin error or other failure. This is the opposite of
# the usual "stale dll" case TPUI already self-heals (deploying its own
# current copy), so it is never auto-fixed here -- only flagged, since
# "fixing" it in the wrong direction breaks the game.
$FileVersionPins = @{
    'BBCF'                    = @{ FileName = 'iDmacDrv32.dll'; RequiredCrc = 'F1FF8CC9' }
    'BBCP'                    = @{ FileName = 'iDmacDrv32.dll'; RequiredCrc = 'F1FF8CC9' }
    'BlazBlueContinuumShift'  = @{ FileName = 'iDmacDrv32.dll'; RequiredCrc = 'BCB0E7FE' }
    'BlazBlueContinuumShift2' = @{ FileName = 'iDmacDrv32.dll'; RequiredCrc = 'BCB0E7FE' }
    'BlazBlueCrossTagBattle'  = @{ FileName = 'iDmacDrv32.dll'; RequiredCrc = 'BCB0E7FE' }
    'ttt2'                    = @{ FileName = 'EBOOT.BIN';      RequiredCrc = '3DD05100' }
}

