# Issue #85 Tier 1: known per-emulator firmware/BIOS prerequisites that
# TeknoParrot itself never bundles or downloads -- the user must obtain and
# place these files themselves. Keyed by <EmulatorType>, one entry per
# emulator that has a confirmed real-world requirement (only Pcsx2x6 has
# one currently; a real install showed Bloody Roar 3 registered correctly
# but failing to launch with "PCSX2x64 Firmware is not installed"). Adding
# a second emulator's requirement later is a one-line table addition, not
# new detection logic -- Get-CompatibilityWarnings' BiosMissing check reads
# this table generically. TPM never downloads, links, or redistributes any
# of these files; the check is existence-only (Test-Path), never content.
$EmulatorBiosRequirements = @{
    'Pcsx2x6' = @{
        RelativeDir   = 'TeknoParrot\bios'
        RequiredFiles = @('27v1602T.d', '27v1602F.bg')
    }
}

# Word-wraps free text (e.g. a community notes field) to a fixed width,
# returning one string per output line, each pre-fixed with Indent. Existing
# line breaks in the input (paragraph breaks, blank separator lines) are
# preserved as their own wrap groups rather than being collapsed -- notes
# pulled from eggmansworld.github.io are often multi-paragraph and lose all
# readability if reflowed into one block.
function Format-NoteLines {
    param([string]$Text, [int]$Width = 74, [string]$Indent = "    ")
    $out = [System.Collections.Generic.List[string]]::new()
    foreach ($rawLine in ($Text -split "`r?`n")) {
        if ([string]::IsNullOrWhiteSpace($rawLine)) { $out.Add(""); continue }
        $cur = ""
        foreach ($word in ($rawLine -split '\s+')) {
            if ($cur -eq "") { $cur = $word }
            elseif (($cur.Length + 1 + $word.Length) -le $Width) { $cur += " $word" }
            else { $out.Add("$Indent$cur"); $cur = $word }
        }
        if ($cur -ne "") { $out.Add("$Indent$cur") }
    }
    return $out
}

# Returns per-game special setup notes + the executable TeknoParrot expects,
# for every CURRENTLY REGISTERED profile whose eggmansworld.github.io entry
# has a non-empty notes field. Joined on profile_name == ProfileCode (the
# profile XML's own basename) -- the same key already used to drive the
# hardcoded compatibility tables above. Network fetch, same convention as
# Get-BepInExRequiredGames: returns an empty array (never a hardcoded
# fallback) if the fetch fails, caller just sees nothing to report.
function Get-GameSetupNotes {
    param([string]$UserProfilesDir)

    $games = Get-EggmanGameData
    if (-not $games) { return ,@() }

    $registeredCodes = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Directory.Name -ne "FullBackup" } |
        ForEach-Object { [void]$registeredCodes.Add($_.BaseName) }

    return @($games | Where-Object { $_.notes -and $registeredCodes.Contains($_.profile_name) } |
              ForEach-Object {
                  [pscustomobject]@{
                      Code     = $_.profile_name
                      GameName = $_.game_name
                      SetupExe = $_.setup_exe
                      Notes    = $_.notes
                  }
              })
}

# Read-only scan for all compatibility checks above. Returns
# [pscustomobject]@{ PathTooLong = @(...); DllMismatch = @(...); GpuIncompatible = @(...); BiosMissing = @(...); ExeMissing = @(...) }.
# Each PathTooLong entry: @{ Code; Length; Limit; Suggested }.
# Each DllMismatch entry: @{ Code; FileName; Found; Required }.
# Each GpuIncompatible entry: @{ Code; Vendor }.
# Each BiosMissing entry: @{ EmulatorType; ExpectedDir; MissingFiles; AffectedGames }.
# Each ExeMissing/ComponentMissing entry: @{ EmulatorType; ContractId;
# ContractStatus; Confidence; ContractBacked; CapabilityId; ExpectedPath;
# DetectorMethod; DetectorSource; AffectedProfiles; AffectedGames }.
function Get-CompatibilityWarnings {
    param([string]$UserProfilesDir, [string]$TeknoParrotRoot = '')

    $pathTooLong  = @()
    $dllMismatch  = @()
    $gpuIncompatible = @()
    $biosMissing  = @()
    $exeMissing   = @()

    # Best-effort, silent GPU detection -- never prompts. If undetected
    # (or vendor is NVIDIA, which has no known-broken titles here), the
    # GPU-incompatibility check is simply skipped for this run.
    $detectedVendor = (Get-DetectedGpuVendor).Vendor
    $gpuList = if ($detectedVendor -and $GpuIncompatibleGames.ContainsKey($detectedVendor)) {
        [System.Collections.Generic.HashSet[string]]::new(
            [string[]]$GpuIncompatibleGames[$detectedVendor], [System.StringComparer]::OrdinalIgnoreCase)
    } else { $null }

    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                  Where-Object { $_.Directory.Name -ne "FullBackup" })

    foreach ($pf in $profiles) {
        $code = $pf.BaseName
        $relevant = $RawThrillsPathLimits.ContainsKey($code) -or $FileVersionPins.ContainsKey($code) -or
                    ($gpuList -and $gpuList.Contains($code))
        if (-not $relevant) { continue }
        try {
            $doc = Read-Xml $pf.FullName
            if (-not $doc.GameProfile) { continue }
            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { continue }
            $curPath = $gpNode.InnerText.Trim()
            if (-not (Test-Path -LiteralPath $curPath)) { continue }

            if ($RawThrillsPathLimits.ContainsKey($code)) {
                $info = $RawThrillsPathLimits[$code]
                if ($curPath.Length -gt $info.Limit) {
                    $pathTooLong += [pscustomobject]@{
                        Code = $code; Length = $curPath.Length
                        Limit = $info.Limit; Suggested = $info.Suggested
                    }
                }
            }

            if ($FileVersionPins.ContainsKey($code)) {
                $pin     = $FileVersionPins[$code]
                $exeDir  = [System.IO.Path]::GetDirectoryName($curPath)
                $dllPath = Join-Path $exeDir $pin.FileName
                if (Test-Path -LiteralPath $dllPath) {
                    try {
                        $foundCrc = Get-Crc32 -Path $dllPath
                        if ($foundCrc -ne $pin.RequiredCrc) {
                            $dllMismatch += [pscustomobject]@{
                                Code = $code; FileName = $pin.FileName
                                Found = $foundCrc; Required = $pin.RequiredCrc
                            }
                        }
                    } catch {
                        Write-Log "CompatibilityWarnings: could not CRC $($pin.FileName) for $code -- $_"
                    }
                }
                # File simply missing: not flagged. TPUI deploys its own
                # current copy at first launch -- nothing to warn about yet.
            }

            if ($gpuList -and $gpuList.Contains($code)) {
                $gpuIncompatible += [pscustomobject]@{ Code = $code; Vendor = $detectedVendor }
            }
        } catch {
            Write-Log "CompatibilityWarnings: could not parse $($pf.Name) -- $_"
        }
    }

    # Issue #85 Tier 1: known per-emulator firmware/BIOS prerequisites.
    # Existence-only check (Test-Path), never reads file content -- TPM
    # never downloads, links, or redistributes these files. Skipped
    # entirely if -TeknoParrotRoot wasn't supplied (backward compatible
    # with existing callers). BIOS checks still require a confirmed
    # requirement, but the pcsx2x6 component check below is independent of
    # that firmware table.
    # One entry per (EmulatorType, missing-file-set), not per game -- every
    # game sharing that emulator would otherwise produce an identical
    # duplicate warning.
    if ($TeknoParrotRoot) {
        $emulatorGames = @{}
        foreach ($pf in $profiles) {
            try {
                $doc = Read-Xml $pf.FullName
                if (-not $doc.GameProfile) { continue }
                $etNode = $doc.GameProfile.SelectSingleNode("EmulatorType")
                if (-not $etNode) { continue }
                $emuType = $etNode.InnerText.Trim()
                if ([string]::IsNullOrWhiteSpace($emuType)) { continue }
                if (-not $emulatorGames.ContainsKey($emuType)) { $emulatorGames[$emuType] = [System.Collections.Generic.List[string]]::new() }
                $emulatorGames[$emuType].Add($pf.BaseName)
            } catch {
                Write-Log "CompatibilityWarnings: could not parse $($pf.Name) for BIOS check -- $_"
            }
        }

        foreach ($emuType in $emulatorGames.Keys) {
            $hasBiosRequirement = $EmulatorBiosRequirements -and $EmulatorBiosRequirements.ContainsKey($emuType)

            # Issue #254/#268: inspect only a positively matched ECVF
            # contract. Missing or ambiguous contracts, unsupported detector
            # methods, and absent emulator folders remain unclassified rather
            # than becoming speculative component warnings.
            $componentState = Get-ContractBackedMissingComponents `
                -EmulatorType $emuType `
                -TeknoParrotRoot $TeknoParrotRoot `
                -AffectedProfiles @($emulatorGames[$emuType])
            if (@($componentState.Components).Count -gt 0) {
                $exeMissing += @($componentState.Components)
                continue  # do not report secondary BIOS noise when a required component is absent
            }

            $req = if ($hasBiosRequirement) { $EmulatorBiosRequirements[$emuType] } else { $null }
            $emuDir = if ($emuType -eq 'Pcsx2x6') { Resolve-Pcsx2Directory -TeknoParrotRoot $TeknoParrotRoot } else { $null }
            if (-not $emuDir) { continue }  # emulator folder itself not present -- nothing to check yet

            if (-not $req) { continue }  # no confirmed BIOS requirement for this emulator

            $biosDir = Join-Path $emuDir $req.RelativeDir
            $missing = @($req.RequiredFiles | Where-Object { -not (Test-Path -LiteralPath (Join-Path $biosDir $_) -PathType Leaf) })
            if ($missing.Count -gt 0) {
                $biosMissing += [pscustomobject]@{
                    EmulatorType   = $emuType
                    ExpectedDir    = $biosDir
                    MissingFiles   = $missing
                    AffectedGames  = @($emulatorGames[$emuType] | Sort-Object)
                }
            }
        }
    }

    # ExeMissing is retained as the compatibility-warning field name for the
    # #254 callers/tests; its entries now represent any contract-declared
    # required component, not only an executable. ComponentMissing is the
    # general semantic alias for new callers.
    return [pscustomobject]@{ PathTooLong = $pathTooLong; DllMismatch = $dllMismatch; GpuIncompatible = $gpuIncompatible; BiosMissing = $biosMissing; ExeMissing = $exeMissing; ComponentMissing = $exeMissing }
}

# =============================================================================
# CONTROL PROPAGATION HELPERS
# =============================================================================
#
# Profiles have no default XML namespace, so plain XPath works. The button
# layout is /GameProfile/JoystickButtons/JoystickButtons (an outer wrapper
# element containing one inner element per button).

# True if a button node already carries any input binding child.
function Test-ButtonIsBound {
    param($btn)
    return ($null -ne $btn.SelectSingleNode("RawInputButton")) -or
           ($null -ne $btn.SelectSingleNode("DirectInputButton")) -or
           ($null -ne $btn.SelectSingleNode("XInputButton"))
}

# Returns the inner button nodes of a profile [xml] document.
function Get-ButtonNodes {
    param($doc)
    return $doc.SelectNodes("/GameProfile/JoystickButtons/JoystickButtons")
}

# Composite match key for a button: "InputMapping|AnalogType".
# Returns $true if a JoystickButtons ButtonName refers to a pure directional
# control (Up/Down/Left/Right joystick axis) rather than an action button.
# After stripping a leading player-number prefix (P1/P2/Player 1/Player 2),
# the remaining label must consist ONLY of direction words. Any additional
# qualifier (Punch, Kick, Shoulder, Fire, etc.) means the slot is an action
# button that happens to use a direction word as a positional modifier (e.g.
# "Left Punch", "Left Shoulder") -- not a joystick axis.
# Used by Invoke-ControlPropagation to guard against copying e.g. SF3's D-pad
# Up binding into a target game's "Left Punch" slot when both share the same
# InputMapping key (P1ButtonUp) but mean completely different physical controls.
function Test-ButtonNameDirectional {
    param([string]$name)
    $n = $name.Trim() -replace '(?i)^\s*(player\s*[12]|p[12])\s+', ''
    $words = @($n -split '\s+' | Where-Object { $_ -ne '' })
    if ($words.Count -eq 0) { return $false }
    $dirWords = @('up','down','left','right','north','south','east','west')
    foreach ($w in $words) {
        if ($dirWords -notcontains $w.ToLower()) { return $false }
    }
    return $true
}

# AnalogType is absent on many template buttons; it defaults to None on both
# sides so a minimal template button still matches a bound archetype button.
function Get-ButtonKey {
    param($btn)
    $imNode = $btn.SelectSingleNode("InputMapping")
    if ($null -eq $imNode -or [string]::IsNullOrWhiteSpace($imNode.InnerText)) { return $null }
    $im = $imNode.InnerText.Trim()
    $atNode = $btn.SelectSingleNode("AnalogType")
    if ($atNode -and -not [string]::IsNullOrWhiteSpace($atNode.InnerText)) {
        $at = $atNode.InnerText.Trim()
    } else {
        $at = "None"
    }
    return "$im|$at"
}

# Classifies a profile's control family from its button set. This is what
# keeps bindings from crossing between game types (a wheel binding can never
# land on a gun, because driving and lightgun are different classes).
# Infers the control family from a profile's AnalogType values.
# NOTE: "spinner" cannot be auto-detected from AnalogType alone -- spinner
# games must be assigned via familyOverride in overrides.json.
function Get-ProfileFamily {
    param($doc)
    $hasWheel = $false; $hasGun = $false; $hasTrackball = $false; $hasOtherAxis = $false
    foreach ($btn in (Get-ButtonNodes $doc)) {
        $imNode = $btn.SelectSingleNode("InputMapping")
        $im = if ($imNode) { $imNode.InnerText.Trim() } else { "" }
        $atNode = $btn.SelectSingleNode("AnalogType")
        $at = if ($atNode -and -not [string]::IsNullOrWhiteSpace($atNode.InnerText)) { $atNode.InnerText.Trim() } else { "None" }
        if ($im -eq "P1Trackball" -or $im -eq "P2Trackball") { $hasTrackball = $true }
        switch ($at) {
            "Wheel"                 { $hasWheel = $true }
            "Gas"                   { $hasWheel = $true }
            "Brake"                 { $hasWheel = $true }
            "AnalogJoystick"        { $hasGun = $true }   # TeknoParrot uses analog joystick axes to represent lightgun aim
            "AnalogJoystickReverse" { $hasGun = $true }
            "None"                  { }
            default                 { $hasOtherAxis = $true }
        }
    }
    if ($hasWheel)     { return "driving"   }
    if ($hasGun)       { return "lightgun"  }
    if ($hasTrackball) { return "trackball" }
    if ($hasOtherAxis) { return "analog"    }
    return "button"
}

# Reads the "Input API" FieldValue, or $null if the profile has no such field.
function Get-ProfileInputApi {
    param($doc)
    $f = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral 'Input API')]")
    if ($null -eq $f) { return $null }
    $v = $f.SelectSingleNode("FieldValue")
    if ($null -eq $v) { return $null }
    return $v.InnerText.Trim()
}

# Sets the "Input API" FieldValue, but only if the field exists AND lists the
# requested API among its options. Returns $true on success. This matters
# because a RawInput binding will not work if the profile's API says XInput.
# Sets the "Input API" FieldValue. Normally only succeeds if the profile's
# FieldOptions already lists the requested API -- this matters because a
# RawInput binding will not work if the profile's API says XInput. The one
# exception is "MergedInput": TeknoParrot's own UI has been confirmed
# (issue #1) to dynamically materialize "MergedInput" into a legacy
# profile's on-disk FieldOptions the first time it's selected there, so an
# absent FieldOptions entry for that specific value does not mean the
# profile can't actually use it -- it just hasn't been touched in the TP
# UI yet. Mirror that behavior here so a propagated XInput-style binding
# is actually visible/usable without requiring the user to manually
# re-toggle every target game in the TeknoParrot UI first.
function Set-ProfileInputApi {
    param($doc, [string]$api)
    $f = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral 'Input API')]")
    if ($null -eq $f) { return $false }
    $optsNode = $f.SelectSingleNode("FieldOptions")
    $opts = if ($optsNode) { @($optsNode.SelectNodes("string") | ForEach-Object { $_.InnerText.Trim() }) } else { @() }
    if ($opts -notcontains $api) {
        if ($api -ne 'MergedInput' -or $null -eq $optsNode) { return $false }
        $newOpt = $doc.CreateElement("string")
        $newOpt.InnerText = $api
        [void]$optsNode.AppendChild($newOpt)
    }
    $v = $f.SelectSingleNode("FieldValue")
    if ($null -eq $v) { return $false }
    $v.InnerText = $api
    return $true
}

# Longest common prefix of a list of strings. Used to turn a device's bind
# names into a single device name. Returns "" for an empty list.
function Get-LongestCommonPrefix {
    param($strings)
    $arr = @($strings)
    if ($arr.Count -eq 0) { return "" }
    $prefix = [string]$arr[0]
    foreach ($s in $arr) {
        $max = [Math]::Min($prefix.Length, $s.Length)
        $i = 0
        while ($i -lt $max -and $prefix[$i] -eq $s[$i]) { $i++ }
        $prefix = $prefix.Substring(0, $i)
        if ($prefix.Length -eq 0) { break }
    }
    return $prefix
}

# Returns the distinct device names a profile is bound to. Buttons are grouped
# by their device path, and each device's name is the longest common prefix of
# its bind names (e.g. "Ultimarc I-PAC A" + "Ultimarc I-PAC F" -> "Ultimarc
# I-PAC"). This lets you confirm each game type uses the device you intend
# before copying its controls to other games.
function Get-ProfileDevices {
    param($doc)
    $byPath = @{}
    $tagOf  = @{}
    foreach ($btn in (Get-ButtonNodes $doc)) {
        foreach ($tag in @("RawInputButton","DirectInputButton","XInputButton")) {
            $bind = $btn.SelectSingleNode($tag)
            if ($null -ne $bind) {
                $dp      = $bind.SelectSingleNode("DevicePath")
                $pathKey = if ($dp) { $dp.InnerText } else { $tag }
                $bnNode  = $btn.SelectSingleNode("BindName")
                $bn      = if ($bnNode) { $bnNode.InnerText } else { "" }
                if (-not $byPath.ContainsKey($pathKey)) {
                    $byPath[$pathKey] = New-Object System.Collections.ArrayList
                    $tagOf[$pathKey]  = $tag
                }
                if ($bn -and $bn -ne 'None') { [void]$byPath[$pathKey].Add($bn) }
                break
            }
        }
    }
    $names = New-Object System.Collections.ArrayList
    foreach ($pathKey in $byPath.Keys) {
        # The API comes from the binding element type, not a guess -- a gamepad
        # read via RawInput is labelled RawInput, not XInput.
        switch ($tagOf[$pathKey]) {
            "XInputButton"      { $api = "XInput"      }
            "DirectInputButton" { $api = "DirectInput" }
            default             { $api = "RawInput"    }
        }
        $name = (Get-LongestCommonPrefix $byPath[$pathKey]).Trim()
        if ([string]::IsNullOrWhiteSpace($name)) {
            # No usable bind names: fall back to a friendly device path (e.g.
            # "Windows Mouse Cursor"), but not a raw HID path.
            if ($pathKey -and -not $pathKey.StartsWith('\\?\')) { $name = $pathKey }
            else { $name = "(unnamed device)" }
        }
        # Replace TeknoParrot's generic "Input Device N" label with the actual
        # API so the report is accurate and readable (e.g. "XInput Device 0").
        if     ($name -match '^Input Device (\d+)') { $name = "$api Device $($Matches[1])" }
        elseif ($name -match '^Input Device')       { $name = "$api Device" }
        if ($names -notcontains $name) { [void]$names.Add($name) }
    }
    return $names
}


# Config fields that describe INPUT behaviour (aim mode, sensitivity, axis
# handling). These are safe to copy between same-type games so a propagated
# game reproduces the reference game's feel. A field is copied only when the target
# also defines it, so nothing is ever invented. Verified present in real
# lightgun profiles (e.g. "Use Relative Input", relative sensitivity, cursor).
# Copying is only as correct as the reference game's own values -- the
# pre-propagation summary (Section 10) prints these before the user confirms,
# so a wrong value on the reference (e.g. an axis mode left over from
# testing with a keyboard instead of a real wheel) is caught before it
# fans out to every other game of that type.
$InputConfigFields = @(
    "Use Relative Input",
    "Player 1 Relative Sensitivity",
    "Player 2 Relative Sensitivity",
    "HideCursor",
    "Reverse Y Axis",
    "Reverse Throttle Axis",
    "Use Keyboard/Button For Axis",
    "Keyboard/Button Axis X/Y Sensitivity",
    "Keyboard/Button Axis Throttle Sensitivity"
)

# Known carried-setting values that usually mean the reference game was bound
# with a substitute device (keyboard, mouse) instead of its real hardware --
# the same root cause as "Use Keyboard/Button For Axis" left True on a wheel
# game. Each entry: the family this applies to, the carried field name, the
# value that triggers the warning, and why it matters.
$ConfigCarryWarnings = @(
    @{ Family = "driving";  Field = "Use Keyboard/Button For Axis"; Value = "True"
       Message = "wheel/pedal axes will be read as digital keyboard/button input, not analog -- should be False if you bind with a real wheel." },
    @{ Family = "lightgun"; Field = "Use Relative Input"; Value = "True"
       Message = "gun aim will be read as relative mouse-style movement, not absolute screen position -- should usually be False for a real lightgun that reports absolute coordinates." }
)

# Returns warning strings for a family's carried config values: known
# device-mismatch combos (see $ConfigCarryWarnings) plus any "...Sensitivity"
# field carried as literal 0, which would silently disable aiming/axis
# response on every propagated game of that type.
function Get-ConfigCarryFlags {
    param([string]$family, $configCarry)
    $flags = New-Object System.Collections.ArrayList
    foreach ($rule in $ConfigCarryWarnings) {
        if ($rule.Family -eq $family -and $configCarry.ContainsKey($rule.Field) -and $configCarry[$rule.Field] -eq $rule.Value) {
            [void]$flags.Add("$($rule.Field)=$($rule.Value) -- $($rule.Message)")
        }
    }
    foreach ($key in $configCarry.Keys) {
        if ($key -match 'Sensitivity$' -and $configCarry[$key].Trim() -eq "0") {
            [void]$flags.Add("$key=0 -- this disables aiming/axis response entirely.")
        }
    }
    return $flags
}

# Returns a hashtable { FieldName = FieldValue } for those of $names that the
# profile's ConfigValues actually contains.
function Get-ConfigFieldMap {
    param($doc, $names)
    $out = @{}
    foreach ($fi in $doc.SelectNodes("/GameProfile/ConfigValues/FieldInformation")) {
        $fn = $fi.SelectSingleNode("FieldName")
        if ($null -eq $fn) { continue }
        $name = $fn.InnerText.Trim()
        if ($names -contains $name) {
            $fv = $fi.SelectSingleNode("FieldValue")
            if ($null -ne $fv) { $out[$name] = $fv.InnerText }
        }
    }
    return $out
}

# Sets a ConfigValues field's value if the field exists in the profile.
# Returns $true if it was set. (Field names are a fixed internal whitelist,
# so the XPath literal below is not built from external input.)
function Set-ConfigField {
    param($doc, [string]$name, [string]$value)
    $fi = $doc.SelectSingleNode("/GameProfile/ConfigValues/FieldInformation[FieldName=$(ConvertTo-XPathStringLiteral $name)]")
    if ($null -eq $fi) { return $false }
    $fv = $fi.SelectSingleNode("FieldValue")
    if ($null -eq $fv) { return $false }
    $fv.InnerText = $value
    return $true
}

# Scans UserProfiles and returns the bound-game pool: every profile that the
# user has bound to a meaningful degree (>= $minBound bound buttons). Each
# entry carries its family, Input API, and a map of (key -> bound button node)
# used as the source of truth for copying. Includes previously-propagated profiles
# intentionally: on re-runs they act as archetypes for any newly registered games.
function Build-ArchetypePool {
    param([string]$userProfilesDir, [int]$minBound)
    $pool  = New-Object System.Collections.ArrayList
    $files = Get-ChildItem -LiteralPath $userProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue
    foreach ($f in $files) {
        try { $doc = Read-Xml $f.FullName }
        catch { Write-Log "Pool scan: could not parse $($f.Name)"; continue }
        if ($null -eq $doc.GameProfile) { continue }
        $map = @{}; $boundCount = 0
        foreach ($btn in (Get-ButtonNodes $doc)) {
            if (Test-ButtonIsBound $btn) {
                $key = Get-ButtonKey $btn
                if ($key) { $map[$key] = $btn; $boundCount++ }
            }
        }
        if ($boundCount -ge $minBound) {
            [void]$pool.Add([pscustomobject]@{
                Code        = $f.BaseName
                Path        = $f.FullName
                Family      = (Get-ProfileFamily $doc)
                InputApi    = (Get-ProfileInputApi $doc)
                Devices     = (Get-ProfileDevices $doc)
                ConfigCarry = (Get-ConfigFieldMap $doc $InputConfigFields)
                Map         = $map
                BoundCount  = $boundCount
            })
        }
    }
    return $pool
}

# For each UNbound (or barely-bound) profile, choose the best same-family
# reference game by key overlap, copy its bindings into matching unbound
# buttons, carry its Input API, and record what was bound vs left manual.
# Reference games are never modified. Returns a list of per-game report objects.
function Invoke-ControlPropagation {
    param([string]$userProfilesDir, $pool, [int]$minBound, $noPropagate = @(), $forceArchetype = @{}, $familyOverride = @{}, $canonicalArchetype = @{}, [bool]$DryRun = $false)

    $reports     = New-Object System.Collections.ArrayList
    $files       = Get-ChildItem -LiteralPath $userProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue
    $sourcePaths = @{}
    foreach ($s in $pool) { $sourcePaths[$s.Path] = $true }

    foreach ($f in $files) {
        # An archetype's BINDINGS are never modified, full stop. Its own
        # Input API may only be corrected against a family's user-
        # designated canonical archetype (canonicalArchetype in
        # overrides.json) -- never a heuristic guess. v0.99.12 tried
        # guessing via best non-self button overlap, reasoning that an
        # archetype can itself be sitting on a stale API, and actively
        # broke a real tester's library: almost every well-bound
        # button-family profile is simultaneously a pool member (the same
        # $minBound threshold drives both), so the "best overlap" heuristic
        # -- which is fine for deciding what bindings to COPY -- ended up
        # cross-correcting unrelated, independently-correct archetypes
        # against each other with no actual signal for which one is right.
        # Confirmed in a real run: StreetFighterIII3rdStrike, the tester's
        # own deliberately-configured MergedInput reference, got silently
        # flipped to DirectInput because a different archetype (BBCF) won
        # the overlap comparison. Reverted in v0.99.14. canonicalArchetype
        # (v0.99.17) sidesteps that exact problem: correction only ever
        # runs when the user has explicitly named the one correct archetype
        # for that family, and only ever pulls from that one designated
        # source -- never a guess. See issue #1.
        if ($sourcePaths.ContainsKey($f.FullName)) {
            $selfEntry = $null
            foreach ($s in $pool) { if ($s.Path -eq $f.FullName) { $selfEntry = $s; break } }
            if ($selfEntry -and $canonicalArchetype.ContainsKey($selfEntry.Family)) {
                $canonCode = [string]$canonicalArchetype[$selfEntry.Family]
                if ($selfEntry.Code -ne $canonCode) {
                    $canon = $null
                    foreach ($s in $pool) { if ($s.Code -eq $canonCode) { $canon = $s; break } }
                    if ($canon -and $canon.InputApi -and $canon.InputApi -ne $selfEntry.InputApi) {
                        try { $canonDoc = Read-Xml $f.FullName }
                        catch { Write-Log "Propagation: could not parse $($f.Name) for canonical Input API check"; continue }
                        if ($null -ne $canonDoc.GameProfile -and (Set-ProfileInputApi $canonDoc $canon.InputApi)) {
                            try {
                                Save-XmlMaybe $canonDoc $f.FullName $DryRun
                                # Update the in-memory pool entry too, not just the file on disk --
                                # $selfEntry is the same object instance referenced by $pool, so this
                                # is visible to every later iteration of this same loop. Without this,
                                # a non-archetype profile that propagates from $selfEntry later in this
                                # very run (e.g. a target alphabetically after this archetype) would
                                # still copy the now-stale pre-correction InputApi, since $best.InputApi
                                # below is read from this same pool snapshot. Confirmed on a real
                                # tester's log: BBCF's correction and ChronoRegalia/dbzenkai/
                                # PokkenTournament/PPQ propagating FROM BBCF with the old DirectInput
                                # value happened in the same second of the same run. See issue #1.
                                $selfEntry.InputApi = $canon.InputApi
                                [void]$reports.Add([pscustomobject]@{
                                    Code = $f.BaseName; Status = "api-fixed-canonical"
                                    Archetype = $canon.Code; ArchetypeApi = $canon.InputApi
                                })
                                Write-Log "Propagation: $($f.BaseName) (archetype) Input API corrected to $($canon.InputApi) to match user-designated canonical archetype $($canon.Code) for family $($selfEntry.Family)"
                            } catch {
                                Write-Log "Propagation: FAILED to save canonical Input API fix for $($f.Name) -- $_"
                                [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "save-failed"; Archetype = $canon.Code })
                            }
                        }
                    }
                }
            }
            continue
        }
        if ($noPropagate -contains $f.BaseName) {
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "skipped-override" })
            continue
        }

        try { $doc = Read-Xml $f.FullName }
        catch { Write-Log "Propagation: could not parse $($f.Name)"; continue }
        if ($null -eq $doc.GameProfile) { continue }

        $btns = Get-ButtonNodes $doc
        if ($null -eq $btns -or $btns.Count -eq 0) { continue }

        $alreadyBound = 0
        foreach ($b in $btns) { if (Test-ButtonIsBound $b) { $alreadyBound++ } }
        $buttonsAlreadyBound = ($alreadyBound -ge $minBound)

        $targetFamily = if ($familyOverride.ContainsKey($f.BaseName)) {
            $familyOverride[$f.BaseName]
        } else {
            Get-ProfileFamily $doc
        }

        # If this game is pinned to a specific archetype via overrides, use it
        # (this is an explicit user choice, so family is not enforced here).
        $best = $null; $bestOverlap = 0; $forced = $false
        if ($forceArchetype.ContainsKey($f.BaseName)) {
            $wantCode = [string]$forceArchetype[$f.BaseName]
            foreach ($s in $pool) { if ($s.Code -eq $wantCode) { $best = $s; $forced = $true; break } }
            if ($null -eq $best) {
                Write-Log "Propagation: pinned archetype '$wantCode' for $($f.BaseName) not found; using best match."
            }
        }

        # Otherwise pick the best same-family archetype by how many of this
        # game's keys it can supply. Ties go to the more completely-bound one.
        # Computed even when this profile's buttons are already bound (below)
        # -- needed there too, to check whether the archetype's Input API can
        # be retroactively applied without touching any button binding.
        if ($null -eq $best) {
            foreach ($s in $pool) {
                if ($s.Family -ne $targetFamily) { continue }
                $ov = 0
                foreach ($b in $btns) { $k = Get-ButtonKey $b; if ($k -and $s.Map.ContainsKey($k)) { $ov++ } }
                if ($ov -gt $bestOverlap -or ($ov -eq $bestOverlap -and $null -ne $best -and $s.BoundCount -gt $best.BoundCount)) {
                    $best = $s; $bestOverlap = $ov
                }
            }
            if ($null -eq $best -or $bestOverlap -eq 0) {
                if ($buttonsAlreadyBound) {
                    [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "skipped-bound" })
                } else {
                    [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "no-archetype"; Family = $targetFamily })
                }
                continue
            }
        }

        # A profile whose buttons are already configured is never re-bound
        # (this loop never touches a working binding), but the Input API
        # fix from issue #1 only runs from inside this same per-profile pass
        # -- without this branch it could never reach an already-bound
        # profile on any later run, even after the fix shipped, since this
        # function would always continue past it above. Checking and
        # correcting just the Input API field here, independent of button
        # binding, lets that fix apply retroactively. See issue #1.
        if ($buttonsAlreadyBound) {
            $currentApi = Get-ProfileInputApi $doc
            $apiSet = $false
            if ($best.InputApi -and $best.InputApi -ne $currentApi) {
                $apiSet = Set-ProfileInputApi $doc $best.InputApi
            }

            # Report-only: scan bound slots for directional/action classification
            # mismatch vs the archetype. Never rewrites -- only flags for ACTION
            # REQUIRED output so the user knows which slots need a manual rebind
            # in TeknoParrot's own UI. Same Test-ButtonNameDirectional logic the
            # non-bound copy path uses to PREVENT these mismatches going forward.
            # See issue #17.
            $mismatchSlots = New-Object System.Collections.ArrayList
            foreach ($b in $btns) {
                if (-not (Test-ButtonIsBound $b)) { continue }
                $k = Get-ButtonKey $b
                if (-not $k -or -not $best.Map.ContainsKey($k)) { continue }
                $srcNameNode = $best.Map[$k].SelectSingleNode("ButtonName")
                $srcName = if ($srcNameNode) { $srcNameNode.InnerText } else { "" }
                $nameNode = $b.SelectSingleNode("ButtonName")
                $btnName = if ($nameNode) { $nameNode.InnerText } else { "" }
                if ((Test-ButtonNameDirectional $srcName) -ne (Test-ButtonNameDirectional $btnName)) {
                    [void]$mismatchSlots.Add($btnName)
                }
            }
            $mismatchStr = if ($mismatchSlots.Count -gt 0) { $mismatchSlots -join ', ' } else { $null }

            if ($apiSet) {
                try {
                    Save-XmlMaybe $doc $f.FullName $DryRun
                    [void]$reports.Add([pscustomobject]@{
                        Code = $f.BaseName; Status = "api-fixed"
                        Archetype = $best.Code; ArchetypeApi = $best.InputApi
                        MismatchSlots = $mismatchStr
                    })
                    Write-Log "Propagation: $($f.BaseName) already bound -- updated Input API to $($best.InputApi) to match archetype $($best.Code)"
                } catch {
                    Write-Log "Propagation: FAILED to save Input API fix for $($f.Name) -- $_"
                    [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "save-failed"; Archetype = $best.Code })
                }
            } else {
                [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "skipped-bound"; MismatchSlots = $mismatchStr })
            }
            if ($mismatchStr) {
                Write-Log "Propagation: $($f.BaseName) already bound -- $($mismatchSlots.Count) slot(s) have directional/action mismatch vs archetype $($best.Code): $mismatchStr -- rebind in TeknoParrot UI"
            }
            continue
        }

        $boundNow = 0
        $manual   = New-Object System.Collections.ArrayList
        $usedKeys = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
        foreach ($b in @($btns)) {                     # @() snapshots before tree edits
            if (Test-ButtonIsBound $b) { continue }
            $k        = Get-ButtonKey $b
            $nameNode = $b.SelectSingleNode("ButtonName")
            $btnName  = if ($nameNode) { $nameNode.InnerText } else { "" }
            if ($k -and $best.Map.ContainsKey($k)) {
                if ($usedKeys.Contains($k)) {
                    if ($btnName) { [void]$manual.Add($btnName) }
                    continue
                }

                # Guard: skip the copy if source and target disagree on whether
                # this slot is a joystick direction vs an action button. Some
                # game profiles reuse the same InputMapping enum value (e.g.
                # P1ButtonUp, P1Button1) for completely different physical
                # controls across titles. Example: P1ButtonUp is the Up
                # direction in SF3 but "Left Punch" in Tekken 6; P1Button1 is
                # LP in SF3 but the UP direction in Rampage. Copying across
                # that semantic boundary bakes in wrong, non-fixable bindings
                # (the profile then counts as REFERENCE and is never revisited).
                # Test-ButtonNameDirectional classifies a slot as directional
                # only when its label, after stripping the player-number prefix,
                # consists exclusively of direction words. A mismatch (one side
                # directional, other side not) is treated as manual. See #17.
                $srcNameNode = $best.Map[$k].SelectSingleNode("ButtonName")
                $srcName = if ($srcNameNode) { $srcNameNode.InnerText } else { "" }
                if ((Test-ButtonNameDirectional $srcName) -ne (Test-ButtonNameDirectional $btnName)) {
                    if ($btnName) { [void]$manual.Add($btnName) }
                    continue
                }
                # Clone the archetype's whole bound node (preserving the exact
                # element order TeknoParrot writes), then restore THIS game's
                # own display name. The clone carries the real device + key.
                $imported = $doc.ImportNode($best.Map[$k], $true)
                $impName  = $imported.SelectSingleNode("ButtonName")
                if ($impName -and $nameNode) { $impName.InnerText = $btnName }
                [void]$b.ParentNode.ReplaceChild($imported, $b)
                [void]$usedKeys.Add($k)
                $boundNow++
            } elseif ($btnName) {
                [void]$manual.Add($btnName)
            }
        }

        $apiSet = $false
        if ($best.InputApi) { $apiSet = Set-ProfileInputApi $doc $best.InputApi }

        # Carry input-behaviour config (aim mode, sensitivity, axis handling)
        # from the archetype, but only fields this target also defines.
        $cfgCarried = New-Object System.Collections.ArrayList
        foreach ($cf in $best.ConfigCarry.Keys) {
            if (Set-ConfigField $doc $cf $best.ConfigCarry[$cf]) { [void]$cfgCarried.Add($cf) }
        }

        try {
            Save-XmlMaybe $doc $f.FullName $DryRun
            [void]$reports.Add([pscustomobject]@{
                Code = $f.BaseName; Status = "bound"; Family = $targetFamily
                Archetype = $best.Code; ArchetypeApi = $best.InputApi; ApiSet = $apiSet
                Bound = $boundNow; Manual = $manual; ConfigCarried = $cfgCarried; Forced = $forced
            })
            Write-Log "Propagated $($f.BaseName): family=$targetFamily src=$($best.Code) bound=$boundNow api=$($best.InputApi)/set=$apiSet config=$($cfgCarried -join ';')"
        } catch {
            Write-Log "Propagation: FAILED to save $($f.Name) -- $_"
            [void]$reports.Add([pscustomobject]@{ Code = $f.BaseName; Status = "save-failed"; Archetype = $best.Code })
        }
    }
    return $reports
}

# Backup-before-write for the standalone "Propagate Controls" menu option.
# Extracted specifically so backup-copy-failure handling is unit-testable:
# a caller must abort before calling Invoke-ControlPropagation whenever
# ErrorCount is greater than zero, in every mode (interactive or
# -Unattended) -- there is no safe "continue anyway" for an incomplete
# backup, since this mode's own promised safety net (and the README's) is
# that UserProfiles is backed up before anything is written.
function New-PropagationBackup {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$UserProfilesDir
    )

    $backupRoot = Join-Path $UserProfilesDir "FullBackup"
    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss")
    $backupPath = Join-Path $backupRoot ("PropagateControls_" + $timestamp)

    [void][System.IO.Directory]::CreateDirectory($backupRoot)
    [void][System.IO.Directory]::CreateDirectory($backupPath)

    $backupCopyErrs = $null
    Get-ChildItem -LiteralPath $UserProfilesDir | Where-Object { $_.Name -ne "FullBackup" } |
        Copy-Item -Destination $backupPath -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable backupCopyErrs

    return [pscustomobject]@{
        Path       = $backupPath
        ErrorCount = $backupCopyErrs.Count
    }
}

# Prints Invoke-ControlPropagation's $reports in the same format used by both
# the AutoSync/Register-only flow and the standalone "Propagate Controls" menu
# option, so the two entry points never drift out of sync with each other.
# Returns the count of games actually updated (bound/api-fixed/api-fixed-
# canonical) and the no-archetype subset, both needed by callers for their own
# later summary/ACTION REQUIRED sections.
function Write-ControlPropagationResults {
    param($Reports)

    Write-Host ""
    Write-Host " Results:" -ForegroundColor Green
    foreach ($r in $Reports) {
        switch ($r.Status) {
            "bound" {
                $pin = if ($r.Forced) { "  (pinned)" } else { "" }
                Write-Host ("    {0}{1}" -f $r.Code, $pin) -ForegroundColor Green
                Write-Host ("       copied from {0} [{1}] -- bound {2} control(s)" -f $r.Archetype, $r.Family, $r.Bound) -ForegroundColor DarkGray
                if ($r.ConfigCarried.Count -gt 0) {
                    Write-Host ("       carried settings: {0}" -f ($r.ConfigCarried -join ", ")) -ForegroundColor DarkGray
                }
                if (-not $r.ApiSet -and $r.ArchetypeApi) {
                    Write-Host ("       NOTE: left Input API unchanged ('{0}' not offered by this game)" -f $r.ArchetypeApi) -ForegroundColor Yellow
                }
                if ($r.Manual.Count -gt 0) {
                    Write-Host ("       still manual: {0}" -f ($r.Manual -join ", ")) -ForegroundColor Yellow
                }
            }
            "no-archetype"     { Write-Host ("    {0}  -- no '{1}' example game bound yet; controls will be set once you bind one (see ACTION REQUIRED)" -f $r.Code, $r.Family) -ForegroundColor Yellow }
            "api-fixed"        { Write-Host ("    {0}  -- already bound; Input API corrected to '{1}' (matched from {2})" -f $r.Code, $r.ArchetypeApi, $r.Archetype) -ForegroundColor Green }
            "api-fixed-canonical" { Write-Host ("    {0}  -- archetype; Input API corrected to '{1}' (matched from canonical archetype {2})" -f $r.Code, $r.ArchetypeApi, $r.Archetype) -ForegroundColor Green }
            "skipped-bound"    { Write-Host ("    {0}  -- already bound, left unchanged" -f $r.Code) -ForegroundColor DarkGray }
            "skipped-override" { Write-Host ("    {0}  -- skipped (per-game override)" -f $r.Code) -ForegroundColor DarkGray }
            "save-failed"      { Write-Host ("    {0}  -- ERROR saving (see TeknoParrot-Manager.log)" -f $r.Code) -ForegroundColor Red }
        }
        if ($r.MismatchSlots) {
            Write-Host ("       ACTION REQUIRED -- directional/action mismatch: {0}" -f $r.MismatchSlots) -ForegroundColor Yellow
            Write-Host ("       Rebind these slots manually in TeknoParrot's own UI (see issue #17)" ) -ForegroundColor Yellow
        }
    }
    $boundCount = @($Reports | Where-Object { $_.Status -eq "bound" -or $_.Status -eq "api-fixed" -or $_.Status -eq "api-fixed-canonical" }).Count
    $noArchetype = @($Reports | Where-Object { $_.Status -eq "no-archetype" })
    Write-Host ""
    Write-Host (" Games updated: {0}" -f $boundCount) -ForegroundColor Green
    return [pscustomobject]@{ BoundCount = $boundCount; NoArchetypeItems = $noArchetype }
}

# Asks the user which control devices they have and want to use, then prints a
# tailored plan of which game to bind with which device. This is guidance
# only: it reads no files and changes nothing. The actual copying happens
# later, after the user binds those games and re-runs.
function Invoke-DeviceSurvey {

    # Scriptblock instead of a nested function: PowerShell nested functions
    # escape into session scope after the first call, polluting the environment
    # for the rest of the session. A scriptblock stays local to this function.
    $readYesNo = { param([string]$q) return ((Read-HostSafe "   $q (Y/N)").ToUpper() -eq "Y") }

    Write-Host ""
    Write-Host " Which controls do you have and want to use?" -ForegroundColor Cyan
    Write-Host " (Answer Y or N. This only prints a plan; it changes nothing.)" -ForegroundColor DarkCyan
    Write-Host ""

    $hasXbox      = & $readYesNo "Xbox / XInput controller?"
    $hasArcade    = & $readYesNo "Arcade joystick + buttons?"
    $hasTrackball = & $readYesNo "Trackball?"
    $hasSpinner   = & $readYesNo "Spinner (single-axis dial)?"
    $hasWheel     = & $readYesNo "Steering wheel + pedals?"
    $hasGun       = & $readYesNo "Lightgun?"
    $hasKeyboard  = & $readYesNo "Keyboard (no game controller)?"

    # Resolve one device per game family from what the user has, preferring the
    # purpose-built control and falling back to the most versatile available.
    $plan = [ordered]@{}

    if ($hasTrackball) { $plan["Trackball games (Golden Tee, Silver Strike)"] = "your trackball" }

    if     ($hasArcade)   { $plan["Fighting / classic arcade"] = "your arcade stick + buttons" }
    elseif ($hasXbox)     { $plan["Fighting / classic arcade"] = "your Xbox pad" }
    elseif ($hasKeyboard) { $plan["Fighting / classic arcade"] = "your keyboard" }

    if     ($hasWheel)   { $plan["Driving games"] = "your wheel + pedals" }
    elseif ($hasXbox)    { $plan["Driving games"] = "your Xbox pad (analog steering, triggers, gears)" }
    elseif ($hasSpinner) { $plan["Driving games"] = "your spinner for steering, buttons for gas/brake" }

    if ($hasGun) {
        $plan["Lightgun games"] = "your lightgun"
    } else {
        # No gun: trackball (relative/mouse aim) is the suggested fallback, with
        # the Xbox right stick as the alternative. Ask only if both are present.
        if ($hasTrackball -and $hasXbox) {
            Write-Host ""
            Write-Host "   No lightgun. For gun games, aim with:" -ForegroundColor Yellow
            Write-Host "     1) Trackball       (precise, but no fixed center; you roll to aim)"
            Write-Host "     2) Xbox right stick (smooth and self-centering)"
            if ((Read-HostSafe "   Choose 1 or 2") -eq "2") {
                $plan["Lightgun games (no gun)"] = "your Xbox right stick (analog aim)"
            } else {
                $plan["Lightgun games (no gun)"] = "your trackball (relative/mouse aim)"
            }
        }
        elseif ($hasTrackball) { $plan["Lightgun games (no gun)"] = "your trackball (relative/mouse aim)" }
        elseif ($hasXbox)      { $plan["Lightgun games (no gun)"] = "your Xbox right stick (analog aim)" }
    }

    if     ($hasXbox)     { $plan["All other games"] = "your Xbox pad" }
    elseif ($hasArcade)   { $plan["All other games"] = "your arcade stick + buttons" }
    elseif ($hasKeyboard) { $plan["All other games"] = "your keyboard" }

    Write-Host ""
    Write-Host " ----------------------------------------------------------" -ForegroundColor Cyan
    Write-Host " YOUR BINDING PLAN" -ForegroundColor Cyan
    Write-Host " ----------------------------------------------------------" -ForegroundColor Cyan
    if ($plan.Count -eq 0) {
        Write-Host "  No devices selected -- nothing to plan." -ForegroundColor Yellow
        Write-Log "Device survey: no devices selected."
        return
    }
    Write-Host " In TeknoParrotUi.exe, bind ONE game of each type below using the"
    Write-Host " device shown, then re-run this script and choose Propagate:"
    Write-Host ""
    foreach ($k in $plan.Keys) {
        Write-Host ("   - {0}" -f $k) -ForegroundColor Green
        Write-Host ("       bind with: {0}" -f $plan[$k]) -ForegroundColor DarkGray
    }
    Write-Host ""
    Write-Host " Bind each one completely, including Test, Service, Coin, Start." -ForegroundColor DarkCyan
    if (-not $hasGun -and (@($plan.Keys) -match "Lightgun")) {
        Write-Host ""
        Write-Host " Gun games without a gun aim with mouse/cursor or stick input." -ForegroundColor Yellow
        Write-Host " Propagation now also carries the aim-mode settings (relative" -ForegroundColor Yellow
        Write-Host " input, sensitivity, hide-cursor) between gun games, so they" -ForegroundColor Yellow
        Write-Host " match your bound game's settings. If one still aims oddly, check that" -ForegroundColor Yellow
        Write-Host " game's own settings in the TeknoParrot UI." -ForegroundColor Yellow
    }
    Write-Log "Device survey: plan=$($plan.Count) items; xbox=$hasXbox arcade=$hasArcade trackball=$hasTrackball spinner=$hasSpinner wheel=$hasWheel gun=$hasGun keyboard=$hasKeyboard"
}

# =============================================================================
# RESTORE FROM BACKUP
# =============================================================================
# Lists all timestamped backups in UserProfiles\FullBackup, lets the user pick
# one, confirms, then copies it back to UserProfiles -- overwriting current files.
# The FullBackup subfolder itself is never touched during the restore.
function Invoke-RestoreBackup {
    param([string]$userProfilesDir)

    $backupRoot = Join-Path $userProfilesDir "FullBackup"
    if (-not (Test-Path -LiteralPath $backupRoot)) {
        Write-Host "  No backups found in: $backupRoot" -ForegroundColor Yellow
        return
    }

    $backups = @(Get-ChildItem -LiteralPath $backupRoot -Directory -ErrorAction SilentlyContinue |
                     Sort-Object Name -Descending)
    if ($backups.Count -eq 0) {
        Write-Host "  No backup folders found." -ForegroundColor Yellow
        return
    }

    Write-Host ""
    Write-Host "  Available backups (most recent first):" -ForegroundColor Cyan
    for ($i = 0; $i -lt $backups.Count; $i++) {
        $b         = $backups[$i]
        $fileCount = @(Get-ChildItem -LiteralPath $b.FullName -File -ErrorAction SilentlyContinue).Count
        Write-Host ("    {0,3})  {1}   ({2} file(s))" -f ($i + 1), $b.Name, $fileCount)
    }
    Write-Host ""
    $choice = (Read-HostSafe "  Enter number to restore, or Enter to cancel")
    if ([string]::IsNullOrWhiteSpace($choice)) {
        Write-Host "  Restore cancelled." -ForegroundColor DarkGray
        Write-Log "Restore: cancelled by user."
        return
    }
    if ($choice -notmatch '^\d+$' -or $choice.Length -gt 9 -or [int]$choice -lt 1 -or [int]$choice -gt $backups.Count) {
        Write-Host "  Invalid selection. Restore cancelled." -ForegroundColor Yellow
        Write-Log "Restore: invalid selection '$choice'."
        return
    }
    $selected = $backups[[int]$choice - 1]

    $backupXmls = @(Get-ChildItem -LiteralPath $selected.FullName -Filter "*.xml" -File `
                        -ErrorAction SilentlyContinue)
    if ($backupXmls.Count -eq 0) {
        Write-Host ("  ERROR: Selected backup '{0}' contains no XML profiles -- restore aborted." -f $selected.Name) -ForegroundColor Red
        Write-Log "Restore: aborted -- backup '$($selected.Name)' contains no XML files."
        return
    }

    Write-Host ""
    Write-Host ("  Selected : {0}  ({1} profile(s))" -f $selected.Name, $backupXmls.Count) -ForegroundColor Yellow
    Write-Host "  WARNING  : This will OVERWRITE all current UserProfiles with the backup." -ForegroundColor Yellow
    $confirm = (Read-HostSafe "  Type YES to confirm")
    if ($confirm.ToUpper() -ne "YES") {
        Write-Host "  Restore cancelled." -ForegroundColor DarkGray
        Write-Log "Restore: user did not confirm."
        return
    }

    # TeknoParrot must be fully closed before files can be safely replaced.
    # If it is running, profile files it has open cannot be deleted, which
    # would leave the UserProfiles directory in a mixed old/new state.
    if (-not (Wait-TpmForProcessClose -ProcessNames @('TeknoParrotUi') -FriendlyName 'TeknoParrot')) {
        Write-Host '  Restore cancelled. Your selected backup is unchanged.' -ForegroundColor Yellow
        Write-Log 'Restore: cancelled while waiting for TeknoParrot to close.'
        return
    }

    # Snapshot the live profiles before deletion so a partial copy failure can
    # roll the live directory back without touching historical FullBackup data.
    $rollbackDir = Join-Path ([System.IO.Path]::GetTempPath()) ('tpm-restore-rollback-' + [guid]::NewGuid().ToString('N'))
    try {
        [void][System.IO.Directory]::CreateDirectory($rollbackDir)
        Get-ChildItem -LiteralPath $userProfilesDir | Where-Object { $_.Name -ne 'FullBackup' } |
            Copy-Item -Destination $rollbackDir -Recurse -Force -ErrorAction Stop
    } catch {
        Write-Host '  ERROR: Could not snapshot current profiles before restore; nothing was changed.' -ForegroundColor Red
        Write-Log "Restore: rollback snapshot failed -- $_"
        if (Test-Path -LiteralPath $rollbackDir) { Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue }
        return [pscustomobject]@{ Succeeded = $false; Name = $selected.Name; ErrorCount = 1; RollbackSucceeded = $false }
    }

    # Remove current UserProfiles content, keeping FullBackup intact.
    # Use Where-Object instead of -Exclude for reliable PS 5.1 behaviour.
    # Treat any deletion failures as fatal: a partial delete followed by a
    # partial copy would leave UserProfiles in an undefined mixed state.
    $deleteErrs = @()
    # Remove-Item receives FileInfo/DirectoryInfo objects from the pipeline
    # (not path strings), so pipeline binding already bypasses wildcard
    # expansion -- safe even with [, ], $ in game folder names. If this
    # source is ever changed to raw path strings, add -LiteralPath there.
    Get-ChildItem -LiteralPath $userProfilesDir | Where-Object { $_.Name -ne "FullBackup" } |
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable deleteErrs
    if ($deleteErrs.Count -gt 0) {
        Write-Host ("  ERROR: {0} file(s) could not be removed. The restore was not completed." -f $deleteErrs.Count) -ForegroundColor Red
        Write-Host "  TPM will keep the selected backup and attempt to restore the previous live profiles." -ForegroundColor Yellow
        Write-Log "Restore: FAILED -- $($deleteErrs.Count) file(s) could not be removed."
        try {
            Get-ChildItem -LiteralPath $userProfilesDir | Where-Object { $_.Name -ne 'FullBackup' } | Remove-Item -Recurse -Force -ErrorAction Stop
            Get-ChildItem -LiteralPath $rollbackDir | Copy-Item -Destination $userProfilesDir -Recurse -Force -ErrorAction Stop
            Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue
            return [pscustomobject]@{ Succeeded = $false; Name = $selected.Name; ErrorCount = $deleteErrs.Count; RollbackSucceeded = $true }
        } catch {
            Write-Log "Restore: rollback after delete failure failed -- $_"
            return [pscustomobject]@{ Succeeded = $false; Name = $selected.Name; ErrorCount = $deleteErrs.Count; RollbackSucceeded = $false; RollbackPath = $rollbackDir }
        }
    }

    # Copy backup into UserProfiles. Copy-Item receives FileInfo/DirectoryInfo
    # objects from the pipeline (not path strings), so pipeline binding
    # already bypasses wildcard expansion -- safe even with [, ], $ in game
    # folder names. If this source is ever changed to raw path strings, add
    # -LiteralPath there.
    $restoreErrs = @()
    Get-ChildItem -LiteralPath $selected.FullName |
        Copy-Item -Destination $userProfilesDir -Recurse -Force `
                  -ErrorAction SilentlyContinue -ErrorVariable restoreErrs
    $errCount = $restoreErrs.Count

    if ($errCount -gt 0) {
        Write-Host ("  ERROR: {0} file(s) could not be restored. The restore was not completed." -f $errCount) -ForegroundColor Red
        Write-Host '  TPM will attempt to restore the previous live profiles from its rollback snapshot.' -ForegroundColor Yellow
        Write-Log "Restore: failed with $errCount error(s) from $($selected.Name)"
        try {
            Get-ChildItem -LiteralPath $userProfilesDir | Where-Object { $_.Name -ne 'FullBackup' } | Remove-Item -Recurse -Force -ErrorAction Stop
            Get-ChildItem -LiteralPath $rollbackDir | Copy-Item -Destination $userProfilesDir -Recurse -Force -ErrorAction Stop
            Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue
            return [pscustomobject]@{ Succeeded = $false; Name = $selected.Name; ErrorCount = $errCount; RollbackSucceeded = $true }
        } catch {
            Write-Log "Restore: rollback after copy failure failed -- $_"
            return [pscustomobject]@{ Succeeded = $false; Name = $selected.Name; ErrorCount = $errCount; RollbackSucceeded = $false; RollbackPath = $rollbackDir }
        }
    }
    Remove-Item -LiteralPath $rollbackDir -Recurse -Force -ErrorAction SilentlyContinue
    Write-Host "  Restore complete." -ForegroundColor Green
    Write-Log "Restore: completed from $($selected.Name), no errors."
    return [pscustomobject]@{ Succeeded = $true; Name = $selected.Name; ErrorCount = 0; RollbackSucceeded = $true }
}

# =============================================================================
# LAUNCHBOX XML EXPORT  (standalone file only -- no direct LaunchBox writes)
# =============================================================================
# Reads every UserProfile that has a valid GamePath and builds a LaunchBox-
# compatible XML file the user can inspect and import manually. Writing
# directly to LaunchBox's Arcade.xml is intentionally not done here: LaunchBox
# must be fully closed before its database files are modified externally, its
# XML schema can vary between versions, and game entries must be associated with
# a specific internal emulator ID that only LaunchBox itself can assign safely.
# Manual import takes about 30 seconds and avoids every one of those risks.
#
# Returns the count of games written, or -1 on a fatal write error.
#
# NOTE: <ApplicationPath> below is deliberately the GameProfile XML's own
# path relative to the LaunchBox root, NOT the game's executable. This was
# confirmed against a real, working LaunchBox installation's live
# Data\Platforms\TeknoParrot.xml: LaunchBox's TeknoParrot emulator entry
# uses CommandLine "--profile=%romfile%.xml" with FileNameWithoutExtensionAndPath
# enabled, so the "rom" LaunchBox launches against IS the profile XML --
# %romfile% resolves to the bare profile filename, and the literal ".xml"
# is appended by the emulator's own command-line template.
function Export-LaunchBoxXml {
    param([string]$userProfilesDir, [string]$lbRoot, [string]$outputPath)

    $files = Get-ChildItem -LiteralPath $userProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue |
                 Where-Object { $_.Directory.Name -ne "FullBackup" }

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine('<?xml version="1.0" encoding="utf-8"?>')
    [void]$sb.AppendLine('<LaunchBox>')

    $count = 0
    foreach ($f in $files) {
        try {
            $doc = Read-Xml $f.FullName
            if ($null -eq $doc.GameProfile) { continue }

            $gpNode   = $doc.GameProfile.SelectSingleNode("GamePath")
            $gamePath = if ($gpNode) { $gpNode.InnerText } else { "" }
            if (-not $gamePath -or -not (Test-Path -LiteralPath $gamePath)) { continue }

            # Friendly title: try the Description field; fall back to
            # CamelCase-split profile code ("AkaiKatanaShinNesica" -> "Akai Katana Shin Nesica")
            $descNode = $doc.GameProfile.SelectSingleNode("Description")
            if ($descNode -and -not [string]::IsNullOrWhiteSpace($descNode.InnerText)) {
                $title = $descNode.InnerText.Trim()
            } else {
                $title = [regex]::Replace($f.BaseName, '(?<=[a-z])(?=[A-Z])', ' ')
            }

            $appPath = if ($lbRoot) { Get-RelativePath $lbRoot $f.FullName } else { $f.FullName }

            $esc = [System.Security.SecurityElement]
            [void]$sb.AppendLine('  <Game>')
            [void]$sb.AppendLine("    <Title>$($esc::Escape($title))</Title>")
            [void]$sb.AppendLine("    <Platform>Arcade</Platform>")
            [void]$sb.AppendLine("    <ApplicationPath>$($esc::Escape($appPath))</ApplicationPath>")
            [void]$sb.AppendLine("    <CommandLine />")
            [void]$sb.AppendLine("    <RomPath>$($esc::Escape($gamePath))</RomPath>")
            [void]$sb.AppendLine("    <Favorite>false</Favorite>")
            [void]$sb.AppendLine("    <Completed>false</Completed>")
            [void]$sb.AppendLine("    <Hidden>false</Hidden>")
            [void]$sb.AppendLine("    <Enabled>true</Enabled>")
            [void]$sb.AppendLine("    <Notes>Exported by TeknoParrot Manager</Notes>")
            [void]$sb.AppendLine('  </Game>')
            $count++
        } catch {
            Write-Log "LaunchBox export: skipped $($f.Name) -- $_"
        }
    }

    [void]$sb.AppendLine('</LaunchBox>')

    try {
        [System.IO.File]::WriteAllText($outputPath, $sb.ToString(), (New-Object System.Text.UTF8Encoding $false))
        return $count
    } catch {
        Write-Log "LaunchBox export: FAILED to write file -- $_"
        return -1
    }
}

# =============================================================================
# LAUNCHBOX DIRECT INTEGRATION  (writes straight into LaunchBox's Data\ files)
# =============================================================================
# Real-world schema below (Emulator/Platform/Game field names and values) was
# captured from a working LaunchBox installation's live Data\Emulators.xml and
# Data\Platforms\TeknoParrot.xml -- not guessed. Confirmed via a LaunchBox
# forum admin post that TeknoParrot's profile structure is not understood by
# LaunchBox's own auto-import, which is why ScrapeAs=Arcade and
# DisableAutoImport=true matter for any platform this script creates.

# Strips characters that are invalid in a Windows filename from a
# user-typed custom platform name, since the name doubles as the
# Data\Platforms\<name>.xml filename. Falls back to "TeknoParrot" if
# nothing valid remains.
function Get-SafeLaunchBoxPlatformFileName {
    param([string]$platformName)
    $clean = [regex]::Replace($platformName, '[\\/:*?"<>|]', '').Trim()
    if ([string]::IsNullOrWhiteSpace($clean)) { $clean = "TeknoParrot" }
    return $clean
}

# Backs up only the specific Data\ files about to be modified -- never the
# whole Data\ folder, since some platform files (Arcade.xml) run 20+ MB and
# copying everything on every run would be slow for no benefit. Files are
# copied into Scripts\LaunchBoxBackups\<timestamp>\ preserving their path
# relative to the LaunchBox root, so a restore is a straight copy back
# (see Invoke-RestoreLaunchBoxBackup). Returns the backup folder path, or
# $null on failure -- writing to LaunchBox's live files without a
# successful backup first is never acceptable.
function Backup-LaunchBoxFiles {
    param([string]$lbRoot, [string[]]$relativeFiles)

    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss")
    $backupPath = Join-Path (Join-Path $PSScriptRoot "LaunchBoxBackups") $timestamp

    try {
        foreach ($rel in $relativeFiles) {
            $srcFull = Join-Path $lbRoot $rel
            if (-not (Test-Path -LiteralPath $srcFull)) { continue }   # nothing to back up yet (new platform file)
            $dstFull = Join-Path $backupPath $rel
            if (-not (Test-PathInside $dstFull $backupPath)) {
                Write-Log "LaunchBox backup: FAILED -- '$rel' would escape the backup folder"
                return $null
            }
            [void][System.IO.Directory]::CreateDirectory((Split-Path -Parent $dstFull))
            Copy-Item -LiteralPath $srcFull -Destination $dstFull -Force
        }
    } catch {
        Write-Log "LaunchBox backup: FAILED -- $_"
        return $null
    }
    Write-Log "LaunchBox backup: saved to $backupPath"
    return $backupPath
}

# Restores a previous LaunchBox backup by copying each backed-up file back
# to its original relative location under the LaunchBox root. Mirrors
# Invoke-RestoreBackup's UX (list by timestamp, confirm with YES, refuse
# while the target app is running) so both restore flows feel like the
# same feature.
function Invoke-RestoreLaunchBoxBackup {
    param([string]$lbRoot)

    $backupRoot = Join-Path $PSScriptRoot "LaunchBoxBackups"
    if (-not (Test-Path -LiteralPath $backupRoot)) {
        Write-Host "  No LaunchBox backups found in: $backupRoot" -ForegroundColor Yellow
        return
    }

    $backups = @(Get-ChildItem -LiteralPath $backupRoot -Directory -ErrorAction SilentlyContinue | Sort-Object Name -Descending)
    if ($backups.Count -eq 0) {
        Write-Host "  No LaunchBox backup folders found." -ForegroundColor Yellow
        return
    }

    Write-Host ""
    Write-Host "  Available LaunchBox backups (most recent first):" -ForegroundColor Cyan
    for ($i = 0; $i -lt $backups.Count; $i++) {
        $b         = $backups[$i]
        $fileCount = (Get-ChildItem -LiteralPath $b.FullName -Recurse -File -ErrorAction SilentlyContinue).Count
        Write-Host ("    {0,3})  {1}   ({2} file(s))" -f ($i + 1), $b.Name, $fileCount)
    }
    Write-Host ""
    $choice = (Read-HostSafe "  Enter number to restore, or Enter to cancel")
    if ([string]::IsNullOrWhiteSpace($choice)) {
        Write-Host "  Restore cancelled." -ForegroundColor DarkGray
        Write-Log "LaunchBox restore: cancelled by user."
        return
    }
    if ($choice -notmatch '^\d+$' -or $choice.Length -gt 9 -or [int]$choice -lt 1 -or [int]$choice -gt $backups.Count) {
        Write-Host "  Invalid selection. Restore cancelled." -ForegroundColor Yellow
        Write-Log "LaunchBox restore: invalid selection '$choice'."
        return
    }
    $selected = $backups[[int]$choice - 1]

    Write-Host ""
    Write-Host ("  Selected : {0}" -f $selected.Name) -ForegroundColor Yellow
    Write-Host "  WARNING  : This will OVERWRITE the current LaunchBox Emulators.xml," -ForegroundColor Yellow
    Write-Host "             Platforms.xml, and any platform file(s) in this backup." -ForegroundColor Yellow
    $confirm = (Read-HostSafe "  Type YES to confirm")
    if ($confirm.ToUpper() -ne "YES") {
        Write-Host "  Restore cancelled." -ForegroundColor DarkGray
        Write-Log "LaunchBox restore: user did not confirm."
        return
    }

    if (-not (Wait-TpmForProcessClose -ProcessNames @('LaunchBox','BigBox') -FriendlyName 'LaunchBox')) {
        Write-Host '  Restore cancelled. Your selected backup is unchanged.' -ForegroundColor Yellow
        Write-Log 'LaunchBox restore: cancelled while waiting for LaunchBox to close.'
        return
    }

    $backupFiles = @(Get-ChildItem -LiteralPath $selected.FullName -Recurse -File -ErrorAction SilentlyContinue)
    $errCount = 0
    foreach ($bf in $backupFiles) {
        try {
            $rel = Get-RelativePath $selected.FullName $bf.FullName
            $dst = Join-Path $lbRoot $rel
            if (-not (Test-PathInside $dst $lbRoot)) { $errCount++; continue }
            [void][System.IO.Directory]::CreateDirectory((Split-Path -Parent $dst))
            Copy-Item -LiteralPath $bf.FullName -Destination $dst -Force
        } catch {
            $errCount++
            Write-Log "LaunchBox restore: failed to restore $($bf.FullName) -- $_"
        }
    }

    if ($errCount -gt 0) {
        Write-Host ("  ERROR: {0} file(s) could not be restored. The restore was not completed." -f $errCount) -ForegroundColor Red
        Write-Log "LaunchBox restore: failed with $errCount error(s) from $($selected.Name)"
        return [pscustomobject]@{ Succeeded = $false; Name = $selected.Name; ErrorCount = $errCount }
    }
    Write-Host "  Restore complete." -ForegroundColor Green
    Write-Log "LaunchBox restore: completed from $($selected.Name), no errors."
    return [pscustomobject]@{ Succeeded = $true; Name = $selected.Name; ErrorCount = 0 }
}

# Finds the existing TeknoParrot <Emulator> entry in Emulators.xml by
# Title (so re-runs, and machines that already configured this by hand,
# Returns the InnerText of a named child element, or "" if the child is
# absent -- guards against malformed/legacy LaunchBox XML entries that may
# be missing a field this script expects, rather than crashing the whole
# run on one unexpected node.
function Get-XmlChildText {
    param([System.Xml.XmlNode]$node, [string]$childName)
    $child = $node.SelectSingleNode($childName)
    if ($null -eq $child) { return "" }
    return $child.InnerText
}

# Sets a child element's text, creating the child first if it is
# unexpectedly missing (e.g. a cloned template from an older LaunchBox
# schema) -- a live write to LaunchBox's own database should never crash
# over one missing field.
function Set-XmlChildText {
    param([System.Xml.XmlNode]$node, [string]$childName, [string]$value)
    $child = $node.SelectSingleNode($childName)
    if ($null -eq $child) {
        $child = $node.OwnerDocument.CreateElement($childName)
        [void]$node.AppendChild($child)
    }
    $child.InnerText = $value
}

# =============================================================================
# POSTGRESQL DATABASE BACKUP/RESTORE
# =============================================================================

# Backs up every verified, existing Postgres database used by a registered
# profile. A query failure is not treated as an absent database. The result
# is explicit so the caller cannot proceed to profile writes after a partial
# backup.
function Backup-PostgresDatabases {
    param([string]$UserProfilesDir, [string]$SuperPasswordPlain)
    $failedDatabases = New-Object System.Collections.Generic.List[string]
    $failureDetails = New-Object System.Collections.Generic.List[string]
    $result = [ordered]@{
        Path = $null
        Succeeded = $true
        ExistingDatabaseCount = 0
        FailedDatabaseCount = 0
        FailedDatabases = @()
        FailureDetails = @()
    }
    if (-not (Test-PostgresInstalled)) { return [pscustomobject]$result }
    $names = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    $databaseGameLabels = @{}
    try {
        $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction Stop | Where-Object { $_.Directory.Name -ne 'FullBackup' } | Sort-Object Name)
        foreach ($pf in $profiles) {
            $dbName = ''
            $gameLabel = $pf.BaseName
            try {
                $doc = Read-Xml $pf.FullName
                if ($doc.GameProfile -and $doc.GameProfile.GameName) { $gameLabel = ([string]$doc.GameProfile.GameName).Trim() }
                if (-not $doc.GameProfile -or -not (Test-GameNeedsPostgres $doc)) { continue }
                $dbName = Get-PostgresFieldValue $doc 'DbName'
                if ([string]::IsNullOrWhiteSpace($dbName) -or -not (Test-SafePostgresDbName $dbName)) {
                    [void]$failedDatabases.Add(('{0} / {1}' -f $gameLabel, $pf.BaseName))
                    [void]$failureDetails.Add(('{0}: missing or unsafe database name.' -f $gameLabel))
                    continue
                }
                $databaseGameLabels[$dbName] = $gameLabel
                $state = Get-PostgresDatabaseState -DbName $dbName -SuperPasswordPlain $SuperPasswordPlain
                if ($state.Exists) { [void]$names.Add($dbName) }
            } catch {
                [void]$failedDatabases.Add(('{0} / {1}' -f $gameLabel, $dbName))
                [void]$failureDetails.Add(('{0} / {1}: {2}' -f $gameLabel, $dbName, $_.Exception.Message))
            }
        }
    } catch {
        [void]$failedDatabases.Add('UserProfiles enumeration')
        [void]$failureDetails.Add(('Could not enumerate game profiles: {0}' -f $_.Exception.Message))
    }

    if ($names.Count -eq 0) {
        $result.Succeeded = ($failedDatabases.Count -eq 0)
        $result.FailedDatabaseCount = $failedDatabases.Count
        $result.FailedDatabases = @($failedDatabases.ToArray())
        $result.FailureDetails = @($failureDetails.ToArray())
        return [pscustomobject]$result
    }
    if ($failedDatabases.Count -gt 0) { $result.Succeeded = $false }
    $result.ExistingDatabaseCount = $names.Count
    $result.Path = Join-Path (Join-Path $PSScriptRoot 'PostgresBackups') ((Get-Date).ToString('yyyy-MM-dd_HH-mm-ss_fff'))
    [void][System.IO.Directory]::CreateDirectory($result.Path)
    $pgDumpExe = Join-Path $script:PostgresBinDir 'pg_dump.exe'
    if (-not (Test-Path -LiteralPath $pgDumpExe -PathType Leaf)) {
        $result.Succeeded = $false
        foreach ($dbName in @($names | Sort-Object)) {
            $label = if ($databaseGameLabels.ContainsKey($dbName)) { $databaseGameLabels[$dbName] } else { $dbName }
            [void]$failedDatabases.Add(('{0} / {1}' -f $label, $dbName))
            [void]$failureDetails.Add(('{0}: pg_dump.exe was not found at {1}.' -f $dbName, $pgDumpExe))
        }
    } else {
        $pgpassFile = $null
        $previousPgPassFile = $null
        try {
            $pgpassFile = New-PostgresPgPassFile -Password $SuperPasswordPlain
            $previousPgPassFile = Set-PostgresPgPassFileEnvironment -Path $pgpassFile
            foreach ($dbName in @($names | Sort-Object)) {
                $destFile = Join-Path $result.Path ($dbName + '.backup')
                $dumpOutput = (& $pgDumpExe -U postgres -h 127.0.0.1 -p 5432 -F c -f $destFile $dbName 2>&1 | Out-String).Trim()
                $exitCode = $LASTEXITCODE
                if ($exitCode -ne 0 -or -not (Test-Path -LiteralPath $destFile -PathType Leaf) -or (Get-Item -LiteralPath $destFile).Length -eq 0) {
                    $result.Succeeded = $false
                    $label = if ($databaseGameLabels.ContainsKey($dbName)) { $databaseGameLabels[$dbName] } else { $dbName }
                    [void]$failedDatabases.Add(('{0} / {1}' -f $label, $dbName))
                    [void]$failureDetails.Add(('{0}: pg_dump exit code {1}. {2}' -f $dbName, $exitCode, $dumpOutput))
                } else {
                    Write-Log "Postgres backup: verified database backup for $dbName at $($result.Path)."
                }
            }
        } catch {
            $result.Succeeded = $false
            [void]$failureDetails.Add(('Backup execution failed: {0}' -f $_.Exception.Message))
        } finally {
            if ($previousPgPassFile -ne $null -or $pgpassFile) { Restore-PostgresPgPassFileEnvironment -PreviousValue $previousPgPassFile }
            if ($pgpassFile) { Remove-PostgresPgPassFile -Path $pgpassFile -ThrowOnFailure }
        }
    }
    $result.FailedDatabaseCount = $failedDatabases.Count
    $result.FailedDatabases = @($failedDatabases.ToArray())
    $result.FailureDetails = @($failureDetails.ToArray())
    if (-not $result.Succeeded) { Write-Log ("Postgres backup incomplete. FailedDatabases={0}; FailureDetails={1}" -f ($result.FailedDatabases -join '|'), ($result.FailureDetails -join '|')) }
    return [pscustomobject]$result
}

# Restores a previous Postgres database backup. Mirrors
# Invoke-RestoreLaunchBoxBackup's UX (list by timestamp, confirm with YES)
# so all three restore flows under the Restore backup menu feel like the same feature.
# Necessarily destructive to each restored database's CURRENT content --
# warned clearly before proceeding. Requires PostgreSQL to already be
# installed and running (it always will be if there's anything to
# restore).
function Invoke-RestorePostgresBackup {
    $backupRoot = Join-Path $PSScriptRoot "PostgresBackups"
    if (-not (Test-Path -LiteralPath $backupRoot)) {
        Write-Host "  No Postgres database backups found in: $backupRoot" -ForegroundColor Yellow
        return
    }

    $backups = @(Get-ChildItem -LiteralPath $backupRoot -Directory -ErrorAction SilentlyContinue | Sort-Object Name -Descending)
    if ($backups.Count -eq 0) {
        Write-Host "  No Postgres backup folders found." -ForegroundColor Yellow
        return
    }

    Write-Host ""
    Write-Host "  Available Postgres database backups (most recent first):" -ForegroundColor Cyan
    for ($i = 0; $i -lt $backups.Count; $i++) {
        $b = $backups[$i]
        $dbFiles = @(Get-ChildItem -LiteralPath $b.FullName -Filter "*.backup" -File -ErrorAction SilentlyContinue)
        $names = ($dbFiles | ForEach-Object { $_.BaseName }) -join ', '
        Write-Host ("    {0,3})  {1}   ({2} database(s): {3})" -f ($i + 1), $b.Name, $dbFiles.Count, $names)
    }
    Write-Host ""
    $choice = (Read-HostSafe "  Enter number to restore, or Enter to cancel")
    if ([string]::IsNullOrWhiteSpace($choice)) {
        Write-Host "  Restore cancelled." -ForegroundColor DarkGray
        Write-Log "Postgres restore: cancelled by user."
        return
    }
    if ($choice -notmatch '^\d+$' -or $choice.Length -gt 9 -or [int]$choice -lt 1 -or [int]$choice -gt $backups.Count) {
        Write-Host "  Invalid selection. Restore cancelled." -ForegroundColor Yellow
        Write-Log "Postgres restore: invalid selection '$choice'."
        return
    }
    $selected = $backups[[int]$choice - 1]
    $backupFiles = @(Get-ChildItem -LiteralPath $selected.FullName -Filter "*.backup" -File -ErrorAction SilentlyContinue)
    if ($backupFiles.Count -eq 0) {
        Write-Host "  ERROR: Selected backup contains no .backup files -- restore aborted." -ForegroundColor Red
        return
    }

    Write-Host ""
    Write-Host ("  Selected : {0}  ({1} database(s))" -f $selected.Name, $backupFiles.Count) -ForegroundColor Yellow
    Write-Host "  WARNING  : This will REPLACE the current content of each database" -ForegroundColor Yellow
    Write-Host "             listed above with this backup's snapshot." -ForegroundColor Yellow
    $confirm = (Read-HostSafe "  Type YES to confirm")
    if ($confirm.ToUpper() -ne "YES") {
        Write-Host "  Restore cancelled." -ForegroundColor DarkGray
        Write-Log "Postgres restore: user did not confirm."
        return
    }

    if (-not (Test-PostgresInstalled)) {
        Write-Host "  ERROR: PostgreSQL is not installed -- nothing to restore into." -ForegroundColor Red
        Write-Log "Postgres restore: aborted -- PostgreSQL not installed."
        return
    }

    $superPwPlain = $null
    if ($postgresSuperPasswordEncrypted) {
        try {
            $secure = ConvertTo-SecureString -String $postgresSuperPasswordEncrypted
            $savedPwPlain = ConvertFrom-SecureStringPlain $secure
            if (Test-PostgresPassword $savedPwPlain) { $superPwPlain = $savedPwPlain }
        } catch {
            Write-Log "Postgres restore: could not decrypt saved password -- $_"
        }
    }
    if (-not $superPwPlain) {
        $superPwSecure = Read-Host "  Enter your PostgreSQL database password" -AsSecureString
        $typedPwPlain  = ConvertFrom-SecureStringPlain $superPwSecure
        if (-not (Test-PostgresPassword $typedPwPlain)) {
            Write-Host "  ERROR: That password did not work against your PostgreSQL server." -ForegroundColor Red
            Write-Log "Postgres restore: aborted -- password verification failed."
            return
        }
        $superPwPlain = $typedPwPlain
    }

    $dropdbExe = Join-Path $script:PostgresBinDir "dropdb.exe"
    $errCount = 0
    try {
        foreach ($bf in $backupFiles) {
            $dbName = $bf.BaseName
            if (-not (Test-SafePostgresDbName $dbName)) { $errCount++; continue }
            $pgpassFile = New-PostgresPgPassFile -Password $superPwPlain
            $previousPgPassFile = $null
            try {
                $previousPgPassFile = Set-PostgresPgPassFileEnvironment -Path $pgpassFile
                & $dropdbExe -U postgres -h 127.0.0.1 -p 5432 --if-exists $dbName 2>&1 | Out-Null
            } finally {
                Restore-PostgresPgPassFileEnvironment -PreviousValue $previousPgPassFile
                Remove-PostgresPgPassFile -Path $pgpassFile -ThrowOnFailure
            }
            $encoding = if ($dbName -eq 'GameDB06') { 'UTF8' } else { 'SQL_ASCII' }
            if (New-PostgresDatabaseFromBackup -DbName $dbName -Encoding $encoding -BackupFile $bf.FullName -SuperPasswordPlain $superPwPlain) {
                Write-Host ("    Restored: {0}" -f $dbName) -ForegroundColor Green
                Write-Log "Postgres restore: restored $dbName from $($bf.FullName)"
            } else {
                Write-Host ("    FAILED  : {0}" -f $dbName) -ForegroundColor Red
                Write-Log "Postgres restore: FAILED to restore $dbName"
                $errCount++
            }
        }
    } finally {
        $superPwPlain = $null
        $savedPwPlain = $null
        $typedPwPlain = $null
        $secure = $null
        $superPwSecure = $null
        [GC]::Collect()
    }

    if ($errCount -gt 0) {
        Write-Host ("  ERROR: {0} database(s) could not be restored. The restore was not completed." -f $errCount) -ForegroundColor Red
        Write-Log "Postgres restore: failed with $errCount database error(s)."
        return [pscustomobject]@{ Succeeded = $false; ErrorCount = $errCount }
    }
    Write-Host "  Restore complete." -ForegroundColor Green
    return [pscustomobject]@{ Succeeded = $true; ErrorCount = 0 }
}

# never get a duplicate), or creates one using field values verified
# against a real, working LaunchBox installation. $emulatorsDoc is modified
# in place but not saved -- the caller saves once after all changes for
# this run are made. Returns the Emulator's ID (GUID string).
function Get-OrCreateLaunchBoxEmulator {
    param([System.Xml.XmlDocument]$emulatorsDoc, [string]$tpRoot, [string]$lbRoot)

    $emulatorNodes = @($emulatorsDoc.SelectNodes("/LaunchBox/Emulator"))
    $existing = $emulatorNodes | Where-Object { (Get-XmlChildText $_ "Title") -eq "TeknoParrot" } | Select-Object -First 1
    if ($existing) {
        $existingId = Get-XmlChildText $existing "ID"
        if ($existingId) { return $existingId }
        # Matched by title but missing an ID -- treat as malformed and fall
        # through to creating a fresh, well-formed entry instead of
        # returning an empty emulator ID that would break every downstream
        # Game/EmulatorPlatform link.
    }

    $relAppPath = Get-RelativePath $lbRoot (Join-Path $tpRoot "TeknoParrotUi.exe")
    $newId = [guid]::NewGuid().ToString()

    $fields = [ordered]@{
        ApplicationPath                      = $relAppPath
        CommandLine                          = "--profile=%romfile%.xml"
        DefaultPlatform                      = ""
        ID                                   = $newId
        Title                                = "TeknoParrot"
        NoQuotes                             = "true"
        NoSpace                              = "true"
        HideConsole                          = "true"
        FileNameWithoutExtensionAndPath      = "true"
        AutoHotkeyScript                     = ""
        AutoExtract                          = "false"
        UseStartupScreen                     = "true"
        HideAllNonExclusiveFullscreenWindows = "false"
        StartupLoadDelay                     = "25000"
        HideMouseCursorInGame                = "true"
        DisableShutdownScreen                = "false"
        AggressiveWindowHiding                = "false"
        UsePauseScreen                       = "false"
        PauseAutoHotkeyScript                = ""
        ResumeAutoHotkeyScript               = ""
        DefaultPauseSettingsPushed           = "true"
        SuspendProcessOnPause                = "true"
        ForcefulPauseScreenActivation        = "true"
        LoadStateAutoHotkeyScript            = ""
        SaveStateAutoHotkeyScript            = ""
        ResetAutoHotkeyScript                = ""
        SwapDiscsAutoHotkeyScript            = ""
        ExitAutoHotkeyScript                 = ""
        SkipVersionCheck                     = "false"
        LoginToCheevoOnGameLaunch            = "true"
        EnableHardcoreAchievements           = "true"
    }

    $emulatorNode = $emulatorsDoc.CreateElement("Emulator")
    foreach ($key in $fields.Keys) {
        $child = $emulatorsDoc.CreateElement($key)
        $child.InnerText = $fields[$key]
        [void]$emulatorNode.AppendChild($child)
    }
    [void]$emulatorsDoc.DocumentElement.AppendChild($emulatorNode)
    Write-Log "LaunchBox: created new Emulator entry for TeknoParrot (ID=$newId)"
    return $newId
}

# Finds an existing <Platform> definition in Platforms.xml by name (Arcade
# always exists already; "TeknoParrot" or a custom name might not), or
# creates a minimal one. ScrapeAs=Arcade and DisableAutoImport=true are not
# arbitrary -- TeknoParrot is not a real platform as far as LaunchBox's own
# auto-import is concerned (confirmed via a LaunchBox forum admin post:
# "the platform is Arcade ... TeknoParrot ... won't work via the
# auto-import system right now ... a limitation by design"), so any
# platform this script manages must scrape as Arcade and stay excluded
# from LaunchBox's own auto-import sweeps. No other metadata (notes,
# release date, BigBox theme, etc.) is fabricated -- left blank for the
# user to fill in via LaunchBox's own platform editor if they want to.
# Returns $true if a new platform was created, $false if one already existed.
function Get-OrCreateLaunchBoxPlatform {
    param([System.Xml.XmlDocument]$platformsListDoc, [string]$platformName, [string]$tpRoot, [string]$lbRoot)

    $platformNodes = @($platformsListDoc.SelectNodes("/LaunchBox/Platform"))
    $existing = $platformNodes | Where-Object { (Get-XmlChildText $_ "Name") -eq $platformName } | Select-Object -First 1
    if ($existing) { return $false }

    $relFolder = Get-RelativePath $lbRoot (Join-Path $tpRoot "GameProfiles")

    $fields = [ordered]@{
        Category                = ""
        LocalDbParsed           = "true"
        Name                    = $platformName
        LastSelectedChild       = ""
        ReleaseDate             = ""
        Developer               = ""
        Manufacturer            = ""
        Cpu                     = ""
        Memory                  = ""
        Graphics                = ""
        Sound                   = ""
        Display                 = ""
        Media                   = ""
        MaxControllers          = ""
        Folder                  = $relFolder
        Notes                   = ""
        VideosFolder            = ""
        FrontImagesFolder       = ""
        BackImagesFolder        = ""
        ClearLogoImagesFolder   = ""
        FanartImagesFolder      = ""
        ScreenshotImagesFolder  = ""
        BannerImagesFolder      = ""
        SteamBannerImagesFolder = ""
        ManualsFolder           = ""
        MusicFolder             = ""
        ScrapeAs                = "Arcade"
        VideoPath               = ""
        ImageType               = ""
        SortTitle                = ""
        LastGameId              = ""
        BigBoxView              = ""
        BigBoxTheme             = ""
        AndroidThemeVideoPath   = ""
        HideInBigBox            = "false"
        DisableAutoImport       = "true"
    }

    $platformNode = $platformsListDoc.CreateElement("Platform")
    foreach ($key in $fields.Keys) {
        $child = $platformsListDoc.CreateElement($key)
        $child.InnerText = $fields[$key]
        [void]$platformNode.AppendChild($child)
    }
    [void]$platformsListDoc.DocumentElement.AppendChild($platformNode)
    Write-Log "LaunchBox: created new Platform '$platformName'"
    return $true
}

# Ensures an <EmulatorPlatform> link exists between the TeknoParrot
# emulator and a platform. $isNewPlatform controls Default -- true only
# when the platform itself was just created (nothing else could already
# depend on its default emulator); false when linking into an existing
# platform like Arcade, so an existing default emulator there is never
# silently overridden.
function Add-LaunchBoxEmulatorPlatformLink {
    param([System.Xml.XmlDocument]$emulatorsDoc, [string]$emulatorId, [string]$platformName, [bool]$isNewPlatform)

    $linkNodes = @($emulatorsDoc.SelectNodes("/LaunchBox/EmulatorPlatform"))
    $existing = $linkNodes | Where-Object {
        (Get-XmlChildText $_ "Emulator") -eq $emulatorId -and
        (Get-XmlChildText $_ "Platform") -eq $platformName
    } | Select-Object -First 1
    if ($existing) { return }

    $fields = [ordered]@{
        Emulator           = $emulatorId
        Platform           = $platformName
        CommandLine        = ""
        Default            = if ($isNewPlatform) { "true" } else { "false" }
        M3uDiscLoadEnabled = "false"
        AutoExtract        = "false"
    }
    $linkNode = $emulatorsDoc.CreateElement("EmulatorPlatform")
    foreach ($key in $fields.Keys) {
        $child = $emulatorsDoc.CreateElement($key)
        $child.InnerText = $fields[$key]
        [void]$linkNode.AppendChild($child)
    }
    [void]$emulatorsDoc.DocumentElement.AppendChild($linkNode)
    Write-Log "LaunchBox: linked TeknoParrot emulator to platform '$platformName'"
}

# Hardcoded skeleton used only when the target platform file has zero
# existing <Game> entries to clone a template from (e.g. a platform this
# script just created). Field values match a real entry captured from a
# working LaunchBox installation, with every scraped/stateful field
# blanked -- see New-LaunchBoxGameEntry's generic reset logic for why most
# fields here are intentionally empty/false/0: this script has no way to
# populate real box art, genre, developer, etc. for an arbitrary game, so
# new entries are left for the user to fill in later via LaunchBox's own
# "search for metadata" feature.
$script:LaunchBoxGameSkeletonFields = [ordered]@{
    GogAppId = ""; OriginAppId = ""; OriginInstallPath = ""; VideoPath = ""; ThemeVideoPath = "";
    ApplicationPath = ""; CommandLine = ""; Completed = "false"; ConfigurationCommandLine = "";
    ConfigurationPath = ""; DateAdded = ""; DateModified = ""; Developer = ""; DosBoxConfigurationPath = "";
    Emulator = ""; Favorite = "false"; ID = ""; ManualPath = ""; MusicPath = ""; Notes = ""; Platform = "";
    Publisher = ""; Rating = ""; ReleaseDate = ""; RootFolder = ""; ScummVMAspectCorrection = "false";
    ScummVMFullscreen = "false"; ScummVMGameDataFolderPath = ""; ScummVMGameType = ""; SortTitle = "";
    Source = ""; StarRatingFloat = "0"; StarRating = "0"; CommunityStarRating = "0";
    CommunityStarRatingTotalVotes = "0"; Status = ""; DatabaseID = ""; WikipediaURL = ""; Title = "";
    UseDosBox = "false"; UseScummVM = "false"; Version = ""; Series = ""; PlayMode = ""; Region = "";
    PlayCount = "0"; PlayTime = "0"; Portable = "false"; Hide = "false"; Broken = "false"; CloneOf = "";
    Genre = ""; MissingVideo = "true"; MissingBoxFrontImage = "true"; MissingScreenshotImage = "true";
    MissingMarqueeImage = "true"; MissingClearLogoImage = "true"; MissingBackgroundImage = "true";
    MissingBox3dImage = "true"; MissingCartImage = "true"; MissingCart3dImage = "true"; MissingManual = "true";
    MissingBannerImage = "true"; MissingMusic = "true"; UseStartupScreen = "false";
    HideAllNonExclusiveFullscreenWindows = "false"; StartupLoadDelay = "0"; HideMouseCursorInGame = "false";
    DisableShutdownScreen = "false"; AggressiveWindowHiding = "false";
    OverrideDefaultStartupScreenSettings = "false"; UsePauseScreen = "false"; PauseAutoHotkeyScript = "";
    ResumeAutoHotkeyScript = ""; OverrideDefaultPauseScreenSettings = "false"; SuspendProcessOnPause = "false";
    ForcefulPauseScreenActivation = "false"; LoadStateAutoHotkeyScript = ""; SaveStateAutoHotkeyScript = "";
    ResetAutoHotkeyScript = ""; SwapDiscsAutoHotkeyScript = ""; CustomDosBoxVersionPath = "";
    ReleaseType = ""; MaxPlayers = "0"; VideoUrl = ""; RetroAchievementsBeatenSoftcore = "false";
    RetroAchievementsBeatenHardcore = "false"; HasCloudSynced = "false"; Progress = "Not Started / Unplayed";
}

# Identity fields every new entry sets explicitly -- everything else is
# either a generic type-pattern reset (cloned-template path) or already
# blank/neutral (hardcoded-skeleton path).
$script:LaunchBoxGameIdentityFields = @('ID', 'Title', 'Platform', 'Emulator', 'ApplicationPath', 'CommandLine', 'DateAdded', 'DateModified')

# Builds one <Game> XML element for a TeknoParrot profile and appends it to
# $platformGamesDoc. If the platform file already has an existing <Game>
# entry, clones it as a template and generically resets every non-identity
# field by type (Missing* -> true; true/false -> false; numeric -> 0;
# anything else non-empty -> blank) rather than hand-maintaining a list of
# ~80 field names -- this adapts automatically to whatever LaunchBox
# version/schema the user actually has, since it is their own real data.
# Falls back to the hardcoded skeleton above only when there is no
# existing entry to clone from. Returns $true if a new entry was created,
# $false if one already exists for this profile (matched by
# ApplicationPath) -- re-runs never duplicate or touch a user's existing
# favorites/playtime for a game they already have.
function New-LaunchBoxGameEntry {
    param(
        [System.Xml.XmlDocument]$platformGamesDoc,
        [string]$relProfilePath,
        [string]$title,
        [string]$platformName,
        [string]$emulatorId
    )

    $gameNodes = @($platformGamesDoc.SelectNodes("/LaunchBox/Game"))
    $already = $gameNodes | Where-Object { (Get-XmlChildText $_ "ApplicationPath") -eq $relProfilePath } | Select-Object -First 1
    if ($already) { return $false }

    $now = (Get-Date).ToString("yyyy-MM-ddTHH:mm:ss.fffffffzzz")

    if ($gameNodes.Count -gt 0) {
        $template = $gameNodes[0]
        $newNode  = $template.CloneNode($true)
        foreach ($child in @($newNode.ChildNodes)) {
            $name = $child.Name
            if ($script:LaunchBoxGameIdentityFields -contains $name) { continue }
            if ($name -like 'Missing*') { $child.InnerText = 'true'; continue }
            if ([string]::IsNullOrEmpty($child.InnerText)) { continue }
            if ($child.InnerText -eq 'true' -or $child.InnerText -eq 'false') { $child.InnerText = 'false'; continue }
            if ($child.InnerText -match '^-?\d+(\.\d+)?$') { $child.InnerText = '0'; continue }
            $child.InnerText = ''
        }
    } else {
        $newNode = $platformGamesDoc.CreateElement("Game")
        foreach ($key in $script:LaunchBoxGameSkeletonFields.Keys) {
            $child = $platformGamesDoc.CreateElement($key)
            $child.InnerText = $script:LaunchBoxGameSkeletonFields[$key]
            [void]$newNode.AppendChild($child)
        }
    }

    Set-XmlChildText $newNode "ID"              ([guid]::NewGuid().ToString())
    Set-XmlChildText $newNode "Title"           $title
    Set-XmlChildText $newNode "Platform"        $platformName
    Set-XmlChildText $newNode "Emulator"        $emulatorId
    Set-XmlChildText $newNode "ApplicationPath" $relProfilePath
    Set-XmlChildText $newNode "CommandLine"     ""
    Set-XmlChildText $newNode "DateAdded"       $now
    Set-XmlChildText $newNode "DateModified"    $now

    [void]$platformGamesDoc.DocumentElement.AppendChild($newNode)
    return $true
}

# Orchestrates a full direct-write pass: backs up the files about to
# change, creates/reuses the TeknoParrot Emulator entry, creates/reuses
# each target Platform, links them, and adds a <Game> entry for every
# registered TeknoParrot profile that doesn't already have one in that
# platform file. $platformNames is one or two platform display names (two
# only for the "Both Arcade and a dedicated platform" choice). All targets
# either succeed together or nothing is saved -- never a half-written state
# where some platform files reflect new games and Emulators.xml/
# Platforms.xml do not. Returns @{ Results = <name->count>; BackupPath =
# <path> } on success, or $null if refused/failed before anything changed.
function Invoke-LaunchBoxDirectWrite {
    param([string]$userProfilesDir, [string]$tpRoot, [string]$lbRoot, [string[]]$platformNames)

    if (Test-LaunchBoxRunning) {
        Write-Host "  ERROR: LaunchBox or BigBox is currently running." -ForegroundColor Red
        Write-Host "  Close it completely, then try again." -ForegroundColor Yellow
        Write-Log "LaunchBox direct-write: aborted -- LaunchBox/BigBox is running."
        return $null
    }

    $dataDir          = Join-Path $lbRoot "Data"
    $platformsDir     = Join-Path $dataDir "Platforms"
    $emulatorsXmlPath = Join-Path $dataDir "Emulators.xml"
    $platformsXmlPath = Join-Path $dataDir "Platforms.xml"

    if (-not (Test-Path -LiteralPath $emulatorsXmlPath) -or -not (Test-Path -LiteralPath $platformsXmlPath)) {
        Write-Host "  ERROR: Could not find Emulators.xml / Platforms.xml under $dataDir" -ForegroundColor Red
        Write-Log "LaunchBox direct-write: aborted -- Data files not found under $dataDir"
        return $null
    }

    # Resolve and sanitize the platform file path for every target up
    # front, refusing the whole operation if any name is unsafe -- never
    # partially write some platforms and refuse others.
    $platformFiles = [ordered]@{}
    foreach ($name in $platformNames) {
        $safeName = Get-SafeLaunchBoxPlatformFileName $name
        $filePath = Join-Path $platformsDir "$safeName.xml"
        if (-not (Test-PathInside $filePath $platformsDir)) {
            Write-Host "  ERROR: '$name' is not a valid platform name." -ForegroundColor Red
            Write-Log "LaunchBox direct-write: aborted -- unsafe platform name '$name'"
            return $null
        }
        $platformFiles[$name] = $filePath
    }

    $relBackupFiles = New-Object System.Collections.ArrayList
    [void]$relBackupFiles.Add("Data\Emulators.xml")
    [void]$relBackupFiles.Add("Data\Platforms.xml")
    foreach ($name in $platformFiles.Keys) {
        [void]$relBackupFiles.Add((Get-RelativePath $lbRoot $platformFiles[$name]))
    }
    $backupPath = Backup-LaunchBoxFiles -lbRoot $lbRoot -relativeFiles $relBackupFiles
    if (-not $backupPath) {
        Write-Host "  ERROR: Could not back up LaunchBox files -- aborting without making changes." -ForegroundColor Red
        Write-Host "  The script will not write to LaunchBox without a successful backup first." -ForegroundColor Red
        return $null
    }

    $emulatorsDoc     = Read-Xml $emulatorsXmlPath
    $platformsListDoc = Read-Xml $platformsXmlPath
    $emulatorId       = Get-OrCreateLaunchBoxEmulator -emulatorsDoc $emulatorsDoc -tpRoot $tpRoot -lbRoot $lbRoot

    $files = Get-ChildItem -LiteralPath $userProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue |
                 Where-Object { $_.Directory.Name -ne "FullBackup" }

    $results      = [ordered]@{}
    $platformDocs = [ordered]@{}

    foreach ($name in $platformFiles.Keys) {
        $filePath = $platformFiles[$name]
        $isNewFile = -not (Test-Path -LiteralPath $filePath)

        $platformGamesDoc = if ($isNewFile) {
            $doc = New-Object System.Xml.XmlDocument
            [void]$doc.AppendChild($doc.CreateXmlDeclaration("1.0", $null, "yes"))
            [void]$doc.AppendChild($doc.CreateElement("LaunchBox"))
            $doc
        } else {
            Read-Xml $filePath
        }

        $platformCreated = Get-OrCreateLaunchBoxPlatform -platformsListDoc $platformsListDoc -platformName $name -tpRoot $tpRoot -lbRoot $lbRoot
        Add-LaunchBoxEmulatorPlatformLink -emulatorsDoc $emulatorsDoc -emulatorId $emulatorId -platformName $name -isNewPlatform $platformCreated

        $added = 0
        foreach ($f in $files) {
            try {
                $profileDoc = Read-Xml $f.FullName
                if ($null -eq $profileDoc.GameProfile) { continue }
                $gpNode   = $profileDoc.GameProfile.SelectSingleNode("GamePath")
                $gamePath = if ($gpNode) { $gpNode.InnerText } else { "" }
                if (-not $gamePath -or -not (Test-Path -LiteralPath $gamePath)) { continue }

                $descNode = $profileDoc.GameProfile.SelectSingleNode("Description")
                if ($descNode -and -not [string]::IsNullOrWhiteSpace($descNode.InnerText)) {
                    $title = $descNode.InnerText.Trim()
                } else {
                    $title = [regex]::Replace($f.BaseName, '(?<=[a-z])(?=[A-Z])', ' ')
                }

                $relProfilePath = Get-RelativePath $lbRoot $f.FullName
                $createdGame = New-LaunchBoxGameEntry -platformGamesDoc $platformGamesDoc -relProfilePath $relProfilePath `
                                   -title $title -platformName $name -emulatorId $emulatorId
                if ($createdGame) { $added++ }
            } catch {
                Write-Log "LaunchBox direct-write: skipped $($f.Name) for platform '$name' -- $_"
            }
        }

        $platformDocs[$name] = @{ Doc = $platformGamesDoc; Path = $filePath }
        $results[$name] = $added
    }

    try {
        Save-Xml $emulatorsDoc $emulatorsXmlPath
        Save-Xml $platformsListDoc $platformsXmlPath
        foreach ($name in $platformDocs.Keys) {
            Save-Xml $platformDocs[$name].Doc $platformDocs[$name].Path
        }
    } catch {
        Write-Host "  ERROR: Failed while saving LaunchBox files -- $_" -ForegroundColor Red
        Write-Host "  A backup from before any changes is at: $backupPath" -ForegroundColor Yellow
        Write-Log "LaunchBox direct-write: FAILED during save -- $_"
        return $null
    }

    Write-Log "LaunchBox direct-write: complete. Backup at $backupPath"
    return @{ Results = $results; BackupPath = $backupPath }
}

# =============================================================================
# HYPERSPIN 2 JSON EXPORT  (optional)
# =============================================================================
# Adds registered TeknoParrot games to HyperSpin 2's game list JSON.
# HyperSpin 2 stores one JSON file per system under <dataPath>\games\.
# The TeknoParrot file is identified by looking for one whose games have
# .xml ROM entries (the format TeknoParrot uses for its profile files).
# Games already present (matched by fileName) are never duplicated.
# The existing file is backed up before any write.
function Export-HyperSpinJson {
    param([string]$userProfilesDir, [string]$hsDataPath)

    # Refuse to write if HyperSpin is running -- check first so we fail fast
    # before doing any file I/O rather than processing everything and then failing.
    if (Get-Process -Name "HyperSpin" -ErrorAction SilentlyContinue) {
        Write-Host "  ERROR: HyperSpin is running. Close it before updating the game list." -ForegroundColor Red
        Write-Log "HyperSpin export: aborted -- HyperSpin is running"
        return -1
    }

    # Locate and parse emulators.json
    $emuPath = Join-Path $hsDataPath "emulators.json"
    if (-not (Test-Path -LiteralPath $emuPath)) {
        Write-Host "  ERROR: emulators.json not found: $emuPath" -ForegroundColor Red
        Write-Log "HyperSpin export: emulators.json not found at $emuPath"
        return -1
    }
    try {
        $emuList = Get-Content -LiteralPath $emuPath -Raw | ConvertFrom-Json
    } catch {
        Write-Host "  ERROR: Could not parse emulators.json: $_" -ForegroundColor Red
        Write-Log "HyperSpin export: failed to parse emulators.json -- $_"
        return -1
    }

    # Find TeknoParrot entry by title. Strip spaces and punctuation before
    # comparing so "Tekno Parrot", "TeknoParrot", "teknoparrot" all match.
    $tpEmu = $emuList | Where-Object {
        $_.title -and ($_.title -replace '[^a-zA-Z0-9]', '') -ieq 'TeknoParrot'
    } | Select-Object -First 1
    if (-not $tpEmu) {
        Write-Host "  ERROR: TeknoParrot emulator not found in emulators.json." -ForegroundColor Red
        Write-Host "  (Searched for any emulator whose title is 'TeknoParrot' after removing spaces/punctuation.)" -ForegroundColor DarkGray
        Write-Log "HyperSpin export: TeknoParrot not found in emulators.json"
        return -1
    }

    # Get the system GUID from the emulator entry directly. This means the export
    # works even when no TeknoParrot games have been added to HyperSpin 2 yet,
    # eliminating the "add one game manually first" prerequisite.
    $tpSystemGuid = [string]$tpEmu.id
    if ([string]::IsNullOrEmpty($tpSystemGuid)) {
        Write-Host "  WARNING: TeknoParrot emulator entry has no 'id' field in emulators.json." -ForegroundColor Yellow
        Write-Host "  HyperSpin cannot associate exported games with this emulator safely." -ForegroundColor Yellow
        Write-Host "  [F] Fix it (re-add TeknoParrot in HyperSpin, then retry)" -ForegroundColor Cyan
        Write-Host "  [A] Add anyway (empty systemId)" -ForegroundColor Yellow
        Write-Host "  [S] Skip export (default)" -ForegroundColor Cyan
        do {
            $missingIdChoice = (Read-HostSafe '  Choice (F/A/S)' -Default 'S').Trim().ToUpper()
            if ($missingIdChoice -eq 'F') {
                Write-Host "  Fix the TeknoParrot emulator entry in HyperSpin, then run export again." -ForegroundColor Yellow
                Write-Log "HyperSpin export: skipped because emulator id is missing; operator chose Fix."
                return -1
            }
            if ($missingIdChoice -eq 'S') {
                Write-Log "HyperSpin export: skipped because emulator id is missing; operator chose Skip."
                return 0
            }
            if ($missingIdChoice -notin @('A')) { Write-Host "  Enter F, A, or S." -ForegroundColor Yellow }
        } while ($missingIdChoice -notin @('A'))
        Write-Log "HyperSpin export: operator chose Add anyway with empty systemId."
    }

    # Locate the games folder; create it if HyperSpin 2 has not yet made it.
    $gamesDir = Join-Path $hsDataPath "games"
    if (-not (Test-Path -LiteralPath $gamesDir)) {
        try {
            [void][System.IO.Directory]::CreateDirectory($gamesDir)
            Write-Log "HyperSpin export: created games folder at $gamesDir"
        } catch {
            Write-Host "  ERROR: HyperSpin games folder not found and could not be created: $_" -ForegroundColor Red
            Write-Log "HyperSpin export: games folder missing and creation failed -- $_"
            return -1
        }
    }

    $tpGamesPath = $null
    $newFile     = $false   # true when we create the games file from scratch this run

    # Primary scan: match games files by system GUID. Works with 0 or more existing
    # games and is reliable regardless of the file's name.
    if ($tpSystemGuid) {
        foreach ($gf in (Get-ChildItem -LiteralPath $gamesDir -Filter "*.json" -File -ErrorAction SilentlyContinue)) {
            try {
                $sample    = Get-Content -LiteralPath $gf.FullName -Raw | ConvertFrom-Json
                $firstGame = if ($sample -is [array]) { $sample[0] } else { $sample }
                if ($firstGame -and [string]$firstGame.gameSystemId -eq $tpSystemGuid) {
                    $tpGamesPath = $gf.FullName; break
                }
            } catch { Write-Log "HyperSpin export: GUID scan skipped $($gf.Name) -- $_"; continue }
        }
    }

    # Fallback scan: match by .xml ROM entries (for installs where the emulator
    # entry has no id field, or the system GUID could not be determined).
    if (-not $tpGamesPath) {
        foreach ($gf in (Get-ChildItem -LiteralPath $gamesDir -Filter "*.json" -File -ErrorAction SilentlyContinue)) {
            try {
                $sample    = Get-Content -LiteralPath $gf.FullName -Raw | ConvertFrom-Json
                $firstGame = if ($sample -is [array]) { $sample[0] } else { $sample }
                # PS 5.1 may return a single-element JSON array as a bare PSCustomObject
                # rather than a one-element array.  Normalise roms to an array either way.
                $firstRom  = if ($firstGame -and $firstGame.roms -is [array]) { $firstGame.roms[0] } else { $firstGame.roms }
                if ($firstGame -and $firstRom -and $firstRom.name -like "*.xml") {
                    $tpGamesPath = $gf.FullName
                    if (-not $tpSystemGuid) { $tpSystemGuid = [string]$firstGame.gameSystemId }
                    break
                }
            } catch { Write-Log "HyperSpin export: ROM scan skipped $($gf.Name) -- $_"; continue }
        }
    }

    # No games file found -- create a new empty one named after the emulator title.
    # This eliminates the prerequisite of adding one game manually first.
    # Guard: only write when no file with that name already exists on disk -- a file
    # could exist outside the scanned paths (manual creation, alternate HS install).
    if (-not $tpGamesPath) {
        $safeName = ($tpEmu.title -replace '[^A-Za-z0-9\-\.]', '_').Trim('_')
        if ([string]::IsNullOrEmpty($safeName)) { $safeName = 'TeknoParrot' }
        $tpGamesPath = Join-Path $gamesDir "$safeName.json"
        if (-not (Test-Path -LiteralPath $tpGamesPath)) {
            try {
                [System.IO.File]::WriteAllText($tpGamesPath, '[]', (New-Object System.Text.UTF8Encoding $false))
                Write-Log "HyperSpin export: created new games file at $tpGamesPath"
                $newFile = $true
            } catch {
                Write-Host "  ERROR: Could not create TeknoParrot games file: $_" -ForegroundColor Red
                Write-Log "HyperSpin export: could not create games file -- $_"
                return -1
            }
        } else {
            Write-Log "HyperSpin export: using existing file at $tpGamesPath (found outside scanned paths)"
        }
    }

    # Load existing game list
    try {
        $existing = New-Object System.Collections.ArrayList
        # @() guard: ConvertFrom-Json returns $null for an empty "[]" in PS 5.1, not an empty array.
        foreach ($g in @(Get-Content -LiteralPath $tpGamesPath -Raw | ConvertFrom-Json)) {
            [void]$existing.Add($g)
        }
    } catch {
        Write-Host "  ERROR: Could not read games file: $_" -ForegroundColor Red
        Write-Log "HyperSpin export: failed to read games file -- $_"
        return -1
    }

    # Build set of already-known profile codes (case-insensitive)
    $known = @{}
    foreach ($g in $existing) {
        if ($g.fileName) { $known[$g.fileName.ToLower()] = $true }
    }

    # Iterate UserProfiles; add each game not already in HyperSpin
    $added   = 0
    $now     = (Get-Date).ToString("yyyy-MM-ddTHH:mm:ss.fffffff")
    $xmlFiles = Get-ChildItem -LiteralPath $userProfilesDir -Filter "*.xml" -File -ErrorAction SilentlyContinue |
                Where-Object { $_.Directory.Name -ne "FullBackup" }

    foreach ($pf in $xmlFiles) {
        $code = $pf.BaseName
        if ($known.ContainsKey($code.ToLower())) { continue }

        try {
            $doc    = Read-Xml $pf.FullName
            if ($null -eq $doc.GameProfile) { continue }
            $gpNode = $doc.GameProfile.SelectSingleNode("GamePath")
            if (-not $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { continue }
            if (-not (Test-Path -LiteralPath $gpNode.InnerText.Trim())) { continue }

            $descNode = $doc.GameProfile.SelectSingleNode("Description")
            $title = if ($descNode -and -not [string]::IsNullOrWhiteSpace($descNode.InnerText)) {
                $descNode.InnerText.Trim()
            } else {
                [regex]::Replace($code, '(?<=[a-z])(?=[A-Z])', ' ')
            }
        } catch { continue }

        $gameId = [System.Guid]::NewGuid().ToString()
        $romId  = [System.Guid]::NewGuid().ToString()

        $romObj = [ordered]@{
            id              = $romId
            name            = "$code.xml"
            size            = $null
            crc             = $null
            md5             = $null
            sha1            = $null
            relatedGameId   = $gameId
            relatedSystemId = $tpSystemGuid
            active          = $true
            createdDate     = $now
            modifiedDate    = $now
        }

        $gameObj = [ordered]@{
            id                            = $gameId
            name                          = $title
            description                   = $title
            releaseYear                   = $null
            releaseDate                   = $null
            cooperative                   = $false
            players                       = 1
            videoUrl                      = ""
            developer                     = ""
            publisher                     = ""
            esrb                          = "Not Rated"
            genres                        = ""
            gameSystemId                  = $tpSystemGuid
            fileName                      = $code
            releaseType                   = "Released"
            communityRating               = $null
            communityRatingCount          = $null
            wikipediaURL                  = ""
            cloneOf                       = $null
            referenceId                   = $null
            datFileId                     = $null
            metadataEnrichmentProvider    = $null
            metadataEnrichmentCandidateId = $null
            metadataEnrichmentAppliedDate = $null
            titleId                       = $null
            createdDate                   = $now
            modifiedDate                  = $now
            platform                      = $null
            maxPlayers                    = $null
            overview                      = $null
            databaseID                    = $null
            alternateNames                = $null
            roms                          = @($romObj)
            criticRatings                 = @()
        }

        [void]$existing.Add($gameObj)
        $known[$code.ToLower()] = $true
        $added++
    }

    if ($added -eq 0) {
        Write-Log "HyperSpin export: no new games to add (all already present)"
        return 0
    }

    # Back up the games file before writing, but only when it pre-existed.
    # A freshly-created empty file needs no backup.
    $backupPath = $null
    if (-not $newFile) {
        $backupPath = $tpGamesPath + ".bak_" + (Get-Date).ToString("yyyyMMdd_HHmmss")
        try {
            Copy-Item -LiteralPath $tpGamesPath -Destination $backupPath -ErrorAction Stop
        } catch {
            Write-Host "  ERROR: Could not back up games file: $_" -ForegroundColor Red
            Write-Log "HyperSpin export: backup failed -- $_"
            return -1
        }
    }

    try {
        $allGames = @($existing.ToArray())
        $json = ConvertTo-Json -InputObject @($allGames) -Depth 10
        # Atomic write: a crash mid-write must never leave $tpGamesPath
        # truncated, since on a pre-existing file there is no automatic
        # restore from the .bak_ copy above -- same pattern as Save-Xml,
        # including its Delete+Move fallback (File.Replace's 3-arg overload
        # throws "The path is empty" on some .NET builds even with a real
        # source/destination, so it cannot be relied on alone).
        $tmpPath = $tpGamesPath + ".tmp"
        [System.IO.File]::WriteAllText($tmpPath, $json, (New-Object System.Text.UTF8Encoding $false))
        try {
            [System.IO.File]::Replace($tmpPath, $tpGamesPath, $null)
        } catch {
            [System.IO.File]::Delete($tpGamesPath)
            [System.IO.File]::Move($tmpPath, $tpGamesPath)
        }
    } catch {
        Write-Host "  ERROR: Could not write games file: $_" -ForegroundColor Red
        Write-Log "HyperSpin export: write failed -- $_"
        return -1
    }

    $backupNote = if ($backupPath) { " (backup: $backupPath)" } else { "" }
    Write-Log "HyperSpin export: added $added game(s) to $tpGamesPath$backupNote"
    return $added
}

# =============================================================================
# THUMBNAIL DOWNLOAD  (optional, fetches game icons from GitHub)
# =============================================================================
# Downloads ProfileCode.png from the TeknoParrotUIThumbnails repository into
# <TeknoParrotRoot>\Icons\ -- the exact path TeknoParrotUI reads at startup.
# Only fetches icons that are absent; never overwrites existing files.
# Source: https://github.com/teknogods/TeknoParrotUIThumbnails
function Invoke-ThumbnailDownload {
    param([string]$userProfilesDir, [string]$tpRoot)

    $iconsDir = Join-Path $tpRoot "Icons"
    if (-not (Test-Path -LiteralPath $iconsDir)) {
        try {
            [void][System.IO.Directory]::CreateDirectory($iconsDir)
            Write-Log "Thumbnails: created Icons folder at $iconsDir"
        } catch {
            Write-Host "  ERROR: Could not create Icons folder: $_" -ForegroundColor Red
            Write-Log "Thumbnails: could not create Icons folder -- $_"
            return
        }
    }

    # Load registered profiles first -- needed for custom thumbnail validation below.
    $profiles = @(Get-ChildItem -LiteralPath $userProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue |
                  Where-Object { $_.Directory.Name -ne "FullBackup" })

    if ($profiles.Count -eq 0) {
        Write-Host "  No registered profiles found." -ForegroundColor DarkGray
        if (Test-Path -LiteralPath (Join-Path $PSScriptRoot "CustomThumbnails")) {
            Write-Host "  (Custom thumbnails in CustomThumbnails\ will be processed once games are registered.)" -ForegroundColor DarkGray
        }
        Write-Log "Thumbnails: no registered profiles -- custom copy and download skipped."
        return
    }

    # Build a case-insensitive lookup of all registered profile codes.
    $knownCodes = [System.Collections.Generic.HashSet[string]]::new(
        [System.StringComparer]::OrdinalIgnoreCase)
    foreach ($p in $profiles) { [void]$knownCodes.Add($p.BaseName) }

    # Copy custom thumbnails from Scripts\CustomThumbnails\ into the Icons folder.
    # Each file is validated against the registered profile codes first.
    $customThumbDir = Join-Path $PSScriptRoot "CustomThumbnails"
    if (Test-Path -LiteralPath $customThumbDir) {
        $customFiles = @(Get-ChildItem -LiteralPath $customThumbDir -Filter "*.png" -File -ErrorAction SilentlyContinue)
        if ($customFiles.Count -gt 0) {
            Write-Host ("  Found {0} of your own icon(s) in CustomThumbnails\." -f $customFiles.Count) -ForegroundColor Cyan
            $custCopied = 0; $custSkipped = 0; $custBadName = 0
            foreach ($cf in $customFiles) {
                $code = [System.IO.Path]::GetFileNameWithoutExtension($cf.Name)
                if (-not $knownCodes.Contains($code)) {
                    Write-Host ("  SKIPPED: CustomThumbnails\{0}" -f $cf.Name) -ForegroundColor Yellow
                    Write-Host ("           '{0}' doesn't match any of your registered games (profile code)." -f $code) -ForegroundColor Yellow
                    Write-Host "           Check TeknoParrot-Manager-controls.txt for the exact file name" -ForegroundColor Yellow
                    Write-Host "           to use, rename this PNG to match, then run this again." -ForegroundColor Yellow
                    Write-Log "Thumbnails: custom $($cf.Name) -- no matching profile code, skipped."
                    $custBadName++
                    continue
                }
                $dest = Join-Path $iconsDir $cf.Name
                if (Test-Path -LiteralPath $dest) {
                    $custSkipped++
                } else {
                    try {
                        Copy-Item -LiteralPath $cf.FullName -Destination $dest -ErrorAction Stop
                        Write-Log "Thumbnails: copied custom $($cf.Name)"
                        $custCopied++
                    } catch {
                        Write-Host ("  WARNING: Could not copy {0} -- {1}" -f $cf.Name, $_) -ForegroundColor Yellow
                        Write-Log "Thumbnails: failed to copy custom $($cf.Name) -- $_"
                    }
                }
            }
            if ($custCopied   -gt 0) { Write-Host ("  Added   : {0} of your own icon(s)."                  -f $custCopied)   -ForegroundColor Green   }
            if ($custSkipped  -gt 0) { Write-Host ("  Skipped : {0} -- that game already has an icon."     -f $custSkipped)  -ForegroundColor DarkGray }
            if ($custBadName  -gt 0) { Write-Host ("  Skipped : {0} -- file name didn't match a game (see above)." -f $custBadName)  -ForegroundColor Yellow   }
            Write-Log ("Thumbnails: custom copied={0} skipped={1} badName={2}" -f $custCopied, $custSkipped, $custBadName)
        }
    }

    $missing      = New-Object System.Collections.ArrayList
    $alreadyCount = 0
    foreach ($f in $profiles) {
        if (Test-Path -LiteralPath (Join-Path $iconsDir ($f.BaseName + ".png"))) {
            $alreadyCount++
        } else {
            [void]$missing.Add($f.BaseName)
        }
    }

    Write-Host ("  {0} profile(s): {1} already have an icon, {2} missing." -f `
        $profiles.Count, $alreadyCount, $missing.Count) -ForegroundColor Cyan

    if ($missing.Count -eq 0) {
        Write-Host "  All registered games already have icons. Nothing to download." -ForegroundColor Green
        Write-Log "Thumbnails: all $alreadyCount icons already present."
        return
    }

    $baseUrl = "https://raw.githubusercontent.com/teknogods/TeknoParrotUIThumbnails/master/Icons/"
    $fetched  = 0
    $notAvail = 0
    $failed   = 0
    $i        = 0
    $total    = $missing.Count

    foreach ($code in $missing) {
        $i++
        $destPath = Join-Path $iconsDir ($code + ".png")
        $url      = $baseUrl + [Uri]::EscapeDataString($code + ".png")
        Write-Host ("  [{0,3}/{1}] {2}" -f $i, $total, $code) -ForegroundColor DarkCyan -NoNewline
        $statusCode = 0
        if (Invoke-TpmDownload -DownloadUrl $url -DestinationPath $destPath -Label 'Thumbnails' -Quiet -LastStatusCode ([ref]$statusCode)) {
            Write-Host "  OK" -ForegroundColor Green
            Write-Log "Thumbnails: downloaded $code"
            $fetched++
        } elseif ($statusCode -eq 404) {
            Write-Host "  No icon in online pack" -ForegroundColor DarkGray
            Write-Log "Thumbnails: not in repo $code"
            $notAvail++
        } else {
            Write-Host "  FAILED" -ForegroundColor Red
            Write-Log "Thumbnails: FAILED $code"
            $failed++
        }
    }

    Write-Host ""
    $failSuffix = if ($failed -gt 0) { ", $failed failed" } else { "" }
    Write-Host ("  Thumbnails: {0} downloaded, {1} already had one, {2} have no icon in the online pack{3}." -f `
        $fetched, $alreadyCount, $notAvail, $failSuffix) -ForegroundColor Green
    Write-Log ("Thumbnails: fetched=$fetched alreadyPresent=$alreadyCount notAvail=$notAvail failed=$failed")

    if ($fetched -eq 0 -and $failed -eq 0 -and $notAvail -eq $total -and $total -gt 0) {
        Write-Host "  Some games do not currently have artwork in the online icon pack." -ForegroundColor Yellow
        Write-Host "  This does not mean the games are unsupported. You can add your own" -ForegroundColor Yellow
        Write-Host "  icons: create a CustomThumbnails\ folder next to this script and drop" -ForegroundColor Yellow
        Write-Host "  in a PNG per game, named to match its file in UserProfiles\ (see the" -ForegroundColor Yellow
        Write-Host "  tip above)." -ForegroundColor Yellow
        Write-Log "Thumbnails: all $total missing icon(s) were 404 -- likely no upstream icon for these specific games, not a download failure."
    }
}

# =============================================================================
# "WHAT TPM JUST DID" END-OF-RUN SUMMARY  (beginner clarity, RC4)
# =============================================================================
# Pure formatter -- takes the counts/flags the AutoSync/RegisterOnly run
# already computed and turns them into a plain-English recap plus a scope
# reminder. Adds no new automation or decisions; every input here is a value
# the run already had before this function existed. Kept separate from the
# "Done" counts block above it because that block is the precise numbers a
# returning user wants at a glance, while this is the "what does that mean"
# explanation a first-time user needs and an experienced user can skim past.
function Get-WhatTpmDidSummaryLines {
    param(
        [bool]$AutoSyncRan,
        [int]$ZipsExtracted = 0,
        [int]$NewlyRegistered = 0,
        [int]$AlreadyPresent = 0,
        [ValidateSet('Downloaded', 'Updated', 'Reused', 'NotConfigured')]
        [string]$DatAction = 'NotConfigured',
        [bool]$ThumbnailsRequested,
        [int]$ManualNeeded = 0,
        [int]$NotInTeknoParrot = 0,
        [int]$ControlsNeedAttention = 0
    )

    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add("  What TPM just did:")
    if ($AutoSyncRan) {
        [void]$lines.Add("    - Extracted $ZipsExtracted ZIP(s) from your source folder into the staging folder.")
    }
    [void]$lines.Add("    - Registered $NewlyRegistered new game(s) with TeknoParrot ($AlreadyPresent already registered from before).")
    switch ($DatAction) {
        'Downloaded' { [void]$lines.Add("    - Downloaded Eggman's TeknoParrot DAT file (an index used to match games -- not a game download).") }
        'Updated'    { [void]$lines.Add("    - Updated Eggman's TeknoParrot DAT file to the latest release.") }
        'Reused'     { [void]$lines.Add("    - Used your already-configured Eggman's TeknoParrot DAT file (no download this run).") }
        default      { [void]$lines.Add("    - No Eggman's TeknoParrot DAT file configured -- some games may need manual registration.") }
    }
    if ($ThumbnailsRequested) {
        [void]$lines.Add("    - Downloaded missing game icons (small box-art images, not game data).")
    } else {
        [void]$lines.Add("    - Skipped game icon download.")
    }
    $needsAttention = $ManualNeeded + $NotInTeknoParrot + $ControlsNeedAttention
    if ($needsAttention -gt 0) {
        [void]$lines.Add("    - $needsAttention item(s) still need your attention -- see ACTION REQUIRED below.")
    } else {
        [void]$lines.Add("    - Nothing needs manual attention from this run.")
    }
    [void]$lines.Add("")
    [void]$lines.Add("  TPM organizes, extracts, registers, and exports your games -- it does not")
    [void]$lines.Add("  provide games, install TeknoParrot itself, or guarantee that a game will")
    [void]$lines.Add("  boot or run fullscreen. If a game crashes or launches windowed once it")
    [void]$lines.Add("  starts, that is usually a TeknoParrot, game, or runtime setting -- not")
    [void]$lines.Add("  something TPM changed, unless TPM touched a related file this run (noted")
    [void]$lines.Add("  above).")

    return $lines
}

# =============================================================================
# CONTROLS STATUS REPORT
# =============================================================================
# Writes a snapshot of every registered game's control state to a persistent
# text file. Groups by control family, shows propagation source and any
# buttons still left manual. Overwrites the previous file on every call --
# it is a current-state view, not an append log.
# Returns the number of games written, or -1 on write failure.
function Write-ControlsStatus {
    param([string]$userProfilesDir, $pool, $propagationReports, [string]$outputPath)

    $poolCodes = @{}
    if ($null -ne $pool) { foreach ($s in $pool) { $poolCodes[$s.Code] = $true } }

    $reportMap = @{}
    if ($null -ne $propagationReports) {
        foreach ($r in $propagationReports) { $reportMap[$r.Code] = $r }
    }

    $files = @(Get-ChildItem -LiteralPath $userProfilesDir -Filter *.xml -File -ErrorAction SilentlyContinue |
               Where-Object { $_.Directory.Name -ne "FullBackup" } |
               Sort-Object BaseName)

    $rows = New-Object System.Collections.ArrayList
    foreach ($f in $files) {
        try { $doc = Read-Xml $f.FullName } catch { Write-Log "Write-ControlsStatus: could not parse $($f.Name) -- $_"; continue }
        if ($null -eq $doc.GameProfile) { continue }

        $family = Get-ProfileFamily $doc
        $btns   = @(Get-ButtonNodes $doc)
        $bound  = 0
        $manual = New-Object System.Collections.ArrayList
        foreach ($b in $btns) {
            if (Test-ButtonIsBound $b) {
                $bound++
            } else {
                $n = $b.SelectSingleNode("ButtonName")
                if ($n -and -not [string]::IsNullOrWhiteSpace($n.InnerText)) {
                    [void]$manual.Add($n.InnerText.Trim())
                }
            }
        }

        $status = ""; $reference = ""
        if ($poolCodes.ContainsKey($f.BaseName)) {
            $status = "REFERENCE"
            if ($reportMap.ContainsKey($f.BaseName) -and $reportMap[$f.BaseName].Status -eq "api-fixed-canonical") {
                $r = $reportMap[$f.BaseName]
                $status = "REFERENCE (Input API corrected)"; $reference = $r.Archetype
            }
        }
        elseif ($reportMap.ContainsKey($f.BaseName)) {
            $r = $reportMap[$f.BaseName]
            switch ($r.Status) {
                "bound"            { $status = "propagated"; $reference = $r.Archetype }
                "api-fixed"        { $status = "already bound (Input API corrected)"; $reference = $r.Archetype }
                "skipped-bound"    { $status = "already bound" }
                "skipped-override" { $status = "skipped (override)" }
                "no-archetype"     { $status = "no reference game" }
                "save-failed"      { $status = "save failed" }
                default            { $status = $r.Status }
            }
        }
        elseif ($bound -ge 5) { $status = "bound" }
        elseif ($bound -gt 0) { $status = "partial" }
        else                  { $status = "no controls" }

        # If the propagation run flagged directionally-mismatched slots on this
        # already-bound profile, surface them distinctly so they appear in the
        # controls-status output. The profile's bindings were never changed --
        # these slots need manual attention in TeknoParrot's own UI. See #17.
        $mismatch = New-Object System.Collections.ArrayList
        if ($reportMap.ContainsKey($f.BaseName) -and $reportMap[$f.BaseName].MismatchSlots) {
            foreach ($slot in ($reportMap[$f.BaseName].MismatchSlots -split ', ')) {
                [void]$mismatch.Add($slot)
            }
        }

        [void]$rows.Add([pscustomobject]@{
            Code = $f.BaseName; Family = $family
            Bound = $bound; Total = $btns.Count
            Manual = $manual; Mismatch = $mismatch; Status = $status; Reference = $reference
        })
    }

    $knownFamilies = @('button','driving','lightgun','trackball','analog','spinner')
    $extraFamilies = @($rows | ForEach-Object { $_.Family } | Sort-Object -Unique |
                       Where-Object { $knownFamilies -notcontains $_ })
    $allFamilies   = $knownFamilies + $extraFamilies

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine("TeknoParrot Manager -- Controls Status")
    [void]$sb.AppendLine("Generated : $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))")
    [void]$sb.AppendLine("Profiles  : $($rows.Count)")
    [void]$sb.AppendLine(("=" * 80))

    foreach ($fam in $allFamilies) {
        $group = @($rows | Where-Object { $_.Family -eq $fam } | Sort-Object Code)
        if ($group.Count -eq 0) { continue }
        [void]$sb.AppendLine("")
        [void]$sb.AppendLine("[$fam]")
        foreach ($row in $group) {
            $boundLabel = "{0}/{1} bound" -f $row.Bound, $row.Total
            $refPart    = if ($row.Reference) { "  <- $($row.Reference)" } else { "" }
            [void]$sb.AppendLine(("  {0,-44} {1,-12}  {2}{3}" -f $row.Code, $boundLabel, $row.Status, $refPart))
            if ($row.Manual.Count -gt 0) {
                [void]$sb.AppendLine("    manual: $($row.Manual -join ', ')")
            }
            if ($row.Mismatch.Count -gt 0) {
                [void]$sb.AppendLine("    mismatch (rebind in TeknoParrot UI): $($row.Mismatch -join ', ')")
            }
        }
    }
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine(("=" * 80))

    try {
        [System.IO.File]::WriteAllText($outputPath, $sb.ToString(), (New-Object System.Text.UTF8Encoding $false))
        return $rows.Count
    } catch {
        Write-Log "Controls status: FAILED to write -- $_"
        return -1
    }
}

# =============================================================================
# CONTROL READINESS ENGINE (issue #255)
# =============================================================================
# Read-only assessment of a single profile code across three independent
# dimensions: Registration, Controls, and Launch observation. Issue #255's
# evidence session showed a registration/launch-success path can coexist
# with controls that were skipped or never verified, and TeknoParrotUI's own
# first-run wizard let its "Controls configuration completed" checkbox
# become checked with no mapping screen ever opened (issue #253). Collapsing
# these into a single "Ready" boolean would hide exactly that failure mode,
# so each dimension is reported on its own and never combined.
#
# Hard constraints (do not weaken without a corresponding CLAUDE.md /
# ARCHITECTURE.md update and explicit sign-off -- see issue #255):
#   - Never writes a UserProfile or GameProfiles XML file.
#   - Never runs control propagation (Invoke-ControlPropagation) or invokes
#     TeknoParrotUI's controls wizard.
#   - Never infers a mapping that is not already present on disk.
#   - "Verified" is never assigned by this engine. Confirming a control
#     actually works requires real evidence (an observed successful test),
#     which this static, read-only pass cannot manufacture. Registration,
#     wizard completion, a selected Input API, or a profile's mere existence
#     are explicitly NOT allowed to imply Verified (issue #255).
#
# Precise I/O surface (do not describe this more broadly than it actually
# is): the control-readiness XML assessment reads `<code>.xml` under the
# caller-supplied UserProfilesDir/GameProfilesDir only. Separately,
# Get-ControlReadinessRegistrationState performs a read-only Test-Path
# existence check against the registered profile's GamePath (an arbitrary
# game executable location, not a UserProfiles/GameProfiles path) to
# distinguish 'Registered' from 'Broken'. Neither of these, nor any other
# function in this section, calls or reaches a write-capable path.

# Classifies registration state for one profile code from UserProfiles alone.
# Returns 'Registered', 'Unregistered', or 'Broken'. Never touches GameProfiles
# templates -- registration is strictly about what TeknoParrot has on record.
function Get-ControlReadinessRegistrationState {
    param([Parameter(Mandatory)][string]$Code, [Parameter(Mandatory)][string]$UserProfilesDir)

    # Profile codes are purely alphanumeric (same invariant as
    # Resolve-RegisteredGameFolder); a $Code sourced from an externally-fetched
    # dat index is untrusted input, so reject anything else before it is ever
    # joined into a path rather than let a traversal sequence reach Join-Path.
    if ($Code -notmatch '^[\w]+$') { return 'Unregistered' }

    $path = Join-Path $UserProfilesDir "$Code.xml"
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return 'Unregistered' }

    try {
        $doc = Read-Xml $path
    } catch {
        return 'Broken'
    }
    if ($null -eq $doc.GameProfile) { return 'Broken' }

    $gpNode = $doc.GameProfile.SelectSingleNode('GamePath')
    if ($null -eq $gpNode -or [string]::IsNullOrWhiteSpace($gpNode.InnerText)) { return 'Broken' }

    $gamePath = $gpNode.InnerText.Trim().TrimEnd('\')
    if (-not (Test-Path -LiteralPath $gamePath -PathType Leaf)) { return 'Broken' }

    return 'Registered'
}

# Returns the authoritative required-control specification for one profile
# code, or $null when this engine has no such specification. This is a
# deliberately tiny, hand-curated catalog -- issue #255's own investigation
# (After Burner Climax / abc, upstream teknogods/TeknoParrotUI GameProfiles
# revision 22) is the only source of truth populated so far. A profile code
# with no entry here returns $null on purpose: Get-ControlReadinessControlsState
# must not infer requiredness from whatever nodes happen to be present in an
# arbitrary document, so an unrecognized code always falls through to
# 'Unknown' rather than guessing from structure. Built inline (not as a
# top-level script variable) so the Pester harness's function-body AST
# extraction picks it up automatically.
function Get-ControlReadinessKnownRequirements {
    param([string]$Code)

    if ([string]::IsNullOrWhiteSpace($Code)) { return $null }

    $catalog = @{
        'abc' = [pscustomobject]@{
            # Provenance: teknogods/TeknoParrotUI, GameProfiles/abc.xml,
            # GameProfileRevision 22 -- captured during issue #255's evidence
            # session. This entry is valid ONLY for that exact captured
            # identity/revision. Cross-checked against the document before
            # requirements are trusted (see the "ambiguous contract" branch
            # below): ExecutableName, EmulationProfile, AND
            # GameProfileRevision must all match, or the document is treated
            # as Unknown. A code match alone is not enough, and a later
            # upstream revision of abc.xml is not assumed to share these
            # requirements -- if teknogods ever ships a revision 23+ with
            # different required controls, this entry must not silently keep
            # classifying it against stale requirements; it will instead
            # read as Unknown until a reviewer adds a matching contract.
            ExpectedExecutableName   = 'abc'
            ExpectedEmulationProfile = 'AfterBurnerClimax'
            ExpectedGameProfileRevision = 22
            # InputMapping values for Start, Gun Trigger, Missile Trigger,
            # Climax Switch -- the confirmed required digital controls from
            # the published abc.xml revision 22.
            RequiredButtons = @('P1ButtonStart', 'P1Button1', 'P1Button2', 'P1Button3')
            # InputMapping values for Joystick Analog X/Y and Throttle Lever.
            RequiredAnalogs = @('Analog0', 'Analog2', 'Analog4')
        }
    }

    $key = $Code.ToLowerInvariant()
    if ($catalog.ContainsKey($key)) { return $catalog[$key] }
    return $null
}

# Classifies controls state from an already-loaded profile [xml] document
# (either a real UserProfile or a read-only GameProfiles template), using
# the authoritative requirements for $Code. Returns 'Missing', 'Unsupported',
# 'NotVerified', or 'Unknown'. 'Verified' is intentionally unreachable here
# -- see the section header above.
#
# This deliberately does NOT use raw structural presence as evidence:
#   - "button nodes exist" does not mean the profile is supported;
#   - "no button nodes" does not mean the profile is unsupported;
#   - "some/all buttons bound" does not mean requirements are met or that
#     controls were ever tested.
# Every branch below requires either a positive match against the known
# requirements catalog (Missing/NotVerified) or positive evidence drawn
# from the document's own declared contract (Unsupported -- a selected
# Input API that isn't among the profile's own FieldOptions). Without a
# catalog entry, or without the document matching that entry's expected
# shape, the honest answer is 'Unknown', not a guess.
# Test-ButtonIsBound (shared with Write-ControlsStatus/Invoke-ControlPropagation)
# only checks whether a RawInputButton/DirectInputButton/XInputButton node
# exists -- an empty element (`<DirectInputButton></DirectInputButton>`)
# still counts as "bound" for its purposes. That is too permissive for
# readiness classification: an empty binding element is not a usable
# binding, so this local wrapper adds a non-empty-content requirement on
# top of Test-ButtonIsBound rather than weakening the shared helper (which
# other, unrelated callers may depend on).
function Test-ControlReadinessButtonBindingUsable {
    param($btn)
    if (-not (Test-ButtonIsBound $btn)) { return $false }
    foreach ($nodeName in @('RawInputButton', 'DirectInputButton', 'XInputButton')) {
        $n = $btn.SelectSingleNode($nodeName)
        if ($n -and -not [string]::IsNullOrWhiteSpace($n.InnerText)) { return $true }
    }
    return $false
}

# An analog InputMapping slot is only a structurally complete mapping when
# it also declares a non-empty AnalogType -- a slot with the mapping name
# present but AnalogType missing or blank is malformed/incomplete, not a
# real analog binding, and must not count toward a required analog control.
function Test-ControlReadinessAnalogMappingUsable {
    param($btn)
    $atNode = $btn.SelectSingleNode('AnalogType')
    return ($null -ne $atNode) -and -not [string]::IsNullOrWhiteSpace($atNode.InnerText)
}

function Get-ControlReadinessControlsState {
    param(
        [Parameter(Position = 0)]$doc = $null,
        [Parameter(Position = 1)][string]$Code = ''
    )

    $requirements = Get-ControlReadinessKnownRequirements -Code $Code
    if ($null -eq $requirements) { return 'Unknown' }
    if ($null -eq $doc -or $null -eq $doc.GameProfile) { return 'Unknown' }

    # Ambiguous/unverifiable profile contract: the code matched the catalog,
    # but the document's own declared identity does not match what that
    # catalog entry describes -- including GameProfileRevision, since a
    # later upstream revision is not assumed to share the same required
    # controls. The requirements might not even apply to this document, so
    # nothing below can be trusted as authoritative.
    $execNode     = $doc.GameProfile.SelectSingleNode('ExecutableName')
    $emuNode      = $doc.GameProfile.SelectSingleNode('EmulationProfile')
    $revisionNode = $doc.GameProfile.SelectSingleNode('GameProfileRevision')
    $execName = if ($execNode) { $execNode.InnerText.Trim() } else { '' }
    $emuName  = if ($emuNode) { $emuNode.InnerText.Trim() } else { '' }
    $revision = $null
    if ($revisionNode -and -not [string]::IsNullOrWhiteSpace($revisionNode.InnerText)) {
        [void][int]::TryParse($revisionNode.InnerText.Trim(), [ref]$revision)
    }
    if ($execName -ne $requirements.ExpectedExecutableName -or
        $emuName  -ne $requirements.ExpectedEmulationProfile -or
        $null -eq $revision -or $revision -ne $requirements.ExpectedGameProfileRevision) {
        return 'Unknown'
    }

    # Positive unsupported evidence: the profile's own ConfigValues declare
    # which Input API values it supports (FieldOptions); a selected
    # FieldValue outside that set is a real, document-declared contract
    # violation -- not a heuristic guess about what "should" be supported.
    $inputApiField = $doc.GameProfile.SelectSingleNode("ConfigValues/FieldInformation[FieldName='Input API']")
    if ($inputApiField) {
        $selected = $inputApiField.SelectSingleNode('FieldValue')
        $optionsNode = $inputApiField.SelectSingleNode('FieldOptions')
        if ($selected -and -not [string]::IsNullOrWhiteSpace($selected.InnerText) -and $optionsNode) {
            $options = @($optionsNode.SelectNodes('string') | ForEach-Object { $_.InnerText.Trim() })
            if ($options.Count -gt 0 -and ($options -notcontains $selected.InnerText.Trim())) {
                return 'Unsupported'
            }
        }
    }

    $btns = @(Get-ButtonNodes $doc)
    $byMapping = @{}
    foreach ($b in $btns) {
        $imNode = $b.SelectSingleNode('InputMapping')
        if ($imNode -and -not [string]::IsNullOrWhiteSpace($imNode.InnerText)) {
            $byMapping[$imNode.InnerText.Trim()] = $b
        }
    }

    foreach ($required in $requirements.RequiredButtons) {
        if (-not $byMapping.ContainsKey($required)) { return 'Missing' }
        if (-not (Test-ControlReadinessButtonBindingUsable $byMapping[$required])) { return 'Missing' }
    }
    foreach ($required in $requirements.RequiredAnalogs) {
        # There is no established "analog is bound" signal anywhere in this
        # codebase (Test-ButtonIsBound only covers digital Raw/DirectInput/
        # XInputButton nodes) -- whether an analog axis is actually wired to
        # a working physical device is a real-evidence question this static
        # pass cannot answer. Presence of the required mapping slot is the
        # only authoritative structural fact available, but presence alone
        # is not enough: a slot with an empty/missing AnalogType is not a
        # structurally complete analog mapping either.
        if (-not $byMapping.ContainsKey($required)) { return 'Missing' }
        if (-not (Test-ControlReadinessAnalogMappingUsable $byMapping[$required])) { return 'Missing' }
    }

    # Every known-required control is present and (for digital buttons)
    # bound. That is usable static evidence, but it is not a successful
    # bounded control test or a verification record -- see
    # Test-ControlReadinessVerificationEvidence. Stored device references
    # (e.g. a DirectInputDeviceGuid) or a fully-bound-beyond-requirements
    # profile do not change this outcome; there is no threshold that
    # promotes structural completeness to Verified.
    return 'NotVerified'
}

# Classifies launch-observation state for one profile code. TPM does not
# launch games itself and has no launch-outcome log to read (TeknoParrotUI
# and BudgieLoader own the launch path), so this dimension is always
# 'NotTestedByTpm' today. 'ObservedSuccess'/'ObservedFailure' remain as
# named states for a future real evidence source -- never synthesize them
# from registration, controls state, or any other proxy.
function Get-ControlReadinessLaunchState {
    param([string]$Code)
    return 'NotTestedByTpm'
}

# Combines the three independent dimensions for one profile code into a
# single read-only report row. Controls are read from whichever profile
# document actually exists on disk: the real UserProfile when registered,
# otherwise the GameProfiles template (unregistered games have no real
# bindings, so falling back to the template's unbound buttons correctly
# yields 'Missing' rather than 'Unknown'). $GameProfilesDir is optional --
# omit it to assess registration/controls from UserProfiles only.
function Get-ControlReadinessAssessment {
    param(
        [Parameter(Mandatory)][string]$Code,
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string]$GameProfilesDir = ''
    )

    $registration = Get-ControlReadinessRegistrationState -Code $Code -UserProfilesDir $UserProfilesDir

    # Same code-shape guard as Get-ControlReadinessRegistrationState -- do not
    # join an unvalidated $Code into either directory's path.
    $sourcePath = $null
    if ($Code -match '^[\w]+$') {
        $userProfilePath = Join-Path $UserProfilesDir "$Code.xml"
        $templatePath    = if ($GameProfilesDir) { Join-Path $GameProfilesDir "$Code.xml" } else { '' }
        $sourcePath =
            if (Test-Path -LiteralPath $userProfilePath -PathType Leaf) { $userProfilePath }
            elseif ($templatePath -and (Test-Path -LiteralPath $templatePath -PathType Leaf)) { $templatePath }
            else { $null }
    }

    $doc = $null
    if ($sourcePath) {
        try { $doc = Read-Xml $sourcePath } catch { $doc = $null }
    }

    return [pscustomobject]@{
        Code         = $Code
        Registration = $registration
        Controls     = Get-ControlReadinessControlsState $doc $Code
        Launch       = Get-ControlReadinessLaunchState -Code $Code
    }
}

# Returns $true only when $Assessment carries a structured VerificationEvidence
# record that can actually justify Controls = 'Verified'. Get-ControlReadinessAssessment
# itself never sets Controls to 'Verified' -- this engine has no evidence
# source that could earn it (see Get-ControlReadinessControlsState) -- so the
# only way 'Verified' reaches the formatter today is a caller constructing an
# assessment object by hand. Issue #255 is explicit that registration, wizard
# completion, a selected Input API, or a profile's mere existence must never
# imply Verified; this closes the same gap for any externally-built
# assessment object, not only for this engine's own output. A well-formed
# record needs a non-empty Method (what test was performed, e.g. "manual
# play-test") and a non-empty ObservedAt (when it happened) -- both are
# cheap to fake, but the point is structural: nothing accidentally reaches
# 'Verified' just by echoing a Controls string back.
function Test-ControlReadinessVerificationEvidence {
    param($Assessment)

    if ($null -eq $Assessment) { return $false }
    $evidenceProp = $Assessment.PSObject.Properties['VerificationEvidence']
    if ($null -eq $evidenceProp) { return $false }

    $evidence = $evidenceProp.Value
    if ($null -eq $evidence) { return $false }
    if ($evidence -isnot [System.Management.Automation.PSCustomObject]) { return $false }

    $methodProp = $evidence.PSObject.Properties['Method']
    $observedAtProp = $evidence.PSObject.Properties['ObservedAt']
    if ($null -eq $methodProp -or [string]::IsNullOrWhiteSpace([string]$methodProp.Value)) { return $false }
    if ($null -eq $observedAtProp -or [string]::IsNullOrWhiteSpace([string]$observedAtProp.Value)) { return $false }

    return $true
}

# Formats a Get-ControlReadinessAssessment result into the exact user-facing
# text issue #255's candidate pre-1.0 UX specifies. Pure string formatting
# only -- it never prompts, never reads input, and never triggers a
# configure/test action itself; a future caller decides what happens after
# the question is shown. Returns a string array, one element per display
# line (including the blank separator line before the closing question),
# so a caller can Write-Host each line without re-deriving the wording.
#
# Fail-closed on Controls = 'Verified': that value is only ever trusted when
# Test-ControlReadinessVerificationEvidence confirms real evidence backs it.
# A loose object with Controls = 'Verified' and nothing else is treated the
# same as an unverified profile -- registration, wizard completion, or the
# mere presence of the field must never render as verified (issue #255).
function Get-ControlReadinessSummaryLines {
    param([Parameter(Mandatory)]$Assessment)

    $controlsState = $Assessment.Controls
    if ($controlsState -eq 'Verified' -and -not (Test-ControlReadinessVerificationEvidence -Assessment $Assessment)) {
        $controlsState = 'NotVerified'
    }

    $registrationText = switch ($Assessment.Registration) {
        'Registered'   { 'Game registered successfully' }
        'Unregistered' { 'Game is not registered' }
        'Broken'       { 'Game registration is broken' }
        default        { "Game registration: $($Assessment.Registration)" }
    }

    $controlsText = switch ($controlsState) {
        'Verified'    { 'Controls: Verified' }
        'NotVerified' { 'Controls: Not verified' }
        'Missing'     { 'Controls: Missing' }
        'Unsupported' { 'Controls: Unsupported' }
        'Unknown'     { 'Controls: Unknown' }
        default       { "Controls: $controlsState" }
    }

    $launchText = switch ($Assessment.Launch) {
        'NotTestedByTpm'  { 'Launch status: Not tested by TPM' }
        'ObservedSuccess' { 'Launch status: Explicitly observed (success)' }
        'ObservedFailure' { 'Launch status: Explicitly observed (failure)' }
        default           { "Launch status: $($Assessment.Launch)" }
    }

    $lines = @($registrationText, $controlsText, $launchText)

    # Only offer a recovery instruction when there is something left to
    # verify. A static readiness pass cannot configure or test controls, so
    # the instruction names TeknoParrot's own controls UI rather than
    # implying that TPM will write mappings or run a test.
    if ($controlsState -in @('NotVerified', 'Missing', 'Unknown')) {
        $lines += ''
        $lines += 'Open TeknoParrot controls configuration and map/test controls before treating this game as ready.'
    }

    return $lines
}

# =============================================================================
# TEKNOPARROT WIZARD READINESS DETECTOR (issue #253)
# =============================================================================
# Read-only detection of TeknoParrotUI's own first-run wizard state, so TPM
# can tell a user what TeknoParrot may still ask them to do without ever
# touching TeknoParrot-owned state itself. Per issue #253's own investigation
# of the upstream TeknoParrotUI source: MainWindow.xaml.cs shows the wizard
# is shown/skipped based on Lazydata.ParrotData.FirstTimeSetupComplete;
# JoystickHelper.cs serializes/deserializes ParrotData.xml in the
# TeknoParrotUI working directory; ParrotData.cs defines that flag alongside
# DatXmlLocation. This detector does not have a real, hardware-verified copy
# of ParrotData.xml to confirm the exact root element name against -- so it
# deliberately locates the FirstTimeSetupComplete and DatXmlLocation
# elements via the XPath queries `//FirstTimeSetupComplete` and
# `//DatXmlLocation` (each matches that element name anywhere in the
# document, regardless of the document's actual root element) rather than
# assuming a specific root, and returns 'Unknown' whenever the expected
# field cannot be found at all -- or is found more than once with
# conflicting values (see below) -- instead of guessing a schema. This
# assumption should be confirmed against a real installed ParrotData.xml
# before this detector is relied upon for anything beyond onboarding text.
#
# Hard constraints (same standing as the issue #255 control readiness
# engine above -- do not weaken without a CLAUDE.md / ARCHITECTURE.md
# update and explicit sign-off):
#   - Never creates, writes, repairs, rewrites, or normalizes ParrotData.xml
#     or any other TeknoParrot-owned file.
#   - Never invokes TeknoParrotUI's setup wizard.
#   - A missing file, unparseable XML, and a parseable-but-unrecognized
#     schema are three different facts and are classified distinctly
#     ('Missing', 'Malformed', 'Unknown') rather than folded into one
#     generic failure state.

# Classifies TeknoParrotUI's first-run wizard state from its own
# ParrotData.xml, read-only. Returns a [pscustomobject] with:
#   State          -- 'Complete', 'Incomplete', 'Missing', 'Malformed', or
#                      'Unknown' (present but FirstTimeSetupComplete could
#                      not be confidently read as a boolean, or appears more
#                      than once).
#   DatXmlLocation -- the DAT/XML path TeknoParrotUI has on record, if the
#                      field is present and non-empty; otherwise $null.
#                      Informational only -- never used to influence State.
#
# Exactly one unambiguous FirstTimeSetupComplete element is required to
# classify Complete/Incomplete. A document with more than one such element
# anywhere -- whether the values agree or conflict -- is not the schema
# shape this detector has any confirmed contract for (see the section
# header above: the exact upstream schema is unverified), so it always
# reads as 'Unknown' rather than picking one occurrence and hoping it is
# authoritative. This is the deliberately conservative rule; see
# Tests\TeknoParrot-Manager.Tests.ps1 for both the duplicate-agreeing-value
# and duplicate-conflicting-value cases.
function Get-TeknoParrotWizardState {
    param([Parameter(Mandatory)][string]$TeknoParrotRoot)

    $path = Join-Path $TeknoParrotRoot 'ParrotData.xml'
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        return [pscustomobject]@{ State = 'Missing'; DatXmlLocation = $null }
    }

    $doc = $null
    try {
        $doc = Read-Xml $path
    } catch {
        return [pscustomobject]@{ State = 'Malformed'; DatXmlLocation = $null }
    }
    if ($null -eq $doc -or $null -eq $doc.DocumentElement) {
        return [pscustomobject]@{ State = 'Malformed'; DatXmlLocation = $null }
    }

    $datNode = $doc.SelectSingleNode('//DatXmlLocation')
    $datXmlLocation = if ($datNode -and -not [string]::IsNullOrWhiteSpace($datNode.InnerText)) {
        $datNode.InnerText.Trim()
    } else {
        $null
    }

    $completeNodes = @($doc.SelectNodes('//FirstTimeSetupComplete'))
    if ($completeNodes.Count -ne 1) {
        return [pscustomobject]@{ State = 'Unknown'; DatXmlLocation = $datXmlLocation }
    }
    $completeNode = $completeNodes[0]
    if ([string]::IsNullOrWhiteSpace($completeNode.InnerText)) {
        return [pscustomobject]@{ State = 'Unknown'; DatXmlLocation = $datXmlLocation }
    }

    $state = switch ($completeNode.InnerText.Trim().ToLowerInvariant()) {
        'true'  { 'Complete' }
        'false' { 'Incomplete' }
        default { 'Unknown' }
    }
    return [pscustomobject]@{ State = $state; DatXmlLocation = $datXmlLocation }
}

# Combines the issue #255 control-readiness assessment with the issue #253
# TeknoParrotUI wizard state into the onboarding handoff text a user sees
# after registration/AutoSync. Four dimensions -- Registration, Controls,
# Launch, and TeknoParrotUI wizard state -- are reported independently and
# combined ONLY here, as display text; there is still no combined "Ready"
# boolean anywhere. Pure string formatting: never prompts, never triggers a
# configure/test/wizard action itself.
#
# Fails closed exactly like Get-ControlReadinessSummaryLines: a caller-
# supplied Controls = 'Verified' is only trusted when
# Test-ControlReadinessVerificationEvidence confirms real evidence backs
# it, so this formatter cannot be tricked into claiming controls are ready
# by a hand-built assessment object either.
function Get-OnboardingHandoffSummaryLines {
    param(
        [Parameter(Mandatory)]$Assessment,
        [Parameter(Mandatory)]$WizardState
    )

    $controlsState = $Assessment.Controls
    if ($controlsState -eq 'Verified' -and -not (Test-ControlReadinessVerificationEvidence -Assessment $Assessment)) {
        $controlsState = 'NotVerified'
    }

    $registrationText = switch ($Assessment.Registration) {
        'Registered'   { 'Game registered successfully' }
        'Unregistered' { 'Game is not registered' }
        'Broken'       { 'Game registration is broken' }
        default        { "Game registration: $($Assessment.Registration)" }
    }

    $launchText = switch ($Assessment.Launch) {
        'NotTestedByTpm'  { 'Launch status: Not tested by TeknoParrot Manager' }
        'ObservedSuccess' { 'Launch status: Explicitly observed (success)' }
        'ObservedFailure' { 'Launch status: Explicitly observed (failure)' }
        default           { "Launch status: $($Assessment.Launch)" }
    }

    # Every non-Complete wizard state carries the same caveat: TPM cannot
    # prove TeknoParrot's own setup wizard is done, so it must not imply
    # that it is. Only 'Complete' -- FirstTimeSetupComplete read as true --
    # omits it.
    $wizardCaveat = ' -- TeknoParrot may still ask you to complete its setup wizard'
    $wizardText = switch ($WizardState.State) {
        'Complete'   { 'TeknoParrot first-run setup: Complete' }
        'Incomplete' { "TeknoParrot first-run setup: Not yet complete$wizardCaveat" }
        'Missing'    { "TeknoParrot first-run setup: Unknown (no ParrotData.xml found yet)$wizardCaveat" }
        'Malformed'  { "TeknoParrot first-run setup: Could not be read (its ParrotData.xml appears damaged)$wizardCaveat" }
        'Unknown'    { "TeknoParrot first-run setup: Unknown (unrecognized ParrotData.xml layout)$wizardCaveat" }
        default      { "TeknoParrot first-run setup: $($WizardState.State)$wizardCaveat" }
    }

    $controlsText = switch ($controlsState) {
        'Verified'    { 'Controls: Verified' }
        'NotVerified' { 'Controls: Not verified' }
        'Missing'     { 'Controls: Missing' }
        'Unsupported' { 'Controls: Unsupported' }
        'Unknown'     { 'Controls: Unknown' }
        default       { "Controls: $controlsState" }
    }

    $lines = @(
        $registrationText,
        $launchText,
        $wizardText,
        $controlsText,
        '',
        "TeknoParrot Manager registered this game. TeknoParrotUI still owns the game setup wizard and controls configuration."
    )

    # Same gate as Get-ControlReadinessSummaryLines: only offer a direct
    # TeknoParrot map/test instruction when there is something left to verify.
    if ($controlsState -in @('NotVerified', 'Missing', 'Unknown')) {
        $lines += ''
        $lines += 'Open TeknoParrot controls configuration and map/test controls before treating this game as ready.'
    }

    return $lines
}

# Builds the read-only controls handoff items shown in ACTION REQUIRED after
# registration. Only profile codes with an authoritative requirements catalog
# entry are surfaced here: an uncataloged profile remains Unknown in a direct
# assessment rather than being classified from structure or silently treated
# as ready. A catalog-backed profile whose identity is ambiguous is surfaced
# as Unknown, so stale or mismatched requirements cannot disappear from the
# user-facing readiness report.
function Get-ControlReadinessActionItems {
    param(
        [Parameter(Mandatory)][string]$UserProfilesDir,
        [string]$GameProfilesDir = '',
        [string]$TeknoParrotRoot = ''
    )

    $items = New-Object System.Collections.ArrayList
    if (-not (Test-Path -LiteralPath $UserProfilesDir -PathType Container)) {
        return @()
    }

    $wizardState = if ($TeknoParrotRoot) {
        Get-TeknoParrotWizardState -TeknoParrotRoot $TeknoParrotRoot
    } else {
        [pscustomobject]@{ State = 'Unknown'; DatXmlLocation = $null }
    }

    $profiles = @(Get-ChildItem -LiteralPath $UserProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Directory.Name -ne 'FullBackup' } |
        Sort-Object BaseName)

    foreach ($profileFile in $profiles) {
        $code = $profileFile.BaseName
        if ($null -eq (Get-ControlReadinessKnownRequirements -Code $code)) { continue }

        $assessment = Get-ControlReadinessAssessment -Code $code `
            -UserProfilesDir $UserProfilesDir -GameProfilesDir $GameProfilesDir
        if ($assessment.Registration -ne 'Registered') { continue }

        $displayControls = $assessment.Controls
        if ($displayControls -eq 'Verified' -and
            -not (Test-ControlReadinessVerificationEvidence -Assessment $assessment)) {
            $displayControls = 'NotVerified'
        }
        if ($displayControls -eq 'Verified') { continue }

        $summaryLines = if ($TeknoParrotRoot) {
            Get-OnboardingHandoffSummaryLines -Assessment $assessment -WizardState $wizardState
        } else {
            Get-ControlReadinessSummaryLines -Assessment $assessment
        }

        [void]$items.Add([pscustomobject]@{
            Code         = $code
            Assessment   = $assessment
            SummaryLines = @($summaryLines)
        })
    }

    return @($items)
}

$script:ActiveTpmWorkflowStatus = $null
$script:TpmWorkflowRendering = $false
Write-Log "Script started (v$ScriptVersion$(if ($Unattended) { ' [Unattended]' }))."

# =============================================================================
# SECTION 1 -- Load or prompt for configuration
# =============================================================================

$configPath         = Join-Path $PSScriptRoot "TeknoParrot-Manager.config.json"
$isPostgresRecoveryResume = -not [string]::IsNullOrWhiteSpace($PostgresRecoveryResumeToken)
$tpRoot             = $null
$mode               = $null   # "AutoSync", "RegisterOnly", "CrosshairSetup", "ReShadeSetup", "DgVoodoo2Setup", "GpuFixSetup", "FFBSetup", "BepInExUpdate", "Restore", or "HealthCheck"
$pendingApplyMode   = $null   # set when a preview run's "Apply for real now?" prompt is answered Y -- tells the
                               # next loop iteration to silently re-enter the same mode and run it for real,
                               # instead of showing the menu again.
$forceRealApply     = $false  # consumed once, right after $pendingApplyMode triggers a re-entry, to force
                               # $dryRunActive = $false without re-asking the preview question.
$menuExpanded       = $false  # H selects the readable expanded layout until toggled again.
$zipSource               = $null   # AutoSync only (main collection)
$zipSourceSupplementary  = $null   # AutoSync supplementary source (optional, separate library); $null or ''=not configured
$gamesInstallFolder = $null   # always (the extracted-games root to register)
$retroBat           = $false  # true = extracted folders named GameName.teknoparrot (RetroBat/Batocera)
$hsDataPath         = $null   # HyperSpin 2 data folder (e.g. C:\ProgramData\HyperSpin\data)
$rsSourceDll        = $null   # ReShade 64-bit DLL (bundled at ReShade\ReShade64.dll or user-provided)
$rsSourceDll32      = $null   # ReShade 32-bit DLL (bundled at ReShade\ReShade32.dll or user-provided)
$dgSourceDir        = $null   # dgVoodoo2 DLL folder (bundled at dgVoodoo2\ or user-provided)
$datFilePath          = ''      # optional collection .dat file path (overrides ZIP)
$eggmanDatZip         = ''      # path to Eggman ZIP (contains both dats + notes)
$supplementaryDatPath = ''      # supplementary .dat path (when using separate files)
$includeSupplementary = $false  # whether to build the supplementary index
$lbRoot                     = $null   # LaunchBox install root (containing LaunchBox.exe), if found/entered
$lbPlatformMode             = $null   # "Arcade" / "TeknoParrot" / "Custom" / "Both"
$lbCustomPlatformName       = $null   # only set when $lbPlatformMode is "Custom"
$lbEmulatorId               = $null   # cached GUID of the TeknoParrot Emulator entry in LaunchBox's Emulators.xml
$postgresSuperPasswordEncrypted = $null   # DPAPI-encrypted (ConvertFrom-SecureString, current user+machine) Postgres superuser password
$checkForUpdatesOnStartup = $true   # default true; independent of $configAccepted below -- read even if the
                                     # rest of a saved config is otherwise treated as corrupt/incomplete
$configAccepted       = $false  # true when the user accepted a saved config this run

if ($Unattended -and -not (Test-Path -LiteralPath $configPath)) {
    Write-Host ""
    Write-Host "ERROR: Unattended mode requires saved settings." -ForegroundColor Red
    Write-Host "Run the script once interactively to save your configuration, then retry with -Unattended." -ForegroundColor Yellow
    Write-Log "ERROR: Unattended mode -- no saved config at $configPath"; exit 1
}

# First-run scope framing: shown exactly once, before the setup wizard below
# ever asks a question, only when no saved config exists yet (a returning
# user with a config skips straight to "Saved configuration found:"). Sets
# expectations before anything else so a beginner isn't left guessing what
# TPM is responsible for versus what TeknoParrot/the game itself is
# responsible for. Rephrases the existing ownership disclaimer already
# shipped in TeknoParrot-Manager-README.txt ("WHAT IT DOES NOT DO") rather
# than introducing new legal wording.
if (-not (Test-Path -LiteralPath $configPath) -and -not $Unattended -and -not $isPostgresRecoveryResume) {
    Write-Host ""
    Write-Host "============================================" -ForegroundColor Cyan
    Write-Host "   Welcome to TeknoParrot Manager" -ForegroundColor Cyan
    Write-Host "============================================" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  TPM organizes, extracts, registers, and exports arcade games for" -ForegroundColor DarkCyan
    Write-Host "  TeknoParrot. It does not provide game files -- you must own or" -ForegroundColor DarkCyan
    Write-Host "  otherwise have lawful rights to any ROM/game data you use." -ForegroundColor DarkCyan
    Write-Host ""
    Write-Host "  TPM does not install or configure TeknoParrot itself, and it cannot" -ForegroundColor DarkCyan
    Write-Host "  guarantee that any individual game will boot or run fullscreen." -ForegroundColor DarkCyan
    Write-Host "  If a game crashes or launches windowed once it starts, that is" -ForegroundColor DarkCyan
    Write-Host "  usually a TeknoParrot, game, or runtime setting to fix in" -ForegroundColor DarkCyan
    Write-Host "  TeknoParrotUI or the game itself -- not something TPM changed," -ForegroundColor DarkCyan
    Write-Host "  unless TPM touched a related file (TPM always tells you when it does)." -ForegroundColor DarkCyan
    Write-Host ""
    [void](Read-Host "  Press Enter to continue")
}

# True first run only: no saved config.json existed at all before this
# wizard run started. Used to default the PREVIEW prompt to Y on a true
# first run only -- a returning user (config.json already existed, whether
# or not they accept it this run) keeps today's default-to-last-choice
# behavior instead.
$isTrueFirstRun = -not (Test-Path -LiteralPath $configPath)

if (Test-Path -LiteralPath $configPath) {
    try {
        $cfg = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json
        if ($null -eq $cfg) { throw "Config file parsed as null -- file may be empty or corrupt." }
        # Read before the corrupt-config check below: this is an independent
        # preference, not tied to TeknoParrotRoot/GamesInstallFolder, so it
        # should still apply even if the rest of the saved config is
        # otherwise treated as corrupt/incomplete.
        if ($null -ne $cfg.CheckForUpdatesOnStartup) { $checkForUpdatesOnStartup = [bool]$cfg.CheckForUpdatesOnStartup }
        if ([string]::IsNullOrWhiteSpace($cfg.TeknoParrotRoot) -or
            [string]::IsNullOrWhiteSpace($cfg.GamesInstallFolder)) {
            throw "Config is missing TeknoParrotRoot or GamesInstallFolder -- treating as corrupt."
        }
        Write-Host "Saved configuration found:" -ForegroundColor Cyan
        Write-Host "  TeknoParrot root     : $($cfg.TeknoParrotRoot)"
        if ($cfg.ZipSourceFolder)              { Write-Host "  ZIP source folder    : $($cfg.ZipSourceFolder)" }
        if ($cfg.ZipSourceSupplementaryFolder) { Write-Host "  ZIP supplementary    : $($cfg.ZipSourceSupplementaryFolder)" }
        Write-Host "  Games install folder : $($cfg.GamesInstallFolder)"
        if ($cfg.RetroBat)         { Write-Host "  RetroBat mode        : Yes" }
        if ($cfg.HyperSpinDataPath){ Write-Host "  HyperSpin data path  : $($cfg.HyperSpinDataPath)" }
        if ($cfg.ReShadeSourceDll)   { Write-Host "  ReShade DLL (64-bit) : $($cfg.ReShadeSourceDll)" }
        if ($cfg.ReShadeSourceDll32) { Write-Host "  ReShade DLL (32-bit) : $($cfg.ReShadeSourceDll32)" }
        if ($cfg.DgVoodoo2SourceDir) { Write-Host "  dgVoodoo2 folder     : $($cfg.DgVoodoo2SourceDir)" }
        if ($cfg.EggmanDatZip)          { Write-Host "  Eggman dat ZIP       : $($cfg.EggmanDatZip)" }
        if ($cfg.DatFilePath)           { Write-Host "  Collection dat       : $($cfg.DatFilePath)" }
        if ($cfg.SupplementaryDatPath)  { Write-Host "  Supplementary dat    : $($cfg.SupplementaryDatPath)" }
        if ($cfg.IncludeSupplementary)  { Write-Host "  Supplementary index  : Yes" }
        if ($cfg.LaunchBoxRoot)         { Write-Host "  LaunchBox root       : $($cfg.LaunchBoxRoot)" }
        if ($cfg.LaunchBoxPlatformMode) { Write-Host "  LaunchBox platform   : $($cfg.LaunchBoxPlatformMode)" }
        $cfgUnattendedModeProp = $cfg.PSObject.Properties['UnattendedMode']
        if ($cfgUnattendedModeProp -and $cfgUnattendedModeProp.Value) { Write-Host "  Unattended mode      : $($cfgUnattendedModeProp.Value)" }
        if ($null -ne $cfg.CheckForUpdatesOnStartup -and -not $cfg.CheckForUpdatesOnStartup) {
            Write-Host "  Check for updates on startup: Disabled"
        }
        Write-Host ""
        if ($isPostgresRecoveryResume) {
            Write-Host "  [Automatic repair] Continuing the PostgreSQL setup." -ForegroundColor DarkCyan
            Write-Log "Postgres recovery: auto-accepted saved settings for the protected resume."
            $use = "Y"
        } elseif ($Unattended) {
            Write-Host "  [Unattended] Using saved settings." -ForegroundColor DarkCyan
            Write-Log "Unattended: auto-accepted saved settings."
            $use = "Y"
        } else {
            $use = (Read-HostSafe "Use these settings? (Y/N)")
        }
        if ($use.ToUpper() -eq "Y") {
            # A config saved by an older script version could have
            # TeknoParrotRoot stored as a JSON array instead of a plain
            # string (confirmed from a real tester's config.json) --
            # coerce to a scalar defensively so a stale file from before
            # this fix doesn't keep propagating the wrong type forever
            # (Save-Config below would otherwise just re-save whatever
            # type $tpRoot currently holds).
            $tpRoot             = if ($cfg.TeknoParrotRoot -is [array]) { [string]$cfg.TeknoParrotRoot[0] } else { [string]$cfg.TeknoParrotRoot }
            $zipSource          = $cfg.ZipSourceFolder
            if ($null -ne $cfg.ZipSourceSupplementaryFolder) { $zipSourceSupplementary = "$($cfg.ZipSourceSupplementaryFolder)" }
            $gamesInstallFolder = $cfg.GamesInstallFolder
            if ($null -ne $cfg.RetroBat) { $retroBat = [bool]$cfg.RetroBat }
            if ($cfg.HyperSpinDataPath)  { $hsDataPath  = $cfg.HyperSpinDataPath  }
            if ($cfg.ReShadeSourceDll)   { $rsSourceDll   = $cfg.ReShadeSourceDll   }
            if ($cfg.ReShadeSourceDll32) { $rsSourceDll32 = $cfg.ReShadeSourceDll32 }
            if ($cfg.DgVoodoo2SourceDir) { $dgSourceDir   = $cfg.DgVoodoo2SourceDir }
            if ($cfg.EggmanDatZip)         { $eggmanDatZip         = $cfg.EggmanDatZip         }
            if ($cfg.DatFilePath)          { $datFilePath           = $cfg.DatFilePath           }
            if ($cfg.SupplementaryDatPath) { $supplementaryDatPath  = $cfg.SupplementaryDatPath  }
            if ($null -ne $cfg.IncludeSupplementary) { $includeSupplementary = [bool]$cfg.IncludeSupplementary }
            if ($cfg.LaunchBoxRoot)               { $lbRoot               = $cfg.LaunchBoxRoot }
            if ($cfg.LaunchBoxPlatformMode)        { $lbPlatformMode       = $cfg.LaunchBoxPlatformMode }
            if ($cfg.LaunchBoxCustomPlatformName)  { $lbCustomPlatformName = $cfg.LaunchBoxCustomPlatformName }
            if ($cfg.LaunchBoxEmulatorId)          { $lbEmulatorId         = $cfg.LaunchBoxEmulatorId }
            if ($cfg.PostgresSuperPasswordEncrypted) { $postgresSuperPasswordEncrypted = $cfg.PostgresSuperPasswordEncrypted }
            # A saved "Custom" platform choice with no name is a corrupt/incomplete
            # config (e.g. hand-edited or from an older version) -- silently
            # falling back to a default name would be a confusing surprise, so
            # clear the saved mode and let the platform-choice menu re-ask instead.
            if ($lbPlatformMode -eq "Custom" -and [string]::IsNullOrWhiteSpace($lbCustomPlatformName)) {
                $lbPlatformMode = $null
            }
            # -Unattended has no CLI or config mechanism to pick which mode to
            # run automatically -- every mode's own body already auto-answers
            # its internal prompts under -Unattended (see the many
            # "if ($Unattended) { ... }" blocks throughout this script), but
            # the INITIAL mode choice itself was only ever reachable through
            # the interactive menu or a same-session preview "Apply for real
            # now?" re-entry. A real -Unattended launch as a fresh process
            # therefore always reached the menu loop with no mode chosen and
            # exited 1 at "Mode must be set before starting." -- confirmed by
            # direct reproduction, not assumed. UnattendedMode is an optional
            # saved-config field read ONLY when -Unattended is set (an
            # interactive run always chooses its mode from the menu,
            # regardless of whether this field is present). This RC ships
            # support for only the audited HealthCheck unattended path --
            # a general config-driven selector across all modes is out of
            # scope for the feature freeze, so any other value (including
            # every other real mode name) is rejected the same as garbage.
            $cfgUnattendedModePropForSelect = $cfg.PSObject.Properties['UnattendedMode']
            if ($Unattended -and $cfgUnattendedModePropForSelect -and $cfgUnattendedModePropForSelect.Value) {
                $validUnattendedModes = @('HealthCheck')
                $requestedUnattendedMode = [string]$cfgUnattendedModePropForSelect.Value
                if ($validUnattendedModes -contains $requestedUnattendedMode) {
                    $pendingApplyMode = $requestedUnattendedMode
                    Write-Log "Unattended: initial mode from saved config = $requestedUnattendedMode"
                } else {
                    Write-Log "WARNING: Unattended: config UnattendedMode '$requestedUnattendedMode' is not a recognized mode -- ignoring, menu loop will report the missing-mode error."
                }
            }
            if ($isPostgresRecoveryResume) {
                $pendingApplyMode = 'PostgresSetup'
                Write-Log 'Postgres recovery: protected resume will enter option 12 automatically.'
            }
            $configAccepted = $true
        }
        Write-Host ""
    } catch {
        Write-Host "WARNING: Saved configuration could not be read (file may be corrupt)." -ForegroundColor Yellow
        Write-Host "         Falling through to manual prompts." -ForegroundColor DarkCyan
        Write-Log "Config: could not parse config.json -- $_"
        Write-Host ""
    }
}

# Quiet, opt-out startup update check (CheckForUpdatesOnStartup, default
# true). Never runs in -Unattended mode -- there is no way to show an
# interactive Y/N/V prompt there, and Unattended is meant to be fast and
# non-interactive. See Invoke-StartupUpdateCheck's own comment for how it
# stays from meaningfully delaying startup when GitHub is unreachable.
if ($checkForUpdatesOnStartup -and -not $Unattended -and -not $isPostgresRecoveryResume) {
    $scriptSelfPathForStartupCheck = Join-Path $PSScriptRoot "TeknoParrot-Manager.ps1"
    $startupUpdateInstalled = Invoke-StartupUpdateCheck -ScriptPath $scriptSelfPathForStartupCheck
    if ($startupUpdateInstalled) {
        Write-Host ""
        Write-Host "  Restart TeknoParrot Manager now to run the new version." -ForegroundColor Yellow
        [void](Read-Host "  Press Enter to exit")
        Write-Log "StartupUpdateCheck: exiting after successful update -- not continuing in this session."
        exit 0
    }
}

if (-not $tpRoot) {
    $detected = Find-TeknoParrotRoot
    if ($Unattended) {
        if ($detected.Count -ge 1) {
            $tpRoot = $detected[0]
            Write-Host "  [Unattended] TeknoParrot auto-detected at: $tpRoot" -ForegroundColor DarkCyan
            Write-Log "Unattended: TeknoParrot auto-detected at $tpRoot"
        } else {
            Write-Host "ERROR: Unattended mode -- could not auto-detect TeknoParrot and no saved path." -ForegroundColor Red
            Write-Log "ERROR: Unattended mode -- TeknoParrot root not found."; exit 1
        }
    } elseif ($detected.Count -eq 1) {
        Write-Host ""
        Write-Host "  Auto-detected TeknoParrot at: $($detected[0])" -ForegroundColor Cyan
        $useIt = (Read-HostSafe "  Use this path? (Y/N)").ToUpper()
        if ($useIt -eq "Y") { $tpRoot = $detected[0] }
    } elseif ($detected.Count -gt 1) {
        Write-Host ""
        Write-Host "  Found TeknoParrot in multiple locations:" -ForegroundColor Cyan
        for ($i = 0; $i -lt $detected.Count; $i++) {
            Write-Host ("    {0}) {1}" -f ($i + 1), $detected[$i])
        }
        $pick = (Read-HostSafe "  Enter number to use one, or N to type the path manually")
        if ($pick -match '^\d+$' -and $pick.Length -le 9) {
            $idx = [int]$pick - 1
            if ($idx -ge 0 -and $idx -lt $detected.Count) { $tpRoot = $detected[$idx] }
        }
    }
    if (-not $tpRoot) {
        $tpRoot = Read-PathWithBrowse "Enter TeknoParrot root folder (containing TeknoParrotUi.exe)"
    }
}

if (-not $gamesInstallFolder) {
    if ($Unattended) {
        Write-Host "ERROR: Unattended mode -- games install folder not in saved settings." -ForegroundColor Red
        Write-Log "ERROR: Unattended mode -- gamesInstallFolder not set."; exit 1
    }
    Write-Host ""
    Write-Host "  Game installation folder (staging folder)" -ForegroundColor Cyan
    Write-Host "  This is where TPM extracts and installs games. Your original ZIPs stay where they are." -ForegroundColor DarkCyan
    Write-Host "  TPM will create the accepted folder if it does not exist yet." -ForegroundColor DarkCyan
    $recommendedStagingFolder = Get-TpmSafeStagingFolderDefault `
        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
    if ($recommendedStagingFolder) {
        Write-Host ("  TPM recommends: {0}" -f $recommendedStagingFolder) -ForegroundColor Cyan
        Write-Host "  Press Enter to use this location, or B to choose another." -ForegroundColor DarkCyan
    } else {
        Write-Host "  TPM could not derive a safe default from this installation path." -ForegroundColor Yellow
        Write-Host "  Type a folder or B to browse; it must be outside TeknoParrot, TPM, and your ZIP folders." -ForegroundColor DarkCyan
    }
    $gamesInstallFolder = Read-TpmStagingFolder -RecommendedPath $recommendedStagingFolder `
        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
}

if (-not $configAccepted -and -not $Unattended) {
    Write-Host ""
    Write-Host "  Folder naming mode" -ForegroundColor Cyan
    Write-Host "  Y = RetroBat/Batocera style: GameName.teknoparrot" -ForegroundColor DarkCyan
    Write-Host "  N = Standard style: GameName  (used by LaunchBox and most other frontends)" -ForegroundColor DarkCyan
    $rbChoice = (Read-HostSafe "  Use RetroBat folder naming? (Y/N, default N)" -Default 'N').ToUpper()
    $retroBat = ($rbChoice -eq "Y")
    if ($retroBat) { Write-Log "RetroBat mode enabled by user." }
}

if ((($eggmanDatZip -and -not (Test-Path -LiteralPath $eggmanDatZip)) -or ($datFilePath -and -not (Test-Path -LiteralPath $datFilePath))) -and -not $Unattended) {
    # The configured dat file/ZIP no longer exists on disk (moved, renamed,
    # deleted, or replaced by an external tool like RomVault with a
    # different filename convention) -- previously this fell straight
    # through to the "already configured" branch below, which showed a
    # confusing phantom "Currently using ... (0 MB)" entry for a file that
    # was never actually there. Clearing both here lets this same if/elseif
    # chain naturally re-run the first-run setup wizard instead of
    # duplicating its D/Z/F/N logic a second time.
    $missingPath = if ($eggmanDatZip -and -not (Test-Path -LiteralPath $eggmanDatZip)) { $eggmanDatZip } else { $datFilePath }
    Write-Host ""
    Write-Host "  Saved DAT file was not found." -ForegroundColor Yellow
    Write-Host "  TeknoParrot Manager can download a fresh copy of Eggman's TeknoParrot DAT file." -ForegroundColor Yellow
    Write-Log "EggmanDat: configured path no longer exists ($missingPath) -- re-prompting."
    $eggmanDatZip = ''
    $datFilePath = ''
}

$eggmanDatActionThisRun = if ($eggmanDatZip -or $datFilePath) { 'Reused' } else { 'NotConfigured' }

if (-not $eggmanDatZip -and -not $datFilePath -and -not $Unattended) {
    Write-Host ""
    $eggmanDefaultRoot = Get-EggmanDatDataRoot
    Write-Host "  Download Eggman's TeknoParrot DAT file package?" -ForegroundColor Cyan
    Write-Host "  (TeknoParrot Manager can download Eggman's TeknoParrot DAT file, to be used for game recognition and to help recognize renamed or oddly named games. These are not the games themselves -- TeknoParrot Manager never downloads any game data)" -ForegroundColor DarkCyan
    Write-Host "    D) Download (default)"
    Write-Host "    B) Browse/import a DAT file I already have"
    Write-Host "    N) Skip"
    $datChoice = (Read-HostSafe "  Choice (D/B/N, default D)" -Default 'D').ToUpper()
    $raw = ''   # shared path variable for B and the download-fallback path

    if ($datChoice -eq 'D') {
        # The default destination is deterministic even before the release
        # filename is known. Validate a probe path first so no release query
        # or download starts before a safe destination has been selected.
        $firstRunProbe = if ($eggmanDefaultRoot) { Join-Path $eggmanDefaultRoot 'Eggman-destination-probe.zip' } else { $null }
        $firstRunDestination = Get-EggmanDatPathRole -Path $firstRunProbe -RequestedRole Destination -ProgramDirectory $PSScriptRoot
        if ($firstRunDestination.Safe) {
            Write-Host "  Checking Eggman's Repository for the latest dat release..." -ForegroundColor Cyan
            $rel = Get-EggmanDatRelease
        } else {
            Write-Host "  TPM could not validate its default Eggman data folder before the download." -ForegroundColor Yellow
            Write-Host "  Action: choose B and select a canonical, non-reparse ZIP or dat file outside protected roots." -ForegroundColor Yellow
            Write-Log "EggmanDat: first-run download skipped before release query because the default destination was unsafe: $($firstRunDestination.Reason)"
            $rel = $null
        }
        if ($null -ne $rel) {
            Write-Host ("  Found: {0}  ({1} MB)" -f $rel.FileName, $rel.SizeMB) -ForegroundColor Cyan
            $savedPath = Invoke-EggmanDatDownloadInteractive $rel -ProgramDirectory $PSScriptRoot
            if ($savedPath) {
                $eggmanDatZip = $savedPath
                $eggmanDatActionThisRun = 'Downloaded'
                Write-Host "  Saved: $savedPath" -ForegroundColor Green
                Write-Log "EggmanDat: downloaded to $savedPath"
            } else {
                Write-Host "  Enter path to existing ZIP or .dat file, or press Enter to skip:" -ForegroundColor Yellow
                $raw      = Read-PathWithBrowse "  Path" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*"
                $datChoice = 'BROWSE'
            }
        } elseif (-not $firstRunDestination.Safe) {
            Write-Host "  Automatic download was not started. Enter an existing ZIP or .dat file, or press Enter to skip:" -ForegroundColor Yellow
            $raw      = Read-PathWithBrowse "  Path" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*"
            $datChoice = 'BROWSE'
        } else {
            Write-Host "  Could not reach Eggman's Repository. Enter path to an existing ZIP or .dat file, or press Enter to skip:" -ForegroundColor Yellow
            $raw      = Read-PathWithBrowse "  Path" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*"
            $datChoice = 'BROWSE'
        }
    }

    if ($datChoice -eq 'B' -or $datChoice -eq 'BROWSE') {
        if ($datChoice -eq 'B') { $raw = Read-PathWithBrowse "  Path to ZIP or dat file" -Mode File -FileFilter "ZIP/dat files (*.zip;*.dat)|*.zip;*.dat|All files (*.*)|*.*" }
        if ($raw) {
            if (Test-Path -LiteralPath $raw) {
                $ext = [System.IO.Path]::GetExtension($raw).ToLower()
                if ($ext -eq '.zip') {
                    if (Test-EggmanDatZip -Path $raw) {
                        $eggmanDatZip = $raw
                        Write-Log "EggmanDat: ZIP configured at $raw"
                    } else {
                        Write-Host "  WARNING: ZIP is not a readable Eggman archive with a collection DAT -- dat skipped." -ForegroundColor Yellow
                        Write-Log "EggmanDat: ZIP validation failed at $raw -- skipped."
                    }
                } elseif ($ext -eq '.dat') {
                    $datFilePath = $raw
                    Write-Log "Config: datFilePath set to $raw"
                } else {
                    Write-Host "  WARNING: Expected .zip or .dat file -- dat skipped." -ForegroundColor Yellow
                    Write-Log ("EggmanDat: unrecognised file type '{0}' at {1} -- skipped." -f $ext, $raw)
                }
            } else {
                Write-Host "  WARNING: File not found -- dat skipped." -ForegroundColor Yellow
                Write-Log "EggmanDat: file not found at $raw -- skipped."
            }
        }
    }

    # Issue #120: tell the user immediately what they selected and, when
    # there's enough information to know, whether it's the latest available
    # version -- rather than silently accepting the selection and leaving
    # freshness unstated. ZIP mode can genuinely be compared (same file-size
    # proxy as Test-EggmanDatUpToDate/#106); direct .dat mode has no release
    # to compare against at all, so it says that plainly instead of staying
    # silent or implying a check that can't happen.
    if ($eggmanDatZip) {
        Write-Host ""
        Write-Host ("  Selected: {0}" -f (Split-Path -Leaf $eggmanDatZip)) -ForegroundColor Cyan
        # Reuse $rel from the D) download branch above when it already ran
        # (avoids a redundant second GitHub call right after downloading);
        # falls back to a fresh lookup for the B) browse path, which never
        # queried the release API at all.
        $latestRel = if ($null -ne $rel) { $rel } else { Get-EggmanDatRelease }
        if ($null -eq $latestRel) {
            Write-Host "  Could not reach Eggman's Repository to check whether this is the latest version." -ForegroundColor Yellow
        } else {
            $freshness = Test-EggmanDatUpToDate -LocalDatPath $eggmanDatZip -RemoteSizeBytes $latestRel.SizeBytes
            if ($freshness.Status -eq 'Current') {
                Write-Host "  This is the latest available version." -ForegroundColor Green
            } elseif ($freshness.Status -eq 'UpdateAvailable') {
                Write-Host ("  A newer version is available: {0}  ({1} MB)" -f $latestRel.FileName, $latestRel.SizeMB) -ForegroundColor Yellow
            } else {
                Write-Host "  Could not determine whether this is the latest version." -ForegroundColor Yellow
            }
        }
    } elseif ($datFilePath) {
        Write-Host ""
        Write-Host ("  Selected: {0}" -f (Split-Path -Leaf $datFilePath)) -ForegroundColor Cyan
        Write-Host "  Cannot check whether this is the latest version -- a standalone dat" -ForegroundColor Yellow
        Write-Host "  file has no release to compare it against." -ForegroundColor Yellow
    }

    # Extra version-info file (supplementary dat) follow-up: deferred out of
    # this initial wizard rather than asked here. Checked, not assumed: a
    # supplementary dat only adds alternate/regional version info for games
    # the main Eggman dat already recognizes -- it does not gate whether a
    # game is recognized/registered at all, so deferring it does not reduce
    # baseline recognition quality for a normal first build. Enabling it
    # later and re-running "Register only" (games already extracted -- just
    # register) is the existing supported path for applying it retroactively.
    # Instead of a blocking Y/N here, TPM watches this run's actual match
    # results and, if any game had an uncertain match, prints a targeted
    # recommendation to set this up afterward -- see the post-run summary.
    if ($eggmanDatZip -or $datFilePath) {
        Write-Host "  An extra version-info file (supplementary dat) can be added later if" -ForegroundColor DarkCyan
        Write-Host "  any games end up with an uncertain match -- TPM will recommend it then." -ForegroundColor DarkCyan
    }
} elseif ($eggmanDatZip -and -not $Unattended) {
    # A dat ZIP is already configured -- offer a lightweight check for a
    # newer release instead of silently reusing the same file forever.
    # Direct .dat file mode ($datFilePath) has no GitHub release counterpart
    # to check against, so this only applies to ZIP mode.
    Write-Host ""
    # Show what's already configured before asking whether to check for a
    # newer one -- this is local, immediate info (no network call), so it's
    # shown regardless of whether the user says Y or N to the check itself.
    # The "latest available" side of this can only be known after querying
    # GitHub, which is exactly the network call this Y/N gate exists to make
    # optional -- so only "currently using" appears here.
    $currentSizeMBPreCheck = if (Test-Path -LiteralPath $eggmanDatZip) { [Math]::Round((Get-Item -LiteralPath $eggmanDatZip).Length / 1MB, 1) } else { 0 }
    Write-Host ("  Currently using  : {0}  ({1} MB)" -f (Split-Path -Leaf $eggmanDatZip), $currentSizeMBPreCheck) -ForegroundColor Cyan
    $checkUpdate = (Read-HostSafe "Check for a newer Eggman dat release? (Y/N)").ToUpper()
    if ($checkUpdate -eq 'Y') {
        # Select and revalidate the destination before contacting GitHub.
        # Reading the current DAT for comparison is allowed; writing a
        # replacement under TeknoParrot is not.
        $updateDestination = Resolve-EggmanDatUpdateDestination -CurrentPath $eggmanDatZip -ProgramDirectory $PSScriptRoot
        if ($updateDestination.Status -notin @('Ready','FallbackSelected')) {
            Write-Log "EggmanDat: update skipped before network work because destination status was $($updateDestination.Status)."
        } else {
            Write-Host "  Checking GitHub for latest Eggman dat release..." -ForegroundColor Cyan
            $rel = Get-EggmanDatRelease
            if ($null -eq $rel) {
                Write-Host "  Could not reach GitHub -- keeping your current dat file." -ForegroundColor Yellow
            } else {
                $upToDate = Test-EggmanDatUpToDate -LocalDatPath $eggmanDatZip -RemoteSizeBytes $rel.SizeBytes
                $currentSizeMB = if ($null -ne $upToDate.LocalSizeBytes) { [Math]::Round($upToDate.LocalSizeBytes / 1MB, 1) } else { 0 }
                Write-Host ("  Latest available : {0}  ({1} MB)" -f $rel.FileName, $rel.SizeMB) -ForegroundColor Cyan
                Write-Host ("  Currently using  : {0}  ({1} MB)" -f (Split-Path -Leaf $eggmanDatZip), $currentSizeMB) -ForegroundColor Cyan
                if ($upToDate.Status -eq 'Current') {
                    Write-Host "  Your dat file is already current -- no download needed." -ForegroundColor Green
                    Write-Log "EggmanDat: local file already matches the latest release size -- skipped prompt."
                } else {
                    if ($upToDate.Status -eq 'Unknown') {
                        Write-Host "  Could not determine your current dat file's size -- offering the download anyway." -ForegroundColor Yellow
                    }
                    $doUpdate = if ($updateDestination.Status -eq 'FallbackSelected') {
                        'Y'
                    } else {
                        (Read-HostSafe "  Download and switch to the latest release? (Y/N)").ToUpper()
                    }
                    if ($doUpdate -eq 'Y') {
                        $preferredUpdatePath = $eggmanDatZip
                        if ($updateDestination.Status -eq 'FallbackSelected') {
                            $preferredUpdatePath = Join-Path $updateDestination.DestinationFolder ([System.IO.Path]::GetFileName($rel.FileName))
                        }
                        $savedPath = Invoke-EggmanDatDownloadInteractive $rel -AllowBrowse -PreferredSavePath $preferredUpdatePath -ProgramDirectory $PSScriptRoot
                        if ($savedPath) {
                            $eggmanDatZip = $savedPath
                            $eggmanDatActionThisRun = 'Updated'
                            Write-Host "  Updated: $savedPath" -ForegroundColor Green
                            Write-Log "EggmanDat: updated to $savedPath"
                            [void](Save-Config)
                        } else {
                            Write-Host "  Download failed -- keeping your current dat file." -ForegroundColor Yellow
                        }
                    }
                }
            }
        }
    }
}

# =============================================================================
# SECTION 2 -- Validate TeknoParrot root, locate GameProfiles and UserProfiles
# =============================================================================

if (-not (Test-Path -LiteralPath $tpRoot)) {
    Write-Host ""; Write-Host "ERROR: TeknoParrot root folder not found: $tpRoot" -ForegroundColor Red
    Write-Log "ERROR: TeknoParrot root not found."; exit 1
}

# TeknoParrot's launcher is TeknoParrotUi.exe (Windows path checks are
# case-insensitive, so this also matches TeknoParrotUI.exe).
$tpExe = Join-Path $tpRoot "TeknoParrotUi.exe"
if (-not (Test-Path -LiteralPath $tpExe)) {
    Write-Host ""; Write-Host "ERROR: TeknoParrotUi.exe not found in: $tpRoot" -ForegroundColor Red
    Write-Host "Make sure the path points to the TeknoParrot root folder." -ForegroundColor Yellow
    Write-Log "ERROR: TeknoParrotUi.exe not found."; exit 1
}

$gameProfilesDir = Join-Path $tpRoot "GameProfiles"
if ((-not $Unattended -or ($pendingApplyMode -and $pendingApplyMode -ne 'HealthCheck')) -and
    -not (Ensure-TeknoParrotProfilesReady -TeknoParrotRoot $tpRoot -TeknoParrotExe $tpExe)) {
    Write-Host ''
    Write-Host '  TPM stopped before game registration because TeknoParrot profiles are not ready.' -ForegroundColor Red
    Write-Log 'ERROR: TeknoParrot profiles were not ready after the guided first-run check.'
    [void](Read-HostSafe '  Press Enter to close TPM')
    exit 1
}

$userProfilesDir = Join-Path $tpRoot "UserProfiles"
if (-not (Test-Path -LiteralPath $userProfilesDir)) {
    try {
        [void][System.IO.Directory]::CreateDirectory($userProfilesDir)
    } catch {
        Write-Host ""; Write-Host "ERROR: Could not create UserProfiles folder: $_" -ForegroundColor Red
        Write-Log "ERROR: Could not create UserProfiles folder -- $_"; exit 1
    }
}

Write-Log "Validated. tpRoot=$tpRoot install=$gamesInstallFolder"

# =============================================================================
# SECTION 4 -- Save configuration
# =============================================================================

if (-not (Save-Config)) {
    Write-Host "  WARNING: Could not save configuration -- settings will not be remembered." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "Configuration:" -ForegroundColor Green
Write-Host "  TeknoParrot root     : $tpRoot"
if ($zipSource)               { Write-Host "  ZIP source folder    : $zipSource" }
if ($zipSourceSupplementary)  { Write-Host "  ZIP supplementary    : $zipSourceSupplementary" }
Write-Host "  Games install folder : $gamesInstallFolder"
if ($retroBat)             { Write-Host "  RetroBat mode        : Yes (*.teknoparrot / *.parrot / *.game recognised)" -ForegroundColor Cyan }
if ($eggmanDatZip)         { Write-Host "  Eggman dat ZIP       : $eggmanDatZip" }
elseif ($datFilePath)      { Write-Host "  Collection dat       : $datFilePath" }
if ($supplementaryDatPath) { Write-Host "  Supplementary dat    : $supplementaryDatPath" }
elseif ($includeSupplementary -and $eggmanDatZip) { Write-Host "  Supplementary index  : Yes (from ZIP)" }

# =============================================================================
# SECTION 4b -- Per-game overrides  (TeknoParrot-Manager.overrides.json)
# =============================================================================
# Created empty on first run. Edit with any text editor to fine-tune behaviour:
#   noSync         : ZIP base names to always skip during extraction.
#   onlySync       : Whitelist -- if non-empty, only these ZIPs are extracted
#                    (bypasses the interactive picker; useful for scripted runs).
#   noPropagate    : Profile codes to leave untouched during propagation.
#   forceArchetype : { "ProfileCode": "ArchetypeCode" } -- pin a game to a
#                    specific archetype instead of the automatic best match.
#   familyOverride : { "ProfileCode": "family" } -- override the auto-detected
#                    control family. Valid values: button, driving, lightgun,
#                    trackball, analog, spinner. Fixes mis-classified titles
#                    (e.g. FamilyGuyBowling detected as lightgun; set "trackball").
#   canonicalArchetype : { "family": "ProfileCode" } -- the one archetype in
#                    that family whose Input API is treated as correct. An
#                    archetype is otherwise never modified (see issue #1);
#                    this is the one explicit, user-chosen exception -- every
#                    OTHER archetype in that same family gets its own Input
#                    API corrected to match the designated one, if different.
#                    Deliberately NOT a heuristic guess (v0.99.12 tried
#                    guessing via best button-overlap and broke a real
#                    tester's library by cross-correcting independently
#                    correct archetypes against each other -- reverted in
#                    v0.99.14). Leave unset for a family to never correct
#                    any archetype in it.

$overridesPath         = Join-Path $PSScriptRoot "TeknoParrot-Manager.overrides.json"
$noSyncList            = @()
$onlySyncList          = @()
$noPropagateList       = @()
$forceArchetypeMap     = @{}
$familyOverrideMap     = @{}
$canonicalArchetypeMap = @{}
$subFolderMap          = @{}
$validFamilies         = @('button','driving','lightgun','trackball','analog','spinner')

if (-not (Test-Path -LiteralPath $overridesPath)) {
    $ovTemplate = [ordered]@{
        _comment           = "noSync/onlySync/noPropagate: lists of ZIP base names (without .zip). onlySync acts as a whitelist -- only listed games are extracted. forceArchetype: { GameCode: ArchetypeCode } pins a game to a specific reference game. familyOverride: { GameCode: 'button'|'driving'|'lightgun'|'trackball'|'analog' } overrides the auto-detected control family (fixes mis-classified games like FamilyGuyBowling). canonicalArchetype: { family: ArchetypeCode } the one archetype per family whose Input API is treated as correct -- every other archetype in that family gets its Input API corrected to match it. subFolderMap: { ProfileCode: 'relative\\subpath' } for games whose executable lives in a specific subfolder of the TeknoParrot root rather than in the staging folder (e.g. CrediarDolphin titles). datFile: full path to a No-Intro TeknoParrot dat file; when set the script uses it to auto-register games with shared executable names (like game.exe) without needing fuzzy matching."
        noSync             = @()
        onlySync           = @()
        noPropagate        = @()
        forceArchetype     = [ordered]@{}
        familyOverride     = [ordered]@{}
        canonicalArchetype = [ordered]@{}
        subFolderMap       = [ordered]@{}
        datFile            = ""
    }
    try { [System.IO.File]::WriteAllText($overridesPath, ($ovTemplate | ConvertTo-Json -Depth 10), (New-Object System.Text.UTF8Encoding $false)) }
    catch { Write-Log "Overrides: could not create template -- $_" }
}

if (Test-Path -LiteralPath $overridesPath) {
    try {
        $ov = Get-Content -LiteralPath $overridesPath -Raw | ConvertFrom-Json
        if ($ov.noSync)      { $noSyncList      = @($ov.noSync) }
        if ($ov.onlySync)    { $onlySyncList    = @($ov.onlySync) }
        if ($ov.noPropagate) { $noPropagateList = @($ov.noPropagate) }
        if ($ov.forceArchetype) {
            foreach ($p in $ov.forceArchetype.PSObject.Properties) { $forceArchetypeMap[$p.Name] = [string]$p.Value }
        }
        if ($ov.familyOverride) {
            foreach ($p in $ov.familyOverride.PSObject.Properties) {
                $fv = [string]$p.Value
                if ($validFamilies -contains $fv) {
                    $familyOverrideMap[$p.Name] = $fv
                } else {
                    Write-Host ("  WARNING: familyOverride for '{0}' has unknown family '{1}' -- ignored." -f $p.Name, $fv) -ForegroundColor Yellow
                    Write-Log "Overrides: familyOverride '$($p.Name)' has unknown value '$fv' -- ignored."
                }
            }
        }
        if ($ov.canonicalArchetype) {
            foreach ($p in $ov.canonicalArchetype.PSObject.Properties) {
                $fam = $p.Name
                if ($validFamilies -contains $fam) {
                    $canonicalArchetypeMap[$fam] = [string]$p.Value
                } else {
                    Write-Host ("  WARNING: canonicalArchetype has unknown family '{0}' -- ignored." -f $fam) -ForegroundColor Yellow
                    Write-Log "Overrides: canonicalArchetype has unknown family '$fam' -- ignored."
                }
            }
        }
        if ($ov.subFolderMap) {
            foreach ($p in $ov.subFolderMap.PSObject.Properties) { $subFolderMap[$p.Name] = [string]$p.Value }
        }
        if ($ov.datFile -and -not [string]::IsNullOrWhiteSpace([string]$ov.datFile)) {
            $datFilePath = [string]$ov.datFile
        }
        # Issue #119: this used to also show whenever a dat file was
        # configured ("datFile=yes"), even with every other count at zero --
        # a dat file is a normal, common setting (already shown plainly in
        # the Configuration summary above), not an advanced override, so
        # showing this diagnostic-looking line just because one was
        # configured made ordinary setups look like they had unexplained
        # internal state. Now only shown when an actual override
        # (noSync/onlySync/noPropagate/pinned/familyOverride/
        # canonicalArchetype/subFolderMap) is configured in
        # TeknoParrot-Manager.overrides.json.
        $ovCount = $noSyncList.Count + $onlySyncList.Count + $noPropagateList.Count + $forceArchetypeMap.Count + $familyOverrideMap.Count + $canonicalArchetypeMap.Count + $subFolderMap.Count
        if ($ovCount -gt 0) {
            Write-Host ""
            $sfmLabel = if ($subFolderMap.Count -gt 0) { ", subFolderMap=$($subFolderMap.Count)" } else { "" }
            Write-Host "Overrides: noSync=$($noSyncList.Count), onlySync=$($onlySyncList.Count), noPropagate=$($noPropagateList.Count), pinned=$($forceArchetypeMap.Count), familyOverride=$($familyOverrideMap.Count), canonicalArchetype=$($canonicalArchetypeMap.Count)$sfmLabel" -ForegroundColor DarkCyan
            # Issue #119: the counts above are internal config-key names, not
            # self-explanatory to a normal user. This line only ever appears
            # when at least one override is actually configured, so it's
            # always actionable -- explain what it means and what to do
            # rather than leaving it as an unexplained diagnostic-looking line.
            Write-Host "  These come from TeknoParrot-Manager.overrides.json and change which games" -ForegroundColor DarkGray
            Write-Host "  get synced/propagated, or how they're matched. If you didn't create that" -ForegroundColor DarkGray
            Write-Host "  file yourself, there's nothing to do. If a count looks wrong, edit or" -ForegroundColor DarkGray
            Write-Host "  remove the matching entry in that file and re-run." -ForegroundColor DarkGray
        }
        Write-Log "Overrides: noSync=$($noSyncList.Count) onlySync=$($onlySyncList.Count) noPropagate=$($noPropagateList.Count) pinned=$($forceArchetypeMap.Count) familyOverride=$($familyOverrideMap.Count) canonicalArchetype=$($canonicalArchetypeMap.Count) subFolderMap=$($subFolderMap.Count) datFile=$datFilePath"
    } catch {
        Write-Host "WARNING: could not read TeknoParrot-Manager.overrides.json; ignoring overrides." -ForegroundColor Yellow
        Write-Log "Overrides: parse error -- ignoring."
    }
}

# =============================================================================
# DAT FILE INDEX  (loaded once before the menu loop; reused each run)
# Priority: EggmanDatZip (ZIP mode) > DatFilePath (direct file mode)
# =============================================================================

$datIndex   = @{}
$suppIndex  = @{}   # supplementary dat index: normalizedName -> {ProfileCode, Executable}
$suppCodes  = New-Object 'System.Collections.Generic.HashSet[string]'([StringComparer]::OrdinalIgnoreCase)
$notesIndex = @{}   # game notes index: ProfileCode.ToLower() -> notes text string

if ($eggmanDatZip) {
    if (Test-Path -LiteralPath $eggmanDatZip) {
        Write-Host ""
        Write-Host "Loading collection dat from ZIP..." -ForegroundColor DarkGray
        $datIndex = Build-DatIndexFromZip $eggmanDatZip
        if ($datIndex.Count -gt 0) {
            Write-Host ("  Collection dat: {0} games indexed." -f $datIndex.Count) -ForegroundColor DarkGray
            Write-Log "DatIndex (ZIP): $($datIndex.Count) entries from $eggmanDatZip"
        } else {
            Write-Host "  Collection dat: no entries found -- check ZIP contains a *Collection*_RomVault*.dat entry." -ForegroundColor Yellow
            Write-Log "DatIndex (ZIP): 0 entries from $eggmanDatZip."
        }
        if ($includeSupplementary) {
            Write-Host "  Loading supplementary dat from ZIP..." -ForegroundColor DarkGray
            $suppIndex = Build-DatIndexFromZip $eggmanDatZip '*Supplementary*_RomVault*.dat'
            if ($suppIndex.Count -gt 0) {
                Write-Host ("  Supplementary dat: {0} entries indexed (override collection)." -f $suppIndex.Count) -ForegroundColor DarkGray
                Write-Log "SuppIndex (ZIP): $($suppIndex.Count) entries from $eggmanDatZip"
            } else {
                Write-Host "  Supplementary dat: no entries found." -ForegroundColor Yellow
                Write-Log "SuppIndex (ZIP): 0 entries from $eggmanDatZip."
            }
        }
        Write-Host "  Loading game notes from ZIP..." -ForegroundColor DarkGray
        $notesIndex = Build-GameNotesIndexFromZip $eggmanDatZip
        if ($notesIndex.Count -gt 0) {
            Write-Host ("  Game notes: {0} entries indexed." -f $notesIndex.Count) -ForegroundColor DarkGray
            Write-Log "NotesIndex (ZIP): $($notesIndex.Count) entries from $eggmanDatZip"
        }
    } else {
        Write-Host ("  WARNING: Eggman dat ZIP not found at: {0}" -f $eggmanDatZip) -ForegroundColor Yellow
        Write-Log "DatIndex (ZIP): file not found at $eggmanDatZip -- skipping."
    }
} elseif ($datFilePath) {
    if (Test-Path -LiteralPath $datFilePath) {
        Write-Host ""
        Write-Host "Loading collection dat..." -ForegroundColor DarkGray
        $datIndex = Build-DatIndex $datFilePath
        if ($datIndex.Count -gt 0) {
            Write-Host ("  Collection dat: {0} games indexed." -f $datIndex.Count) -ForegroundColor DarkGray
            Write-Log "DatIndex: $($datIndex.Count) entries from $datFilePath"
        } else {
            Write-Host "  Collection dat: no entries found -- check that the file has <GameProfile> elements." -ForegroundColor Yellow
            Write-Log "DatIndex: 0 entries from $datFilePath -- file parsed but no valid game entries found."
        }
        if ($supplementaryDatPath) {
            if (Test-Path -LiteralPath $supplementaryDatPath) {
                Write-Host "  Loading supplementary dat..." -ForegroundColor DarkGray
                $suppIndex = Build-DatIndex $supplementaryDatPath
                if ($suppIndex.Count -gt 0) {
                    Write-Host ("  Supplementary dat: {0} entries indexed (override collection)." -f $suppIndex.Count) -ForegroundColor DarkGray
                    Write-Log "SuppIndex: $($suppIndex.Count) entries from $supplementaryDatPath"
                } else {
                    Write-Host "  Supplementary dat: no entries found." -ForegroundColor Yellow
                    Write-Log "SuppIndex: 0 entries from $supplementaryDatPath."
                }
            } else {
                Write-Host ("  WARNING: Supplementary dat not found at: {0}" -f $supplementaryDatPath) -ForegroundColor Yellow
                Write-Log "SuppIndex: file not found at $supplementaryDatPath -- skipping."
            }
        }
        # Look for a notes text file alongside the dat (e.g. extracted from the ZIP)
        $notesCandidate = Get-ChildItem -LiteralPath ([System.IO.Path]::GetDirectoryName($datFilePath)) `
                              -Filter '*.txt' -File -ErrorAction SilentlyContinue |
                          Where-Object { $_.Name -ilike '*note*' } |
                          Select-Object -First 1 -ExpandProperty FullName
        if ($notesCandidate) {
            Write-Host "  Loading game notes..." -ForegroundColor DarkGray
            $notesIndex = Build-GameNotesIndex $notesCandidate
            if ($notesIndex.Count -gt 0) {
                Write-Host ("  Game notes: {0} entries indexed." -f $notesIndex.Count) -ForegroundColor DarkGray
                Write-Log "NotesIndex: $($notesIndex.Count) entries from $notesCandidate"
            }
        }
    } else {
        Write-Host ("  WARNING: Collection dat not found at: {0}" -f $datFilePath) -ForegroundColor Yellow
        Write-Log "DatIndex: file not found at $datFilePath -- skipping."
    }
}

# Merge supplementary overrides into the collection index.
# Supplementary entries take precedence for the same normalised game name,
# so the alternate version from the supplementary dat is used instead of
# the collection version (only one version can be installed at a time).
if ($suppIndex.Count -gt 0) {
    foreach ($k in $suppIndex.Keys) {
        $datIndex[$k] = $suppIndex[$k]
        [void]$suppCodes.Add($suppIndex[$k].ProfileCode)
    }
    Write-Log "DatIndex: merged $($suppIndex.Count) supplementary overrides ($($suppCodes.Count) profile codes)."
}

# =============================================================================
# PROFILE SET  (fetched once; used by Resolve-ProfileCode during registration)
# =============================================================================
$profileSet = $null
if ($datIndex.Count -gt 0 -and $gameProfilesDir) {
    Write-Host ""
    Write-Host "Loading TeknoParrot GameProfiles list..." -ForegroundColor DarkGray
    $profileSet = Get-TeknoParrotProfileSet $gameProfilesDir
    if ($profileSet.Count -gt 0) {
        Write-Host ("  Profile set: {0} profiles (used for dat code resolution)." -f $profileSet.Count) -ForegroundColor DarkGray
    } else {
        Write-Host "  Profile set: could not load (GitHub unreachable and GameProfiles folder empty)." -ForegroundColor Yellow
    }
}

# =============================================================================
# ADAPTIVE MAIN MENU (issue #104) -- single data-driven model, rendered at one
# of four layout tiers depending on the current console window's width
# (Get-ConsoleLayoutTier is width-driven; see that function for the exact
# breakpoints): Compact (<90 columns), Standard (90-119), Professional
# (120-149), or Ultra (>=150). Every tier shows the same 15 numbered options
# with the same meaning; only how much description text is shown, and
# whether the layout is one or two columns, changes. Numbering, the
# switch-statement dispatch, and all mode behavior are completely unaffected
# by this -- only Show-MainMenu's own rendering varies. At extremely short
# heights (below the documented 60x10 minimum-supported viewport), an
# emergency compact presentation takes over regardless of tier -- see
# Get-MainMenuEmergencyCompactRows.
# =============================================================================

# Single source of truth for every menu item's number, mode string, section,
# and description -- ShortDesc (one line) and FullDesc (an array of lines).
# Adding, renumbering, or re-sectioning a menu item only ever needs to change
# this array -- every rendering tier and the "Enter 1-N" prompt derive from
# it. Different tiers show different levels of detail derived from these two
# fields (or neither, for Standard/Compact's labels-only rendering) -- see
# "Description text sourcing varies by tier" in ARCHITECTURE.md for exactly
# which tier uses which field. A function (not a plain script-scope
# variable) so it is picked up by the test suite's AST-based function
# extraction like every other testable helper in this script -- see the
# "Main menu source-level drift check" Describe block in
# Tests/TeknoParrot-Manager.Tests.ps1.
function Get-MainMenuSections {
    return @(
    [pscustomobject]@{
        Header = 'Library Management'
        Items  = @(
            [pscustomobject]@{ Number = 1; Mode = 'AutoSync'; Label = 'AutoSync'; ShortDesc = 'Extract ZIPs (NAS or local), then register the games.'; FullDesc = @('Extract ZIPs (NAS or local) to a local', 'folder, then register the games.') }
            [pscustomobject]@{ Number = 2; Mode = 'RegisterOnly'; Label = 'Register only'; ShortDesc = 'Games already extracted -- just register.'; FullDesc = @('Games are already extracted; just register.') }
            [pscustomobject]@{ Number = 3; Mode = 'PropagateControls'; Label = 'Propagate Controls'; ShortDesc = 'Re-copy control bindings, without AutoSync/Register.'; FullDesc = @('Re-copy control bindings from reference', 'games to other compatible games, without', 'going through AutoSync/Register first.') }
        )
    }
    [pscustomobject]@{
        Header = 'Game Enhancements (all optional -- games work without these)'
        Items  = @(
            [pscustomobject]@{ Number = 4; Mode = 'CrosshairSetup'; Label = 'Crosshair setup'; ShortDesc = 'Deploy custom crosshairs to lightgun games.'; FullDesc = @('Pick and deploy custom crosshairs to all', 'registered lightgun games.') }
            [pscustomobject]@{ Number = 5; Mode = 'ReShadeSetup'; Label = 'ReShade setup'; ShortDesc = 'Visual filters: sharper image, CRT-style scanlines, borders.'; FullDesc = @('ReShade adds post-processing filters on top of', 'the game -- sharper image, better colours,', 'CRT-style scanlines, and screen borders, for a', 'more authentic arcade-cabinet look.') }
            [pscustomobject]@{ Number = 6; Mode = 'DgVoodoo2Setup'; Label = 'dgVoodoo2 setup'; ShortDesc = 'Fix old DX8/DirectDraw/Glide crashes.'; FullDesc = @('Fix old DX8, DirectDraw, and Glide games that', 'crash or show black screens.') }
            [pscustomobject]@{ Number = 7; Mode = 'GpuFixSetup'; Label = 'GPU fix setup'; ShortDesc = 'Auto-detect GPU, apply matching compatibility fix.'; FullDesc = @('Auto-detect your GPU (AMD / NVIDIA / Intel) and', 'apply the matching compatibility fix to every', 'registered game that has one.') }
            [pscustomobject]@{ Number = 8; Mode = 'FFBSetup'; Label = 'Force feedback (FFB) setup'; ShortDesc = 'Wheel/stick rumble and force feedback.'; FullDesc = @('Wheel/stick rumble and force feedback.', "Covers TeknoParrot's built-in FFB Blaster (needs a", 'paid membership) and a free third-party plugin.') }
            [pscustomobject]@{ Number = 9; Mode = 'BepInExUpdate'; Label = 'BepInEx setup'; ShortDesc = 'Install, update, or repair the BepInEx modding framework.'; FullDesc = @('BepInEx is a modding framework some TeknoParrot', 'games use for extra features and fixes. TPM offers', 'a user-approved install, update, or repair-reset', 'using the stable package matching each game.', 'Unsafe roots and failed downloads make no changes.') }
        )
    }
    [pscustomobject]@{
        Header = 'Maintenance and Recovery'
        Items  = @(
            [pscustomobject]@{ Number = 10; Mode = 'HealthCheck'; Label = 'Library health check'; ShortDesc = 'Read-only status: registered/broken/unregistered counts.'; FullDesc = @('Read-only: reports registered/broken/', 'unregistered counts plus GPU fix / FFB Blaster /', 'dgVoodoo2 coverage and ReShade/BepInEx install', 'counts. No extraction, registration, repair, or', 'network access -- just a fast status check.') }
            [pscustomobject]@{ Number = 11; Mode = 'Restore'; Label = 'Restore backup'; ShortDesc = 'Roll UserProfiles/LaunchBox/Postgres back.'; FullDesc = @('Roll UserProfiles, LaunchBox files, or Postgres', 'databases back to a previous backup.') }
            [pscustomobject]@{ Number = 12; Mode = 'PostgresSetup'; Label = 'Postgres setup'; ShortDesc = 'Local PostgreSQL database for Golden Tee and other IT games.'; FullDesc = @('Installs/configures the local PostgreSQL', 'database that some Incredible Technologies (IT)', 'games need to keep local scores/settings (Golden', 'Tee Live, Power Putt Live, Silver Strike Bowling', 'Live, Target Toss Pro). Requires running this', "script as Administrator if PostgreSQL isn't", 'installed yet.') }
        )
    }
    [pscustomobject]@{
        Header = 'Application'
        Items  = @(
            [pscustomobject]@{ Number = 13; Mode = 'CheckForUpdates'; Label = 'Check for Updates'; ShortDesc = 'Manual, backup-first check against the latest GitHub release.'; FullDesc = @('Manual, backup-first check against the latest', 'GitHub release. Nothing is downloaded or changed', 'without your explicit confirmation.') }
            [pscustomobject]@{ Number = 14; Mode = 'Support'; Label = 'Create Support Package'; ShortDesc = 'Gather safe logs and reports into one ZIP.'; FullDesc = @('Gather safe TPM, TeknoParrot, and game diagnostics', 'into one ZIP you can send when asking for help.') }
            [pscustomobject]@{ Number = 15; Mode = 'Exit'; Label = 'Exit'; ShortDesc = ''; FullDesc = @() }
        )
    }
    )
}

# Flat, number-ordered view of every item across all sections -- used to
# derive the highest option number (the "Enter 1-N" prompt) and to look an
# item up by number without every caller re-flattening the section list.
function Get-MainMenuItems {
    return @(Get-MainMenuSections | ForEach-Object { $_.Items })
}

# Pure/testable: decides which layout tier fits the current console viewport.
# Width is the primary breakpoint because console menus render in columns, not
# pixels. Height is tracked separately in the render metrics so diagnostics can
# show whether the selected layout is still vertically constrained.
function Get-ConsoleLayoutTier {
    param(
        [int]$Width,
        [int]$Height,
        [int]$RequiredFullLines
    )
    if ($Width -ge 150) { return 'Ultra' }
    if ($Width -ge 120) { return 'Professional' }
    if ($Width -ge 90) { return 'Standard' }
    return 'Compact'
}

function Get-MainMenuRenderMetrics {
    param(
        [ValidateSet('Ultra', 'Professional', 'Standard', 'Compact')][string]$Tier,
        [int]$Width,
        [int]$Height = 0,
        [int]$RequiredFullLines = 0,
        [ValidateSet('Auto', 'UltraTwoColumn', 'UltraCentered')][string]$UltraLayoutMode = 'Auto'
    )

    $contentWidth = [Math]::Max(40, $Width - 2)
    $labelWidth = $null
    $descriptionWidth = 0
    $totalRenderWidth = $contentWidth
    $layout = $Tier
    $heightConstrained = ($Height -gt 0 -and $RequiredFullLines -gt 0 -and $Height -lt $RequiredFullLines)
    $widthConstrained = ($Tier -ne 'Ultra')

    if ($Tier -eq 'Compact') {
        $layout = 'CompactWrappedSingleColumn'
        $descriptionWidth = 0
        $totalRenderWidth = [Math]::Min($contentWidth, 88)
    } elseif ($Tier -eq 'Standard') {
        $layout = 'StandardSingleColumn'
        $labelWidth = 27
        $descriptionWidth = [Math]::Max(24, $contentWidth - 36)
    } elseif ($Tier -eq 'Professional') {
        $layout = 'ProfessionalTwoColumn'
        $gap = 3
        $columnWidth = [Math]::Floor(($contentWidth - 4 - $gap) / 2)
        $labelWidth = 22
        $descriptionWidth = [Math]::Max(36, $columnWidth - 8)
        $totalRenderWidth = ($columnWidth * 2) + $gap + 4
    } else {
        if ($UltraLayoutMode -eq 'UltraCentered') {
            $layout = 'UltraCentered'
            $centeredWidth = [Math]::Min($contentWidth, 132)
            if ($centeredWidth -lt 118) { $centeredWidth = $contentWidth }
            $labelWidth = 30
            $descriptionWidth = [Math]::Max(72, $centeredWidth - 34)
            $totalRenderWidth = $centeredWidth
        } else {
            $layout = 'UltraTwoColumn'
            $gap = 4
            $columnWidth = [Math]::Floor(($contentWidth - $gap) / 2)
            $labelWidth = 22
            $descriptionWidth = [Math]::Max(42, $columnWidth - 18)
            $totalRenderWidth = ($columnWidth * 2) + $gap
        }
    }

    $constrainedBy = 'none'
    if ($widthConstrained -and $heightConstrained) {
        $constrainedBy = 'width,height'
    } elseif ($widthConstrained) {
        $constrainedBy = 'width'
    } elseif ($heightConstrained) {
        $constrainedBy = 'height'
    }

    return [pscustomobject]@{
        DetectedWidth = $Width
        DetectedHeight = $Height
        SelectedTier = $Tier
        Layout = $layout
        LabelWidth = $labelWidth
        DescriptionWidth = $descriptionWidth
        TotalRenderWidth = $totalRenderWidth
        HeightConstrained = $heightConstrained
        WidthConstrained = $widthConstrained
        ConstrainedBy = $constrainedBy
    }
}

function New-ConsoleRenderRow {
    param(
        [string]$Text = '',
        [string]$Color = 'White'
    )
    return [pscustomobject]@{ Text = $Text; Color = $Color; Segments = $null }
}

function New-ConsoleRenderSegmentRow {
    param([object[]]$Segments)
    $text = (($Segments | ForEach-Object { $_.Text }) -join '')
    return [pscustomobject]@{ Text = $text; Color = 'White'; Segments = $Segments }
}

function New-ConsoleRenderSegment {
    param(
        [string]$Text = '',
        [string]$Color = 'White'
    )
    return [pscustomobject]@{ Text = $Text; Color = $Color }
}

function Get-MainMenuSectionColor {
    param([string]$Header)
    if ($Header -like 'Library Management*') { return 'Cyan' }
    if ($Header -like 'Game Enhancements*') { return 'Green' }
    if ($Header -like 'Maintenance*') { return 'Magenta' }
    if ($Header -like 'Application*') { return 'Yellow' }
    return 'White'
}

function Get-MainMenuDefaultDescription {
    param([object]$Item)

    switch ($Item.Mode) {
        'AutoSync' { return 'Extract and register ZIPs safely.' }
        'RegisterOnly' { return 'Register already-extracted games.' }
        'PropagateControls' { return 'Copy bindings from reference games.' }
        'CrosshairSetup' { return 'Deploy lightgun crosshairs.' }
        'ReShadeSetup' { return 'Visual filters: sharper image, CRT-style scanlines.' }
        'DgVoodoo2Setup' { return 'Fix older DirectX/Glide games.' }
        'GpuFixSetup' { return 'Apply GPU compatibility fixes.' }
        'FFBSetup' { return 'Configure wheel/stick feedback.' }
        'BepInExUpdate' { return 'Update BepInEx (a modding framework), if installed.' }
        'HealthCheck' { return 'Read-only library status.' }
        'Restore' { return 'Restore UserProfiles or databases.' }
        'PostgresSetup' { return 'Local PostgreSQL for Golden Tee and other IT games.' }
        'CheckForUpdates' { return 'Manual backup-first update check.' }
        default { return $Item.ShortDesc }
    }
}

function Get-MainMenuGeometry {
    param(
        [ValidateSet('Ultra', 'Professional', 'Standard', 'Compact')][string]$Tier,
        [int]$ViewportWidth,
        [int]$ViewportHeight,
        [ValidateSet('Auto', 'UltraTwoColumn', 'UltraCentered')][string]$UltraLayoutMode = 'Auto'
    )

    $safeWidth = [Math]::Max(40, $ViewportWidth)
    $safeHeight = [Math]::Max(10, $ViewportHeight)
    $contentWidth = [Math]::Max(38, $safeWidth - 2)
    $layout = 'Compact'
    $columnCount = 1
    $gutterWidth = 0
    $menuWidth = [Math]::Min($contentWidth, 88)
    $columnWidth = $menuWidth
    $rightColumnWidth = $columnWidth
    $bannerMode = 'Compact'
    $footerWidth = $menuWidth
    $wrapWidth = [Math]::Max(24, $columnWidth - 8)
    $frameEnabled = $false

    if ($Tier -eq 'Standard') {
        $layout = 'Standard'
        $menuWidth = [Math]::Min($contentWidth, 116)
        $columnWidth = $menuWidth
        $rightColumnWidth = $columnWidth
        $footerWidth = $menuWidth
        $wrapWidth = [Math]::Max(40, $columnWidth - 34)
    } elseif ($Tier -eq 'Professional') {
        $layout = 'ProfessionalTwoColumn'
        $columnCount = 2
        $gutterWidth = 3
        $menuWidth = [Math]::Min($contentWidth, 132)
        $frameEnabled = $true
        $columnWidth = [Math]::Floor(($menuWidth - 4 - $gutterWidth) / 2)
        $rightColumnWidth = $menuWidth - 4 - $gutterWidth - $columnWidth
        $footerWidth = $menuWidth
        $wrapWidth = [Math]::Max(36, $columnWidth - 8)
        $bannerMode = 'Ascii'
    } elseif ($Tier -eq 'Ultra') {
        if ($UltraLayoutMode -eq 'UltraCentered') {
            $layout = 'UltraCentered'
            $menuWidth = [Math]::Min($contentWidth, 136)
            $columnWidth = $menuWidth
            $rightColumnWidth = $columnWidth
            $footerWidth = $menuWidth
            $wrapWidth = [Math]::Max(72, $columnWidth - 16)
        } else {
            $layout = 'UltraTwoColumn'
            $columnCount = 2
            $gutterWidth = 3
            $menuWidth = [Math]::Min($contentWidth, [Math]::Max(148, $contentWidth))
            $frameEnabled = $true
            $columnWidth = [Math]::Floor(($menuWidth - 4 - $gutterWidth) / 2)
            $rightColumnWidth = $menuWidth - 4 - $gutterWidth - $columnWidth
            $footerWidth = $menuWidth
            $wrapWidth = [Math]::Max(42, $columnWidth - 8)
        }
        $bannerMode = 'Ascii'
    }

    $leftPadding = [Math]::Max(0, [Math]::Floor(($safeWidth - $menuWidth) / 2))
    return [pscustomobject]@{
        ViewportWidth = $safeWidth
        ViewportHeight = $safeHeight
        Tier = $Tier
        Layout = $layout
        BannerMode = $bannerMode
        MenuWidth = $menuWidth
        ColumnCount = $columnCount
        ColumnWidth = $columnWidth
        RightColumnWidth = $rightColumnWidth
        GutterWidth = $gutterWidth
        FooterWidth = $footerWidth
        WrapWidth = $wrapWidth
        LeftPadding = $leftPadding
        AvailableRows = $safeHeight
        FrameEnabled = $frameEnabled
    }
}

function Get-ConsoleContentWidth {
    try {
        $width = [int]$Host.UI.RawUI.WindowSize.Width
        if ($width -gt 0) { return $width }
    } catch {}
    try {
        $width = [int]$Host.UI.RawUI.BufferSize.Width
        if ($width -gt 0) { return $width }
    } catch {}
    try {
        $width = [int][Console]::WindowWidth
        if ($width -gt 0) { return $width }
    } catch {}
    return 80
}

function Get-ConsoleContentHeight {
    try {
        $height = [int]$Host.UI.RawUI.WindowSize.Height
        if ($height -gt 0) { return $height }
    } catch {}
    try {
        $height = [int][Console]::WindowHeight
        if ($height -gt 0) { return $height }
    } catch {}
    try {
        $height = [int]$Host.UI.RawUI.BufferSize.Height
        if ($height -gt 0) { return $height }
    } catch {}
    return 25
}

function Split-TextForMenuWidth {
    param(
        [string]$Text,
        [int]$Width
    )

    if ([string]::IsNullOrWhiteSpace($Text)) { return @() }
    if ($Width -lt 20) { $Width = 20 }

    $words = @($Text -split '\s+' | Where-Object { $_ })
    $lines = New-Object System.Collections.Generic.List[string]
    $current = ''
    foreach ($word in $words) {
        if ($current.Length -eq 0) {
            $current = $word
            continue
        }
        if (($current.Length + 1 + $word.Length) -le $Width) {
            $current = "$current $word"
        } else {
            [void]$lines.Add($current)
            $current = $word
        }
    }
    if ($current.Length -gt 0) { [void]$lines.Add($current) }
    return ,@($lines)
}

function Format-MainMenuItemLines {
    param(
        [object]$Item,
        [ValidateSet('Ultra', 'Professional', 'Standard')][string]$Tier,
        [int]$Width
    )

    $result = New-Object System.Collections.Generic.List[string]
    if ($Tier -eq 'Standard') {
        if ($Item.ShortDesc) {
            $prefix = "  {0}) {1,-27} -- " -f $Item.Number, $Item.Label
            $descWidth = [Math]::Max(24, $Width - $prefix.Length)
            $descLines = Split-TextForMenuWidth -Text $Item.ShortDesc -Width $descWidth
            if ($descLines.Count -gt 0) {
                [void]$result.Add($prefix + $descLines[0])
                for ($i = 1; $i -lt $descLines.Count; $i++) {
                    [void]$result.Add((' ' * $prefix.Length) + $descLines[$i])
                }
            }
        } else {
            [void]$result.Add(("  {0}) {1}" -f $Item.Number, $Item.Label))
        }
    } else {
        if ($Item.FullDesc.Count -gt 0) {
            $prefix = "  {0}) {1} -- " -f $Item.Number, $Item.Label
            $descText = ($Item.FullDesc -join ' ')
            $descWidth = [Math]::Max(28, $Width - $prefix.Length)
            $descLines = Split-TextForMenuWidth -Text $descText -Width $descWidth
            if ($descLines.Count -gt 0) {
                [void]$result.Add($prefix + $descLines[0])
                for ($i = 1; $i -lt $descLines.Count; $i++) {
                    [void]$result.Add((' ' * $prefix.Length) + $descLines[$i])
                }
            }
        } else {
            [void]$result.Add(("  {0}) {1}" -f $Item.Number, $Item.Label))
        }
    }
    return ,@($result)
}

function Format-MainMenuSectionLines {
    param(
        [object]$Section,
        [ValidateSet('Ultra', 'Professional', 'Standard')][string]$Tier,
        [int]$Width
    )

    $result = New-Object System.Collections.Generic.List[string]
    $ruleWidth = [Math]::Max(24, $Width)
    $rule = '-' * $ruleWidth
    [void]$result.Add($rule)
    [void]$result.Add(" $($Section.Header)")
    [void]$result.Add($rule)
    foreach ($item in $Section.Items) {
        foreach ($line in (Format-MainMenuItemLines -Item $item -Tier $Tier -Width $Width)) {
            [void]$result.Add($line)
        }
    }
    [void]$result.Add('')
    return ,@($result)
}

function Get-PaddedMainMenuRows {
    param(
        [object[]]$Rows,
        [int]$Padding
    )
    if ($Padding -le 0) { return @($Rows) }
    $prefix = ' ' * $Padding
    return @($Rows | ForEach-Object {
        if ($_.Segments) {
            New-ConsoleRenderSegmentRow -Segments (@((New-ConsoleRenderSegment -Text $prefix -Color 'White')) + $_.Segments)
        } else {
            New-ConsoleRenderRow -Text ($prefix + $_.Text) -Color $_.Color
        }
    })
}

function Get-MainMenuBannerRows {
    param([object]$Geometry)
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in (Get-ManagerBannerRows -Width $Geometry.MenuWidth -Height $Geometry.ViewportHeight)) {
        if ($row.Segments) {
            $segments = @($row.Segments | ForEach-Object { New-ConsoleRenderSegment -Text $_.Text -Color $_.Color })
            [void]$rows.Add((New-ConsoleRenderSegmentRow -Segments $segments))
        } else {
            [void]$rows.Add((New-ConsoleRenderRow -Text $row.Text -Color $row.Color))
        }
    }
    [void]$rows.Add((New-ConsoleRenderRow))
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Get-MainMenuFooterRows {
    param([object]$Geometry)
    $rows = New-Object System.Collections.Generic.List[object]
    $footer = 'Enter number and press Enter | H = Help | L = View Log | Q = Quit'
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'Enter number | H=Help | L=Log | Q=Quit' }
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'Enter number | H=Help | Q=Quit' }
    if ($Geometry.FrameEnabled) { [void]$rows.Add((New-ConsoleRenderRow -Text ('+' + ('-' * ($Geometry.FooterWidth - 2)) + '+') -Color 'DarkCyan')) }
    foreach ($line in (Split-TextForMenuWidth -Text $footer -Width $Geometry.FooterWidth)) {
        $pad = [Math]::Max(0, [Math]::Floor(($Geometry.FooterWidth - $line.Length) / 2))
        [void]$rows.Add((New-ConsoleRenderRow -Text ((' ' * $pad) + $line) -Color 'White'))
    }
    if ($Geometry.FrameEnabled) { [void]$rows.Add((New-ConsoleRenderRow -Text ('+' + ('-' * ($Geometry.FooterWidth - 2)) + '+') -Color 'DarkCyan')) }
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Get-MainMenuSectionRows {
    param(
        [object]$Section,
        [object]$Geometry,
        [ValidateSet('Full', 'Short', 'Labels')][string]$Detail = 'Full'
    )

    $rows = New-Object System.Collections.Generic.List[object]
    $color = Get-MainMenuSectionColor -Header $Section.Header
    $sectionHeader = $Section.Header
    if ($Geometry.Layout -eq 'ProfessionalTwoColumn' -and $sectionHeader -like 'Game Enhancements*') {
        $sectionHeader = 'Game Enhancements'
    }
    $header = (' {0} ' -f $sectionHeader.ToUpperInvariant())
    $ruleCount = [Math]::Max(4, $Geometry.ColumnWidth - $header.Length)
    [void]$rows.Add((New-ConsoleRenderRow -Text (($header + ('-' * $ruleCount)).Substring(0, [Math]::Min($Geometry.ColumnWidth, $header.Length + $ruleCount))) -Color $color))

    foreach ($item in $Section.Items) {
        [void]$rows.Add((New-ConsoleRenderRow -Text ('  {0}) {1}' -f $item.Number, $item.Label) -Color $color))
        if ($Detail -ne 'Labels') {
            if ($Geometry.Layout -eq 'ProfessionalTwoColumn') {
                $descText = Get-MainMenuDefaultDescription -Item $item
            } else {
                $descText = if ($Detail -eq 'Short') { $item.ShortDesc } else { ($item.FullDesc -join ' ') }
            }
            foreach ($line in (Split-TextForMenuWidth -Text $descText -Width $Geometry.WrapWidth)) {
                [void]$rows.Add((New-ConsoleRenderRow -Text ('      {0}' -f $line) -Color 'White'))
            }
        }
        if ($Geometry.ColumnCount -ne 2 -and $Detail -ne 'Labels') {
            [void]$rows.Add((New-ConsoleRenderRow))
        }
    }
    return $rows.ToArray()
}

function Join-MainMenuRenderColumns {
    param(
        [object[]]$LeftRows,
        [object[]]$RightRows,
        [object]$Geometry
    )

    $rows = New-Object System.Collections.Generic.List[object]
    $count = [Math]::Max($LeftRows.Count, $RightRows.Count)
    for ($i = 0; $i -lt $count; $i++) {
        $left = if ($i -lt $LeftRows.Count) { $LeftRows[$i] } else { New-ConsoleRenderRow }
        $right = if ($i -lt $RightRows.Count) { $RightRows[$i] } else { New-ConsoleRenderRow }
        $segments = @()
        if ($Geometry.FrameEnabled) {
            $segments += New-ConsoleRenderSegment -Text '| ' -Color 'DarkCyan'
        }
        $segments += New-ConsoleRenderSegment -Text ($left.Text.PadRight($Geometry.ColumnWidth)) -Color $left.Color
        $segments += New-ConsoleRenderSegment -Text ((' ' * [Math]::Max(0, [Math]::Floor(($Geometry.GutterWidth - 1) / 2))) + '|' + (' ' * [Math]::Max(0, $Geometry.GutterWidth - 1 - [Math]::Floor(($Geometry.GutterWidth - 1) / 2)))) -Color 'DarkCyan'
        $segments += New-ConsoleRenderSegment -Text ($right.Text.PadRight($Geometry.RightColumnWidth)) -Color $right.Color
        if ($Geometry.FrameEnabled) {
            $segments += New-ConsoleRenderSegment -Text ' |' -Color 'DarkCyan'
        }
        [void]$rows.Add((New-ConsoleRenderSegmentRow -Segments $segments))
    }
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Get-MainMenuBodyRows {
    param(
        [object[]]$Sections,
        [object]$Geometry
    )

    $detail = 'Full'
    if ($Geometry.Tier -eq 'Compact') { $detail = 'Labels' }
    if ($Geometry.Tier -eq 'Standard') { $detail = 'Labels' }
    if ($Geometry.ColumnCount -eq 2) { $detail = 'Short' }

    if ($Geometry.ColumnCount -eq 2) {
        $leftRows = @()
        $rightRows = @()
        foreach ($section in @($Sections[0], $Sections[2])) {
            $leftRows += Get-MainMenuSectionRows -Section $section -Geometry $Geometry -Detail $detail
        }
        foreach ($section in @($Sections[1], $Sections[3])) {
            $rightRows += Get-MainMenuSectionRows -Section $section -Geometry $Geometry -Detail $detail
        }
        return @(Join-MainMenuRenderColumns -LeftRows $leftRows -RightRows $rightRows -Geometry $Geometry)
    }

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($section in $Sections) {
        foreach ($row in (Get-MainMenuSectionRows -Section $section -Geometry $Geometry -Detail $detail)) {
            [void]$rows.Add($row)
        }
    }
    return @(Get-PaddedMainMenuRows -Rows $rows.ToArray() -Padding $Geometry.LeftPadding)
}

function Limit-MainMenuRowsToViewport {
    param(
        [object[]]$Rows,
        [int]$ViewportHeight
    )

    $maxRows = [Math]::Max(5, $ViewportHeight - 2)
    if ($Rows.Count -le $maxRows) { return @($Rows) }
    return @($Rows | Select-Object -First $maxRows)
}

# Truncates BODY rows only (never the banner or footer) while preserving
# actionable menu rows and their descriptions as atomic display units.
# Two-column streams are trimmed only at numbered-row boundaries, preventing
# a visible description from outliving its heading.
function Limit-MainMenuBodyRowsToBudget {
    param(
        [object[]]$BodyRows,
        [int]$BodyBudget
    )

    if ($BodyBudget -le 0) { return @() }
    if ($BodyRows.Count -le $BodyBudget) { return @($BodyRows) }

    $start = $BodyRows.Count - $BodyBudget
    $isColumnar = @($BodyRows | Where-Object { $_.Segments }).Count -gt 0
    if ($isColumnar) {
        while ($start -lt $BodyRows.Count) {
            $text = [string]$BodyRows[$start].Text
            if ($text -match '^\s+\d+\)\s+') { break }
            $start++
        }
    }
    if ($start -ge $BodyRows.Count) { return @() }
    return @($BodyRows[$start..($BodyRows.Count - 1)])
}

# Single-line banner ("TeknoParrot Manager v1.0 RC8") with no frame and no
# blank separator, for viewports too short for the normal framed banner (5-6
# rows) to leave any room for menu content -- see
# Get-MainMenuEmergencyCompactRows.
function Get-MainMenuMinimalBannerRows {
    param([object]$Geometry)
    $text = "TeknoParrot Manager {0}" -f (Get-ManagerVersionLine)
    $text = $text -replace '^TeknoParrot Manager Version ', 'TeknoParrot Manager v'
    if ($text.Length -gt $Geometry.MenuWidth -and $Geometry.MenuWidth -gt 3) {
        $text = $text.Substring(0, $Geometry.MenuWidth)
    }
    return @(Get-PaddedMainMenuRows -Rows @((New-ConsoleRenderRow -Text $text -Color 'Cyan')) -Padding $Geometry.LeftPadding)
}

# Single-line footer with no frame/rule, for the same reason as
# Get-MainMenuMinimalBannerRows above.
function Get-MainMenuMinimalFooterRows {
    param([object]$Geometry)
    $footer = 'Enter number | Q=Quit'
    if ($footer.Length -gt $Geometry.FooterWidth) { $footer = 'N | Q' }
    return @(Get-PaddedMainMenuRows -Rows @((New-ConsoleRenderRow -Text $footer -Color 'White')) -Padding $Geometry.LeftPadding)
}

# Packs every menu item's "N) Label" as densely as the viewport width
# allows, word-wrapping only when a token would overflow the line, instead
# of one item per row. This is the fallback for viewports too short to show
# even the normal Compact tier's one-item-per-row Labels rendering (e.g. the
# minimum supported 60x10 terminal) -- at that size, 4 section headers + 14
# item rows (18 rows) cannot fit no matter how much else is trimmed, so
# every option must share rows instead of some options being dropped
# entirely. Section grouping is intentionally not preserved here (headers
# are dropped) since the priority at this size is that every option NUMBER
# is visible and reachable, not that they stay visually grouped.
function Get-MainMenuFlowPackedItemRows {
    param(
        [int]$Width,
        [object]$Geometry
    )
    $tokens = @((Get-MainMenuItems) | ForEach-Object { '{0}) {1}' -f $_.Number, $_.Label })
    $wrapWidth = [Math]::Max(20, $Width)

    # Packs whole "N) Label" tokens greedily, never splitting one across two
    # lines -- unlike a generic word-wrap (e.g. Split-TextForMenuWidth),
    # which treats "4)" and "Crosshair" as separate words and can break an
    # option's number from its own label at a line boundary. A single
    # option's number and name staying on one line matters more here than
    # tight packing, since this is the presentation a very-short-viewport
    # user reads to figure out what to type.
    $lines = New-Object System.Collections.Generic.List[string]
    $current = ''
    foreach ($token in $tokens) {
        if ($current.Length -eq 0) {
            $current = $token
        } elseif (($current.Length + 2 + $token.Length) -le $wrapWidth) {
            $current = "$current  $token"
        } else {
            [void]$lines.Add($current)
            $current = $token
        }
    }
    if ($current.Length -gt 0) { [void]$lines.Add($current) }

    $rows = @($lines | ForEach-Object { New-ConsoleRenderRow -Text $_ -Color 'White' })
    return @(Get-PaddedMainMenuRows -Rows $rows -Padding $Geometry.LeftPadding)
}

# Emergency compact presentation for viewports too short to show all 15
# options one per row even with every description stripped (issue #104
# RC3-B correction: at the minimum supported 60x10 terminal, the normal
# Compact-tier body -- 4 section headers + 15 item rows, 19 rows minimum --
# cannot fit even after Limit-MainMenuBodyRowsToBudget trims it, so the
# normal path was silently dropping every item including 15 (Exit), leaving
# only the banner and footer visible. Reserving space for Exit and the
# footer is not enough on its own if the fix only protects those two and
# still drops every OTHER option -- this replaces the normal framed banner
# and footer with single-line minimal versions (freeing several rows) and
# flow-packs every item's "N) Label" as densely as the width allows, so
# every option number stays visible and reachable without scrolling, rather
# than choosing which options to silently omit.
function Get-MainMenuEmergencyCompactRows {
    param(
        [object]$Geometry,
        # Real terminal row budget (Max(5, real Height - 2)) -- when the
        # flow-packed item rows don't all fit alongside the minimal banner
        # and footer, those two are still NEVER dropped; item rows are
        # trimmed from the front instead (keeping the tail), so the last
        # item line -- which always ends with "15) Exit" -- and the footer
        # both survive even at a viewport too short to show every earlier
        # option. Below the documented 60x10 minimum this can still mean an
        # early option's line goes missing, but the footer and Exit itself
        # are the two guarantees that must never break.
        [int]$MaxRows = 0
    )
    $bannerRows = @(Get-MainMenuMinimalBannerRows -Geometry $Geometry)
    $footerRows = @(Get-MainMenuMinimalFooterRows -Geometry $Geometry)
    $itemRows = @(Get-MainMenuFlowPackedItemRows -Width ([Math]::Max(20, $Geometry.MenuWidth - $Geometry.LeftPadding)) -Geometry $Geometry)

    if ($MaxRows -gt 0) {
        $itemBudget = [Math]::Max(0, $MaxRows - $bannerRows.Count - $footerRows.Count)
        if ($itemRows.Count -gt $itemBudget) {
            # At the minimum supported viewport, retain every actionable
            # number even when labels cannot fit. Number-only packing is a
            # deliberate last resort; silently dropping choices is not.
            $lastMenuItem = @((Get-MainMenuItems))[-1]
            $tokens = @((Get-MainMenuItems) | ForEach-Object {
                if ($_.Number -eq $lastMenuItem.Number) { '{0}) {1}' -f $_.Number, $_.Label } else { '{0})' -f $_.Number }
            })
            $packed = New-Object System.Collections.Generic.List[string]
            $current = ''
            foreach ($token in $tokens) {
                if ($current.Length -eq 0) { $current = $token }
                elseif (($current.Length + 1 + $token.Length) -le $Geometry.MenuWidth) { $current = "$current $token" }
                else { [void]$packed.Add($current); $current = $token }
            }
            if ($current.Length -gt 0) { [void]$packed.Add($current) }
            $itemRows = @($packed | ForEach-Object { New-ConsoleRenderRow -Text $_ -Color 'White' })
        }
        $itemRows = Limit-MainMenuBodyRowsToBudget -BodyRows $itemRows -BodyBudget $itemBudget
    }

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $bannerRows) { [void]$rows.Add($row) }
    foreach ($row in $itemRows) { [void]$rows.Add($row) }
    foreach ($row in $footerRows) { [void]$rows.Add($row) }
    return @($rows.ToArray())
}

function Get-MainMenuVisibleOptionNumbers {
    param([object[]]$Rows)
    $numbers = New-Object System.Collections.Generic.List[int]
    foreach ($row in @($Rows)) {
        foreach ($match in [regex]::Matches([string]$row.Text, '(?<!\d)(\d{1,2})\)(?=\s|$)')) {
            $number = [int]$match.Groups[1].Value
            if (-not $numbers.Contains($number)) { [void]$numbers.Add($number) }
        }
    }
    return @($numbers | Sort-Object)
}

function New-MainMenuScreenResult {
    param([Parameter(Mandatory)]$Geometry, [Parameter(Mandatory)][object[]]$Rows, [int]$ViewportHeight = 0)
    if ($ViewportHeight -le 0) { $ViewportHeight = $Geometry.ViewportHeight }
    $expected = @((Get-MainMenuItems | ForEach-Object { [int]$_.Number }))
    $visible = @(Get-MainMenuVisibleOptionNumbers -Rows $Rows)
    $missing = @($expected | Where-Object { $visible -notcontains $_ })
    $allowed = ($ViewportHeight -ge 10 -and $expected.Count -gt 0 -and $missing.Count -eq 0)
    if (-not $allowed) {
        $fallbackRows = @()
        if ($ViewportHeight -ge 20) {
            $fallbackRows = @((Get-MainMenuBannerRows -Geometry $Geometry); (Get-MainMenuFlowPackedItemRows -Width ([Math]::Max(20, $Geometry.MenuWidth - $Geometry.LeftPadding)) -Geometry $Geometry); (Get-MainMenuFooterRows -Geometry $Geometry))
        } else {
            $fallbackRows = @(Get-MainMenuEmergencyCompactRows -Geometry $Geometry -MaxRows $ViewportHeight)
        }
        $fallbackVisible = @(Get-MainMenuVisibleOptionNumbers -Rows $fallbackRows)
        if ($ViewportHeight -ge 10 -and @($expected | Where-Object { $fallbackVisible -notcontains $_ }).Count -eq 0 -and $fallbackRows.Count -le [Math]::Max(5, $ViewportHeight - 2)) {
            $Rows = $fallbackRows
            $visible = $fallbackVisible
            $missing = @()
            $allowed = $true
        } else {
            $Rows = @((Get-MainMenuMinimalBannerRows -Geometry $Geometry); (New-ConsoleRenderRow -Text '  The menu options do not fit in this window.' -Color 'Yellow'); (New-ConsoleRenderRow -Text '  Resize the PowerShell window and press Enter to redraw.'))
        }
    }
    return [pscustomobject]@{ Geometry = $Geometry; Rows = @($Rows); VisibleOptionNumbers = $visible; MissingOptionNumbers = $missing; AllOptionsVisible = $allowed; PromptAllowed = $allowed }
}

function Get-MainMenuPromptText {
    param([Parameter(Mandatory)]$Screen, [Parameter(Mandatory)][int]$MaxNumber)
    if (-not $Screen.PromptAllowed) { return $null }
    return 'Enter 1-{0}: ' -f $MaxNumber
}

function Render-MainMenuScreen {
    param(
        [ValidateSet('Ultra', 'Professional', 'Standard', 'Compact')][string]$Tier,
        [int]$Width,
        [int]$Height,
        [ValidateSet('Auto', 'UltraTwoColumn', 'UltraCentered')][string]$UltraLayoutMode = 'Auto'
    )

    $geometry = Get-MainMenuGeometry -Tier $Tier -ViewportWidth $Width -ViewportHeight $Height -UltraLayoutMode $UltraLayoutMode
    $sections = @(Get-MainMenuSections)
    $bannerRows = @(Get-MainMenuBannerRows -Geometry $geometry)
    $footerRows = @(Get-MainMenuFooterRows -Geometry $geometry)
    $bodyRows = @(Get-MainMenuBodyRows -Sections $sections -Geometry $geometry)

    # Uses the caller's real requested $Height here, NOT $geometry.ViewportHeight
    # -- Get-MainMenuGeometry internally clamps ViewportHeight to a floor of 10
    # for its own column/description-width math, which is correct for that
    # purpose but would silently let more rows render than an actually-shorter
    # real terminal (e.g. height 8 or 9) can show without scrolling if reused
    # here for the row-count budget/cap.
    $maxTotalRows = [Math]::Max(5, $Height - 2)
    $reserved = $bannerRows.Count + $footerRows.Count
    $bodyBudget = [Math]::Max(0, $maxTotalRows - $reserved)

    # If the normal (one item per row) body can't fit every option even
    # after trimming, switch to the emergency flow-packed presentation
    # instead of silently dropping options -- see
    # Get-MainMenuEmergencyCompactRows. $totalItemCount is the number of
    # individual item rows the normal Labels-detail body needs at minimum
    # (ignoring section headers/blank lines, which are the first things
    # trimmed); if the budget can't even hold that many rows, some options
    # would be dropped, not just descriptions.
    $totalItemCount = (Get-MainMenuItems).Count
    if ($bodyBudget -lt $totalItemCount) {
        # $maxTotalRows (real Height - 2, not the geometry-clamped height)
        # is passed straight through as the row budget -- NOT run back
        # through Limit-MainMenuRowsToViewport's generic front-truncation,
        # which would cut off the LAST rows (the footer) once content
        # overflowed. Get-MainMenuEmergencyCompactRows reserves the banner
        # and footer unconditionally and only trims item rows if needed.
        $rows = Get-MainMenuEmergencyCompactRows -Geometry $geometry -MaxRows $maxTotalRows
        return New-MainMenuScreenResult -Geometry $geometry -Rows $rows -ViewportHeight $Height
    }

    $bodyRows = Limit-MainMenuBodyRowsToBudget -BodyRows $bodyRows -BodyBudget $bodyBudget

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $bannerRows) { [void]$rows.Add($row) }
    foreach ($row in $bodyRows) { [void]$rows.Add($row) }
    foreach ($row in $footerRows) { [void]$rows.Add($row) }
    return New-MainMenuScreenResult -Geometry $geometry -Rows (Limit-MainMenuRowsToViewport -Rows $rows.ToArray() -ViewportHeight $Height) -ViewportHeight $Height
}

function Write-ConsoleRenderRows {
    param([object[]]$Rows)
    foreach ($row in $Rows) {
        if ($row.Segments) {
            foreach ($segment in $row.Segments) {
                $segmentColor = if ($segment.Color) { $segment.Color } else { 'White' }
                Write-Host $segment.Text -ForegroundColor $segmentColor -NoNewline
            }
            Write-Host ''
            continue
        }
        $color = if ($row.Color) { $row.Color } else { 'White' }
        Write-Host $row.Text -ForegroundColor $color
    }
}

function Clear-ConsoleForFreshRender {
    Set-ConsoleRenderOrigin
    try {
        Clear-Host
        Set-ConsoleRenderOrigin
        return
    } catch {}

    try {
        [Console]::Clear()
        Set-ConsoleRenderOrigin
        return
    } catch {}

    Set-ConsoleRenderOrigin
    Write-Host ''
}

function Set-ConsoleRenderOrigin {
    try {
        $rawUi = $Host.UI.RawUI
        $zero = [System.Management.Automation.Host.Coordinates]::new(0, 0)
        $rawUi.CursorPosition = $zero
        $rawUi.WindowPosition = $zero
    } catch {}

    try {
        [Console]::SetCursorPosition(0, 0)
    } catch {}
}

function Center-MainMenuLines {
    param(
        [string[]]$Lines,
        [int]$ContentWidth,
        [int]$ViewportWidth
    )

    $padding = [Math]::Max(0, [Math]::Floor(($ViewportWidth - $ContentWidth) / 2))
    if ($padding -le 0) { return ,@($Lines) }

    $prefix = ' ' * $padding
    return ,@($Lines | ForEach-Object { $prefix + $_ })
}

function Join-MainMenuColumns {
    param(
        [string[]]$Left,
        [string[]]$Right,
        [int]$LeftWidth,
        [int]$Gap = 4
    )

    $result = New-Object System.Collections.Generic.List[string]
    $count = [Math]::Max($Left.Count, $Right.Count)
    for ($i = 0; $i -lt $count; $i++) {
        $leftLine = if ($i -lt $Left.Count) { $Left[$i] } else { '' }
        $rightLine = if ($i -lt $Right.Count) { $Right[$i] } else { '' }
        if ($rightLine.Length -gt 0) {
            [void]$result.Add($leftLine.PadRight($LeftWidth) + (' ' * $Gap) + $rightLine)
        } else {
            [void]$result.Add($leftLine)
        }
    }
    return ,@($result)
}

# Best-effort console maximize -- many hosts (redirected output, ISE, some
# CI/test runners) don't support resizing the window at all; this must never
# throw or block startup over a cosmetic nicety. Called once, not on every
# menu redraw -- unlike layout-tier detection, which does run every redraw
# so a user resizing mid-session still gets the right tier next time the
# menu draws.
function Set-ConsoleMaximizedIfSupported {
    param([object]$RawUi = $null)
    if ($script:TpmConsoleResizeAttempted) { return }
    $script:TpmConsoleResizeAttempted = $true
    try {
        if ($null -eq $RawUi) {
            try {
                if ([Console]::IsInputRedirected -or [Console]::IsOutputRedirected) { return }
            } catch {}
            $RawUi = $Host.UI.RawUI
        }
        $maxSize = $RawUi.MaxPhysicalWindowSize
        if ($maxSize.Width -gt 0 -and $maxSize.Height -gt 0) {
            $currentBuffer = $RawUi.BufferSize
            $targetWidth = [Math]::Max(1, $maxSize.Width)
            $targetHeight = [Math]::Max(1, $maxSize.Height)
            if ($currentBuffer.Width -lt $targetWidth -or $currentBuffer.Height -lt $targetHeight) {
                $bufferWidth = [Math]::Max($currentBuffer.Width, $targetWidth)
                $bufferHeight = [Math]::Max($currentBuffer.Height, $targetHeight)
                $RawUi.BufferSize = [System.Management.Automation.Host.Size]::new($bufferWidth, $bufferHeight)
            }
            $RawUi.WindowSize = [System.Management.Automation.Host.Size]::new([Math]::Min($targetWidth, $RawUi.BufferSize.Width), [Math]::Min($targetHeight, $RawUi.BufferSize.Height))
        }
    } catch {
        Write-Log "Set-ConsoleMaximizedIfSupported: could not resize console -- $_"
    }
}

# Renders the main menu at the given tier. Pure display -- never reads input,
# never touches $mode; the caller's existing Read-Host/switch dispatch is
# completely unchanged by this function or by which tier is chosen.
function Show-MainMenu {
    param(
        [ValidateSet('Ultra', 'Professional', 'Standard', 'Compact')][string]$Tier,
        [int]$Width = (Get-ConsoleContentWidth),
        [int]$Height = (Get-ConsoleContentHeight),
        [ValidateSet('Auto', 'UltraTwoColumn', 'UltraCentered')][string]$UltraLayoutMode = 'Auto',
        [switch]$ReturnScreen
    )
    $screen = Render-MainMenuScreen -Tier $Tier -Width $Width -Height $Height -UltraLayoutMode $UltraLayoutMode
    Clear-ConsoleForFreshRender
    Write-ConsoleRenderRows -Rows $screen.Rows
    if ($ReturnScreen) { return $screen }
}

function Resolve-MainMenuCommand {
    param([AllowEmptyString()][string]$InputText, [Parameter(Mandatory)][int]$MaxNumber)
    $choice = if ($null -eq $InputText) { '' } else { $InputText.Trim() }
    if ($choice -match '^\d+$') {
        $number = 0
        if ([int]::TryParse($choice, [ref]$number) -and $choice -eq [string]$number -and $number -ge 1 -and $number -le $MaxNumber) { return $choice }
        return $null
    }
    switch ($choice.ToUpperInvariant()) {
        'H' { return 'H' }
        'L' { return 'L' }
        'Q' { return 'Q' }
        default { return $null }
    }
}


function Show-MainMenuHelp {
    Clear-ConsoleForFreshRender
    Write-Host 'TeknoParrot Manager Help' -ForegroundColor Cyan
    Write-Host '========================' -ForegroundColor Cyan
    Write-Host '  1 AutoSync: extract and register games.'
    Write-Host '  2 Register only: register already extracted games.'
    Write-Host '  3-10 Setup and maintenance actions.'
    Write-Host '  11 Restore from a trusted backup.'
    Write-Host '  12 PostgreSQL setup and repair.'
    Write-Host '  13 Check for updates.  14 Create a support package.'
    Write-Host ''
    Write-Host '  Safe/read-only: Help, View Log, Health Check, and previews.'
    Write-Host '  File-changing actions: AutoSync, Register, setup, restore, and updates.'
    Write-Host '  Enter a number only when it is shown in the main menu.'
    Write-Host '  Press Enter to return to the main menu.'
    [void](Read-HostSafe '  Press Enter to return')
}

function Read-MainMenuChoiceResponsive {
    param(
        [string]$Prompt,
        [int]$InitialWidth,
        [int]$InitialHeight
    )

    $readHostPrompt = $Prompt.TrimEnd()
    if ($readHostPrompt.EndsWith(':')) {
        $readHostPrompt = $readHostPrompt.Substring(0, $readHostPrompt.Length - 1)
    }
    if ([string]::IsNullOrWhiteSpace($readHostPrompt)) { $readHostPrompt = 'Enter choice' }

    try {
        if ([Console]::IsInputRedirected) {
            # Redirected/piped stdin: never enter the keyboard-polling loop
            # below -- [Console]::KeyAvailable cannot see piped input, and
            # polling it here is exactly the 40-second hang from issue #135.
            # Read-HostSafe exits cleanly with a nonzero code the moment
            # stdin is exhausted, instead of looping forever re-reading an
            # already-closed stream.
            return [pscustomobject]@{ Redraw = $false; Value = (Read-HostSafe $readHostPrompt) }
        }
    } catch {
        # [Console]::IsInputRedirected itself threw (unusual host) -- log it
        # rather than silently swallowing (issue #135) and fall through to
        # the keyboard-polling loop, which has its own KeyAvailable-throws
        # fallback to Read-HostSafe below if a real keyboard also isn't
        # available.
        Write-Log "Read-MainMenuChoiceResponsive: [Console]::IsInputRedirected threw -- $_"
    }

    $value = ''

    Write-Host $Prompt -NoNewline
    while ($true) {
        $currentWidth = Get-ConsoleContentWidth
        $currentHeight = Get-ConsoleContentHeight
        if ($currentWidth -ne $InitialWidth -or $currentHeight -ne $InitialHeight) {
            return [pscustomobject]@{ Redraw = $true; Value = '' }
        }
        try {
            if ([Console]::KeyAvailable) {
                $key = [Console]::ReadKey($true)
                if ($key.Key -eq 'Enter') {
                    Write-Host ''
                    return [pscustomobject]@{ Redraw = $false; Value = $value }
                }
                if ($key.Key -eq 'Backspace') {
                    if ($value.Length -gt 0) {
                        $value = $value.Substring(0, $value.Length - 1)
                        Write-Host "`b `b" -NoNewline
                    }
                    continue
                }
                if ($key.KeyChar -and -not [char]::IsControl($key.KeyChar)) {
                    $value += [string]$key.KeyChar
                    Write-Host $key.KeyChar -NoNewline
                }
            } else {
                Start-Sleep -Milliseconds 80
            }
        } catch {
            # [Console]::KeyAvailable/ReadKey threw -- no real keyboard
            # available either. Log it (issue #135: never silently swallow
            # an input-detection failure) and fall back to Read-HostSafe,
            # which exits cleanly if stdin turns out to be exhausted too.
            Write-Log "Read-MainMenuChoiceResponsive: keyboard polling threw -- $_"
            Write-Host ''
            return [pscustomobject]@{ Redraw = $false; Value = (Read-HostSafe $readHostPrompt) }
        }
    }
}

# =============================================================================
# MAIN MENU LOOP
# =============================================================================
# $MinBoundForArchetype must be set before the loop starts, not only in
# SECTION 10 below -- the standalone "Propagate Controls" menu handler
# (PropagateControls mode) runs entirely inside this loop and returns via
# `continue` without ever reaching SECTION 10. Before this fix, running
# Propagate Controls as the first action of a session left the variable
# $null, which [int]$minBound coerced to 0 in Build-ArchetypePool -- every
# profile (including fully unbound ones) then qualified as an archetype,
# every UserProfiles file was treated as a pool source, and propagation
# silently produced "Games updated: 0" with no per-game report lines. See
# issue #139 and LESSONS_LEARNED.md.
$MinBoundForArchetype = 5
try {
Set-ConsoleMaximizedIfSupported
function Invoke-TpmFfbSetupMode {
    param([Parameter(Mandatory)][string]$UserProfilesDir, [Parameter(Mandatory)][string]$TpRoot, [string]$ScriptRoot = $PSScriptRoot, [scriptblock]$EventSink = $null)
    Write-Host ""
    Write-Host "  Force feedback makes a wheel or stick push back / rumble to match" -ForegroundColor Cyan
    Write-Host "  what's happening on screen (e.g. road vibration, recoil, collisions)." -ForegroundColor Cyan
    Write-Host "  Two independent ways to get it, covering different games -- both can" -ForegroundColor Cyan
    Write-Host "  be set up, neither requires the other:" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "    1) FFB Blaster -- TeknoParrot's own built-in force feedback." -ForegroundColor Cyan
    Write-Host "       Native and well-integrated, but requires an active paid" -ForegroundColor Cyan
    Write-Host "       TeknoParrot membership (teknoparrot.com/en/Home/Subscription)." -ForegroundColor Cyan
    Write-Host "    2) Third-party FFB plugin -- a free, separately-maintained DLL" -ForegroundColor Cyan
    Write-Host "       (mightymikem/FFBArcadePlugin) that adds force feedback to a" -ForegroundColor Cyan
    Write-Host "       different set of arcade titles. No subscription needed." -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  If a game is covered by both, you'll be asked which one to use for it." -ForegroundColor Cyan
    $status = New-TpmWorkflowStatusContext -WorkflowKey 'FFBSetup' -Title 'Force feedback setup' -EventSink $EventSink -Steps @(
        @{ Id = 'inspect'; Label = 'Check available force-feedback options' }
        @{ Id = 'native'; Label = 'Apply the approved native option' }
        @{ Id = 'plugin'; Label = 'Download and apply the optional plugin' }
        @{ Id = 'verify'; Label = 'Verify ownership and results' }
    )
    [void](Start-TpmWorkflowStatus -Context $status)
    [void](Start-TpmWorkflowStep -Context $status -StepId 'inspect' -Activity 'Checking force-feedback options')
    [void](Complete-TpmWorkflowStep -Context $status -Summary 'Force-feedback options checked' -NextStep 'Apply the approved native option')
    [void](Start-TpmWorkflowStep -Context $status -StepId 'native' -Activity 'Applying the native option')
    $nativeCodes = Invoke-FFBBlasterSetup -UserProfilesDir $UserProfilesDir -TpRoot $TpRoot
    [void](Complete-TpmWorkflowStep -Context $status -Summary 'Native force feedback step finished' -NextStep 'Choose whether to add the optional plugin')
    [void](Set-TpmWorkflowWaiting -Context $status -Message 'TPM can add the optional third-party force-feedback plugin.' -UserAction 'Answer Y or N')
    $choice = (Read-HostSafe 'Also set up the free third-party FFB plugin? (Y/N)').Trim().ToUpper()
    [void](Resume-TpmWorkflowStatus -Context $status)
    if ($choice -eq 'Y') {
        [void](Start-TpmWorkflowStep -Context $status -StepId 'plugin' -Activity 'Downloading and applying the optional plugin')
        $plugin = Invoke-FFBPluginSetup -UserProfilesDir $UserProfilesDir -CacheDir (Join-Path $ScriptRoot 'FFBPlugin') -NativeEnabledCodes $nativeCodes
        if (-not ($plugin -and $plugin.Succeeded)) {
            [void](Set-TpmWorkflowFailure -Context $status -FailureId 'ffb-plugin-failed' -Message 'The optional force-feedback plugin was not completed.' -DataSafety 'TPM did not claim a complete third-party plugin deployment.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            [void](Read-HostSafe 'Press Enter to acknowledge the force-feedback result')
            [void](Acknowledge-TpmWorkflowFailure -Context $status -FailureId 'ffb-plugin-failed')
            [void](Stop-TpmWorkflowStatus -Context $status -Reason 'Force-feedback setup stopped')
            [void](Close-TpmWorkflowStatus -Context $status)
            return [pscustomobject]@{ Completed = $false; Context = $status }
        }
        [void](Complete-TpmWorkflowStep -Context $status -Outcome Fixed -Summary 'Optional plugin step finished' -NextStep 'Verify force-feedback ownership')
    } else {
        [void](Start-TpmWorkflowStep -Context $status -StepId 'plugin' -Activity 'Optional plugin skipped by user choice')
        [void](Complete-TpmWorkflowStep -Context $status -Outcome Skipped -Summary 'Optional plugin skipped')
        Write-Log 'FFBPlugin setup: skipped by user choice.'
    }
    [void](Start-TpmWorkflowStep -Context $status -StepId 'verify' -Activity 'Verifying force-feedback results')
    [void](Complete-TpmWorkflowStep -Context $status -Summary 'Force-feedback results recorded')
    [void](Complete-TpmWorkflowStatus -Context $status -Summary 'Force-feedback setup finished')
    [void](Close-TpmWorkflowStatus -Context $status)
    return [pscustomobject]@{ Completed = $true; Context = $status }
}

while ($true) {
    # Refresh the drive-info snapshot at the start of each menu iteration so
    # any drive changes since the last pass (USB ejected, network share
    # reconnected to a different letter) are picked up rather than using
    # stale cached data from the previous mode's run.
    Clear-LocalDriveInfoCache
$mode = $null

    # A just-finished preview run's "Apply for real now?" prompt was
    # answered Y -- silently re-enter the same mode instead of showing
    # the menu again, and force a real (non-preview) pass this time.
    if ($pendingApplyMode) {
        $mode = $pendingApplyMode
        $pendingApplyMode = $null
        $forceRealApply = $true
    }
    if ($mode) {
        # Skip straight past the menu -- fall through to the mode body below.
    } else {
    # Show-MainMenu (issue #104): renders from Get-MainMenuSections at
    # whichever layout tier fits the current console window. Detected fresh
    # every redraw so a mid-session resize picks the right tier next time,
    # not just at startup.
    $menuMaxNumber = (Get-MainMenuItems | Measure-Object -Property Number -Maximum).Maximum
    $fullTierLineCount = 4 + (@(Get-MainMenuSections | ForEach-Object {
        3 + ($_.Items | ForEach-Object { 1 + $_.FullDesc.Count } | Measure-Object -Sum).Sum
    }) | Measure-Object -Sum).Sum
    $consoleWidth  = Get-ConsoleContentWidth
    $consoleHeight = Get-ConsoleContentHeight
    $menuTier = Get-ConsoleLayoutTier -Width $consoleWidth -Height $consoleHeight -RequiredFullLines $fullTierLineCount
    $menuLayoutMode = if ($menuExpanded -and $menuTier -eq 'Ultra') { 'UltraCentered' } else { 'Auto' }
    $screen = Show-MainMenu -Tier $menuTier -Width $consoleWidth -Height $consoleHeight -UltraLayoutMode $menuLayoutMode -ReturnScreen
    if (-not $screen.PromptAllowed) {
        [void](Read-HostSafe '  Resize the window, then press Enter to redraw')
        continue
    }
    if ($Unattended) {
        Write-Host "  [Unattended] Mode must be set before starting." -ForegroundColor Red
        Write-Log "ERROR: Unattended mode -- reached menu loop."; exit 1
    }
    $choiceResult = Read-MainMenuChoiceResponsive -Prompt ("Enter 1-{0}: " -f $menuMaxNumber) -InitialWidth $consoleWidth -InitialHeight $consoleHeight
    if ($choiceResult.Redraw) { continue }
    $modeChoice = Resolve-MainMenuCommand -InputText $choiceResult.Value -MaxNumber $menuMaxNumber
    if ($null -eq $modeChoice) {
        Write-Host "  Invalid choice. Enter 1-15. Commands: H = Help, L = View Log, Q = Quit." -ForegroundColor Yellow
        continue
    }
    if ($modeChoice -eq 'H') {
        Show-MainMenuHelp
        continue
    }
    if ($modeChoice -eq 'L') {
        $logResult = Open-TpmLogsAndReports -ScriptRoot $PSScriptRoot
        if ($logResult.Succeeded) {
            Write-Host ("  Log folder opened: {0}" -f $logResult.Path) -ForegroundColor Green
        } else {
            Write-Host ("  Could not open the log folder: {0}" -f $logResult.Error) -ForegroundColor Yellow
        }
        [void](Read-HostSafe '  Press Enter to return to the main menu')
        continue
    }
    if ($modeChoice -eq 'Q') { break }
    switch ($modeChoice) {
        "1"     { $mode = "AutoSync"       }
        "2"     { $mode = "RegisterOnly"   }
        "3"     { $mode = "PropagateControls" }
        "4"     { $mode = "CrosshairSetup" }
        "5"     { $mode = "ReShadeSetup"   }
        "6"     { $mode = "DgVoodoo2Setup" }
        "7"     { $mode = "GpuFixSetup"    }
        "8"     { $mode = "FFBSetup"       }
        "9"     { $mode = "BepInExUpdate"  }
        "10"    { $mode = "HealthCheck"    }
        "11"    { $mode = "Restore"        }
        "12"    { $mode = "PostgresSetup"  }
        "13"    { $mode = "CheckForUpdates" }
        "14"    { $mode = "Support" }
        "15"    { break }
    }
    if ($modeChoice -eq "15") { break }
    }

    if ($mode -eq "Restore") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Restore from Backup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host "  1) TeknoParrot UserProfiles backup"
        Write-Host "  2) LaunchBox library backup (only relevant if you've used the"
        Write-Host "     direct LaunchBox integration)"
        Write-Host "  3) Postgres database backup (only relevant if you've used the"
        Write-Host "     Postgres setup mode)"
        $restoreStatus = New-TpmWorkflowStatusContext -WorkflowKey 'Restore' -Title 'Restore from backup' -Steps @(
            @{ Id = 'select'; Label = 'Select the backup to restore' }
            @{ Id = 'preflight'; Label = 'Check that the target application is closed' }
            @{ Id = 'apply'; Label = 'Restore the selected files or databases' }
            @{ Id = 'verify'; Label = 'Verify the restored result' }
        )
        [void](Start-TpmWorkflowStatus -Context $restoreStatus)
        [void](Start-TpmWorkflowStep -Context $restoreStatus -StepId 'select' -Activity 'Choosing a backup')
        [void](Set-TpmWorkflowWaiting -Context $restoreStatus -Message 'Choose which backup to restore.' -UserAction 'Enter a backup choice')
        $restoreChoice = (Read-HostSafe "  Enter 1-3")
        $restoreResult = $null
        if ($restoreChoice -eq "2") {
            if (-not $lbRoot) {
                Write-Host "  No LaunchBox root is configured yet -- nothing to restore." -ForegroundColor Yellow
            } else {
                $restoreResult = Invoke-RestoreLaunchBoxBackup -lbRoot $lbRoot
            }
        } elseif ($restoreChoice -eq "3") {
            $restoreResult = Invoke-RestorePostgresBackup
        } else {
            $restoreResult = Invoke-RestoreBackup -userProfilesDir $userProfilesDir
        }
        [void](Resume-TpmWorkflowStatus -Context $restoreStatus)
        if ($restoreResult -and $restoreResult.Succeeded) {
            [void](Complete-TpmWorkflowStep -Context $restoreStatus -Outcome Fixed -Summary 'Restore finished and was verified')
            [void](Complete-TpmWorkflowStatus -Context $restoreStatus -Summary 'Restore complete')
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
        } else {
            [void](Set-TpmWorkflowFailure -Context $restoreStatus -FailureId 'restore-failed' -Message 'The restore was not completed.' -DataSafety 'TPM did not claim a complete restore.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
        }
        Write-Host ""
        Write-Host "============================================" -ForegroundColor Cyan
        if ($restoreResult -and $restoreResult.Succeeded) {
            Write-Host "   Restore finished and was verified." -ForegroundColor Green
            Write-Log "Restore complete."
        } else {
            Write-Host "   Restore was not completed. The message above is the authoritative result." -ForegroundColor Yellow
            Write-Log "Restore did not complete; no success was claimed."
        }
        Write-Host "============================================" -ForegroundColor Cyan
        if (-not ($restoreResult -and $restoreResult.Succeeded)) {
            [void](Read-HostSafe '  Press Enter to acknowledge the restore result')
            [void](Acknowledge-TpmWorkflowFailure -Context $restoreStatus -FailureId 'restore-failed')
            [void](Stop-TpmWorkflowStatus -Context $restoreStatus -Reason 'Restore stopped')
            [void](Close-TpmWorkflowStatus -Context $restoreStatus)
        }
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "HealthCheck") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Library Health Check (read-only)" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $healthStatus = New-TpmWorkflowStatusContext -WorkflowKey 'HealthCheck' -Title 'Library health check' -Steps @(
            @{ Id = 'inspect'; Label = 'Check library and emulator state' }
            @{ Id = 'report'; Label = 'Show action items and controls readiness' }
        )
        [void](Start-TpmWorkflowStatus -Context $healthStatus)
        [void](Start-TpmWorkflowStep -Context $healthStatus -StepId 'inspect' -Activity 'Checking library and emulator state')
        Invoke-LibraryHealthCheck -UserProfilesDir $userProfilesDir -LogPath $logPath -TpRoot $tpRoot
        [void](Complete-TpmWorkflowStep -Context $healthStatus -Summary 'Library checks finished' -NextStep 'Review the action items')
        [void](Start-TpmWorkflowStep -Context $healthStatus -StepId 'report' -Activity 'Preparing the read-only summary')
        [void](Complete-TpmWorkflowStep -Context $healthStatus -Summary 'Read-only action items prepared')
        [void](Complete-TpmWorkflowStatus -Context $healthStatus -Summary 'Health check finished')
        [void](Close-TpmWorkflowStatus -Context $healthStatus)
        Write-Host ""
        Write-Host "============================================" -ForegroundColor Cyan
        Write-Host "   Done." -ForegroundColor Cyan
        Write-Host "============================================" -ForegroundColor Cyan
        Write-Log "Health check complete."
        if ($Unattended) {
            # An unattended run has no further mode to select -- looping back
            # to the menu would immediately re-hit "Mode must be set before
            # starting" and exit 1, turning a genuinely successful health
            # check into a reported failure. Exit cleanly instead; no other
            # mode currently supports a config-driven -Unattended entry
            # point, so this is the only completion path that needs it.
            Write-Log "Unattended: health check complete -- exiting."
            exit 0
        }
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "PostgresSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " PostgreSQL Setup (Incredible Technologies games)" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $postgresStatus = New-TpmWorkflowStatusContext -WorkflowKey 'PostgresSetup' -Title 'PostgreSQL setup' -Steps @(
            @{ Id = 'scan'; Label = 'Check which games need PostgreSQL' }
            @{ Id = 'backup'; Label = 'Make a verified safety backup' }
            @{ Id = 'reset'; Label = 'Repair and verify the database password' }
            @{ Id = 'save'; Label = 'Save the repaired settings' }
            @{ Id = 'database'; Label = 'Back up existing databases' }
            @{ Id = 'profiles'; Label = 'Finish game database setup' }
        )
        $script:PostgresRecoveryStatus = $postgresStatus
        [void](Start-TpmWorkflowStatus -Context $postgresStatus)
        [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'scan' -Activity 'Checking registered games')
        $postgresResumeState = $null
        if ($isPostgresRecoveryResume) {
            try {
                $postgresResumeState = Read-PostgresRecoveryState -StatePath $PostgresRecoveryResumeToken -ExpectedConfigPath $configPath -ExpectedScriptPath (Join-Path $PSScriptRoot 'TeknoParrot-Manager.ps1') -ExpectedTpRoot $tpRoot -ExpectedUserProfilesDir (Join-Path $tpRoot 'UserProfiles')
            } catch {
                Exit-PostgresRecoveryResume -Message 'TPM could not safely continue the protected PostgreSQL setup.'
            }
            $script:PostgresRecoveryResumeState = $postgresResumeState
            if (-not (Test-RunningAsAdministrator)) {
                Exit-PostgresRecoveryResume -Message 'Windows did not give TPM the permission needed to continue the protected PostgreSQL setup.'
            }
            Write-Host '  TPM is continuing the PostgreSQL setup automatically.' -ForegroundColor Cyan
        }
        Write-Host "  Scanning registered games for Postgres requirements..." -ForegroundColor DarkGray
        $pgProfiles = @(Get-ChildItem -LiteralPath $userProfilesDir -Filter '*.xml' -File -ErrorAction SilentlyContinue | Where-Object { $_.Directory.Name -ne 'FullBackup' } | Sort-Object Name)
        $needCount = 0; $scanBlocked = $false
        foreach ($pf in $pgProfiles) {
            try {
                $doc = Read-Xml $pf.FullName
                if ($doc.GameProfile -and (Test-GameNeedsPostgres $doc)) { $needCount++ }
            } catch { $scanBlocked = $true; Write-Log "Postgres setup: profile scan failed for $($pf.BaseName); recovery is blocked." }
        }
        if ($scanBlocked) {
            Write-Host "  Could not safely scan every registered profile -- no changes made." -ForegroundColor Red
            if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TPM could not safely read every registered game profile.' }
            [void](Set-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-scan' -Message 'TPM could not safely check every registered game.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            [void](Read-HostSafe '  Press Enter to acknowledge this message')
            [void](Acknowledge-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-scan')
            [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL scan stopped')
            [void](Close-TpmWorkflowStatus -Context $postgresStatus)
            [void](Read-Host "  Press Enter to return to menu")
            continue
        }
        [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Succeeded -Summary 'Game requirements checked' -NextStep 'Make a verified safety backup')
        if ($needCount -eq 0) {
            Write-Host "  No registered games need PostgreSQL -- nothing to do." -ForegroundColor Green
            Write-Log "Postgres setup: no Postgres-needing games registered."
            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'backup' -Activity 'No PostgreSQL repair is needed')
            [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Skipped -Summary 'No registered game needs PostgreSQL')
            [void](Complete-TpmWorkflowStatus -Context $postgresStatus -Summary 'No action needed')
            [void](Close-TpmWorkflowStatus -Context $postgresStatus)
            if ($isPostgresRecoveryResume) {
                [void](Remove-PostgresRecoveryState -Path $postgresResumeState.Path -ClaimPath $postgresResumeState.ClaimPath)
                Write-Host '  The automatic PostgreSQL setup is complete.' -ForegroundColor Green
                [void](Read-HostSafe '  Press Enter to close TPM')
                exit 0
            }
            [void](Read-Host "  Press Enter to return to menu")
            continue
        }
        Write-Host ("  {0} registered game(s) need PostgreSQL." -f $needCount) -ForegroundColor Cyan
        if (-not (Test-PostgresInstalled) -and -not (Test-RunningAsAdministrator)) {
            Write-PostgresAdministratorGuidance -Operation Install
            [void](Set-TpmWorkflowWaiting -Context $postgresStatus -Message 'Windows needs permission to install PostgreSQL.' -UserAction 'Approve the Windows permission box')
            $elevated = Start-PostgresRecoveryAsAdministrator -ConfigPath $configPath -ScriptPath (Join-Path $PSScriptRoot 'TeknoParrot-Manager.ps1') -TpRoot $tpRoot -UserProfilesDir $userProfilesDir -Operation Install
            if ($elevated) {
                [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Fixed -Summary 'PostgreSQL installation continued automatically')
                [void](Complete-TpmWorkflowStatus -Context $postgresStatus -Summary 'PostgreSQL installation finished')
                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                exit 0
            }
            Write-Log 'Postgres setup: automatic installation handoff did not complete.'
            [void](Set-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-install-handoff' -Message 'Windows permission was not granted, so PostgreSQL was not installed.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            [void](Read-HostSafe '  Press Enter to acknowledge this message')
            [void](Acknowledge-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-install-handoff')
            [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL installation stopped')
            [void](Close-TpmWorkflowStatus -Context $postgresStatus)
            [void](Read-HostSafe "  Press Enter to return to menu")
            continue
        }
        if ($isPostgresRecoveryResume -and $postgresResumeState.Operation -eq 'Recovery' -and -not (Test-PostgresInstalled)) {
            Exit-PostgresRecoveryResume -Message 'The PostgreSQL installation was not available when TPM resumed the repair.'
        }
        $postgresServiceWasRunning = $null
        $postgresServiceRestoreFailed = $false
        if (Test-PostgresInstalled) {
            try {
                $serviceBeforeRecovery = Get-Service -Name $script:PostgresServiceName -ErrorAction Stop
                $postgresServiceWasRunning = ([string]$serviceBeforeRecovery.Status -ne 'Stopped')
            } catch {
                Write-Host '  TPM could not verify PostgreSQL service state. No changes were made.' -ForegroundColor Red
                Write-Log 'Postgres setup: service state could not be verified before the transaction.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TPM could not verify the PostgreSQL service state before continuing.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-service-state' -Message 'PostgreSQL service state could not be verified.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                continue
            }
        }

        $superPwPlain = $null
        $recoveryBackup = $null
        $outPw = $null
        try {
            if (Test-PostgresInstalled) {
                Write-Host "  PostgreSQL is already installed -- existing data will be preserved." -ForegroundColor Green
                if ($isPostgresRecoveryResume -and $postgresResumeState.Operation -eq 'Recovery') {
                    $typedPwPlain = $postgresResumeState.PasswordPlain
                    if (Test-PostgresPassword -SuperPasswordPlain $typedPwPlain) {
                        $superPwPlain = $typedPwPlain
                        $postgresSuperPasswordEncrypted = $postgresResumeState.PasswordOriginEncrypted
                    } else {
                        $recovery = Invoke-PostgresSelectedPasswordRecovery -UserProfilesDir $userProfilesDir -PasswordPlain $typedPwPlain -StatusContext $postgresStatus
                        if (-not $recovery.Succeeded) {
                            if ($recovery.Backup.Path) { Write-Host ("  Recovery BLOCKED. Evidence: {0}" -f $recovery.Backup.Path) -ForegroundColor Red }
                            Exit-PostgresRecoveryResume -Message ('TPM could not complete the protected PostgreSQL repair ({0}).' -f $recovery.Reason)
                        }
                        $recoveryBackup = $recovery.Backup
                        $superPwPlain = $typedPwPlain
                        $postgresSuperPasswordEncrypted = $postgresResumeState.PasswordOriginEncrypted
                    }
                } else {
                    if ($postgresSuperPasswordEncrypted) {
                        try {
                            $secure = ConvertTo-SecureString -String $postgresSuperPasswordEncrypted
                            $savedPwPlain = ConvertFrom-SecureStringPlain $secure
                            if (Test-PostgresPassword -SuperPasswordPlain $savedPwPlain) { $superPwPlain = $savedPwPlain }
                            else { Write-Log 'Postgres setup: saved password did not authenticate; guided recovery is required.' }
                        } catch { Write-Log 'Postgres setup: saved password could not be verified; guided recovery is required.' }
                        finally { $savedPwPlain = $null }
                    }
                    if (-not $superPwPlain) {
                        Write-Host "  PostgreSQL needs attention: the saved PostgreSQL password cannot be used." -ForegroundColor Yellow
                        Write-Host "  TPM can repair it automatically. TPM will make and verify a safety backup first." -ForegroundColor Yellow
                        Write-Host "  Existing PostgreSQL data is preserved; after repair TPM verifies the password works." -ForegroundColor DarkGray
                        $repairNow = (Read-HostSafe '  Repair the PostgreSQL password now? (Y/N)').ToUpper()
                        if ($repairNow -ne 'Y') {
                            Write-Host '  Nothing was changed. The PostgreSQL setup was not completed.' -ForegroundColor Yellow
                            [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL repair declined')
                            [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                            [void](Read-HostSafe '  Press Enter to return to menu')
                            continue
                        }
                        Write-Host '  Choose a new PostgreSQL password for TPM to use.' -ForegroundColor Cyan
                        Write-Host '  The password must not be blank. TPM does not add an extra complexity rule; enter it twice to confirm.' -ForegroundColor DarkGray
                        Write-Host '  The password is masked and will not be displayed, logged, or placed in command-line arguments.' -ForegroundColor DarkGray
                        $typedPwPlain = Read-ConfirmedPostgresPassword 'the new PostgreSQL database password'
                        if (Test-PostgresPassword -SuperPasswordPlain $typedPwPlain) {
                            $superPwPlain = $typedPwPlain
                        } else {
                            if (-not (Test-RunningAsAdministrator)) {
                                Write-PostgresAdministratorGuidance -Operation Recovery
                                [void](Set-TpmWorkflowWaiting -Context $postgresStatus -Message 'Windows needs permission to repair PostgreSQL.' -UserAction 'Approve the Windows permission box')
                                $elevated = Start-PostgresRecoveryAsAdministrator -ConfigPath $configPath -ScriptPath (Join-Path $PSScriptRoot 'TeknoParrot-Manager.ps1') -TpRoot $tpRoot -UserProfilesDir $userProfilesDir -Operation Recovery -PasswordPlain $typedPwPlain
                                if ($elevated) {
                                    [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Fixed -Summary 'PostgreSQL repair continued automatically')
                                    [void](Complete-TpmWorkflowStatus -Context $postgresStatus -Summary 'PostgreSQL repair finished')
                                    [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                                    exit 0
                                }
                                Write-Log 'Postgres setup: automatic password-repair handoff did not complete.'
                                [void](Set-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-recovery-handoff' -Message 'Windows permission was not granted, so PostgreSQL was not repaired.' -DataSafety 'The chosen password was not applied by TPM.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
                                [void](Read-HostSafe '  Press Enter to acknowledge this message')
                                [void](Acknowledge-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-recovery-handoff')
                                [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL repair stopped')
                                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                                [void](Read-HostSafe '  Press Enter to return to menu')
                                continue
                            }
                            $directRecoverySucceeded = $false
                            while (-not $directRecoverySucceeded) {
                                $recovery = Invoke-PostgresSelectedPasswordRecovery -UserProfilesDir $userProfilesDir -PasswordPlain $typedPwPlain -StatusContext $postgresStatus
                                if ($recovery.Succeeded) {
                                    $recoveryBackup = $recovery.Backup
                                    $superPwPlain = $typedPwPlain
                                    $directRecoverySucceeded = $true
                                    break
                                }
                                Write-Host '  PostgreSQL repair did not finish. Nothing was reported as complete.' -ForegroundColor Red
                                if ($recovery.Reason) { Write-Host ("  What happened: {0}" -f $recovery.Reason) -ForegroundColor Yellow }
                                if ($recovery.Backup.Path) { Write-Host ("  Verified backup evidence: {0}" -f $recovery.Backup.Path) -ForegroundColor Yellow }
                                Write-Host '  TPM can try the same approved repair again without asking for the password again.' -ForegroundColor Yellow
                                Write-Log 'Postgres setup: direct recovery failed; user acknowledgement and retry offered.'
                                [void](Set-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-direct-recovery' -Message 'PostgreSQL repair did not finish.' -DataSafety 'The verified backup remains available; TPM did not report setup complete.' -RecoveryActions @(@{ Id = 'Retry'; Label = 'Try the repair again' }; @{ Id = 'Stop'; Label = 'Stop safely' }))
                                [void](Read-HostSafe '  Press Enter to acknowledge the repair result')
                                [void](Acknowledge-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-direct-recovery')
                                [void](Update-TpmWorkflowActivity -Context $postgresStatus -Activity 'Waiting for your retry choice')
                                $retryDirect = (Read-HostSafe '  Try the PostgreSQL repair again? (Y/N)').ToUpper()
                                if ($retryDirect -ne 'Y') {
                                    [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL repair stopped')
                                    [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                                    break
                                }
                            }
                            if (-not $directRecoverySucceeded) { continue }
                        }
                    }
                }
            } else {
                $outPw = [ref]$null
                if (-not (Install-Postgres83 -OutSuperPasswordPlain $outPw)) {
                    Write-Host "  PostgreSQL setup did not complete -- no profile changes made." -ForegroundColor Red
                    if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'PostgreSQL could not be installed successfully.' }
                    [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-install-failed' -Message 'PostgreSQL installation did not complete.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                    continue
                }
                $superPwPlain = $outPw.Value
            }

            if (-not $recoveryBackup) { $recoveryBackup = New-PostgresRecoveryBackup -UserProfilesDir $userProfilesDir }
            if (-not $recoveryBackup.Verified) {
                Write-Host ("  Recovery BLOCKED. No profile changes were made. Evidence: {0}" -f $recoveryBackup.Path) -ForegroundColor Red
                Write-Log 'Postgres setup: verified recovery evidence was unavailable before configuration changes.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TPM could not verify the protected backup before continuing PostgreSQL setup.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-backup-unverified' -Message 'Verified PostgreSQL recovery evidence was unavailable.' -DataSafety 'No PostgreSQL or profile changes were made.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                continue
            }
            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'database' -Activity 'Backing up existing databases')
            Write-Host "  Backing up existing Postgres databases..." -ForegroundColor Cyan
            $pgBackup = Backup-PostgresDatabases -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain
            $leavePostgres = $false
            while (-not $pgBackup.Succeeded) {
                Write-Host "  PostgreSQL setup stopped because the database backup did not complete." -ForegroundColor Red
                Write-Host "  Nothing was changed." -ForegroundColor Green
                if (@($pgBackup.FailedDatabases).Count -gt 0) { Write-Host ("  Affected games/databases: {0}" -f (@($pgBackup.FailedDatabases) -join ', ')) -ForegroundColor Yellow }
                Write-Host "  [R] Retry backup  [S] Skip PostgreSQL setup  [D] Show details  [B] Back to main menu"
                $backupChoice = (Read-HostSafe "  Choice, default R" -Default 'R').Trim().ToUpper()
                if ($backupChoice -eq 'D') {
                    Write-Host "  PostgreSQL backup details" -ForegroundColor Cyan
                    if ($pgBackup.Path) { Write-Host ("    Backup evidence: {0}" -f $pgBackup.Path) -ForegroundColor DarkGray }
                    foreach ($failedDatabase in @($pgBackup.FailedDatabases)) { Write-Host ("    Failed game/database: {0}" -f $failedDatabase) -ForegroundColor DarkGray }
                    foreach ($failureDetail in @($pgBackup.FailureDetails)) { Write-Host ("    Cause: {0}" -f $failureDetail) -ForegroundColor DarkGray }
                    Write-Log ("Postgres backup details shown. FailedDatabases={0}; FailureDetails={1}" -f (@($pgBackup.FailedDatabases) -join '|'), (@($pgBackup.FailureDetails) -join '|'))
                    continue
                }
                if ($backupChoice -eq 'R') {
                    $pgBackup = Backup-PostgresDatabases -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain
                    continue
                }
                if ($backupChoice -eq 'S' -or $backupChoice -eq 'B') { $leavePostgres = $true; break }
                Write-Host "  Invalid choice. Choose R, S, D, or B." -ForegroundColor Yellow
            }
            if ($isPostgresRecoveryResume -and (-not $pgBackup.Succeeded -or $leavePostgres)) { Exit-PostgresRecoveryResume -Message 'TPM could not finish the PostgreSQL database backup.' }
            if ($leavePostgres) {
                [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL setup skipped')
                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                continue
            }
            if (-not $pgBackup.Succeeded) { continue }
            if ($pgBackup.Path) { Write-Host ("  Database backup saved: {0}" -f $pgBackup.Path) -ForegroundColor DarkCyan }
            else { Write-Host "  No existing databases needed backup." -ForegroundColor DarkGray }
            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'save' -Activity 'Saving the repaired settings')
            if (-not $isPostgresRecoveryResume) { $postgresSuperPasswordEncrypted = ConvertTo-PostgresEncryptedPassword $superPwPlain }
            if (-not (Save-Config)) {
                Write-Host "  PostgreSQL setup stopped because the repaired settings could not be saved." -ForegroundColor Red
                Write-Log 'Postgres setup: encrypted password configuration save failed after database backup.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TPM could not save the protected PostgreSQL password configuration.' }
                [void](Stop-TpmWorkflowStatus -Context $postgresStatus -Reason 'PostgreSQL setup stopped')
                [void](Close-TpmWorkflowStatus -Context $postgresStatus)
                continue
            }
            [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Succeeded -Summary 'Repaired settings saved' -NextStep 'Finish game database setup')



            [void](Start-TpmWorkflowStep -Context $postgresStatus -StepId 'profiles' -Activity 'Finishing game database setup')
            Write-Host "  Configuring games and creating only missing databases..." -ForegroundColor Cyan
            $pgResults = Invoke-PostgresGameSetup -UserProfilesDir $userProfilesDir -SuperPasswordPlain $superPwPlain -RecoveryBackup $recoveryBackup
            if ($pgResults.RecoveryBlocked) {
                Write-Host ("  Recovery BLOCKED. No recovery-complete result was reported. Evidence: {0}" -f $pgResults.BackupPath) -ForegroundColor Red
                Write-Log 'Postgres setup: profile population was recovery-blocked.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TPM could not safely finish configuring the PostgreSQL game profiles.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-profile-recovery' -Message 'PostgreSQL profile setup was recovery-blocked.' -DataSafety 'No recovery-complete result was reported.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                continue
            }
            if ([int]$pgResults.Errors -gt 0) {
                Write-Host ("  PostgreSQL setup reported {0} error(s); TPM will not claim recovery is complete." -f $pgResults.Errors) -ForegroundColor Red
                Write-Log 'Postgres setup: errors were reported; completion was not claimed.'
                if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TPM could not verify a clean PostgreSQL setup result.' }
                [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-profile-errors' -Message 'PostgreSQL game setup reported errors.' -DataSafety 'TPM did not claim recovery complete.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                continue
            }
            Write-Host ""
            Write-Host "  Results:" -ForegroundColor Cyan
            [void](Complete-TpmWorkflowStep -Context $postgresStatus -Outcome Succeeded -Summary 'Game database setup verified')
            Write-Host ("    Fields updated         : {0}" -f $pgResults.Configured) -ForegroundColor Green
            Write-Host ("    Databases created      : {0}" -f $pgResults.DbCreated) -ForegroundColor Green
            Write-Host ("    Already configured     : {0}" -f $pgResults.AlreadyConfigured) -ForegroundColor DarkGray
            if ($pgResults.Errors -gt 0) { Write-Host ("    Errors                 : {0}  (see TeknoParrot-Manager.log)" -f $pgResults.Errors) -ForegroundColor Red }
            Write-Log ("Postgres setup: complete. Configured={0} DbCreated={1} AlreadyConfigured={2} Errors={3}" -f $pgResults.Configured, $pgResults.DbCreated, $pgResults.AlreadyConfigured, $pgResults.Errors)
        } finally {
            if ($null -ne $postgresServiceWasRunning -and -not (Restore-PostgresServiceState -WasRunning $postgresServiceWasRunning)) {
                $postgresServiceRestoreFailed = $true
            }
            if ($outPw) { $outPw.Value = $null }
            $outPw = $null
            $secure = $null
            $superPwSecure = $null
            $savedPwPlain = $null
            $typedPwPlain = $null
            $superPwPlain = $null
            [GC]::Collect()
        }
        if ($postgresServiceRestoreFailed) {
            Write-Host '  PostgreSQL setup did not finish safely because TPM could not restore the original service state.' -ForegroundColor Red
            Write-Log 'Postgres setup: original service state restoration failed; completion was not claimed.'
            if ($isPostgresRecoveryResume) { Exit-PostgresRecoveryResume -Message 'TPM could not restore the original PostgreSQL service state.' }
            [void](Resolve-TpmWorkflowFailure -Context $postgresStatus -FailureId 'postgres-service-restore' -Message 'The original PostgreSQL service state could not be restored.' -DataSafety 'TPM did not claim PostgreSQL setup complete.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
            continue
        }
        if ($isPostgresRecoveryResume) {
            if (-not (Remove-PostgresRecoveryState -Path $postgresResumeState.Path -ClaimPath $postgresResumeState.ClaimPath)) {
                Exit-PostgresRecoveryResume -Message 'PostgreSQL setup finished, but TPM could not remove its protected temporary repair state.'
            }
            if ($postgresResumeState.Operation -eq 'Recovery') {
                Write-Host '  PostgreSQL is fixed.' -ForegroundColor Green
                Write-Host '  TPM reset and verified the password successfully.' -ForegroundColor Green
            } else {
                Write-Host '  PostgreSQL setup is complete. TPM continued the repair automatically.' -ForegroundColor Green
            }
            [void](Read-HostSafe '  Press Enter to continue')
            exit 0
        }
        [void](Complete-TpmWorkflowStatus -Context $postgresStatus -Summary 'PostgreSQL setup finished and was verified')
        [void](Close-TpmWorkflowStatus -Context $postgresStatus)
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }
    if ($mode -eq "CheckForUpdates") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Check for Updates" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $updateStatus = New-TpmWorkflowStatusContext -WorkflowKey 'CheckForUpdates' -Title 'Update check' -Steps @(
            @{ Id = 'query'; Label = 'Check for a newer TPM release' }
            @{ Id = 'apply'; Label = 'Back up, download, and validate the update' }
            @{ Id = 'verify'; Label = 'Verify the installed update' }
        )
        [void](Start-TpmWorkflowStatus -Context $updateStatus)
        [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'query' -Activity 'Checking for a newer release')
        [void](Complete-TpmWorkflowStep -Context $updateStatus -Summary 'Release check finished' -NextStep 'Apply only after approval')
        $scriptSelfPath = Join-Path $PSScriptRoot "TeknoParrot-Manager.ps1"
        $updateInstalled = Invoke-CheckForUpdates -ScriptPath $scriptSelfPath
        if ($updateInstalled) {
            [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'apply' -Activity 'Applying the approved update')
            [void](Complete-TpmWorkflowStep -Context $updateStatus -Outcome Fixed -Summary 'Update installed' -NextStep 'Restart TPM')
            [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'verify' -Activity 'Update verified')
            [void](Complete-TpmWorkflowStep -Context $updateStatus -Summary 'Update verified')
            [void](Complete-TpmWorkflowStatus -Context $updateStatus -Summary 'Update installed')
            [void](Close-TpmWorkflowStatus -Context $updateStatus)
        } else {
            [void](Start-TpmWorkflowStep -Context $updateStatus -StepId 'apply' -Activity 'No update is needed')
            [void](Complete-TpmWorkflowStep -Context $updateStatus -Outcome Skipped -Summary 'No update was installed')
            [void](Complete-TpmWorkflowStatus -Context $updateStatus -Summary 'You already have the latest version')
            [void](Close-TpmWorkflowStatus -Context $updateStatus)
        }
        if ($updateInstalled) {
            Write-Host ""
            Write-Host "  Restart TeknoParrot Manager now to run the new version." -ForegroundColor Yellow
            [void](Read-Host "  Press Enter to exit")
            Write-Log "CheckForUpdates: exiting after successful update -- not continuing in this session."
            exit 0
        }
        Write-Log "CheckForUpdates: complete, no restart needed."
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "Support") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Create Support Package" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host "  TPM will collect safe logs and reports for you."
        Write-Host "  It will not include game files, credentials, or arbitrary folders." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  1) Create Support Package"
        Write-Host "  2) Open TPM Logs and Reports"
        Write-Host "  3) Return to the main menu"
        $supportChoice = (Read-HostSafe "  Choose 1-3").Trim()
        if ($supportChoice -eq '2') {
            $openResult = Open-TpmLogsAndReports -ScriptRoot $PSScriptRoot
            if ($openResult.Succeeded) {
                Write-Host ("  Opened: {0}" -f $openResult.Path) -ForegroundColor Green
            } else {
                Write-Host ("  TPM logs and reports could not be opened: {0}" -f $openResult.Error) -ForegroundColor Yellow
                Write-Host ("  Folder: {0}" -f $openResult.Path) -ForegroundColor DarkGray
            }
            [void](Read-HostSafe '  Press Enter to return to the menu')
            continue
        }
        if ($supportChoice -eq '1') {
            $supportResult = New-TpmSupportPackage -ScriptRoot $PSScriptRoot -TeknoParrotRoot $tpRoot -UserProfilesDir $userProfilesDir -ApprovedGamesRoot $gamesInstallFolder
            Write-Host ""
            if ($supportResult.Succeeded) {
                Write-Host "  Support package created." -ForegroundColor Green
                Write-Host ("  Checked {0} safely identified games." -f $supportResult.Summary.GamesChecked)
                Write-Host ("  Collected {0} diagnostic files and {1} plugin inventories." -f $supportResult.Summary.FilesCollected, $supportResult.Summary.PluginInventoriesCollected)
                Write-Host ("  {0} optional diagnostics were not present; full detail is in the package manifest." -f $supportResult.Summary.OptionalDiagnosticsNotFound) -ForegroundColor DarkGray
                Write-Host ("  Collection failures: {0}. Intentional exclusions: {1}." -f $supportResult.Summary.CollectionFailures, $supportResult.Summary.IntentionallyExcluded) -ForegroundColor DarkGray
                Write-Host ("  Saved here: {0}" -f $supportResult.PackagePath) -ForegroundColor Green
                Write-Host "  This is the file to send when asking for help." -ForegroundColor Cyan
                $openPackage = (Read-HostSafe "  Open the package folder now? (Y/N)").Trim().ToUpper()
                if ($openPackage -eq 'Y') {
                    try { Start-Process -FilePath 'explorer.exe' -ArgumentList @([System.IO.Path]::GetDirectoryName($supportResult.PackagePath)) -ErrorAction Stop | Out-Null } catch { Write-Host "  Windows could not open the package folder." -ForegroundColor Yellow }
                }
            } else {
                if ($supportResult.PackagePath) {
                    Write-Host "  Support ZIP was created, but temporary cleanup needs attention." -ForegroundColor Yellow
                    Write-Host ("  Saved here: {0}" -f $supportResult.PackagePath) -ForegroundColor Yellow
                    Write-Host "  Do not send it until the cleanup warning is resolved." -ForegroundColor Yellow
                } else {
                    Write-Host "  Support package was not created." -ForegroundColor Red
                    Write-Host "  No success was reported. Check the TPM log for details." -ForegroundColor Yellow
                }
                foreach ($errorText in @($supportResult.Errors)) { Write-Host ("  Reason: {0}" -f $errorText) -ForegroundColor DarkGray }
            }
            [void](Read-HostSafe '  Press Enter to return to the menu')
        }
        continue
    }

    if ($mode -eq "PropagateControls") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Propagate Controls" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " This copies your current TeknoParrot control bindings from" -ForegroundColor DarkCyan
        Write-Host " configured reference games to other compatible games. No games" -ForegroundColor DarkCyan
        Write-Host " will be registered or extracted." -ForegroundColor DarkCyan

        # Backup UserProfiles before any write, same safety net as every other
        # standalone flow that writes into UserProfile XMLs (GPU fix, cursor
        # hide, FFB Blaster). Invoke-ControlPropagation itself is unchanged --
        # this option is a thin wrapper around the existing pipeline
        # (Build-ArchetypePool / Invoke-ControlPropagation /
        # Write-ControlPropagationResults), not a new implementation of it.
        try {
            $propagationBackup = New-PropagationBackup -UserProfilesDir $userProfilesDir
        } catch {
            Write-Host "  ERROR: Could not create backup folder: $_" -ForegroundColor Red
            Write-Host "  The script will not continue without a successful backup." -ForegroundColor Red
            Write-Log "PropagateControls: backup FAILED -- $_"
            [void](Read-Host "  Press Enter to return to menu")
            continue
        }
        $backupPath = $propagationBackup.Path
        if ($propagationBackup.ErrorCount -gt 0) {
            # Fatal, no override, no exception for -Unattended: this mode's
            # own doc text and the README both promise UserProfiles are
            # backed up before it writes anything. An incomplete backup
            # means that promise is already broken, so propagation must not
            # proceed regardless of interactive confirmation or unattended
            # mode -- there is no safe "continue anyway" here.
            Write-Host ("  ERROR: {0} file(s) could not be backed up." -f $propagationBackup.ErrorCount) -ForegroundColor Red
            Write-Host "  The script will not continue without a complete backup." -ForegroundColor Red
            Write-Log "PropagateControls: backup FAILED -- $($propagationBackup.ErrorCount) file(s) could not be copied."
            [void](Read-Host "  Press Enter to return to menu")
            continue
        }
        Write-Host ("  Backup: {0}" -f $backupPath) -ForegroundColor DarkGray
        Write-Log "PropagateControls: backup at $backupPath"

        Write-Host ""
        $pool = Build-ArchetypePool -userProfilesDir $userProfilesDir -minBound $MinBoundForArchetype
        if ($pool.Count -eq 0) {
            Write-Host " No fully-bound example games found yet, so there is nothing" -ForegroundColor Yellow
            Write-Host " to copy controls from yet. Bind at least one game of each" -ForegroundColor Yellow
            Write-Host " control type in TeknoParrot's own UI, then re-run this option." -ForegroundColor Yellow
            Write-Log "PropagateControls: no reference games found (>= $MinBoundForArchetype bound buttons)."
            [void](Read-Host "  Press Enter to return to menu")
            continue
        }

        Write-Host " Found these bound games to copy controls FROM:" -ForegroundColor Green
        foreach ($s in $pool) {
            $apiLabel = if ($s.InputApi) { $s.InputApi } else { "n/a" }
            $devLabel = if ($s.Devices.Count -gt 0) { ($s.Devices -join ", ") } else { "?" }
            Write-Host ("    {0,-26} [{1}]  {2} buttons" -f $s.Code, $s.Family, $s.BoundCount) -ForegroundColor DarkGray
            Write-Host ("        api={0}   device(s): {1}" -f $apiLabel, $devLabel) -ForegroundColor DarkGray
            if ($s.ConfigCarry.Count -gt 0) {
                $cfgLabel = ($s.ConfigCarry.GetEnumerator() | ForEach-Object { "$($_.Key)=$($_.Value)" }) -join ", "
                Write-Host ("        settings that will be copied: {0}" -f $cfgLabel) -ForegroundColor DarkGray
                foreach ($flag in (Get-ConfigCarryFlags $s.Family $s.ConfigCarry)) {
                    Write-Host ("        WARNING: $flag") -ForegroundColor Red
                }
            }
        }
        Write-Host ""
        Write-Host " This copies each game's controls to your OTHER games of the SAME" -ForegroundColor DarkCyan
        Write-Host " type. It never changes a game you have already bound, and it leaves" -ForegroundColor DarkCyan
        Write-Host " game-specific controls (gear shifts, special buttons) unbound for" -ForegroundColor DarkCyan
        Write-Host " you to set. Your UserProfiles were backed up at the start of this run." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host " IMPORTANT: the 'settings that will be copied' lines above apply to" -ForegroundColor Yellow
        Write-Host " EVERY other game of that type. Check them against your real hardware" -ForegroundColor Yellow
        Write-Host " now -- for example 'Use Keyboard/Button For Axis' should be False if" -ForegroundColor Yellow
        Write-Host " you bind with a real wheel, and 'Use Relative Input' should match how" -ForegroundColor Yellow
        Write-Host " your lightgun reports position. If anything looks wrong, answer N," -ForegroundColor Yellow
        Write-Host " fix the game above in TeknoParrotUI, then re-run." -ForegroundColor Yellow
        Write-Host ""

        if ($Unattended) {
            Write-Host "  [Unattended] Propagating controls." -ForegroundColor DarkCyan
            Write-Log "PropagateControls: unattended -- propagation = Y."
            $goCtl = "Y"
        } else {
            $goCtl = (Read-HostSafe " Propagate controls now? (Y/N)")
        }

        if ($goCtl.ToUpper() -eq "Y") {
            $reports = Invoke-ControlPropagation -userProfilesDir $userProfilesDir -pool $pool -minBound $MinBoundForArchetype -noPropagate $noPropagateList -forceArchetype $forceArchetypeMap -familyOverride $familyOverrideMap -canonicalArchetype $canonicalArchetypeMap -DryRun $false
            $propResult = Write-ControlPropagationResults -Reports $reports
            Write-Host ""
            Write-Host " IMPORTANT: launch ONE updated game in TeknoParrot and test its" -ForegroundColor Cyan
            Write-Host " controls before trusting the rest. If anything is wrong, restore" -ForegroundColor Cyan
            Write-Host (" from the backup made at the start of this run:" ) -ForegroundColor Cyan
            Write-Host ("    {0}" -f $backupPath) -ForegroundColor Cyan
            Write-Log "PropagateControls: completed. Games updated=$($propResult.BoundCount)"
        } else {
            Write-Host " Skipped control propagation." -ForegroundColor DarkGray
            Write-Log "PropagateControls: user declined."
        }

        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "CrosshairSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Crosshair Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $crosshairStatus = New-TpmWorkflowStatusContext -WorkflowKey 'CrosshairSetup' -Title 'Crosshair setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check the emulator and game folders' }
            @{ Id = 'choose'; Label = 'Choose the P1 and P2 crosshairs' }
            @{ Id = 'apply'; Label = 'Install and verify the crosshair files' }
        )
        [void](Start-TpmWorkflowStatus -Context $crosshairStatus)
        [void](Start-TpmWorkflowStep -Context $crosshairStatus -StepId 'inspect' -Activity 'Checking crosshair prerequisites')
        [void](Complete-TpmWorkflowStep -Context $crosshairStatus -Summary 'Prerequisites checked' -NextStep 'Choose the P1 and P2 crosshairs')
        [void](Start-TpmWorkflowStep -Context $crosshairStatus -StepId 'choose' -Activity 'Waiting for your crosshair choices')
        [void](Set-TpmWorkflowWaiting -Context $crosshairStatus -Message 'Choose the crosshair images to use.' -UserAction 'Enter the P1 and P2 image numbers')
        [void](Resume-TpmWorkflowStatus -Context $crosshairStatus)
        [void](Complete-TpmWorkflowStep -Context $crosshairStatus -Summary 'Crosshair choices recorded' -NextStep 'Install and verify the files')
        [void](Start-TpmWorkflowStep -Context $crosshairStatus -StepId 'apply' -Activity 'Installing crosshair files')
        $crosshairResult = Invoke-CrosshairSetup -UserProfilesDir $userProfilesDir `
                              -GamesInstallFolder $gamesInstallFolder `
                              -TpRoot $tpRoot
        if ($crosshairResult -and $crosshairResult.Succeeded) {
            [void](Complete-TpmWorkflowStep -Context $crosshairStatus -Outcome Fixed -Summary 'Crosshair setup finished')
            [void](Complete-TpmWorkflowStatus -Context $crosshairStatus -Summary 'Crosshair setup finished')
            [void](Close-TpmWorkflowStatus -Context $crosshairStatus)
            Write-Host ""
            Write-Host "Crosshair setup finished and was verified." -ForegroundColor Green
            Write-Log "Crosshair setup complete."
        } else {
            [void](Set-TpmWorkflowFailure -Context $crosshairStatus -FailureId 'crosshair-incomplete' -Message 'Crosshair setup was not completed.' -DataSafety 'TPM did not claim a complete crosshair deployment.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            Write-Host ""
            Write-Host "Crosshair setup was not completed. The message above is the authoritative result." -ForegroundColor Yellow
            [void](Read-HostSafe '  Press Enter to acknowledge the crosshair result')
            [void](Acknowledge-TpmWorkflowFailure -Context $crosshairStatus -FailureId 'crosshair-incomplete')
            [void](Stop-TpmWorkflowStatus -Context $crosshairStatus -Reason 'Crosshair setup stopped')
            [void](Close-TpmWorkflowStatus -Context $crosshairStatus)
            Write-Log "Crosshair setup did not complete; no success was claimed."
        }
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "ReShadeSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " ReShade Visual Enhancements Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $reShadeStatus = New-TpmWorkflowStatusContext -WorkflowKey 'ReShadeSetup' -Title 'ReShade setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check the ReShade source' }
            @{ Id = 'acquire'; Label = 'Download and verify the official installer' }
            @{ Id = 'apply'; Label = 'Install the selected visual enhancement' }
            @{ Id = 'verify'; Label = 'Verify the result' }
        )
        [void](Start-TpmWorkflowStatus -Context $reShadeStatus)
        [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'inspect' -Activity 'Checking ReShade files')
        $bundledDll   = Join-Path $PSScriptRoot "ReShade\ReShade64.dll"
        $bundledDll32 = Join-Path $PSScriptRoot "ReShade\ReShade32.dll"
        if (-not $rsSourceDll -or -not (Test-Path -LiteralPath $rsSourceDll)) {
            if (Test-Path -LiteralPath $bundledDll) {
                $rsSourceDll = $bundledDll
            } else {
                Write-Host ""
                [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Summary 'No local ReShade source was found' -NextStep 'Download and verify the official installer')
                [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'acquire' -Activity 'Preparing automatic download')
                Write-Host "  ReShade 64-bit DLL not found." -ForegroundColor Yellow
                Write-Host "    D) Download automatically from reshade.me"
                Write-Host "    B) Browse for a file I already have"
                Write-Host "    N) Skip"
                $rsGetChoice = (Read-HostSafe "  Choice (D/B/N)").ToUpper()
                $rsGotDll    = $false
                if ($rsGetChoice -eq 'D') {
                while (-not $rsGotDll -and $rsGetChoice -eq 'D') {
                    Write-Host "  Checking reshade.me for the latest version..." -ForegroundColor Cyan
                    $rsLatestVer = Get-ReShadeLatestVersion
                    if (-not $rsLatestVer) {
                        Write-Host "  TPM could not reach reshade.me. Choose R to retry automatically, B for the advanced existing-file fallback, or N to cancel." -ForegroundColor Red
                        Write-Log "ReShade auto-download: aborted -- could not determine latest version."
                    } else {
                        $rsSetupUrl = Get-ReShadeSetupDownloadUrl -Version $rsLatestVer
                        if (-not $rsSetupUrl) {
                            Write-Host "  Could not build a safe download URL -- aborted." -ForegroundColor Red
                        } else {
                            $rsCacheDir  = Join-Path $PSScriptRoot "ReShade"
                            [void][System.IO.Directory]::CreateDirectory($rsCacheDir)
                            $rsSetupPath = Join-Path $rsCacheDir "ReShade_Setup_$rsLatestVer.exe"
                            Write-Host "  Downloading ReShade $rsLatestVer installer..." -ForegroundColor Cyan
                            if (Invoke-TpmDownload -DownloadUrl $rsSetupUrl -DestinationPath $rsSetupPath -Label 'ReShadeSetup' -Version $rsLatestVer) {
                                Write-Host "  Verifying installer signature..." -ForegroundColor Cyan
                                $rsSig = Test-ReShadeSetupTrustedSignature -Path $rsSetupPath
                                Write-Host ("  Signer     : {0}" -f $rsSig.Signer) -ForegroundColor DarkGray
                                Write-Host ("  Thumbprint : {0}" -f $rsSig.Thumbprint) -ForegroundColor DarkGray
                                if (-not $rsSig.Trusted) {
                                    Write-Host "  SECURITY: Signature does not match the trusted ReShade certificate -- refusing to use this installer." -ForegroundColor Red
                                    Write-Host "  The advanced existing-file fallback is available only if you already have a trusted official file." -ForegroundColor Yellow
                                    Write-Log ("ReShade auto-download: SECURITY -- signature not trusted. Subject='{0}' Thumbprint={1}" -f $rsSig.Signer, $rsSig.Thumbprint)
                                    try { Remove-Item -LiteralPath $rsSetupPath -Force -ErrorAction SilentlyContinue } catch {}
                                } else {
                                    Write-Host "  Signature trusted. Extracting ReShade32.dll / ReShade64.dll..." -ForegroundColor Cyan
                                    try {
                                        Expand-ReShadeSelfExtractingArchive -SetupExePath $rsSetupPath -DestDir $rsCacheDir
                                        $rsSourceDll   = Join-Path $rsCacheDir "ReShade64.dll"
                                        $rsSourceDll32 = Join-Path $rsCacheDir "ReShade32.dll"
                                        $rsGotDll      = $true
                                        Write-Host "  Downloaded and extracted successfully." -ForegroundColor Green
                                        Write-Log "ReShade auto-download: extracted $rsLatestVer to $rsCacheDir"
                                    } catch {
                                        Write-Host ("  Extraction failed: {0}" -f $_) -ForegroundColor Red
                                        Write-Log "ReShade auto-download: extraction failed -- $_"
                                    }
                                }
                            } else {
                                Write-Host "  The automatic ReShade download did not finish. Choose R to retry, B for the advanced fallback, or N to cancel." -ForegroundColor Red
                            }
                        }
                    }
                if (-not $rsGotDll) {
                    Write-Host '  Automatic ReShade download did not finish.' -ForegroundColor Red
                    $rsRetryChoice = (Read-HostSafe '  R Retry automatic download / B Use an existing file (advanced) / N Cancel').ToUpper()
                    if ($rsRetryChoice -eq 'R') { $rsGetChoice = 'D'; continue }
                    $rsGetChoice = $rsRetryChoice
                }
                }
                }
                if (-not $rsGotDll -and $rsGetChoice -eq 'B') {
                    Write-Host ""
                    Write-Host "    Enter the full path to the DLL file now:" -ForegroundColor White
                    Write-Host ""
                    $inp = Read-PathWithBrowse "  Path to ReShade 64-bit DLL (or press Enter to cancel)" -Mode File -FileFilter "DLL files (*.dll)|*.dll|All files (*.*)|*.*"
                    if ([string]::IsNullOrWhiteSpace($inp) -or -not (Test-Path -LiteralPath $inp)) {
                        Write-Host "  File not found. ReShade setup cancelled." -ForegroundColor Red
                        Write-Log "ReShade setup: aborted -- DLL not found."
                        [void](Resolve-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-file-missing' -Message 'The selected ReShade file was not found.' -DataSafety 'No ReShade file was deployed.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                        continue
                    }
                    if ([System.IO.Path]::GetExtension($inp).ToLower() -ne '.dll') {
                        Write-Host "  That file does not appear to be a DLL. Cancelled." -ForegroundColor Red
                        Write-Log "ReShade setup: aborted -- file is not a .dll."
                        [void](Resolve-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-file-type' -Message 'The selected ReShade file is not a DLL.' -DataSafety 'No ReShade file was deployed.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                        continue
                    }
                    $rsSourceDll = $inp
                }
                if (-not $rsGotDll) {
                    [void](Set-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-acquisition-cancelled' -Message 'ReShade setup was cancelled.' -DataSafety 'No unverified ReShade file was used.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
                    Write-Host '  ReShade setup cancelled. No unverified DLL was used.' -ForegroundColor Yellow
                    Write-Log 'ReShade setup: cancelled after automatic acquisition failed.'
                    [void](Read-HostSafe '  Press Enter to acknowledge the ReShade result')
                    [void](Acknowledge-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-acquisition-cancelled')
                    [void](Stop-TpmWorkflowStatus -Context $reShadeStatus -Reason 'ReShade setup stopped')
                    [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
                    [void](Read-HostSafe '  Press Enter to return to menu')
                    continue
                }
            }
            if (Save-Config) {
                Write-Log "Config: saved ReShadeSourceDll = $rsSourceDll"
            } else {
                Write-Log "Config: could not save ReShadeSourceDll"
            }
        }
        if (-not $rsSourceDll32 -or -not (Test-Path -LiteralPath $rsSourceDll32)) {
            if (Test-Path -LiteralPath $bundledDll32) { $rsSourceDll32 = $bundledDll32 }
        }
        $reShadeResult = Invoke-ReShadeSetup -UserProfilesDir $userProfilesDir `
                            -SourceDll $rsSourceDll `
                            -SourceDll32 $rsSourceDll32 `
                            -ConfigPath $configPath `
                            -TpRoot $tpRoot `
                            -Mode $mode `
                            -ZipSource $zipSource `
                            -GamesInstallFolder $gamesInstallFolder `
                            -RetroBat $retroBat `
                            -HsDataPath $hsDataPath
        if ($reShadeResult -and $reShadeResult.Succeeded) {
            [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Outcome Fixed -Summary 'ReShade source verified' -NextStep 'Install into selected games')
            [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'apply' -Activity 'Installing ReShade into selected games')
            [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Outcome Fixed -Summary 'ReShade files installed' -NextStep 'Verify the result')
            [void](Start-TpmWorkflowStep -Context $reShadeStatus -StepId 'verify' -Activity 'Verifying ReShade setup')
            [void](Complete-TpmWorkflowStep -Context $reShadeStatus -Summary 'ReShade setup finished')
            [void](Complete-TpmWorkflowStatus -Context $reShadeStatus -Summary 'ReShade setup finished')
            [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
        } else {
            [void](Set-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-incomplete' -Message 'ReShade setup was not completed.' -DataSafety 'No unverified ReShade deployment was reported as complete.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            [void](Read-HostSafe '  Press Enter to acknowledge the ReShade result')
            [void](Acknowledge-TpmWorkflowFailure -Context $reShadeStatus -FailureId 'reshade-incomplete')
            [void](Stop-TpmWorkflowStatus -Context $reShadeStatus -Reason 'ReShade setup stopped')
            [void](Close-TpmWorkflowStatus -Context $reShadeStatus)
            continue
        }
        Write-Host ""
        Write-Host "Done." -ForegroundColor Green
        Write-Log "ReShade setup complete."
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "DgVoodoo2Setup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " dgVoodoo2 Legacy Compatibility Setup" -ForegroundColor Cyan
        $dgStatus = New-TpmWorkflowStatusContext -WorkflowKey 'DgVoodoo2Setup' -Title 'dgVoodoo2 setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check legacy game requirements' }
            @{ Id = 'acquire'; Label = 'Download and verify the official package' }
            @{ Id = 'apply'; Label = 'Install the selected compatibility files' }
            @{ Id = 'verify'; Label = 'Verify the result' }
        )
        [void](Start-TpmWorkflowStatus -Context $dgStatus)
        [void](Start-TpmWorkflowStep -Context $dgStatus -StepId 'inspect' -Activity 'Checking legacy game requirements')
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $bundledDg = Join-Path $PSScriptRoot "dgVoodoo2"
        if (-not $dgSourceDir -or -not (Test-Path -LiteralPath $dgSourceDir)) {
            if (Test-Path -LiteralPath $bundledDg) {
                $dgSourceDir = $bundledDg
            } else {
                Write-Host ""
                Write-Host "  dgVoodoo2 DLL folder not found." -ForegroundColor Yellow
                Write-Host "    D) Download automatically from the official GitHub release"
                Write-Host "    B) Browse for a folder I already have"
                Write-Host "    N) Skip"
                $dgGetChoice = (Read-HostSafe "  Choice (D/B/N)").ToUpper()
                $dgGotDir    = $false
                if ($dgGetChoice -eq 'D') {
                while (-not $dgGotDir -and $dgGetChoice -eq 'D') {
                    Write-Host "  Checking the official GitHub release for the latest dgVoodoo2..." -ForegroundColor Cyan
                    $dgRel = Get-DgVoodoo2LatestRelease
                    if (-not $dgRel) {
                        Write-Host "  TPM could not reach the official dgVoodoo2 release. Choose R to retry automatically, B for the advanced existing-folder fallback, or N to cancel." -ForegroundColor Red
                        Write-Log "dgVoodoo2 auto-download: aborted -- release query failed."
                    } else {
                        Write-Host ("  Found: {0}  ({1} MB)" -f $dgRel.FileName, ([Math]::Round($dgRel.SizeBytes / 1MB, 1))) -ForegroundColor Cyan
                        $dgCacheDir = Join-Path $PSScriptRoot "dgVoodoo2"
                        [void][System.IO.Directory]::CreateDirectory($dgCacheDir)
                        $dgZipPath  = Join-Path $env:TEMP $dgRel.FileName
                        if (Invoke-TpmDownload -DownloadUrl $dgRel.DownloadUrl -DestinationPath $dgZipPath -ExpectedBytes $dgRel.SizeBytes -Label 'dgVoodoo2' -Version $dgRel.Version -ExpectedSha256 $dgRel.ExpectedSha256) {
                            try {
                                Expand-DgVoodoo2Zip -ZipPath $dgZipPath -DestDir $dgCacheDir
                                $dgSourceDir = $dgCacheDir
                                $dgGotDir    = $true
                                Write-Host "  Downloaded and extracted successfully." -ForegroundColor Green
                                Write-Log "dgVoodoo2 auto-download: extracted $($dgRel.Version) to $dgCacheDir"
                            } catch {
                                Write-Host ("  Extraction failed: {0}" -f $_) -ForegroundColor Red
                                Write-Log "dgVoodoo2 auto-download: extraction failed -- $_"
                            } finally {
                                try { Remove-Item -LiteralPath $dgZipPath -Force -ErrorAction SilentlyContinue } catch {}
                            }
                        } else {
                            Write-Host "  The automatic dgVoodoo2 download did not finish. Choose R to retry, B for the advanced fallback, or N to cancel." -ForegroundColor Red
                        }
                    }
                    if (-not $dgGotDir) {
                        $dgRetryChoice = (Read-HostSafe '  R Retry automatic download / B Use an existing folder (advanced) / N Cancel').ToUpper()
                        if ($dgRetryChoice -eq 'R') { $dgGetChoice = 'D'; continue }
                        $dgGetChoice = $dgRetryChoice
                    }
                }
                }
                if (-not $dgGotDir -and $dgGetChoice -eq 'B') {
                    Write-Host ""
                    Write-Host "    Enter the full path to a folder that already contains those files:" -ForegroundColor White
                    Write-Host ""
                    $inp = Read-PathWithBrowse "  Path to dgVoodoo2 folder (or press Enter to cancel)"
                    if ([string]::IsNullOrWhiteSpace($inp) -or -not (Test-Path -LiteralPath $inp)) {
                        Write-Host "  Folder not found. dgVoodoo2 setup cancelled." -ForegroundColor Red
                        Write-Log "dgVoodoo2 setup: aborted -- folder not found."
                        [void](Resolve-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-folder-missing' -Message 'The selected dgVoodoo2 folder was not found.' -DataSafety 'No dgVoodoo2 files were deployed.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }) -Acknowledge)
                        continue
                    }
                    $dgSourceDir = $inp
                }
                if (-not $dgGotDir -and $dgGetChoice -ne 'B') {
                    [void](Set-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-acquisition-cancelled' -Message 'dgVoodoo2 setup was cancelled.' -DataSafety 'No unverified dgVoodoo2 files were used.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
                    Write-Host '  dgVoodoo2 setup cancelled. No unverified files were used.' -ForegroundColor Yellow
                    Write-Log 'dgVoodoo2 setup: cancelled after automatic acquisition failed.'
                    [void](Read-HostSafe '  Press Enter to acknowledge the dgVoodoo2 result')
                    [void](Acknowledge-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-acquisition-cancelled')
                    [void](Stop-TpmWorkflowStatus -Context $dgStatus -Reason 'dgVoodoo2 setup stopped')
                    [void](Close-TpmWorkflowStatus -Context $dgStatus)
                    [void](Read-HostSafe '  Press Enter to return to menu')
                    continue
                }
            }
            if (Save-Config) {
                Write-Log "Config: saved DgVoodoo2SourceDir = $dgSourceDir"
            } else {
                Write-Log "Config: could not save DgVoodoo2SourceDir"
            }
        }
        $dgResult = Invoke-DgVoodoo2Setup -UserProfilesDir $userProfilesDir `
                              -SourceDir $dgSourceDir `
                              -TpRoot $tpRoot
        if (-not ($dgResult -and $dgResult.Succeeded)) {
            [void](Set-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-deployment-failed' -Message 'dgVoodoo2 setup was not completed.' -DataSafety 'TPM did not claim a complete dgVoodoo2 deployment.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            [void](Read-HostSafe '  Press Enter to acknowledge the dgVoodoo2 result')
            [void](Acknowledge-TpmWorkflowFailure -Context $dgStatus -FailureId 'dgv-deployment-failed')
            [void](Stop-TpmWorkflowStatus -Context $dgStatus -Reason 'dgVoodoo2 setup stopped')
            [void](Close-TpmWorkflowStatus -Context $dgStatus)
            continue
        }
        [void](Complete-TpmWorkflowStep -Context $dgStatus -Outcome Fixed -Summary 'dgVoodoo2 files installed' -NextStep 'Verify the result')
        [void](Start-TpmWorkflowStep -Context $dgStatus -StepId 'verify' -Activity 'Verifying dgVoodoo2 setup')
        [void](Complete-TpmWorkflowStep -Context $dgStatus -Summary 'dgVoodoo2 setup finished')
        [void](Complete-TpmWorkflowStatus -Context $dgStatus -Summary 'dgVoodoo2 setup finished')
        [void](Close-TpmWorkflowStatus -Context $dgStatus)
        Write-Host ""
        Write-Host "Done." -ForegroundColor Green
        Write-Log "dgVoodoo2 setup complete."
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "GpuFixSetup") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " GPU Compatibility Fix Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host ""
        Write-Host "  This scans your registered games and applies the correct GPU"
        Write-Host "  compatibility fix for your graphics card to each profile that"
        Write-Host "  supports one. It is safe to re-run any time you update your GPU"
        Write-Host "  drivers or switch to a new card."
        Invoke-GpuFixSetup -UserProfilesDir $userProfilesDir `
                           -TpRoot $tpRoot
        Write-Host ""
        Write-Host "Done." -ForegroundColor Green
        Write-Log "GPU fix setup complete."
        [void](Read-Host "  Press Enter to return to menu")
        continue
    }

    if ($mode -eq "FFBSetup") {
        $ffbModeResult = Invoke-TpmFfbSetupMode -UserProfilesDir $userProfilesDir -TpRoot $tpRoot -ScriptRoot $PSScriptRoot
        if ($ffbModeResult.Completed) {
            Write-Host ""
            Write-Host "Done." -ForegroundColor Green
            Write-Log "FFB setup complete."
            [void](Read-Host "  Press Enter to return to menu")
        }
        continue
    }

    if ($mode -eq "BepInExUpdate") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " BepInEx Update Check" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host ""
        Write-Host "  BepInEx is a third-party Unity plugin/modding framework. Some"
        Write-Host "  TeknoParrot games need it for controls or fixes to work via a"
        Write-Host "  community plugin." -NoNewline
        $requiredGames = Get-BepInExRequiredGames
        if ($requiredGames.Count -gt 0) {
            Write-Host " Known examples:"
            $lineLen = 70; $line = "    "; $firstR = $true
            foreach ($g in $requiredGames) {
                $add = if ($firstR) { $g } else { ", $g" }
                if (($line + $add).Length -gt $lineLen) {
                    Write-Host $line -ForegroundColor White
                    $line = "    $g"; $firstR = $false
                } else { $line += $add; $firstR = $false }
            }
            if ($line.Trim()) { Write-Host $line -ForegroundColor White }
        } else {
            Write-Host ""
        }
        Write-Host ""
        Write-Host "  TPM can install, update, or repair-reset BepInEx for selected games." -ForegroundColor DarkCyan
        Write-Host "  It chooses the stable package matching each game's 32-bit or 64-bit executable." -ForegroundColor DarkCyan
        Write-Host "  Nothing is changed until you approve the listed games." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  Troubleshooting: https://docs.bepinex.dev/articles/user_guide/troubleshooting.html"
        $bepInExCacheDir = Join-Path $PSScriptRoot "BepInExCache"
        $bepStatus = New-TpmWorkflowStatusContext -WorkflowKey 'BepInEx' -Title 'BepInEx setup' -Steps @(
            @{ Id = 'inspect'; Label = 'Check eligible game folders' }
            @{ Id = 'acquire'; Label = 'Download and verify the matching package' }
            @{ Id = 'apply'; Label = 'Back up and apply the selected change' }
            @{ Id = 'verify'; Label = 'Verify the result' }
        )
        [void](Start-TpmWorkflowStatus -Context $bepStatus)
        [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'inspect' -Activity 'Checking game folders')
        [void](Complete-TpmWorkflowStep -Context $bepStatus -Summary 'Game folders checked' -NextStep 'Download and verify the matching package')
        $bepResult = Invoke-BepInExUpdateCheck -UserProfilesDir $userProfilesDir -CacheDir $bepInExCacheDir -ApprovedGamesRoot $gamesInstallFolder
        Write-Host ""
        if ($bepResult -and $bepResult.Succeeded) {
            [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'apply' -Activity 'Applying the selected BepInEx change')
            [void](Complete-TpmWorkflowStep -Context $bepStatus -Outcome Fixed -Summary 'BepInEx change applied' -NextStep 'Verify the result')
            [void](Start-TpmWorkflowStep -Context $bepStatus -StepId 'verify' -Activity 'Verifying the result')
            [void](Complete-TpmWorkflowStep -Context $bepStatus -Summary 'BepInEx setup finished and was verified')
            [void](Complete-TpmWorkflowStatus -Context $bepStatus -Summary 'BepInEx setup finished')
            [void](Close-TpmWorkflowStatus -Context $bepStatus)
            Write-Host "BepInEx setup finished and was verified." -ForegroundColor Green
            Write-Log "BepInEx update check complete."
        } else {
            [void](Set-TpmWorkflowFailure -Context $bepStatus -FailureId 'bepinex-failed' -Message 'BepInEx setup was not completed.' -DataSafety 'No unverified BepInEx change was reported as complete.' -RecoveryActions @(@{ Id = 'Acknowledge'; Label = 'Return to menu' }))
            Write-Host "BepInEx setup was not completed. The message above is the authoritative result." -ForegroundColor Yellow
            Write-Log "BepInEx setup did not complete; no success was claimed."
            [void](Read-HostSafe '  Press Enter to acknowledge the BepInEx result')
            [void](Acknowledge-TpmWorkflowFailure -Context $bepStatus -FailureId 'bepinex-failed')
            [void](Stop-TpmWorkflowStatus -Context $bepStatus -Reason 'BepInEx setup stopped')
            [void](Close-TpmWorkflowStatus -Context $bepStatus)
        }
        continue
    }

    # Decide Preview/Run/Back before any AutoSync/Register input, config write,
    # network probe, benchmark, or staging operation.
    if ($forceRealApply) {
        $dryRunActive   = $false
        $forceRealApply = $false
    } else {
        $dryRunActive = [bool]$DryRun
        if (-not $Unattended -and -not $dryRunActive) {
            Write-Host ""
            $previewChoice = ''
            do {
                Write-Host '  [P] Preview only -- no changes'
                Write-Host '  [R] Run now -- may make changes'
                Write-Host '  [B] Back'
                $previewChoice = (Read-HostSafe '  Choice, default P' -Default 'P').Trim().ToUpper()
                if ($previewChoice -notin @('P', 'R', 'B')) {
                    Write-Host '  Invalid choice. Choose P, R, or B.' -ForegroundColor Yellow
                }
            } while ($previewChoice -notin @('P', 'R', 'B'))
            if ($previewChoice -eq 'B') { continue }
            $dryRunActive = ($previewChoice -eq 'P')
        }
    }
    if ($dryRunActive) { Write-Log "PREVIEW MODE active for this run -- no changes will be written." }

    $zipPathsJustCaptured = $false
    if ($mode -eq "AutoSync" -and -not $zipSource) {
        Write-Host ""
        Write-Host "  Main collection ZIP folder" -ForegroundColor Cyan
        Write-Host "  Point directly at the folder containing your original .zip files." -ForegroundColor DarkCyan
        Write-Host ("  This must be DIFFERENT from the staging folder: {0}" -f $gamesInstallFolder) -ForegroundColor Yellow
        Write-Host "  Example: <ROM folder>\TeknoParrot Collection" -ForegroundColor DarkCyan
        $zipSource = Read-PathWithBrowse "  Path"
        $zipPathsJustCaptured = $true
    }
    if ($mode -eq "AutoSync" -and ($null -eq $zipSourceSupplementary -or $zipSourceSupplementary -eq '') -and -not $Unattended) {
        Write-Host ""
        Write-Host "  Supplementary game collection folder (optional)" -ForegroundColor Cyan
        Write-Host "  Only needed if you downloaded the separate Supplementary .zip pack." -ForegroundColor DarkCyan
        Write-Host "  (This is not the Supplementary DAT -- most users without the pack should press Enter to skip.)" -ForegroundColor DarkCyan
        Write-Host "  Example: <ROM folder>\TeknoParrot Supplementary" -ForegroundColor DarkCyan
        $rawSupp = Read-PathWithBrowse "  Path (or press Enter to skip)"
        if ($rawSupp -and (Test-Path -LiteralPath $rawSupp)) {
            $zipSourceSupplementary = $rawSupp
            Write-Log "Config: supplementary ZIP source set to $rawSupp"
        } elseif ($rawSupp) {
            Write-Host "  Folder not found -- supplementary source skipped." -ForegroundColor Yellow
            Write-Log "Config: supplementary ZIP source not found at $rawSupp -- skipped."
        } else {
            $zipSourceSupplementary = ''
            Write-Log "Config: supplementary ZIP source skipped by user."
        }
        $zipPathsJustCaptured = $true
    }
    if ($zipPathsJustCaptured) {
        if (Save-Config) {
            Write-Log "Config: saved ZIP source path(s)."
        } else {
            Write-Log "Config: could not re-save after ZIP source prompt."
        }
    }

    if ($mode -eq "AutoSync") {
        if (-not (Test-Path -LiteralPath $zipSource)) {
            Write-Host ""; Write-Host "ERROR: ZIP source folder not found: $zipSource" -ForegroundColor Red
            Write-Log "ERROR: ZIP source not found."; [void](Read-Host "  Press Enter to return to menu"); continue
        }
        # Reject every protected-path overlap before any network classification
        # or throughput probe can touch the proposed staging location.
        $earlyStagingCandidate = Test-TpmStagingFolderCandidate `
            -Candidate $gamesInstallFolder -TeknoParrotRoot $tpRoot `
            -ZipSource $zipSource -ZipSourceSupplementary $zipSourceSupplementary `
            -ProgramDirectory $PSScriptRoot
        if (-not $earlyStagingCandidate.Valid) {
            Write-Host ""; Write-Host "ERROR: The staging folder is not safe to use." -ForegroundColor Red
            Write-Host ("    Staging folder : {0}" -f $gamesInstallFolder) -ForegroundColor Yellow
            Write-Host ("    Reason         : {0}" -f $earlyStagingCandidate.Reason) -ForegroundColor Yellow
            Write-Host "Choose a folder outside TeknoParrot, TPM, and every ZIP source folder." -ForegroundColor Yellow
            if ($Unattended) {
                Write-Log ("ERROR: unsafe staging folder -- {0}" -f $earlyStagingCandidate.Reason)
                [void](Read-Host "  Press Enter to return to menu"); continue
            }
            $recoveryDefault = Get-TpmSafeStagingFolderDefault `
                -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
            if ($recoveryDefault) { Write-Host ("  TPM recommends: {0}" -f $recoveryDefault) -ForegroundColor Cyan }
            $gamesInstallFolder = Read-TpmStagingFolder -RecommendedPath $recoveryDefault `
                -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
            if (Save-Config) { Write-Log "Config: staging folder updated after early unsafe-path rejection" }
            continue
        }
        $gamesInstallFolder = $earlyStagingCandidate.CanonicalPath
        $autoSyncDriveInfo = Get-LocalDriveInfoSafe
        if (Test-IsNetworkPath $gamesInstallFolder -Drives $autoSyncDriveInfo) {
            Write-Host ""
            Write-Host "  WARNING: The staging folder is on a network path." -ForegroundColor Yellow
            Write-Host "  Games will be extracted to -- and played from -- the network drive." -ForegroundColor Yellow
            Write-Host "  A local drive (e.g. D:\TeknoParrotGames) is faster and recommended." -ForegroundColor Yellow
            Write-Host "  Measuring write speed to the staging drive..." -ForegroundColor Cyan
            $stagingMbps = Measure-PathWriteThroughput $gamesInstallFolder
            if ($stagingMbps) {
                if ($stagingMbps -ge 500) {
                    Write-Host ("  Write speed: {0} MB/s -- fast enough for smooth extraction and gameplay." -f $stagingMbps) -ForegroundColor Green
                } elseif ($stagingMbps -ge 150) {
                    Write-Host ("  Write speed: {0} MB/s -- extraction will work but games may stutter during play." -f $stagingMbps) -ForegroundColor Yellow
                } else {
                    Write-Host ("  Write speed: {0} MB/s -- too slow for reliable extraction or play. Local drive strongly recommended." -f $stagingMbps) -ForegroundColor Red
                }
                Write-Log "Network staging benchmark: $stagingMbps MB/s"
            } else {
                Write-Host "  Write speed could not be measured (staging folder may not exist yet or is read-only)." -ForegroundColor DarkCyan
                Write-Log "Network staging benchmark: skipped (folder not found or write failed)"
            }
            if ($Unattended) {
                Write-Host "  [Unattended] Continuing with network staging folder." -ForegroundColor Yellow
                Write-Log "Unattended: network staging folder -- continuing."
            } else {
                $contNet = (Read-HostSafe "  Continue with network staging folder? (Y/N)")
                if ($contNet.ToUpper() -ne "Y") {
                    Write-Host "Aborted." -ForegroundColor Yellow
                    Write-Log "Aborted: user declined network staging folder."
                    [void](Read-Host "  Press Enter to return to menu"); continue
                }
            }
            Write-Log "Network staging folder accepted: $gamesInstallFolder"
        }
        $pathBoundariesValid = $false
        while (-not $pathBoundariesValid) {
            if (Test-PathInside $gamesInstallFolder $tpRoot) {
                Write-Host ""; Write-Host "ERROR: The staging folder is inside the TeknoParrot folder." -ForegroundColor Red
                Write-Host ("    Staging folder     : {0}" -f $gamesInstallFolder) -ForegroundColor Yellow
                Write-Host ("    TeknoParrot folder : {0}" -f $tpRoot) -ForegroundColor Yellow
                Write-Host "Choose a staging folder outside the TeknoParrot folder to keep the emulator folder clean." -ForegroundColor Yellow
                if ($Unattended) {
                    Write-Log "ERROR: staging folder inside TeknoParrot root."; [void](Read-Host "  Press Enter to return to menu"); continue 2
                }
                Write-Host ""; Write-Host "    R) Choose a different staging folder" -ForegroundColor Cyan
                Write-Host "    Q) Return to menu" -ForegroundColor Cyan
                $fix = (Read-HostSafe "  Choice").Trim().ToUpperInvariant()
                if ($fix -eq 'R') {
                    $recoveryDefault = Get-TpmSafeStagingFolderDefault `
                        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
                    if ($recoveryDefault) { Write-Host ("  TPM recommends: {0}" -f $recoveryDefault) -ForegroundColor Cyan }
                    $gamesInstallFolder = Read-TpmStagingFolder -RecommendedPath $recoveryDefault `
                        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
                    if (Save-Config) { Write-Log "Config: staging folder updated to $gamesInstallFolder after TeknoParrot-inside correction" }
                    continue
                }
                Write-Log "ERROR: staging folder inside TeknoParrot root -- user returned to menu."
                [void](Read-Host "  Press Enter to return to menu"); continue 2
            }
            if ((Test-PathInside $gamesInstallFolder $zipSource) -or (Test-PathInside $zipSource $gamesInstallFolder)) {
                Write-Host ""; Write-Host "ERROR: The staging folder and the ZIP source overlap." -ForegroundColor Red
                Write-Host ("    Staging folder : {0}" -f $gamesInstallFolder) -ForegroundColor Yellow
                Write-Host ("    ZIP source     : {0}" -f $zipSource) -ForegroundColor Yellow
                Write-Host "Keep them on separate paths so the original ZIPs are never modified." -ForegroundColor DarkCyan
                if ($Unattended) {
                    Write-Log "ERROR: staging folder overlaps ZIP source."; [void](Read-Host "  Press Enter to return to menu"); continue 2
                }
                Write-Host ""; Write-Host "    R) Choose a different staging folder" -ForegroundColor Cyan
                Write-Host "    Z) Choose a different ZIP source folder" -ForegroundColor Cyan
                Write-Host "    Q) Return to menu" -ForegroundColor Cyan
                $fix = (Read-HostSafe "  Choice").Trim().ToUpperInvariant()
                if ($fix -eq 'R') {
                    Write-Host ("  New staging folder must differ from: {0}" -f $zipSource) -ForegroundColor DarkCyan
                    $recoveryDefault = Get-TpmSafeStagingFolderDefault `
                        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
                    if ($recoveryDefault) { Write-Host ("  TPM recommends: {0}" -f $recoveryDefault) -ForegroundColor Cyan }
                    $gamesInstallFolder = Read-TpmStagingFolder -RecommendedPath $recoveryDefault `
                        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
                    if (Save-Config) { Write-Log "Config: staging folder updated to $gamesInstallFolder after overlap correction" }
                    continue
                } elseif ($fix -eq 'Z') {
                    $zipSource = Read-PathWithBrowse "  Path"
                    if (-not (Test-Path -LiteralPath $zipSource)) {
                        Write-Host ""; Write-Host "ERROR: ZIP source folder not found: $zipSource" -ForegroundColor Red
                        Write-Log "ERROR: ZIP source not found."; [void](Read-Host "  Press Enter to return to menu"); continue 2
                    }
                    $zipPathsJustCaptured = $true
                    if (Save-Config) { Write-Log "Config: ZIP source updated after overlap correction." }
                    continue
                }
                Write-Log "ERROR: staging folder overlaps ZIP source -- user returned to menu."
                [void](Read-Host "  Press Enter to return to menu"); continue 2
            }
            # Defence in depth for any protected path not covered by the
            # user-facing branches above (TPM package folder, supplementary
            # source, or a staging parent that contains a protected path).
            $stagingCandidate = Test-TpmStagingFolderCandidate `
                -Candidate $gamesInstallFolder -TeknoParrotRoot $tpRoot `
                -ZipSource $zipSource -ZipSourceSupplementary $zipSourceSupplementary `
                -ProgramDirectory $PSScriptRoot
            if (-not $stagingCandidate.Valid) {
                Write-Host ""; Write-Host "ERROR: The staging folder is not safe to use." -ForegroundColor Red
                Write-Host ("    Staging folder : {0}" -f $gamesInstallFolder) -ForegroundColor Yellow
                Write-Host ("    Reason         : {0}" -f $stagingCandidate.Reason) -ForegroundColor Yellow
                Write-Host "Choose a folder outside TeknoParrot, TPM, and every ZIP source folder." -ForegroundColor Yellow
                if ($Unattended) {
                    Write-Log ("ERROR: unsafe staging folder -- {0}" -f $stagingCandidate.Reason)
                    [void](Read-Host "  Press Enter to return to menu"); continue 2
                }
                Write-Host ""; Write-Host "    R) Choose a different staging folder" -ForegroundColor Cyan
                Write-Host "    Q) Return to menu" -ForegroundColor Cyan
                $fix = (Read-HostSafe "  Choice").Trim().ToUpperInvariant()
                if ($fix -eq 'R') {
                    $recoveryDefault = Get-TpmSafeStagingFolderDefault `
                        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
                    if ($recoveryDefault) { Write-Host ("  TPM recommends: {0}" -f $recoveryDefault) -ForegroundColor Cyan }
                    $gamesInstallFolder = Read-TpmStagingFolder -RecommendedPath $recoveryDefault `
                        -TeknoParrotRoot $tpRoot -ZipSource $zipSource `
                        -ZipSourceSupplementary $zipSourceSupplementary -ProgramDirectory $PSScriptRoot
                    if (Save-Config) { Write-Log "Config: staging folder updated after unsafe-path correction" }
                    continue
                }
                Write-Log ("ERROR: unsafe staging folder -- user returned to menu ({0})" -f $stagingCandidate.Reason)
                [void](Read-Host "  Press Enter to return to menu"); continue 2
            }
            $gamesInstallFolder = $stagingCandidate.CanonicalPath
            $pathBoundariesValid = $true
        }
        try {
            $zipBytes = (Get-ChildItem -LiteralPath $zipSource -Filter *.zip -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
            if (-not $zipBytes) { $zipBytes = 0 }
            $root      = [System.IO.Path]::GetPathRoot([System.IO.Path]::GetFullPath($gamesInstallFolder))
            $drive     = New-Object System.IO.DriveInfo($root)
            $freeBytes = $drive.AvailableFreeSpace
            Write-Host ("  Staging drive {0} free: {1} GB; ZIPs total ~{2} GB (need ~{3} GB extracted)." -f `
                $root, [Math]::Round($freeBytes/1GB,1), [Math]::Round($zipBytes/1GB,1), [Math]::Round(($zipBytes*1.5)/1GB,1)) -ForegroundColor DarkCyan
            if ($freeBytes -lt ($zipBytes * 1.5)) {
                Write-Host "  WARNING: free space on the staging drive may be insufficient." -ForegroundColor Yellow
                if ($Unattended) {
                    Write-Host "  [Unattended] Continuing despite low free space." -ForegroundColor Yellow
                    Write-Log "Unattended: low disk space warning -- continuing."
                } else {
                    $cont = (Read-HostSafe "  Continue anyway? (Y/N)")
                    if ($cont.ToUpper() -ne "Y") { Write-Host "Aborted." -ForegroundColor Yellow; Write-Log "Aborted: low staging-drive space."; [void](Read-Host "  Press Enter to return to menu"); continue }
                }
            }
            Write-Log "Space check: free=$([Math]::Round($freeBytes/1GB,1))GB zips=$([Math]::Round($zipBytes/1GB,1))GB"
        } catch { Write-Log "Space check skipped: $_" }

        if (Test-IsNetworkPath $zipSource -Drives $autoSyncDriveInfo) {
            Write-Host ""
            Write-Host "Network ZIP source detected: $zipSource" -ForegroundColor Yellow
            Write-Host "Running throughput benchmark..." -ForegroundColor Cyan
            $mbps = Measure-PathThroughput $zipSource
            if ($mbps) {
                if     ($mbps -ge 500) { $rating = "Excellent" }
                elseif ($mbps -ge 250) { $rating = "Good"      }
                elseif ($mbps -ge 150) { $rating = "Adequate"  }
                else                   { $rating = "Poor"       }
                Write-Host "  Throughput : $mbps MB/s  [$rating]" -ForegroundColor Cyan
                Write-Host "  (AutoSync copies games to your local drive, so play" -ForegroundColor DarkCyan
                Write-Host "   performance does not depend on this speed.)" -ForegroundColor DarkCyan
                Write-Log "NAS benchmark: $mbps MB/s ($rating)"
            } else {
                Write-Host "  Benchmark skipped (no ZIPs found yet or read error)." -ForegroundColor DarkCyan
            }
        }
    } else {
        if (-not (Test-Path -LiteralPath $gamesInstallFolder)) {
            Write-Host ""; Write-Host "ERROR: Games install folder not found: $gamesInstallFolder" -ForegroundColor Red
            Write-Log "ERROR: install folder not found."; [void](Read-Host "  Press Enter to return to menu"); continue
        }
    }

    Write-Log "Mode=$mode install=$gamesInstallFolder"


    # Creating the destination is itself a write. Keep it after the preview
    # decision so Preview/Dry Run never creates a staging directory.
    if ($mode -eq "AutoSync" -and -not $dryRunActive -and
        -not (Test-Path -LiteralPath $gamesInstallFolder)) {
        try {
            [void][System.IO.Directory]::CreateDirectory($gamesInstallFolder)
            Write-Host "Created staging folder: $gamesInstallFolder" -ForegroundColor Green
        } catch {
            Write-Host ""; Write-Host "ERROR: Could not create staging folder: $_" -ForegroundColor Red
            Write-Log "ERROR: Could not create staging folder -- $_"; [void](Read-Host "  Press Enter to return to menu"); continue
        }
    }

    $backupRoot = Join-Path $userProfilesDir "FullBackup"
    $timestamp  = (Get-Date).ToString("yyyy-MM-dd_HH-mm-ss")
    $backupPath = Join-Path $backupRoot $timestamp

Write-Host ""
if ($dryRunActive) {
    Write-Host "PREVIEW MODE -- skipping backup (nothing will be changed)." -ForegroundColor Yellow
} else {
Write-Host "Backing up UserProfiles..." -ForegroundColor Cyan

# Guard: if the backup folder cannot be created the script exits here rather
# than proceeding with modifications that have no restore point.
try {
    [void][System.IO.Directory]::CreateDirectory($backupRoot)
    [void][System.IO.Directory]::CreateDirectory($backupPath)
} catch {
    Write-Host "  ERROR: Could not create backup folder: $_" -ForegroundColor Red
    Write-Host "  The script will not continue without a successful backup." -ForegroundColor Red
    Write-Log "Backup FAILED: could not create backup folder -- $_"
    [void](Read-Host "  Press Enter to return to menu")
    continue
}

# Use Where-Object instead of -Exclude so FullBackup is reliably excluded
# across all PowerShell 5.1 versions (-Exclude has known edge-case behaviour).
# Copy-Item below receives FileInfo/DirectoryInfo objects from the pipeline
# (not path strings), so pipeline binding already bypasses wildcard
# expansion -- safe even with [, ], $ in game folder names. If this source
# is ever changed to raw path strings, add -LiteralPath there.
$backupErrors = 0
Get-ChildItem -LiteralPath $userProfilesDir | Where-Object { $_.Name -ne "FullBackup" } |
    Copy-Item -Destination $backupPath -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable copyErrs
$backupErrors = $copyErrs.Count
if ($backupErrors -gt 0) {
    Write-Host "  WARNING: $backupErrors file(s) could not be backed up." -ForegroundColor Yellow
    Write-Host "  Continuing without a complete backup means you may not be able to fully" -ForegroundColor Yellow
    Write-Host "  restore this run's changes if something goes wrong." -ForegroundColor Yellow
    Write-Log "Backup WARNING: $backupErrors file(s) failed to copy."
    if ($Unattended) {
        Write-Host "  [Unattended] Continuing despite incomplete backup." -ForegroundColor Yellow
        Write-Log "Unattended: incomplete backup -- continuing."
    } else {
        $contBackup = (Read-HostSafe "  Continue anyway? (Y/N)").ToUpper()
        if ($contBackup -ne "Y") {
            Write-Host "Aborted." -ForegroundColor Yellow
            Write-Log "Aborted: user declined to continue with incomplete backup."
            [void](Read-Host "  Press Enter to return to menu")
            continue
        }
    }
}
Write-Host "Backup saved to: $backupPath" -ForegroundColor Green
Write-Log "Backup created at $backupPath"
}

# =============================================================================
# SECTION 6 -- AutoSync: game selection and extraction
# =============================================================================

if ($mode -eq "AutoSync") {
    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " AutoSync: Extracting Games" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " New and changed games are extracted; unchanged games skipped." -ForegroundColor DarkCyan
    Write-Host " Local games are never deleted automatically." -ForegroundColor DarkCyan
    if ($retroBat) { Write-Host " RetroBat mode: folders extracted as GameName.teknoparrot" -ForegroundColor Cyan }
    Write-Host ""

    # Pre-validate the supplementary source now so we can decide whether to use the
    # combined picker. If invalid, errors are shown here before the picker runs.
    $onlySyncListSupp = $null
    $suppValid        = $false
    if ($zipSourceSupplementary) {
        if (-not (Test-Path -LiteralPath $zipSourceSupplementary)) {
            Write-Host "  WARNING: Supplementary ZIP folder not found: $zipSourceSupplementary -- skipped." -ForegroundColor Yellow
            Write-Log "AutoSync: supplementary ZIP source not found -- skipped."
        } elseif ((Test-PathInside $gamesInstallFolder $zipSourceSupplementary) -or
                  (Test-PathInside $zipSourceSupplementary $gamesInstallFolder)) {
            Write-Host "  ERROR: Supplementary ZIP folder overlaps the staging folder -- skipped." -ForegroundColor Red
            Write-Log "AutoSync: supplementary ZIP source overlaps staging folder -- skipped."
        } elseif (Test-PathInside $zipSourceSupplementary $tpRoot) {
            Write-Host "  ERROR: Supplementary ZIP folder is inside the TeknoParrot folder -- skipped." -ForegroundColor Red
            Write-Log "AutoSync: supplementary ZIP source is inside TeknoParrot root -- skipped."
        } else {
            $suppValid = $true
        }
    }

    # Picker return conventions (also used by overrides and unattended paths):
    #   $null   = skip this source entirely (user pressed D with nothing selected)
    #   @()     = no filter; extract all unextracted games (A was pressed, or unattended)
    #   @(...)  = whitelist; extract only the named games
    #
    # If onlySync is already populated from the overrides file, use it directly.
    # Otherwise run the interactive picker. When the supplementary source is valid,
    # both libraries are presented in a single combined list (Select-GamesInteractiveCombined).
    $combinedPickerRan = $false
    if ($onlySyncList.Count -eq 0) {
        if ($Unattended) {
            Write-Host "  [Unattended] Game selection: all unextracted games." -ForegroundColor DarkCyan
            Write-Log "Unattended: game selection = all."
        } elseif ($suppValid) {
            # Combined picker: both collection and supplementary shown in one sorted list.
            $combined          = Select-GamesInteractiveCombined -zipSourceMain $zipSource `
                                     -zipSourceSupp $zipSourceSupplementary -installFolder $gamesInstallFolder `
                                     -datIndex $datIndex -userProfilesDir $userProfilesDir
            $onlySyncList      = $combined.Main
            $onlySyncListSupp  = $combined.Supp
            $combinedPickerRan = $true
        } else {
            $onlySyncList = Select-GamesInteractive -zipSource $zipSource -installFolder $gamesInstallFolder -datIndex $datIndex -userProfilesDir $userProfilesDir
            # $null means user pressed D with nothing selected -- leave as $null (skip).
            # @() means A was pressed (no filter). Other values are explicit selections.
        }
    }
    # When the combined picker did not run (unattended, or overrides pre-set the main list),
    # default supplementary to all unextracted games. When the picker ran, $onlySyncListSupp
    # is already set by the picker ($null = skip, @() = all, @(...) = specific).
    if ($suppValid -and -not $combinedPickerRan -and $null -eq $onlySyncListSupp) {
        $onlySyncListSupp = @()
    }

    $syncStatePath = Join-Path $gamesInstallFolder "TeknoParrot-Manager.syncstate.json"

    $sync = $null
    if ($null -ne $onlySyncList) {
        $sync = Invoke-AutoSync -zipSource $zipSource -installFolder $gamesInstallFolder `
                    -syncStatePath $syncStatePath -noSync $noSyncList -onlySync $onlySyncList -retroBat $retroBat -DryRun $dryRunActive `
                    -datIndex $datIndex -userProfilesDir $userProfilesDir
    } else {
        Write-Host "  No games selected -- skipping main extraction." -ForegroundColor Yellow
        Write-Log "AutoSync: main extraction skipped -- no games selected."
    }

    # Supplementary extraction pass -- selection was already resolved above.
    $syncSupp = $null
    if ($suppValid) {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " AutoSync: Supplementary Games" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " Supplementary source: $zipSourceSupplementary" -ForegroundColor DarkCyan
        Write-Host ""
        if ($null -ne $onlySyncListSupp) {
            if ($Unattended) {
                Write-Host "  [Unattended] Game selection: all unextracted supplementary games." -ForegroundColor DarkCyan
                Write-Log "Unattended: supplementary game selection = all."
            }
            $syncSupp = Invoke-AutoSync -zipSource $zipSourceSupplementary -installFolder $gamesInstallFolder `
                            -syncStatePath $syncStatePath -noSync $noSyncList -onlySync $onlySyncListSupp -retroBat $retroBat -DryRun $dryRunActive `
                            -datIndex $datIndex -userProfilesDir $userProfilesDir
        } else {
            Write-Host "  No supplementary games selected -- skipping." -ForegroundColor Yellow
            Write-Log "AutoSync: supplementary extraction skipped -- no games selected."
        }
    }

    Write-Host ""
    Write-Host "Extraction summary:" -ForegroundColor Green
    if ($sync -and $syncSupp) { Write-Host "  Collection:" -ForegroundColor Cyan }
    if ($sync) {
        Write-Host "  Extracted  : $($sync.Synced)"   -ForegroundColor Green
        Write-Host "  Up to date : $($sync.UpToDate)"  -ForegroundColor DarkGray
        if ($sync.WouldSync -gt 0) { Write-Host "  Would extract : $($sync.WouldSync)  (preview -- nothing written yet)" -ForegroundColor Yellow }
        if ($sync.Skipped -gt 0) { Write-Host "  Skipped    : $($sync.Skipped)  (per-game override)" -ForegroundColor DarkGray }
        if ($sync.Failed  -gt 0) { Write-Host "  Failed     : $($sync.Failed)  (see TeknoParrot-Manager.log)" -ForegroundColor Red }
    } else {
        Write-Host "  Collection : skipped (no games selected)" -ForegroundColor DarkGray
    }
    if ($syncSupp) {
        Write-Host "  Supplementary:" -ForegroundColor Cyan
        Write-Host "  Extracted  : $($syncSupp.Synced)"   -ForegroundColor Green
        Write-Host "  Up to date : $($syncSupp.UpToDate)"  -ForegroundColor DarkGray
        if ($syncSupp.WouldSync -gt 0) { Write-Host "  Would extract : $($syncSupp.WouldSync)  (preview -- nothing written yet)" -ForegroundColor Yellow }
        if ($syncSupp.Skipped -gt 0) { Write-Host "  Skipped    : $($syncSupp.Skipped)  (per-game override)" -ForegroundColor DarkGray }
        if ($syncSupp.Failed  -gt 0) { Write-Host "  Failed     : $($syncSupp.Failed)  (see TeknoParrot-Manager.log)" -ForegroundColor Red }
    } elseif ($suppValid) {
        Write-Host "  Supplementary: skipped (no games selected)" -ForegroundColor DarkGray
    }
}

# =============================================================================
# SECTION 7 -- Build profile index from GameProfiles
# =============================================================================

$registrationFolders = @()
if ($sync -and $sync.SyncedNames) { $registrationFolders += @($sync.SyncedNames) }
if ($syncSupp -and $syncSupp.SyncedNames) { $registrationFolders += @($syncSupp.SyncedNames) }
Write-Host ""
if ($registrationFolders.Count -gt 0) {
    Write-Host "Checking your TeknoParrot folder so the new game is registered correctly." -ForegroundColor Cyan
    Write-Host "This checks the selected new game folder; only changed or new games will be written." -ForegroundColor DarkCyan
    Write-Log "Registration check: checking selected new game folders; only changed or new games will be written."
} else {
    Write-Host "Checking existing TeknoParrot games for registration changes." -ForegroundColor Cyan
    Write-Host "Only changed or new games will be written." -ForegroundColor DarkCyan
}
Write-Host ""
Write-Host "Indexing TeknoParrot game profiles..." -ForegroundColor Cyan
$profileIndex = Build-ProfileIndex $gameProfilesDir
Write-Host "  Indexed $($profileIndex.Keys.Count) executable names across the profile set." -ForegroundColor DarkCyan
Write-Log "Profile index built: $($profileIndex.Keys.Count) executable keys."

if ($profileIndex.Keys.Count -eq 0) {
    Write-Host ""
    Write-Host "ERROR: No usable profiles found in GameProfiles." -ForegroundColor Red
    Write-Host "Run TeknoParrotUi.exe once to let it download/update profiles, then retry." -ForegroundColor Yellow
    Write-Log "ERROR: empty profile index."
    [void](Read-Host "  Press Enter to return to menu")
    continue
}

# =============================================================================
# SECTION 8 -- Register games
# =============================================================================

Write-Host ""
Write-Host "--------------------------------------------" -ForegroundColor Cyan
Write-Host " Registering Games" -ForegroundColor Cyan
Write-Host "--------------------------------------------" -ForegroundColor Cyan
Write-Host " Scanning: $gamesInstallFolder" -ForegroundColor DarkCyan
Write-Host ""

$result = Register-Games -userProfilesDir $userProfilesDir -installFolder $gamesInstallFolder -profileIndex $profileIndex -gameProfilesDir $gameProfilesDir -datIndex $datIndex -profileSet $profileSet -DryRun $dryRunActive -tpRootDir $tpRoot -subFolderMap $subFolderMap -GameFolders $registrationFolders

foreach ($r in $result.Registered) {
    if ($r.DatMatch) {
        Write-Host ("  Registered (dat)       : {0}" -f $r.Code) -ForegroundColor Green
    } elseif ($r.FuzzyScore) {
        Write-Host ("  Registered (fuzzy {0}) : {1}" -f $r.FuzzyScore, $r.Code) -ForegroundColor Cyan
        Write-Host ("               folder  : {0}" -f $r.FuzzyFolder) -ForegroundColor DarkGray
    } elseif ($r.SubFolderMatch) {
        Write-Host ("  Registered (tp-root)   : {0}" -f $r.Code) -ForegroundColor Green
    } else {
        Write-Host ("  Registered             : {0}" -f $r.Code) -ForegroundColor Green
    }
    Write-Host "               $($r.GamePath)" -ForegroundColor DarkGray
}
foreach ($a in $result.Already) {
    Write-Host "  Already set : $a  (UserProfile exists, left unchanged)" -ForegroundColor DarkGray
}

# Collect unique game folders that need manual registration, keeping the most
# useful executable per folder (fewest profile matches = most specific hint).
# Multiple ambiguous files in the same folder collapse to one entry.
$manualRegData = @{}   # folderName -> @{ ExeName; ProfileCount; Profiles }
if ($result.Ambiguous.Count -gt 0) {
    $installBase = $gamesInstallFolder.TrimEnd('\')
    foreach ($amb in $result.Ambiguous) {
        $rel        = if ($amb.Exe.Length -gt $installBase.Length) { $amb.Exe.Substring($installBase.Length).TrimStart('\') } else { $amb.Exe }
        $folderName = $rel.Split('\')[0]
        $exeName    = [System.IO.Path]::GetFileName($amb.Exe)
        $count      = @($amb.Codes.Split(',')).Count
        if (-not $manualRegData.ContainsKey($folderName) -or $count -lt $manualRegData[$folderName].ProfileCount) {
            $manualRegData[$folderName] = @{
                Exe          = $amb.Exe
                ExeName      = $exeName
                ProfileCount = $count
                Profiles     = $amb.Codes
                BestGuess    = $amb.BestGuess
                BestScore    = $amb.BestScore
                Reason       = $amb.Reason
                ClaimedBy    = $amb.ClaimedBy
            }
        }
    }
}

# Duplicate profile codes (Reason="duplicate": exactly one profile code,
# contested by exactly one other folder) are resolvable in-script -- unlike
# "shared" conflicts (one exe name maps to several different games' profile
# codes), there's no ambiguity about WHICH profile is in play, only which
# folder it should point at. Offer to fix these now instead of sending the
# user to TeknoParrotUI for something this script can do directly.
$duplicateConflicts = @($manualRegData.GetEnumerator() | Where-Object { $_.Value.Reason -eq "duplicate" })
if ($duplicateConflicts.Count -gt 0 -and -not $Unattended) {
    Write-Host ""
    Write-Host ("  {0} duplicate profile conflict(s) found (one profile code claimed by two folders)." -f $duplicateConflicts.Count) -ForegroundColor Yellow
    $resolveChoice = (Read-HostSafe "  Resolve them now by picking which folder keeps the profile? (Y/N)").ToUpper()
    if ($resolveChoice -eq "Y") {
        foreach ($entry in $duplicateConflicts) {
            $folderName = $entry.Key
            $info       = $entry.Value
            $code       = $info.Profiles   # single code for a "duplicate" entry
            $userProfilePath = Join-Path $userProfilesDir ($code + ".xml")
            $currentExe = $null
            try {
                $curDoc = Read-Xml $userProfilePath
                $curGp  = $curDoc.GameProfile.SelectSingleNode("GamePath")
                if ($curGp) { $currentExe = $curGp.InnerText.Trim() }
            } catch {
                Write-Log "Duplicate resolution: could not read current GamePath for $code -- $_"
            }
            Write-Host ""
            Write-Host ("  Profile          : {0}" -f $code) -ForegroundColor Yellow
            Write-Host ("  Currently set to : {0}" -f $currentExe) -ForegroundColor DarkGray
            Write-Host ("  Conflicting copy : {0}" -f $info.Exe) -ForegroundColor DarkGray
            $pick = (Read-HostSafe "  [K]eep current / [S]witch to conflicting copy / [Q]uit resolving").ToUpper()
            if ($pick -eq "Q") { break }
            if ($pick -eq "S") {
                try {
                    $swDoc = Read-Xml $userProfilePath
                    $swGp  = $swDoc.GameProfile.SelectSingleNode("GamePath")
                    if ($null -eq $swGp) {
                        $swGp = $swDoc.CreateElement("GamePath")
                        [void]$swDoc.GameProfile.PrependChild($swGp)
                    }
                    $swGp.InnerText = $info.Exe
                    Save-XmlMaybe $swDoc $userProfilePath $dryRunActive
                    $switchMsg = if ($dryRunActive) { "[Preview] Would switch." } else { "Switched." }
                    Write-Host "  $switchMsg" -ForegroundColor (if ($dryRunActive) { "DarkCyan" } else { "Green" })
                    Write-Log "Duplicate resolution: $code switched to $($info.Exe) (was $currentExe)"
                    $manualRegData.Remove($folderName)
                } catch {
                    Write-Host "  FAILED to switch: $_" -ForegroundColor Red
                    Write-Log "Duplicate resolution FAILED for $code -- $_"
                }
            } else {
                Write-Host "  Kept current. Still listed in ACTION REQUIRED." -ForegroundColor DarkGray
            }
        }
    }
}

if ($manualRegData.Count -gt 0 -and -not $Unattended -and -not $dryRunActive) {
    Invoke-ManualRegistrationChoices -ManualRegData $manualRegData -UserProfilesDir $userProfilesDir `
        -GameProfilesDir $gameProfilesDir -InstallFolder $gamesInstallFolder -Result $result -DryRun $dryRunActive
}
if ($manualRegData.Count -gt 0) {
    Write-Host ""
    Write-Host ("  {0} game(s) still need registration -- see ACTION REQUIRED at the end of this run." -f $manualRegData.Count) -ForegroundColor Yellow
}
if ($result.Unmatched.Count -gt 0) {
    Write-Host ("  {0} game folder(s) not recognised by TeknoParrot -- see ACTION REQUIRED at the end of this run." -f $result.Unmatched.Count) -ForegroundColor Yellow
}

if ($registrationFolders.Count -gt 0 -and -not $dryRunActive) {
    $newGameLabel = [System.IO.Path]::GetFileName($registrationFolders[0])
    Write-Host ""
    Write-Host ("{0} was added. TeknoParrot Manager can now check your library for related setup tasks." -f $newGameLabel) -ForegroundColor Green
    Write-Host "  [N] New game only (default)" -ForegroundColor Cyan
    Write-Host "  [A] Check all games" -ForegroundColor Yellow
    Write-Host "  [B] Back" -ForegroundColor Cyan
    $maintenanceChoice = (Read-HostSafe "  Choice (N/A/B)" -Default "N").Trim().ToUpper()
    if ($maintenanceChoice -notin @('N','A','B','')) { $maintenanceChoice = 'N' }
    if ($maintenanceChoice -in @('N','')) {
        Write-Log "AutoSync: one-game maintenance scope = New game only."
        Write-Host "  New game only selected. Whole-library maintenance was not run." -ForegroundColor Green
        Write-Host "  Registration complete: $($result.Registered.Count) new game(s)." -ForegroundColor Green
        continue
    }
    if ($maintenanceChoice -eq 'B') {
        Write-Log "AutoSync: maintenance scope selection backed out."
        continue
    }
    Write-Log "AutoSync: maintenance scope = all games."
}

# =============================================================================
# SECTION 8b -- Download game thumbnails (optional)
# =============================================================================

Write-Host ""
if ($dryRunActive) {
    Write-Log "PreviewMode: thumbnail download skipped."
    $doThumb = "N"
} elseif ($Unattended) {
    Write-Host "  [Unattended] Downloading missing thumbnails." -ForegroundColor DarkCyan
    Write-Log "Unattended: thumbnail download = Y."
    $doThumb = "Y"
} else {
    Write-Host "  This downloads small box-art icons only, never the games themselves --" -ForegroundColor DarkCyan
    Write-Host "  it just gives each registered game a picture in TeknoParrot's game list." -ForegroundColor DarkCyan
    Write-Host "  Tip: want to use your own game icons instead? Create a  CustomThumbnails\" -ForegroundColor DarkCyan
    Write-Host "  folder next to this script and drop PNG images in it. Name each PNG the" -ForegroundColor DarkCyan
    Write-Host "  same as that game's file in the UserProfiles\ folder (called the profile" -ForegroundColor DarkCyan
    Write-Host "  code), but ending in .png instead of .xml. TeknoParrot-Manager-controls.txt" -ForegroundColor DarkCyan
    Write-Host "  lists every game's file name if you're not sure." -ForegroundColor DarkCyan
    $doThumb = (Read-HostSafe "Download thumbnails for registered games missing an icon? (Y/N)").ToUpper()
}
if ($doThumb -eq "Y") {
    Write-Host ""
    Write-Host "Downloading thumbnails from TeknoParrotUIThumbnails..." -ForegroundColor Cyan
    Write-Host " Source: https://github.com/teknogods/TeknoParrotUIThumbnails" -ForegroundColor DarkCyan
    Write-Host ""
    Invoke-ThumbnailDownload -userProfilesDir $userProfilesDir -tpRoot $tpRoot
}

# =============================================================================
# SECTION 9  -- Game repair: fix broken GamePaths
# =============================================================================

Write-Host ""
if ($Unattended) {
    Write-Host "  [Unattended] Running repair." -ForegroundColor DarkCyan
    Write-Log "Unattended: repair = Y."
    $doRepair = "Y"
} else {
    $doRepair = (Read-HostSafe "Check for and repair broken game paths now? (Y/N)")
}
$nf   = @(); $amb2 = @()   # initialise so the final summary can reference them safely
if ($doRepair.Trim().ToUpper() -eq "Y") {
    Write-Host ""
    Write-Host "Repairing game paths..." -ForegroundColor Cyan
    $repair = Repair-GamePaths -userProfilesDir $userProfilesDir -installFolder $gamesInstallFolder -profileIndex $profileIndex -DryRun $dryRunActive
    $fixed = @($repair | Where-Object { $_.Status -eq "fixed" })
    $nf    = @($repair | Where-Object { $_.Status -eq "not-found" })
    $amb2  = @($repair | Where-Object { $_.Status -eq "ambiguous" })
    $noex  = @($repair | Where-Object { $_.Status -eq "no-exe-name" })
    $sf    = @($repair | Where-Object { $_.Status -eq "save-failed" })
    if ($fixed.Count -eq 0 -and $nf.Count -eq 0 -and $amb2.Count -eq 0 -and $sf.Count -eq 0) {
        Write-Host "  All game paths are valid. Nothing to repair." -ForegroundColor Green
    } else {
        foreach ($r in $fixed) {
            Write-Host "  Fixed : $($r.Code)" -ForegroundColor Green
            Write-Host "          $($r.NewPath)" -ForegroundColor DarkGray
        }
        foreach ($r in $sf) {
            Write-Host "  Save failed : $($r.Code)  (see TeknoParrot-Manager.log)" -ForegroundColor Red
        }
        if ($nf.Count -gt 0) {
            Write-Host ("  {0} game(s) not yet extracted -- extract first, then re-run Repair." -f $nf.Count) -ForegroundColor DarkCyan
        }
        if ($amb2.Count -gt 0) {
            Write-Host ("  {0} profile(s) could not be auto-fixed -- see ACTION REQUIRED at the end of this run." -f $amb2.Count) -ForegroundColor Yellow
        }
    }
    Write-Log "Repair: fixed=$($fixed.Count) notfound=$($nf.Count) manualreg=$($amb2.Count) noexe=$($noex.Count) savefail=$($sf.Count)"
}

# =============================================================================
# SECTION 10 -- Control propagation
# =============================================================================

$MinBoundForArchetype = 5
$noArchetypeItems     = @()   # populated after propagation; used in ACTION REQUIRED
$reports              = $null  # populated if propagation runs; used by Write-ControlsStatus

Write-Host ""
Write-Host "--------------------------------------------" -ForegroundColor Cyan
Write-Host " Control Propagation" -ForegroundColor Cyan
Write-Host "--------------------------------------------" -ForegroundColor Cyan

$pool = Build-ArchetypePool -userProfilesDir $userProfilesDir -minBound $MinBoundForArchetype

if ($pool.Count -eq 0) {
    # First run: nothing to copy FROM yet. Help the user plan what to bind.
    Write-Host " No fully-bound example games found yet, so there is nothing" -ForegroundColor Yellow
    Write-Host " to copy controls from yet. Let's plan which games to bind first." -ForegroundColor Yellow
    if (-not $Unattended) { Invoke-DeviceSurvey }
    Write-Log "Propagation: no reference games found (>= $MinBoundForArchetype bound buttons)$(if (-not $Unattended) { '; ran device survey' })."
} else {
    Write-Host " Found these bound games to copy controls FROM:" -ForegroundColor Green
    foreach ($s in $pool) {
        $apiLabel = if ($s.InputApi) { $s.InputApi } else { "n/a" }
        $devLabel = if ($s.Devices.Count -gt 0) { ($s.Devices -join ", ") } else { "?" }
        Write-Host ("    {0,-26} [{1}]  {2} buttons" -f $s.Code, $s.Family, $s.BoundCount) -ForegroundColor DarkGray
        Write-Host ("        api={0}   device(s): {1}" -f $apiLabel, $devLabel) -ForegroundColor DarkGray
        if ($s.ConfigCarry.Count -gt 0) {
            $cfgLabel = ($s.ConfigCarry.GetEnumerator() | ForEach-Object { "$($_.Key)=$($_.Value)" }) -join ", "
            Write-Host ("        settings that will be copied: {0}" -f $cfgLabel) -ForegroundColor DarkGray
            foreach ($flag in (Get-ConfigCarryFlags $s.Family $s.ConfigCarry)) {
                Write-Host ("        WARNING: $flag") -ForegroundColor Red
            }
        }
    }
    Write-Host ""
    Write-Host " This copies each game's controls to your OTHER games of the SAME" -ForegroundColor DarkCyan
    Write-Host " type. It never changes a game you have already bound, and it leaves" -ForegroundColor DarkCyan
    Write-Host " game-specific controls (gear shifts, special buttons) unbound for" -ForegroundColor DarkCyan
    Write-Host " you to set. Your UserProfiles were backed up at the start of this run." -ForegroundColor DarkCyan
    Write-Host ""
    Write-Host " IMPORTANT: the 'settings that will be copied' lines above apply to" -ForegroundColor Yellow
    Write-Host " EVERY other game of that type. Check them against your real hardware" -ForegroundColor Yellow
    Write-Host " now -- for example 'Use Keyboard/Button For Axis' should be False if" -ForegroundColor Yellow
    Write-Host " you bind with a real wheel, and 'Use Relative Input' should match how" -ForegroundColor Yellow
    Write-Host " your lightgun reports position. If anything looks wrong, answer N," -ForegroundColor Yellow
    Write-Host " fix the game above in TeknoParrotUI, then re-run." -ForegroundColor Yellow
    Write-Host ""
    if (-not $Unattended -and (Read-HostSafe " Want a recommended binding plan for more control types first? (Y/N)").ToUpper() -eq "Y") {
        Invoke-DeviceSurvey
        Write-Host ""
    }
    if ($Unattended) {
        Write-Host "  [Unattended] Propagating controls." -ForegroundColor DarkCyan
        Write-Log "Unattended: propagation = Y."
        $goCtl = "Y"
    } else {
        $goCtl = (Read-HostSafe " Propagate controls now? (Y/N)")
    }
    if ($goCtl.ToUpper() -eq "Y") {
        $reports = Invoke-ControlPropagation -userProfilesDir $userProfilesDir -pool $pool -minBound $MinBoundForArchetype -noPropagate $noPropagateList -forceArchetype $forceArchetypeMap -familyOverride $familyOverrideMap -canonicalArchetype $canonicalArchetypeMap -DryRun $dryRunActive
        $propResult       = Write-ControlPropagationResults -Reports $reports
        $nb               = $propResult.BoundCount
        $noArchetypeItems = $propResult.NoArchetypeItems
        Write-Host ""
        Write-Host " IMPORTANT: launch ONE updated game in TeknoParrot and test its" -ForegroundColor Cyan
        Write-Host " controls before trusting the rest. If anything is wrong, restore" -ForegroundColor Cyan
        Write-Host (" from the backup made at the start of this run:" ) -ForegroundColor Cyan
        Write-Host ("    {0}" -f $backupPath) -ForegroundColor Cyan
        Write-Log "Propagation: completed. Games updated=$nb"
    } else {
        Write-Host " Skipped control propagation." -ForegroundColor DarkGray
        Write-Log "Propagation: user declined."
    }
}

# =============================================================================
# Done
# =============================================================================

Write-Host ""
Write-Host "============================================" -ForegroundColor Cyan
if ($dryRunActive) {
    Write-Host "   PREVIEW MODE -- no changes were written." -ForegroundColor Yellow
    Write-Host "============================================" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "  You'll be asked below whether to apply these changes for real." -ForegroundColor Yellow
} else {
    Write-Host "   Done." -ForegroundColor Cyan
    Write-Host "============================================" -ForegroundColor Cyan
}
Write-Host ""
Write-Host "  Newly registered : $($result.Registered.Count)" -ForegroundColor Green
Write-Host "  Already present  : $($result.Already.Count)"    -ForegroundColor DarkGray
if ($result.Ambiguous.Count -gt 0) {
    Write-Host "  Manual needed    : $($manualRegData.Count) game(s)  (see ACTION REQUIRED below)" -ForegroundColor Yellow
}
if ($result.Unmatched.Count -gt 0) {
    Write-Host ("  Not in TeknoParrot : {0} folder(s)  (see ACTION REQUIRED below)" -f $result.Unmatched.Count) -ForegroundColor Yellow
}

# Read-only bridge from the #258/#262 evidence model into the end-of-run
# handoff. This deliberately runs before the recap so the recap can count
# controls that still need attention, and the same snapshot is then rendered
# in ACTION REQUIRED below without re-reading or modifying any profile.
$controlReadinessItems = @(Get-ControlReadinessActionItems -UserProfilesDir $userProfilesDir `
    -GameProfilesDir $gameProfilesDir -TeknoParrotRoot $tpRoot)

# Targeted, context-aware recommendation for the extra version-info file
# (supplementary dat) -- deferred out of the initial wizard (see the
# Eggman-dat setup block above). Only shown when this run actually had an
# uncertain match AND a supplementary dat isn't already configured; a clean
# run with no ambiguous matches sees no extra prompt at all.
if (-not $dryRunActive -and -not $Unattended -and -not $includeSupplementary -and
    ($eggmanDatZip -or $datFilePath) -and $result.Ambiguous.Count -gt 0) {
    Write-Host ""
    Write-Host ("  {0} game(s) this run had an uncertain match. An extra version-info" -f $result.Ambiguous.Count) -ForegroundColor Yellow
    Write-Host "  file (supplementary dat) can improve that -- set it up now?" -ForegroundColor Yellow
    $askSuppNow = (Read-HostSafe "  Set up a supplementary dat now? (Y/N, default N)" -Default 'N').ToUpper()
    if ($askSuppNow -eq 'Y') {
        $rawSuppNow = Read-PathWithBrowse "  Path to supplementary dat file" -Mode File -FileFilter "dat files (*.dat)|*.dat|All files (*.*)|*.*"
        if ($rawSuppNow -and (Test-Path -LiteralPath $rawSuppNow)) {
            $supplementaryDatPath = $rawSuppNow
            $includeSupplementary = $true
            if (Save-Config) { Write-Log "Config: supplementaryDatPath set to $rawSuppNow (post-run recommendation)." }
            Write-Host "  Saved. Run 'Register only' (games already extracted -- just register)" -ForegroundColor Green
            Write-Host "  from the main menu to apply it to games already registered this run." -ForegroundColor Green
        } elseif ($rawSuppNow) {
            Write-Host "  WARNING: File not found -- skipped." -ForegroundColor Yellow
            Write-Log "Config: post-run supplementary dat not found at $rawSuppNow -- skipped."
        }
    }
}

if (-not $dryRunActive) {
    Write-Host ""
    $summaryLines = Get-WhatTpmDidSummaryLines -AutoSyncRan ($mode -eq "AutoSync") -ZipsExtracted ($(if ($sync) { $sync.Synced } else { 0 })) `
        -NewlyRegistered $result.Registered.Count -AlreadyPresent $result.Already.Count -DatAction $eggmanDatActionThisRun `
        -ThumbnailsRequested ($doThumb -eq "Y") -ManualNeeded $manualRegData.Count -NotInTeknoParrot $result.Unmatched.Count `
        -ControlsNeedAttention $controlReadinessItems.Count
    foreach ($sl in $summaryLines) { Write-Host $sl -ForegroundColor DarkCyan }
}

Write-Host ""
if (-not $dryRunActive) { Write-Host "  Backup : $backupPath" -ForegroundColor DarkCyan }
Write-Host "  Log    : $logPath"    -ForegroundColor DarkCyan

$csStatusPath = Join-Path $PSScriptRoot "TeknoParrot-Manager-controls.txt"
$csCount = Write-ControlsStatus -userProfilesDir $userProfilesDir -pool $pool -propagationReports $reports -outputPath $csStatusPath
if ($csCount -ge 0) {
    Write-Host "  Controls : $csStatusPath" -ForegroundColor DarkCyan
    Write-Log "Controls status: wrote $csCount games to $csStatusPath"
}

Write-Log "Completed. Registered=$($result.Registered.Count) Already=$($result.Already.Count) ManualReg=$($result.Ambiguous.Count) Unmatched=$($result.Unmatched.Count)"

# =============================================================================
# GAME INFO -- source tag and notes for newly registered games
# =============================================================================

if ($result.Registered.Count -gt 0 -and $notesIndex.Count -gt 0) {
    $infoItems = @($result.Registered | Where-Object { $notesIndex.ContainsKey($_.Code.ToLower()) })
    if ($infoItems.Count -gt 0) {
        Write-Host ""
        Write-Host "============================================" -ForegroundColor Cyan
        Write-Host "   Game Info (from dat)" -ForegroundColor Cyan
        Write-Host "============================================" -ForegroundColor Cyan
        foreach ($r in $infoItems) {
            $key = $r.Code.ToLower()
            Write-Host ""
            Write-Host ("  {0}" -f $r.Code) -ForegroundColor Yellow
            if ($suppCodes.Contains($r.Code)) {
                Write-Host "  Source: supplementary dat (alternate version used instead of collection)" -ForegroundColor DarkCyan
            }
            if ($notesIndex.ContainsKey($key)) {
                Write-Host "  Notes:" -ForegroundColor Cyan
                $noteLines = ($notesIndex[$key] -split "`n") | Where-Object { $_.Trim() } | Select-Object -First 4
                foreach ($nl in $noteLines) {
                    Write-Host ("    {0}" -f $nl.Trim()) -ForegroundColor DarkGray
                }
            }
        }
        Write-Host ""
    }
}

# =============================================================================
# LAUNCHBOX XML EXPORT  (optional, runs before ACTION REQUIRED)
# =============================================================================

Write-Host ""
if ($dryRunActive) {
    $doLBSetup = "N"
    Write-Log "PreviewMode: LaunchBox setup skipped."
} elseif ($Unattended) {
    $doLBSetup = "N"
    Write-Log "Unattended: LaunchBox setup skipped."
} else {
    Write-Host "  Add your registered games to LaunchBox now? (Y/N)" -ForegroundColor Cyan
    Write-Host "    This writes directly into LaunchBox's library -- no import wizard" -ForegroundColor DarkGray
    Write-Host "    needed. LaunchBox must be closed first; the script checks for you." -ForegroundColor DarkGray
    Write-Host "    (Prefer the old manual-import reference file instead? Answer N here," -ForegroundColor DarkGray
    Write-Host "     then Y to the next question.)" -ForegroundColor DarkGray
    $doLBSetup = (Read-HostSafe "  Y/N").ToUpper()
}

if ($doLBSetup -eq "Y" -and -not $lbRoot) {
    $lbDetected = Find-LaunchBoxRoot
    if ($lbDetected.Count -eq 1) {
        Write-Host ""
        Write-Host "  Auto-detected LaunchBox at: $($lbDetected[0])" -ForegroundColor Cyan
        $useLbIt = (Read-HostSafe "  Use this path? (Y/N)").ToUpper()
        if ($useLbIt -eq "Y") { $lbRoot = $lbDetected[0] }
    } elseif ($lbDetected.Count -gt 1) {
        Write-Host ""
        Write-Host "  Found LaunchBox in multiple locations:" -ForegroundColor Cyan
        for ($i = 0; $i -lt $lbDetected.Count; $i++) {
            Write-Host ("    {0}) {1}" -f ($i + 1), $lbDetected[$i])
        }
        $lbPick = (Read-HostSafe "  Enter number to use one, or N to type the path manually")
        if ($lbPick -match '^\d+$' -and $lbPick.Length -le 9) {
            $lbIdx = [int]$lbPick - 1
            if ($lbIdx -ge 0 -and $lbIdx -lt $lbDetected.Count) { $lbRoot = $lbDetected[$lbIdx] }
        }
    }
    if (-not $lbRoot) {
        $lbInput = Read-PathWithBrowse "  Enter LaunchBox root folder (containing LaunchBox.exe), or press Enter to skip"
        if ($lbInput -and (Test-Path -LiteralPath (Join-Path $lbInput "LaunchBox.exe"))) {
            $lbRoot = $lbInput
        } elseif ($lbInput) {
            Write-Host "  LaunchBox.exe not found at that path -- direct LaunchBox setup skipped." -ForegroundColor Yellow
        }
    }
    if ($lbRoot) { [void](Save-Config) }
}

if ($doLBSetup -eq "Y" -and $lbRoot -and (Test-LaunchBoxRunning)) {
    Write-Host "  LaunchBox or BigBox is currently running -- close it and re-run this step." -ForegroundColor Yellow
    Write-Host "  Falling back to the manual-import reference file instead." -ForegroundColor DarkCyan
    $doLBSetup = "N"
    $doLB = "Y"
} elseif ($doLBSetup -eq "Y" -and -not $lbRoot) {
    Write-Host "  LaunchBox path not available -- falling back to the manual-import reference file." -ForegroundColor Yellow
    $doLBSetup = "N"
    $doLB = "Y"
} elseif ($doLBSetup -ne "Y" -and -not $dryRunActive -and -not $Unattended) {
    $doLB = (Read-HostSafe "  Export a LaunchBox manual-import reference file instead? (Y/N)").ToUpper()
} else {
    $doLB = "N"
}

if ($doLBSetup -eq "Y") {
    $usesSavedChoice = $false
    if ($lbPlatformMode -and -not $Unattended) {
        $savedLabel = if ($lbPlatformMode -eq "Custom") { $lbCustomPlatformName } else { $lbPlatformMode }
        $useSaved = (Read-HostSafe "  Use saved LaunchBox platform choice ($savedLabel)? (Y/N)").ToUpper()
        $usesSavedChoice = ($useSaved -eq "Y")
    }
    if (-not $usesSavedChoice) {
        Write-Host ""
        Write-Host "  How should TeknoParrot games appear in LaunchBox?" -ForegroundColor Cyan
        Write-Host ""
        Write-Host "    1) Mixed into your existing Arcade platform"
        Write-Host "       (recommended if you browse all arcade games together)"
        Write-Host "    2) A separate `"TeknoParrot`" platform"
        Write-Host "       (recommended if you want them grouped on their own)"
        Write-Host "    3) A separate platform with a name you choose"
        Write-Host "    4) Both -- mixed into Arcade AND a separate TeknoParrot platform"
        Write-Host ""
        $platChoice = (Read-HostSafe "  Enter 1-4")
        switch ($platChoice) {
            "1" { $lbPlatformMode = "Arcade" }
            "2" { $lbPlatformMode = "TeknoParrot" }
            "3" {
                $lbPlatformMode = "Custom"
                $lbCustomPlatformName = (Read-HostSafe "  Enter a platform name")
                if ([string]::IsNullOrWhiteSpace($lbCustomPlatformName)) { $lbCustomPlatformName = "TeknoParrot" }
            }
            "4" { $lbPlatformMode = "Both" }
            default { $lbPlatformMode = "TeknoParrot" }
        }
        [void](Save-Config)
    }

    $lbTargetPlatforms = switch ($lbPlatformMode) {
        "Arcade" { @("Arcade") }
        "Custom" { @($lbCustomPlatformName) }
        "Both"   { @("Arcade", "TeknoParrot") }
        default  { @("TeknoParrot") }
    }

    $lbWriteResult = Invoke-LaunchBoxDirectWrite -userProfilesDir $userProfilesDir -tpRoot $tpRoot -lbRoot $lbRoot -platformNames $lbTargetPlatforms
    if ($null -eq $lbWriteResult) {
        Write-Host "  LaunchBox setup did not complete -- see TeknoParrot-Manager.log. No changes were made." -ForegroundColor Red
    } else {
        Write-Host ""
        Write-Host "  LaunchBox setup complete." -ForegroundColor Green
        foreach ($name in $lbWriteResult.Results.Keys) {
            Write-Host ("    {0,-12} : {1} game(s) added" -f $name, $lbWriteResult.Results[$name]) -ForegroundColor Green
        }
        Write-Host ("  Backup saved : {0}" -f $lbWriteResult.BackupPath) -ForegroundColor DarkCyan
        Write-Host "  If anything looks wrong in LaunchBox, use menu option 11 (Restore" -ForegroundColor DarkCyan
        Write-Host "  backup) -> LaunchBox library backup to undo this." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  New games have no box art/metadata yet -- in LaunchBox, right-click a" -ForegroundColor DarkCyan
        Write-Host "  game and use 'Edit... -> Search' to fetch it, the same way you would" -ForegroundColor DarkCyan
        Write-Host "  for any manually-imported game." -ForegroundColor DarkCyan
        Write-Log ("LaunchBox direct-write: " + (($lbWriteResult.Results.Keys | ForEach-Object { "$_=$($lbWriteResult.Results[$_])" }) -join ", "))
    }
}

if ($doLB -eq "Y") {
    $lbPath  = Join-Path $PSScriptRoot "TeknoParrot-LaunchBox-Import.xml"
    $lbCount = Export-LaunchBoxXml -userProfilesDir $userProfilesDir -lbRoot $lbRoot -outputPath $lbPath
    if ($lbCount -lt 0) {
        Write-Host "  LaunchBox export failed -- see TeknoParrot-Manager.log" -ForegroundColor Red
    } else {
        Write-Host ("  Exported : {0} game(s)" -f $lbCount) -ForegroundColor Green
        Write-Host "  File     : $lbPath" -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  HOW TO IMPORT INTO LAUNCHBOX" -ForegroundColor Cyan
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  Important: LaunchBox must be fully CLOSED before importing." -ForegroundColor Yellow
        Write-Host ""
        Write-Host "  Step 1.  Close LaunchBox completely." -ForegroundColor White
        Write-Host "  Step 2.  Open LaunchBox." -ForegroundColor White
        Write-Host "  Step 3.  Go to  Tools -> Import -> Emulated Games." -ForegroundColor White
        Write-Host "  Step 4.  On the first screen:" -ForegroundColor White
        Write-Host "             - Emulator: select TeknoParrot (or add it first -- see below)." -ForegroundColor DarkGray
        Write-Host "             - Import type: 'Import ROM files'." -ForegroundColor DarkGray
        Write-Host ("             - Folder: {0}" -f (Join-Path $tpRoot "UserProfiles")) -ForegroundColor DarkGray
        Write-Host "             - File types: *.xml  (import the profile files themselves," -ForegroundColor DarkGray
        Write-Host "               not the game executables -- TeknoParrot launches games" -ForegroundColor DarkGray
        Write-Host "               by profile, so the profile XML is what LaunchBox treats" -ForegroundColor DarkGray
        Write-Host "               as the 'rom' for each game)." -ForegroundColor DarkGray
        Write-Host "  Step 5.  Follow the wizard. LaunchBox will assign game names," -ForegroundColor White
        Write-Host "             metadata, and box art automatically." -ForegroundColor DarkGray
        Write-Host ""
        Write-Host "  If TeknoParrot is not yet in LaunchBox's emulator list:" -ForegroundColor Cyan
        Write-Host "    a. Go to  Tools -> Manage -> Emulators -> Add." -ForegroundColor DarkGray
        Write-Host "    b. Name: TeknoParrot" -ForegroundColor DarkGray
        Write-Host ("    c. Emulator path: {0}" -f (Join-Path $tpRoot "TeknoParrotUi.exe")) -ForegroundColor DarkGray
        Write-Host "    d. Command-line parameters: --profile=%romfile%.xml" -ForegroundColor DarkGray
        Write-Host "    e. Exit Script tab: add a script so Escape cleanly quits" -ForegroundColor DarkGray
        Write-Host "       TeknoParrot back to LaunchBox (without one, Escape may not" -ForegroundColor DarkGray
        Write-Host "       exit the game properly)." -ForegroundColor DarkGray
        Write-Host "    f. Save, then re-run the import wizard." -ForegroundColor DarkGray
        Write-Host ""
        Write-Host "  Seeing full-screen issues only when launching through LaunchBox?" -ForegroundColor Cyan
        Write-Host "    Go to  Tools -> Manage -> Emulators -> TeknoParrot -> Edit ->" -ForegroundColor DarkGray
        Write-Host "    Startup Screen tab, and disable 'Enable Game Startup Screen'." -ForegroundColor DarkGray
        Write-Host ""
        Write-Host "  The exported XML file ($lbPath)" -ForegroundColor DarkCyan
        Write-Host "  is a reference showing all registered games, their profile codes," -ForegroundColor DarkCyan
        Write-Host "  and executable paths. You do not need to import it directly." -ForegroundColor DarkCyan
        Write-Log "LaunchBox export: exported $lbCount games to $lbPath"
    }
}

# =============================================================================
# HYPERSPIN 2 EXPORT  (optional, runs after LaunchBox export)
# =============================================================================

Write-Host ""
if ($dryRunActive) {
    $doHS = "N"
    Write-Log "PreviewMode: HyperSpin 2 export skipped."
} elseif ($Unattended) {
    $doHS = "N"
    Write-Log "Unattended: HyperSpin 2 export skipped."
} else {
    $doHS = (Read-HostSafe "Export registered games to HyperSpin 2? (Y/N)").ToUpper()
}
if ($doHS -eq "Y") {
    if (-not $hsDataPath) {
        Write-Host ""
        Write-Host "  Enter HyperSpin 2 data folder path." -ForegroundColor Cyan
        $hsInput = Read-PathWithBrowse "  Path (default: C:\ProgramData\HyperSpin\data)" -InitialDirectory "C:\ProgramData\HyperSpin"
        if ([string]::IsNullOrWhiteSpace($hsInput)) { $hsInput = "C:\ProgramData\HyperSpin\data" }
        $hsDataPath = $hsInput

        if (Save-Config) {
            Write-Log "Config: saved HyperSpinDataPath = $hsDataPath"
        } else {
            Write-Log "Config: could not save HyperSpinDataPath"
        }
    }

    Write-Host ""
    $hsCount = Export-HyperSpinJson -userProfilesDir $userProfilesDir -hsDataPath $hsDataPath
    if ($hsCount -lt 0) {
        Write-Host "  HyperSpin 2 export failed -- see TeknoParrot-Manager.log" -ForegroundColor Red
    } elseif ($hsCount -eq 0) {
        Write-Host "  HyperSpin 2 already up to date -- no new games to add." -ForegroundColor Green
    } else {
        Write-Host ("  Added : {0} game(s) to HyperSpin 2" -f $hsCount) -ForegroundColor Green
        Write-Host ""
        Write-Host "  Games are added with title only. Use HyperSpin's Scrape feature" -ForegroundColor DarkCyan
        Write-Host "  to fetch box art, descriptions, and ratings for the new entries." -ForegroundColor DarkCyan
        Write-Log "HyperSpin 2: exported $hsCount game(s)"
    }
}

# =============================================================================
# CROSSHAIR SETUP  (optional, runs after HyperSpin export)
# =============================================================================

Write-Host ""
if ($Unattended) {
    $doCrosshairs = "N"
    Write-Log "Unattended: crosshair setup skipped."
} else {
    $doCrosshairs = (Read-HostSafe "Configure custom crosshairs for lightgun games? (Y/N)").ToUpper()
}
if ($doCrosshairs -eq "Y") {
    Write-Host ""
    Write-Host "Crosshair Setup" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Invoke-CrosshairSetup -UserProfilesDir $userProfilesDir `
                          -GamesInstallFolder $gamesInstallFolder `
                          -TpRoot $tpRoot
}

# =============================================================================
# RESHADE SETUP  (optional, runs after crosshair setup)
# =============================================================================

Write-Host ""
Write-Host "============================================" -ForegroundColor DarkCyan
Write-Host "   OPTIONAL: ReShade Visual Enhancements" -ForegroundColor DarkCyan
Write-Host "============================================" -ForegroundColor DarkCyan
Write-Host ""
Write-Host "  ReShade is a free tool that can make your arcade games look better"
Write-Host "  on modern screens. It works by applying real-time visual effects"
Write-Host "  on top of the game -- your game files are never touched."
Write-Host ""
Write-Host "  Popular effects:"
Write-Host "    Sharpening   -- removes the blurry look of upscaled games"
Write-Host "    CRT scanlines -- makes games look like an authentic arcade monitor"
Write-Host "    Colour boost  -- makes older games more vivid and punchy"
Write-Host "    Borders       -- adds decorative bezel artwork around the game"
Write-Host ""
Write-Host "  Your games work perfectly WITHOUT ReShade -- this is 100% optional."
Write-Host "  It can be removed at any time by deleting one file from a game folder."
Write-Host "  Press Home while in-game to open the ReShade overlay and pick effects."
Write-Host ""
Write-Host "  You can turn this on later from the main menu's ReShade setup option," -ForegroundColor DarkCyan
Write-Host "  which can also download ReShade for you automatically." -ForegroundColor DarkCyan
Write-Host ""
if ($Unattended) {
    $doReShade = "N"
    Write-Log "Unattended: ReShade setup skipped."
} else {
    $doReShade = (Read-HostSafe "Set up ReShade visual enhancements for your games? (Y/N, default N)" -Default 'N').ToUpper()
}
$rsSetupDone = $false
if ($doReShade -eq "Y") {
    # Locate 64-bit DLL: bundled copy first, then config. No blocking
    # manual-acquisition prompt here (deferred to the standalone "ReShade
    # setup" menu entry, which offers a real auto-download option) -- if
    # nothing is available yet, point the user there instead of stopping
    # the onboarding flow to walk through manual DLL acquisition.
    $bundledDll2   = Join-Path $PSScriptRoot "ReShade\ReShade64.dll"
    $bundledDll2_32 = Join-Path $PSScriptRoot "ReShade\ReShade32.dll"
    if (-not $rsSourceDll -or -not (Test-Path -LiteralPath $rsSourceDll)) {
        if (Test-Path -LiteralPath $bundledDll2) {
            $rsSourceDll = $bundledDll2
        } else {
            Write-Host ""
            Write-Host "  ReShade 64-bit DLL not found yet." -ForegroundColor Yellow
            Write-Host "  Run 'ReShade setup' from the main menu to download it automatically" -ForegroundColor Cyan
            Write-Host "  or point at a copy you already have." -ForegroundColor Cyan
            Write-Log "ReShade post-run: skipped -- DLL not found yet, deferred to standalone menu entry."
            $doReShade = "N"
        }
    }
    # Auto-detect bundled 32-bit DLL; no error if absent.
    if (-not $rsSourceDll32 -or -not (Test-Path -LiteralPath $rsSourceDll32)) {
        if (Test-Path -LiteralPath $bundledDll2_32) { $rsSourceDll32 = $bundledDll2_32 }
    }
    if ($doReShade -eq "Y") {
        Write-Host ""
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        Write-Host " ReShade Visual Enhancements Setup" -ForegroundColor Cyan
        Write-Host "--------------------------------------------" -ForegroundColor Cyan
        $rsSetupDone = $true
        Invoke-ReShadeSetup -UserProfilesDir $userProfilesDir `
                            -SourceDll $rsSourceDll `
                            -SourceDll32 $rsSourceDll32 `
                            -ConfigPath $configPath `
                            -TpRoot $tpRoot `
                            -Mode $mode `
                            -ZipSource $zipSource `
                            -GamesInstallFolder $gamesInstallFolder `
                            -RetroBat $retroBat `
                            -HsDataPath $hsDataPath
    }
}
# =============================================================================
# DGVOODOO2 SETUP  (optional, runs after ReShade setup)
# =============================================================================

Write-Host ""
Write-Host "============================================" -ForegroundColor DarkCyan
Write-Host "   OPTIONAL: dgVoodoo2 Legacy Compatibility" -ForegroundColor DarkCyan
Write-Host "============================================" -ForegroundColor DarkCyan
Write-Host ""
Write-Host "  Some older arcade games use DirectX 8, DirectDraw, or the Glide API"
Write-Host "  from 3dfx. On modern PCs these can cause crashes, black screens, or"
Write-Host "  missing graphics."
Write-Host ""
Write-Host "  dgVoodoo2 is a free compatibility layer that translates those old"
Write-Host "  graphics calls into modern DirectX 11/12. It works by placing small"
Write-Host "  DLL files in the game folder -- your original game files are never changed."
Write-Host ""
Write-Host "  Only run this for games that crash or show black screens on first launch."
Write-Host "  Games that run fine do not need it."
Write-Host ""
Write-Host "  You can turn this on later from the main menu's dgVoodoo2 setup option," -ForegroundColor DarkCyan
Write-Host "  which can also download dgVoodoo2 for you automatically." -ForegroundColor DarkCyan
Write-Host ""
if ($Unattended) {
    $doDgVoodoo = "N"
    Write-Log "Unattended: dgVoodoo2 setup skipped."
} else {
    $doDgVoodoo = (Read-HostSafe "Set up dgVoodoo2 for old DX8/Glide games? (Y/N, default N)" -Default 'N').ToUpper()
}
if ($doDgVoodoo -eq "Y") {
    # No blocking manual-acquisition prompt here (deferred to the
    # standalone "dgVoodoo2 setup" menu entry, which offers a real
    # auto-download option) -- if nothing is available yet, point the user
    # there instead of stopping the onboarding flow.
    $bundledDg2 = Join-Path $PSScriptRoot "dgVoodoo2"
    if (-not $dgSourceDir -or -not (Test-Path -LiteralPath $dgSourceDir)) {
        if (Test-Path -LiteralPath $bundledDg2) {
            $dgSourceDir = $bundledDg2
        } else {
            Write-Host ""
            Write-Host "  dgVoodoo2 DLL folder not found yet." -ForegroundColor Yellow
            Write-Host "  Run 'dgVoodoo2 setup' from the main menu to download it automatically" -ForegroundColor Cyan
            Write-Host "  or point at a folder you already have." -ForegroundColor Cyan
            Write-Log "dgVoodoo2 post-run: skipped -- folder not found yet, deferred to standalone menu entry."
            $doDgVoodoo = "N"
        }
    }
}
$dgSetupDone = $false
if ($doDgVoodoo -eq "Y") {
    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " dgVoodoo2 Legacy Compatibility Setup" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    $dgSetupDone = $true
    Invoke-DgVoodoo2Setup -UserProfilesDir $userProfilesDir `
                          -SourceDir $dgSourceDir `
                          -TpRoot $tpRoot
}
# =============================================================================
# GPU FIX SETUP  (optional, runs after dgVoodoo2 setup)
# =============================================================================

Write-Host ""
Write-Host "============================================" -ForegroundColor DarkCyan
Write-Host "   OPTIONAL: GPU Compatibility Fixes" -ForegroundColor DarkCyan
Write-Host "============================================" -ForegroundColor DarkCyan
Write-Host ""
Write-Host "  Some games include settings that fix graphical issues specific to"
Write-Host "  AMD, NVIDIA, or Intel graphics cards. This step auto-detects your"
Write-Host "  GPU and applies the right fix to every registered game that has one."
Write-Host ""
Write-Host "  Safe to run any time -- re-run if you change or update your GPU."
Write-Host ""
if ($dryRunActive) {
    $doGpuFix = "N"
    Write-Log "PreviewMode: GPU fix setup offer skipped."
} elseif ($Unattended) {
    $doGpuFix = "N"
    Write-Log "Unattended: GPU fix setup skipped."
} else {
    $doGpuFix = (Read-HostSafe "Apply GPU compatibility fixes for your games? (Y/N)").ToUpper()
}
if ($doGpuFix -eq "Y") {
    Write-Host ""
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Write-Host " GPU Compatibility Fix Setup" -ForegroundColor Cyan
    Write-Host "--------------------------------------------" -ForegroundColor Cyan
    Invoke-GpuFixSetup -UserProfilesDir $userProfilesDir `
                       -TpRoot $tpRoot
}

# =============================================================================
# ACTION REQUIRED -- collects everything the user must do manually
# =============================================================================

function New-TpmGameNotesReportText {
    param([object[]]$SetupNotes = @())
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.AppendLine("TeknoParrot Manager - Game Notes")
    [void]$builder.AppendLine("These imported notes are informational; complete required actions in the separate Action Required report.")
    foreach ($sn in @($SetupNotes | Sort-Object Code)) {
        [void]$builder.AppendLine("")
        [void]$builder.AppendLine(("Game: {0} ({1})" -f $sn.Code, $sn.GameName))
        if ($sn.SetupExe) { [void]$builder.AppendLine(("Run: {0}" -f $sn.SetupExe)) }
        [void]$builder.AppendLine("Source notes:")
        foreach ($line in (Format-NoteLines -Text $sn.Notes)) {
            $safeLine = $line -replace '(?i)fuck\w*', '[language removed]' -replace '(?i)\bsucks?\b', '[insult removed]' -replace '(?i)\b(useless users|sensitive snowflake)\b', '[insult removed]'
            [void]$builder.AppendLine($safeLine)
        }
    }
    return $builder.ToString()
}

function Write-TpmGameNotesReport {
    param([object[]]$SetupNotes = @(), [string]$NotesPath, [switch]$Quiet)
    if (@($SetupNotes).Count -eq 0) { return $false }
    try {
        [System.IO.File]::WriteAllText($NotesPath, (New-TpmGameNotesReportText -SetupNotes $SetupNotes), (New-Object System.Text.UTF8Encoding $false))
        if (-not $Quiet) {
            Write-Host ("  Informational game notes saved separately: {0}" -f $NotesPath) -ForegroundColor DarkCyan
            Write-Log "Game notes report written to $NotesPath"
        }
        return $true
    } catch {
        Write-Log "Game notes report could not be written -- $_"
        return $false
    }
}

function New-TpmActionRequiredReportText {
    param(
        [hashtable]$ManualRegData = @{},
        [object[]]$AmbiguousPaths = @(),
        [object[]]$NotFound = @(),
        [object[]]$NoArchetypeItems = @(),
        [object]$Result,
        [object]$CompatibilityWarnings,
        [object[]]$ControlReadinessItems = @(),
        [string]$GameNotesPath = ''
    )
    $unmatched = @()
    if ($Result -and $Result.PSObject.Properties['Unmatched']) { $unmatched = @($Result.Unmatched) }
    $pathTooLong = @()
    $dllMismatch = @()
    $gpuIncompatible = @()
    $biosMissing = @()
    $exeMissing = @()
    if ($CompatibilityWarnings) {
        $pathTooLong = @($CompatibilityWarnings.PathTooLong)
        $dllMismatch = @($CompatibilityWarnings.DllMismatch)
        $gpuIncompatible = @($CompatibilityWarnings.GpuIncompatible)
        $biosMissing = @($CompatibilityWarnings.BiosMissing)
        $exeMissing = @($CompatibilityWarnings.ExeMissing)
    }
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.AppendLine("TeknoParrot Manager - Action Required")
    [void]$builder.AppendLine("Generated: $((Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))")
    [void]$builder.AppendLine("============================================================")
    if ($ManualRegData.Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("REGISTER THESE GAMES IN TEKNOPARROTUI")
        [void]$builder.AppendLine("----------------------------------------------------------")
        [void]$builder.AppendLine("Open TeknoParrotUI -> Add Game -> select the profile -> browse to the executable.")
        foreach ($fn in ($ManualRegData.Keys | Sort-Object)) {
            $ai = $ManualRegData[$fn]
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("  Game     : $fn")
            [void]$builder.AppendLine("  Run      : $($ai.ExeName)")
            if ($ai.Reason -eq "duplicate") {
                $claimedBy = if ($ai.ClaimedBy) { $ai.ClaimedBy } else { "another folder" }
                [void]$builder.AppendLine("  Note     : profile '$($ai.Profiles)' is already used by: $claimedBy")
                [void]$builder.AppendLine("             TeknoParrot can only point one profile at one executable -- this copy")
                [void]$builder.AppendLine("             needs its own profile, or you must choose which copy to use.")
                continue
            }
            if ($ai.BestGuess -and $ai.BestScore -ge 0.40) {
                [void]$builder.AppendLine(("  Best guess: {0}  (similarity {1})" -f $ai.BestGuess, $ai.BestScore))
            }
            if ($ai.ProfileCount -le 15) {
                [void]$builder.AppendLine("  Profiles ($($ai.ProfileCount)): $($ai.Profiles)")
            } else {
                [void]$builder.AppendLine("  Profiles : shared by $($ai.ProfileCount) games -- search by name in TeknoParrotUI")
            }
        }
    }
    if (@($AmbiguousPaths).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("FIX THESE GAME PATHS IN TEKNOPARROTUI")
        [void]$builder.AppendLine("----------------------------------------------------------")
        $byExe = @{}
        foreach ($r in @($AmbiguousPaths)) {
            if (-not $byExe.ContainsKey($r.Exe)) { $byExe[$r.Exe] = [System.Collections.Generic.List[string]]::new() }
            $byExe[$r.Exe].Add($r.Code)
        }
        foreach ($exePath in ($byExe.Keys | Sort-Object)) {
            $codes = ($byExe[$exePath] | Sort-Object) -join " and "
            $exeName = [System.IO.Path]::GetFileName($exePath)
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine(("  {0} needs a corrected game folder." -f $codes))
            [void]$builder.AppendLine(("  TeknoParrot Manager could not find: {0}" -f $exeName))
            [void]$builder.AppendLine(("  Open TeknoParrotUI and point each game to the folder containing {0}." -f $exeName))
        }
    }
    if (@($NotFound).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("EXTRACT THESE GAMES FIRST, THEN RE-RUN REPAIR")
        [void]$builder.AppendLine("----------------------------------------------------------")
        foreach ($item in (@($NotFound) | Sort-Object Code | ForEach-Object { $_.Code })) { [void]$builder.AppendLine("  $item") }
    }
    if (@($NoArchetypeItems).Count -gt 0) {
        $byFamily = @{}
        foreach ($r in @($NoArchetypeItems)) {
            if (-not $byFamily.ContainsKey($r.Family)) { $byFamily[$r.Family] = [System.Collections.Generic.List[string]]::new() }
            $byFamily[$r.Family].Add($r.Code)
        }
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("SET UP CONTROLS FOR THESE GAME TYPES IN TEKNOPARROTUI")
        [void]$builder.AppendLine("----------------------------------------------------------")
        [void]$builder.AppendLine("Bind one game of each type fully, then re-run and choose Register.")
        foreach ($family in ($byFamily.Keys | Sort-Object)) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine(("  {0} GAMES ({1} waiting):" -f $family.ToUpper(), $byFamily[$family].Count))
            [void]$builder.AppendLine("  $( ($byFamily[$family] | Sort-Object) -join ', ' )")
        }
    }
    if (@($unmatched).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("GAME FOLDERS NOT RECOGNISED BY TEKNOPARROT (informational)")
        [void]$builder.AppendLine("----------------------------------------------------------")
        foreach ($folder in ($unmatched | Sort-Object)) { [void]$builder.AppendLine("  $folder") }
    }
    if (@($pathTooLong).Count -gt 0) {
        [void]$builder.AppendLine("These games may fail to launch because their folder paths are too long.")
        [void]$builder.AppendLine("TeknoParrot Manager cannot safely rename folders and update profiles automatically here.")
        [void]$builder.AppendLine("Manual safe repair: back up each UserProfile XML, close TeknoParrotUI,")
        [void]$builder.AppendLine("move/rename the folder near a drive root, update the profile in TeknoParrotUI,")
        [void]$builder.AppendLine("then re-run Repair and test the game.")
        foreach ($w in ($pathTooLong | Sort-Object Code)) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("  Game        : $($w.Code)")
            [void]$builder.AppendLine("  Current path: $($w.Length) characters (limit ~$($w.Limit))")
            [void]$builder.AppendLine("  Rename to   : $($w.Suggested)")
        }
    }
    if (@($dllMismatch).Count -gt 0) {
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("FILE VERSION MISMATCH -- THESE GAMES NEED A SPECIFIC OLDER FILE")
        [void]$builder.AppendLine("----------------------------------------------------------")
        [void]$builder.AppendLine("How to fix: join the TeknoParrot Discord (linked from teknoparrot.com),")
        [void]$builder.AppendLine("ask in #fixes for the file named below matching the required CRC32, and")
        [void]$builder.AppendLine("replace that file in the game's own folder. Do NOT let TeknoParrot")
        [void]$builder.AppendLine("redeploy its current copy here -- that makes it worse, not better.")
        foreach ($w in ($dllMismatch | Sort-Object Code)) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("  Game           : $($w.Code)")
            [void]$builder.AppendLine("  File           : $($w.FileName)")
            [void]$builder.AppendLine("  Current CRC32  : $($w.Found)")
            [void]$builder.AppendLine("  Required CRC32 : $($w.Required)")
        }
    }
    if (@($gpuIncompatible).Count -gt 0) {
        $vendor = $gpuIncompatible[0].Vendor
        [void]$builder.AppendLine(""); [void]$builder.AppendLine("KNOWN $($vendor.ToUpper()) GPU INCOMPATIBILITY -- NO FIX AVAILABLE (informational)")
        [void]$builder.AppendLine("----------------------------------------------------------")
        [void]$builder.AppendLine("These games are confirmed not to work on $vendor GPUs. Known")
        [void]$builder.AppendLine("limitation, not a setup mistake -- there is no fix to apply.")
        foreach ($w in ($gpuIncompatible | Sort-Object Code)) { [void]$builder.AppendLine("  $($w.Code)") }
    }
    if (@($biosMissing).Count -gt 0) {
        foreach ($b in $biosMissing) {
            [void]$builder.AppendLine(""); [void]$builder.AppendLine("$($b.EmulatorType.ToUpper()) FIRMWARE NOT INSTALLED")
            [void]$builder.AppendLine("----------------------------------------------------------")
            [void]$builder.AppendLine("These games are registered but need firmware before they can start.")
            [void]$builder.AppendLine("TeknoParrot Manager cannot provide firmware.")
            [void]$builder.AppendLine("Obtain the firmware from your legitimate source.")
            [void]$builder.AppendLine("  Place in : $($b.ExpectedDir)")
            [void]$builder.AppendLine("  Missing  : $($b.MissingFiles -join ', ')")
            [void]$builder.AppendLine("  Affected : $($b.AffectedGames -join ', ')")
        }
    }
    if (@($exeMissing).Count -gt 0) {
        foreach ($e in $exeMissing) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("$($e.EmulatorType.ToUpper()) EMULATOR COMPONENT NOT FOUND")
            [void]$builder.AppendLine("----------------------------------------------------------")
            [void]$builder.AppendLine("A registered game uses this emulator, but the component declared")
            [void]$builder.AppendLine("by its ECVF contract was not found at the expected path below.")
            [void]$builder.AppendLine("TeknoParrot Manager only checked the contract-declared path; it did not determine why")
            [void]$builder.AppendLine("the file is missing.")
            [void]$builder.AppendLine("  Contract : $($e.ContractId) ($($e.ContractStatus))")
            [void]$builder.AppendLine("  Detector : $($e.DetectorMethod) / $($e.DetectorSource)")
            [void]$builder.AppendLine("  Evidence : contract-backed; confidence $($e.Confidence)")
            [void]$builder.AppendLine("  Expected : $($e.ExpectedPath)")
            [void]$builder.AppendLine("  Affected : $($e.AffectedGames -join ', ')")
            [void]$builder.AppendLine("  Action   : Use TeknoParrotUI's own update/repair screen, then review this")
            [void]$builder.AppendLine("             health check again. TeknoParrot Manager does not replace emulator files.")
        }
    }
    if (@($ControlReadinessItems).Count -gt 0) {
        foreach ($item in @($ControlReadinessItems)) {
            [void]$builder.AppendLine("")
            [void]$builder.AppendLine("CONTROLS NOT READY : $($item.Code)")
            [void]$builder.AppendLine("----------------------------------------------------------")
            [void]$builder.AppendLine("Registration, launch success, and TeknoParrot wizard completion")
            [void]$builder.AppendLine("are reported separately and do not prove that controls work.")
            foreach ($line in $item.SummaryLines) { [void]$builder.AppendLine([string]$line) }
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($GameNotesPath)) {
        [void]$builder.AppendLine("")
        [void]$builder.AppendLine("Additional informational game notes were written separately to:")
        [void]$builder.AppendLine(("  {0}" -f $GameNotesPath))
    }
    return $builder.ToString()
}

function Write-TpmActionRequiredReport {
    param(
        [string]$ActionPath,
        [hashtable]$ManualRegData = @{},
        [object[]]$AmbiguousPaths = @(),
        [object[]]$NotFound = @(),
        [object[]]$NoArchetypeItems = @(),
        [object]$Result,
        [object]$CompatibilityWarnings,
        [object[]]$ControlReadinessItems = @(),
        [string]$GameNotesPath = '',
        [switch]$Quiet
    )
    try {
        $text = New-TpmActionRequiredReportText -ManualRegData $ManualRegData -AmbiguousPaths $AmbiguousPaths -NotFound $NotFound -NoArchetypeItems $NoArchetypeItems -Result $Result -CompatibilityWarnings $CompatibilityWarnings -ControlReadinessItems $ControlReadinessItems -GameNotesPath $GameNotesPath
        [System.IO.File]::WriteAllText($ActionPath, $text, (New-Object System.Text.UTF8Encoding $false))
        if (-not $Quiet) {
            Write-Host ""
            Write-Host "  Action items saved to:" -ForegroundColor Green
            Write-Host "  $ActionPath" -ForegroundColor Cyan
            Write-Host "  Open that file to review everything you need to do manually." -ForegroundColor DarkCyan
            Write-Log "Action items written to $ActionPath"
        }
        return $true
    } catch {
        Write-Log "Action items: could not write file -- $_"
        return $false
    }
}
function Write-TpmActionRequiredReports {
    param(
        [bool]$HasAnyAction,
        [switch]$WriteNotes,
        [string]$ActionPath = '',
        [string]$NotesPath = '',
        [object[]]$SetupNotes = @(),
        [hashtable]$ManualRegData = @{},
        [object[]]$AmbiguousPaths = @(),
        [object[]]$NotFound = @(),
        [object[]]$NoArchetypeItems = @(),
        [object]$Result,
        [object]$CompatibilityWarnings,
        [object[]]$ControlReadinessItems = @(),
        [string]$GameNotesPath = ''
    )
    if ($WriteNotes) {
        $null = Write-TpmGameNotesReport -SetupNotes $SetupNotes -NotesPath $NotesPath -Quiet
    }
    if (-not $HasAnyAction) { return $false }
    return (Write-TpmActionRequiredReport `
        -ActionPath $ActionPath `
        -ManualRegData $ManualRegData `
        -AmbiguousPaths $AmbiguousPaths `
        -NotFound $NotFound `
        -NoArchetypeItems $NoArchetypeItems `
        -Result $Result `
        -CompatibilityWarnings $CompatibilityWarnings `
        -ControlReadinessItems $ControlReadinessItems `
        -GameNotesPath $GameNotesPath)
}

$compatWarnings = Get-CompatibilityWarnings -UserProfilesDir $userProfilesDir -TeknoParrotRoot $tpRoot
$setupNotes     = Get-GameSetupNotes -UserProfilesDir $userProfilesDir

$hasAnyAction = ($manualRegData.Count -gt 0) -or ($amb2.Count -gt 0) -or
                ($nf.Count -gt 0) -or ($noArchetypeItems.Count -gt 0) -or
                ($result.Unmatched.Count -gt 0) -or
                ($controlReadinessItems.Count -gt 0) -or
                ($compatWarnings.PathTooLong.Count -gt 0) -or
                ($compatWarnings.DllMismatch.Count -gt 0) -or
                ($compatWarnings.GpuIncompatible.Count -gt 0) -or
                ($compatWarnings.BiosMissing.Count -gt 0) -or
                ($compatWarnings.ExeMissing.Count -gt 0)

$notesPath = Join-Path $PSScriptRoot "TeknoParrot-Manager-game-notes.txt"
$null = Write-TpmActionRequiredReports -HasAnyAction:$false -WriteNotes -NotesPath $notesPath -SetupNotes $setupNotes
if ($hasAnyAction) {
    Write-Host ""
    Write-Host "============================================" -ForegroundColor Yellow
    Write-Host "   ACTION REQUIRED" -ForegroundColor Yellow
    Write-Host "============================================" -ForegroundColor Yellow

    # -- 1. Games needing manual registration ---------------------------------
    if ($manualRegData.Count -gt 0) {
        Write-Host ""
        Write-Host "  REGISTER THESE GAMES IN TEKNOPARROTUI" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  The script found these games on disk but cannot register them" -ForegroundColor DarkCyan
        Write-Host "  automatically. Either the name of the executable file is shared" -ForegroundColor DarkCyan
        Write-Host "  by multiple TeknoParrot profiles, or the one profile it matches" -ForegroundColor DarkCyan
        Write-Host "  is already pointed at a different copy of this game." -ForegroundColor DarkCyan
        Write-Host "  Open TeknoParrotUI -> Add Game -> select the profile -> browse" -ForegroundColor DarkCyan
        Write-Host "  to the executable shown below." -ForegroundColor DarkCyan
        Write-Host ""
        foreach ($folderName in ($manualRegData.Keys | Sort-Object)) {
            $info    = $manualRegData[$folderName]
            $count   = $info.ProfileCount
            $exeName = $info.ExeName
            Write-Host "  Game   : $folderName" -ForegroundColor Yellow
            Write-Host "  Run    : $exeName" -ForegroundColor DarkGray
            if ($info.Reason -eq "duplicate") {
                $claimedBy = if ($info.ClaimedBy) { $info.ClaimedBy } else { "another folder" }
                Write-Host ("  Note   : profile '{0}' is already used by: {1}" -f $info.Profiles, $claimedBy) -ForegroundColor Cyan
                Write-Host "           TeknoParrot can only point one profile at one executable -- this" -ForegroundColor DarkCyan
                Write-Host "           copy needs its own profile, or you must choose which copy to use." -ForegroundColor DarkCyan
                Write-Host ""
                continue
            }
            if ($info.BestGuess -and $info.BestScore -ge 0.40) {
                Write-Host ("  Best guess : {0}  (similarity {1} -- below auto-register threshold {2})" -f `
                    $info.BestGuess, $info.BestScore, $FuzzyAutoThreshold) -ForegroundColor Cyan
            }
            if ($count -le 15) {
                Write-Host "  Profiles ($count) : $($info.Profiles)" -ForegroundColor DarkCyan
            } else {
                Write-Host "  Profiles : shared by $count games -- search by game name in TeknoParrotUI" -ForegroundColor DarkCyan
            }
            Write-Host ""
        }
    }

    # -- 2. Repair: broken paths that could not be auto-fixed -----------------
    if ($amb2.Count -gt 0) {
        $byExe = @{}
        foreach ($r in $amb2) {
            $k = $r.Exe
            if (-not $byExe.ContainsKey($k)) { $byExe[$k] = [System.Collections.Generic.List[string]]::new() }
            $byExe[$k].Add($r.Code)
        }
        Write-Host "  FIX THESE GAME PATHS IN TEKNOPARROTUI" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        foreach ($exePath in ($byExe.Keys | Sort-Object)) {
            $codes = ($byExe[$exePath] | Sort-Object) -join " and "
            $exeName = [System.IO.Path]::GetFileName($exePath)
            Write-Host ("  {0} needs a corrected game folder." -f $codes) -ForegroundColor Yellow
            Write-Host ("  TeknoParrot Manager could not find: {0}" -f $exeName) -ForegroundColor DarkGray
            Write-Host ("  Open TeknoParrotUI and point each game to the folder containing {0}." -f $exeName) -ForegroundColor DarkCyan
            Write-Host ""
        }
    }

    # -- 3. Games not yet extracted (informational) ---------------------------
    if ($nf.Count -gt 0) {
        Write-Host "  EXTRACT THESE GAMES FIRST, THEN RE-RUN REPAIR" -ForegroundColor DarkCyan
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  These profiles exist but their game has not been extracted to" -ForegroundColor DarkCyan
        Write-Host "  your staging folder yet. No action needed now -- use AutoSync" -ForegroundColor DarkCyan
        Write-Host "  to extract the game, then re-run the script and choose Repair." -ForegroundColor DarkCyan
        Write-Host ""
        $lineLen = 70; $line = "  "; $first = $true
        foreach ($item in ($nf | Sort-Object Code | ForEach-Object { $_.Code })) {
            $add = if ($first) { $item } else { ", $item" }
            if (($line + $add).Length -gt $lineLen) {
                Write-Host $line -ForegroundColor DarkGray
                $line = "  $item"; $first = $false
            } else { $line += $add; $first = $false }
        }
        if ($line.Trim()) { Write-Host $line -ForegroundColor DarkGray }
        Write-Host ""
    }

    # -- 4. Control types with no reference game bound yet --------------------
    if ($noArchetypeItems.Count -gt 0) {
        $byFamily = @{}
        foreach ($r in $noArchetypeItems) {
            if (-not $byFamily.ContainsKey($r.Family)) { $byFamily[$r.Family] = [System.Collections.Generic.List[string]]::new() }
            $byFamily[$r.Family].Add($r.Code)
        }
        $familyExamples = @{
            'button'    = 'Street Fighter III, BlazBlue, Tekken 7, Dead or Alive 5'
            'driving'   = 'Daytona Championship USA, Initial D, OutRun 2 SP, F-Zero AX'
            'lightgun'  = 'House of the Dead 4, Aliens Extermination, Point Blank, Rambo'
            'trackball' = 'Golden Tee Live, Silver Strike Bowling, Target Toss Pro'
            'spinner'   = 'any spinner-based game in TeknoParrot'
            'analog'    = 'any analog-stick game in TeknoParrot'
        }
        Write-Host ""
        Write-Host "  SET UP CONTROLS FOR THESE GAME TYPES IN TEKNOPARROTUI" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  These games could not receive controls automatically because" -ForegroundColor DarkCyan
        Write-Host "  you have not yet set up controls for that type of game." -ForegroundColor DarkCyan
        Write-Host "  Pick ONE game of each type, bind it fully in TeknoParrotUI" -ForegroundColor DarkCyan
        Write-Host "  (every button, axis, Test, Service, Coin, Start), then" -ForegroundColor DarkCyan
        Write-Host "  re-run this script and choose Propagate." -ForegroundColor DarkCyan
        Write-Host ""
        foreach ($family in ($byFamily.Keys | Sort-Object)) {
            $codes      = ($byFamily[$family] | Sort-Object) -join ", "
            $suggestion = if ($familyExamples.ContainsKey($family)) { $familyExamples[$family] } else { "any $family game in TeknoParrot" }
            Write-Host ("  {0} GAMES  ({1} game(s) waiting for controls):" -f $family.ToUpper(), $byFamily[$family].Count) -ForegroundColor Yellow
            Write-Host "  Waiting : $codes" -ForegroundColor DarkGray
            Write-Host "  Pick one to bind first: $suggestion" -ForegroundColor DarkCyan
            Write-Host ""
        }
    }

    # -- 5. Game folders not recognised by TeknoParrot ------------------------
    if ($result.Unmatched.Count -gt 0) {
        Write-Host ""
        Write-Host "  GAME FOLDERS NOT RECOGNISED BY TEKNOPARROT" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  These folders contained game files but none of their" -ForegroundColor DarkCyan
        Write-Host "  executables matched any profile in TeknoParrot's library." -ForegroundColor DarkCyan
        Write-Host "  They are likely games TeknoParrot does not yet support, or" -ForegroundColor DarkCyan
        Write-Host "  utilities / launchers that live alongside your games." -ForegroundColor DarkCyan
        Write-Host "  No action is required -- this is informational only." -ForegroundColor DarkCyan
        Write-Host ""
        $lineLen = 70; $line = "  "; $firstU = $true
        foreach ($folder in $result.Unmatched) {
            $add = if ($firstU) { $folder } else { ", $folder" }
            if (($line + $add).Length -gt $lineLen) {
                Write-Host $line -ForegroundColor DarkGray
                $line = "  $folder"; $firstU = $false
            } else { $line += $add; $firstU = $false }
        }
        if ($line.Trim()) { Write-Host $line -ForegroundColor DarkGray }
        Write-Host ""
    }

    # -- 6. Raw Thrills games whose install path is too long ------------------
    if ($compatWarnings.PathTooLong.Count -gt 0) {
        Write-Host ""
        Write-Host "  PATH TOO LONG -- THESE GAMES MAY FAIL TO LAUNCH" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  This game may fail to launch because its folder path is too long." -ForegroundColor DarkCyan
        Write-Host "  TeknoParrot Manager cannot safely rename folders and update profiles automatically" -ForegroundColor DarkCyan
        Write-Host "  in this report, so use the manual steps below." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  MANUAL SAFE REPAIR:" -ForegroundColor DarkCyan
        Write-Host "    1. Back up the affected UserProfile XML before changing anything." -ForegroundColor DarkCyan
        Write-Host "    2. Close TeknoParrotUI, then rename/move the folder to the recommended name." -ForegroundColor DarkCyan
        Write-Host "    3. Use a location near a drive root, such as D:\TPGames\<name>." -ForegroundColor DarkCyan
        Write-Host "    4. Point the profile to the renamed folder in TeknoParrotUI." -ForegroundColor DarkCyan
        Write-Host "    5. Re-run Repair and test the game." -ForegroundColor DarkCyan
        Write-Host ""
        foreach ($w in ($compatWarnings.PathTooLong | Sort-Object Code)) {
            Write-Host ("  Game        : {0}" -f $w.Code) -ForegroundColor Yellow
            Write-Host ("  Current path: {0} characters (limit ~{1})" -f $w.Length, $w.Limit) -ForegroundColor DarkGray
            Write-Host ("  Rename to   : {0}" -f $w.Suggested) -ForegroundColor Cyan
            Write-Host ""
        }
    }

    # -- 7. iDmacDrv32.dll version pins (BlazBlue-series) ----------------------
    if ($compatWarnings.DllMismatch.Count -gt 0) {
        Write-Host ""
        Write-Host "  FILE VERSION MISMATCH -- THESE GAMES NEED A SPECIFIC OLDER FILE" -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  These games require a SPECIFIC OLDER version of a particular file." -ForegroundColor DarkCyan
        Write-Host "  A newer version causes errors (e.g. a coin error) and the game will" -ForegroundColor DarkCyan
        Write-Host "  not start correctly. This is the opposite of the usual fix -- do NOT" -ForegroundColor DarkCyan
        Write-Host "  let TeknoParrot redeploy its current copy here, that makes it worse." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  HOW TO FIX:" -ForegroundColor DarkCyan
        Write-Host "    1. Join the TeknoParrot Discord (linked from teknoparrot.com)." -ForegroundColor DarkCyan
        Write-Host "    2. In the #fixes channel, ask for or search for the file named" -ForegroundColor DarkCyan
        Write-Host "       below, matching the required CRC32 shown for your game." -ForegroundColor DarkCyan
        Write-Host "    3. Replace that file in the game's own folder with the one you got." -ForegroundColor DarkCyan
        Write-Host ""
        foreach ($w in ($compatWarnings.DllMismatch | Sort-Object Code)) {
            Write-Host ("  Game           : {0}" -f $w.Code) -ForegroundColor Yellow
            Write-Host ("  File           : {0}" -f $w.FileName) -ForegroundColor DarkGray
            Write-Host ("  Current CRC32  : {0}" -f $w.Found) -ForegroundColor DarkGray
            Write-Host ("  Required CRC32 : {0}" -f $w.Required) -ForegroundColor Cyan
            Write-Host ""
        }
    }

    # -- 8. Games known not to work on the detected GPU vendor (informational) -
    if ($compatWarnings.GpuIncompatible.Count -gt 0) {
        $gpuVendorSeen = $compatWarnings.GpuIncompatible[0].Vendor
        Write-Host ""
        Write-Host ("  KNOWN {0} GPU INCOMPATIBILITY -- NO FIX AVAILABLE" -f $gpuVendorSeen.ToUpper()) -ForegroundColor Yellow
        Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host ("  These registered games are confirmed NOT to work on {0} GPUs." -f $gpuVendorSeen) -ForegroundColor DarkCyan
        Write-Host "  This is a known limitation of the game/emulation layer, not a setup" -ForegroundColor DarkCyan
        Write-Host "  mistake on your end -- there is no fix to apply. Informational only." -ForegroundColor DarkCyan
        Write-Host ""
        $lineLen = 70; $line = "  "; $firstG = $true
        foreach ($w in ($compatWarnings.GpuIncompatible | Sort-Object Code | ForEach-Object { $_.Code })) {
            $add = if ($firstG) { $w } else { ", $w" }
            if (($line + $add).Length -gt $lineLen) {
                Write-Host $line -ForegroundColor DarkGray
                $line = "  $w"; $firstG = $false
            } else { $line += $add; $firstG = $false }
        }
        if ($line.Trim()) { Write-Host $line -ForegroundColor DarkGray }
        Write-Host ""
    }

    # -- 8b. Missing emulator firmware/BIOS prerequisites (issue #85) ---------
    if ($compatWarnings.BiosMissing.Count -gt 0) {
        foreach ($b in $compatWarnings.BiosMissing) {
            Write-Host ""
            Write-Host ("  {0} FIRMWARE NOT INSTALLED" -f $b.EmulatorType.ToUpper()) -ForegroundColor Yellow
            Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
            Write-Host "  These games are registered and will show as launchable, but will" -ForegroundColor DarkCyan
            Write-Host "  fail at launch until the required firmware files are in place." -ForegroundColor DarkCyan
            Write-Host "  TeknoParrot Manager cannot provide firmware. Obtain the firmware from your legitimate source." -ForegroundColor DarkCyan
            Write-Host "  Use TeknoParrotUI's own setup/update screen if it offers one; TeknoParrot Manager will not copy it." -ForegroundColor DarkCyan
            Write-Host ""
            Write-Host ("  Place in : {0}" -f $b.ExpectedDir) -ForegroundColor Cyan
            Write-Host ("  Missing  : {0}" -f ($b.MissingFiles -join ', ')) -ForegroundColor Yellow
            Write-Host ("  Affected : {0}" -f ($b.AffectedGames -join ', ')) -ForegroundColor DarkGray
            Write-Host ""
        }
    }

    # -- 8a. Missing emulator component (issue #254) --------------------------
    if ($compatWarnings.ExeMissing.Count -gt 0) {
        foreach ($e in $compatWarnings.ExeMissing) {
            Write-Host ""
            Write-Host ("  {0} EMULATOR COMPONENT NOT FOUND" -f $e.EmulatorType.ToUpper()) -ForegroundColor Yellow
            Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
            Write-Host "  A registered game uses this emulator, but the component declared" -ForegroundColor DarkCyan
            Write-Host "  by its ECVF contract was not found at the expected path below." -ForegroundColor DarkCyan
            Write-Host "  TeknoParrot Manager only checked the contract-declared path; it did not determine why" -ForegroundColor DarkCyan
            Write-Host "  the file is missing." -ForegroundColor DarkCyan
            Write-Host ""
            Write-Host ("  Contract : {0} ({1})" -f $e.ContractId, $e.ContractStatus) -ForegroundColor DarkGray
            Write-Host ("  Detector : {0} / {1}" -f $e.DetectorMethod, $e.DetectorSource) -ForegroundColor DarkGray
            Write-Host ("  Evidence : contract-backed; confidence {0}" -f $e.Confidence) -ForegroundColor DarkGray
            Write-Host ("  Expected : {0}" -f $e.ExpectedPath) -ForegroundColor Cyan
            Write-Host ("  Affected : {0}" -f ($e.AffectedGames -join ', ')) -ForegroundColor DarkGray
            Write-Host "  TeknoParrot is missing a component. Use TeknoParrotUI's own update/repair screen." -ForegroundColor DarkCyan
            Write-Host "  Verify or restore this component through your normal TeknoParrot installation/update process using TeknoParrotUI." -ForegroundColor DarkGray
            Write-Host "  TeknoParrot Manager will not invent or replace emulator files; this health result remains visible for review." -ForegroundColor DarkCyan
            Write-Host ""
        }
    }

    # -- 8b. Controls readiness (issues #255/#253) ----------------------------
    if ($controlReadinessItems.Count -gt 0) {
        foreach ($item in $controlReadinessItems) {
            Write-Host ""
            Write-Host ("  CONTROLS NOT READY : {0}" -f $item.Code) -ForegroundColor Yellow
            Write-Host "  ----------------------------------------------------------" -ForegroundColor DarkGray
            Write-Host "  Registration, launch success, and TeknoParrot wizard completion" -ForegroundColor DarkCyan
            Write-Host "  are reported separately and do not prove that controls work." -ForegroundColor DarkCyan
            foreach ($line in $item.SummaryLines) {
                if ([string]::IsNullOrEmpty([string]$line)) {
                    Write-Host ""
                } else {
                    Write-Host ("  {0}" -f $line) -ForegroundColor DarkCyan
                }
            }
        }
    }



    Write-Host "============================================" -ForegroundColor Yellow

    $defaultActionPath = Join-Path $PSScriptRoot "TeknoParrot-Manager-ActionItems.txt"
    $actionPath = $defaultActionPath
    if (-not $Unattended -and -not $dryRunActive) {
        try {
            Add-Type -AssemblyName System.Windows.Forms
            $saveDialog = New-Object System.Windows.Forms.SaveFileDialog
            $saveDialog.Title            = "Save Action Required summary"
            $saveDialog.InitialDirectory = $PSScriptRoot
            $saveDialog.FileName         = "TeknoParrot-Manager-ActionItems.txt"
            $saveDialog.Filter           = "Text files (*.txt)|*.txt|All files (*.*)|*.*"
            $saveDialog.OverwritePrompt  = $true
            if ($saveDialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
                $actionPath = $saveDialog.FileName
            } else {
                Write-Log "Action items: save dialog cancelled, using default path."
            }
        } catch {
            Write-Log "Action items: save dialog failed, using default path -- $_"
        }
    }
    $gameNotesPathForReport = if ($setupNotes.Count -gt 0) { $notesPath } else { '' }
    $null = Write-TpmActionRequiredReports `
        -HasAnyAction:$true `
        -ActionPath $actionPath `
        -ManualRegData $manualRegData `
        -AmbiguousPaths $amb2 `
        -NotFound $nf `
        -NoArchetypeItems $noArchetypeItems `
        -Result $result `
        -CompatibilityWarnings $compatWarnings `
        -ControlReadinessItems $controlReadinessItems `
        -GameNotesPath $gameNotesPathForReport
}

Write-Host ""
Write-Host "  Next steps:" -ForegroundColor Cyan
Write-Host "   1. Launch TeknoParrotUi.exe -- registered games now appear; review ACTION REQUIRED controls status before treating them as ready."
Write-Host "   2. Work through the ACTION REQUIRED items above."
Write-Host "   3. Bind one game of each control type, then re-run and propagate."
Write-Host "   4. Test one propagated game before trusting the rest."
if ($rsSetupDone) {
    Write-Host ""
    Write-Host "  ReShade:" -ForegroundColor Cyan
    Write-Host "   - Launch any game that had ReShade installed."
    Write-Host "   - Press the  Home  key to open the effects overlay."
    Write-Host "   - Tick the effects you want and adjust with the sliders."
    Write-Host "   - Settings save automatically -- you only need to do this once per game."
    Write-Host "   - TPM does not remove unowned ReShade hooks automatically; review any"
    Write-Host "     removal in the advanced troubleshooting path."
}
if ($dgSetupDone) {
    Write-Host ""
    Write-Host "  dgVoodoo2:" -ForegroundColor Cyan
    Write-Host "   - Launch each game that had dgVoodoo2 installed and test it."
    Write-Host "   - If a game now crashes that worked before, the DLL may conflict --"
    Write-Host "     delete D3D8.dll / DDraw.dll / Glide2x.dll / Glide3x.dll from that"
    Write-Host "     game's folder to revert. Your game files are not affected."
}
Write-Host ""
Write-Host "  Crosshairs:" -ForegroundColor Cyan
Write-Host ("   - Custom crosshair images are in:  {0}" -f (Join-Path $PSScriptRoot "Crosshairs\"))
Write-Host "   - You can add your own PNG images to that folder at any time."
Write-Host "   - Run mode 4 (Crosshair setup) to preview and deploy them to lightgun games."
Write-Host ""

    if ($dryRunActive -and -not $Unattended) {
        Write-Host "  Preview completed successfully." -ForegroundColor DarkCyan
        Write-Host "  No changes have been made." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  Would you like to perform the operation for real?" -ForegroundColor Cyan
        Write-Host "  TPM will perform a fresh scan before making any changes, to ensure" -ForegroundColor DarkCyan
        Write-Host "  nothing has changed since the preview." -ForegroundColor DarkCyan
        Write-Host ""
        Write-Host "  [Y] Apply changes" -ForegroundColor Cyan
        Write-Host "  [N] Return to the main menu" -ForegroundColor Cyan
        $applyNow = (Read-HostSafe "  Your choice").ToUpper()
        if ($applyNow -eq "Y") {
            $pendingApplyMode = $mode
            Write-Log "PreviewMode: user chose to apply for real -- re-entering $mode."
            continue
        }
    }

    [void](Read-Host "  Press Enter to return to menu")
} # end while ($true)
} catch {
    $errMsg  = $_.Exception.Message
    $errFull = "FATAL ERROR (unhandled): $($_.Exception)`nStack: $($_.ScriptStackTrace)"
    Write-Host ""
    Write-Host "============================================" -ForegroundColor Red
    Write-Host "  FATAL ERROR -- script aborted" -ForegroundColor Red
    Write-Host "============================================" -ForegroundColor Red
    Write-Host ("  {0}" -f $errMsg) -ForegroundColor Red
    Write-Host "  Full details have been written to:" -ForegroundColor Yellow
    Write-Host ("  {0}" -f (Join-Path $PSScriptRoot "TeknoParrot-Manager.log")) -ForegroundColor Yellow
    try { Write-Log $errFull } catch {}
    [void](Read-Host "  Press Enter to exit")
    exit 1
}
